respect to $(M_n)$;
\item[(ii)] $\mathbb{E}[N_{k_n}(\mathcal T^n)]\sim n\pi_{k_n}$.
\end{enumerate}

[Theorem 6 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb_{\leq n}$, $f:\cube^n\to [-1,1]$, and $p\in [1,2)$,
\begin{equation}
    \left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p} \geq C^{\text{\rm\ref{thm:high-order-Tal-isoper-Boolean}}}(p)^k\Wop^{\geq k}(f) \left[1+ \frac{1}{2k}\ln\left(\frac{1}{\Wop^{\geq k}(f)}\right)\right]^\frac{kp}{2},
\end{equation}
with $C^{\text{\rm\ref{thm:high-order-Tal-isoper-Boolean}}}(p) = \left(M(p)^{-\frac{2}{p}}+\frac{p}{2\upe(2-p)}\right)^{-\frac{p}{2}}  \gtrsim 2-p$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Lemma-Stability wp-n of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $\theta\ge0$ and $C_{2,1}>0$ be given in (equation Qn cancel-1 of the paper). The Marcus flow 
		$\wp_n$ given by (equation regular Marcus flow Q2 of the paper) satisfies the following stabilities estimates:
		\begin{itemize}[leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item $($Stability with respect to initial data$)$  For all $f,g\in H_d^{\theta}$,  we have
			\begin{align}
				\sup_{n\ge1}\|\wp_n\big(r,l,f\big)-\wp_n\big(r,l,g\big)\|^2_{H^{\theta}}\leq \left\lVertf-g\right\rVert_{H^{\theta}}^2\cdot \mathrm{e}^{2C_{2,1}|l|r},
				\quad r\in[0,1].
			\end{align} 
			\item $($Stability respect to different mollifier-layers$)$ 
			Let $s>\theta+\delta_2$ with $\delta_2=\delta_{\mathcal Q_2}$ given in (equation delta-Qi of the paper).
			For all $f\in H_d^s$, we have
			\begin{align}
				\|\wp_n\big(r,l,f\big)-\wp_m\big(r,l,f\big)\|^2_{H^{\theta}}\lesssim (n \land m)^{-2(s-\theta-\delta_2)}\|f\|^2_{H^s} \left({\rm e}^{5C_{2,1}|l|r}-{\rm e}^{3C_{2,1}|l|r}\right),
				\quad n,m\ge1,\quad   r\in[0,1].
			\end{align}
		\end{itemize}

