& \quad + \left[\mathbb{E} \left[\left| \int_s^t \left( \sigma(X_{s,\max\{s,\delta(r)\}}^{\delta,x}) -\sigma(X_{s,\max\{s,\delta(r)\}}^{\delta,\widetilde{x}})\right) dW_r \right|^p ...","release_manifest_digest":"sha256:4efa3fca1e09b8526928a12dc0d8ad9be812fb5e01526dcfcfb85e6f2af41f41","revision_digest":"sha256:02a3e66a52e72b7c4bbd30e745952f89685c8107b723691e855e48685f535ec0","source_id":"arxiv:2604.25964","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

