[Corollary 8 of arXiv:2608.27156, 'Traveling Waves in Equity Markets with\\Rank-Based Entry and Exit'] Under the hypotheses of Theorem~\ref{thm:wave}, the profile satisfies $1 - V(y) = e^{-\alpha y (1 + o(1))}$ as $y \to \infty$, where
\begin{equation}
    \alpha \;=\; \frac{a + \sqrt{a^{2} - 2\,\sigma^{2}(1)\,\tilde f'(1)}}{\sigma^{2}(1)},
    \qquad a \;=\; c - \tilde b(1):
\end{equation}
the capitalization distribution of the wave has a Pareto tail with exponent $\alpha$ at the top of the market. Symmetrically, $V(y) = e^{\beta y (1 + o(1))}$ as $y \to -\infty$, where $\beta$ is the positive root of \eqref{eq:char-poly} at $e = 0$.

[Definition of arXiv:2608.30848, '\huge \bf Limit Laws of the Iterated Logarithm Under Sub-linear Expectations'] A sub-linear expectation $\widehat{\mathbb E} :\mathscr{H}\rightarrow\bar{\mathbb{R}}$ on the space $\mathscr{H}$ is a function satisfying the following properties: for all $X,Y\in\mathscr{H}$,
\begin{itemize}
\item[(a)] If $X \geq Y$, then $\widehat{\mathbb E} [X] \geq \widehat{\mathbb E} [Y]$;
\item[(b)] $\widehat{\mathbb E} [c]=c$;
\item[(c)] When $\widehat{\mathbb E} [X]+\widehat{\mathbb E} [Y]$ is not of the form $+\infty-\infty$ or $-\infty+\infty$, we have $\widehat{\mathbb E} [X+Y] \leq \widehat{\mathbb E} [X]+\widehat{\mathbb E} [Y]$;
\item[(d)] For $\lambda>0$, we have $\widehat{\mathbb E} [\lambda X]=\lambda\widehat{\mathbb E} [X]$. \end{itemize}
Here, $\bar{\mathbb{R}}=[-\infty,\infty]$, and $0\cdot\infty$ is defined as $0$. The triple $(\Omega,\mathscr{H},\widehat{\mathbb E})$ is called a sub-linear expectation space. Given a sub-linear expectation $\widehat{\mathbb E}$, $\widehat{\mathcal E}$ denotes its conjugate expectation, i.e., $$ \widehat{\mathcal E} [X]:=-\widehat{\mathbb E} [-X],\quad\forall X\in\mathscr{H}. $$

[Proposition 12 of arXiv:2512.05340, 'The rate of convergence of the critical mean-field $O(N)$ magnetization via multivariate n'] If $V$ satisfies Assumption~\ref{assumption: assumptions on V}, then for $x, u, v, w\in \RR^{d}$ and $t>0$,
\begin{equation}
     |\,\sU_{u}^x(t)| \leq |u|,
 \end{equation}
\begin{equation}
     \EE|\,\sU_{u}^x(t)|^{2} \leq C_{1}^{2}e^{-2\theta t}|u|^{2},
 \end{equation}
\begin{equation}
     \EE|\,\sU_{u,v}^x(t)|^{2} \leq C_{2}^{2}|u|^{2}|v|^{2},
 \end{equation}
 \begin{equation}
     |\,\sU_{u,v,w}^x(t)| \leq |u||v||w|P(t),
 \end{equation}
 where, 
 \begin{align*}
     C_{1} &:= \frac{1}{\sqrt{J(2t_{0})}},                               &\theta :=& \frac{\log(1/J(2t_{0}))}{2t_{1}},\\ 
     C_{2} &:= \sqrt{2}M_1\left(1+\frac{C_1^2}{\theta^2}\right)^{1/2},   &P(t)   :=& (3M_1^2(t+1)/2+M_2)(t+1).
 \end{align*}
with $J:[1,\infty)\to\RR$ defined via
   \begin{equation*}
     J(t):= 1-\frac{1-e^{-\chi}}{2t}, \qquad  \chi:=c_1B^k,
   \end{equation*}
   and 
   \begin{equation*}
     \begin{split}
        t_{0}&:= \frac{\eta + 2B + 2m_{1}(\mu)}{\eta\mu(\{x\in\RR^{d}: |x| > B+ 1\})},\\
        t_{1}&:= \max\left\{2t_{0}, \frac{1}{\chi}\log\left(\frac{4t_{0}}{1-e^{-\chi}}\right)\right\}.
        \end{split}
    \end{equation*}
   The constants $k,B,c_1,M_1,M_2$ are as defined in Assumption~\ref{assumption: assumptions on V}, while $\mu$ and $\eta$ are as defined in
   Lemma~\ref{lemma: geom erg}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Coro advanced geographic ineq decoupling map of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] Let $n\in \mathbb N$ be such that $n\varepsilon\geqslant 1+r\tau_K$ and let 
	\begin{equation*}
		T_\gamma=T_\gamma(n)=\big\lceil n(\lambda_\gamma+\varepsilon)\big\rceil+r_\gamma\tau_K,\qquad \gamma\in \{1,2\}.
	\end{equation*}
	Let $u\in \widetilde{\mathcal{W}}_n$ be such that $d_{\mathrm{LP}}(L[u],\mu)< \delta$. Then, $\Phi_{n,T_1,T_2}(u)$ exists and for each $\gamma\in \{1,2\}$ and all $w^\gamma\in \Phi^{(\gamma)}_{n,T_\gamma}(u)$,
	\begin{equation*}
		d_{\mathrm{LP}}(L[w^\gamma],\mu_\gamma)\leqslant f_\gamma(\varepsilon,\delta),
	\end{equation*}
	where $f_\gamma$ is a function that satisfies
	\begin{equation}
		\lim_{\varepsilon\to 0}\lim_{\delta \to 0}f_\gamma(\varepsilon,\delta)=0.
	\end{equation}

