[Corollary 6 of arXiv:2608.27307, '2608.27307'] Under the assumptions of Theorem~\ref{thm:opt_ll}, let $E_*$ be a regular right edge in the sense of Definition~\ref{def:reg_r_edge}, the following statements hold.
        \begin{enumerate}[label=(\roman*)]
                \item For every $\eps>0$ and $D>0$,
                      \begin{align}
                              \bb P\left(\spec W\cap[E_*+N^{-2/3+\eps},E_*+\eps_*]\neq\varnothing\right)\leq N^{-D}. 
                      \end{align}
                      If $E_*=E_+$, then
                      \begin{align}
                              \bb P(\la_1>E_++N^{-2/3+\eps})\leq N^{-D}. 
                      \end{align}
                \item For any $j$ satisfying $E_+-\eps_*/2\leq \gamma_j\leq E_+ $,
                      \begin{align}
                              \abs{\la_j-\gamma_j}\prec N^{-2/3}j^{-1/3}. 
                      \end{align}
                      In particular, for every fixed $K\in\N$,
                      \begin{align}
                              \max_{1\leq j\leq K}\abs{\la_j-E_+}\prec N^{-2/3}. 
                      \end{align}
                \item For each nonzero eigenvalue $\la_j$, let $\bfru_j\in\R^M$ and $\bfrv_j\in\R^N$ be normalized left and right singular vectors of $Y$, respectively. Then, for every fixed $K\in\N$, uniformly for $1\leq j\leq K$ and deterministic vectors $\bhv\in\C^M$, $\btw\in\C^N$,
                      \begin{align}
                              \abs{\scalar{\bhv}{\bfru_j}}^2\prec N^{-1}\|\bhv\|^2,\qquad \abs{\scalar{\btw}{\bfrv_j}}^2\prec N^{-1}\|\btw\|^2. 
                      \end{align}
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm main of arXiv:2411.13926, 'Random walks on random walks:\\ non-perturbative results in high dimensions'] Consider the RWRW model  on $\mathbb{Z}^d$ with $\lambda \in [0,\infty)$ and  $d\geq 5$. 

\begin{itemize}
\item[a)] The Strong law of large numbers (SLLN):

There exists a  $v \in \ensuremath{\mathbb{R}}^d$ such that
\begin{equation} \lim_{t \rightarrow \infty} \frac{X_t}{t} = v \quad P_{\ensuremath{\mathbb{P}}}\text{-almost surely and in }L_1
\end{equation}

\item[b)]  Large deviation bounds (LDBs):

For every $\epsilon >0$ there exists constants $C,c>0$ such that 
\begin{equation}
P_{\ensuremath{\mathbb{P}}} \left( \left| \frac{X_t}{t} - v \right| > \epsilon \right) \leq Ce^{-ct}, \quad \text{ for all } t \in \ensuremath{\mathbb{N}},
\end{equation}
with $v\in \ensuremath{\mathbb{R}}^d$ as in (equation eq:SLLN of the paper).
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:resultknownmask of arXiv:2602.11129, 'Information-Theoretic Thresholds for Bipartite Latent-Space Graphs Under Noisy Observation'] Consider any fixed $p \in (0,1)$. 
    Then, the following holds with probability $1 - o(n)$ over $\ \mathbf{M} \sim \mathbb{M}(n, m, q)$ whenever $d \gg \log(n)^3$.

    \vspace{0.5em}
    If $p \neq \frac{1}{2}$ then:\hspace{1em} $\begin{aligned}[t]
            \hspace{0.8cm}\dtv{\mathbb{W}_{\mathbf{M}}(n, m, p, d)}{ \mathbb{M}(n, m, p)} &= \begin{cases} 1 - o(1) & \text{if } d \ll nmq^2  \hspace{1.3cm} \text{ or } \hspace{.1cm} d \ll m\sqrt{n}q  \\
            o(1) & \text{if } d \gg nmq^2\log(n) \hspace{.1cm} \text{ and } \hspace{.1cm} d \gg m\sqrt{n}q \log(n)
            \end{cases}
        \end{aligned}$

    \vspace{0.5em}
    If $p = \frac{1}{2}$ then:\hspace{1em} $\begin{aligned}[t]
        \hspace{0.8cm}\dtv{\mathbb{W}_{\mathbf{M}}(n, m, p, d)}{ \mathbb{M}(n, m, p)} &= \begin{cases} 1 - o(1) & \text{if } d \ll nmq^2 \\
            o(1) & \text{if } d \gg nmq^2\log(n)
            \end{cases}
        \end{aligned}$

    \vspace{0.5em}
    \noindent Here, $o(1)$ denotes a function that tends to zero as $n \rightarrow \infty$. Recall further that $m \ge n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 21 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] We define the linear map $\tilde\Delta^\partial : \scal{\tcT} \to \scal{\tcT} \otimes \scal{\tcT_1}$ recursively via
	\begin{align*}
		&\tilde \Delta^\partial \<bs(2)0> = \<s(1)0> \otimes \partial \, \<b1> + \<b1> \otimes \partial \, \<s(1)0>, \qquad && \tilde \Delta^\partial \<ps(2)0> = \<s(1)0> \otimes \partial \, \<p1> + \<p1> \otimes \partial \, \<s(1)0>,
		\\
		&\tilde \Delta^\partial \<b0> = 0, \qquad &&\tilde \Delta^\partial \<p0> = 0,
		\\
		& \tilde \Delta^\partial \<s(1)0> = \mathbf{1} \otimes \partial \, \<s(1)0>, \qquad && \tilde \Delta^\partial X^k = 0,
		\\
		&\tilde \Delta^\partial \tau \sigma = \tilde \Delta^\partial \tau \tilde \Delta \sigma + \tilde \Delta \tau \tilde \Delta^\partial \sigma,
		\\
		&\tilde \Delta^\partial \mcI_\mfl^k \tau = (\mcI_\mfl^k \otimes \id) \tilde \Delta^\partial \tau + \sum_{|j|_\mfs < o(\mcI_\mfl^k \tau) } \frac{X^j}{j!} \otimes \mcI_{(\mfl, \partial)}^{k+j} \tau.
	\end{align*}
	For each $x,y \in \mbR^d$, we also define a linear map ${\chi}_x^y : \langle \tcT_1 \rangle \to \mbR$ as follows. For each $\mfl \in \mfL_+, \mft \in \mfL_-$ we set
	\begin{align*}
		\chi_z^{z'} (\mcI_{(\mfl, \partial)}^k \sigma) &= k! \mcQ_{X^k} [ J^\mfl(z') H_{\sigma; \eps, \delta}^{z, g}(z') + \mathcal{N}_{\gamma_{\sigma}}^{\mfl} H_{\sigma; \eps, \delta}^{z, g}(z')] 
		\\
		& \qquad - \sum_{|l|_\mfs < |\mcI_{\mfl}^k \sigma|_\mfs} \frac{(z'-z)^l}{l!} D^{k+l} K_\mfl \ast \mcR H_{\sigma; \eps, \delta}^{z, g}(z).
	\end{align*}
	We also define
	\begin{align*}
		\chi_z^{z'}(\Xi_{(\mft, \partial)}) &= \begin{cases}
			g_\eps(z') \qquad & \text{ if } \mft = \<b0>,
			\\
			g_{\delta}(z') \qquad & \text{ if } \mft = \<p0>,
			\\
			\eps^{-1/2} \partial_x K \ast g_{\eps, \delta}(z') \qquad & \text{ if } \mft = \<s(1)0>.
		\end{cases}
	\end{align*}
	Finally, we extend this definition by declaring that for $\eta \in \mcT_+$ we have
	\begin{align*}
		\chi_z^{z'}(\mcI_{(\mfl, \partial)}^k \sigma \cdot \eta) = \chi_z^{z'}(\mcI_{(\mfl, \partial)}^k \sigma) \cdot \gamma_{z'z}(\eta)
	\end{align*}
	where $\gamma_{z'z}$ is the element of $\mathcal{G}_+$ corresponding to $\Gamma_{z'z}$.

[Defn of arXiv:2601.00119, 'The largest common subtree of two random trees'] Let $\mu$ be a measure on $\mathbb{N}$. A random plane tree $\tau$ is called a \emph{Bienaym\'{e} tree with offspring distribution $\mu$} if it satisfies the following properties:
\begin{enumerate}
    \item[(a)] The law of $\mathrm{k}_\varnothing(\tau)$ is $\mu$.
    \item[(b)] For all $k \geq 1$ such that $\mu(k) > 0$, conditionally given that $\mathrm{k}_\varnothing(\tau) = k$, the subtrees $\theta_1\tau,...,\theta_k\tau$ are i.i.d.~and with the same law as $\tau$.
\end{enumerate}
We frequently call (b) \emph{the branching property} of Bienaymé trees. If $\sum_{k \geq 0} k\mu(k) = 1$ and $\mu(0) > 0$, then we call $\tau$ and $\mu$ \emph{critical}, and it is well-known that $\tau$ is almost surely finite.

[Proposition 2 of arXiv:2608.06646, 'Three-dimensional stochastic wave equation with non-Lipschitz coefficients'] Assume that $b$ and $\sigma$ are globally Lipschitz with Lipschitz constants $L_b$ and $L_\sigma$, respectively. Assume further that the initial condition $u_0$ is bounded with bounded derivatives and that $v_0$ is bounded. Under assumption~\eqref{E:ZeroOrderDifference}, there exists a unique random field solution $u$ to the stochastic wave equation~\eqref{E:SWE} such that, for all $p\ge 2$ and $T>0$,
    \begin{equation} 
        \sup_{(t,x)\in [0,T]\times \mathbb{R}^3}\mathbb{E}|u(t,x)|^p
        \le (3M)^{\frac{p}{2}} e^{cp\beta_0 T}.
    \end{equation}
    Here 
    \begin{equation}
    M=3\lr{T\|v_0\|_{L^\infty(\R^3)}+\|u_0\|_{L^\infty(\R^3)}+T\|\nabla u_0\|_{L^\infty(\R^3)}}^2 +Cp|\sigma(0)|^2\frac{T^{\nu+1}}{\nu+1}+C|b(0)|^2T^4\,,
\end{equation}

  and 
  $\beta_0 = C L_b^{1/2} + C p^{1/(\nu+1)} L_\sigma^{2/(\nu+1)}$, and the parameter $\nu$ is defined in~\eqref{E:ZeroOrderDifference}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem T:L2Lim of arXiv:2412.03521, 'On ergodic properties of stochastic PDEs'] Suppose that conditions~(it:i-InvMea of the paper) and~(it:iii-InvMea of the paper) of
  Theorem~(T:InvMea of the paper) hold. Let the following condition~(it:ii'-InvMea of the paper)
  replace condition~(it:ii-InvMea of the paper) of Theorem~(T:InvMea of the paper):

  \begin{enumerate}[wide, labelwidth=!, labelindent=0pt, label=\emph{(\roman*')}]
    \setcounter{enumi}{1}
    \setlength\itemsep{.1in}

    \item For $t \ge 0$, $x \in \mathbb{R}$ and a Borel measure
      $\mu$ on $\mathbb{R}^d$, let $J_0(t,x;\mu)$ be the solution to the homegenous
      equation (see~(equation E:def-J0 of the paper)). We assume that the following limit
      exists:
      \begin{align}
        \lim_{t\to\infty} \sup_{x\in\mathbb{R}^d} \left| J_0(t,x;\mu)\right| <\infty.
      \end{align}

  \end{enumerate}

  \noindent We also assume that the nonnegative weight function $\rho$ is an
  element in $L^1(\mathbb{R}^d)$, which does not necessarily need to be admissible (see
  Definition~(D:Rho of the paper)). Recall that $u(t,\cdot)$ is the solution
  to~(equation E:SHE of the paper). Then the following existence and uniqueness statements hold:

  \begin{enumerate}[wide, labelwidth=!, labelindent=0pt, label=\emph{(\arabic*)}]
    \setlength\itemsep{.1in}

    \item There exists a random field $Z=\{Z(x);\;x\in\mathbb{R}^d\}$
      such that $Z(\cdot)\in L_\rho^2(\mathbb{R}^d)$ a.s. and
      \begin{equation}
        u(t,\cdot) \stackrel{\text{(d)}}{\longrightarrow} Z,
          \quad \text{as $t\to\infty$,}
          \quad \text{in $L_\rho^2(\mathbb{R}^d)$.}
      \end{equation}

    \item Suppose $u_1$ and $u_2$ are two solutions
      to~(equation E:SHE of the paper) starting from $\mu_1$ and $\mu_2$, respectively. Assume
      that both $\mu_i$ satisfy~(equation E:InitData-Limit of the paper). Let $Z_1$ and $Z_2$ be
      the respective limiting random fields given in part~(it:L2Lim-1 of the paper). Then
      we have
      \begin{align}
        \lim_{t\to\infty} \sup_{x\in\mathbb{R}^d} \left|J_0(t,x;\mu_1-\mu_2)\right| = 0
        \quad \Longrightarrow \quad Z_1 \stackrel{(d)}{=} Z_2\:,
      \end{align}
      where the notation $Z_1 \stackrel{(d)}{=} Z_2$ denotes that the two random
      fields follow the same law.

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

