body:
[Lemma lem:RW of arXiv:2410.23899, 'Tightness for interlacing geometric random walk bridges'] Let $k, \vec{x}, \vec{y}, a,b, f,g$ be as in the first paragraph of Definition (AvoidBB of the paper). Suppose that $d_n$ is a sequence of positive reals such that $d_n \rightarrow \infty$ as $n \rightarrow \infty$, and set $A_n = \lfloor a d_n \rfloor$, $B_n = \lceil b d_n \rceil$. Let $f_n: [d_n^{-1}A_n, d_n^{-1} B_n] \rightarrow (-\infty, \infty]$ and $g_n: [d_n^{-1}A_n, d_n^{-1} B_n] \rightarrow [-\infty, \infty)$ be continuous functions such that $f_n \rightarrow f$ and $g_n \rightarrow g$ uniformly on $[a,b]$. In the case when $f = \infty$, the last statement means that $f_n = \infty$ for all large $n$, and when $g = -\infty$, the last statement means that $g_n = -\infty$ for all large $n$. We also suppose that 
\begin{equation}
\lim_{n \rightarrow \infty} |g_n(d_n^{-1}B_n) - g_n(b)| = 0 \mbox{ if } g \neq -\infty \mbox{ and }\lim_{n \rightarrow \infty} |f_n(d_n^{-1}A_n) - f_n(a)| = 0 \mbox{ if } f \neq -\infty.
\end{equation}

Fix $p \in (0,\infty)$, $\sigma = \sqrt{p(1+p)}$ and suppose that $\vec{X}^n, \vec{Y}^n \in \mathfrak{W}_k$ are sequences such that 
\begin{equation}
\lim_n \sigma^{-1} d_n^{-1/2} (X_i^n - p A_n)  = x_i \mbox{ and } \lim_n \sigma^{-1} d_n^{-1/2} (Y_i^n - p B_n)   = y_i \mbox{ for } i = 1, \dots, k.
\end{equation}
Define $F_n: [A_n, B_n] \rightarrow (-\infty, \infty]$ and $G_n: [A_n, B_n] \rightarrow [-\infty, \infty)$ through
$$F_n(t) = \sigma d_n^{1/2} \cdot f_n(t/d_n) + pt \mbox{ and } G_n(t) = \sigma d_n^{1/2} \cdot g_n(t/d_n) + p t.$$
Then, we have the following statements.
\begin{enumerate}
\item There exists $N_0 \in \mathbb{N}$ such that for $n \geq N_0$ the laws $\mathbb{P}_{\mathsf{Inter}, \operatorname{Geom}}^{A_n,B_n, \vec{X}^n, \vec{Y}^n, F_n, G_n}$ are well-defined, i.e. the sets $\Omega_{\mathsf{Inter}}(A_n, B_n, \vec{X}^n, \vec{Y}^n, F_n, G_n)$ are non-empty.
\item If $\mathfrak{Q}^n$ has law $\mathbb{P}_{\mathsf{Inter}, \operatorname{Geom}}^{A_n,B_n, \vec{X}^n, \vec{Y}^n, F_n, G_n}$, then the sequence of $\llbracket 1,k \rrbracket$-indexed line ensembles $\mathcal{Q}^n$ on $[a,b]$ defined by
\begin{equation}
\mathcal{Q}_i^n(t) = \sigma^{-1} d_n^{-1/2} \cdot \left( Q_i(t d_n) - td_n p \right) \mbox{ for } n \geq N_0, \hspace{2mm} t \in [a,b] \mbox{ and } i = 1, \dots, k,
\end{equation}
converges weakly to $\mathbb{P}_{\operatorname{avoid}}^{a,b,\vec{x},\vec{y},f,g}$ from Definition (AvoidBB of the paper) as $n \rightarrow \infty$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 (Continuity of the half-line Robin form) of arXiv:2608.30211, '2608.30211'] Let $V\in L^\infty(\R_+)$ be real.  For $\beta\in[0,\infty)$ set
\begin{equation}
 \nu_\beta(V):=
 \inf_{h\in H^1(\R_+)\setminus\{0\}}
 \frac{\displaystyle
  \int_0^\infty\bigl(|h'|^2+Vh^2\bigr)\,dy
  +\beta |h(0)|^2}
 {\displaystyle\int_0^\infty h^2\,dy},
\end{equation}
and let $\nu_\infty(V)$ be the same infimum over
$H_0^1(\R_+)\setminus\{0\}$, without the boundary term.  Then
$\beta\mapsto\nu_\beta(V)$ extends continuously to the compactified
interval $[0,\infty]$.  More quantitatively, there is $C_V>0$ such that
\begin{equation}
 0\leq \nu_\infty(V)-\nu_\beta(V)\leq C_V\beta^{-1/2}
 \qquad(\beta\geq1).
\end{equation}

[Corollary cor:canonical-borel-liouville-data of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] For every $n\ge1$ and $0<a<b$, the maps
\begin{equation}
 x\longmapsto\Lambda_n^x,
 \qquad
 x\longmapsto\Pi_{a,b}^x

\end{equation}
are measurable, and $\Pi_{a,b}^x$ is a finite-rank projection for every
$x\inX$.  On $\Omega_{\rm op}$,
\begin{equation}
 G_x=A_x^{-1},
 \qquad
 \Pi_{a,b}^x=\mathbf 1_{(a,b)}(A_x).
\end{equation}

