[Defn 18 of arXiv:2608.03956, 'From Triangular Array Progression\\ to Near-Log-Concave State Transitions'] Let $\mathbf{D}$ be an ordered finite subset of $\R$ with cardinality $|\mathbf{D}|\geq 3$, and $X : \Omega \rightarrow \mathbf{D}$ be a random variable with probability mass function 
\begin{align}
\P\left(X = d_j\right) = P_{X}(d_j), \notag 
\end{align}
for every $d_j \in \mathbf{D}$. The random variable $X$ is called \emph{near}-log-concave of degree $r\in \Z_+$ for finite $0 \leq r \leq |\mathbf{D}|-3$, if 
\begin{align} 
P_{X}(d_{j-1})P_{X}(d_{j+1}) \leq P_{X}(d_j)^2 \hspace{0.15in} \text{$\forall j\in\mathcal{I}_{|\mathbf{D}|}^{(r)}$}, \notag
\end{align}
where $\mathcal{I}_{|\mathbf{D}|}^{(r)} \subseteq \mathcal{I}_{|\mathbf{D}|} = \{2,\ldots,|\mathbf{D}|\}$ such that 
\begin{align}
|\mathcal{I}_{|\mathbf{D}|}^{(r)}| = |\mathbf{D}| - r - 2. \notag
\end{align}

[Theo 40 of arXiv:2608.28148, 'Flows and homotopies of Banach Lie algebroids'] Assume that $M$ is smoothly paracompact and $k\geq 2$. Let $a\colon [0,1]^2\rightarrow A$ be a $C^k$-variation of admissible curves and $b\colon [0,1]^2\to A$ be a $C^k$-map such that $\gamma= \pi\circ a=\pi\circ b$, $b_\varepsilon(0)=b_\varepsilon(1)=0$, for every $\varepsilon$ and $b^t:=b(\cdot,t)$ is an admissible curve for all $t \in [0,1]$. We have the following equivalences
\begin{enumerate}
\item[\rm (1)] $(a,b)$ is a homotopy from $a_0$ to $a_1$;
\item[\rm (2)] the pair gives rise to an algebroid morphism  
\[f_{a,b}\colon T([0,1]\times[0,1])\to A, \quad f_{a,b}(\lambda \partial_t+\mu\partial_\varepsilon)=\lambda a+\mu b\]
over $\gamma \colon [0,1]^2 \rightarrow M, \gamma :=\pi \circ a$.
\item [\rm (3)] 
For one (hence every) extension $\mathfrak{u}_\varepsilon(t,\gamma_\varepsilon(t))=a_\varepsilon(t)$ from \Cref{timedependent2}, the section $b$ is given by:
\begin{equation}
\dis b_\varepsilon(t)= \int_0^t \mathfrak{F}_{\mathfrak{u}_\varepsilon, \gamma_\varepsilon (s)}^{t,s} \frac{\partial \mathfrak{u}_\varepsilon}{\partial \varepsilon}\left(s,\g_\varepsilon(s)\right)ds.
\end{equation}
where the integral is the Bochner integral in the Banach space $A_{\gamma_\varepsilon(t)}$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem_cheap_hop of arXiv:2411.02046, 'Speed of Convergence and Moderate Deviations of FPP on Random Geometric Graphs'] There exists~$\delta > 0$  such that  for any~$n \in \N$, any~$\ell > 0$, and any~$t \ge 1$, 
	\begin{equation*}
		\p \left( \begin{array}{l} \text{there is 
 a self-avoiding path $\gamma$ in $\mathcal{G}^t$  starting in  } B(o,\ell)\\[.1cm] \text{starting in  }~B(o,\ell)~{ with }~|\gamma| = n \text{ and } \sum_{e \in \gamma} \tau^t_e \le \delta n
		\end{array}\right) \le  \frac{\max\{\ell^d,1\}}{2^{n}}.
	\end{equation*}

[Proposition 9 of arXiv:2609.01296, 'Asymptotic safety regions for Gabor frames generated by Hermite functions'] Let $0< \delta < \eta < \frac{1}{3}$, and let $S_n(\delta,\eta)$ be defined by \eqref{eq:diagonal_safety_region}. Then
    \begin{equation}
        \lim_{n\to\infty} \sup_{(a,b)\in S_n(\delta, \eta)}
        \sum_{\substack{(k,l)\in\Z^2\\X_{k,l}(a,b)\geq6n}}
        \left|\mathcal L^0_n\left(X_{k,l}(a,b)\right)\right| e^{-X_{k,l}(a,b)/2} = 0.
    \end{equation}

