        \begin{align}
                \frac1N\abs{\avg{B_1G\wt IGB_2}_{L}}                                                      & \prec \frac{\vphi+\eta}{N\eta},                                                 \\
                \frac1{N^2}\sum_{i,\mu} \abs{(B_1G\wh\Sg^{1/2})_{\mu i}}                                  & \prec \sqrt{\frac{\vphi+\eta}{N\eta}},                                                 \\
                \frac1{NL^2}\sum_{i,\mu} \abs{(B_1G\wh\Sg^{1/2})_{\mu i}} \abs{(\wh\Sg^{1/2}GB_2)_{i\mu}} & \prec \frac1N\frac{\vphi+\eta}{N\eta} \leq\left(\frac{\vphi+\eta}{N\eta}\right)^2. 
        \end{align}
        Moreover, if $\bbv,\bbw$ are deterministic unit vectors and the displayed factors have compatible block indices, then
        \begin{align}
                \frac1{N^2}\sum_{i,\mu} \abs{(B_1G)_{\bbv i}} \abs{(B_2G)_{\mu i}} \abs{(GB_3)_{\mu\bbw}} \prec \left(\frac{\vphi+\eta}{N\eta}\right)^{3/2}. 
        \end{align}

