[Theorem thm:dichotomy of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Fix $C_\star>C_{\mathrm{GTD}}$ and $\kappa\ge2C_\star$. Let $h,\gamma>0$ satisfy $h<2/\sqrt\kappa$, and let $s$, $\beta$, and $q_\kappa$ be defined as above. Then at least one of the following two cases holds.

\begin{enumerate}
\item[\rm(Q)] There is $\lambda\in[1,\kappa]$ such that, for the
two-dimensional quadratic potential
$U_\lambda(x)=\lambda\lvert x\rvert^2/2$, two initial states
$z,\widetilde z\in\mathbb R^4$ satisfy
\begin{equation}
 \lim_{n\to\infty}
 \norm{\delta_z(Q_{h,\gamma}^{U_\lambda})^n-
       \delta_{\widetilde z}(Q_{h,\gamma}^{U_\lambda})^n}_{\mathrm{TV}}^{1/n}
 =\rho_{\mathrm q}(s,\beta;\kappa)\ge q_\kappa.
\end{equation}

\item[\rm(C)] There exist $U\in\mathcal U_\kappa^2$ and constants $c_0,C_0>0$ such that, for every $R\ge1$, the following holds. The dilated potential $U_R(x)=R^2U(x/R)$ also belongs to $\mathcal U_\kappa^2$, the kernel $Q_{h,\gamma}^{U_R}$ has a unique invariant law $\pi_R$, and there is an initial state $z_R\in\mathbb R^4$ satisfying
\begin{equation}
 W_2(\delta_{z_R},\pi_R)\le C_0(1+R),
\end{equation}
while
\begin{equation}
 \norm{\delta_{z_R}(Q_{h,\gamma}^{U_R})^n-\pi_R}_{\mathrm{TV}}\ge\frac38,
 \qquad
 0\le n\le\left\lfloor\frac1{16}e^{c_0R^2}\right\rfloor.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop prop convergence of sep dist of arXiv:2512.20338, 'Up-down chains and scaling limits: \\ application to permuton- and graphon-valued diffusio'] Suppose that $ \sum_{ n \ge 0 } \tfrac{1}{ c _n} < \infty $ and that $ \{  c _{n+1} -  c _{n} \}_{ n \ge 0 } $ is an unbounded, nondecreasing sequence.
	Then we have the limits
	$$ 
    	\lim_{ n \to \infty }
    		 \Delta _n( \lfloor   c _n t \rfloor )
      		=
    	\lim_{ n \to \infty }
    		 \Delta _n^*( t )
      		=
            	\sum_{i=0}^{\infty} 
            		e^{- t  c _i } 
            		\prod_{j = 0 \atop j \ne i}^\infty 
    					\frac{ c _{j}}{ c _{j}- c _{i}}
    		,
    			\qquad
    			t > 0
    		.
	$$  

	\noindent
	Moreover, 

	for $ n \ge 0 $ we have the asymptotic description
    \begin{equation}
    	\sum_{ i = n + 1 }^{\infty} 
    		e^{- t  c _i } 
    		\prod_{j = 0 \atop j \ne i}^\infty 
				\frac{ c _{j}}{ c _{j}- c _{i}}
			=
				o( e^{ - t  c _n } )
		,
			\qquad
			t \to \infty

    \end{equation}

