body:
[Proposition prop:annealed cond of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $n\ge2$. Let $\bm{u}=(u_1,\ldots,u_{n})$,
		$\bm{q}=(q_1,\ldots,q_n)$ be strictly increasing
		in~$(0,1)$, and $\zeta\in\mathrm{Prefix}_{n+1}(\bm{u};\bm{q})$.
		Define the \emph{prefix free energy}
		\begin{equation}
			\mathcal{P}^{(n)}(\bm{u};\bm{q})
			\;:=\;
			\inf_{\zeta'\,\in\,\mathrm{Prefix}_{n+1}(\bm{u};\bm{q})}
			\mathcal{P}\mathrm{arisi}(\zeta'),
		\end{equation}
		and the \emph{$n$-step complexity functional at level $f$}
		\begin{equation}
			\mathcal{C}^{(n)}_f(\bm{u};\bm{q})
			\;:=\;
			u_n\,\bigl(\mathcal{P}^{(n)}(\bm{u};\bm{q})-f\bigr).
		\end{equation}

		We assume:
		\begin{enumerate}
			\item[\emph{(i)}]
			\emph{(Tail optimality)} The infimum $\mathcal{P}^{(n)}(\bm{u};\bm{q})$ is
			attained at $\zeta$.
			\item[\emph{(ii)}]
			\emph{(Stationarity)} $(\bm{u};\bm{q})$ is a critical point of
			$\mathcal{C}^{(n)}_f$.
		\end{enumerate}
		Let $\varepsilon\in(0,1)$, let
		$(\mathbf{m}^{(1)},\ldots,\mathbf{m}^{(n-1)})\in\mathrm{SUSY}_{n-1}(\zeta,\varepsilon)\cap\mathrm{LawMatch}_{n-1}(\zeta,\varepsilon)$. Let
		$\mathcal{N}_\varepsilon(f,\zeta,q_n,\mathbf{m}^{(n-1)})$ be the number of critical points $\mathbf{m}$
		of $F_{\mathrm{TAP},\zeta}$ with
		$(\mathbf{m}^{(1)},\ldots,\mathbf{m}^{(n-1)},\mathbf{m})\in\mathrm{SUSY}_n(\zeta,\varepsilon)$ and
		$\tfrac{1}{N}F_{\mathrm{TAP},\zeta}(\mathbf{m})\in(f-\varepsilon,f+\varepsilon)$. Set
		\begin{equation*}
			\mathrm{Skel}_{n-1}=\left(\nabla F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(1)}),F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(1)}),\ldots,\nabla F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(n-1)}), F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(n-1)})\right).
		\end{equation*} Then
		\begin{multline}
			\lim_{\varepsilon\to0}\lim_{N\to\infty}
			\frac{1}{N}\log\mathbb{E}\Bigl[
			\mathcal{N}_\varepsilon(f,\zeta,q_n,\mathbf{m}^{(n-1)})
			\;\Big|\;
			\mathrm{Skel}_{n-1}=(0,N\mathcal{P}\mathrm{arisi}(\zeta),\ldots,0,N\mathcal{P}\mathrm{arisi}(\zeta))
			\Bigr]
			=
			\mathcal{C}_f^{(n)}(\bm{u};\bm{q})
			\\=
			\zeta([0,q_n))\,(\mathcal{P}\mathrm{arisi}(\zeta)-f).
		\end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 7 of arXiv:2512.19517, 'Spiking and Resetting'] The process $({\bar X}^\varepsilon_t)_{t \ge 0}$ with state space $\{0,1\}$ and c\`adl\`ag  trajectories defined by 
\begin{equation}

\begin{split}
\forall t \ge 0, \quad {\bar X}^\varepsilon_t = \sum_{k\ge 0} {\mathbf 1}_{ t \in [e_{2k+1}^{\varepsilon}, e_{2k+2}^\varepsilon )} 
\end{split}
\end{equation}
converges in law to the jump Markov process $({\bar X}_t)_{t \ge 0}$ defined in Section \ref{sec:imr}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 4. prop: improved lower bound for point probability of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] For any $x \in F$, $t \geq 0$, and $\varepsilon > 0$,
  \begin{equation}
    P_{x}(X(t) = x) 
    \geq 
    \frac{\mu(\{x\})}{\mu(D_{R}(x, \varepsilon))}
    - 
    P_{x}(\tau_{B_{R}(x, \varepsilon)} \leq t).
  \end{equation}

[Lemma lem:VolumeGrowthEstimate of arXiv:2609.01825, 'On everywhere locally soluble varieties \\ in families over toric bases'] Let $A_0 \subset A_1 \subset A_2 = \mathbb R^s$ be affine subspaces of dimension $d_0 < d_1$ and $d_2 = s$ equipped with the Euclidean distance. Let $X_i \subset A_i$ be compact subsets with $\operatorname{diam}(X_0) \leq \delta_0$ and $\operatorname{dist}(X_{i-1}, X_i) \leq \delta_i$ for $i = 1, 2$. Then
	\begin{equation*}
		\operatorname{vol}(X_2) \ll_{d_0, d_1, d_2} (\delta_0 + \delta_1 + \delta_2)^{d_0} (\delta_1 + \delta_2)^{d_1 - d_0} \delta_2^{d_2 - d_1}. 
	\end{equation*}
	When $\delta_0 \geq \delta_1 \geq \delta_2$, this simplifies to $\operatorname{vol}(X_2) \ll_{d_0, d_1, d_2} \delta_0^{d_0} \delta_1^{d_1 - d_0} \delta_2^{d_2 - d_1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Problem problem-kac of arXiv:2604.04882, 'On a Problem of M. Kac on Laplace Distributions'] Let
    \begin{align}
        \Phi(x,y)=\frac{1}{\tfrac{1}{x}+\tfrac{1}{y}-1}.
    \end{align}
    Prove that if
    \begin{align}
        \Phi\left(
            \int_{-\infty}^{+\infty} e^{i\xi t}\,d\sigma_1(t),
            \int_{-\infty}^{+\infty} e^{i\xi t}\,d\sigma_2(t)
        \right)
        =\frac{1}{1+\xi^2},
    \end{align}
    then $\sigma_1$ and $\sigma_2$ are centered Laplace distributions. (Stated as a problem by the paper; open unless the paper says otherwise.)

