body:
[Lemma 7 of arXiv:2609.01296, 'Asymptotic safety regions for Gabor frames generated by Hermite functions'] Let $0< a \leq b$ and $r\geq0$. Define an ellipse
    \begin{equation}
        E_r = \left \{(x,y)\in \R^2 :\frac{x^2}{b^2}+\frac{y^2}{a^2}\leq \frac{r}{\pi} \right \}.
    \end{equation}
There exists an absolute constant $C>0$ such that for every $0 \leq r_1 \leq r_2$ we have
\begin{equation}
     \#\left(( E_{r_2} \setminus E_{r_1})\cap \Z^2 \right) \leq ab(r_2-r_1) + C(a\sqrt{r_2} + b \sqrt{r_2-r_1} + 1).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem A1 of arXiv:2411.01847, 'Well-Posedness of Stochastic Chemotaxis System'] Let $\left(e^{-tA}\right)_{t\geq 0}$ be the Neumann heat semigroup in $\mathcal{O}$.

       Let $\nu_1$ denote the first nonzero eigenvalue of $A$ on $\mathcal{O}$ under Neumann boundary condition. Then, there exists a constant $C$, depending only on $\mathcal{O}$, such that:
      \begin{itemize}
  \item[(\romannumeral 1)] If $1\leq p\leq \infty$, for $t>0$
  \begin{align}
      \|(A+1)^\beta e^{-tA} \omega\|_{p}\leq Ct^{-\beta}e^{-\nu_1t}\|\omega\|_{p},\\
       \|\nabla e^{-tA} \omega\|_{p}\leq C(1+t^{-\frac{1}{2}})e^{-\nu_1t}\|\omega\|_{p},
  \end{align}
holds for all $\omega\in L^{p}(\mathcal{O})$.
  \item[(\romannumeral 2)] If $p\in [2,\infty)$, for $t>0$
  \begin{align}
       \|\nabla e^{-tA} \omega\|_{p}\leq Ce^{-\nu_1t}\|\omega\|_{W^{1,p}(\mathcal{O})},
  \end{align}
is valid for all $\omega\in W^{1,p}(\mathcal{O})$.

\item[(\romannumeral 3)]
If $\beta>0$, $p\in (1,\infty), t>0$, then the operators $(A+1)^\beta e^{-tA}\nabla\cdot$ and $e^{-tA}\nabla\cdot$ both possess extension to  operators from $L^{p}(\mathcal{O})$ into $L^{p}(\mathcal{O})$ which fulfill
  \begin{align}
      &\|(A+1)^\beta e^{-tA}\nabla\cdot w\|_{p}\leq C(\epsilon)t^{-\frac{1}{2}-\beta-\epsilon}e^{-\nu_1 t}\|w\|_{p}, \\
      &\| e^{-tA}\nabla\cdot w\|_{p}\leq Ct^{-\frac{1}{2}}e^{-\nu_1 t}\|w\|_{p},
  \end{align}
  for all $\omega\in (L^p(\mathcal{O}))^2$, any $\epsilon>0$.






	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop p:r-X-Y of arXiv:2411.12003, 'Central Limit Theorem for non-stationary random products of $\SL(2, \R)$ matrices'] Under the assumptions of Lemma~(l:X-Y of the paper), let $K_r:=\textcolor{black}{5\,} C_r^{{\varepsilon}} C_X^{2}$ be the factor that appears in its conclusion~(equation eq:t-bound of the paper). Assume additionally that for some $\rho>0$ one has
\begin{equation}
    \rho^{\textcolor{black}{2+{\varepsilon}}} N_{\rho}(X)\le \frac{1}{100}
\end{equation}
and
\begin{equation}
    K_r \rho^{\textcolor{black}{2+{\varepsilon}}} e^{\frac{\rho^2}{2}} \le \frac{1}{100}.
\end{equation}
Then
\[
N_{\rho}(Y) \le N_{\rho}(X) + 2 K_r e^{\frac{\rho^2}{2}}.
\]

[Definition 7 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Consider a pullback square of stacks
  \begin{equation*}
    \begin{tikzcd}
      \mcalY' \arrow[r,"g'"] \arrow[d,"f'"'] & \mcalY \arrow[d,"f"] \\
      \mcalX' \arrow[r,"g"'] & \mcalX.
    \end{tikzcd}
  \end{equation*}
  For \(\mcalF\in\mcalD_{\qcoh}(\mcalY)\), the canonical equivalence \(Lf'^*Lg^*\simeq L(g')^*Lf^*\) and the counit \(Lf^*Rf_*\mcalF\to\mcalF\) give a morphism
  \begin{equation*}
    Lf'^*Lg^*Rf_*\mcalF\xrightarrow{\sim}L(g')^*Lf^*Rf_*\mcalF\to L(g')^*\mcalF.
  \end{equation*}
  Its adjoint under \(Lf'^*\dashv Rf'_*\) is denoted by
  \begin{equation}

    \BC_{f,g}(\mcalF)\colon Lg^*Rf_*\mcalF\to Rf'_*L(g')^*\mcalF
  \end{equation}
   and is called the \emph{base change morphism}. This is a morphism in \(\mcalD_{\qcoh}(\mcalX')\).

[Definition 40 (Represented four-copy functional) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] For $q\ge2$ and $\xi=[f_n]_{\mathcal U}\in\cH_q$, define
\begin{equation}
 \mathfrak Q_q(\xi)
 =\Ulim\left\{
  \E[I_q^{W_n}(f_n)^4]
  -3\E[I_q^{W_n}(f_n)^2]^2
 \right\}.

\end{equation}

[Defin def:augmented-stable of arXiv:2411.03609, 'Asymptotically optimal Wasserstein couplings for the small-time stable domain of attractio'] A L\'evy process $\bm{X}=(\bm{X}_t)_{t \in [0,1]}$ is an augmented $\alpha$-stable process if it has no Gaussian component, and, for some $\alpha\in(0,2]$, its L\'evy measure $\nu_{\bm{X}}$ has the form
\begin{equation} 
\nu_{\bm{X}}(A)
= \int_0^\infty\int_{\mathbb{S}^{d-1}}  \1_{A}(x\bm{v}) \mathcal{Q}(x,\bm{v})  \sigma(\mathrm{d} \bm{v})x^{-\alpha-1}\mathrm{d} x, \quad \text{ for } A \in \mathcal{B}(\mathbb{R}^d_{\bm{0}}),
\end{equation}
where $\sigma$ is a probability measure on $\mathcal{B}(\mathbb{S}^{d-1})$ and $\mathcal{Q}:(0,\infty)\times \mathbb{S}^{d-1} \mapsto [0,\infty)$ is a measurable satisfying $\mathcal{Q}(\cdot,\bm{v})\in\mbox{SV}_0$ for $\bm{v}\in\mathbb{S}^{d-1}$.

[Theorem 4 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] Fix $T>0.$ Let $X$ be a random variable whose density $f : \N \rightarrow (0, \infty) $ with respect to $\pi_{T}$ is ultra log-concave, then we have
\begin{displaymath}
    \delta_{\mathrm{FI}}(f) \ge a(1-a)T^{2} \Delta_{\frac{f(0)}{f(1)}} \Bigg( \frac{\E X}{T} \Bigg)
\end{displaymath}
where, for $c>0,$ we denote
\begin{displaymath}
    \Delta_{c}(z):= z^{5} \Big( \frac{c}{1 + cz} \Big)^{2}  , \quad z\ge 0.
\end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:lf-insertion-infty of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] Let $\beta\in\mathbb{R}$, $(\alpha_i,z_i)\in\mathbb{R}\times\mathbb{H}$ and $(\beta_j,s_j)\in\mathbb{R}\times\partial\mathbb{H}$ for $i=1,...,m$ and $j = 1,...,n$ and the $z_i$'s and $s_j$'s are pairwise distinct. Set 
	\begin{equation*}
	\begin{split}
	&C_{\mathbb{H}}^{(\alpha_i,z_i)_i,(\beta_j,s_j)_j,(\beta,\infty)} =\\ &\prod_{i=1}^m\prod_{j=1}^n(2\mathrm{Im}z_i)^{-\frac{\alpha_i^2}{2}}|z_i|_+^{-2\alpha_i(Q-\alpha_i-\frac{\beta}{2})}|s_j|_+^{-\beta_i(Q-\frac{\beta_i+\beta}{2})}e^{\frac{\alpha_i\beta_j}{2}G_\mathbb{H}(z_i,s_j)+\sum_{i'=i+1}^{m}\alpha_i\alpha_{i'}G_\mathbb{H}(z_i,z_{i'})+\sum_{j'=j+1}^{n}\frac{\beta_j\beta_{j'}}{4}G_\mathbb{H}(s_j,s_{j'}) }.   
	\end{split}
	\end{equation*}
	Let $(h,\mathbf{c})$ be sampled from $C_{\mathbb{H}}^{(\alpha_i,z_i)_i,(\beta_j,s_j)_j,(\beta,\infty)}P_\mathbb{H}\times [e^{(\sum_i\alpha_i+\frac{\beta}{2}+\frac{1}{2}\sum_j\beta_j-Q)c}dc]$, and 
	\begin{equation*}
	    \phi(z) = h(z)+(\beta-2Q)\log|z|_++\sum_{i=1}^m\alpha_iG_\mathbb{H}(z,z_j)+\sum_{j=1}^n\frac{\beta_j}{2}G_\mathbb{H}(z,s_j)+\mathbf{c}.
	\end{equation*}
	We write $\mathrm{LF}_{\mathbb{H}}^{(\alpha_i,z_i)_i,(\beta_j,s_j)_j,(\beta,\infty)}$ for the law of $\phi$ and call a sample from $\mathrm{LF}_{\mathbb{H}}^{(\alpha_i,z_i)_i,(\beta_j,s_j)_j,(\beta,\infty)}$ the Liouville field on $\mathbb{H}$ with insertions $(\alpha_i,z_i)_{1\le i\le m}, (\beta_j,s_j)_{1\le j\le n}, (\beta,\infty)$.

[Lemma 55 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the notation from Definition \ref{Def.ParametersEdge}. If $R \in (0, \infty)$ and $z(\theta) = R e^{\pm \im \theta}$, then
\begin{equation}
\frac{d}{d\theta}\Real[\GFt(z(\theta))] > 0 \mbox{ for } \theta \in (0, \pi).
\end{equation}

[Cor corolary:condlaw of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] Under $\mathbb{P}_{0,x,0}$ and conditionally on $\tilde{\mathcal{E}}$, the point measures 
$$\mathcal{E}_+(\mathrm{d} s, \mathrm{d}\upvarrho, \mathrm{d} \omega):=\mathbbm{1}_{L_\sigma^* (\upvarrho,\omega)>0}\mathcal{E}(\mathrm{d} s, \mathrm{d}\upvarrho, \mathrm{d} \omega) \quad \text{ and } \quad  \mathcal{E}_0(\mathrm{d} s, \mathrm{d}\upvarrho, \mathrm{d} \omega):=\mathbbm{1}_{L_\sigma^* (\upvarrho,\omega)=0}\mathcal{E}(\mathrm{d} s, \mathrm{d}\upvarrho, \mathrm{d} \omega)$$ are independent, and their conditional distributions are as follows:
\begin{itemize}
    \item[\emph{(i)}]The conditional distribution of $\mathcal{E}_+$ given $\tilde{\mathcal{E}}$ is characterised by the relation: 
     \begin{align}
         \mathbb{E}_{0,x,0}\Big[  g( \, \widetilde{\mathcal{E}} \, ) \exp \big(-  \langle \mathcal{E}_+,f \rangle  \big)      
        \Big]  
        =  \mathbb{E}_{0,x,0}\Big[  g(\, \widetilde{\mathcal{E}} \, ) \prod_{z \in \mathcal{D}_{\widetilde{X}}} \mathbf{N}_x^{*, \Delta \widetilde{X}_z }\Big( \exp \big( -f(z , \rho, W ) \big) \Big)  \Big],  
    \end{align}
    which holds for every non-negative measurable function $f$ on $\mathbb{R}_+\times \mathbb{D}(\mathbb{R}_+, \mathcal{M}_f(\mathbb{R}_+)\times \mathcal{W}_{E})$.
    \item[\emph{(ii)}]  The point measure  $\mathcal{E}_0$ conditionally on $\widetilde{\mathcal{E}}$ is a Poisson point measure  with intensity measure given by 
    \begin{equation*}
        \mathbbm{1}_{[ 0,A_\sigma )}{\mathrm{d}} t \otimes  \mathbf{N}_{x}^*( \, \cdot \cap \{L_\sigma^*=0\}). 
    \end{equation*}
\end{itemize}
Furthermore, the previous statements hold if we replace $\mathbb{P}_{0,x,0}$ by the excursion measure $\mathbb{N}_{x,0}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2512.02661, 'Worst-case mixing estimates for Brownian motion with semipermeable barriers'] For every $\gamma \in (0,1)$ there exists a constant $c>0$ depending only on $\gamma$ such that the following holds.
	Consider $R>0$ and $y\in \bbR^2$ with $\Vert y \Vert \leq R$.
	Then, for every $\varepsilon \leq \gamma R/2$,
	\begin{align}
		\bbP\bigl(W_{R^2} \in \sB(y, \varepsilon) \text{ and } \Vert W_t - (t/R^2)y \Vert \leq \gamma R, \, \forall t\leq R^2 \bigr) \geq c(\varepsilon/R)^2. 
	\end{align}

