[Lemma lem:correlation_stopping_tilde of arXiv:2608.05089, 'Correlation decay in area-tilted line ensembles'] There is some $\lambda_0 > 1$ and $C, c > 0$ such that for all $\lambda \geqslant \lambda_0$,
\begin{equation}
    \mathbb{P} \mleft[
        \exists j \in L^0_\ell \text{ such that } \mathsf{AllReversed}^j(\widetilde{\mathbf{X}},\widetilde{\mathbf{Y}}) \text{ holds}
    \mright] \geqslant 1 - C e^{-c t},
\end{equation}
and the same holds with $L^0_\ell$ replaced by $L^0_r$, $L^t_\ell$, or $L^t_r$.

[Lemma lem:lower_bound_alpha_stab of arXiv:2411.03609, 'Asymptotically optimal Wasserstein couplings for the small-time stable domain of attractio'] Let $\bm{X}$ be a L\'evy process that differs in law from the $\alpha$-stable process~$\bm{Z}$, $\alpha\in(0,2]$. Let $\psi_{\bm{X}}$ and $\psi_{\bm{Z}}$ denote their L\'evy--Khintchine exponents. Pick any $q\in(0,1]\cap(0,\alpha)$ and $\bm{u}_*\in \mathbb{R}^d\setminus\{\bm 0\}$ for which $C_*\coloneqq 2^{q-1}|\bm{u}_*|^{-q}|\psi_{\bm{X}_1}(\bm{u}_*)-\psi_{\bm{Z}_1}(\bm{u}_*)|> 0$. Then, we have
\begin{align*}
\mathcal{W}_q(\bm{X}^t_1,\bm{Z}_1)
\geqslant C_*t^{1-q/\alpha}
+ \mathcal{O}(t^{2-q/\alpha}),
\qquad\text{as }t \downarrow 0.
\end{align*}

[Lemma rho_in_l2_l2 of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] All limit points $\mathbb{Q}$ of the sequence $( \mathbb{Q}_{\nu_N})_{ {N \geq 1}}$ are concentrated on one path of absolutely continuous measures whose density, which we denote by $\rho_t$, is such that
    \begin{equation*}
        \int_0^T \int_0^1 [\rho_t(u)]^2 du ds < \infty \quad \textrm{ $\mathbb{Q}$-a.s. }
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 34 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$, there exist $C,c>0$ such that for any $T>0$, distinct $v,v',w\in \widetilde{\mathbb{Z}}^d$ with $|v-w|\ge d$, and event $\mathsf{A}$ measurable with respect to $\mathcal{C}_{v'}$,  	\begin{equation}
		\mathbb{P}\big( \widehat{\mathcal{L}}^{v}_{1/2} \ge T \mid \big\{ v\xleftrightarrow{} w \Vert \mathsf{A}  \big\}  \big)\le Ce^{-cT}. 
	\end{equation}

