body:
[Theorem th:intro-Einaiiagapi of arXiv:2412.09290, 'Asymptotics of Harish-Chandra transform and infinitesimal freeness'] (Theorem (Einaiiagapi of the paper))
  Let $A$ be a random Hermitian matrix of size $N$. Assume that for every finite $r$ one has
  \begin{equation}
    \lim_{N \rightarrow \infty} N \left( \frac{1}{N} \log \mathbb{E}[H \text{}
    C (x_1, \ldots, x_r, 0^{N - r} ; \lambda_1 (A), \ldots, \lambda_N (A))] -
    \sum_{i = 1}^r \Psi (x_i) \right) = \sum_{i = 1}^r \Phi (x_i), 
  \end{equation}
  where $\Psi, \Phi$ are smooth functions in a (complex) neighborhood of $0$ and the
  above convergence is uniform in a (complex) neighborhood of $0^r$. Then one has the following     limit:
  \begin{equation}
    \lim_{N \rightarrow \infty} N \left( \frac{1}{N^{k + 1}} \mathbb{E} \left[
    \sum_{i = 1}^N \lambda_i^k (A) \right] -\ensuremath{\boldsymbol{\mu}}_k \right)
    =\ensuremath{\boldsymbol{\mu}}'_k, 
  \end{equation}
  where 
  \begin{equation}
    \ensuremath{\boldsymbol{\mu}}_n = \sum_{m = 0}^{n - 1} \frac{n!}{m! (m + 1) ! (n - m) !}
    \frac{\mathrm{d}^m}{\mathrm{d} x^m} ((\Psi' (x))^{n - m}) {\mbox{\rotatebox[origin=c]{-90}{${-\!\!-}$}}}_{x =
    0}, 
  \end{equation}
  \begin{equation}
    \ensuremath{\boldsymbol{\mu}}'_k := \sum_{m = 0}^{k - 1} \frac{k!}{m! (m + 1) !
    (k - m - 1) !}  \left. \frac{\mathrm{d}^m}{\mathrm{d} x^m} ((\Psi' (x))^{k - m
    - 1} \Phi' (x)) \right|_{x = 0} . 
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary eq:block-cap-coordinate-lower of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[corollary]{cor:block-growing-cutoff-separation}
Retain the notation of (thm:mesoscopic-block-lower of the paper).  Every
\(x\in\mathcal K_{N,t}\) satisfies
\begin{equation}
 \left\lVertx\right\rVert_\infty\ge\frac{t}{\sqrt{k_N}}
 =\left(\frac{t}{\sqrt c}+o(1)\right)N^{-1/(2p)}.
\end{equation}
Consequently, if a point cutoff \(D_{N,r_N}\) from
(thm:growing-point-cutoff of the paper) intersects \(\mathcal K_{N,t}\), then
\begin{equation}
 q_N^{\rm gr}=\sqrt N\,r_N^{p-1}
 \ge
 \left(t^{p-1}c^{-(p-1)/2}+o(1)\right)N^{1/(2p)}.
\end{equation}
In particular, every growing cutoff for which
\(q_N^{\rm gr}=O(1)\), and hence every cutoff in the pressure-universal
regime \(q_N^{\rm gr}\to0\), is eventually disjoint from the entire cap
\(\mathcal K_{N,t}\) that creates the coherent-block critical point.

[Lemma 58 (Compact-scale tail) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] If
\[
 R_{r+1}^2
 =\sup_n\sum_q\omega_q^{(r+1)}E_{n,q}<\infty,
\]
then
\begin{equation}
 \sup_n\sum_{q>Q}\omega_q^{(r)}E_{n,q}
 \le R_{r+1}^2\rho_r(Q)\longrightarrow0.

\end{equation}

[Lemma 12 of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] For $n\ge1$,~$t>0$ and~$\lambda>0$, denote
\begin{equation}

\Gamma(\lambda):=\bigl\{x\in\BbbL_n\colon \sqrt{L_t(x)}\ge m_n-\lambda\bigr\}.
\end{equation}
Then for all~$\lambda>0$,
\begin{equation}

\lim_{k\to\infty}\,\limsup_{n\to\infty}\,P^\varrho\Bigl(\exists x,y\in\Gamma(\lambda)\colon y\in B_{n-k}(x)\smallsetminus B_k(x)\Bigr) = 0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm domination2 of arXiv:2411.13926, 'Random walks on random walks:\\ non-perturbative results in high dimensions'] Let $\gamma \in \Gamma_{-\infty}$, $A \in \ensuremath{\mathcal{A}}(\gamma)$ and $\lambda>0$. Then it holds that, in law, 
\begin{equation}
\ensuremath{\mathbb{Q}}_A= \ensuremath{\mathbb{Q}}_{\gamma^c} \bigoplus  \ensuremath{\mathcal{L}} (\sum_{i\in \ensuremath{\mathcal{Z}}} \delta_{Z^{(i)}}),
\end{equation}
  where $ \ensuremath{\mathcal{L}} (\sum_{i\in \ensuremath{\mathcal{Z}}} \delta_{Z^{(i)}})$ is the law of $\sum_{i\in \ensuremath{\mathcal{Z}}} \delta_{Z^{(i)}}$ and the $Z^{(i)}$'s are random walk paths in $S$ that intersects $\gamma$ having the following properties, depending on an auxiliary random variable $\mathbf{y}$:
\begin{enumerate}
\item  random walk paths:
\begin{enumerate}
   \item The $Z^{(i)}$'s have the conditional law $P^{RW}(\;\cdot \;|\; D_i)$, where the random event $D_i $  
 only concerns the behaviour of $Z^{(i)}$ in the time interval $[-|\gamma|,-1]$.   
    \item We associate an anchor point $z_i \in \{-|\gamma|,...,-1\}$ to each $Z^{(i)}$.
          This point in particular satisfies $Z^{(i)}_{z_i} = \gamma_{z_i}$, and is a function of $\mathbf{y}$.
    \item 
    $D_i$ satisfies $\{Z^{(i)}_{z_i}=\gamma_{z_i}\}\cap\{ Z^{(i)}_s \neq \gamma_s, z_i<s\leq -1 \} \subset D_i \subset \{Z^{(i)}_{z_i}=\gamma_{z_i}\}$ and is a deterministic function of $\mathbf{y}$.
\end{enumerate}

\item  independence and conditional independence:
\begin{enumerate}
      \item conditioned on $\mathbf{y}$ the $Z^{(i)}$'s are independent.
      \item $\eta^{\gamma^c}$ and $(\mathbf{y}, \ensuremath{\mathcal{Z}}, Z^{(i)}, 1\leq i\leq \ensuremath{\mathcal{Z}})$ are independent.
\end{enumerate}

\item  stochastic domination:

\begin{enumerate}
\item There is an $n=n(\lambda) \in \ensuremath{\mathbb{N}}$ such that $|\ensuremath{\mathcal{Z}}_s| \preceq Poi(\lambda)+n$, where $\ensuremath{\mathcal{Z}}_s := \{ i : z_i = s \}$, $s\in \{-|\gamma|,\dots,-1\}$.
\item The vector $(|\ensuremath{\mathcal{Z}}_s|)_{s=-|\gamma|,\dots,-1}$ is stochastically dominated by a vector of independent $Poi(\lambda)+n$-distributed random variables.
\end{enumerate}

\item   random walk bounds when $d\geq 3$:
\begin{enumerate}
      \item there is $\delta>0$ not depending on $\gamma$ nor $A$ such that $P^{RW}(D_i)>\delta$.
\item there exists a constant $C<\infty$, not depending on $\lambda, \gamma$ nor $A$, so that 
\begin{equation} 
\ensuremath{\mathbb{Q}}_A(Z^{i}_t = x \;|\; \mathbf{y}, z_i) \leq C(t-z_i)^{-\frac d2 }.
\end{equation}
\end{enumerate}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem convexbifurcation of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] After some arbitrarily $C^\infty$-small perturbation of $\xi$, there exists finitely many times $0 < t_1 < \dots < t_N < 1$ such that 
    \begin{itemize}
        \item If $t \neq t_i$, then $S_t$ is $\xi$-convex ,
        \item At $t=t_i$, a pair of parallel closed characteristics of $\xi|_{S_t}$ is born or dies.
    \end{itemize}
    Moreover, when a pair of characteristics is born (in forwards time), a $\flat$ annulus appears between them, and when a pair of characteristics dies, a $\sharp$ annulus disappears between them (see \zcref{fig:birthdeath}). (Proof in the paper; no proof environment follows the statement in the TeX.)

