body:
[Lem 16 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Assume Hypothesis \ref{hypnonlin}. Then, there exists some $\delta_1 \in (0, \;1]$ and some bounded function $g: \mathbb{N} \mapsto \mathbb{R}$, such that
	\begin{align} 
	\forall \alpha,\beta \in S, \; \forall n \in \mathbb{N}_+, \; \forall	0 \leq s \leq t \leq T, \quad	\mathbb{E}_{\nu_{\rho}} \big[ \big\{ \mcb{B}_t^{n, \alpha , \beta}(H) - \mcb{B}_s^{n, \alpha , \beta}(H) \big\}^{2} \big] \leq  C(t-s)^{1 + \delta_1} g(n). 		
	\end{align}
	In the last line, $C$ is some constant independent of $n$, $s$ and $t$. Furthermore, if $H \in C_c^{2}(\mathbb{R})$, then the role of $C$ in \eqref{ubvarnlintight1} is fulfilled by some constant $C(H)$ satisfying \eqref{Cinvshift}.

[Corollary cor:main_corollary of arXiv:2512.09219, 'Strong confluence of geodesics in Liouville quantum gravity'] Fix a bounded open set $U \subseteq \mathbb{C}$, $\ell>0$ and $\nu>0$. Set $\varepsilon_n = 2^{-n}$ for all $n \in \mathbb{N}$. Fix also $q>0$. Then almost surely, the following holds for all $n$ large enough. For all $\text{\usefont{U}{bboldx}{m}{n}z} \in (\varepsilon_n^{q} \mathbb{Z}^2) \cap U$ and all $w \in U$ satisfying $w\notin \mathcal{B}_{\tau_{16\ell}(\text{\usefont{U}{bboldx}{m}{n}z})}^\bullet(\text{\usefont{U}{bboldx}{m}{n}z})$, and every geodesic $\Gamma_{\text{\usefont{U}{bboldx}{m}{n}z},w}$, there exists $(z,r) \in \mathbb{C} \times [\varepsilon_n^{1+\nu} , \varepsilon_n]$ such that 
\begin{align}

B_{\lambda_4 r}(z) \subseteq \mathcal{B}_{\tau_{2 \ell}(\text{\usefont{U}{bboldx}{m}{n}z})}^{\bullet}(\text{\usefont{U}{bboldx}{m}{n}z}) \setminus \mathcal{B}_{\tau_{\ell}(\text{\usefont{U}{bboldx}{m}{n}z})}^{\bullet}(\text{\usefont{U}{bboldx}{m}{n}z}), \quad  \Gamma_{\text{\usefont{U}{bboldx}{m}{n}z} ,  w} \cap B_{\lambda_2 r}(z) \neq \emptyset \quad \text{and} \quad \mathfrak{C}_r^{\text{\usefont{U}{bboldx}{m}{n}z} ,  w,\Gamma_{\text{\usefont{U}{bboldx}{m}{n}z},w}}(z)\quad  \text{occurs}.
\end{align}

[Definition of arXiv:2608.28505, 'Quagmires and large Suslin forests'] Silver's principle $W_\kappa(\lambda)$ asserts that there exist a $\kappa$-Kurepa tree $T$ with $|T_\kappa| = \lambda$ and a sequence $\langle W_\alpha : \alpha < \kappa\rangle$ such that:
\begin{enumerate}
\item for every $\alpha < \kappa$, $W_\alpha$ is a subset of $\mathcal{P}(T_\alpha)$ of cardinality  $<\kappa$,
\item for every $X \in [T_{\kappa}]^{<\kappa}$, there exists $\alpha < \kappa$ such that $\pi_\beta[X] \in W_\beta$ for every $\beta$ with $\alpha \le \beta < \kappa$.
\end{enumerate}

[Theorem 5 of arXiv:2608.06038, 'Efron type identities\\ for stopping sets and Poisson hulls'] Let $f\colon \bN\times[0,\infty]\times\bar{\N}_0\to\R_+$ be a
  measurable function and $B\in\cX$.  Then
  \begin{align}

    \BE \big[\I\{\eta_Z(\BX)<\infty\}
    f\big(\eta_Z,\lambda_{Z^c}(B),\eta_{Z^c}(B)\big)\big]
    =\sum_{m\in\bar\N_0}\int \frac{t^m}{m!} e^{-t}f(\mu,t,m)
    \,\lambda^*_B(d(\mu,t)).
  \end{align}

