body:
[Corollary coro:1 of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Fix $T\in(0,1]$, and two families of functions $\theta=(\theta_\mu)_{\mu\in(0,T]}$ and $\tilde{R}=(\tilde{R}_\mu)_{\mu\in(0,T]}$ with $\theta_\mu,\tilde{R}_\mu\in C^\infty([0,T],\R^{{\mcb{n}}})$, and which for some universal constant $C_{\theta,\tilde{R}}>1$ satisfy, for every $\mu \in (0,T]$, 
\begin{equs}    {\| \theta_\mu 
    \|}_{L^\infty_{0;T}}\vee
 \mu^{-\delta/2}{\| \tilde{R}_\mu 
    \|}_{L^\infty_{0;T}}
\leqslant C_{\theta,\tilde{R}}\,.
\end{equs} 

Writing 
\begin{equs}
    \tilde{F}_{\eps,\mu}[]\eqdef K_\mu F_{\eps,\mu}[]\,,\quad \Tilde{I}_{\eps,\mu}[]\eqdef K_\mu I_{\eps,\mu}[]\,,\quad {and}\quad u_\mu \eqdef \theta_\mu+{\tt u}\,,
\end{equs}
we clearly have $K_\mu\theta_\mu+{\tt u}=K_\mu\theta_\mu+K_\mu\mathcal{R}_\mu{\tt u}=K_\mu u_\mu$ (since ${\tt u}$ is constant in time, so that $\mathcal{R}_\mu{\tt u}={\tt u}$) along with the estimate
\begin{equs}
    {\| u_\mu 
    \|}_{L^\infty_{0;T}}\leqslant C_{\theta,\tilde R}+|{\tt u}|\,.
\end{equs}

Then, there exists universal constants $K,r\geqslant1$ such that setting $C_F\eqdef K{\talloblong \omega\xi \talloblong}^r_{4}$ we have, for every $\eta>0$, 
    \begin{equs}
        {\|  \tilde{F}_{\eps,\mu}[K_\mu\theta_\mu] 
    \|}_{L^\infty_{0;T}}&\leqslant C_F\mathcal{G}_{\tt u}(C_{\theta,\tilde{R}})\mu^{-1+H-\eta}\,,\\
         \norm{ \mathrm{D}\tilde{F}_{\eps,\mu}[K_\mu\theta_\mu,\mathcal{R}_\mu\dot G_\mu \tilde{R}_{\mu}]}_{L_{0;T}^\infty}&\leqslant C_F\mathcal{G}_{\tt u}(C_{\theta,\tilde{R}})\mu^{-1+H-\eta}\,,\\
          {\| \Tilde{I}_{\eps,\mu}[K_\mu\theta_\mu] 
    \|}_{L_{0;T}^\infty}&\leqslant C_F\mathcal{G}_{\tt u}(C_{\theta,\tilde{R}})\mu^{-1+\delta-\eta}\,.
    \end{equs}

[Lemma 32 of arXiv:2605.30030, 'Critical exponents for planar random-cluster model with cluster-weight~$q=4$'] There exists a coupling~$\bbP$ between~$\rcP$ and~$\rcP[\,\cdot\,|\,L(1)]$ via a decision tree and a stopping time~$\tau$ such that, 
when~$\tau<\infty$, 
\begin{itemize}
	\item~$\calF_\tau = \delta \Z^2 \setminus e_{[\tau]}$ is a well-separated outer flower domain on~$\Lambda_{4|y|}$
	and compatible boundary conditions $(\xi,\xi')$ satisfy~$\xi < \xi'$; 
	\item the law of~$\omega$ on~$\calF_\tau$ conditionally on~$\omega_{[\tau]}$ is~$\rcP_{\calF_\tau}^{\xi}$;
	\item the law of~$\omega'$ on~$\calF_\tau$ conditionally on~$\omega'_{[\tau]}$ stochastically dominates~$\rcP_{\calF_\tau}^{\xi'}$.
\end{itemize}
Moreover,~$\bbP[\tau < \infty] \ges 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 7 of arXiv:2604.13454, 'Invariant and periodic measures in classical spin systems on infinite lattices with highly'] Given a probability measure $\mu$ on $\ell_\rho^{2\theta}(\mathbb{Z}^+)$, the following statements are equivalent:
       \begin{itemize}
           \item[(i)] Uniqueness holds for solutions of the martingale problem associated to (\ref{INFSDE2}) with initial law $\mu$;
           \item[(ii)] Equation (\ref{INFSDE2}) with initial condition $\mu$ admits a weak martingale solution which is unique in the sense of probability law.
       \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] When the function $g$, defined in \eqref{g_defn}, is \emph{H\"{o}lder continuous} with constant $L$ and exponent $\alpha$ for some $0<\alpha\leqslant 1$, i.e.\ 
\begin{equation}
\left|g(x_{1},y_{1})-g(x_{2},y_{2})\right|\leqslant L\left|\left|(x_{1},y_{1})-(x_{2},y_{2})\right|\right|_{2}^{\alpha} \quad \text{for all } (x_{1},y_{1}), (x_{2},y_{2})\in\mathcal{S},
\end{equation} 
we have, for $H_{n}$ as defined in \eqref{H_{n}_defn}, $E_{n}$ as defined in \eqref{E_{n}_defn} and $\mathcal{S}_{n}$ as defined in \eqref{S_{n}_defn}, for each $n\geqslant N$:
\begin{align}
{}&\sup\left\{\left|H_{n}(x,y)-g(x,y)\right|:(x,y)\in\mathcal{S}\right\}\leqslant 2^{-\alpha/2}L\E\left[K_{n}^{-\alpha/2}\right]}\\
{}&\sup\left\{\left|E_{n}\left(\frac{r_{1}}{n},\frac{r_{2}}{n}\right)-g\left(\frac{r_{1}}{n},\frac{r_{2}}{n}\right)\right|:\left(\frac{r_{1}}{n},\frac{r_{2}}{n}\right)\in \mathcal{S}_{n}\right\}\leqslant 2^{-\alpha/2}L\E\left[K_{n}^{-\alpha/2}\right]}
\end{align}

[Proposition 12 (Local Jacobi energy) of arXiv:2609.03958, '2609.03958'] Let $n\geq 2$, $K\geq 0$, $u\in C^4(B_{10})$ and $f\in C^2(B_{10})$ with $D^2u\geq -KI$ and $\inf_{B_{10}}f >0$. Assume that  $M=\{(x,u(x)):x\in B_{10}\}\subset\R^{n+1}$ is a smooth 2-convex graph satisfying the scalar curvature equation \eqref{eq:intro-main}. If $\eta\in C_c^1(B_2)$ and $0\leq\eta\leq1$, then there exists some constant  $C>0$ depending only on $n$, $K$, $\inf_{B_{10}}f$, $\sup_{B_{10}}f$, $\|Df\|_{L^{\infty}(B_{10})}$, $\|Du\|_{L^{\infty}(B_{2})}$ and $\|D\eta\|_{L^{\infty}(B_{2})}$ such that
\begin{equation}
 \int_{M}\eta^2F_{ij}b_ib_j\,d\mu
 \leq C,
\end{equation}
where $b$ comes from Proposition \ref{prop:strong-jacobi}.

[Proposition prop:diffusion-coldstart of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Fix $K>0$, $d\ge1$, and $\gamma>0$, and let $H\in\mathbb R^{d\times d}$ be
symmetric with smallest eigenvalue $K$.
\begin{enumerate}
\item[\rm(i)] The eigenvalues of $A$ are the roots of
$\mu^2+\gamma\mu+\lambda=0$ as $\lambda$ ranges over the eigenvalues
of $H$, and
$\alpha(\gamma,H)\ge-\sqrt K$, with equality if and only if
$\gamma=2\sqrt K$.
\item[\rm(ii)] The measure $\mu_H$ is the unique invariant law of
$(P_t)_{t\ge0}$. For every initial state $z\in\mathbb R^{2d}$,
\begin{equation}
 \limsup_{t\to\infty}
 \lVert \delta_zP_t-\mu_H\rVert_{\mathrm{TV}}^{1/t}
 \le e^{\alpha(\gamma,H)},
\end{equation}
and the limit exists and equals $e^{\alpha(\gamma,H)}$ for a
suitable $z$. Moreover, there are initial states
$y,\widetilde y\in\mathbb R^{2d}$ such that
\begin{equation}
 \lim_{t\to\infty}
 \norm{\delta_yP_t-\delta_{\widetilde y}P_t}_{\mathrm{TV}}^{1/t}
 =e^{\alpha(\gamma,H)}
 \ \ge\ e^{-\sqrt K}.
\end{equation}
\item[\rm(iii)] There are an initial state $z\in\mathbb R^{2d}$ and a
constant $c>0$ such that, for every $\varepsilon\in(0,c/4]$,
\begin{equation*}
 t_{\mathrm{mix}}\bigl(z,\varepsilon;(P_t)_{t\ge0},\mu_H\bigr)
 \ \ge\ \frac{1}{\sqrt K}\,\log\frac{c}{4\varepsilon},
\end{equation*}
where the mixing time is defined as in
Section~(sec:notation of the paper), with $t\in[0,\infty)$ in place of $n$.
\end{enumerate}

