body:
[Definition 1 (Centered-admissible exponents) of arXiv:2606.16662, '2606.16662'] Given a mixed triple \((i;j,k)\) and \(\eps>0\), a pair \((s,\sigma)\) is \((i;j,k,\eps)\)-centered admissible if
\begin{equation}
        \Gamma_{i;j,k}>\frac d2+10\eps,
        \qquad
        s<\lambda_i+\Gamma_{i;j,k}-d-10\eps,
        \qquad
        \max\{0,d-\Gamma_{i;j,k}\}+10\eps
        <\sigma<\lambda_i+\Gamma_{i;j,k}-d-10\eps .
\end{equation}
The underlying zero-loss \(\sigma\)-interval is non-empty precisely when
\begin{equation}
        \max\{0,d-\Gamma_{i;j,k}\}<\lambda_i+\Gamma_{i;j,k}-d.
\end{equation}
For the \(\eps\)-window in \eqref{eq:centered-window}, the gap between
the two endpoints is required to exceed \(20\eps\); throughout the paper
\(\eps\) is chosen below the available strict margin.  In the singular subrange \(\Gamma_{i;j,k}\le d\), this is the stochastic summability condition
\begin{equation}
        2\Gamma_{i;j,k}+\lambda_i>2d.
\end{equation}
The first condition in \eqref{eq:centered-window} is the finite random-matrix summability requirement coming from the high-loop factor \(N^{d/2-\Gamma_{i;j,k}}\).  In the equal-gain case it is \(3\alpha>d/2\), which is weaker than the non-empty singular-window condition \(\alpha>2d/7\).  The gap comes from the operator summation after insertion of the low input.  The \(Q^{d/2}\)-branch forces the lower bound on \(\sigma\), while the \(M^{d/2}\)-branch forces the upper bound; the two inequalities overlap in the singular range exactly when \(2\Gamma+\lambda>2d\).

[Definition 158 of arXiv:2601.16377, '2601.16377'] Let $h \in [H]$ and $k \in \llbracket k^-(h),k^+(h) \rrbracket$. We introduce
\begin{equation*}
\begin{split}
& \mathfrak{a}_k = \hat{a}_k(\textnormal{\textsf{\textbf{Gau\ss{}}}}_{\amsmathbb{Z}}),\qquad \mathfrak{a}_k' = \mathfrak{a}_k  + \frac{\theta_{h,h} - \frac{1}{2}}{\N} \\
& \mathfrak{b}_k = \hat{b}_k(\textnormal{\textsf{\textbf{Gau\ss{}}}}_{\amsmathbb{Z}}),\qquad \mathfrak{b}_k' = \mathfrak{b}_k - \frac{\theta_{h,h} - \frac{1}{2}}{\N}
\end{split}
\end{equation*}
If $f$ is a continuous function defined in a neighborhood of the $h$-th segment $[\hat{a}_h,\hat{b}_h]$, we set
\begin{equation}

\begin{split}
\mathsf{Shift}_h[f] & = \sum_{l = 1}^{K} (\textnormal{\textsf{Gau\ss{}}}_{\amsmathbb{Z},l} - Q_l^{\boldsymbol{\mu}}) \int_{\hat{a}_h'}^{\hat{b}'_h} f(x) \big(\partial_{\hat{p}_l} \mu_h^{\hat{\boldsymbol{p}}}(x)\big)\big|_{\hat{\boldsymbol{p}} = \frac{\boldsymbol{Q}^{\boldsymbol{\mu}}}{\N}}\,\dd x \\
& \quad + \frac{\theta_{h,h} - 1}{2\theta_{h,h}}\bigg[\mathbbm{1}_{\amsmathbb{S}_h}(\hat{a}_h')\big(f(\mathfrak{a}_{k^-(h)}') - f(\hat{a}_{h}')\big)  + \sum_{k = k^-(h)}^{k^+(h) - 1} \mathbbm{1}_{\amsmathbb{S}_h}(\beta_k) \big(f(\mathfrak{b}_k') + f(\mathfrak{a}'_{k + 1})\big)  \\
& \quad\qquad \qquad\qquad + \mathbbm{1}_{\amsmathbb{S}_h}(\hat{b}'_h) \big(f(\mathfrak{b}_{k^+(h)}') - f(\hat{b}'_h)\big)\bigg]
\end{split}
\end{equation}
As in \eqref{eq_x258}, the indicator functions indicate respectively that $[\hat{a}_h',\alpha_{k^+(h)}]$, $[\beta_{k},\alpha_{k + 1}]$ and $[\beta_{k^+(h)},\hat{b}_h']$ are saturations.  The equilibrium measure $\boldsymbol{\mu}^{\hat{\boldsymbol{p}}}$ is the one already encountered in Section~\ref{Sec:gausdssat}.

[Theorem 2 (Wendel's formula) of arXiv:2608.16752, 'Absorption Probabilities for Random Convex Hulls: Distribution-Freeness via the Wall-Cross'] Let $d\geq 1$ and $n\geq d+1$.  Let  $\xi_1,\dots, \xi_n$ be (possibly dependent) random vectors in $\R^d$ such that the following conditions hold:
\begin{itemize}
\item[(i)] \emph{Sign-flip invariance}:  For every vector of signs $(\eps_1,\dots, \eps_n)\in \{+1,-1\}^n$, we have the distributional equality
$$
(\eps_1 \xi_1,\dots, \eps_n \xi_n)
\stackrel{d}{=} (\xi_1,\dots, \xi_n).
$$
\item[(ii)] \emph{General position}:  For every $1\leq i_1 < \dots < i_d\leq n$, the probability that the vectors $\xi_{i_1}, \dots,\xi_{i_d}$ are linearly dependent is $0$.
\end{itemize}
Then
\begin{align}
    \pwend{n}{d}
    &:=
    \pr[0\in \Conv(\xi_1,\dots, \xi_n)]
    =
    \frac{1}{2^{n-1}}
    \sum_{j=d}^{n-1}
    \binom{n-1}{j},

    \\
    \qwend{n}{d}
    &:=
    \pr[0\notin \Conv(\xi_1,\dots, \xi_n)]
    =
    \frac{1}{2^{n-1}}
    \sum_{j=0}^{d-1}
    \binom{n-1}{j}.

\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop wtapprox of arXiv:2608.06500, 'Free energy of Ising models under a spectral condition'] For all $A,\varepsilon>0$, there exists a polynomial
    $P\in\mathbb{R}[h,\varphi]$ such that

    \begin{align*}
\sup_{(h,\varphi)\in[-C,C]\times\mathbb{R}} e^{-A\varphi^2}
|V_h'(\varphi)-P(h,\varphi)| < \varepsilon\, .
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 22 (Sphere rigidity) of arXiv:2609.01882, '\textbf{Coxeter Descents and Parabolic Homotopy Colimits}\\[2mm] \large A Hochster-type de'] Let $G$ be compact, connected, simply connected, and simple, with irreducible Weyl system $(W,S)$ of rank at least two. Let $\mathcal K$ be a proper simplicial complex with vertex set exactly $S$. The following are equivalent:
\begin{enumerate}[label=(\roman*)]
  \item $\XK(G)$ is an integral homology sphere;
  \item $\XK(G)$ is homotopy equivalent to a sphere;
  \item $\mathcal K=\partial\Delta^S$.
\end{enumerate}
For (iii), the space is in fact the unit adjoint sphere.

[Lemma lem:prelimit-limiting-r-mass-budgets-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] There exists a constant \(C_r<\infty\) such that, for all \(0\le k\le \ell\),
\begin{equation}
\mathbb{E}\left[
\sum_{J\in\mathcal D_k^\circ}
\widetilde\nu_\ell(J)^r
\right]
\le
C_r2^{-r(s+\delta)k}.
\end{equation}
Moreover, for all \(k\ge0\),
\begin{equation}
\mathbb{E}\left[
\sum_{J\in\mathcal D_k^\circ}
\widetilde\nu(J)^r
\right]
\le
C_r2^{-r(s+\delta)k}.
\end{equation}

