[Prop 24 of arXiv:2609.02261, 'Quantization and process'] For all symbols $F\in {\cal S}(\R^{2n})$,

  \begin{align} 
  <( {\rm Op }_h^{\rm Weyl}  F) \Psi _{X h}, 
 \Psi _{X h}> &=  (\pi  h) ^{-n} \int _{\R^{2n}} 
 e^{ - \frac {1} {h} |X-T|^2 } F(T) dT \\[3mm]
 & = (F \star \nu_h^{\rm Weyl} ) (X), 
 \end{align}

where $ \nu_h^{\rm Weyl}$ denotes the measure defined in (\ref{mesure-Weyl}), that is,

   $$ d \nu_h^{\rm Weyl} (X) =  ( \pi h) ^{-n}
  e^{ - \frac {1} {h} |X|^2 } dX. $$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 216 of arXiv:2601.16377, '2601.16377'] The fundamental solution $\boldsymbol{\mathcal{F}}(z_1,z_2)$ has the following properties.
\begin{enumerate}
\item[(F1)] Writing $\{i,j\} = \{1,2\}$, it is tame with exponent $1$ with respect to $z_i$, uniformly so for $z_j$ in any compact subset of ${\amsmathbb{C}} \setminus [\alpha_{h_j},\beta_{h_j}]$.
\item[(F2)] It is a solution of the master Riemann--Hilbert problem with respect to both its variables. Namely, for any $h_1,h_2 \in [H]$, $z_i \in \amsmathbb{C} \setminus [\alpha_{h_i},\beta_{h_i}]$ and $x_i \in (\alpha_{h_i},\beta_{h_i})$ we have
\begin{equation*}
\begin{split}
\theta_{h_1,h_2}\big(\mathcal{F}_{h_1,h_2}(x_1^+,z_2) + \mathcal{F}_{h_1,h_2}(x_1^-,z_2)\big) + \sum_{g_1 \neq h_1} 2\theta_{h_1,g_1} \mathcal{F}_{g_1,h_2}(x_1,z_2) & = - \frac{\delta_{h_1,h_2}}{(x_1 - z_2)^2}, \\
\theta_{h_1,h_2}\big(\mathcal{F}_{h_1,h_2}(z_1,x_2^+) + \mathcal{F}_{h_1,h_2}(z_1,x_2^-)\big) + \sum_{g_2 \neq h_2} 2\theta_{h_2,g_2} \mathcal{F}_{h_1,g_2}(z_1,x_2) & = - \frac{1}{(z_1 - x_2)^2} .
\end{split}
\end{equation*}
Writing $\{i,j\} = \{1,2\}$, the limit indicated by $x_i^{\pm}$ is uniform with respect to $z_j$ in any compact of ${\amsmathbb{C}} \setminus [\alpha_{h_j},\beta_{h_j}]$, and a continuous function of $x_i$. Note that the source function in both cases is $D_{h_1,h_2}(z_1,z_2) = -\frac{\delta_{h_1,h_2}}{(z_1 - z_2)^2}$. \item[(F3)] It has a joint tameness property, namely there exists a constant $M > 0$ such that, for any $z_1 \in {\amsmathbb{C}} \setminus [\alpha_{h_1},\beta_{h_1}]$ and $z_2 \in {\amsmathbb{C}} \setminus [\alpha_{h_2},\beta_{h_2}]$
\[
\big|(z_1 - z_2)^{2\delta_{h_1,h_2}}\sigma_{h_1}(z_1)\sigma_{h_2}(z_2)\mathcal{F}_{h_1,h_2}(z_1,z_2)\big| \leq M
\]
\item[(F4)] For each $\varepsilon_i \in \{\pm 1\}$ and $x_i \in (\alpha_{h_i},\beta_{h_i})$ with $i = 1,2$, the joint boundary values
\[
\lim_{(t_1,t_2) \rightarrow (0^+,0^+)} \bigg(\mathcal{F}_{h_1,h_2}( x_1 + \ii \varepsilon_1 t_1,\,x_2 + \ii \varepsilon_2 t_2) + \frac{\delta_{h_1,h_2}\delta_{\varepsilon_1 + \varepsilon_2,0}}{( x_1 + \ii \varepsilon_1 t_1 - x_2 - \ii \varepsilon_2 t_2)^2}\bigg)
\]
exist uniformly for $x_i$ in any compact subset of $(\alpha_{h_i},\beta_{h_i})$, and are continuous functions of $x_1,x_2$.
\item[(F5)] for any $h, h_i \in [H]$ and $z_i \in \amsmathbb{C} \setminus [\alpha_{h_i},\beta_{h_i}]$ with $i = 1,2$, we have
\begin{equation}

\oint_{\gamma_{h}} \mathcal{F}_{h_1,h_2}({z}_1,z_2)\dd z_1 = \oint_{\gamma_{h}} \mathcal{F}_{h_1,h_2}(z_1,{z}_2)\dd z_2 = 0.
\end{equation}
\item[(F6)] $\mathcal{F}_{h_1,h_2}(z_1^*,z_2^*) = \big(\mathcal{F}_{h_1,h_2}(z_1,z_2)\big)^*$.
\end{enumerate}

