[Lemma E[deg-edges]_asymp of arXiv:2604.05921, 'Simplicity of random hypergraphs'] If $\forall e \in E: \delta_e = \delta\in O(1)$ and
\begin{enumerate}
    \item $\mathds{E}[d_U^{\delta}] \in o(n)$
    \item $\exists c>0: \lim_{n \rightarrow \infty} \mathds{P}(d_U \geq 1) \geq c$
\end{enumerate}
then 
\begin{align*}
    \mathds{E}[DH_n] =  \frac{\delta-1}{\delta} \frac{\delta \mathds{E}[d_U^2] - 2 \mathds{E}[d_U]}{2 \mathds{E}[d_U]} (1+o(1)).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2506.18834, '\large\bf On the random-time and finite-time ruin probability for widely dependent claim s'] (1) Under the assumptions of Theorem \ref{thm104} but without requiring conditions (\ref{110}) and $G\in\mathcal{C}$, we have

\begin{eqnarray}
\lim\inf_{t>0}\psi(x;t)E^{-1}N(t)\overline{G}^{-1}(x+ct)\ge1.
\end{eqnarray}

(2) Under the assumptions of Theorem \ref{thm105} but without requiring conditions (\ref{110}) and $G\in\mathcal{C}$,
(\ref{32010}) still holds. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:moment-identities of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] Let $A=(a_i)$ and $B=(b_i)$ be the spoke and rim labels of a geodesic Leech labeling. Then
\begin{equation}
  (m-2)\sum_i a_i+3\sum_i b_i=\frac{N(N+1)}2,
\end{equation}
\begin{equation}
  \sum_{t\in T(A)}t=3\sum_i b_i,
\end{equation}
and
\begin{equation}
\begin{aligned}
  \frac{N(N+1)(2N+1)}6
  ={}&\left(\sum_i a_i\right)^2
  +(m-3)\sum_i a_i^2
  -2\sum_i a_i a_{i+1}\\
  &+3\sum_i b_i^2
  +2\sum_i b_i b_{i+1}
\end{aligned}
\end{equation}
hold. In particular,
\[
  \sum_{t\in T(A)}t\equiv0\pmod3.
\]

[Lemma 10 of arXiv:2604.17973, 'Schauder estimates and classical solutions of the Dirichlet problem for stochastic parabol'] Let $\alpha\in(0,1)$, let $h\in C^{1+\alpha/2}([0,T];L_\omega^\gamma)$ satisfy
\[
h(0)=0,
\qquad
h'(0)=0,
\]
and let $v$ be the solution of
\begin{equation}
\partial_t v(t,y)=\partial_y^2 v(t,y),
\qquad
v(0,y)=0,
\qquad
v(t,0)=h(t).
\end{equation}
Then
\begin{equation}
|\partial_t v|_{(\alpha,\alpha/2);[0,T]\times\R_+}^{L_\omega^\gamma}
+|\partial_y^2 v|_{(\alpha,\alpha/2);[0,T]\times\R_+}^{L_\omega^\gamma}
\le C\,[h']_{\alpha/2;[0,T]}^{L_\omega^\gamma},
\end{equation}
where $C=C(\alpha,\gamma,T)$. 

Moreover, if $v_1$ and $v_2$ correspond to boundary data $h_1$ and $h_2$, respectively, and if $h_1'(0)=h_2'(0)=0$, then
\begin{equation}
\sup_{(t,y)\in[0,T]\times\R_+}
\E\bigl|\partial_y^2 v_1(t,y)-\partial_y^2 v_2(t,y)\bigr|^\gamma
\le C\sup_{t\in[0,T]}\E\bigl|h_1'(t)-h_2'(t)\bigr|^\gamma.
\end{equation}

[Dfn 3. dfn: resistance metrics of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] [{Resistance metric, [Kigami_01_Analysis]}]

  A metric $R$ on a non-empty set $F$ is called a \textit{resistance metric}
  if and only if,
  for any non-empty finite subset $V \subseteq F$,
  there exists an electrical network $G$ with the vertex set $V$ 
  such that the effective resistance on $G$ coincides with $R|_{V \times V}$.

[Proposition 13 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] Suppose that $u:\Z^d\to \R$ and $f:\Z^d\to \R^d$ are related on $\Z^d$ via
\begin{equation}
-\nabla^*\cdot A\nabla u=\nabla^*\cdot f.
\end{equation}
There exists $\beta>1$ depending only on $\Lambda$ such that for any $p\in[1,\beta]$ and any ball $B$, we have almost surely
\begin{equation}
\fint_{x\in B}\Big(\fint_{B_{\di}(x)}A\nabla u\cdot\nabla u\Big)^{p}\,\lesssim \,\fint_{x\in 2B}\Big(\fint_{B_{\di}(x)}A^{-1} f\cdot f\Big)^{p}+\Big(\fint_{x\in 2B}\fint_{B_{\di}(x)}A\nabla u\cdot\nabla u \Big)^{p}.
\end{equation}
Furthermore, the following elliptic regularity estimates hold:
\begin{enumerate}
\item
(Global quenched Meyers' estimates) For $p\in[1,\beta]$,
\begin{equation}
\int_{x\in \ZZ^d}\Big(\fint_{B_{\di}(x)}A\nabla u\cdot\nabla u\Big)^{p}\,\lesssim  \,\int_{x\in \ZZ^d}\Big(\fint_{B_{\di}(x)}A^{-1} f\cdot f\Big)^{p}.
\end{equation}
\item
(Large-scale hole-filling estimates) For $\rd(x)\le r\le R$, if $f\equiv0$ in $B_R(x)$, then 
\begin{equation}
\int_{ B_r (x) }A\nabla u\cdot \nabla u\,\lesssim \, \Big(\frac rR\Big)^{\frac d{\beta'}}\int_{B_{R} (x) } A\nabla u\cdot \nabla u.
\end{equation}
Here we recall that $\beta':=\frac\beta{\beta-1}$ is the H\"older conjugate of $\beta$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

