body:
[Theorem 7 (Regulated-base product-form representation) of arXiv:2607.24533, 'Colored Markov-Modulated Brownian Motion for Preemptive Workload Stacks'] {Suppose that Assumptions~\ref{assump:intensity}, \ref{assump:stability}, and~\ref{assump:first-moment} hold for the regulated-base model. Then the model admits a stationary probability law.} On the face
$\Theta_{1,c_2,\dots,c_n}$, the stationary density row vector is
\begin{equation}

\vect{\pi}^{\mathrm R}(\bm{x})
=
\vect{\nu}^{\mathrm R}(x_1)
\prod_{r=1}^{n-1}
\Lop{c_r}{c_{r+1}}(x_{c_{r+1}}),
\qquad x_1>0,
\end{equation}
where $c_1=1$ and $\vect{\nu}^{\mathrm R}$ has the form
\eqref{eq:regulated-base-density}, with the direction of
$\vect g_{\mathrm{reg}}$ fixed by the reflecting boundary condition
\eqref{eq:regulated-base-boundary-g}. Because color $1$ is only one component
of the full stack, $\vect{\nu}^{\mathrm{R}}$ is not normalized to integrate
to $1$ on its own. Its scale is fixed jointly with the excursion mass by the
global normalization below. {Thus, $\vect\nu^{\mathrm R}$ is the density on the base face and an anchor for the full stack, not the marginal stationary density of $X_1$ after higher-color faces have been included.}

With
\begin{align*}
\mathfrak{M}^{\mathrm R}
=
\begin{bmatrix}
\vect{0} & \vect{M}^{(2,3)} & \cdots & \vect{M}^{(2,C)}\\
\vect{0} & \vect{0} & \cdots & \vect{M}^{(3,C)}\\
\vdots & \ddots & \ddots & \vdots\\
\vect{0} & \cdots & \vect{0} & \vect{0}
\end{bmatrix},
\end{align*}
$\vect{m}^{\mathrm R}
=
[\vect{M}^{(1,2)},\dots,\vect{M}^{(1,C)}]$,
$\e^{\mathrm R}$ the column vector obtained by stacking $C-1$
copies of $\e$, and $\I^{\mathrm R}$ the identity matrix of the same dimension
as $\mathfrak M^{\mathrm R}$, the
normalization condition is
\begin{equation}

\int_0^\infty
\vect{\nu}^{\mathrm R}(x)\,\dd x
\left[
\e
+
\vect{m}^{\mathrm R}
(\I^{\mathrm R}-\mathfrak{M}^{\mathrm R})^{-1}
\e^{\mathrm R}
\right]
=
1.
\end{equation}

[Corollary 12 of arXiv:2608.29585, '2608.29585'] If $h_k\in\mathscr D$ for all $k$, then, for $0\le m<r$,
\begin{equation}
 f_r\equiv\sum_{k=0}^{m}p_k(x_r)h_k
 \pmod{p_{m+1}(x_r)\mathscr D}.
\end{equation}
Moreover, for $r>s$,
\begin{equation}
 f_r-f_s\in(x_r-x_s)\mathscr D.
\end{equation}

[Lemma 21 of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] We have
\begin{equation}

\lim_{k\to\infty}\limsup_{n\to\infty} P^\varrho\biggl(\,\bigcup_{x\in\BbbL_n}\Bigl\{\sqrt{L_t(x)}\le\frac12 m_n\Bigr\}\cap \BB_{n,k}(x)\biggr)=0
\end{equation}
and, recalling that $ \overline P^\varrho$ denotes the coupling measure from Lemma~\ref{lemma-4.1}, 
\begin{equation}

\lim_{k\to\infty}\limsup_{n\to\infty} \overline P^\varrho\biggl(\,\bigcup_{x\in\BbbL_n}\bigl\{\tilde h(x)- \tilde h(z)+\sqrt{L_t(z)}<0\bigr\}\cap\BB_{n,k}(x)\biggr)=0,
\end{equation}
where we again invoked the shorthand $z:=\frakm^k(x)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lm:ProbEstimate of arXiv:2608.27828, 'Scaling limit of the 3D abelian Yang--Mills Langevin dynamics'] Let $T>0$, $p \geq 2$, and $0<\kappa<1$ sufficiently small. Then, for any $\tilde\kappa\in (0,\kappa)$,
\begin{align}

 \E\sup_{t\in [0,T]}\|\tilde \Psi^\varepsilon(t)\|^p_{\CC^{-1/2-\kappa}_\varepsilon} & \le C_{p,T}  \;,
 \\

  \E \sup_{t\in [0,T]} \norm{  \varepsilon^{4}\mathop{}\!\mathrm{d}_\varepsilon^* (\mathop{}\!\mathrm{d}_\varepsilon\tilde\Psi^\varepsilon )^3 (t)}^p_{\CC^{-3/2-2\kappa}_\varepsilon}
  & \le C_{p,T} \varepsilon^{p \tilde\kappa} 
\end{align}
where the constant $C_{p,T}>0$ may depend on $p,T,\kappa,\tilde\kappa$, but is independent of $\eps>0$.

