\begin{align}
\mathsf{E}\left[\sup_{t\in[0,T]}|Y^i_t|^2+\int_0^T|Z^i_s|^2ds+|K^{(N)}_T|^2\right]
\leq& C\left(1+\mathsf{E}\left[|\xi|^2\right]+\mathsf{E}\left[\int_0^T|f(t,0,0)|^2dt\right]\right).
\end{align}

