body:
[Lemma rescomY of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] Under the assumptions of Theorem (MixEV of the paper), let $G$ and $G_{{\mathfrak t}}$ denote the resolvents of ${H_{\Lambda}}$ and ${H_{\Lambda}}({\mathfrak t})$, respectively. 
Let $F: \mathbb{R}^n \rightarrow \mathbb{R}$ be a function whose derivatives satisfy the following bound: for any fixed $l\in \mathbb{Z}_+$, there exists a constant $C_l>0$ such that
\begin{equation}
    \begin{aligned}
        \max_{\left\lvert \alpha \right\rvert=1,2,\ldots,l}\max_x\left|F^{(\alpha)}(x)\right|(|x|+1)^{-C_l} \leqslant C_l.
    \end{aligned}
\end{equation}
Denote $\widehat m=\left\langle G \right\rangle$ and $\widehat m_t=\left\langle G_t \right\rangle$ for any $t\in \qa{0,{\mathfrak t}}$. Then, there exists a constant $\sigma_0>0$ such that for any constant $0<\sigma<\sigma_0$, and for any sequences of real numbers $\ha{E_1\left({i}\right)}_{i=1}^n$ and $\ha{E_2\left({t}\right)}_{i=1}^n$ satisfying
\begin{equation}\nonumber
    \begin{aligned}
        \left|E_1\left({i}\right)-E^+\right| \leqslant N^{-2 / 3+\sigma}, \quad\left|E_2\left({i}\right)-E^+\right| \leqslant N^{-2 / 3+\sigma}, \quad {i=1,2,\ldots,n},
    \end{aligned}
\end{equation}
setting $\eta=N^{-2 / 3-\sigma}$, we have
\begin{equation}
    \begin{aligned}
        \Bigg|\mathbb{E} &F\left({DN} \int_{E_1\left({1}\right)}^{E_2\left({1}\right)} \mathrm{~d} y \operatorname{Im} \widehat m(y+\mathrm{i} \eta),\ldots,DN \int_{E_1\left({n}\right)}^{E_2\left({n}\right)} \mathrm{~d} y \operatorname{Im} \widehat m(y+\mathrm{i} \eta)\right)\\
        &-\mathbb{E} F\left(DN \int_{E_1\left({1}\right)}^{E_2\left({1}\right)} \mathrm{~d} y \operatorname{Im} \widehat m_{{\mathfrak t}}(y+\mathrm{i} \eta),\ldots,DN \int_{E_1\left({n}\right)}^{E_2\left({n}\right)} \mathrm{~d} y \operatorname{Im} \widehat m_{{\mathfrak t}}(y+\mathrm{i} \eta)\right)\Bigg| \lesssim N^{-\delta}
    \end{aligned}
\end{equation}
for some small constant $\delta>0$ depending only on $\delta_A,\ \varepsilon_A$, and the constants $C_l$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 8 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let $M$ be a compact connected smooth manifold without boundary, $H$ a Tonelli Hamiltonian on $M$, $\phi\in\SCL(M)$, and $u$ the viscosity solution of \eqref{eq:HJephi pre}. If $x\in\reg(\phi,H)$ and $t\in(0,\tau_{\phi,H}(x)]$ for $\tau_{\phi,H}(x)<+\infty$, or $t\in(0,+\infty)$ for $\tau_{\phi,H}(x)=+\infty$, then there exists a unique $(u,H)$-calibrated curve $\gamma:[0,t]\to M$ with $\gamma(0)=x$, and it is given by
	\begin{align*}
		\gamma(s)=\pi\circ\Phi^s_H(x,D\phi(x)),\qquad \forall s\in[0,t],
	\end{align*}
	where $\pi:T^*M\to M$ is the canonical projection and $\Phi^s_H$ is the Hamiltonian flow of $H$.

[Proposition 15 of arXiv:2604.01978, 'Homogenized Transformers'] Under Assumption \ref{ass:high_order_short}, 
\begin{equation*}
    \|G_{\mu}(x, \cdot)-G_{\nu}(y, \cdot)\|_{L^{2}({\uprho_*})}\leq C\left(W_{2}(\mu,\nu)\,+\, \|x-y\|\right)
    \end{equation*}
for all $(\mu,\nu)\in \cP(\S^{d-1})$ and $(x,y)\in \S^{d-1}$, where 
\begin{equation*}
C=O\left(\upbeta^{2}e^{4\upbeta\|\Bar{\bA}\|}e^{\upbeta^{2}d\sigma_{\bA}^{2}}\right).
\end{equation*}

[Lemma 38 (Hereditary non-ghost property) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] For every fixed $J$, define the internal ultraproduct module
\[
 \mathbb M_{q,\mathcal U}^{[J]}
 =\left\{[m_n]_{\mathcal U}:m_n\in M_{n,q}^{[J]},\
       \sup_n\norm{m_n}<\infty\right\}.
\]
Then
\begin{equation}
 \boxed{\mathbb M_{q,\mathcal U}^{[J]}\subset\cD_q.}

\end{equation}

[Corollary 31 (Homogeneous case) of arXiv:2608.17374, '\textbf{On the Pseudo-Mixing of Kac's Walk}'] For homogeneous $T\in \mathbb{R}^{[n]^d\times [n]^d}$ define
$f_T(X)=\mathrm{Ev}_d(T)(X)$ as in \eqref{eq:eval-map}, and let $T^\sharp$ be the
Frobenius-orthogonal projection of $T$ onto $\mathcal C_d^\perp$. Then
\begin{equation}
\Var(f_T(X)) \;\ge\; n^{-d}\,\|T^\sharp\|_F^2.
\end{equation}

