[Defn 4 (Prior) of arXiv:2605.07050, 'Universality of the fluctuations of the free energy in generalized Sherrington--Kirkpatric'] For a random variable $\bsx = (x_1, \dots, x_N) \in \R^N$ whose distribution is given by a prior $\caX$, we assume that for $i=1, 2, \dots, N$, 
\begin{itemize}
\item The entries $x_i$'s are i.i.d. and the distribution of $\sqrt{N} x_i$ does not depend on $N$.
\item The entries $x_i$'s are symmetric (about $0$) and their variances are normalized so that $\E[x_i^2] = N^{-1}$.
\item for any integer $s>2$, there exists a constant $C^x_s$ such that $\E[|\sqrt{N} x_i|^s] \leq C^x_s$.
\end{itemize}

[Prop multgain1 of arXiv:2608.27939, 'Entropy and domination for quasi-Hitchin representations'] Let $\gamma$ be a closed curve on $S$ with $m$ pairwise-disjoint segments, each having the coarse itinerary (equation eq:strict-pattern of the paper). Let $A, A_0 \in \mathrm{SL}_n(\mathbb{C})$ be the determinant-one lifts of $\rho(\gamma), \rho_0(\gamma)$ respectively. Then we have 
\begin{equation}
    \ell_{\rho}^H(\gamma) \leq \ell_{\rho_0}^H(\gamma) - 2m \ln (\alpha^{-1}) 
\end{equation}
for some $0<\alpha<1$.

[Lemma 15 of arXiv:2607.18104, '2607.18104'] There exist $c,C>0$ such that for all $\delta>0$ and $n\in \N$ with $n\geq \delta^{-2}$, 
\begin{equation}
 \mathsf{G}_{n,\delta} :=   \left\{ \pinpmt_{x,s;y,t} \text{ is } \delta\text{-good for all } (x,s;y,t) \in \SetR \cap \mathcal{D}_{\delta^{1/2}}\right\}  
\end{equation}
satisfies
\begin{equation}
     \P\left(  \mathsf{G}_{n,\delta} \right) \geq 1- C\exp\big(-c\delta^{-1/8}\big) . 
\end{equation}

[Proposition 15 of arXiv:2608.30059, 'Multihomogeneous Measures and Stochastic Polar Representations'] Let \(Z\) and \(W\) be \(E\)-valued random elements. If  
\(\nu_Z \in M_{\chi_\alpha,\sigma}(E)\),  then
\begin{equation}

\nu_W=\nu_Z
\quad\Longleftrightarrow\quad
\E{\Gamma(W)}=\E{\Gamma(Z)}
\quad\text{for every }\Gamma\in\mathcal H_\alpha(E),
\end{equation}
where equality is understood in \([0,\infty]\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma X of arXiv:2607.05418, 'On the Group Randomness of 0-1 Real Sequences from Binary Linear Codes'] Let $i,i_1,i_2,i_3,i_4,j,j_1,j_2,j_3,j_4 \in [1\mathrel{{.}\,{.}}\nobreak p]$ and $t,t_1,t_2,t_3,t_4 \in [1\mathrel{{.}\,{.}}\nobreak n]$. Also for $1 \leq q \leq 4$, denote $S_q:=\{i_q,j_q\}$. Then
        \begin{enumerate}
            \item $\mathbb{E}(X_{ijt},\widetilde{\Omega}_p)=0$;
            \item if $d^\bot \geq 3$, and $t_1 \neq t_2$ or $S_1 \cap S_2=\emptyset$, then $\mathbb{E}(X_{i_1j_1t_1}X_{i_2j_2t_2},\widetilde{\Omega}_p)=0$;
            \item if $d^\bot \geq 2, t_1=t_2, \sharp S_1=\sharp S_2=2$ and $\sharp(S_1 \cap S_2)=1$, then $\mathbb{E}(X_{i_1j_1t_1}X_{i_2j_2t_2},\widetilde{\Omega}_p)=\frac{1}{16}$;
            \item if $d^\bot \geq 5$, then $\mathbb{E}(X_{i_1j_1t_1}X_{i_2j_2t_2}X_{i_3j_3t_3}X_{i_4j_4t_4},\widetilde{\Omega}_p)=0$ unless $t_1,t_2,t_3,t_4$ come in pairs and there is no $q$ such that $S_q \cap S_{q'}=\emptyset$ for all $q' \neq q$.
        \end{enumerate}

