[Proposition lem:zeros:entropyAndMoments of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Suppose $(U, W)$ satisfies Assumption (as:results:fixedPoint of the paper). If $\nu \in \mathcal{S}_\kappa$, then $\nu\in \mathcal{Q}_{\kappa, d}$ and we have
    \begin{equation}

        \int_{\ensuremath{\mathbb{R}}^d} \big| \nabla \log \nu_0(x)\big|^2 \nu_0(x) dx < \infty,
    \end{equation}
    Furthermore, $\nu$ is bounded, continuous, and positive, has moments of all orders, and we have for all $x \in \ensuremath{\mathbb{R}}^d$ that  \begin{equation}
\begin{aligned}
    \nabla \log \nu_0(x) 
    &= - \nabla U(x) - \kappa \mathbb E^{\bar{\nu}}\big[ \nabla W(Y_0 - Y_1) | Y_0 = x\big].
\end{aligned}    

\end{equation}

[Thm cor:mixing-from-other-temp of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] There exists $h_0$ such that for all $\beta'$ and all $h\ge h_0$, if $X_t$ is continuous-time Glauber dynamics run at $\beta>\beta_c$ on $\mathbb{T}_n^2$, initialized from $x_0 \sim \pi_{\beta',h}$, with probability $1-o(1)$, $x_0$ is such that 
\begin{align*}
    \|\mathbb P_{x_0}( X_t\in \cdot ) - \pi_{\mathbb{T}_n^2,\beta}^+ \| \le n^{-10}\,, \qquad \text{for all }t\in [n^{o(1)} ,  e^{\Omega( n)}]\,.
\end{align*}
The analogous infinite-volume statement as in Theorem~(thm:main of the paper) also holds. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 14 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] Suppose that $u$ and $f$ are related via~\eqref{eq.u}. There exist $\kappa, c_M>0$ depending only on $\Lambda$ such that 
\begin{enumerate}
\item
For any $2\le p\le q\le2\beta$, 
\begin{equation}
\Big(\int_{x\in\ZZ^d}\expecb{\big(\fint_{B_{\di}(x)}A\nabla u\cdot \nabla u\big)^{\frac p2}}^\frac qp\Big)^{\frac1{q}} \,\lesssim_{\Lambda}\, 
\left(\int_{x\in\ZZ^d}\expecb{\Big(\fint_{B_{\di}(x)}A^{-1}f\cdot f\Big)^{\frac p2}}^\frac qp\right)^{\frac1{q}}.
\end{equation}
\item
If $\gamma \theta\ge c_M$ and $2-\kappa\le p, q, p(1+\theta)\le 2+\kappa$, then  
\begin{equation}
\Big(\int_{\ZZ^d} \expecb{\big(A\nabla u\cdot\nabla u\big)^{\frac 12p}}^\frac qp \Big)^{\frac1q}  \lesssim_{\Lambda }  {\big(\gamma^{\frac1{d+1} } \Gamma^2\big)}^ {c_M} 
\Big(\int_{\ZZ^d}\expecb{\big(A^{-1} f\cdot f\big)^{\frac12 {p}(1+\theta)}}^\frac {q}{p(1+\theta)}\Big)^{\frac1q}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

