[Proposition prop.CLT_MDeg2 of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] For $d = 1$, let $\lambda = \frac{1}{N}$ and $m$ satisfy 
		\begin{equation}
			1 \ll 3^{76m} \ll \log N,
		\end{equation}
		(e.g. $m=\lfloor\tfrac{1}{100} \log \log N\rfloor$), then the martingale $\widetilde{M}^{N}_t$ defined in (equation eq.defMt_newTilde of the paper) with respect to $\widetilde{G}_\lambda$ defined in (equation eq.TwoscaleExDeg2 of the paper) converges weakly to a Brownian motion of variance $\sigma^2=\tfrac{\chi(\rho)^2}{\pi\mathbf{D}(\rho)}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 6 of arXiv:2609.00743, '$L_p$ Brunn-Minkowski inequality for the eigenvalue of generalized Monge-Ampère equation'] There exists $u\in C^{2,\alpha}(\bar{\Omega})\cap C^\infty(\Omega)$ which is a solution to \eqref{general MA} for $\lambda=\underline{\lambda}_{n+k+1}$, where
    \begin{equation}
    \underline{\lambda}_{n+k+1}=\inf\left\{ \frac{\int_{\Omega} (-u)(u^\star)^k~d\mu_u}{\int_{\Omega}(-u)^{n+k+1}~dx}: u\in C^{1}(\overline{\Omega})~\text{is strictly convex in }
 \Omega,~u\vert_{\partial\Omega}=0\right\}.
    \end{equation}
    Moreover, if $(\lambda',u')$ is another pair of such solution, then $\lambda=\lambda'$ and there exists $c>0$ such that $u=cu'$. (Proof in the paper; no proof environment follows the statement in the TeX.)

Let $(K, \langle \cdot, \cdot \rangle_K)$ and $(\mathcal{H}, \langle \cdot, \cdot \rangle_\mathcal{H})$ be real separable Hilbert spaces. An isonormal Gaussian process $W = \{W(h) : h \in \mathcal{H}\}$ on a complete probability space $(\Omega, \mathcal{F}, \mathbb{P})$ is a family of centered Gaussian random variables such that $\mathbb{E}[W(h_1) W(h_2)] = \langle h_1, h_2 \rangle_\mathcal{H}$. A $K$-valued Wiener functional is a measurable map $F: \Omega \to K$. The space $L^p(\Omega; K)$ consists of strongly measurable $K$-valued random variables $F$ with $\mathbb{E}[\|F\|_K^p] < \infty$.
K and \mathcal{H} are real separable Hilbert spaces
W is an isonormal Gaussian process on \mathcal{H}

[Thm 43 (Explicit upper bounds) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] Let $\sigma, \alpha > 0$ and $d_0 \coloneqq 1 - \log 2$. Then
\begin{align}
    \sigma \vee \alpha \ <\ c^{\SG}(\sigma, \alpha) \ \le\ (\sigma + 2\alpha) \wedge \sigma\,\mathcal{U}(a),

\end{align}
{where $a = \alpha/\sigma$ as in \eqref{eqn:normalize} and}
\begin{align}
    \mathcal{U}(a) \coloneqq \sup_{\ell \ge \log 2} \frac{a\ell + \sqrt{2\ell}}{\ell + d_0},

\end{align}
{a one-variable supremum that Lemma~\ref{lem:sgMeval} evaluates in closed form. Its variable is $\ell = \log(1/p)$, and the constraint $\ell \ge \log 2$ is the range of $\ell$ as the atom weight $p$ runs over $(0,1/2]$.} Consequently
\begin{align}
    \frac{c^{\SG}(\sigma,\alpha)}{\sigma \vee \alpha} \longrightarrow 1
    \qquad \text{as } a \downarrow 0 \text{ and as } a \to \infty.

\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop_1edge of arXiv:2608.07236, 'Negative association of Busemann functions \\in exponential last-passage percolation'] For any coordinate-wise monotone functions $f$ and $g$ that are monotone in the same direction, it holds that 
\begin{equation}
\textup{$\mathbb{C}$ov}\Big(f\big(B^{\rho_k}(\mathcal{B})\big), g\big( (B^{\rho_j}(\mathcal{R}^j_i))_{i,j=1}^{2k} ,(B^{\rho_j}(\mathcal{G}^j_i))_{i,j=1}^{2k}\big) \Big) \leq 0.
\end{equation}
In addition, if we restrict the range of the index $j$, then we have
\begin{equation}
\textup{$\mathbb{C}$ov}\Big(f\big(B^{\rho_k}(\mathcal{B})\big), g\big( (B^{\rho_j}(\mathcal{R}^j_i))_{i=1, \dots, 2k}^{j=1,\dots, k} ,(B^{\rho_j}(\mathcal{G}^j_i))_{i=1 \dots 2k}^{j=k,\dots, 2k}\big) \Big) = 0.
\end{equation}

