[Dfn 35 (Bilateral sub-Gamma class) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] Let $\sigma, \alpha > 0$. A random variable $X$ belongs to the class $\SG(\sigma^2, \alpha)$ if
\begin{align}
    \E\left[e^{\lambda X}\right] \le \exp\left(\frac{\sigma^2\lambda^2}{2\left(1 - \alpha|\lambda|\right)}\right)
    \qquad \text{for all } |\lambda| < \frac{1}{\alpha}.

\end{align}

[Lemma lem:distinct-pair of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] If $L_w(\ell)\ge\tfrac12$, then
\begin{equation}
  s^{\times}(S)
  \le
  \frac{M_w+\binom{\ell}{2}}{2}
  -\frac{L_w(\ell)^2-L_w(\ell)}4.
\end{equation}

[Proposition 5 of arXiv:2608.29713, '\textbf{A Cartan geometry from a correspondence space in Riemannian geometry}'] Let $(M,g)$ be a Riemannian manifold, and let $(q:\mathcal F_g(M)\to M,\omega)$ be the Riemannian geometry associated with $(M,g)$. Under the identification $\mathcal U M \cong \mathcal F_g(M)/H,$ the Cartan connection $\omega$ determines a Cartan geometry of type $(G,H)$ on $\mathcal U M$. Then the objects induced on $\mathcal U M$ by this Cartan geometry are exactly as follows:
\begin{enumerate}
\item the metric $\bar{g}$  is the restriction of the Sasaki metric $\widehat g$ to $\mathcal U M$;
\item the vector field $U$ is the geodesic vector field $\mathbf Z_g$;
\item the $1$-form $\alpha$ is the $1$-form $\tau$;
\item $\mathbb R U\oplus\mathcal E$ is the horizontal distribution $\mathcal{H}$ of $\pi:\mathcal U M\to M$;
\item $\mathcal B$ is the vertical distribution $V$ of
$\pi:\mathcal U M\to M$;
\item the tensor $\Psi$ is the tensor $\Phi$ defined by
\[
J(\xi)=\Phi(\xi)+\widehat g(\mathbf Z_g,\xi)\mathbb A,
\qquad
\xi\in T(\mathcal U M),
\]
where $J$ is the almost complex structure on $TM$ and $\mathbb A$ is the Liouville normal vector field along $\mathcal U M\subset TM$.
\end{enumerate}
Consequently, $(\bar g,U,\alpha,\Psi)$ is the contact metric structure on $\mathcal U M$ induced by the Sasaki metric, as described in
Subsection~\ref{31052026}.

[Theorem 22 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] For every sufficiently small \(\eps>0\), the blow-up
\(\widetilde X=\Bl_SX\) admits a K\"ahler metric
\(\widehat\omega_\eps\) satisfying
\begin{equation}
  [\widehat\omega_\eps]
  =
  \pi^*[\omega]-\eps^2[E]
\end{equation}
and
\begin{equation}
  \norm{
    S(\widehat\omega_\eps)-\pi^*S(\omega)
  }_{C^0(\widetilde X)}
  \longrightarrow0.
\end{equation}

[Definition 53 of arXiv:2607.18104, '2607.18104'] Fix an $(N,k)$-periodic Bernoulli path $h^{\per}_0$ and define the \textbf{periodic ASEP height function} $h^{\pASEP}(h_0,0;y,t)$ for $t=0$ by $h^{\pASEP}(h^{\per}_0,0;y,0)=h^{\per}_0(y)$ for all $y\in \Z$. For times $t>0$, we define the height function $h^{\pASEP}(h^{\per}_0,0;y,t)$ in terms of the underlying periodic ASEP $(\eta^{\per}_t)_{t \geq 0}$ as follows. When a particle jumps from  $y$ to  $y+1$ at time $r$, set
\begin{equation}
h^{\pASEP}(h^{\per}_0,0;z,r) = \begin{cases}
h^{\pASEP}(h^{\per}_0,0;z,r^-) + 1 & \text{ if } z=y+jN \text{ for some } j \in \Z,  \\
h^{\pASEP}(h^{\per}_0,0;z,r^-)  & \text{ if } z \neq y+jN \text{ for some } j \in \Z . 
\end{cases}
\end{equation} Similarly, when a particle jumps in $(\eta^{\per}_t)_{t \geq 0}$ from site $y$ to site $y-1$ at time $r$, then we set
\begin{equation}
h^{\pASEP}(h^{\per}_0,0;z,r) = \begin{cases}
h^{\pASEP}(h^{\per}_0,0;z,r^-) - 1 & \text{ if } z=y-1+jN \text{ for some } j \in \Z , \\
h^{\pASEP}(h^{\per}_0,0;z,r^-)  & \text{ if } z \neq y-1+jN \text{ for some } j \in \Z .
\end{cases}
\end{equation} For starting times $s\geq 0$ for $h^{\pASEP}(h^{\per}_0,s;z,r)$, we consider the above construction, but with respect to $\eta^{\per}_s(x)=h^{\per}_0(x-1)-h^{\per}_0(x)$ for all $x \in \Z$.

[Definition 12 of arXiv:2606.06193, 'Peng's Maximum Principle for McKean-Vlasov Stochastic Differential Equations with Common N'] On the probabilistic set-up $(\Omega,\cF,(\cF_t)_{t\in[0,T]}, \P)$ we call a strong solution to the conditional McKean--Vlasov BSDE \eqref{eq:Cond-MKVBSDE} on the interval $[0, T]$ a $4$-tuple $(P,Q,R,S)\in \mathbb{S}^{2,m}\times\Lambda^{2,m\times d}\times\Lambda^{2,m\times d}\times\Lambda^{2,m\times d}$ such that $\P$-a.s. for every $t\in[0,T]$,
            \begin{equation*}
                \begin{aligned}
                   P_t=&\xi-\int_t^T\tilde{\E}\left[F\left(t,
                    P_t,\tilde{P}_t,
                    Q_t,\tilde{Q}_t,
                    S_t,\tilde{S}_t,
                    R_t,\tilde{R}_t,
                    \chi_t,\tilde{\chi}_t\right)\right]\dt \\
                    &-\int_t^T R_t\dW^0_t-\int_t^TQ_t\dW^1_t-\int_t^TS_t\dW^2_t,
                \end{aligned}
            \end{equation*}
            such that all integrals are well-defined.

[Lemma lem:swfourier2 of arXiv:2602.11129, 'Information-Theoretic Thresholds for Bipartite Latent-Space Graphs Under Noisy Observation'] Whenever $\boldsymbol{\Sigma}_\beta$ is positive definite for all $\beta \subseteq \alpha$, we have
    \begin{align*}
        \Expectedsub{\mathbf{x}}{ \SW{K_{1,\alpha}} \mid (\mathbf{x}_u)_{u \in \alpha} } &= \lim_{h \rightarrow \infty} \frac{-1}{(2\pi)^{|\alpha|}} \int_{[-\infty, \infty]^{|\alpha|}} e^{-\trp{i\mathbf{t}}{\mathbf{x}}_{\tau}} \left( \sum_{\beta \subseteq \alpha} (-1)^{|\alpha \setminus \beta|}  \hspace{.1cm}\varphi_{\beta}(\mathbf{t}) \right) \prod_{e \in \mathbf{t}} \frac{1 - e^{ih\mathbf{t}(e)}}{i\mathbf{t}(e)} \mathrm{d} \mathbf{t},
    \end{align*}
    where $\varphi_{\beta}(\mathbf{t}) = \Expected{\exp(i\trp{\mathbf{t}}{\mathbf{z}_\beta})}$ is the characteristic function of $\mathbf{z}_\beta$, and $\mathbf{x}_{\tau}$ is the vector that contains $\tau $ everywhere. (Proof in the paper; no proof environment follows the statement in the TeX.)

