[Lemma 15 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let~\eqref{co:3},~\eqref{co:6} and~\eqref{co:7} hold. Then
\begin{equation*}
\E\big[|\hat{I}_{t}^{(n)} - I_{t_{j,n}}^{(n)}\big|^{p}\big]^{\frac{1}{p}} \leq m_{p,j,n}(t-t_{j,n})^{\frac{1}{2}}
\end{equation*}
for any $n\in\N$, $j\in\{0,\dots,k_{n}-1\}$ and $t\in [t_{j,n},t_{j+1,n}]$ with the non-negative constant
\begin{equation}
\begin{split}
m_{p,j,n} &:= T^{\frac{1}{2}}\big(\hat{b}_{0}(t_{j,n},N(t_{j,n})) + \hat{b}_{k+3}(t_{j,n},N(t_{j,n})) N(t_{j,n})\big)\\
&\quad + \E\big[\big(Z_{1}^{2} + \cdots + Z_{d}^{2}\big)^{\frac{p}{2}}\big]^{\frac{1}{p}}l(t_{j,n},N(t_{j,n}))N(t_{j,n}),
\end{split}
\end{equation}
where $Z_{1},\dots,Z_{d}$ are independent $\mathcal{N}(0,1)$-distributed random variables. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 of arXiv:2606.17381, 'Large deviation principle for friendship-biases\\ in Galton--Watson trees'] {\bf[Spectral representation of $\Lambda$]}

For every $t = (t_-,t_0,t_+) \in \R^3$, $\Lambda(t)$ exists in $[-\infty,\infty]$. In particular,
\[
\Lambda(t) =
\begin{cases}
\log \vartheta(t), & \text{if } t_0 < \log(1/p),\\
\infty, & \text{if } t_0\geq \log(1/p),
\end{cases}
\]
where $\vartheta(t)$ is the Perron--Frobenius eigenvalue of $M(t)$.

[Lem 29 of arXiv:2607.06242, 'Exponential mixing and Freidlin--Wentzell large deviation principle for Markov cocycles'] For $m$-a.e. $\sigma\in\Sigma$ and every $M>0$, the level set
  \begin{align*}
  K_M(\sigma)=\{E_{\Ac(\sigma)}\leq M\}
\end{align*}
  is compact in $X$.

