body:
[Proposition prop:shearM of arXiv:2608.16915, 'Exact mean--covariance dynamics of the Weber field in the stochastic Lagrangian representa'] For $f_0\in L^2(\mathbb{T}^2)$ with zero mean, the field
\[
  u(t,x)=\bigl(e^{\nu t\Delta_\perp}f_0(x_2,x_3),\,0,\,0\bigr)
\]
is a global smooth solution of (equation eq:NS of the paper) for $t>0$, since $(u\cdot\nabla)u=0$. Its
mean displacement and mean deformation are
\begin{equation}
  \ell(t)=-t\,u(t),\qquad
  M(t)=I-t\,e_1\otimes\nabla_\perp e^{\nu t\Delta_\perp}f_0 ,
\end{equation}
and for every $0<\alpha<1$ and $\tau>0$,
\begin{equation}
  \sup_{t\ge\tau}\left\lVert M(t)-I\right\rVert_{C^\alpha}
  \le C_\alpha\,\nu^{-1-\alpha/2}\,\tau^{-\alpha/2}\,\left\lVert f_0\right\rVert_{L^2(\mathbb{T}^2)} .
\end{equation}

[Lem 17 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] For every $n \in \mathbb{N}_+$, it holds 
\begin{align} 
 \sup_{r \in [0,T]} \Bigg\{ \frac{1}{n} \sum_{x} \big[  \Theta(n) ( \mathbb{L}_n^{\gamma,s} H )( \tfrac{x + q_n^r }{n}  ) \big]^{2}  \Bigg\} \leq C(\gamma,H).
\end{align}
Moreover, if $H \in C_c^{2}(\mathbb{R})$, then the role of $C(\gamma,H)$ above is fulfilled by some constant $C(H)$ satisfying \eqref{Cinvshift}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:one-large-position of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] If $m\ge40$, then
\begin{equation}
  \kappa\le\floor*{\frac{3m}{2}}+1
  +\mu(\kappa)+2\mu(\floor{\kappa/2}).
\end{equation}
In particular,
\begin{equation}
  e=\kappa-1\le3m-6.
\end{equation}

[Definition 8 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] We introduce the set of noise types $\tilde{\mathfrak{L}}_- = \{ \<b0>, \<p0>, \<s(1)0>, \<bs(2)0>, \<ps(2)0> \}$ (with homogeneities $-3/2 - \kappa, -3/2 - \kappa, -1 - \kappa, -3/2 - 2\kappa, -3/2 - 2\kappa$ respectively) and kernel types $\tilde{\mathfrak{L}}_+ = \{ \<bk>, \<pk>, \<k> \}$. We let $\hat{\mfT}$ be the (reduced) regularity structure associated to the (completion of) the subcritical rule
	\begin{align*}
		R( \<bk> ) &= \{ (\<dbk>, \<dbk>), (\<dbk>), (\<b0>), () \},
		\\
		R( \<pk> ) &= \{ (\<dpk>, \<dpk>), (\<dpk>), (\<p0>), () \},
		\\
		R( \<k> ) &= \{ (\<dk>, \<dbk>), (\<dk>), (\<dbk>), (\<dk>, \<dpk>), (\<dpk>), (\<s(1)0>, \<dbk>), (\<s(1)0>), (\<s(1)0>, \<dpk>), (\<bs(2)0>), (\<ps(2)0>), ()\}
	\end{align*}
	where we have used the convention that thick lines such as $\<k>$ represent kernels carrying a vanishing derivative decoration whilst thin lines such as $\<dk>$ represent edges carrying a spatial derivative.

	We let $\tilde{\mfT}$ be the substructure generated by those trees in the natural basis for $\hat{\mfT}$ which do not contain either of 
	\begin{align*}
		\<s(1)b1>, \qquad \<s(1)p1>
	\end{align*}
	as subtrees. We equip this with the structure group described in Appendix~\ref{app:degree_shift} which can be identified with the elements of the character group of $\hat{\mcT}_+$ which vanish on trees containing one of the two trees excluded as subtrees above.

[Lemma cont of arXiv:2411.04157, 'Stochastic homogenization of dynamical discrete optimal transport'] Let $m\in W^{1,1}((0,T);{\mathcal P}(\mathcal X))$ and $J\in L^1((0,T);\mathbb{R}^{\mathcal E}_a)$ solve (equation eq: dcont of the paper). 
    Then $(m,\iota J)$ solves 
    \begin{align}
    \partial_tm+\dive \iota J=0 \quad \text{ in }\mathcal{D}'((0,T)\times \mathbb{R}^n).
\end{align}

