[Cor 30 of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Define functions $  {\mathpzc F},\mathpzc G_{ij}$ on $\ak$ by 
    \begin{align*}
          {\mathpzc F} (   \beta)&:= \int_I x e^{   \beta \bullet    x - \log M(   \beta)}\mu(\mathrm d   x),\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\mathpzc G_{ij}(   \beta):= \int_I x_ix_j e^{   \beta \bullet    x - \log M(   \beta)}\mu(\mathrm d   x).
    \end{align*}
    There exists $C>0$ such that the following bounds hold uniformly over $   \beta \in \ak$ and $\x\in I^k$ and $1\le i<j\le k$ and $A\in \mathbb N$:
    \begin{align*}
       \bigg| \int_{I^k} (   a_i-   x_i)\qdif(\x,\dr \bfa) -   {\mathpzc F}(   \beta)\bigg| &\leq Ce^{C\cdot A} \bigg(|   \beta|^{2p-1}e^{-\frac1{\Con} \min_{i<j}|   x_i-   x_j|} +|   \beta|^{A}\bigg)
       \\\bigg| \int_{I^k} (   a_i-   x_i)(   a_i-   x_i)^T\qdif(\x,\dr \bfa)-\mathpzc G(\beta)\bigg| &\leq Ce^{C\cdot A} \bigg(|   \beta|^{2p-2}e^{-\frac1{\Con} \min_{i<j}|   x_i-   x_j|}+|   \beta|^{A-1}\bigg)\\\bigg| \int_{I^k} (   a_i-   x_i)(   a_j-   x_j)^T\qdif(\x,\dr \bfa)-   {\mathpzc F(\beta)}  {\mathpzc F(\beta)}^T\bigg| &\leq Ce^{C\cdot A} \bigg(|   \beta|^{2p-2}e^{-\frac1{\Con} \min_{i<j}|   x_i-   x_j|}+|   \beta|^{A-1}\bigg).
    \end{align*}
    In the left side of the second and third bounds, one could interpret the expression using any norm on $d\times d$ matrices.

[Lemma lem:thisisactuallywhatwewannabound of arXiv:2602.11129, 'Information-Theoretic Thresholds for Bipartite Latent-Space Graphs Under Noisy Observation'] \begin{align*}
        &1  +\dchisq{\mathcal{L}(\mu \mid S_\rho)}{\nu} \le (1 + o(1)) \Expectedsubb{  \mathbf{X}_{\text{R}}^{(1)} ,  \mathbf{X}_{\text{R}}^{(2)}  \sim S_\rho }{ \exp\left( 2m q^{2} \sum_{u\in R} \frac{ \Expected{ \SWnum{K_{1,\{u\}}}{1} } \Expected{ \SWnum{K_{1,\{u\}}}{2} }}{p(1-p)} \right) }^{1/2} \\
        &\hspace{6cm} \times \prod_{\substack{k = 2}}^{\log(m)} \Expectedsubb{  \mathbf{X}_{\text{R}}^{(1)} ,  \mathbf{X}_{\text{R}}^{(2)}  \sim S_\rho }{ \exp\left( m \left( \frac{ 2q^2 }{(p(1-p))}\right)^{k} \sum_{\alpha \subseteq R, |\alpha| = k}  \Lambda_\alpha(\mathbf{X}_R^{(1)}, \mathbf{X}_R^{(2)})  \right) }^{1/2^k}.
    \end{align*}

[Proposition 7 of arXiv:2506.20411, 'Maximal Counts in the Stopped Occupancy Problem'] For $r_n'\sim \beta \log L$ with any $0<\beta<1/2$,
locally uniformly in $s$,
\begin{equation}
d_{\rm TV}(\widehat{\rm M}_n^s|_{[-r_n',\infty]}\,,\,  {\rm \Xi}^\uparrow_{(e-1)s+c_n}|_{[-r_n',\infty]})\to\ 0.
\end{equation}

[Lemma 46 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the same notation as in Definitions \ref{Def.ParametersBulk}, \ref{Def.ScalingBulk} and \ref{Def.ContoursBulk}, and that $c \neq 1$. Let $M^N$ be the point process on $\mathbb{R}^2$, formed by $\{(t_j, X_i^{j,N}): i \geq 1, j \in \llbracket 1, m\rrbracket \}$. Then for all large $N$ (depending on $q$ and $c$), $M^N$ is a Pfaffian point process with reference measure $\mu_{\mathcal{T},\nu(N)}$ and correlation kernel $K^N$ that are defined as follows. 

The measure $\mu_{\mathcal{T},\nu(N)}$ is as in Definition \ref{Def.ScaledLatticeMeasures} for $\nu(N) = (\nu_{t_1}(N), \dots, \nu_{t_m}(N))$, where $\nu_{t}(N)$ is $\sigma_1^{-1} N^{-1/3}$ times the counting measure on $\Lambda_{t}(N)$. 

The correlation kernel $K^N: (\mathcal{T} \times \mathbb{R}) \times (\mathcal{T} \times \mathbb{R}) \rightarrow\operatorname{Mat}_2(\mathbb{C})$ takes the form
\begin{equation}
\begin{split}
&K^N(s,x; t,y) = \begin{bmatrix}
    K^N_{11}(s,x;t,y) & K^N_{12}(s,x;t,y)\\
    K^N_{21}(s,x;t,y) & K^N_{22}(s,x;t,y) 
\end{bmatrix} \\
&= \begin{bmatrix}
    I^N_{11}(s,x;t,y) & I^N_{12}(s,x;t,y) + R^N_{12}(s,x;t,y) \\
    -I^N_{12}(t,y;s,x) - R^N_{12}(t,y;s,x) & I^N_{22}(s,x;t,y) + R^N_{22}(s,x;t,y) 
\end{bmatrix} ,
\end{split}
\end{equation}
where $I^N(s,x;t,y), R^N(s,x;t,y)$ are defined as follows. The kernels $I^N_{ij}$ are given by
\begin{equation}
\begin{split}
&I^N_{11}(s,x;t,y) = \frac{1}{(2\pi \im)^{2}}\oint_{\gamma_N^+(1)} dz \oint_{\gamma_N^+(1)} dw F_{11}^N(z,w) H_{11}^N(z,w) \mbox{, where }\\
& F^N_{11}(z,w) = e^{NS_1(z) + NS_1(w)} \cdot e^{T_s G_1(z) + T_t G_1(w)} \cdot e^{- \sigma_1 x N^{1/3} \log (z) - \sigma_1 y N^{1/3} \log(w)  }, \\
&H^N_{11}(z,w) = 4\sigma_1^2 N^{2/3} \cdot  \frac{z-w}{(z^{2}-1)(w^{2}-1)(zw-1)} \cdot ( 1 - c/z) (1 - c/w);
\end{split}
\end{equation}
\begin{equation}
\begin{split}
&I^N_{12}(s,x;t,y) = \frac{1}{(2\pi \im)^{2}}\oint_{\gamma_N^+(1)} dz \oint_{\gamma_N^-(-1)} dw F_{12}^N(z,w) H_{12}^N(z,w) \mbox{, where }\\
& F^N_{12}(z,w) = e^{NS_1(z) - NS_1(w)} \cdot e^{T_s G_1(z) - T_t G_1(w)} \cdot e^{- \sigma_1 x N^{1/3} \log (z) + \sigma_1 y N^{1/3} \log(w)  }, \\
&H^N_{12}(z,w) =  \sigma_1 N^{1/3} \cdot \frac{zw - 1}{z (z-w)(z^2 - 1)} \cdot \frac{z - c}{w - c};
\end{split}
\end{equation}
\begin{equation}
\begin{split}
&I^N_{22}(s,x;t,y) = \frac{1}{(2\pi \im)^{2}}\oint_{\gamma_N^-(-1)} dz \oint_{\gamma_N^-(-1)} dw F_{22}^N(z,w) H_{22}^N(z,w) \mbox{, where }\\
& F^N_{22}(z,w) = e^{-NS_1(z) - NS_1(w)} \cdot e^{-T_s G_1(z) - T_t G_1(w)} \cdot e^{ \sigma_1 x N^{1/3} \log (z) + \sigma_1 y N^{1/3} \log(w)  }, \\
&H^N_{22}(z,w) =  \frac{1}{4} \cdot \frac{z-w}{zw - 1} \cdot \frac{1}{(z- c)(w - c)}.
\end{split}
\end{equation}
The kernels $R^N_{ij}$ are given by
\begin{equation}
\begin{split}
&R^N_{12}(s,x;t,y) = \frac{-{\bf 1}\{s < t \} \cdot \sigma_1 N^{1/3} }{2 \pi \im} \oint_{\gamma_{N}^+(1)}dz e^{(T_s - T_t) G_1(z)} \cdot e^{ (\sigma_1 y N^{1/3}  - \sigma_1 x N^{1/3} - 1) \log (z)} \\
& +  \frac{{\bf 1}\{c > 1\}\cdot \sigma_1 N^{1/3}}{2\pi \im} \oint_{\gamma_N^+(1)}dz \frac{zc - 1}{z(z^2 - 1)} \cdot F_{12}^N(z,c);
\end{split}
\end{equation}
\begin{equation}
\begin{split}
&R^N_{22}(s,x;t,y) = \frac{{\bf 1}\{c > 1\}}{2\pi \im} \oint_{\gamma^-_N(-1)} dz \frac{F_{22}^N(z,c)}{4(c z - 1)} - \frac{{\bf 1}\{c > 1\}}{2\pi \im} \oint_{\gamma^-_N(-1)} dw \frac{F_{22}^N(c,w)}{4(c w - 1)} \\
& + \frac{1}{2\pi \im}\oint_{\gamma^-_N(-1)} dw  \frac{(1-w^2)}{4(1-c w)(w-c)} \cdot e^{ ( \sigma_1 y N^{1/3} - \sigma_1 x N^{1/3} - 1) \log (w) - T_s G_1(w^{-1}) - T_t G_1(w)}.
\end{split}
\end{equation}

