body:
[Corollary cor:ci_sample_mean of arXiv:2609.01581, 'Concentration of additive functionals of Stratonovich-type'] Let the assumptions of Theorem~(thm:ci of the paper) hold. Fix a confidence level $1-\alpha$, with
$\alpha \in (0,1)$, and for $n \geq 1$ define
\begin{align}
  r_A(\alpha,n,t)
  =
  \sqrt{\frac{2\tilde\sigma_A^2}{nt}\left(\log\frac{2}{\alpha} 
  + n\log N_\nu\right)}
  +
  \frac{c_A}{nt}\left(\log\frac{2}{\alpha} + n\log N_\nu\right).

\end{align}
Then for every $n \geq 1$ and $t > 0$, it holds that
\begin{align}
  \mathbb{P}^\nu\left(-r_A(\alpha,n,t) \leq \widehat{A}_{n,t} 
  - \E^\mu[\overline{A}_t]
  \leq r_A(\alpha,n,t)\right)
  \geq 1-\alpha,

\end{align}
that is, with probability of at least $1-\alpha$, under $\mathbb{P}^\nu$, the stationary mean
is found in the confidence interval
\begin{align}
  \E^\mu[\overline{A}_t]
  \in
  \left[\widehat{A}_{n,t} - r_A(\alpha,n,t),
  \widehat{A}_{n,t} + r_A(\alpha,n,t)\right].

\end{align}
Corresponding one-sided guarantees hold with the smaller radius
$r_A^{(1)}(\alpha,n,t)$ obtained by replacing $\log(2/\alpha)$ with $\log(1/\alpha)$
in Eq.~(equation eq:ci_sample_mean of the paper).

[Definition 6 of arXiv:2608.24675, 'Towards Liouville Quantum Gravity on fractals'] We say that	a centered Gaussian random element $h\colon\Omega\to \mathcal S'(K)$ is a \emph{fractal Gaussian free field} (FGFF) on $K$  if its covariance is given by
	 \begin{equation}
		 \mathbb E[\langle h,u\rangle \langle h,v\rangle]=\int_K\int_{K} k_{d_S}(x,y)u(x)v(y)\, d\mu(x)\, d\mu(y)
     \end{equation}
     for all $u,v\in \mathcal S(K)$.

[Definition def:regeneration of arXiv:2608.15344, 'A Harris recurrent continuous-time Markov process without wide-sense regenerative structur'] The process $X$ is said to be \textit{wide-sense regenerative} if there exist randomized stopping times $0\leq R_0<R_1<\dots<\infty$ such that:
\begin{enumerate}[label=(\roman*)]
    \item for each $n\geq0$, $\Theta_{R_n}X$ is independent of $R_n$;
    \item $\Theta_{R_n}X$ is identically distributed in $n$.
\end{enumerate}

[Lem deter_lemma:no_sausages of arXiv:2601.00119, 'The largest common subtree of two random trees'] If $B_n^{(1)}$ occurs and if $n$ is large enough so that $14\max(c,n^{1/2-\alpha})<\tilde{\delta}\sqrt{n}$, then there exist $w \in \tau$,  $w'\in \tau'$, and $0\leq k\leq \mathrm{Ht}(\tau)-1$ such that at least one of the following two events happens:
\begin{enumerate}
\item[\emph{(i)}] $\displaystyle{\Bigg|ck- \!\sum_{\substack{\varnothing \prec x\preceq w \\ \varnothing \prec x'\preceq w'}}\! {\mathbf 1}_{\left\{|w|-|x|=|w'|-|x'|<k\right\}} \operatorname{LCS}^\bullet\left(\operatorname{Trim}_{x}\tau,\operatorname{Trim}_{x'}\tau'\right)\wedge n^{1/2-\alpha}\Bigg|>\tfrac{\tilde\delta}{14} \sqrt{n} }$;
\item[\emph{(ii)}] $\displaystyle{\Bigg|ck- \!\sum_{\substack{\varnothing \prec x\preceq w \\ \varnothing \prec x'\preceq w'}}\! {\mathbf 1}_{\left\{|w|-|x|=k-1-(|w'|-|x'|)<k\right\}} \operatorname{LCS}^\bullet\left(\operatorname{Trim}_{x}\tau,\operatorname{Trim}_{x'}\tau'\right)\wedge n^{1/2-\alpha}\Bigg|>\tfrac{\tilde\delta}{14} \sqrt{n} }$.
\end{enumerate}

