[Corollary 250 of arXiv:2601.16377, '2601.16377'] Assume that $\pi_{\boldsymbol{v}}^{\circ}$ is a bijection, that $\boldsymbol{v}$ has bipartite $\mathfrak{G}$-orbit and $\textbf{\text{\foreignlanguage{russian}{B}}} = \textnormal{\textbf{Id}} - \boldsymbol{1}$. Then, the Green function on $\Sigma_{\boldsymbol{v}}^{\textnormal{half}}$ with Dirichlet boundary conditions on $\partial\Sigma_{\boldsymbol{v}}^{\textnormal{half}}$ is
\begin{equation}

\textnormal{Gr}(p_1,p_2) = -\frac{1}{4\pi}\left(\textnormal{gr}_{\boldsymbol{v}}(p_1,p_2) + 2\log\bigg|\frac{z_1 - z_2}{z_1 - z_2^*}\bigg|\right).
\end{equation}

[Lemma 32 of arXiv:2511.10814, '\Large \bf \boldmath\ \\ Convergence of the extended Kalman filter with small and state-de'] (Properties of symmetric and positive semi-definite matrices)
Let $A, B \in \mathcal{M}_{d}(\mathbb{R})$, $d \in \mathbb{N}$, symmetric and positive semi-definite matrices.
	Then it holds

\begin{enumerate}

\item 														
\begin{equation}
\lambda_{min}(A) \trace(B) \leq \trace(AB)  \leq  \lambda_{max}(A) \trace(B)
\end{equation}
where $\lambda_{min}(A)$  and $\lambda_{max}(A)$ denote the smallest and largest eigenvalue
	of A, respectively.

	\item  \begin{equation} 
	\dfrac{\trace(B)}{ \trace\left( A^{-1} \right)} \leq   \trace(AB) \leq \trace(A)  \trace (B) 
						\end{equation}														
where for the first inequality A is assumed to be positive definite.

\item \begin{equation}
	\trace^2(A)  \geq \trace\left( A^2 \right) \geq  \dfrac{1}{d} \trace^2 (A)
\end{equation}

\item  \begin{equation}				\vert A\vert_F = \sqrt{\trace\left( A^2 \right)}  \leq \trace(A)
						\end{equation}
			where $\vert A\vert_F$  denotes the Frobenius norm of A.
					\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 42 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $q \in (0,1)$, $c \in [0, q^{-1})$, and set
\begin{equation}
\begin{split}
&\sigma_1 = \frac{q^{1/3} (1 + q)^{1/3}}{1- q}, \hspace{2mm} f_1 = \frac{q^{1/3}}{2 (1 + q)^{2/3}}, \hspace{2mm} p_1 = \frac{q}{1-q}, \hspace{2mm} h_1 = \frac{2q}{1-q}.
\end{split}
\end{equation}
We also define for $z \in \mathbb{C} \setminus \{0, q , q^{-1}\}$ the functions
\begin{equation}
\begin{split}
&S_1(z) = \log(1 - q/z) - \log(1-qz) - h_1 \log(z), \\
&G_1(z) = \log(1-q/z)- p_1 \log(z) - \log (1-q).
\end{split}
\end{equation}
In equation (\ref{Eq.DefSGBot}) and the rest of the paper we always take the principal branch of the logarithm.

