body:
[Prop degree-times-n of arXiv:2510.18856, 'Evolution of recursive trees with limited memory'] Let $\left(\left(\mathscr{E}_{j,k}\right)_{k\geqslant 1}: j\geqslant 0\right)$ be \emph{iid} copies of $\left(\mathscr{E}_{k-1\leadsto k}\right)_{k\geqslant 1}$. Then, as $n \to \infty$,\begin{align*}
 \left(\left(\tau_{j,k}^n\right)_{k\geqslant 1}: j\geqslant 0\right) \stackrel{d}{\longrightarrow} \left(\left(\mathscr{E}_{j,k}\right)_{k\geqslant 1}: j\geqslant 0\right).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 25 (Separated and coherent defects) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] Define
\begin{align}
 \mathfrak R_Q(r)
 &=\sum_{a,b}\sum_{p,q\le Q}
   \sum_{\substack{1\le s\le p\wedge q\\\neg(p=q=s)}}
   b_{p,q,s}\norm{r_{a,p}\wtensor_sr_{b,q}}^2,
 \\
 \mathfrak I_Q(A,r)
 &=\sum_{a,b}\sum_{p,q\le Q}\sum_{1\le s\le p\wedge q}
   b_{p,q,s}\norm{A_{a,p}\wtensor_sr_{b,q}}^2,
 \\
 \mathfrak H_Q(A,r)&=\mathfrak R_Q(r)+\mathfrak I_Q(A,r).

\end{align}
The coherent defects are
\begin{align}
 \Delta_{\mathrm{res}}(r)
 &=\sum_{a,b}\norm{\Gamma(R_a,R_b)-\E[R_aR_b]}_2^2,
 \\
 \Delta_{\mathrm{mix}}(A,r)
 &=\sum_{a,b}\norm{\Gamma(\mathcal A_a,R_b)}_2^2.

\end{align}

