body:
[Lemma 42 of arXiv:2609.01114, 'Unbalanced spectral Tur\'an problem for color-critical graphs with prescribed large maximu'] The following statements hold for all sufficiently large $n$.
\begin{enumerate}[label=\textnormal{(\roman*)}]
\item $|A_2|<\varepsilon^3D$, $|B_2|<\varepsilon^3D$, $|L|<\varepsilon^3D$, $|K_A|<\varepsilon^3D$, and $|K|<\varepsilon^3D$.
\item If $v\in V_i'$ and $j\ne i$, then
\begin{equation}
 d_{V_j'}(v)\ge\left(\frac1p-50(10^4p^2f^2)\varepsilon^3\right)D,
 \quad
 d_{B'_{1,j}}(v)\ge\left(\frac1p-51(10^4p^2f^2)\varepsilon^3\right)D.
\end{equation}
\item $ E(G^{\star}[A_1])=\emptyset$, and $E(G^{\star}[B'_{1,i}])=\emptyset\quad(i\in[p])$.

\item The total number of missing crossing pairs between the $V_i$ satisfies
\begin{equation}
 \sum_{1\le i<j\le p}
 \bigl(|V_i||V_j|-e_{G^{\star}}(V_i,V_j)\bigr)
 \le2\varepsilon^6D^2.
\end{equation}
\end{enumerate}

