[Theorem 2 of arXiv:2505.20799, 'A note on the improved sparse Hanson-Wright inequalities'] In the same setting of Theorem \ref{Theo_main1}, we have for $0<\alpha\le 1$ and $t\ge 0$
	\begin{align}
		\mathbb{P}\{\vert \xi^\top A\xi-\mathbb{E}\xi^\top A\xi\vert\ge L(\alpha)^{2}t    \}\le 2\exp(-c(\alpha)f(t)),\nonumber
	\end{align}
where  $L(\alpha)=\max_{i}\Vert \zeta_{i}\Vert_{\Psi_{\alpha}}$, $c(\alpha)$ is a positive constant depending only on $\alpha$, and
\begin{align}
	f(t)=\min\Big\{ \frac{t^{2}}{\sum_{k}a_{kk}^{2}p_{k}+\sum_{i\neq j}a_{ij}^{2}p_{i}p_{j}}, 
	& \frac{t}{\Vert (a_{ij}\sqrt{p_{i}p_{j}})_{n\times n}\Vert_{l_{2}\to l_{2}} }, \nonumber\\
	&\Big( \frac{t}{\max_{i}\big( \sum_{j}a_{ij}^{2}p_{j}\big)^{1/2}} \Big)^{\frac{2\alpha}{2+\alpha}}, \Big(\frac{t}{\Vert A\Vert_{\infty}}\Big)^{\frac{\alpha}{2}}\Big\}.\nonumber
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 (Bulk case) of arXiv:2511.12623, 'The eigenvector bead process'] We recall Convention~\ref{conv:inverse-stieltjes-branches}. Fix \(E\in(-2,2)\) and define the anchor \\
\(
i_N(E)\;:=\;\min\bigl\{\,k\in\{1,\dots,N\}\ :\ \lambda^{(N)}_{k}\ \ge E\sqrt{N}\,\bigr\}.
\) Then the overlaps satisfy
\begin{equation}
\Omega^{(N)}_{\,i_N(E)+u,\;i_N(E)+v}
\;\mathrel{\underset{N\to\infty}{\overset{d}{\sim}}}\;
\frac{g_v}{\,S_{\mu,\,g^2}^{-1}(h)_u-\mu_v\,}\,
\sqrt{\bigl(S_{\mu,\,g^2}^{-1}\bigr)'(h)_u},
\qquad h=-\frac{E}{2\sqrt{4-E^2}}.
\end{equation}

\noindent
Here $(\mu_u)_{u\in\mathbb Z}$ follow the sine$_\beta$ point process, and $(g_u)_{u\in\mathbb Z}$ are i.i.d. standard Gaussians $\mathcal{N}_\beta(0,1)$ independent of $(\mu_u)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:Td-ad-model-exists of arXiv:2606.10257, 'Downward conditional monotonicity gives survival and extinction for contact processes in r'] Consider an MMPP $(B,X)$ with irreducible, monotone $T$, increasing $\alpha$, eigenvector $v^*$, and which satisfies, for all triples $\ell<i<j$,
	\begin{equation}
		(\alpha_j-\alpha_i)\sum_{\ell\leq s} v^*_s\leq \sum_{\ell\leq s} (T_{is}-T_{js}).
	\end{equation}
	For any $\delta>0$, there exists an MMPP $(B^\delta,X^\delta)$ with strictly monotone $T^\delta=T+\delta E$ (with $E$ an appropriate matrix), the same $\alpha$, eigenvector $v^\delta$, and which satisfies, for all triples $\ell<i<j$,
	\begin{equation}
		(\alpha_j-\alpha_i)\sum_{\ell\leq s} v^\delta_s < \sum_{\ell\leq s} (T^\delta_{is}-T^\delta_{js}).
	\end{equation}
	Furthermore, $(B^\delta,X^\delta)$ weakly converges to $(B,X)$ as $\delta\to0$, and the eigenvectors satisfy $v^*\preceq v^\delta$ for all $\delta>0$.

