[Proposition prop:negative-moments of arXiv:2608.28004, 'Hausdorff Dimension of the Set of Extreme Points\\ of a Random Countable Stable Zonotope'] Let \(U=B_S(u_0,r)\subsetS^{d-1}\) be a geodesic ball, that is, the ball of
radius \(r\) centered at \(u_0\) in the metric \(d_S\), and suppose that
\(\diam U\leq\pi/4\). For every \(0<\beta<N\), there exists
\(C_\beta<\infty\), depending only on \(d\), \(\alpha\), and \(\beta\),
such that, for all distinct \(u,v\in U\),
\begin{equation}
    \mathbb E\|X(u)-X(v)\|^{-\beta}
    \leq
    C_\beta\, d_S(u,v)^{-\beta/\alpha}.
\end{equation}

[Lemma Palm-Lcal-ijn of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For $r\neq l\in [n], k=1,2$ and for all non-negative measurable functions $f$ on $(\Omega,{\mathcal F })$,
\begin{align}
 \frac{\Lambda^{(k)}_{l,r}}{4\lambda_l\lambda_r v_lv_r} \mathbb{E}^0_{{\mathcal V }^{(k)}_{l,r}} [f ({\mathcal H })]
& = \int_{0}^\infty  \int_{0}^h \int_{t^*}^\infty 
\mathbb{E}_{\mathcal H }\Bigg[ f \Big(\theta_{\hat{s}(0,h,-t',h')}({\mathcal H }^r+\delta_{(0,h)}+ {\mathcal H }^l+\delta_{(-t',h')}+\!\!\!\sum_{ m\neq l,r}{\mathcal H }^m)\Big) {\nonumber}\\

&\hspace{2.5in}\times \prod_{i}{\mathds{1}}_{{\mathcal H }^i\left(E^{\hat{s}_k(0,h,-t',h'),v_i}_{\hat{h}_k(0,h,-t',h')}\right)=0}
\Bigg] {\rm d}t'  {\rm d}h' {\rm d}h {\nonumber}\\ 

&\, +  \int_{0}^\infty  \int_h^\infty \int_0^{\infty}
\mathbb{E}_{\mathcal H }\Bigg[ f \Big(\theta_{\hat{s}(0,h,-t',h')}({\mathcal H }^r+\delta_{(0,h)}+ {\mathcal H }^l+\delta_{(-t',h')}+\!\!\! \sum_{m\neq l,r}{\mathcal H }^m)\Big) {\nonumber}\\

&\hspace{2.5in}\times \prod_{i}{\mathds{1}}_{{\mathcal H }^i\left(E^{\hat{s}_k(0,h,-t',h'),v_i}_{\hat{h}_k(0,h,-t',h')}\right)=0}
\Bigg] {\rm d}t'  {\rm d}h' {\rm d}h,
{\nonumber}
\end{align}

where, $(\hat{s}_k(t,h,t',h'),\hat{h}_k(t,h,t',h'))$
are the coordinates of the $k$-th intersection of the two radial birds with heads at $(t,h)$ and $(t',h')$, $t^*=\frac{1}{v_lv_r}(h^2-h'^2)^{\frac{1}{2}} (v_r^2-v_l^2)^{\frac{1}{2}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 20 of arXiv:2609.03512, ''] Let $G$ be a graph with $g(G)=3$ and $r(G)=4$. Then $\gamma(G)=\gamma_t(G)=2$ if and only if $G$ belongs to one of the following classes:
\begin{enumerate}
\item $G\in\mathcal{M}\bigl(B_2,B_4,B_5\bigr)$; or
\item $G\in\mathcal{M}\bigl(B_1,K_4\bigr)$, with $m_i\geq 2$ for at least one index $i$ corresponding to a dominating vertex $v_i$ of the base graph.
\end{enumerate}

