[Lemma lemma16 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that assumptions (A1 of the paper)-(A4 of the paper) hold and let $\varphi$ be a characteristic satisfying (C2 of the paper)-(C3 of the paper). Then, for every $h \in \mathbb{N}_{0}$, the function 
\begin{align} 
t\in \mathbb{R} \mapsto e^{-\alpha t} \int_{[0, \infty)} {\rm Var}[\varphi](t-x) \nu^{(h)}({\rm d} x)
\end{align}
\noindent is directly Riemman integrable, where $\nu^{(h)}$ is defined in (equation eq62 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 21 of arXiv:2605.03851, 'The Relay Random Tree:\\A stochastic geometry approach of multihop relay in an urban visib'] \textbf{Finite Range Shades.}

Let $\landsc$ be a landscape, $(x_1, y_1)$ a point of $\Half$, and $(a, b)\in \landsc$ a building. We call the shade of $(a, b)$ from $(x_1, y_1)$ the set of points right to $a$ that form a lower slope with $(x_1, y_1)$ than $(a, b)$ does, or that are too far away from $(x_1, y_1)$:
\[S^{ (x_1, y_1)}_{(a, b)} = \left\{ (x, y)\in \Half:x_1 \in [a, x_1+R],\  \frac{y-y_1}{x-x_1}\leq \frac{b-y_1}{a-x_1}\right\}\cup \{(x, y)\in \Half:x > x_1+R\}.\]

\begin{figure}[h]
            \centering
            \includegraphics[width=0.75\textwidth]{Figures/Shade_fini_horiz.ipe.png}
            \caption{One of the main differences with the infinite range setting, that will be the source of the more complex results, can be seen as the fact that the shades in this context are non convex}
\end{figure}

[Lemma 21 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb$, $f\in \Sob^k(\Rbb^n,\gamma_n)\cap \Leb^{\infty}(\Rbb^n,\gamma_n)$, $t> 0$ and $p\in [1,2]$,
\begin{equation}
    \left\|\left|\grad^k \Pop_t f\right|\right\|_{\Leb^2}^{2} \leq \upe^{-2k\left(p-1\right)t}\left(\upe^{4t}-1\right)^{-k(1-\frac{p}{2})}  \left\|f\right\|_{\Leb^{\infty}}^{2-p} \left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p},
\end{equation}
and further for all $\kappa\in \Nbb^n$ with $|\kappa|=k$,
\begin{equation}
    \left\|\Dop^\kappa \Pop_t f\right\|_{\Leb^2}^{2} \leq \upe^{-2k\left(p-1\right)t}\left(\upe^{4t}-1\right)^{-k(1-\frac{p}{2})}  \left\|f\right\|_{\Leb^{\infty}}^{2-p} \left\|\Dop^\kappa f\right\|_{\Leb^p}^{p}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 21 of arXiv:2605.04359, 'Well-posedness of reflected BSDEs with default time and irregular barrier: An application '] Let $\left(\L_t\right)_{t \leq T}$ be a regulated process which is r.u.s.c along stooping satisfying condition \textbf{(H3')} with $\L \in \mathcal{S}^2_{2\beta}$. Let $\left(Y_t,Z_t,K_t,U_t\right)_{t \leq T}$ be the unique solution of the RBSDE \eqref{basic equation lower} associated with $\left(\L_T,f,\L\right)$ which exists due to Theorem \ref{Lower existence Thm} in the sense of Definition \ref{Definition of the solution}.  Then,
	\begin{itemize}
		\item[(i)] For each $\sigma \in \mathcal{T}_{[0,T]}$, the state process is a solution of the following optimal stopping problem with $\mathcal{E}^f$-expectation:
		\begin{equation}
			Y_{\sigma}=\esssup_{\eta\in \mathcal{T}_{[\sigma,T]}} \mathcal{E}^f_{\sigma,\eta}\left(\L_{\eta}\right)~\text{ a.s.}

		\end{equation}
		\item[(ii)] \textit{$(\beta,A,\varepsilon)$-optimality}: For every $\sigma \in \mathcal{T}_{[0,T]}$ and each $\varepsilon>0$, the stopping time \eqref{Optila varep Stp} is $(\beta,A,\varepsilon)$-optimal for the stopping problem with $\mathcal{E}^f$-expectation \eqref{Stopping problem}, in the sense that
		\begin{equation}
			Y_{\sigma} \leq \mathcal{E}^f_{\sigma,\eta_{\sigma}^{\varepsilon}}\left(\L_{\eta_{\sigma}^{\varepsilon}}\right)+\mathfrak{c}_{\beta,A,T}\varepsilon~\text{ a.s.}

		\end{equation}
		where the positive constant $\mathfrak{c}_{\beta,A,T}$ is given in the proof of Lemma \ref{Also needed}.
	\end{itemize}

[Definition of arXiv:2606.03079, 'Mean Field Limits for Stochastic, Underdamped Reactive Langevin Dynamics Models'] For $x \in \mathbb{R}^{d}$, let $G(x)$ denote a standard positive mollifier and $G_{\eta}(x)=\eta^{-d} G(x / \eta)$. That is, $G(x)$ is a smooth function on $\mathbb{R}^{d}$ satisfying the following four requirements
 \begin{enumerate}
     \item $G(x) \geq 0$;
     \item $G(x)$ is compactly supported in $B(0,1)$, the unit ball in $\mathbb{R}^{d}$;
     \item $\int_{\mathbb{R}^{d}} G(x) d x=1$;
     \item $\displaystyle\lim_{\eta \rightarrow 0} G_{\eta}(x)=\displaystyle\lim_{\eta \rightarrow 0} \eta^{-d} G(x / \eta)=\delta_{0}(x)$, where $\delta_{0}(x)$ is the Dirac delta function and the limit is taken in the space of Schwartz distributions.
 \end{enumerate}

[Lemma lem:large-enough of arXiv:2608.20537, 'Persistent anisotropy in multi-dimensional\\ branching Brownian motion'] There exists a constant $c(d) > 0$ such that 
  \begin{equation*}
    \inf_{(s,x)\in\partial_{\textnormal{sp}} D} V(s,x;t) \geq c.
  \end{equation*}

