[Proposition 63 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] The following conditions are equivalent:
\item[(i)] $F$ is $\sigma$-demicontinuous;
\item[(ii)] The common $\sigma$-order and $\mathrm{u\sigma o}$ adherence of $\Ba_{F}$ is norm bounded;
\item[(iii)] $\sigma$-order adherence preserves norm bounded sets;
\item[(iii')] $\mathrm{u\sigma o}$ adherence preserves norm bounded sets. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 (Minimum-row slack identity) of arXiv:2609.01570, 'A Proof of Fraenkel's Conjecture'] For every \(a\in A\setminus\{s\}\),
\(d_aa\ge N\),
\begin{equation}
 1-\sum_{a\ne s}\frac1{d_a}
 =\frac{Q-\sum_{a\in A}a}{N}
 +\sum_{a\ne s}\frac{\delta_a}{d_aN},
\end{equation}
and
\begin{equation}
 \delta_a\in\{jQ:j\ge0\}\cup\{2s+jQ:j\ge0\}
 \subset\{0,2s\}\cup[Q,\infty).
\end{equation}
In particular, \(\sum_{a\ne s}d_a^{-1}\le1\).

[Lemme 21 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] Let  $\kappa>0$ and $\Ups\in \mathcal G_{\kappa}$. Then, for $N \geq 2$,

\begin{enumerate}

\item For all $\delta > 0$

$$\Ups^{\otimes N} \Big[ \big\{\bs{x}_N \in \R^N \, : \,  |x_k - x_j| \leq N^{-1 - \delta} \quad \text{ for some } \quad k \neq j \big\} \Big] \, \leq \,  \norm{\varrho}_{ L^{\infty}(\R) } N^{1-\delta} \, .$$

\item There is a constant $C^\prime > 0$ such that

$$\Ups^{\otimes N}\Big[ \Big\{ \bs{x}_N \in \R^N \, : \, 1+ \frac{2}{\ell N} \sum_{\substack{j=1 \\ j \neq k} }^N \ln|x_k - x_j| \, \leq \frac{\kappa}{2}

            \quad \text{ for some } \quad  k \in \intn{1}{ N } \Big\} \Big] \,  \leq \, C^\prime N^{-1}  \, .$$

\item Let  $\delta \geq 2$ and set $\mc{F} = \mc{F}_1 \cap \mc{F}_2 $ where

\begin{align*}

\mc{F}_1 &= \big\{  \bs{x}_N \in \mathbb{R}^N \, : \, |x_k - x_j | \geq N^{-1-\delta} \quad  \forall k \neq j \in  \intn{1}{N} \big\}  \vspace{4mm} \\

\mc{F}_2 &= \Big\{ \bs{x}_N \in \mathbb{R}^N \, : \, 1 \, - \,  \sul{\substack{j=1 \\ j \neq k}}{N} \frac{ \ln|x_k - x_j|  }{ \ln(2\veps_N) }  \, \geq  \, \frac{\kappa}{2} \quad \forall k \in \intn{1}{N} \Big\} \, .

\end{align*}

Then

\begin{align*}

&\Int{\mathbb{R}^N}{} \mathbbm{1}_{ \mc{F} }(\bs{x}_N) \, \ln\bigg( 1 - \sul{\substack{j=1 \\ k \neq j}}{N}  \frac{  \ln|x_k - x_j| }{ \ln(2\veps_N) } \bigg) \,\dd^{N}\Ups(\bs{x}_N) \\

&= \Int{\mathbb{R}}{} \ln\left( 1 - \frac{N-1}{\ln(2\veps_N)} \Int{\mathbb{R}}{} \ln|x - y| \, \dd \Ups(y) \right) \, \dd \Ups(x) + \mathrm{O}(N^{-\frac{1}{2}}) \, .

\end{align*}

\end{enumerate}

[Lemma lem:Kolmo of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Pick $\tau\in\mathcal{T}$, and suppose that for some $\eta>0$ and $c>0$ small enough we have
\begin{equs}
\max_{u\in\{0,1,2\}}\max_{r\in\{0,1\}}\sup_{\mu\in(0,1]}  \E\Big[\Big( \eps^{u(1-c)}\mu^{-|\tau|+uc+r+\eta}\norm{\d_\mu^r\big(K^{\otimes1+\mathfrak{s}(\tau)}_{4,\mu}(\omega\d_\eps^u\xi^{\tau}_{\eps,\mu})\big)}_{L^\infty_tL^1_{s^\tau}}\Big)^P\Big]^{1/P}\lesssim_{P,\tau} 1\,.
\end{equs}
Then, it holds
  \begin{equs}
\max_{u\in\{0,1\}} \E\Big[\Big(\sup_{\mu\in(0,1]}\eps^{u(1-c)} \mu^{-|\tau|+uc+r+2\eta}\norm{K^{\otimes1+\mathfrak{s}(\tau)}_{4,\mu}(\omega\d_\eps^u\xi^{\tau}_{\eps,\mu})}_{L^\infty_tL^1_{s^\tau}}\Big)^P\Big]^{1/P}\lesssim_{P,\tau} 1\,.
\end{equs}

