[Lemma 9 of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] Suppose the assumptions \eqref{eq_ratio}, \eqref{assm3}, and \eqref{assm_gap} hold. Then
there exists sufficiently small constant $\wt c>0$ such that the following estimates hold:
\begin{itemize}
\item[(1)] We have
\begin{equation}
\rho_{\al c}(x) \sim \sqrt{\lambda_+-x}, \quad  \text{ for } \ \ x \in \left[\lambda_+ - 2\wt c,\lambda_+ \right],\ \al\in\{1,2\}.
\end{equation}
\item[(2)] For $z =E+\ii \eta\in S(\wt c,C_0,-\infty)$ and $\al\in\{1,2\}$, 
\begin{equation}
\vert m_{\al c}(z) \vert \sim 1,  \quad  \im m_{\al c}(z) \sim \begin{cases}
    {\eta}/{\sqrt{\kappa+\eta}}, & \text{ if } E\geq \lambda_+ \\
    \sqrt{\kappa+\eta}, & \text{ if } E \le \lambda_+\\
  \end{cases}.
\end{equation}
\item[(3)] There exists a constant $\tau'>0$ such that
\begin{equation}
\min_{\mu} \vert 1 + m_{1c}(z)\wt \sigma_\mu \vert \ge \tau', \quad \min_{i} \vert 1 + m_{2c}(z)\sigma_i  \vert \ge \tau',
\end{equation}
for any $z \in S(\wt c,C_0,-\infty)$.
\end{itemize}
The estimates \eqref{SQUAREROOT} and \eqref{Immc} also hold for $\rho_c$ and $m_c$.

[Lemma 9 of arXiv:2606.11142, 'Strong invariance principles for diffusions, Markov chains and their perturbations.'] Let $P^m_{(x,y)}$ and $P^m_{\epsilon,(x,y)}$ denote the distributions of the vectors $V = (Z_{t_1}, \dots, Z_{t_m})$ and $V^\epsilon = (Z^\epsilon_{t_1}, \dots, Z^\epsilon_{t_m})$, respectively, where $Z_{t_k} = (X_{t_k}, Y_{t_k})$ and $Z^\epsilon_{t_k} = (X^\epsilon_{t_k}, Y^\epsilon_{t_k})$. These vectors consist of random variables sampled at the nodes of either the Euler scheme and its perturbed version, or a diffusion process and its perturbed counterpart, both starting from the initial point $z_0 = (x, y)$. Then, there exists a constant $C > 0$, such that:
\begin{equation*}
\|P^m_{(x,y)} - P^m_{\epsilon,(x,y)}\|_{TV} \le C m \bar{\Delta}_{\epsilon,\gamma,q},
\end{equation*}
where $z = (z_1, \dots, z_m)$, $z_k = (x_k, y_k) \in \mathbb{R}^{2d}$, and $dz = dz_1 \dots dz_m$.

