[Lemma lem:secondhalfsum of arXiv:2412.09145, 'Asymptotic expansions for normal deviations of random walks conditioned to stay positive'] Fix some $a>1$ and $b>0$. Let the sequence $v_k$ be such that
\begin{align}

    |v_k| \le \frac{C\log^d k}{k^a}.
\end{align}
Then there exist polynomials $K_\nu$ of degree $\nu$ such that the following equality holds uniformly in $z$:
\begin{align*}
    \sum_{k=2}^{\lfloor n/2\rfloor} 
        \frac{z^m v_k}{(n-k)^{b}}e^{-\frac{z^2}{2 (n-k)}}
=
    \frac{z^m}{n^b} 
    e^{-\frac{z^2}{2 n}}
    \sum_{\nu=0}^{\lfloor a \rfloor-1}
            \frac{K_{\nu}(z^2/n)}{n^{\nu}}
+
    O\left(\frac{\log^{d+\delta_a} n}{n^{a+b-m/2-1}}\right),
\end{align*}
where $\delta_a:={\rm 1}\{a\in\mathbb N\}$.

[Proposition 20 (Uniform spectral lower bound) of arXiv:2608.30211, '2608.30211'] For $\mu_\varrho$ from \eqref{eq:mu-rho},
\begin{equation}
 \liminf_{\kappa\to\infty}\inf_{\varrho\in[0,1]}
 \bigl(\Lambda_{\kappa,\varrho}-\mu_\varrho\bigr)\geq0.
\end{equation}
As a consequence, with $\mu_*$ from \eqref{eq:uniform-gap}, there is
$\kappa_1(f,\Omega)$ such that
\begin{equation}
 \Lambda_{\kappa,\varrho}\geq\frac{\mu_*}{2}
 \qquad(\kappa\geq\kappa_1,\ \varrho\in[0,1]).
\end{equation}

[Prop 19 of arXiv:2608.03956, 'From Triangular Array Progression\\ to Near-Log-Concave State Transitions'] Let $\mathbf{D}^{(n)}$ be an ordered finite subset of $\R$ with cardinality $|\mathbf{D}^{(n)}| = n+1$ for any $n \geq 2$, and $X^{(n)} : \Omega \rightarrow \mathbf{D}^{(n)}$ be a random variable with probability mass function
\begin{align}
\P\left(X^{(n)} = d^{(n)}_j\right) = \T^{(1)}_{n,j} \notag
\end{align}
for every $d^{(n)}_j \in \mathbf{D}^{(n)}$. Then, the following hold:
\begin{enumerate}
\item $X^{(2)}$, $X^{(3)}$ and $X^{(4)}$ are log-concave random variables with $\mathcal{I}_{|\mathbf{D}^{(n)}|}^{(0)} = \mathcal{I}_{|\mathbf{D}^{(n)}|}$ for $n=2,3,4$
\item $X^{(n)}$ is a \emph{near}-log-concave random variable of degree \emph{1} with $\mathcal{I}_{|\mathbf{D}^{(n)}|}^{(1)} = \mathcal{I}_{|\mathbf{D}^{(n)}|}\setminus\{4\}$ for every $n\geq 5$
\end{enumerate}
given that $\mathcal{I}_{|\mathbf{D}^{(n)}|} = \{2,\ldots,|\mathbf{D}^{(n)}|-1\}$ for every finite $n\geq 2$.

[Prop 26 (Variational identity for the sub-Gamma class) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] Fix $a > 0$. For every $p \in (0,1)$ the feasible spreads $\{\nu > 0 : Y_{p,\nu} \in \SG(1,a)\}$ form the interval $(0, \nu^{\SG}_{\max}(p,a)]$: the supremum in \eqref{eqn:sgnumax} is finite and attained; moreover $\nu^{\SG}_{\max}(p,a) = \nu^{\SG}_{\max}(1-p,a)$. For $c > 0$, every $X \in \SG(1,a)$ satisfies $X \lecx c\Lap$ if and only if
\begin{align}
    (1-p)\,\nu^{\SG}_{\max}(p,a) \le c\left(1 + \log\frac{1}{2p}\right)
    \qquad \text{for every } p \in (0, 1/2].

\end{align}
Consequently
\begin{align}
    c^{\SG}(1,a) = \sup_{p \in (0,1/2]} R^{\SG}(p,a),
    \qquad
    R^{\SG}(p,a) \coloneqq \frac{(1-p)\,\nu^{\SG}_{\max}(p,a)}{1 + \log\frac{1}{2p}},

\end{align}
and the infimum in \eqref{eqn:defcSG} is a minimum: $c^{\SG}(1,a)$ is itself admissible.

[Lem 15 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 2$ and $G=(V,E)$ be a subgraph of $\mathbb Z^d$. Let $J\in (\mathbb R^+)^E$, $\mathsf{h}\in \mathbb R^V$, and $A\subset V$. Then, for every $x\in V$,
\begin{equation}
	\partial_{\mathsf{h}_x}\langle \sigma_A\rangle_{G,J,\mathsf{h}}=\langle \sigma_A;\sigma_x\rangle_{G,J,\mathsf{h}},
\end{equation}
and for every $uv\in E$,
\begin{equation}
	\partial_{J_{uv}}\langle \sigma_A\rangle_{G,J,\mathsf{h}}=\langle \sigma_A;\sigma_u\sigma_v\rangle_{G,J,\mathsf{h}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 34 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $\mc{K}\subset\subset \C$. Let $\phi_{\mu_N}$ be as in \eqref{Expression simplifiée du potentiel logarithmique en fonction du déterminant} and $\phi_{\widetilde{\mu}_N}$ be as in \eqref{Expression simplifiée du potentiel logarithmique en fonction du déterminant - 2}. Let $\beta>0$ be as in Proposition \ref{Différence des potentiels loga entre mu_N tilde et mu}. Then, there exists $C_0>0$ such that for all $z\in \mc{K}$, 
    \begin{equation}
        \begin{split}
            \phi_{\mu_N}(z) &\leq \phi_{\widetilde{\mu}_N}(z)+\mc{O}(N^{-\vartheta}\log(\delta N^{-\beta}))+\mc{O}(N^{-\vartheta})\\
            &+\mc{O}\pr{N^{-\vartheta}\log\pr{1+C_0N^{\beta-\varrho\eta/2}\delta^{-1}}}+\log\pr{1+2C_0N^{-\varrho\eta/2}\alpha^{-1/2}}\\
            &+\mc{O}\pr{\alpha^{{\kappa_2}}\log\pr{1+C_0N^{\beta-\varrho\eta/2}\delta^{-1}}}
        \end{split}

    \end{equation}
    with probability $1-o(1)$, and
    \begin{equation}
        \begin{split}
            \phi_{\mu_N}(z)&\geq \phi_{\widetilde{\mu}_N}(z)+\mc{O}(N^{-\vartheta})+\mc{O}(\alpha^{{\kappa_2}})+\mc{O}(\alpha^{-1/2}N^{-\varrho\eta/2})\\
            &+\mc{O}(N^{-\vartheta}\log(\delta N^{-\beta}))+\mc{O}(\alpha^{{\kappa_2}}\log(\delta N^{-\beta}))
        \end{split}

    \end{equation}
    with probability $\geq 1-o(1)$.

