	for all $w\in \Psi_{N,n,T}(\underline u)$,
	\begin{equation}

		d_{\mathrm{LP}}(L[w], \mu)\leqslant 4h\Big((1-\varepsilon-\delta)\frac{1-\delta}{1+r\delta}\Big)+3\delta=:f(\varepsilon, \delta).
	\end{equation}

