body:
[Theorem th consta of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] For any $t_0\in (0,T]$, there exists a positive constant $\mathcal{C}=\mathcal{C}(t_0)$ such that for some generic constant $\gamma\in (0,1)$ (which is independent of $t_0$) and for any $M>0$, for all $ y_0, \hat y_0\in U_{M,0} $, it holds that

\begin{equation}
| y(t_0)-\hat y(t_0)|_{L^2_{\mathcal{F}_{t_0}}(\Omega;L^{2}(G))} \leq
\mathcal{C} M^{1-\gamma}| y(T)-\hat y(T)|_{L^2_{\mathcal{F}_{T}}(\Omega;H^{1}(G))}^{\gamma},
\end{equation}

where $y(\cdot)$ (resp. $\hat y(\cdot)$) is the solution to (sp-eq1 of the paper) with respect to the initial datum $y_0$ (resp. $\hat y_0$). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma BBM-F-KPP-Connection of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] For a measurable function $\phi:\mathbb{R} \to [0,1]$, let
\begin{equation}
u_\phi(t,x) = 1 - \mathbb{E}[\prod_{k=1}^{n(t)}\{1-\phi(x- \chi_k(t))\}].
\end{equation}
Then $u = u_\phi$ solves the following F-KPP equation
\begin{equation}
\partial_t u = \frac{1}{2}\partial_x^2 u + u- u^2
\end{equation}
 with the initial condition $u(0,x) = \phi(x)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 48 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $G=(V,E)$ be a subgraph of $\mathbb Z^d$ and let $A\subset V$ be a finite even subset of $G$. Let $\beta>0$. Let $\n$ be distributed according to $\mathbf P_{G,\beta}^{A}$. Let $(\omega_e)_{e\in E(\mathbb Z^d)}$ be an independent Bernoulli percolation with parameter $1-\exp(-\beta)$. For each $e\in \mathbb Z^d$, we define
\begin{equation}
	\eta_e:=\max(\mathds{1}_{\n_e>0},\omega_e).
\end{equation}
Then, the law of $\eta$ is $\phi_{G,\beta}^0[\:\cdot\:|\: \mathcal F_A]$. As a consequence, if $\mathcal A$ is an increasing event, one has
\begin{equation}
	\mathbf P^{A}_{G,\beta}[\mathcal A]\leq \phi_{G,\beta}^0[\mathcal A\: | \: \mathcal F_A].
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:eigenfunction-square-laplacian of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] The square $\phi^2$ belongs to $H_0^1(D)$ and satisfies
\begin{equation}
 L_0(\phi^2)
 =2\Lambda\phi^2M_x-2\Gamma_\mathcal E(\phi)\,\mathcal L^2
 \qquad\text{in }\mathcal D'(D).
\end{equation}
Equivalently, for every $\zeta\in C_c^\infty(D)$,
\begin{equation}
 \mathcal E(\phi^2,\zeta)
 =2\Lambda\int_D\zeta\phi^2\,dM_x
  -2\int_D\zeta\Gamma_\mathcal E(\phi)\,dz.
\end{equation}

[Lemma lem:FJ2 of arXiv:2412.03366, 'Regularity of Weighted Tensorized Fractional Brownian Fields and associated function space'] Let $1 \le p \le \infty$  and $\ell_1, \ell_2, m_1, m_2$ be integers such that $\ell_1 \le m_1$ and $\ell_2 \le m_2$. Assume that $g_{\bar{k}}$, $\bar{k} \in \mathbb{Z}^2$, are functions satisfying the following inequality 
\begin{equation}
\forall {\boldsymbol{x}} \in \mathbb{R}^2, \, \vert g_{\bar{k}}(\boldsymbol{x}) \vert \le \frac{C}{\left( 1+2^{\min(\ell_1,m_1)}|x_1 - 2^{-m_1}k_1 \vert \right)^2 \left( 1+2^{\min(\ell_2,m_2)}|x_2 - 2^{-m_2}k_2 \vert \right)^2}.
\end{equation}
for some $C>0$. If one sets  
$$
F = \sum_{\bar{k} \in \mathbb{Z}^2} d_{\bar{k}} g_{\bar{k}},
$$
then
\begin{equation}
\Vert F \Vert_{L^p} \le C \, 2^{-(m_1+m_2)/p} 2^{m_1-\ell_1}2^{m_2 - \ell_2} \left( \sum_{\bar{k} \in \mathbb{Z}^2} \vert d_{\bar{k}} \vert^p \right)^{1/p}.
\end{equation}

[Defn def:valid of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] A bounded, simply connected domain $D$ is \emph{valid} if
    \begin{enumerate}[label=(\roman*)]
        \item $\dim_M(\partial D)<2-\alpha^2/2$, when considering $\field{e^{i\alpha\phi}}$ or $\cos(\alpha\phi)$;
        \item $\mathrm{Leb}(\partial D)=0$, when considering $:\! \sin(\alpha\phi) \!: $.
    \end{enumerate}

[Proposition prop:parity of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] A geodesic Leech labeling satisfies
\begin{equation}
  \nu_A+\nu_B+\nu_A(m-\nu_A)-\chi_A+\chi_B=\ceil{N/2}.
\end{equation}
Moreover, $\chi_A$ and $\chi_B$ are even.

[Cor 80 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] \begin{align*}

\mathbbm{1}_{i \leq j} \sum_{\ell=i}^j \prod_{m=\ell+1}^N (x_i - x_m) \prod_{\substack{m = \ell \\ m \neq j}}^N \frac{1}{x_j - x_m}

= \delta_{ij} & & i,j=1,\dots, N\, .

\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] Assume (eqDou2023Assumtion1 of the paper), (eqDou2023Assumtion2 of the paper), and that $ \alpha \in (0,1] $ is a constant.
For any given $\widehat{G} \subset \subset G$ and $\varepsilon \in (0, \frac{T}{2}) $, let $ \gamma \in (0,1) $ as stated in (thmProb9 of the paper).
Then there exists a constant $ \mathcal{C} > 0 $  such that  for all $ \delta \in (0,1) $,
\begin{align*}
|y_{\tau} - y^{*}|_{L^{2}_{\mathbb{F}}(\varepsilon,T-\varepsilon;H^{1}(\widehat{G}))}
\leq
\mathcal{C} (1 + |y^{*}|_{L^{2}_{\mathbb{F}}(0,T;H^{2}(G))}) \delta^{\alpha \gamma}
,
\end{align*}
where $ y_{\tau} $ is the minimizer of the functional (eqDou2023Fucntional of the paper) with the regularization parameter  $ \tau = \delta^{2 \alpha} $.

