body:
[Definition def:NBP-Wishart of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let $H\in\mathbb{C}^{N\times M}$ be a $N\times M$ matrix, and let $x,y$  respectively denote  elements in $[N], [M]$.  For each integer $n\ge0$, define the nonbacktracking power matrix $V_n$ (viewed as an operator) as follows:

\paragraph{Even case ($n=2m$):}
\begin{itemize}
  \item $V_{2m}:\,\mathbb{C}^{[N]}\to\mathbb{C}^{[N]}$, with
  \begin{equation}
  (V_{2m})_{x_0x_{2m}} = \sum_{y_1,x_2,\dots,y_{2m-1}}
  \Bigl[\prod_{i=0}^{2m-2}\mathbf{1}(\zeta_i\neq\zeta_{i+2})\Bigr]\,
  H_{x_0y_1}H^*_{y_1x_2}\cdots H^*_{y_{2m-1}x_{2m}},
  \end{equation}
  summing over $y_{2k+1}\in[M],\,x_{2k}\in[N]$. Here $\zeta_i$ denotes $x_i$ or $y_i$.
  \item $V_{2m}:\,\mathbb{C}^{[M]}\to\mathbb{C}^{[M]}$, with
  \begin{equation}
  (V_{2m})_{y_0y_{2m}} = \sum_{x_1,y_2,\dots,x_{2m-1}}
  \Bigl[\prod_{i=0}^{2m-2}\mathbf{1}(\zeta_i\neq\zeta_{i+2})\Bigr]\,
  H^*_{y_0x_1}H_{x_1y_2}\cdots H_{x_{2m-1}y_{2m}},
  \end{equation}
  summing over $x_{2k+1}\in[N],\,y_{2k}\in[M]$.
\end{itemize}

\paragraph{Odd case ($n=2m+1$):}
\begin{itemize}
  \item $V_{2m+1}:\,\mathbb{C}^{[N]}\to\mathbb{C}^{[M]}$, with
  \begin{equation}
  (V_{2m+1})_{x_0y_{2m+1}} = \sum_{y_1,x_2,\dots,x_{2m}}
  \Bigl[\prod_{i=0}^{2m-1}\mathbf{1}(\zeta_i\neq\zeta_{i+2})\Bigr]\,
  H_{x_0y_1}H^*_{y_1x_2}\cdots H_{x_{2m}y_{2m+1}},
  \end{equation}
  summing over $y_{2k+1}\in[M],\,x_{2k}\in[N]$.
  \item $V_{2m+1}:\,\mathbb{C}^{[M]}\to\mathbb{C}^{[N]}$, with
  \begin{equation}
  (V_{2m+1})_{y_0x_{2m+1}} = \sum_{x_1,y_2,\dots,y_{2m}}
  \Bigl[\prod_{i=0}^{2m-1}\mathbf{1}(\zeta_i\neq\zeta_{i+2})\Bigr]\,
  H^*_{y_0x_1}H_{x_1y_2}\cdots H^*_{y_{2m}x_{2m+1}},
  \end{equation}
  summing over $x_{2k+1}\in[N],\,y_{2k}\in[M]$.
\end{itemize}
We also set 
\begin{equation}
V_0 = \begin{cases}I_N:\mathbb{C}^{[N]}\to\mathbb{C}^{[N]},\\
I_M:\mathbb{C}^{[M]}\to\mathbb{C}^{[M]},\end{cases}
\quad
V_1 = \begin{cases}H:\mathbb{C}^{[N]}\to\mathbb{C}^{[M]},\\
H^*:\mathbb{C}^{[M]}\to\mathbb{C}^{[N]},\end{cases}
\quad
V_n = 0~(n<0).
\end{equation}

[Thm 4 of arXiv:2607.06242, 'Exponential mixing and Freidlin--Wentzell large deviation principle for Markov cocycles'] Assume that there is a lower semicontinuous function $U: E\to[0,\infty)$ and a measurable function $S:E\to[0,\infty]$ such that for any given $x,y\in E$ there exist progressively measurable processes $X_t^{\s,x}$ and $Y_t^{\s,x,y}$
      (denoted $X_t^{\s}$ and $Y_t^{\s}$ for simplicity)
      such that the following conditions hold:
      \begin{enumerate}[label=(H\arabic*)]
        \item There is a lower semicontinuous function $V: E\to \mathbb R_+$ and constant $\gamma>0$ such that
        \begin{align*}
          P_t^{\sigma}V(x) + \gamma \int_0^tP_s^{\sigma}V(x)ds\leq V(x) + \int_0^tK(\beta_s\s)ds
        \end{align*}
        where $K\in L^1(\Sigma,m)$ is nonnegative, and for any $M>0$, $U, p$ are bounded on $\{V\leq M\}$ and $\{V\leq M\}\times \{V\leq M\}$. 
        \item There exist $\zeta,\kappa>0$ such that for all $t\geq 0$,
        \begin{align*}
          p(X_t^{\s},Y_t^{\s})\leq p(x,y)\exp\left(-\zeta t + \kappa\int_0^tS(X_s^{\s})ds\right).
        \end{align*}
        \item There exist $\varpi>0$ and $b\in L^1(\Sigma,m)$ such that 
        \begin{align*}
          U(X_t^{\s}) + \varpi\int_0^tS(X_s^{\s})ds \leq U(x)+ \int_0^tb(\beta_s\s)ds + M_t^{\s},
        \end{align*}
        where $M_t^{\s}$ is a continuous local martingale with $M_0^\sigma=0$ and
        \[d\langle M^{\s}\rangle_t\leq b_1S(X_t^{\s})dt+b_2(\b_t\s)dt \quad \text{ for }t\geq 0,\]
        where  $b_1>0$ is a constant and  $b_2\in L^1(\Sigma,m)$ is nonnegative. Furthermore, 
        \begin{align*}
          \zeta>\frac{\kappa}{\varpi} \int_{\Sigma}b d m.
        \end{align*}
        \item The law of $\left(X_t^{\s}\right)_{t\in\mathbb R_+}$ coincides with $\mathbf P_{\s,x}$ and for any $\d\in(0,1]$, there exist a constant $C_{\d}>0$ and  a measurable function $\bar{\varepsilon}_{\d}:\mathbb{R}_+\to (0,1)$ which is non-increasing, such that for any $t\geq 0$, 
        \begin{align*}
          d_{TV}\left(\mathcal{L}(Y_t^{\s}), P_{t}^{\s}(y,\cdot)\right)\leq C_{\d}\left(M_{\d}(t,\s)\right)^{1/2}, \,\quad d_{TV}\left(\mathcal{L}(Y_t^{\s}), P_{t}^{\s}(y,\cdot)\right)\leq 1-\bar{\varepsilon}_{\d}(M_{\d}(t,\s)),
        \end{align*}
        where 
        \[ M_{\d}(t,\s): =\mathbf E\left(\int_0^tb_3(\beta_s\s)p(X_s^{\s},Y_s^{\s})ds\right)^{\d},\]
        and $b_3\in L^1(\Sigma,m)$ is nonnegative. 
      \end{enumerate}
      Then there is a unique $\beta_t$-invariant stationary measure 
      $(\G_\sigma)_{\s\in \Sigma}$
      of $P_t^{\s}$  such that $\G_\sigma P_t^\sigma=\G_{\beta_t \sigma}$ $m$-a.s. for all $t\geq 0$. Furthermore, there exist $\Sigma_0\subset\Sigma$ with $m(\Sigma_0)=1$, $T>0$ and $\l>0$ such that the following properties hold.
      \begin{itemize}
        \item Pullback exponential stability: for every $\sigma\in \Sigma_0$ and $x\in E$, there is $C_{\lambda}(\sigma,x)>0$ such that, for all $t\geq 0$,
        \begin{align*}
          \W_{\rho\wedge 1}\left(\delta_x P_t^{\beta_{-t} \sigma}, \G_\sigma\right) \leq C_\lambda(\sigma,x)e^{-\lambda t}.
        \end{align*}
        \item Forward exponential stability: for each fixed $r\in[0,T)$, there is a full measure set $\Sigma_r\subset\Sigma_0$ such that, for every $\sigma\in \Sigma_r$ and $x\in E$, there is $C_{\lambda,r}(\sigma,x)>0$ such that, for all $n\geq0$,
        \begin{align*}
          \W_{\rho\wedge 1}\left(\delta_x P_t^\sigma, \G_{\beta_t \sigma}\right) \leq C_{\lambda,r}(\sigma,x)e^{-\lambda t},\qquad t=nT+r.
        \end{align*}
      \end{itemize}
      Here $\W_{\rho\wedge 1}$ is the Wasserstein distance induced by the metric $\rho\wedge 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Einaiiagapi of arXiv:2412.09290, 'Asymptotics of Harish-Chandra transform and infinitesimal freeness'] Let $A$ be a random Hermitian matrix of size $N$. Assume that for every finite $r$ one has
  \begin{equation}
    \lim_{N \rightarrow \infty} N \left( \frac{1}{N} \log \mathbb{E}[H \text{}
    C (x_1, \ldots, x_r, 0^{N - r} ; \lambda_1 (A), \ldots, \lambda_N (A))] -
    \sum_{i = 1}^r \Psi (x_i) \right) = \sum_{i = 1}^r \Phi (x_i), 
  \end{equation}
  where $\Psi, \Phi$ are smooth functions in a (complex) neighborhood of $0$ and the
  above convergence is uniform in a (complex) neighborhood of $0^r$. Then one has the following     limit:
  \begin{equation}
    \lim_{N \rightarrow \infty} N \left( \frac{1}{N^{k + 1}} \mathbb{E} \left[
    \sum_{i = 1}^N \lambda_i^k (A) \right] -\ensuremath{\boldsymbol{\mu}}_k \right)
    =\ensuremath{\boldsymbol{\mu}}'_k, 
  \end{equation}
  where $(\ensuremath{\boldsymbol{\mu}}_k)_{k \in \mathbb{N}}$ are given by ((topg of the paper)) and
  \begin{equation}
    \ensuremath{\boldsymbol{\mu}}'_k := \sum_{m = 0}^{k - 1} \frac{k!}{m! (m + 1) !
    (k - m - 1) !}  \left. \frac{\mathrm{d}^m}{\mathrm{d} x^m} ((\Psi' (x))^{k - m
    - 1} \Phi' (x)) \right|_{x = 0} . 
  \end{equation}

[Lemma pitdef of arXiv:2608.07236, 'Negative association of Busemann functions \\in exponential last-passage percolation'] Suppose $\textup{\texttt{slope}}_m (h)> \textup{\texttt{slope}}_{m+1} (h)$ and recall $\sigma^m$  defined in (equation qmap of the paper).
We then have the following identities:
\begin{align}
(\sigma^{m} h)^{m+1} (x) &= h^{m+1}(x) + \sup_{z\leq x} \{h^{m}(z) - h^{m+1}(z-1)\} - \sup_{z\leq 0} \{h^{m}(z) - h^{m+1}(z-1)\},  \\
(\sigma^{m} h)^{m} (x) &= h^{m}(x) - \sup_{z\leq x} \{h^{m}(z) - h^{m+1}(z-1)\} +  \sup_{z\leq 0} \{h^{m}(z) - h^{m+1}(z-1)\}.
\end{align}

