body:
[Proposition 4 of arXiv:2609.02218, 'Neumaier graphs of coherent rank five'] Let $n\geqslant8$ and $m\geqslant3$. 
Suppose $H$ is a Hadamard matrix of order $n$ with first row $h_1=\one^\transpose$, and let $\bL$ be a family of $m$ MALS of order $n-1$. 
Let $A$ be the adjacency matrix of $\Gamma(H;\bL)$.
Then
\[
 A^2
 =
 \left ((m-1)\frac{n(n-1)}2+n(n-2)\right )A_0+\mu_{A_1}A_1+\lambda_{A_2}A_2
 +\mu_{A_3}A_3+\lambda_{A_4}A_4,
\]
where
\begin{equation}
\begin{aligned}
 \lambda_{A_2}
 &=(m-2)\frac{n^2}{4}+n(n-2),
 &\lambda_{A_4}
 &=(m-1)\frac{n(n-1)}4+n(n-3),\\
 \mu_{A_1}
 &=(m-1)\frac{n(n-2)}4+n(n-2),
 &\mu_{A_3}
 &=(m-2)\frac{n(n-2)}4+n(n-2).
\end{aligned}
\end{equation}
Furthermore,
$\Gamma(H;\bL)$ is edge regular if and only if $m=n-3$.

[Theorem 10 (\cite{panchenko2005question}) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Let
\begin{equation*}
    0=m_0\le m_1\le\cdots\le m_K=1\qquad\text{and}\qquad 0=\widehat q_0\le \widehat q_1\le\cdots\le \widehat q_K\le \widehat q_{K+1}=1.
\end{equation*}
Let $\Phi$ and $\xi$ be smooth, convex, even functions, with $\Phi$ of moderate growth. Let $z_0,\ldots,z_K$ be independent centered Gaussian random variables with
\begin{equation}
    \E z_r^2=\xi'(\widehat q_{r+1})-\xi'(\widehat q_r).
\end{equation}
Define $\Phi_{K+1}=\Phi$ and, recursively,
\begin{equation}
    \Phi_r(x)
    =
    \begin{cases}
    \displaystyle
    \frac1{m_r}
    \log \E_{z_r}e^{m_r\Phi_{r+1}(x+z_r)}, & m_r>0,\\[2mm]
    \displaystyle
    \E_{z_r}\Phi_{r+1}(x+z_r), & m_r=0.
    \end{cases}
\end{equation}
Here $\E_{z_r}$ denotes expectation over $z_r$ only. Put
\begin{equation}
    V_r(x,z_r)
    = e^{m_r(\Phi_{r+1}(x+z_r)-\Phi_r(x))}.
\end{equation}
For an external field $h\in\R$, define
\begin{equation}
    Z=h+z_0+\cdots+z_K,
    \qquad
    Z_r=h+z_0+\cdots+z_{r-1}, \qquad\text{and}\quad W_r=V_r(Z_r,z_r).
\end{equation}
For $1\le l\le K$, set
\begin{equation}

    U_l^{\mathrm P}
    =
    \E\left[
        W_1\cdots W_{l-1}
        \left(
            \E\left[W_l\cdots W_K\Phi'(Z)
            \mid z_0,\ldots,z_{l-1}\right]
        \right)^2
    \right].
\end{equation}
Then $U_l^{\mathrm P}$ is nondecreasing in each mass coordinate $m_j$, for each $j\in\{1,\dots,K\}$.

Moreover, each $\Phi_r$ is convex and even, $\Phi_r'\in\mcCp$, and the map
\begin{equation}

    g\mapsto \E_{z_r}V_r(x,z_r)g(x+z_r)
\end{equation}
sends $\mcC$ into $\mcC$ and sends $\mcCp$ into $\mcCp$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Ppn 177 (estimates for $\barvD$ and $\barvD^\frozen$) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Let $\barvD$ and $\barvD^\frozen$ be as specified by Definition~\ref{d:barD}.
 For $N$ large enough, it holds for all
 $q_0\le s < t\le1$ that
	\beq
	\frac{\E[( \bar{D}^{\RomI}(t)-\bar{D}^{\RomI}(s))^2]}
		{(t-s)^2}
	\le L^{O(1)}\,,\eeq
as well as (with $\BUCKETS$ as in \eqref{e:buckets.scB})
	\beq
	\sum_{\sigma\in\{\RomII,\RomIII,\Ising\}}
	\E\sup\bigg\{
	\Big|\bar{D}^\sigma(t)\Big| : 0\le t\le 1\bigg\}
	\le\bigg( \frac{L^{O(1)} \BUCKETS}{N\delta}
	\bigg)^{1/2}\,.
	\eeq
The same estimates hold with $\barvD^\frozen$ in place of
$\barvD$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma closedness conditions of arXiv:2609.02073, 'Existence of closed non-planar $p$-elasticae'] The following are equivalent:
    \begin{enumerate}
        \item[(i)] The curve $\gamma_{\lambda,C^2}\in W^{2,p}(\R/\Z;\R^3)$ is a closed non-planar $p$-elastica.
        \item[(ii)] The open curve $\tilde \gamma_{\lambda,C^2}\in W^{2,p}(0,1;\R^3)$ is a  non-planar $p$-elastica with $\tilde \gamma_{\lambda,C^2}(0)=\tilde \gamma_{\lambda,C^2}(1)$ and $\tilde \gamma_{\lambda,C^2}'(0)=\tilde \gamma_{\lambda,C^2}'(1)$.
        \item[(iii)] The parameter couple $(\lambda,C^2) \in S$ satisfies $\Delta z(\lambda,C^2)=0$ and $\Delta \theta(\lambda,C^2) \in 2\pi \Q$.
    \end{enumerate}

