[Dfn def:Bregdiv of arXiv:2506.01746, '\bf Optimal Bregman quantization: existence and uniqueness of optimal quantizers revisited'] Let $F:U\to \mathbb{R}^d$ be a continuously differentiable,  strictly convex function defined on a  {\em convex} $U\subset \mathbb{R}^d$. The convex $U$ will be assumed {\em open} in all what follows, except specific mention  (see e.g. Proposition~(prop:existence of the paper)$(a)$). The $F$-Bregman divergence of $x\!\in U$ with respect to (w.r.t.) another point $\xi\!\in U$ is defined by 
\begin{equation}
 \forall\, x\!\in U,\quad \phi_{_F}(\xi,x)= F(\xi)-F(x) -\langle \nabla F(x) | \xi- x \rangle\ge 0.
\end{equation}
Moreover $\phi_{_F}(\xi,x)=0$  if and only if $\xi=x$ since $F$ is strictly convex.

[Lemma 10 of arXiv:2605.17494, 'Generalized intersection exponents and local cut points for three-dimensional Brownian loo'] Let $W_1= A_{\frac{1}{20}} \cap \mathcal{A}(0,2)$ and $W_2= A_{\frac{1}{18}} \cap \mathcal{A}(-\frac{1}{10},\frac{21}{10})$ be two wedges with $W_1 \subset W_2$. There exists a universal constant $C$ such that for any $x_1 \in W_1 \cap S_0$, $x_2 \in W_1 \cap S_2$,
    \begin{equation}
    \Pb^{x_1}(B[0, \sigma_2] \in W_2 \mid B(\sigma_2)=x_2) \ge C,    
    \end{equation}
    where $\sigma_2$ is the last time $B$ visits $S_2$.

[Definition 19 of arXiv:2609.01190, 'Rough differential equations on manifolds via natural bundles'] Let $m,n\in \Nsf$ and let $M$ be an $m$-dimensional manifold. A rough velocity field $f:M\to R_n^2M$ is called \emph{admissible} if, for every $p\in M$, there exists a chart $(U,x)$ around $p$ such that the coordinate representation $(f_\tau^i)$ of $f$ in the induced chart $(\overline{U},\overline{x})$ on $R_n^2M$ satisfies 
	\begin{equation}

		\left(
			\frac{\partial f^i_{\tb}}{\partial x^j}f^j_{\ta}
		\right)(p) 
		= f_{\tab}^i(p) + f_{\tc}^i(p)
	\end{equation}
for every $i\in \llbracket 1,m \rrbracket$ and every $\alpha,\beta\in \llbracket 1,n \rrbracket$.

[Definition 4 of arXiv:2609.01098, 'Gaussian upper bounds for averaged heat semigroups on graphs'] The {\em Sobolev inequality} $S_\phi(n,r_1,r_2)$ holds in $B$, if for all $x\in B$, $r\in[r_1,r_2]$ {and $u\in\cC_{c}(B_x(r))$}, we have
\begin{equation*}
\frac{m(B_x(r))^{\frac{2}{n}}}{\phi r^2}
\Vert u\Vert_{\frac{2n}{n-2}}^2
\leq \cE(u)+\frac{1}{r^2}\Vert u\Vert_2^2.
\end{equation*}

[Lemma eq:local-mass of arXiv:2607.14087, 'Stochastic Domination of Gaussian Maxima: A Resolution of the Weak Simplex Conjecture'] \label[lemma]{lem:local-centering}
For $a,b,s$ as above,
\begin{align}
 \int f_{a,b}\,d\gamma_1
 &=e^{a^2/2}\Phi(s),\\
 \int zf_{a,b}(z)\,d\gamma_1(z)
 &=e^{a^2/2}\bigl(a\Phi(s)-\varphi(s)\bigr).

\end{align}
Consequently, the first moment vanishes if and only if
\begin{equation}
  a=r(s):=\frac{\varphi(s)}{\Phi(s)},
  \qquad
  b=H(s):=s+r(s).
\end{equation}

[Thm main of arXiv:2608.30048, 'Counterexamples for generalizations of the non-elliptic Schr\"{o}dinger maximal operator'] Let $n,k\geq 2$. Let $P\in \mathbb{R}[X_1,...,X_n]$ be a polynomial of degree $k$ with leading form 
  \begin{align}
        P_k=
        Q_k+X_1Q_{k-1}+X_1^dQ_{k-d}+X_1^{d+1}Q_{k-(d+1)}+\cdots +X_1^kQ_0,
    \end{align}
    where $2\leq d \leq k$ and $Q_{k-i}\in \mathbb{R}[X_2,...,X_n]$ is a form of degree $k-i$ for all $i=0,1,d,...,k$. Assume $Q_{k-1}$ is not identically zero. Define $s_d=(d-1)/2d$ for $2\leq d \leq k$ and $s_\infty=1/2$.
Suppose there exists a constant $C_s$ such that
    \begin{align}
        \|\sup_{0<t<1}|T_t^Pf|\|_{L^1(B_n(0,1))} \leq C_s \|f\|_{H^s(\mathbb{R}^n)}, \quad \text{for all } f\in H^s(\mathbb{R}^n).
    \end{align}
Then $s\geq s_\infty$ if $Q_{k-i}$ is identically zero for all $d\leq i \leq k$, and otherwise $s\geq s_d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:edge-number of arXiv:2608.23135, 'Graph distance and effective resistance of the random walk trace in four and five dimensio'] There exists $C<\infty$ such that
\begin{equation*}

\mathbb{P}\bigl(\#\mathcal E_{\mathrm{RW}}\,\mathbb{E}[\Delta_n]
   \ge C\sqrt\delta\,n(\log n)^{-3/2}\bigr)
\le C\sqrt\delta\log(\delta^{-1})+o_n(1).
\end{equation*}

