body:
[Theorem 13 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ and let $(X_N=I_p(f_N), N\geq 1)$ with $f_N\in H^{\odot p}$ 
		for all $N\geq 1$. Assume that $(X_N, N\geq 1)$ satisfies \eqref{c1}. 
		Let $Y_N=I_q(g_N)$ with $q=ap$ for some integer $a\geq 1$. Assume that
		\begin{equation*}
			(Y_N, Y_{1,N}, \ldots, Y_{a-1,N}) \xrightarrow[N\to\infty]{(d)} 
			(Y, Y_1, \ldots, Y_{a-1}),
		\end{equation*}
		and that there exists $\rho_a\in\mathbb{R}$ such that
		\begin{equation*}
			\mathbf{E}[Y_{a,N}] \xrightarrow[N\to\infty]{} \rho_a.
		\end{equation*}
		Then $(X_N, Y_N)\xrightarrow[N\to\infty]{(d)}(Z,Y)$, where 
		$Z\sim N(0,\sigma^2)$ and the characteristic function of $(Z,Y)$ 
		is given by, for every $(u,v)\in\mathbb{R}^2$,
		\begin{equation}
			\varphi(u,v) 
			= e^{-\sigma^2 u^2/2}
			\sum_{\ell=0}^\infty \frac{u^\ell}{\ell!}
			\sum_{\substack{m=(m_1,\ldots,m_{a-1})\in\mathbb{N}^{a-1}\\ 
					|m|\leq \ell}}
			B_{\ell,m}(v)\,
			\mathbf{E}\!\left[\prod_{r=1}^{a-1}Y_r^{m_r}\, e^{ivY}\right],
		\end{equation}
		where the coefficients $B_{\ell,m}(v)$ are defined by the following recursion:
		\begin{equation}
			B_{0,(0,\ldots,0)} = 1, \qquad B_{\ell,m} = 0 
			\text{ if any component of $m$ is negative or } |m|>\ell,
		\end{equation}
		and
		\begin{equation}
			B_{\ell+1,m} = -\frac{v}{p}\,B_{\ell,m-e_1} 
			+ \frac{i}{p}\sum_{s=1}^{a-2}(m_s+1)\,B_{\ell,m+e_s-e_{s+1}}
			+ \frac{i\rho_a}{p}\,(m_{a-1}+1)\,B_{\ell,m+e_{a-1}}.
		\end{equation}
		The series \eqref{fib} converges absolutely for every $(u,v)\in\mathbb{R}^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 18 (Transfer from a represented sequence to its Fock terminal) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] Fix $Q,d<\infty$.  For every $n$, let $W_n$ be isonormal over $H_n$ and
let
\begin{equation}
 Z_{n,a}=\sum_{q=1}^{Q}I_q^{W_n}(z_{n,a,q}),
 \qquad
 \sup_n\sum_{a,q}q!\norm{z_{n,a,q}}^2<\infty.

\end{equation}
Put
$
 \zeta_{a,q}=[z_{n,a,q}]_{\mathcal U}\in\cH_q
$
and, on the Gaussian space over $\bigoplus_{s\le Q}\cK_s$, define
\begin{equation}
 Z_a^{\mathrm{FF}}
 =\sum_{q=1}^{Q}\mathbb U_q^{-1}\zeta_{a,q}.

\end{equation}
Then the represented packet itself, and not merely some spatial
realization of it, satisfies
\begin{equation}
 \Ulim \E\varphi(Z_n)=\E\varphi(Z^{\mathrm{FF}})

\end{equation}
for every bounded Lipschitz function $\varphi:\R^d\to\R$.

The transfer is compatible with the finite forest register.  More
precisely, let $G$ be such a network with $L$ open legs and put
$x_v=\zeta_{a_v,q_v}$ when its input at $v$ is $z_{n,a_v,q_v}$.  Then
\begin{equation}
 [C_{G,n}((z_{n,a_v,q_v})_{v\in V})]_{\mathcal U}
 =C_G^{\mathrm{FF}}
 \bigl((\mathbb U_{q_v}^{-1}\zeta_{a_v,q_v})_{v\in V}\bigr)
 \quad\text{in }\cT_L^{\mathcal U}.

\end{equation}
For $L=0$ this is the scalar complete-block pairing value; for $L>0$
the unpaired complete primitive blocks form the raw labeled output.  The
assertion is multilinear and therefore also holds for finite linear
combinations of networks.

[Lemma 12 of arXiv:2609.01346, '2609.01346'] For every $\delta_0\in(0,\delta_*)$ there is
$C_e=C_e(n,k,\delta_0)$ such that
\begin{equation}
 r_\delta(s_1(\delta))\leq C_e
 \quad\text{for all }\delta\in\sS\cap[\delta_0,\delta_*).
\end{equation}

