[Defn def:-2 of arXiv:2411.13403, 'Path weighting method for spot sensitivities and its variance reduction'] For any $\epsilon_{1}>0$ and $\epsilon_{2}>0$, the
\emph{covariance inflated process} $S_{t}^{\epsilon_{1},\epsilon_{2}}$
is defined to be the process given by 
\begin{equation}
\begin{aligned}S_{t_{i+1}}^{\epsilon_{1},\epsilon_{2}} & =H_{i}(S_{t_{i}}^{\epsilon_{1},\epsilon_{2}},\sqrt{\Delta t_{i+1}}Z_{i+1}),\;i\ge1,\\
S_{t_{1}}^{\epsilon_{1},\epsilon_{2}} & =H_{1}^{\epsilon_{1},\epsilon_{2}}(s,\sqrt{\Delta t_{1}}Z_{1}),
\end{aligned}

\end{equation}
where the functional $H_{1}^{\epsilon_{1},\epsilon_{2}}$ is obtained
by replacing the volatility curve (for the time step $[t_{0},t_{1})$
only) $\sigma_{0}^{(k)}(s^{(k)})=\sigma^{(k)}(t_{0},s^{(k)})$ by
\begin{equation}
\sigma_{0,\epsilon_{1}}^{(k)}(t,s^{(k)})=\sigma_{0}^{(k)}(S_{t_{0}}^{(k)})+\epsilon_{1},
\end{equation}
and replacing the correlation matrix $\Sigma=Q\Lambda^{2}Q^{\text{T}}$
(for the time step $[t_{0},t_{1})$ only) by 
\begin{equation}
\Sigma_{\epsilon_{2}}=\epsilon_{2}I+(1-\epsilon_{2})\Sigma.
\end{equation}

[Lem 35 of arXiv:2608.28148, 'Flows and homotopies of Banach Lie algebroids'] Let $c\colon [t_0,t_1]\to A$ be a smooth admissible curve and set $\gamma:=\pi\circ c$. The expression \eqref{eq:transport_operator} is independent of the local trivialisation. For fixed $c$ we obtain an $\R$-linear map 
 \begin{align}
 \mathcal{T}_c \colon \Gamma(\gamma^\ast A) \rightarrow \Gamma(c^\ast(TA)), b \mapsto \mathcal{T}_c(b).\end{align}
 Finally, if $f\colon [t_0,t_1]\to\R$ is smooth, then 
 \begin{align} \mathcal{T}_c(fb) = f\mathcal{T}_c(b)+\frac{df}{dt} b^V, 
 \end{align} 
 where $b^V$ denotes the vertical lift of $b$.

[Lemma eq:VR-MTPx of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For all non-negative measurable functions $f$ on $(\Omega,{\mathcal F })$,
	\begin{equation}
		\mathbb E_{{\mathcal V }}^0 [f({\mathcal H })] = 
		\mathbb E_{{\mathcal R }}^0 [f (\theta_{\beta(0)}({\mathcal H }))].

	\end{equation}

