	Then,
	\begin{align}
	\anyProb{\randSubset{{\boldsymbol{\uptheta}}}{k}}{\mathcal{E}_i}
		\leq \anyProb{\randSubset{{\boldsymbol{\uptheta}}}{k+1}}{\mathcal{E}_i},
		\qquad i\in\{1,2,\dots\}.
	\end{align}

