[Theorem 1 of arXiv:2608.29940, 'Counterexamples to the site-percolation analogues\\ of the Easo--Severo--Tassion cutset th'] There exists an infinite, connected, locally finite graph $G$ with a distinguished vertex $\rho$ such that
\begin{enumerate}
  \item[(i)] $\displaystyle\inf_{z\in V(G)}\mathbb{P}_{p}(z\leftrightarrow\infty)>0$ for every $p>2^{-1/2}$, and in particular $p_c^*(G)<1$;
  \item[(ii)] $\displaystyle\mathcal{C}_G(z\leftrightarrow\infty)\ge \tfrac14$ for every $z\in V(G)$, so $G$ is uniformly transient;
  \item[(iii)] $\displaystyle\sup_{n\ge1}\bigl|\mathcal{Q}^{\mathrm{site}}_n(\rho)\bigr|^{1/n}=\infty$, and hence $\kappa^{\mathrm{site}}(G)=\infty$.
\end{enumerate}
Consequently Claims~\ref{conj:A} and~\ref{conj:B} are both false. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thm2ndResult of arXiv:2606.13615, 'Data-Driven Subsampling Rates for Diffusion Parameter Estimation of SDEs'] Suppose that Assumption~(Assumptions of the paper) holds and that (equation eqGenSDEIntro of the paper) admits an invariant measure $\mu$. Let $\mathbf{X}_0 \sim \mu$ be independent of $\mathbf{W}$, let $\mathbf{X} = (\mathbf{X}_t)_{t \geq 0}$ be the corresponding solution process to (equation eqGenSDEIntro of the paper) with $d$-th component $X = (X_t)_{t \geq 0}$, and assume that the ergodicity condition (equation eqErgoCond of the paper) is fulfilled. Then it holds that
\begin{equation}

\lim_{\delta \rightarrow 0} \lim_{J \rightarrow \infty} \frac{1}{J} \sum_{j=1}^J T_{j,\delta}(X) = 2 \quad P\text{-almost surely}.
\end{equation}
Furthermore, for $\mu$-almost all $\mathbf{x} \in \mathbb{R}^d$, (equation eqStatementMainResult2 of the paper) also holds for the $d$-th component $X^{\mathbf{x}} = (X_t^{\mathbf{x}})_{t \geq 0}$ of the solution process $\mathbf{X}^{\mathbf{x}} = (\mathbf{X}_t^{\mathbf{x}})_{t \geq 0}$ with initial condition $\mathbf{X}_0^{\mathbf{x}} = \mathbf{x}$ $P$-a.s., in place of $X$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 44 of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Let $F:[0,\infty) \to[0,\infty)$ be a decreasing function of exponential decay at infinity. Fix $\sigma>0$, $M>0$, $K > 0$, and $d\ge 2$. Let $H:[0,\infty)\to[0,\infty)$ be decreasing and satisfy $H(x) \leq Ae^{-bx}$ where $A,b>0$. Let $\br_0 \in \Ekk$ be centered and $\delta$-repulsive. Then there exists $\epsilon=\epsilon(F,\sigma,M,\delta,d)>0$ and $C=C(F,\sigma,M,\delta,K, A,b,d)>0$ such that uniformly over $\x\in I^k$, $y\in \mathbb R^d$, $r\ge 0$ and  all $f: I\to [0,\infty)$ satisfying $|f(x)| \leq H(|x|)$ one has 
        $$ \sup_{\substack{\br\in \Ekk\\d_{\mathrm{SRI}}(\br,\br_0) <\epsilon
       }}\Ebb [f(   R^i_r -    R^j_r -y)]<C \cdot A b^{-d} \cdot r^{-\frac{d}2}  \big( 1+ r^{-1/2} |x_i-x_j-y|\big)^{-K} .$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Pro 2.2 of arXiv:2608.00420, '{Weighted $L^p$ solutions of scalar BSDEs with general unbounded stochastic coefficients}\'] Let $\bar\rho_t(\omega)$, $\bar\mu_t(\omega)$: $\Omega \times [0,\tau]\mapsto {\mathbb R}$ and $\bar f_t(\omega)$, $\bar\nu_t(\omega)$: $\Omega \times [0,\tau]\mapsto {\mathbb R}_+$ be four $(\mathcal{F}_t)$-progressively measurable processes satisfying $\int_{0}^{\tau}\left(|\bar\rho_t|+|\bar\mu_t|+\bar\nu_t^2\right){\rm d}t<+\infty$,
\begin{align*}
\bar\rho_t\geq \bar\mu_t+\frac{\theta}{2(p-1)}\bar\nu_t^2, \ \ t\in[0,\tau]
\end{align*}
for some constant $\theta>1$, and
$$
\mathbb{E}\left[\left(\int_0^\tau e^{\int_{0}^{t}\bar\rho_r{\rm d}r}\bar f_t{\rm d}t\right)^{p}\right]<+\infty.
$$
Assume that the generator $g$ satisfies the following assumption:
\begin{enumerate}
\renewcommand{(A)}{(A)}
\renewcommand{(A)}{(A)}
\item $\forall (t,y,z)\in[0,\tau]\times{\mathbb R}\times{\mathbb R}^d$,~ $\sgn(y)g(\omega,t,y,z) \leq \bar f_t(\omega) + \bar\mu_t(\omega)|y| + \bar\nu_t(\omega)|z|$,
\end{enumerate}
and $(y_t,z_t)_{t\in [0,\tau]}$ is an adapted solution of BSDE (equation BSDE1.1 of the paper) such that $y_\cdot\in S_\tau^{p}(\bar\rho_\cdot;{\mathbb R})$. Then there exists a constant $C_{p,\theta}>0$ depending only on $p$ and $\theta$ such that for each $0\leq r\leq t< +\infty$,
\begin{align*}
\mathbb{E}\left[\sup_{s\in[t\wedge\tau,\tau]}\left(e^{p
\int_{0}^{s}\bar{\rho}_{r}{\rm d}r}|y_s|^{p}\right)\bigg|\mathcal{F}_{r\wedge\tau}\right]\leq
C_{p,\theta}\mathbb{E}\left[e^{p\int_{0}^{\tau}\bar{\rho}_{r}{\rm d}r}|\xi|^{p}+\left(
\int_{t\wedge\tau}^{\tau}e^{ \int_{0}^{s}\bar{\rho}_r{\rm d}r}\bar{f}_s{\rm d}s\right)^{p}\bigg|\mathcal{F}_{r\wedge\tau}\right].
\end{align*}

[Theorem 10 of arXiv:2606.11142, 'Strong invariance principles for diffusions, Markov chains and their perturbations.'] (Simplified Theorem 1.1 from \cite{Bitter}). Under the Boundedness Assumption, for every $n$ and pairs $(t_i, x), (t_j, y)$, there exists a constant $C > 0$ such that the error between the transition densities is bounded by:
\begin{equation*}
|p - p_\epsilon|(t_i, t_j, x, y) \le C \ln(e(j - i)) \cdot \Delta^{(n)} \cdot \mathcal{Q}_{S-d-6} \left( \frac{x - y}{\sqrt{t_j - t_i}} \right),
\end{equation*}
where $\Delta^{(n)} = \frac{1}{n^{\min(\gamma_2/2,\alpha_2,\beta)}} + \Delta_a + \Delta_b$, and $S$ is some number greater than $2d + 6$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 of arXiv:2512.04807, 'Existence and uniqueness of the canonical Brownian motion in non-simple conformal loop ens'] Let $F_1,F_2$ be two sets with $F_1 \cap F_2 = \{z\}$. For $i=1,2$, let $(\CE_i,\CF_i)$ be a resistance form on $F_i$ with associated resistance metric $R_i$. Define $R\colon (F_1 \cup F_2) \times (F_1 \cup F_2) \to [0,\infty)$ by
 \[
 R(x,y) = \begin{cases}
 R_1(x,y) ,& x,y \in F_1,\\
 R_2(x,y) ,& x,y \in F_2,\\
 R_1(x,z)+R_2(z,y) ,& x \in F_1,\, y \in F_2 .
 \end{cases}
 \]
 Then $R$ is a resistance metric on $F_1 \cup F_2$ and the associated resistance form $(\CE,\CF)$ is given by
 \begin{align}\begin{split}
  \CF &= \{ f : f|_{F_1} \in \CF_1,\, f|_{F_2} \in \CF_2 \} ,\\
  \CE(f,f) &= \CE_1(f|_{F_1},f|_{F_1})+\CE_2(f|_{F_2},f|_{F_2}) .
 \end{split}\end{align}

[Pro 16 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let \( \Omega \subset \R^n \) be an open convex subset and $\phi\in\text{\rm SCL}\,(\Omega)$. Then we have
	\begin{align*} \text{\rm Alex}\,(\phi)\subset\reg(\phi)\subset\text{\rm Diff}\,(\phi).
	\end{align*}

[Theorem thm:endpoint-circle-equality of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Assume the minimal Kahane--Peyri\`ere regime. Then, almost surely on \(\mathcal S_\circ\),
\begin{equation}
\dim_{\mathrm F}(\mu_\circ)=A_{\mathrm{loc}}(W).
\end{equation}

[Definition1 3 of arXiv:2506.11799, 'Quenched limit for diffusive biased random walks in random environment'] We define iteratively the joint regeneration times $(\mu_{k}^{(1)}, \mu_{k}^{(2)})$ as $(\mu_{0}^{(1)}, \mu_{0}^{(2)}) = (0, 0)$ and
	\begin{equation*}
		(\mu_{k+1}^{(1)}, \mu_{k+2}^{(2)}) \coloneqq \inf_{n, m}\left\{(\tau_n^{(1)}, \tau_m^{(2)}) \colon \tau_n^{(1)} \ge \mu_{k}^{(1)}, \tau_m^{(2)} \ge \mu_{k}^{(2)}, X^{(1)}_{\tau_n} \cdot v^* = X^{(2)}_{\tau_m} \cdot v^* \right\}.
	\end{equation*}
    Furthermore, we let $\mathcal{L}_k = X^{(1)}_{\mu_{k}} \cdot v^* = X^{(2)}_{\mu_k} \cdot v^*$ denote the $k$-th joint regeneration level.

[Proposition eq:BregEsts of arXiv:2412.06420, 'Accuracy, Estimates, and Representation Results'] Assume:
	\begin{itemize}
	\item $\mathsf{acc}$ is continuously differentiable. What weakenings would work? Need its derivative to be integrable. 
	\item $\mathsf{acc}$ is absolutely continuous. NB this follows from cts diff, but perhaps not from the relevant weakenings. 
	\end{itemize}
	$\mathsf{acc}$ is strictly proper iff there is a strictly convex function $\varphi$ (and values $\mathsf{acc}_v(v)$) where:
	\begin{align}\mathsf{acc}_v(x)=\mathsf{acc}_v(v)-\left[\varphi(v)-\varphi(x)-(v-x)\varphi'(x)\right]
	\end{align}
	That is, the error-score is:
	\begin{align}\mathfrak{s}_v(x)=\varphi(v)-\varphi(x)-(v-x)\varphi'(x)
		\end{align}

