[Lemma lem:oscillation of arXiv:2504.11107, 'An Invariance Principle for some\\% Reaction-Diffusion Equations with a Multiplicative Ran'] For every $a>0$ and $k\in[2\,,\infty)$,
	\begin{equation}
		\sup_{t\in[a,1+a]} \mathrm{E}\left(\left|
		\frac{ \sup_{x\in\mathbb{T}} w(t\,,x) }{ \inf_{x\in\mathbb{T}} w(t\,,x)} \right|^k\right)<\infty,
	\end{equation}
	uniformly in the initial data $w_0\in L^\infty(\mathbb{T})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem prop:uniform-T-W2 of arXiv:2607.00149, '\bf Uniform-in-time Propagation-of-Chaos for\\ Stein Variational Gradient Descent'] Let Assumption~(ass:Wass of the paper) hold. Recall the exponent $\mathfrak r=\mathfrak r(d,\nu)$ in (equation eq:rdef of the paper), and let
$
    \gamma_*:=\frac{\mathfrak r}{4} \wedge \beta_{\rm init},
$
where $\beta_{\rm init}$ is the logarithmic decay rate of the probability associated with the initialization in Assumption~(ass:Wass of the paper). Then there is a $N_0 \in \mathbb{N}$ and $C \in (0,\infty)$ such that,
for all $N\ge N_0$,
\begin{equation}
    \sup_{T>0}\,
    \mathbb P\left(
        W_2(\overline\mu_T^N,\overline\mu_T)
        > (\log N)^{-\mathfrak r / 4}
    \right)
    \le C\,(\log N)^{-\gamma_*}.
\end{equation}
Moreover,
\[
W_2(\overline\mu_T^N,\overline\mu_T)
=
O_{\mathbb P}\bigl((\log N)^{-\mathfrak r/2}\bigr)
\]
uniformly over deterministic averaging horizons \(T>0\), in the sense that
\begin{equation}
\lim_{M\to\infty}\limsup_{N\to\infty}
\sup_{T>0}
\mathbb P\left(
W_2(\overline\mu_T^N,\overline\mu_T)>M(\log N)^{-\mathfrak r/2}
\right)
=0.
\end{equation}

[Lem Hypercon of arXiv:2507.02518, '{\bf Exponential Ergodicity in Relative Entropy and $L^2$-Wasserstein Distance for non-equ'] Let $\bar{\mu}$ be the invariant probability measure of $(P_t)_{t\ge0}$, and
assume that $(P_t)_{t\ge0}$ is hyperbounded, i.e.,
$\|P_{t_0}\|_{p\rightarrow q }:= \|P_{t_0}\|_{L^p(\bar{\mu})\rightarrow L^q(\bar{\mu})}<\infty $ for some   $t_0>0 $ and  $1<p<q<\infty$.
Assume moreover that $L^2$-exponential ergodicity holds, i.e.
\begin{align*}\|P_t f-\bar{\mu}(f)\|_{L^2(\bar{\mu})}\leq c\text{\rm{e}}^{-\lambda t}\|f-\bar{\mu}(f)\|_{L^2(\bar{\mu})},\ \ t\geq 0
\end{align*}
for some constants $c,\lambda>0$.
Then hypercontractivity holds, i.e.
\begin{align*}
\|P_{\tilde{t}_0}\|_{p\rightarrow q }\leq 1
\end{align*}
for some constant $\tilde{t}_0>0$ depending only on $c,\lambda,q,p,t_0$ and $\|P_{t_0}\|_{p\rightarrow q }$.
Consequently, exponential ergodicity in relative entropy holds:
\begin{align*}
\bar{\mu}(P_t f\log P_tf)\leq \tilde{c}\text{\rm{e}}^{-\tilde{\lambda} t}\bar{\mu}(f\log f),\ \ \bar{\mu}(f)=1, f>0, t\geq 0
\end{align*}
for some constants $\tilde{c}, \tilde{\lambda}>0$ depending only on $\tilde{t_0},q,p$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem equa:convL of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] For every $y \in {E}$ with $y \neq x$, under $\mathbb{P}_{0,y}$  and $\mathbb{N}_{y}$,  a.e.  for every $M \geq 0$ we have 
    \begin{equation}
        \lim \limits_{k\to \infty}\sup_{t \leq M} \Big|  \frac{1}{\varepsilon_k} \int_0^t {\mathrm{d}} s ~\mathbbm{1}_{\{ \uptau(W_s) < H(\rho_s) < \uptau(W_s) + \varepsilon_k \}} - L_t(\rho , W)   \Big|=0. 
        \end{equation}

