[Corollary 42 of arXiv:2609.02878, '2609.02878'] Let $(\hat X,\hat g_s)$ be the underlying metric flow of a tangent space
at a fixed limiting point whose base lies in $Y^{\rm prod}$, in the
relative-dimension-one setting.  For every $A>1$,
\begin{equation}
 K_A:=\sup_{s\in[-A,-A^{-1}]}\sup_{\hat X}
 |\Rm_{\hat g_s}|_{\hat g_s}<\infty.
\end{equation}
The number $K_A$ may depend on the realized tangent-space model, but is
fixed before
the packing number $N$ is chosen.

[Prop CM UT UB of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] For all $r \in (0, e^{-1} \wedge r_*)$, $t \in (0, \infty)$, and $\lambda \in (0, \infty)$, 
  it holds that
  \begin{equation}
    \sup_{\bm{x} \in M^k} \sup_{y \in M}
    \hat{P}_{\bm{x}}\!\left(\Pi_t(B(y,r)) \geq \lambda r^{d_{\mathrm{cp}}}\right) 
    \leq 
    \tilde{c}_1(t) e^{-\tilde{c}_2(t) \lambda},
    \qquad 
    \text{if}\quad \hat{d}_{\mathrm{s}} > 2,
  \end{equation}
  and 
  \begin{equation}
    \sup_{\bm{x} \in M^k} \sup_{y \in M}
    \hat{P}_{\bm{x}}\!\left(\Pi_t(B(y,r)) \geq \lambda r^{d_{\mathrm{f}}} \log(1/r)\right) 
    \leq 
    \tilde{c}_3(t) e^{-\tilde{c}_4(t) \lambda},
    \qquad 
    \text{if}\quad \hat{d}_{\mathrm{s}} = 2,
  \end{equation}

[Theorem 2 of arXiv:2608.29736, '2608.29736'] Let $(M^n,\omega)$ be a compact K\"ahler manifold of complex
 dimension $n\geq 2$. Let $\chi$ be another K\"ahler form.  Suppose that the $J$-semistable condition ~\eqref{topintegralnonnegative}--~\eqref{$J$-semistablecondition} holds. Set the positive constant \begin{equation}
     c= \frac{2n\displaystyle\int_M\Big(\chi^n-n\chi^{n-1}\wedge\omega\Big)+\int_M \omega^n}{8n^2\displaystyle\int_M\chi\wedge\omega^{n-1}},
     \end{equation}and let \begin{equation}
     S:=\{ D \,|\,D\; \text{is a prime divisor and } \int_DF_{n-1}(\chi)< c\int_D\omega^{n-1} \}.
 \end{equation}
Then any finite subset of  $S$ is an exceptional family in the sense of Boucksom~\cite{Boucksom}. In particular, the cardinality of  $S$ is bounded by  the Picard number of $M$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2511.09280, 'Random Walk conditioned to stay above a non-flat floor: curvature effects'] There are \(n_0\geq 0, r_0\geq 0\), \(c,C>0\) such that for any \(n\geq n_0\), and any \(1\leq i<j\leq n\) with \(j-i\geq r_0 n^{2/3}\),
    \begin{equation*}
        \babs{ \Cov(n^{-1/3}W_i,n^{-1/3}W_j) } \leq C\exp(-c\tfrac{|j-i|}{n^{2/3}}).
    \end{equation*}

