[Thm Main Theorem of arXiv:2411.07671, 'Long Time Behavior of General Markov Additive Processes'] Let $(\xi,\Theta),\mathbb{P})$ be a MAP such that Assumptions 1,2,3, and 4 are satisfied. Then, we have
\begin{enumerate}[label=(\roman*)]
    \item $\xi_t$ drifts to $-\infty$ $\:\mathbb{P}_{0,\pi}$-a.s., if and only if\begin{equation}
    \int_{S\times \mathbb{R}^+}U_\pi^+(dv,dz)\eta^+_v(\zeta^+ =+\infty)=1
\end{equation}
\item  $\xi_t$ drifts to $+\infty$ $\:\mathbb{P}_{0,\pi}$-a.s.,  if and only if\begin{equation}
    \int_{S\times \mathbb{R}^-}U_\pi^-(dv,dz)\eta^-_v(\zeta^- =+\infty)=1
\end{equation}
\item $\xi_t$ oscillates $\mathbb{P}_{0,\pi}$-a.s., if and only if \begin{equation}
    \int_{S\times \mathbb{R}^+}U_\pi^+(dv,dz)\eta^+_v(\zeta^+ =+\infty)=0 \quad \text{and} \quad \int_{S\times \mathbb{R}^+}U_\pi^-(dv,dz)\eta^-_v(\zeta^- =+\infty)=0
    \end{equation}
\end{enumerate}
where \begin{equation*}
U^+_\theta (dv,dz)= \mathbb{E}_{0,\theta}\left[ \int_0^{\Bar{L}_\infty} \textbf{1}_{\{ \Theta^+_s\in dv, \xi^+_s\in dz\}}ds \right] \quad \text{and} \quad
     U^-_\theta (dv,dz)= 
     \mathbb{E}_{0,\pi}\left[ \int_0^{\underline{L}_\infty} \textbf{1}_{\{ \Theta^-_s\in dv \, , \, \xi^-_s\in dz \} }ds \right].
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

