[Lemma lem:Z of arXiv:2608.16915, 'Exact mean--covariance dynamics of the Weber field in the stochastic Lagrangian representa'] Let $B_t=\sqrt{2\nu}\,\beta_t$ for a standard one-dimensional Brownian motion $\beta$, let
$K>0$, $\lambda:=\nu K^2$, and set $Z_t:=\int_0^t e^{iKB_s}\,\mathrm{d} s$. Then
\begin{equation}
  \mathbb{E}\left\lvert Z_t\right\rvert^2=2\Bigl(\frac{t}{\lambda}-\frac{1-e^{-\lambda t}}{\lambda^2}\Bigr)
  \ \ge\ \frac{t}{\lambda}\quad\text{whenever }\lambda t\ge2 ,
\end{equation}
\begin{equation}
  \mathbb{E}\left\lvert Z_t\right\rvert^4\le\frac{12\,t^2}{\lambda^2},
\end{equation}
and consequently, by the Paley--Zygmund inequality applied to $\left\lvert Z_t\right\rvert^2$,
\begin{equation}
  \mathbb{P}\Bigl\{\left\lvert Z_t\right\rvert^2\ge\tfrac12\mathbb{E}\left\lvert Z_t\right\rvert^2\Bigr\}\ge\frac1{48},
  \qquad
  \mathbb{E}\left\lvert Z_t\right\rvert\ge c\,\sqrt{t/\lambda}\qquad(\lambda t\ge2)
\end{equation}
for a universal constant $c>0$.

[Lemma 52 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the notation from Definition \ref{Def.ParametersEdge}. There exist constants $\delta_0 \in (0,1)$ and $C_0 > 0$, depending on $q, \kappa$ and $c$, such that the function $\SFb(z;\kappa)$ is analytic in the disk $\{|z-\zc(\kappa)| < 2\delta_0\}$, the functions $\SFt(z;\kappa), \GFt(z)$ are analytic in the disk $\{|z- c| < 2\delta_0\}$, and the following statements hold. 
If $|z-\zc(\kappa)| \leq \delta_0$, then
\begin{equation}
\left| \SFb(z;\kappa) - \SFb(\zc(\kappa);\kappa)  \right| \leq C_0 |z - \zc(\kappa)|^3.
\end{equation}
If $|z-c| \leq \delta_0$, then
\begin{equation}
\left| \SFt(z;\kappa) - \SFt(c;\kappa) - [\sigmap^2(\bar{\kappa} - \kappa)/2c^2] (z-c)^2 \right| \leq C_0 |z - c|^3,
\end{equation}
\begin{equation}
\left| \GFt(z) - \GFt(c) + (\sigmap^2/2c^2) (z-c)^2 \right| \leq C_0 |z - c|^3.
\end{equation}

