[Thm Generalised Theorem of arXiv:2411.07671, 'Long Time Behavior of General Markov Additive Processes'] Let $((\xi,\Theta),\mathbb{P})$ be a MAP such that Assumptions 1,2,3, and 4* satisfied. Then, 
\begin{enumerate}[label=(\roman*)]
    \item $\xi_t$ drifts to $-\infty$ $\:\mathbb{P}_{0,\pi}$-a.s.,  if and only if\begin{equation*}
    \int_{S\times \mathbb{R}^+}U_\pi^+(dv,dz)\eta^+_v(\zeta^+ =+\infty)=1  \quad \text{and} \quad  \int_{S\times \mathbb{R}^+}\widetilde{U}_\pi^+(dv,dz)\widetilde{\eta}^+_v(\tilde{\zeta}^+ =+\infty)=1
\end{equation*}
\item  $\xi_t$ drifts to $+\infty$ $\:\mathbb{P}_{0,\pi}$-a.s.,  if and only if\begin{equation*}
   \int_{S\times \mathbb{R}^+}U_\pi^-(dv,dz)\eta^-_v(\zeta^- =+\infty)=1 \quad \text{and} \quad  \int_{S\times \mathbb{R}^-}\widetilde{U}_\pi^-(dv,dz)\widetilde{\eta}^-_v(\tilde{\zeta}^- =+\infty)=1
\end{equation*}
\item $\xi_t$ oscillates $\mathbb{P}_{0,\pi}$-a.s., if and only if\begin{equation*}
    \int_{S\times \mathbb{R}^+}U_\pi^+(dv,dz)\eta^+_v(\zeta^+ =+\infty)=0 \quad \text{and} \quad \int_{S\times \mathbb{R}^+}{U}_\pi^-(dv,dz){\eta}^-_v(\zeta^- =+\infty)=0
\end{equation*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2608.25887, '\bf Efficient Estimation of High Information Projections using Nearest Neighbours'] Let $X_1, X_2, ...$ be a sequence of i.i.d. random variables on $\R^p; p > 4$, with density function $f_X$ satisfying
    \begin{itemize}
    \item[C1:] The support of $f_X$ is bounded, i.e. $\exists M > 0$ s.t. $Supp(f_X):= \{\x \in \R^p | f_X(\x) > 0\} \subset B_M(\0)$.
    \item[C2:] The density $f_X$ has bounded first two derivatives on the interior of $Supp(f_X)$.
    \item[C3:] There exist $l, H > 0$ s.t.
    \begin{align*}
        \sup_{\substack{\x \in Supp(f_X)\\0 < h_1 \leq h_2 \leq H}} \frac{f_X(\x)^2h_1^{p-1}h_2^{p-1}h_2^3}{\oint_{B_{h_1}(\x)}\oint_{B_{h_2}(\x)}f_X(\z)f_X(\w)d\z d\w} \leq l
    \end{align*}
    \item[C4:] For any $a > 0$ $\exists U > 0$ for which
    \begin{align*}
        \sup_{\substack{\x \in Supp(f_X),\\ 0 < u < U}} \frac{1}{\Fdx(u)^k} \int_1^\infty \Fdx( u\epsilon^{-1/a})^k d\epsilon = o(1),
    \end{align*}
    as $k \to \infty$.
\end{itemize}
Then
\begin{align*}
    I(\X_n, k(n)) \xrightarrow{P} I(f_X)
\end{align*}
provided the sequence $\{k(n)\}_{n \in \mathbb{N}}$ satisfies $k(n) \to \infty$ and $k(n)^{2-p/4}/n^{1-p/4} \to 0$ as $n\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

