[Lemma lm:renom_cst of arXiv:2608.27828, 'Scaling limit of the 3D abelian Yang--Mills Langevin dynamics'] One has
\begin{equ} 
\eps^3 c^\varepsilon_t 

\lesssim 1.
\end{equ}
Moreover, uniformly in $\rho\in [0,1]$,
\begin{equ} 
   \eps^3  | c_t^\varepsilon-c_s^\varepsilon |
    \lesssim
    |t-s|^{\rho}
    \varepsilon^{-2\rho}.
\end{equ}

[Lem gamma fct reflect of arXiv:2609.02409, 'Membranes and Maps'] For all positive integers $d$ we have
    \begin{equation}
        \gamfct{-x}{u}
        =
        \frac{1}{\gamfct{x+1}{u}} \,,\qquad
        \gamfct{x}{u}\,\gamfct{-x-d}{u}
        =
        \prod_{k=0}^{d} \cS\big(u(x+k)\big)^{-1} \,.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm correspondence of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] The map \begin{align}
     \mathsf{gap}:\mathcal P_{s,1}(\Gamma)\to \mathcal P_{s,1}( \mathsf{S}), \mathsf{P}\mapsto 
     \mathsf{sq}_{\#}\mathsf{P}^0
\end{align}
is a bijection and for $\mathsf{P}\in \mathcal P_{s,1}(\Gamma)$ it holds 
 \begin{align}
\int fd\mathsf{P}=\int \int_0^{\tau_1(\xi)}f(\theta_x\xi)dx\mathsf{P}^0(d\xi),
    \end{align}
    where $f:\Gamma\to \IR$ is bounded and measurable. We call $ \mathsf{gap}(\mathsf{P})$ the gap distribution of $\mathsf{P}$ resp.\ of the point process $\xi$ with distribution $\mathsf{P}.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 of arXiv:2608.29585, '2608.29585'] For every $d\ge1$, the inclusion
$R_{\mathrm{ev}}\hookrightarrow\cO_d$ extends uniquely to a continuous
homomorphism
\begin{equation}
 \iota_d:\widehat R_{\mathrm{ev}}^{\mathrm{BG}}
 \longrightarrow\widehat\cO_d.
\end{equation}
More precisely,
\begin{equation}
 \val_{\Phi_d}((q^2;q^2)_m)
 =\left\lfloor\frac{m}{d^\sharp}\right\rfloor.
\end{equation}

