body:
[Lemma 5 of arXiv:2609.03958, '2609.03958'] Let $\lambda\in \Gamma_2$ and $\sigma_2(\lambda)=f$. Assume that $$\ell_i:=\sigma_1(\lambda)-\lambda_i,\ \ \ i=1,\ldots,n.$$
Then we have 
\begin{equation}
 R_k:=\max_{\substack{z\ne0\\ \ell\cdot z=0}}
      \frac{(e\cdot z)^2}{z^TD_kz}=\frac13\left[ n+2- \frac{\bigl((n-1)\sigma_1(\lambda)+2\ell_k\bigr)^2} {(n-1)\sigma_1^2(\lambda)-2f+2\ell_k^2} \right].
\end{equation}

[Theorem 26 of arXiv:2606.21111, 'On Elephant Random Walk with Delayed Amnesia'] Let $(4a-1)/4a<p\le1$. Then,
	\begin{equation*}
		\lim_{n\to\infty}\frac{W_n}{n^{2a(p-1)+1}}=\mu L\ \ \text{a.s.},
	\end{equation*}
where $L$ is as given in \eqref{Lvariab}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 40 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $0<T\le1$, $0<\sigma<1$, and suppose that $H$ satisfies the parabolic tail condition \eqref{eq:parabolic-tail-bound}.  Then the heat spectral splitting satisfies
\begin{equation}

\max\{\norm{Q_{cb}}_{H^\alpha},\norm{Q_{ba}}_{H^\alpha}\}\le \left(\frac12+C L^\eta\right)\norm{Q_{ca}}_{H^\alpha} +C\bigl(\norm{H}_{\gamma,\alpha}+K\bigr)L^\gamma,
\end{equation}
where $\eta:=\min\{1-\sigma,\rho\}>0$ and $\rho=\frac{\sigma\beta}{2}$.
In particular, at $\gamma=1$ this is a critical admissible scale splitting.  If $0<\gamma<1$, then after restricting to a sufficiently small time horizon $T_0$, it is a subcritical admissible scale splitting, because $1/2+C T_0^\eta<2^{-\gamma}$.

[Thm Thm_MakNikPal of arXiv:2606.22183, 'Expected loss of quasi-arithmetic means of exchangeable random variables'] Let $I\subseteq \mathbb{R}$ be a nonempty open interval, $\alpha:(I-I)\to\mathbb{R}_+$ be an even error function, and $L:I\to \mathbb{R}$ be a function.
Then the following two assertions are equivalent:
 \begin{enumerate}
   \item[(i)] $L$ is strongly $\alpha$-convex, i.e., (equation help_strongly_alpha_convex_def of the paper) holds for all  $x,y\in I$ and $t\in[0,1]$.
   \item[(ii)] For all $x_0\in I$, there exists a constant $c_{x_0}\in\mathbb{R}$ such that
         \begin{align}
           L(x)\geqslant L(x_0) + c_{x_0}(x-x_0) + \alpha(x-x_0),\qquad x\in I.
         \end{align}
 \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] For $\Pi\in \mathcal P_{s,1}( \mathsf{S})$ and $m<n$    denote by $\Pi^{m,n}$ the pushforward of $\Pi$ under the map $
        ( \mathsf{s}_i)_{i\in \IZ}\mapsto ( \mathsf{s}_i)_{i=m,\dots,n}$. We set  \begin{align*}
    \mathcal E^*(\Pi):=\lim_{n\to \infty}n^{-1}\mathsf{Ent}(\Pi^{1,n}\mid \gamma^{\otimes_{i=1}^n})=\sup_{n\in \IN}n^{-1}\mathsf{Ent}(\Pi^{1,n}\mid \gamma^{\otimes_{i=1}^n}).
\end{align*}

[Thm local of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $D\subset\mathbb C$ be a proper, simply connected domain. Let $(\phi, A, \phi^A, h_A)$ be a coupling of a GFF $\phi$ with zero boundary conditions in $D$ and a random closed set $A\subset \bar D$ connected to $\partial D$ such that, given $A$, $\phi^A$ is a GFF with zero boundary conditions in $D\setminus A$ and $h_A$ is a harmonic function in $D\setminus A$. Suppose that 
    \begin{enumerate}[label=(\roman*)]
        \item Given $A$, 
        \begin{equation}
            \restr{(\field{e^{i\alpha\phi}})}{D\setminus A} =\ \big(e^{i\alpha h_A}\restr{\field{e^{i\alpha\phi^A}}\big)}{D\setminus A}\quad  \text{a.s.}
        \end{equation}
        \item For every connected component $\mathcal O$ of $D\setminus A$ and any $f\in C^\infty_c(D)$, $$(\field{e^{i\alpha\phi}}, f\1_{[\partial\mathcal O]_n}) \longrightarrow 0$$ in probability as $n\to\infty$.
        \item  For any $N\in\mathbb N$, the random variables
        \begin{equation}
            \restr{\big(\field{e^{i\alpha\phi^A}}\big)}{\cup_{i=1}^N\mathcal O_i} \text{ and } \ \big(h_A, \restr{\big(\field{e^{i\alpha\phi}}\big)}{D\setminus\cup_{i=1}^N\mathcal O_i}\big) 
        \end{equation}
        are conditionally independent given $A$.
    \end{enumerate}
    Then, $(\phi,A)$ is a local set coupling. That is, when restricted to $D\backslash A$,
    \begin{equation}
        \phi=\phi^A + h_A + \frac{2\pi}{\alpha} k_{\mathcal O},
    \end{equation}
    where $\phi^A$ is conditionally independent of $h_A+(2k_{\mathcal O}/\alpha)\pi$ given $A$, and $k_{\mathcal O}$ is some integer that may depend on the connected component $\mathcal O$ of $D\setminus A$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 24 of arXiv:2605.03851, 'The Relay Random Tree:\\A stochastic geometry approach of multihop relay in an urban visib'] \textbf{Markov behaviour in horizontal finite range.}

For $n\in\N$, let $\tilde{x}_n:= X_n-X_{n-1}$ denote the length of the $n-$th hop.

The sequence $(\tilde{x}_n, \mathrm{t}_n, H_n)$ is a Markov chain with kernel $\mathrm{VIS}_R$ given by:
    \begin{align*}
        &\forall (\tilde{X}, T, H)\in \Half, \forall A \in \mathcal{B}(\R\times\Half), \mathrm{VIS}_R((\tilde{X}, T, H), A) = \int_A vis^{\tilde{X}, T, H}(t, h) \delta_{\frac{h-H}{t} }(\tilde{x})\rm{d}\Leb(t) \rm{d}\mathcal{L}(h)
        \end{align*}
    \begin{align*}
        \forall \tilde{X}, T, H, t, h \in \R_+, vis^{\tilde{X}, T, H} (t, h) :=\frac{h-H}{t^2}\lambda \exp\Biggl(-\lambda \Biggl(&\frac{\primi(H)-\primi(H+(R-\tilde{X})T)}{T}-\frac{\primi(H+Rt)-\primi(H)}{t}\\
        &+\frac{\primi(H + (R-\tilde{X} (t \wedge T)}{t\wedge T}-\frac{\primi(H +(R-\tilde{X} t)}{t}\Biggl)\Biggl)\\
        &\mathds{1}_{\frac{h-H}{t}\in ]0, R], T\geq t \text{ or } \tilde{X}+ \frac{h-H}{t}> R } ,
    \end{align*}
    and 
    \begin{align*}
        &\mathrm{VIS}_R((\tilde{X}, T, H), (-\infty, -\infty, -\infty)) = \exp\Biggl(-\lambda \Biggl(R - \frac{\primi(H)-\primi(H+(R-\tilde{X})T)}{T}\Biggl)\Biggl)\\
        &\mathrm{VIS}_R((-\infty, -\infty, -\infty), (-\infty, -\infty, -\infty)) = 1.
    \end{align*}

[Definition def-rareevent of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] Given an edge potential $h$ and $\cc\in \R$ with $ \cc \neq \sref$, 
let the event $\Conset_n(h,\cc)$ be defined by 
\begin{align}
    \Conset_n(h,c)\coloneqq
    \begin{cases}
       \{ \mathbb{E}_{L_n} [S_h] \geq \cc\} \quad \text{ if } \cc > \sref,\\
       \{ \mathbb{E}_{L_n} [S_h] \leq \cc\} \quad \text{ if } \cc < \sref. 
    \end{cases}

\end{align}
and let the collection of measures $\Conset(h,\cc)$ be defined by
\begin{align}
    \Conset(h,c)\coloneqq
    \begin{cases}
       \{ \mu\in \P\cpr{\TkappaX{1}}:\mathbb{E}_{\mu} [S_h] \geq \cc\} \quad \text{ if } \cc > \sref,\\
       \{ \mu\in \P\cpr{\TkappaX{1}}:\mathbb{E}_{\mu} [S_h] \leq \cc\} \quad \text{ if } \cc < \sref. 
    \end{cases}

\end{align}

[Lemma 10 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let $f$ and $g$ be nonnegative real functions defined on $\T^d\times\R^d$ with $m_0(f)$, $m_1(f)$, $m_0(g)$ and $m_1(g)$ which are finite almost everywhere.
Let $k>1+\frac{d}{2}$ (\emph{i.e.} $k\geq 3$ since $k$ is an integer), then there exists a constant $C=C(k,d)>0$ such that
\begin{equation*}
\lVert m_{0}(f) -m_{0}(g) \rVert_{L^2_x} \leq C \lVert \langle v \rangle^k (f-g) \rVert_{L^2_{x,v}},
\end{equation*}
and
\begin{equation*}
\lVert m_{1}(f) - m_{1}(g)\rVert_{L^2_x} \leq C \lVert \langle v \rangle^k (f-g) \rVert_{L^2_{x,v}}.
\end{equation*}

