[Theorem 49 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $(X_1, \mu_1)$ and $(X_2, \mu_2)$ be Polish measure spaces, and let $c$ be a continuous cost function on $X_1\times X_2$ such that $-c(X_1 \times X_2)=[a,b)$. Fix a weight $\lambda \in (0,1)$. Assume that $(X_1, \mu_1)$ and $(X_2,\mu_2)$ satisfy the Cost-Santal\'o inequality in Lemma~\ref{l:transfer} associated with $(\lambda,c,F)$ and domain $(\mathcal{A}_1, \mathcal{A}_2)$, where $F:[a,b]\to [0,\infty)$ is a continuous, non-decreasing function such that $F(a)=0$.  Assume also that the total masses 
    \[
    0<Z_1 = \int_{X_1} \Omega(\Phi_1(x_1)) d\mu_1(x_1),\, Z_2 = \int_{X_2}\Omega(\Phi_2(x_2)) d\mu_2(x_2) <+\infty.
    \]

    Let $\Phi_1: X_1 \to [a,b]$ and $\Phi_2: X_2 \to [a,b]$ be measurable functions satisfying
    \begin{equation}

        \lambda \Phi_1(x_1) + (1-\lambda) \Phi_2(x_2) \ge -c(x_1, x_2), \quad \forall x_1\in X_1, x_2\in X_2.
    \end{equation}
    Let $\Omega: [a,b] \to (0,\infty)$ be a continuous, non-increasing, log-concave function. Moreover, assume the following balance condition holds:
    \begin{equation}

        \int_a^b \Omega(r) dF(r) \leq Z_1^\lambda Z_2^{1-\lambda}.
    \end{equation}
    Define the probability measures
    \[
    dP_1(x_1) = Z_1^{-1} \Omega(\Phi_1(x_1))d\mu_1(x_1) \quad \text{and} \quad dP_2(x_2) = Z_2^{-1} \Omega(\Phi_2(x_2)) d\mu_2(x_2)
    \]
    and define the transport cost function on $X_1 \times X_2$ by:
    \begin{equation}
        c_{\Omega}(x_1, x_2) = \log \left( \frac{\Omega(-c(x_1, x_2))^{\frac{1}{1-\lambda}}}{\Omega(\Phi_1(x_1))^{\frac{\lambda}{1-\lambda}} \Omega(\Phi_2(x_2))} \right).
    \end{equation}
    Then $c_\Omega \ge 0$, and for any $\nu_1 \in \mathcal{P}(X_1)$ having density with respect to $P_1$, and $\nu_2 \in \mathcal{P}(X_2)$ having density with respect to $P_2$, one has the optimal transport bound:
    \begin{equation}
        \mathcal{T}_{c_{\Omega}}^{\mathcal{A}}(\nu_1, \nu_2) \leq \frac{\lambda}{1-\lambda} H(\nu_1 | P_1) + H(\nu_2 | P_2),
    \end{equation}
    where $\mathcal{T}_{c_{\Omega}}^{\mathcal{A}}(\nu_1, \nu_2)$ denotes the restricted Kantorovich cost taken as the supremum over pairs $(\varphi, \psi)$ satisfying the pointwise bound $\varphi(x_1) + \psi(x_2) \le c_\Omega(x_1, x_2)$, with the additional constraint that $e^{\frac{1-\lambda}{\lambda}\varphi} \Omega(\Phi_1(\cdot)) \in \mathcal{F}(\mathcal{A}_1)$ and $e^{\psi} \Omega(\Phi_2(\cdot)) \in \mathcal{F}(\mathcal{A}_2)$.

