[Definition 16 of arXiv:2606.11271, '\LARGE The $K$-th nearest neighbor random walk on a Poisson point process gets trapped'] For any $\varepsilon >0$, $R\in \N^*$ and $n\in \N$, $X_n$ is called an $(\varepsilon,R)$-nice point if there exists $u \in \Z^d$ such that
\begin{itemize}
\item[$(i)$] $\Lambda_R (u)$ is $\varepsilon$-good;
\item[$(ii)$] $E_n \cap \Lambda_R(u) = \emptyset$;
\item[$(iii)$] $E_{n+1} \cap \Lambda_R(u) \neq  \emptyset$.
\end{itemize}

[Prop 4 (\cite{GGT25}) of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] Let $\{X^n_s : s \in S_n, n\ge 1\}$ be a collection of $\cX$-valued random elements such that $(\omega, s) \mapsto X^n_s(\omega)$ is $\cF\otimes \cS_n/\cB(\cX)$-measurable for all $n \ge 1$. Let $p \in (0, \infty)$. Then, the following assertions are equivalent:
\begin{enumerate}[\rm (i)]
\item $\{X^n_s : s \in S_n, n\ge 1\}$ is $(\nu_n)$-$\CUI(p)$.

\item $\{X^n_s : s \in S_n, n\ge 1\}$ is uniformly tight, which means
\begin{align*}
\forall \ep >0, \, \exists K_\ep \in \cK(\cX)\; :\; \sup_{n \ge 1} (\bP \otimes \nu_n) (X^n_s \notin K_\ep) \le \ep,
\end{align*}
and that 
\begin{align*}
\lim_{a \to \infty} \sup_{n \ge 1} \bE \int_{S_n} \|X^n_s\|^p \, \1_{\{\|X^n_s\| > a\}} \nu_n(\od s) =  0.
\end{align*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 25 of arXiv:2606.09904, 'Non-explosion principles for branched rough differential equations with unbounded coeffici'] Suppose Assumption~\ref{as:growth} holds for \(l\) satisfying \(\int_a^\infty l(r)^{-1} \dd r = \infty\)
  for some \(a > 0\). Moreover, suppose that the vector field \(b\) satisfies
  \begin{equation}
    \<x, b(x)\> \le \|x\| l(\|x\|) \text{ for all } x \in \mathbb{R}^d.
  \end{equation}
  Then, the branched RDE~\eqref{eq:bRDE} has a unique global solution.

