[Lemma lm:xBhatproc of arXiv:2507.08757, 'Strong existence and uniqueness of the tilt-indexed Busemann process in the planar corner '] For each ${\widehat B}\in \widehat{\mathcal{K}}$, the process ${\boldsymbol{\pi}}^{{\widehat B},u,{\raisebox{1.3pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}}}$  satisfies the following properties: 
\begin{enumerate}  [label={\rm(\alph*)}, ref={\rm\alph*}]   \itemsep=3pt
\item 
For $\widehat\mathbb{P}$-almost every ${\widehat\omega}$, the definition in (equation eq:inf-formula of the paper) agrees with (equation eq:inf-formula-rational of the paper) for rational $s$, so ${\boldsymbol{\pi}}^{{\widehat B},u,{\raisebox{1.3pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}}}({\widehat\omega})$ is well-defined.
\item ${\widehat\omega}\mapsto {\boldsymbol{\pi}}^{{\widehat B},u,{\raisebox{1.3pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}}}({\widehat\omega})$ is an $\mathfrak{S}$-measurable, $\textup{D}_{\textup{LCRL}}([0,1],\mathbb{X}_u)$-valued random variable which almost surely takes values in $\textup{D}_{\textup{LCRL}}([0,1],\mathcal{G}_u^{\omega({\widehat\omega})})$.
\item 
For $\widehat\mathbb{P}$-almost every ${\widehat\omega}$ and all $s \in [0,1]$,
\begin{align}
{\boldsymbol{\pi}}^{{\widehat B},u,s}({\widehat\omega})=\inf\bigl\{\gamma\in\mathcal{G}_u^{\omega({\widehat\omega})}:\nu^{\omega({\widehat\omega})}(\phi_{}^{{\widehat B},u}\preceq \gamma)\geq s\bigr\}.
\end{align}
Consequently, ${\boldsymbol{\pi}}^{{\widehat B},u,r}({\widehat\omega})\preceq{\boldsymbol{\pi}}^{{\widehat B},u,s}({\widehat\omega})$ for $r\le s$ in $[0,1]$.
\item  
For $\widehat\mathbb{P}$-almost every ${\widehat\omega}$ and all $\gamma \in \mathcal{G}_u^{\omega({\widehat\omega})}$,
\begin{align}
\bigl\{s\in [0,1] : {\boldsymbol{\pi}}^{{\widehat B},u,s}({\widehat\omega}) \preceq \gamma\bigr\}=\bigl[0,\nu^{\omega({\widehat\omega})}(\phi_{}^{{\widehat B},u} \preceq \gamma)\bigr]. 

\end{align}
\item  
For $\widehat\mathbb{P}$-almost every ${\widehat\omega}$, all $u,z\in\mathbb{Z}^2$, and all $s\in[0,1]$,
\begin{equation}\begin{aligned}
{\boldsymbol{\pi}}^{{\widehat B},u+z,s}({\widehat\omega})=z+{\boldsymbol{\pi}}^{{\widehat B},u,s}(\widehat{T}_z{\widehat\omega}).
	\end{aligned}\qedhere\end{equation}
\end{enumerate}

[Theorem thm:EL for k and tau of arXiv:2609.02073, 'Existence of closed non-planar $p$-elasticae'] [ourpaper]

    Let $p\in (1,\infty)$ and $\gamma:[0,L]\to\R^n$ be an analytic non-planar $p$-elastica, parameterized by arclength.
    Then $\gamma$ is a three-dimensional curve with $k,|\tau|>0$ on $[0,L]$, satisfying 
    \begin{equation}

    \begin{split}
        p (k^{p-1})'' + (p-1) k^{p+1} -p k^{p-1} \tau^2 -\lambda k &= 0, \\
         k^{2p-2} \tau &= C,
    \end{split}
    \end{equation}
    for some real constant $C\neq 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thm-local-Appendix of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $d \geq 1$ and $p\ge 1$.  
		Assume (Hypo-W L of the paper), (Hypo-Qi-M of the paper), and (Hypo-F-h of the paper) hold with $\sigma> \frac{d}{2} + p$. Let $s > \frac{d}{2} + p + \max \{3(\alpha\lor \beta\lor \varsigma),\ell\mathbf{1}_{\{\epsilon>0\}},1\}$. Let $u_0\in H^s$ be an $\mathcal{F}_{0}$-measurable random variable. Then (equation SPDE-general of the paper) with initial data $u(0)=u_0$ admits a unique maximal $H^s$ classical solution $(u,\tau^{*})$. Moreover, 
		\begin{equation*}
			u\in D([0,\tau^*);H^{s'})\quad \forall s'<s\quad {\mathbb P}\text{-}{\rm a.s.},
		\end{equation*}
		the lifetime $\tau^*$ is independent of $s$, and the following blow-up criterion holds:
		\begin{equation*} 
			\limsup_{t \rightarrow \tau^*} \|u(t)\|_{W^{p,\infty}} = \infty \quad \text{a.s. on } \{\tau^* < \infty\}.
		\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2608.01419, 'A model of opinion dynamics evolving via a preferential attachment mechanism involving mul'] Consider the model described in \S\ref{subsec:model_fixed_sample_size}, and let us define $Z_{n}=(n^{-1}A_{n},n^{-1}B_{n},n^{-1}C_{n})$ for all $n\in\mathbb{N}$ with $n\geqslant N$. Fix \emph{any} $T>0$. Writing $t_{N}=0$ and $t_{n}=\sum_{N+1\leqslant i\leqslant n}i^{-1}$ for $n\geqslant N+1$, we set $m_{n}=\min\{m\geqslant n: t_{m}\geqslant t_{n}+T\}$ for each $n\in\mathbb{N}$. Recall the function $h$ as defined in \eqref{h_defn_fixed_size}. For each fixed $n\in\mathbb{N}$ with $n\geqslant N+1$, let $\{Z^{n}(t): t\geqslant t_{n}\}$, with $Z^{n}(t)=(a^{n}(t),b^{n}(t),c^{n}(t))$ for each $t\geqslant t_{n}$, indicate the solution to
\begin{equation}
\left(\dot{a}(t),\dot{b}(t),\dot{c}(t)\right)=h(a(t),b(t),c(t)) \text{ for all }t\geqslant t_{n}, \text{ with } \left(a(t_{n}),b(t_{n}),c(t_{n})\right)=\left(n^{-1}A_{n},n^{-1}B_{n},n^{-1}C_{n}\right),\nonumber
\end{equation}
and let 
\begin{equation}
W_{j}=(j+1)^{-1/2}\left\{\left(j^{-1}A_{j},j^{-1}B_{j},j^{-1}C_{j}\right)-\left(a^{n}(t_{j}),b^{n}(t_{j}),c^{n}(t_{j})\right)\right\} \text{ for each }j\geqslant n.\nonumber
\end{equation}
We now define the process $\{W^{n}(t):t\in [t_{n},t_{n}+T]\}$ by linear interpolation, as follows: 
\begin{equation}
W^{n}(t)=W_{j}+\frac{t-t_{j}}{t_{j+1}-t_{j}}(W_{j+1}-W_{j}) \text{ for }t\in[t_{j},t_{j+1}], \text{ for each }j\in\{n,n+1,\ldots,m_{n}-1\}.\nonumber  
\end{equation}  
Finally, we set $\tilde{W}^{n}(t)=W^{n}(t_{n}+t)$ for all $t\in[0,T]$. Likewise, we define $\tilde{Z}^{n}(t)=Z^{n}(t_{n}+t)$ for all $t\in[0,T]$. Then the laws of the processes $\{(\tilde{Z}^{n}(\cdot),\tilde{W}^{n}(\cdot))\}_{n\in\mathbb{N}}$ are relatively compact in the space $\mathcal{P}(C([0,T];\mathbb{R}^{3}))^{2}$, where $C([0,T];\mathbb{R}^{3})$ is the set of all continuous functions from $[0,T]$ to $\mathbb{R}^{3}$ and $\mathcal{P}(C([0,T];\mathbb{R}^{3}))^{2}$ is the space of all probability measures on $C([0,T];\mathbb{R}^{3})\times C([0,T];\mathbb{R}^{3})$.

If a subsequence of $\{(\tilde{Z}^{n}(\cdot),\tilde{W}^{n}(\cdot))\}_{n\in\mathbb{N}}$ converges in law to a limiting process $\{z^{*}(\cdot),w^{*}(\cdot)\}$, then $z^{*}(\cdot)$ belongs to a compact, connected, internally chain transitive invariant set corresponding to the ODE described by \eqref{ODE_fixed_sample_size}, and, letting $J_{h}$ denote the Jacobian of $h$, each of
\begin{multline}
w^{*}(t)-\int_{0}^{t}\left\{J_{h}\left(z^{*}(s)\right)+\frac{1}{2}I_{3}\right\}w^{*}(s)ds \quad \text{and}\quad \left[w^{*}(t)-\int_{0}^{t}\left\{J_{h}\left(z^{*}(s)\right)+\frac{1}{2}I_{3}\right\}w^{*}(s)ds\right]\\\left[w^{*}(t)-\int_{0}^{t}\left\{J_{h}\left(z^{*}(s)\right)+\frac{1}{2}I_{3}\right\}w^{*}(s)ds\right]^{T}-\int_{0}^{t}Q\left(z^{*}(s)\right)ds,\nonumber
\end{multline}
is a martingale for all $t\in[0,T]$, where $Q:\mathcal{S}\rightarrow\mathbb{R}^{3\times 3}$ is a matrix-valued function with entries given by
\begin{equation}
\begin{cases}
&Q_{1,1}(a,b,c)=H_{1}(a,b,c)\{1-H_{1}(a,b,c)\},\\
&Q_{1,2}(a,b,c)=Q_{2,1}(a,b,c)=H_{2}(a,b,c)\{1-H_{1}(a,b,c)\},\\
&Q_{2,2}(a,b,c)=H_{4}(a,b,c)-H_{2}^{2}(a,b,c),\\
&Q_{1,3}(a,b,c)=Q_{3,1}(a,b,c)=H_{2}(a,b,c)-H_{1}(a,b,c)H_{3}(a,b,c),\\
&Q_{2,3}(a,b,c)=Q_{3,2}(a,b,c)=H_{4}(a,b,c)-H_{2}(a,b,c)H_{3}(a,b,c),\\
&Q_{3,3}(a,b,c)=kq_{\beta}(a,b,c)\{1-q_{\beta}(a,b,c)\}+k^{2}\{1-q_{\beta}(a,b,c)\}^{2}-k^{2}H_{1}(a,b,c)\\&+2k H_{2}(a,b,c)-H_{3}^{2}(a,b,c),
\end{cases}
\end{equation}
with $H_{1}$, $H_{2}$ and $H_{3}$ as defined in \eqref{H_{1}_defn}, \eqref{H_{2}_defn} and \eqref{H_{3}_defn}, and $H_{4}:\mathcal{S}\rightarrow[0,k^{2}]$ defined as
\begin{equation}
H_{4}(a,b,c)=\sum_{i\in[k]}i^{2}g\left(\frac{i}{k}\right){k\choose i}q_{\beta}(a,b,c)^{i}\{1-q_{\beta}(a,b,c)\}^{k-i} \text{ for } (a,b,c)\in\mathcal{S},_defn}
\end{equation}
where $\mathcal{S}$ is as defined in \eqref{domain_defn} and $q_{\beta}(\cdot,\cdot,\cdot)$ is as defined in \eqref{q_defn}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:global_matrix_meromorphicity of arXiv:2603.27906, 'Marked GUE-corners process in doubly periodic dimer models'] The 1-forms

\begin{equation}
\mathcal R\ni (z_k,w_k)\mapsto \boldsymbol{\mathcal{M}}_{i_1,j_1,i_2,j_2}\left(z_1,w_1;z_2,w_2\right) \frac{\,\mathrm{d} z_1 \,\mathrm{d} z_2}{z_2(z_2-z_1)}, 
\end{equation}
for $k=1,2$ are meromorphic with possible poles only at $p_\infty$, $p_0$, $q_\infty$, $q_0$, and $(z_1,w_1)=(z_2,w_2)$.

