[Theorem 21 of arXiv:2506.10522, 'On the Law of the Iterated Logarithm for $m$-dependent stationary random variables under s'] Let $\{X_n;n=1,2,\cdots\}$ be a sequence of $m$-dependent and linear stationary random variables in a sub-linear space $\sles$ satisfying condition (CC). If there exists $M$ such that 
    \begin{equation}
        \Vstar\left(\limsup_{n\to\infty}\frac{|S_n|}{\sqrt{2n\log\log n}}\geq M \right) < 1,

    \end{equation}
    then 
    \begin{equation}
        C_{\V}\left[\frac{X_1^2}{\log\log |X_1|}\right]<\infty

    \end{equation}
    and
    \begin{equation}
        \lim_{n\to\infty}\frac{\bE[S_n]}{n}=\lim_{n\to\infty}\frac{\be[S_n]}{n}=0.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 5 of arXiv:2609.01296, 'Asymptotic safety regions for Gabor frames generated by Hermite functions'] Let $g \in L^2(\R)$ be nonzero. Define
    \begin{equation}
        \delta_g(b) := \delta_{\mathcal{D}_b g}
        = \frac{1}{2} \inf_{x \in [0,1]}
        \sqrt{\frac{\displaystyle\sum_{k\in\mathbb Z}|\widehat g(b(x-k))|^2}{\displaystyle\sum_{k\in\mathbb Z}(x-k)^2|\widehat g(b(x-k))|^2}}
    \end{equation}
    If $a b < \delta_g(b)$, then the Gabor system $\G(g, a \Z \times b \Z)$ is a frame.

