[Lemma lem:extreme_means of arXiv:2607.22291, 'Rare subtree patterns in size-conditioned Bienaymé trees: Poisson approximation and declum'] Assume (hyp:M of the paper)  for $(G_{k})$  along $(k_{n})$ with respect to $(M_{n})$. The following statements hold. 
\begin{enumerate}[label=\textup{(\roman*)}]
\item  If $n\pi_n\to0$, then under $\P(\cdot\mid S_n=-1)$,
$\sum_{i=1}^n I_i^{(M_n)}$ converges in probability to $0$;
\item  Assume in addition (hyp:C of the paper) for $(G_k)$  along $(k_{n})$ with respect to $(M_{n})$. If $n\pi_n\to\infty$, then $$ \frac{\sum_{i=1}^n I_i^{(M_n)}}{n\pi_n}  \quad \mathop{\longrightarrow}^{(\P)}_{n \rightarrow \infty} \quad1 \qquad \textrm{under } \P(\cdot\mid S_n=-1).$$
\end{enumerate}

[Definition defn_Mm of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] We define $m(z)\equiv m_N(z)$ as the unique solution to 
 \begin{equation}
m(z)= \big\langle \left(\Lambda -z- m(z)\right)^{-1} \big\rangle ,
\end{equation}
 such that $\im m(z)>0$ whenever $z\in \mathbb{C}_+$.  
 Then, we define the matrix $M(z)\equiv M_N(z,\Lambda)$ as 
\begin{equation}
M(z):= \left(\Lambda -z- m(z)\right)^{-1}.
 \end{equation}
Since $\Lambda$ is Hermitian, we have that $m(\overline z)= \overline {m(z)}$ and $M(\overline z)=M(z)^*$.

[Lemma lemma_localized_eigenvalue_local_law of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] In the setting of (theorem_localized_eigenvector_localization of the paper), the following estimate holds uniformly in $t\in \left[{0,1}\right]$ for some constant $C>0$ that does not depend on $\varepsilon$:

\begin{equation}
        \begin{aligned}
            \mathbb{E}\avg{\left({\im G_t}\right){\widehat{\Lambda}}_t\left({\im G_t}\right){\widehat{\Lambda}}_t}\prec N^{C\varepsilon}N^{-5/3}k^{2/3}\lVert A \rVert_{\text{\rm{HS}}}^2\le N^{-1-2\varepsilon_A+C\varepsilon}
        \end{aligned}
    \end{equation}

    where $G_t$ is defined by $G_t :=\left({H+t\Lambda-z_t}\right)^{-1}$ with $z_t$ defined in (equation eq:z1t of the paper).

