[Lem eq:inside:L:N of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] For every fixed $y \neq x$ and $\delta,\upsilon\geq 0$, $\varepsilon > 0$ set:
\begin{equation*}
    J_{\delta,\upsilon,\varepsilon}(y):=\mathbb{N}_{y}\Big(\sup_{t\geq 0}\Big|L_t(\rho,W)- \varepsilon^{-1}\int_{0}^{t} {\mathrm{d}} s \,  \mathbbm{1}_{\{\uptau_{\delta, \upsilon}(W_s)<H(\rho_s)<\uptau_{\delta, \upsilon}(W_s)+\varepsilon<\uptau(W_s) \}}\Big|\Big).
\end{equation*}
The following properties hold:
\begin{itemize}
\item[$\mathrm{(i)}$] $J_{\delta, \upsilon,\varepsilon}(y)\leq 2$;
\item[$\mathrm{(ii)}$] $ \limsup_{\upsilon \to 0} \limsup_{\varepsilon \to 0} J_{0,\upsilon,\varepsilon}(y)=0$. 
\end{itemize}

[Defi 17 of arXiv:2603.27433, 'The $k$-cycle shuffling with repeated cards'] Let $P_{n,k}$ be the random permutation in $\S_n$ given by
\begin{equation}
P_{n,k}:=\begin{cases}
(i_1\ldots i_k) & \text{with probability }\frac{k}{n(n-1)\cdots(n-k+1)}\\
\text{otherwise} & \text{with probability zero}\end{cases}.
\end{equation}
Moreover, for any $t\ge 1$, let $P_{n,k}^{*t}$ be the $t$-fold convolution of $P_{n,k}$. If $k$ is even and $t$ is odd, we view $P_{n,k}^{*t}$ as a random variable in $\A_n^c$; otherwise, we view $P_{n,k}^{*t}$ as a random variable in $\A_n$. Given $n=ml$ with $l\ge 2$, the random variable $\sim_l\backslash P_{n,k}^{*t}\in\sim_l\backslash\S_n$ is induced from \Cref{defi: quotient of space} in the obvious way.

[Lemma lem:supp_lmeasx of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] The set $\mathcal{G}_0 \coloneqq \{z \in \mathrm{HC} \mid z_a=0\}$ is a measurable set of full measure w.r.t.\ $\mu^{(a)}$ and $\var{\sigma^{(a)}}$, (where we identify $\mathcal{G}_0$ with its canonical embedding into $[C_0]$,) but it is not closed as a subset of $(C_0, \| \cdot \|_{\infty})$. Identifying the considered measures with their restrictions to $\mathcal{B}(L)\cap [C_0]$ or $\mathcal{B}(C_0,\|\cdot\|_{\infty})$ (see Remark (rem:embeddings_and_measurability of the paper)), it holds that
    \begin{equation*}
        \mathrm{supp} \, \mu^{(a)} = \mathrm{supp} \var{\sigma^{(a)}} = \{z \in C_0 \mid z_a=0\},
    \end{equation*}
    where the support is defined w.r.t.\ the topology on $C_0$ induced by $\| \cdot \|_{\infty}$.

[Theorem thm:global_clt_intro of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Define
\begin{equation}

    \sigma_n^2 = 
    \mleft( 1 - 2 p (1-p) \sum_{j=1}^K \beta_j \mathsf{e}_j (\mathsf{e}_j-1) p^{\mathsf{e}_j-2} \mright)^{-1}
    \times p(1-p) \binom{n}{2}.
\end{equation}
Then for any $\varepsilon > 0$, we have
\begin{equation}
    \mathbf{d} \mleft( \frac{\mathsf{E}(X) - \mathbb{E}[\mathsf{E}(X)]}{\sigma_n}, Z \mright) \lesssim n^{-\frac{1}{2} + \varepsilon},
\end{equation}
for both $\mathbf{d} = \mathbf{d}_\mathrm{Was}$ and $\mathbf{d} = \mathbf{d}_\mathrm{Kol}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:walk-overshoot of arXiv:2411.10113, 'Long-range one-dimensional\\ internal diffusion-limited aggregation'] Suppose that~(equation ass:irreducible of the paper) and~(equation ass:moments of the paper) hold. 
Then $\mu :=  \bE Y$ has $1 \leq \mu < \infty$, and
\begin{equation}

   \mu = \exp \left\{ \sum_{n=1}^\infty \frac{1}{n} \left[ \frac{1}{2} - \bP ( S_n > 0 ) \right] \right\} .
\end{equation}
Moreover, define the probability distributions $(\pi_k)_{k \in {\mathbb N}}$ 
and $(\psi_k)_{k \in {\mathbb N}}$ by
\begin{equation}

 \pi_k := \frac{\bP ( Y \geq k )}{\mu} , ~~~
 \psi_k := \frac{ k \bP ( Y = k)}{\mu}, 
 \text{ for } k \in {\mathbb N}.\end{equation}
 \begin{thmenumi}[label=(\roman*)]
    \item

Let $Z_\infty$, $L_\infty$ denote independent
random variables with distributions given by $\pi$, $\psi$ from~(equation eq:pi-k of the paper), respectively, and set $U_\infty := \max (Z_\infty, L_\infty)$. Then
\[ \sup_{y \in {\mathbb Z}_+} \bP_0 ( Z_y \geq k ) \leq \bP_0 ( U_\infty \geq k) , \text{ for all } k \in {\mathbb Z}_+. \] 
    \item

    It holds that, for every~$x \in {\mathbb Z}$ and every~$k \in {\mathbb N}$, 
\begin{equation}

 \lim_{y \to \infty} \bP_x ( Z_y = k  ) = \pi_k .\end{equation}
 \item 

 Suppose, additionally, that $\Exp ( |X|^p ) < \infty$, for some $p >2$. Then, 
\begin{equation}

\sup_{y \in {\mathbb Z}_+} \bE_x \bigl[ Z_y^{p-2} \bigr] < \infty .\end{equation}
\end{thmenumi} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:prefix-postbin-variance-budgets-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Assume that the local-mass bounds defining \(\mathcal G_n^{\mathrm{pre}}\) hold up to the levels under consideration. If \(2^n\le\lvert\xi\rvert\le2^{n+1}\) and \(
d\in\mathfrak D_{\xi,n}^{\mathrm{osc}}\), then
\begin{equation}
\sum_{\ell=0}^{m-1}
\sum_{I\in\mathcal D_\ell^\circ}
\sum_{\substack{J\in\mathcal D_{\ell+1}^\circ\\ J\subset I}}
\lvert c_J(\xi,d,\ell)\rvert^2M_IT_{\ell+1,n}
\le
C2^{2\varepsilon n}\lvert\xi\rvert^{-a},
\end{equation}
and
\begin{equation}
\sum_{\ell=m}^{\infty}
\sum_{I\in\mathcal D_\ell^\circ}
\sum_{\substack{J\in\mathcal D_{\ell+1}^\circ\\ J\subset I}}
\lvert c_J(\xi,d,\ell)\rvert^2M_IT_{\ell+1,n}
\le
C2^{2\varepsilon n}\lvert\xi\rvert^{-a}.
\end{equation}

