		For any $t\geq 0$ we have by Lemma \ref{weak_conv_times}, Lemma \ref{vanish} and Slutsky's theorem ...","release_manifest_digest":"sha256:d8129adbd25d09f7cd6ca1c7fa3bcf3a2731029a5134edf33ad2c5da756b2655","revision_digest":"sha256:1dfac49eda209135c54d77d1648e17cf7ae015e47faa9369af24e6dd1f8dbc9b","source_id":"arxiv:2605.15931","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

