body:
[Definition def:inhomo of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let $W_N$ be an $N\times N$ real symmetric (or complex Hermitian) Wigner matrix, let $\Sigma_N$ be a deterministic variance-profile matrix and $A_N$ be a finite-rank perturbation.  Define
\begin{equation} 
H_N=\Sigma_N \circ W_N,  
\end{equation}
where “\(\circ\)” is the Hadamard (entrywise) product, and the corresponding deformed inhomogeneous random  matrix
\begin{equation}
    X_N=H_N+A_N.
\end{equation}
Here,  the following conditions are assumed: 

\begin{enumerate}[leftmargin=*,label=(A\arabic*)]
  \item  \textbf{(Wigner matrix)}  
    The entries $\{W_{ij}\}_{i\le j}$ are independent, symmetric, and satisfy
    \begin{equation}
      \begin{cases}
        \mathbb{E}[W_{ii}^2]=2,\;\mathbb{E}[W_{ij}^2]=1, & \text{real 
        case},\\
        \mathbb{E}[W_{ii}^2]=1,\;\mathbb{E}[|W_{ij}|^2]=1,\;\mathbb{E}[W_{ij}^2]=0, & \text{complex 
        case}.
      \end{cases}
    \end{equation}
    Moreover, there exists $\theta\ge 1$ such that for all $k\ge2$,
    \begin{equation}
      \mathbb{E}\bigl[|W_{ij}\bigr|^{2k}]
      \;\le\;
      \theta^{\,k-1}(2k-1)!!,
     \end{equation}
    where  $\theta:=\theta_N\rightarrow\infty$ may be  allowed   if needed. 
  \item  \textbf{(Variance profile)}  
    The profile matrix $\Sigma_N=(\sigma_{ij})$ has nonnegative entries such that 
    \(\sum_{j=1}^N\sigma_{ij}^2=1\) for each~$i$.  Equivalently, 
    $P_N:=(\sigma_{ij}^2)_{i,j=1}^N
    $ is a Markov transition matrix.

  \item  \textbf{(Finite-rank deformation)}  
    The perturbation $A_N$ is symmetric (resp.\ Hermitian) of rank $r$, with spectral decomposition
    \begin{equation}
        A_N = Q\,\Lambda\,Q^*, 
      \qquad
      \Lambda = \mathrm{diag}(a_1,\dots,a_r,0,\dots,0),
    \end{equation}

    where $Q$ is an orthogonal (resp.\  unitary) matrix.  
\end{enumerate}

[Defn d.moment-function of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] \ 
We say that $\xi : \mathbb{R}^d \times \mathbb{K} \times \hat{\mathcal{N}}_{\mathbb{R}^d \times \mathbb{K}} \to \mathbb{R}$ satisfies a $p$-moment condition with respect to $\tilde{\mathcal{P}}$ 
 on {\em  finite windows}
 if $\xi( \tilde{x}_i, \tilde{\mathcal{P}}_n )$
satisfy  the $p$-moment condition~(equation e:xinpmom of the paper), that is to say

\begin{equation}

\sup_{1 \leq n< \infty} \sup_{1 \leq q \leq p} \sup_{x_1,\ldots,
  x_{q} \in W_n} \mathbb {E} _{\bk x1{q}}[ \max(1,|\xi(\tilde{x}_1, \tilde{\mathcal{P}}_n )|^p)]
\leq M_p^{\xi} < \infty.
\end{equation}

