[Proposition 4 of arXiv:2506.11799, 'Quenched limit for diffusive biased random walks in random environment'] Under our assumptions, there exists a universal constant $\eta>0$ such that we have that
	\begin{equation*}
		\inf_{x, y \in \mathbb{V}_d} \mathbb{P}_{x, y} \left( \{\mathcal{D}^\bullet = \infty\} \right) \ge \eta.
	\end{equation*}
    Furthermore, we have that for all $p>0$ there exists a constant $C = C_p$ such that
    \begin{equation*}
    	\sup_{x, y \in \mathbb{V}_d} \mathbb{E}_{x, y} \Bigg[ \Big(\sup_{0 \le t \le \mu^{(1)}_1} \|X^{(1)}_t\|\Big)^p \Bigg] < \infty,
    \end{equation*}
    the same result holds symmetrically for $X^{(2)}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 4 of arXiv:2606.10336, 'From Pitman's local times representation to the Gorin-Shkolnikov identity and beyond'] Assume that $\phi: \mathbb{R} \to \mathbb{R}$ be sufficiently smooth and $\int_0^1\phi(x)^2dx < \infty$.
We have:
\begin{equation}

\int_0^\infty \phi(I_x) dx - \frac{1}{4} \int_0^\infty \ell_x^2 \left( \frac{\phi(I_x)}{I_x} + \phi'(I_x) \right)dx 
\stackrel{d}{=} \mathcal{N}\left(0, \frac{1}{4} \int_0^1\phi(x)^2 dx\right).
\end{equation}

[Corollary 28 of arXiv:2605.04359, 'Well-posedness of reflected BSDEs with default time and irregular barrier: An application '] Let $Y^1$, $Y^2$ be two adapted processes with regulated trajectories of the form \eqref{form of the process for Ito}. Then
	\begin{equation*}
		\begin{split}
			Y^1_t Y^2_t&=Y^1_0 Y^2_0+\int_{0}^{t}Y^1_{s-}dY^{2,\ast}_s+\int_{0}^{t}Y^2_{s-}dY^{1,\ast}_s+\left[Y^{1,\ast},Y^{2,\ast}\right]_t\\
			&\qquad+\sum_{0 \leq s <t}\left(Y^1_{s+}Y^2_{s+}-Y^1_s Y^2_s\right),\quad t \in [0,T].
		\end{split}
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thmadm of arXiv:2411.09005, 'On Time-Changed Linear Birth-Death Process with Immigration at Extinction'] For $\alpha=\lambda=\mu$ and $n\ge0$, the series components of the state probabilities of TFLBDPwI are given by
	\begin{equation}
		p_{k}^\nu(n,t)=\begin{cases}
			\frac{(-1)^{k-n}c_{n,k}(\lambda t^\nu)^k}{\Gamma(k\nu+1)},\,k\ge n,\vspace{0.15cm}\\
			0,\ k<n,
		\end{cases}
	\end{equation}
	where $c_{0,0}=1$, $c_{0,k+1}=c_{0,k}+c_{1,k}$, $c_{1,k+1}=c_{0,k}+2(c_{1,k}+c_{2,k})$ and $c_{n,k+1}=(n-1)c_{n-1,k}+2nc_{n,k}+(n+1)c_{n+1,k}$ such that $c_{n,k}=0$ whenever $n>k$ for all $n\ge0$ and $k\ge0$.

