body:
[Lem l:1104.1 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] The following holds:
\begin{enumerate}
	\item 
Uniformly on ${\rm D}$,
\begin{equation}
	\psi_n \big(\lfloor {\rm e}^{n} \cdot \rfloor \big) 
	\underset{n \to \infty}\longrightarrow\
		\psi_{\rm D} \,,
\end{equation}
where $\psi_{\rm D}$ is as in~(equation e:1.9p of the paper). As $\psi_{\rm D}$ is a continuous function on $\overline{{\rm D}}$, the functions $\{\psi_n\}$ are uniformly bounded in the supremum norm and asymptotically equicontinuous, in the sense that 
\begin{equation}
    \lim_{\delta \downarrow 0} \limsup_{n\to \infty} \sup_{|x-y| < \delta {\rm e}^n} \big|\psi_n(x) - \psi_n(y) \big| = 0 \,.
\end{equation}
\item With $\overline{h}_{\rm D}$ as in~(equation e:1.7p of the paper),
\begin{equation}
	\overline{h}_n \underset{n \to \infty} \Longrightarrow \overline{h}_{\rm D} \,.
\end{equation}
\item 
With respect to the supremum norm on $\overline{{\rm D}}$, 
\begin{equation}

h^\psi_n(\lfloor {\rm e}^n \cdot \rfloor) \underset{n \to \infty}\Longrightarrow h^\psi_{\rm D}
\quad ; \qquad 
h^\psi_{\rm D} := \overline{h}_{\rm D} \psi_{\rm D} \,.
\end{equation}
The field $h_{\rm D}^\psi$ is Gaussian with mean zero and covariance given by
\begin{equation}
	\mathbb{E} h_{\rm D}^\psi(x)h_{\rm D}^\psi(y) = \frac{\int_{{\rm D} \times {\rm D}} G_{\rm D}(z,x) G_{\rm D}(z', y) {\rm d} z {\rm d} z'}{\int_{{\rm D} \times {\rm D}} G_{\rm D}(z,z') {\rm d} z {\rm d} z'} \,.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

