[Theorem 4 of arXiv:2608.29316, 'Powers of the Dirac Operator on $S^1\times S^{n-1}$'] On $V(f,j,\X,\e)$ the opeartor $\a^0A$ acts as a constant multiple of
\begin{equation}
Z_L(r,f,j,\Xi,\e)=\Xi\e\cdot\textstyle\frac{\G\left(\frac12(f+J+1+r-\Xi\e/2)\right)\G\left(\frac12(-f+J+1+r+\Xi\e/2)\right)}{\G\left(\frac12(f+J+1-r+\Xi\e/2)\right)\G\left(\frac12(-f+J+1-r-\Xi\e/2)\right)}
\end{equation}
and $A\a^0$ acts as a constant multiple of 
\begin{equation}
\begin{split}
Z_R(r,f,j,\Xi,\e)&=\Xi\e\cdot\textstyle\frac{\G\left(\frac12(f+J+1+r+\Xi\e/2)\right)\G\left(\frac12(-f+J+1+r-\Xi\e/2)\right)}{\G\left(\frac12(f+J+1-r-\Xi\e/2)\right)\G\left(\frac12(-f+J+1-r+\Xi\e/2)\right)}\\
&=-Z_L(r,f,j,\X,-\e).
\end{split}
\end{equation}

