[Proposition prop:link_gat_der_mall_der of arXiv:2605.07832, 'A Bismut -Elworthy formula for BSDEs with degenerate noise'] Let $A$ be defined as in (equation A of the paper), let $\Lambda : \mathcal{D} (\Lambda) \subseteq U \rightarrow U $ be a positive self-adjoint operator on a separable Hilbert space $U$ and Let us denote by $X^x$ the solution of the stochastic wave equation (equation wa1 of the paper) and by $P_t\,f,\, t>0,\, f\in B_b(H) $ its transition semigroup applied to $f$. Then for any $k\in {\cal H}$  there exists $\widetilde u\in L^2_{\cal P}(\Omega \times [0,T];U)$ such that 
\begin{align*}
\nabla_k (P_tf)(x) \langle \nabla^{\cal H} (P_tf)(x),\rangle_{\cal H}
= \mathbb E[f(X_t^x)\int_0^t u_s dW_s]
\end{align*}
and 
\begin{align} 
  | \langle \nabla^{\cal H} (P_tf)(x),\rangle_{\cal H}|
\leq\frac{c}{t^{3/2}} \|f\|_\infty 
\end{align}
Moreover if $h=Jb=\Big(
\begin{array}
[c]{c}
0\\
b
\end{array}
\Big)$ then 
\begin{align} 
  | \langle \nabla^{\cal H} (P_tf)(x),\rangle_{\cal H}|= | \nabla^J_b (P_tf)(x)|
\leq\frac{c}{t^{1/2}} \|f\|_\infty 
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] The densities $\rho_{c}$, $\rho_{1c}$, and $\rho_{2c}$ share the same support on $(0,\infty)$, which is a union of intervals. For $\al=1,2$,
\begin{equation}
{\rm{supp}} \, \rho_{c} \cap (0,\infty) ={\rm{supp}} \, \rho_{\al c} \cap (0,\infty) = \bigcup_{k=1}^{L} [e_{2k}, e_{2k-1}] \cap (0,\infty),
\end{equation}
where $L\in \mathbb N$ depends only on $\pi_{A,B}$. The points $(x,m)=(e_k, m_{2c}(e_k))$ are the real solutions to
\begin{equation}
f(x,m)=0, \quad \text{and} \quad \frac{\partial f}{\partial m}(x,m) = 0. 
\end{equation}
Finally, $e_1 = {\rm O}(1)$, $m_{1c}(e_1) \in (-(\max_{\mu}\sigma_\mu^b)^{-1}, 0)$, and $m_{2c}(e_1) \in (-(\max_i \sigma_{i}^a)^{-1}, 0)$.

[Lemma lemma_G_large_2 of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] In the setting of (mix of the paper), let $z=E+\mathrm{i} \eta$ with $\eta\gtrsim N^{-1/3+\tau_e}$ and $\eta/\im m (z) \sim N^{-\varepsilon_g}$ for some small constants $\tau_e,{\varepsilon}_g>0$. If $\varepsilon_g<({1/8})\wedge ({\delta_A/4})$, then for any $z_1,z_2\in\ha{z,\overline{z}}$, we have that
    \begin{equation}
        \begin{aligned}
            \max_{a\in [\![{D}]\!]}\absa{\mathbb{E}\avga{\left({G (z) -M (z) }\right)E_a}}\prec N^{-1}\left({\im m (z) }\right)^{-1},
        \end{aligned}
    \end{equation}
    \begin{equation}
        \begin{aligned}
            \left\|\mathbb{E} L_{(1,2)}-K_{(1,2)}\right\|_2\prec N^{-1}\eta^{-2}\pa{N^{-\tau_e\wedge \varepsilon_g}}.
        \end{aligned}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 of arXiv:2605.30560, 'Projected McKean--Vlasov Dynamics for Entropic Weak Optimal Transport'] When $d=1$ and $\mu,\nu \in \Pc_2(\R)$, for any $\pi\in\Pi(\mu,\nu)$,
\begin{equation}
\begin{aligned}
T^{\rm ad}_{\pi}\big(\Pi(\mu,\nu)\big)
& =
\big(L^2(\mu)\oplus L^2(\nu)\big)^{\perp},
\end{aligned}
\end{equation}
where orthogonality is taken in $L^2(\pi;\R^{2})$.
The orthogonal projection onto $T^{\rm ad}_{\pi}\big(\Pi(\mu,\nu)\big)$ is given by
\begin{equation}
\begin{aligned}
P^{\pi}:\ T^{\rm ad}_{\pi}\!\big(\Pc_2(\R^{2})\big) &\longrightarrow T^{\rm ad}_{\pi}\big(\Pi(\mu,\nu)\big),\\
u=(u_1,u_2) &\longmapsto \Big(0,\ u_2-\E_{Y}^{\pi}\!\big[u_2(X,Y)\big]\Big).
\end{aligned}
\end{equation}

