[Definition def:centered-capped-arrays-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] For \(d\in\mathfrak D_{\xi,n}^{\mathrm{osc}}\), 
set \(m=m_{\xi,d}\).
Define the stopped centered capped prefix array by
\[
\widehat F^{\mathrm{pre,cap}}_{\xi,d,n}
=
\sum_{\ell=0}^{m-1}
\mathbf 1_{\{\tau_n>\ell\}}
\sum_{I\in\mathcal D_\ell^\circ}
\sum_{\substack{J\in\mathcal D_{\ell+1}^\circ\\J\subset I}}
X_{J,n}^{\mathrm{cap}}(\xi,d,\ell).
\]
For \(L>m\), define the stopped centered capped post-bin partial sum by
\[
\widehat F^{\mathrm{post,cap}}_{\xi,d,n,L}
=
\sum_{\ell=m}^{L-1}
\mathbf 1_{\{\tau_n>\ell\}}
\sum_{I\in\mathcal D_\ell^\circ}
\sum_{\substack{J\in\mathcal D_{\ell+1}^\circ\\J\subset I}}
X_{J,n}^{\mathrm{cap}}(\xi,d,\ell).
\]
The corresponding unstopped arrays \(F^{\mathrm{pre,cap}}_{\xi,d,n}\) and \(F^{\mathrm{post,cap}}_{\xi,d,n,L}\) are obtained by removing the factors \(\mathbf 1_{\{\tau_n>\ell\}}\).

[Lemma 18 of arXiv:2605.09372, 'Sharp weighted norm estimates for martingale square functions'] Let $P_1\in\mathcal P_1$. We have
\begin{equation*}\sum_{i<\kappa_2(P_1)}\|W^{\frac1p}d_i(W^{-\frac1p}f)\|_{\mathbb C^d}^2\chi_{P_1}=0.
\end{equation*}

[Theorem 21 (Quantitative uniform spectral convergence) of arXiv:2608.30211, '2608.30211'] Assume $\partial\Omega\neq\varnothing$.  There are $C>0$ and
$\kappa_{\rm sp}>0$ such that
\begin{equation}
 \sup_{\varrho\in[0,1]}
 \bigl|\Lambda_{\kappa,\varrho}-\mu_\varrho\bigr|
 \leq C\kappa^{-1/2}
 \qquad(\kappa\geq\kappa_{\rm sp}).
\end{equation}

[Proposition prop.H1TwoScaleDeg2 of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] There exists a finite positive constant $C(c_{-},c_{+},\mathbf{r},\rho)$ such that for every $\lambda\in(0,\tfrac{1}{2})$, the following estimates about the expectation and variance of the carr\'e du champ of $\widetilde{G}_\lambda$ hold:
		\begin{multline}
			\left|\mathbb{E}_\rho\left[\sum_{b\in(\mathbb{Z})^*}\left(c_b(\pi_b\widetilde{G}_\lambda)^2\right)\left(\eta\right)\right]-2\expec{\overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}}\overline{G}_\lambda}\right|\\
			\leqslant C\left(\sqrt{\log (\lambda^{-1})}+3^{14m}\right)(3^{-\alpha m}\sqrt{\log(\lambda^{-1})}+3^{7m}),
		\end{multline}
		\begin{equation}
			\mathbb{V}\!\mathrm{ar}_\rho\left[\sum_{b\in(\mathbb{Z})^*}\left(c_b(\pi_b\widetilde{G}_\lambda)^2\right)(\eta)\right]\leqslant C 3^{38m}\left((\log(\lambda^{-1}))^{\frac{3}{2}}+1\right).
		\end{equation}

