[Lemma lem:vertex_split of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] There exists a map from the set of diagrams   with all unmarked vertices of degree at least $3$ to the set of typical connected diagrams 
\begin{equation}
    \phi : \mathscr{D}_{s;\beta}^* \to \mathcal{T}_{\ell, s}, \quad \Gamma \mapsto \phi(\Gamma)
\end{equation}
  such that  the following three conditions hold: 
\begin{itemize}
    \item[(i)] (Preserving $|E|-|V|$) 
    \begin{equation}
        |E(\phi(\Gamma))| - |V(\phi(\Gamma))| = |E(\Gamma)| - |V(\Gamma)|,
    \end{equation}

    \item[(ii)] (Monotonic decreasing) 
    \begin{equation}
        |E(\phi(\Gamma))| \ge |E(\Gamma)|, \qquad |V(\phi(\Gamma))| \ge |V(\Gamma)|,
    \end{equation}

    \item[(iii)] (Multiplicity controlling)  
       \begin{equation}
        |\phi^{-1}(\Gamma)| \le 2^{|E(\Gamma)|},\quad \forall \,\Gamma \in \mathcal{T}_{\ell, s}.
    \end{equation}

\end{itemize}

[Lemma 6 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] We have
    \begin{equation}

        \partial_{t} F(t,k) = - e^{DF(t,k)} + 1, \quad \forall k \in \N
    \end{equation}
    and 
    \begin{equation}

        \partial_{t} G(t,k) = - G(t,k) DG(t,k), \quad \forall k\in \N.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor concentration_meso of arXiv:2510.18856, 'Evolution of recursive trees with limited memory'] Fix $\beta \in (0,1)$. For any $\epsilon,\delta>0$ and $T < T_\beta = 2(1-\beta)^{-1}$ there exist constants $C=C(\delta,T)>0$ and $\xi=\xi(\epsilon)>0$ such that
    \begin{align*}
        \mathbb{P}\left(\exists\;\;v \in [\delta n, n]: \sup_{t\leqslant T }\left|\frac{1}{v}L_v(\lfloor tv^{1-\beta} \rfloor)-f_{\beta}(t)\right|>v^{\frac{-1+\beta}{2}+\epsilon}\right)\leqslant \exp(-Cn^{\xi}).
    \end{align*}

