[Definition def:zero of arXiv:2604.21142, 'Gaussian fluctuations for Internal DLA on cylinders'] A function $f : V_N \times {\ensuremath{\mathbb Z}}  \to {\ensuremath{\mathbb R}} $ has the zero horizontal average property if
	\begin{equation}
	\sum_{x \in V_N} f(x, y) = 0 \qquad \text{for every } y \in {\ensuremath{\mathbb Z}} \,.
	\end{equation}

[Lemma 10 of arXiv:2606.26619, 'Ergodicity of stochastic reaction-diffusion equations on unbounded domains driven by space'] Assume that (S1)--(S3) and (H5) hold. Define
  \begin{align*}
    h_{-}(u):=
  \begin{cases}
        -\gamma u + \inf_{0\leq v\leq u}\big(b(v) - b(0) - C_{b,\theta}\big), & u\geq 0, \\
        - C_{b,\theta}, & u\leq 0,\\
  \end{cases}
  \end{align*}
where $\gamma > 2(2\nu)^2 G_{\sigma}^2$. Let $v_{-}$ be the unique solution to (\ref{260603.1828}) with $\tilde{b}=h_{-}$. If
\[
m >\frac{G_{\sigma}^2}{8},
\]
then
\begin{align*}
  \sup_{t\geq 0}\sup_{x\in\mathbb{R}}\mathbb{E}|v_{-}(t,x)|^2 <\infty.
\end{align*}

[Lemma 15 of arXiv:2609.03793, 'Typical martingale diverges on a co-$\sigma$-porous set'] Let $\f\in\M_\infty$ and $r>0$ be arbitrary. Then there exists $\g\in\Mi, \pni{\g-\f}\leq\frac{r}{2}$ such that
\begin{equation}

\forall\varepsilon>0\exists m_0\in\N\forall m\geq m_0\forall u\in2^m\exists w\in2^{12m}\cap u\appinf:
\ab{g_{2m}(w)-g_{12m}(w)}
\geq r-\varepsilon
.
\end{equation}

