body:
[Proposition prop: second-order distrib of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] Let $m,n\geq0$, $x\in\mathcal E_{n}$ and $y\in\mathcal E_{m}$. Assume that for all $k\in\Gamma=\mathbb{Z}$,
    \begin{equation}
        \Phi^{(1)}\left(xU_{e_{L},k}\right)=\Phi^{(1)}\left(yU_{e_{L},k}\right)=0.
    \end{equation}
    For $k\in\mathbb{Z}$, we define $x^{(k)}:=xU_{e_{L},-k}=xu^{-k}$ and $ y^{(k)}:=yU_{e_{L},-k}=yu^{-k}.$ For $R,S\geq0$, let
    \begin{equation*}
        X^{(R)}:=\sum_{k=-R}^{R}x^{(k)},\qquad Y^{(S)}:=\sum_{k=-S}^{S}y^{(k)}.
    \end{equation*}
    If $R\geq2n+m,$ and $S\geq n+2m,$ then
    \begin{equation}
        \Phi^{(2)}\left(X^{(R)},Y^{(S)}\right)=\Phi^{(1)}\left(X^{(R)}Y^{(S)}\right).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:cumulant_flow of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Suppose that the force coefficients satisfy the flow equation (equation eq:flow2 of the paper), we then have the following equations for their joint cumulants as defined in Definition~(def:joint_cumulant of the paper). 

\begin{enumerate}
\item For $\text{${\boldsymbol{\tau}}$}\in\widehat\mathcal{T}$ such that $r(\text{${\boldsymbol{\tau}}$})\geqslant1$, and recall that $k
=
\min\{i\in[p({\boldsymbol{\tau}})]:r_i=1\}$. We then have
\begin{equs}
\text{$\text{{\Large $\kappa$}}$}_{\eps,\mu}^{\text{\scriptsize{${\boldsymbol{\tau}}$}}}=&-  \sum_{(\text{\scriptsize{${\boldsymbol{\sigma}}$}},\pi,\rho)\in\text{\scriptsize{$\mathrm{Ind}$}}(\text{\scriptsize{${\boldsymbol{\tau}}$}})     }  
\mathrm{A}^{\text{\scriptsize{${\boldsymbol{\tau}}$}}, (\text{\scriptsize{${\boldsymbol{\sigma}}$}},\pi,\rho)}_\mu
\Big(\big(\text{{\Large $\kappa$}}_{\eps,\mu}^{\text{\scriptsize{${\boldsymbol{\lambda}}$}}_q}\big)_{q=1}^{|\rho|}\Big)
       \,.
\end{equs}
\item Next, we turn to $\text{${\boldsymbol{\tau}}$}\in\text{$\widehat\mathcal{T}$}$ such that $r({\boldsymbol{\tau}})=0$, and $|{\boldsymbol{\tau}}|>0$. 
We then have 

\begin{equs}
\text{$\text{{\Large $\kappa$}}$}_{\eps,\mu}^{{\boldsymbol{\tau}}}=&-  
\sum_{k = 1}^{p({\boldsymbol{\tau}})} 
\sum_{(\text{\scriptsize{${\boldsymbol{\sigma}}$}},\pi,\rho)\in\text{\scriptsize{$\mathrm{Ind}$}}(\text{\scriptsize{$\mathbf{d}_{k}$}}\text{\scriptsize{${\boldsymbol{\tau}}$}})     } 
\int_0^\mu
\mathrm{A}^{\text{\scriptsize{$\mathbf{d}$}}_{k}{\boldsymbol{\tau}}, ({\boldsymbol{\sigma}},\pi,\rho)}_\nu \Big(\big(\text{{\Large $\kappa$}}_{\eps,\nu}^{\text{\scriptsize{${\boldsymbol{\lambda}}_q$}}}\big)_{q=1}^{|\rho|}
\Big)\mathrm{d}\nu
       \,.
\end{equs}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:Moran-Model of arXiv:2605.10617, 'Logarithmic scaling of selective sweep curves:\\ from tents to houses'] Fix $a, \varphi_N\geq 0$ and let $X^N=(X_0^N(t),X_1^N(t) , t \geq 0)$ be the counting process of the resident and mutant in the Moran model, that is we have $X_0^N(t)+ X_1^N(t)=N$, $\forall t \geq 0$ and with transition rates from $(k,N-k)$ given by
\begin{align}\begin{split}
    (k, N-k) \to (k+1,N-k-1) &\quad \text{ at rate } \quad  \phantom{(1+a\varphi_N)}\frac{k(N-k)}N\\
    (k, N-k) \to (k-1,N-k+1) &\quad \text{ at rate } \quad  (1+a \varphi_N)\frac{k(N-k)}N.
    \end{split}
\end{align}

[Definition 8 (Liouville field with boundary insertions on $\bH$) of arXiv:2608.27630, 'Oriented planar maps and \\ annular mating of trees'] In the setting above, sample $(h, \bfc)$ from the infinite measure
    \begin{equation}
        C_{\bH}^{(\beta_i, s_i)_{i=1}^m}
        \bP_{\bH}
        \times \ab[ e^{(\frac{1}{2}\sum_{i=1}^m\beta_i-Q)c}\Leb_{\bR}(\d c)],
    \end{equation}
    where
    \begin{equation}
        C_{\bH}^{(\beta_i, s_i)_{i=1}^m} = 
        \begin{cases}
        \prod_{i=1}^m \ab|s_i|_+^{-\beta_i(Q-\frac{\beta_i}{2})} \exp\ab(\frac{1}{4}\sum_{j=i+1}^m \beta_i\beta_j G_{\bH}(s_i, s_j)) \text{ if } s_1\neq \infty\\
        \prod_{i=2}^m \ab|s_i|_+^{-\beta_i(Q-\frac{\beta_i}{2}-\frac{\beta_1}{2})} \exp\ab(\frac{1}{4}\sum_{j=i+1}^m \beta_i\beta_j G_{\bH}(s_i, s_j)) \text{ if } s_1= \infty
        \end{cases},
    \end{equation}
    and take
    \begin{equation}

        \phi(z) = h(z)-2Q\log\ab|z|_+ +\frac{1}{2}\sum_{i=1}^m \beta_i G_{\bH}(s_i, z)+\bfc.
    \end{equation}
    We write $\LF_{\bH}^{(\beta_i, s_i)_{i=1}^m}$ for the law of $\phi$.

[Lemma sparse of arXiv:2412.05503, 'Critical scaling profile for trees and connected subgraphs \\ on the complete graph'] Let $n \ge 3$, $z \ge 0$, and $t=\sqrt{3e}$.
\begin{enumerate}
\item[(i)]
If $n^{3/2} z \le b$, then $A(n,z) \le C_b n^{3/2} z$ for some $C_b > 0$.

\item[(ii)]
If $\varepsilon > 0$, then
\begin{equation}
    A(n,z) \le C_\varepsilon
    \exp\Bigl\{ \big(\frac{1}{24}+\varepsilon \big)  e t^2 z^2 n^3  \Bigr\}
\end{equation}
for some $C_\varepsilon > 0$.
\end{enumerate}

