body:
[Corollary cor_join_bounds of arXiv:2411.02046, 'Speed of Convergence and Moderate Deviations of FPP on Random Geometric Graphs'] For~$x$ and~$t$ as in Lemma~(lem_T_t_and_T of the paper), we have
	\begin{equation}
		\p (| T(x) - Y_{t,x}| \ge \mathfrak C t ) \le 2^{-\Kprime \|x\|} + e^{-\mathfrak{c} t} + \|x\|^{4d} e^{-\mathfrak{c}_1 t},
	\end{equation}
	where~$\Kprime$ is defined in~(equation eq_def_Kprime of the paper),~$\mathfrak C$ and~$\mathfrak c$ are the constants of Lemma~(lem_q_and_no_q of the paper), and~$\mathfrak c_1$ is the constant of Lemma~(lem_T_t_and_T of the paper).

[Proposition 26 (Potter's bound, \protect{\autocite[Theorem 1.5.6) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] {BinghamGoldieTeugels1987RegularVariation}}]

Let \(f\) be a \(\beta\)-varying function. For all \(C>1\) and
\(\varepsilon>0\), there is \(A>0\) such that

\begin{equation*}{
 \forall x,y \geq A,\ \frac{f(x)}{f(y)} \leq C\times\left( \frac{x}{y} \right)^{\beta+\varepsilon} \vee \left( \frac{x}{y} \right)^{\beta-\varepsilon}.
}\end{equation*}

In particular, for all \(\varepsilon>0\) we have
\(x^{\beta-\varepsilon} \ll f(x) \ll x^{\beta+\varepsilon}\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 23 (Exact mixed-degree formula) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] For $p,q\ge1$, $f\in H^{\odot p}$, and $g\in H^{\odot q}$,
\begin{equation}
 \Gamma(I_p(f),I_q(g))
 =\sum_{s=1}^{p\wedge q}c_{p,q,s}
 I_{p+q-2s}(f\wtensor_sg),

\end{equation}
where
\begin{equation}
 c_{p,q,s}
 =p(s-1)!\binom{p-1}{s-1}\binom{q-1}{s-1}.

\end{equation}
When $p=q=s$, the term in \eqref{hs:eq:mixed-gamma} is the constant
$q!\ip fg$.

[Lm Perm Expansion of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] For deterministic matrices $A_1,\dots ,A_j$, we have
    \begin{equation*}
        \mathbb{E}\left[\prod_{i=1}^{j}\theta(t_i)^T A_i \theta(t_i)\right] = \sum_{\pi \in \mathcal{P}_2(\{1,2\} \times [j])} \left(\prod_{i \in [j]} \frac{e^{-|t_i-t_{\sigma(i)}|}}{n}\right)\prod_{i=1}^{l}\mathrm{Tr}\left(A_{\sigma_i^{(1)}}\cdots A_{\sigma_i^{(|\sigma_i|)}}\right),
    \end{equation*}
    where $\sigma = \sigma_1\cdots \sigma_l = \mathrm{Perm}(\pi)$ in the sum above, and each cycle in the disjoint cycle decomposition can be written as $\sigma_i = (\sigma_i^{(0)}\cdots \sigma_i^{(|\sigma_i|)})$.

[Lemma 3.9 of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] For all $0<u\le 1$, there exists $K_2(u_1,u)$ such that for all $n>n_2(u_1)$ and $z\in\mathbb R^3$ with $|z|\ge2^{-n}$, we have
    \begin{equation*}
        \mathbb{P}_{z}\Big(\tau_{\mathscr{T}}^{[K_2n^2]}<L_{B(0,2)}\Big)<u^n.
    \end{equation*}

[Definition 27 of arXiv:2608.18834, 'The Parabolic Anderson Model's Total Mass at Small Times: Geometry, Fluctuations, and Reno'] For every $H\in(0,1)$, define the measure
\begin{align}

\dd\mu_H(x)=
\frac{\Ga(2H+1)}{2\Ga(H)\Ga(1-H)}|x|^{1-2H}\d x
\qquad x\in\mbb R.
\end{align}
Then, define $\mu=\mu_{H_1}\otimes\cdots\otimes\mu_{H_d}.$
For the time covariance, we denote
\begin{align}

\nu=
\begin{cases}
\mu_{H_0}&\text{if }H_0<1,\\
\de_0&\text{if }H_0=1.
\end{cases}
\end{align}

[Definition def:trees of arXiv:2411.07157, 'Rough differential equations in the flow approach'] We associate to any $\underline{\tau}  \in \boldsymbol{\mathfrak{T}}$, an \textit{order} ${\mathfrak{o}}(\underline{\tau}) \eqdef |E(\underline{\tau})|$, a \textit{size} $\mathfrak{s}(\underline{\tau}) \eqdef |N(\underline{\tau})| = |E(\underline{\tau})|+1$, and a \textit{scaling} $|\underline{\tau}|$ defined by
    \begin{equs}
        |\underline{\tau}|\eqdef -1+\mathfrak{s}(\underline{\tau})H\equiv -1+({\mathfrak{o}}(\underline{\tau})+1)H\,.
    \end{equs}
All these quantities are well-defined for elements of $\mathfrak{T}$ as well and we overload notation accordingly. 

For $k\in\N$, we denote by $\mathfrak{T}_{\leqslant k}$ the set of all trees $\tau\in\mathfrak{T}$ with ${\mathfrak{o}}(\tau)\leqslant k$, and let
\begin{equs}
    \mathcal{T}\eqdef\mathfrak{T}_{\leqslant 2}\equiv\Big\{ \raisebox{0ex}{\includegraphics[scale=1.2]{figures/Xi.pdf}},\raisebox{-0.5ex}{\includegraphics[scale=1.2]{figures/XiX.pdf}},\raisebox{-1ex}{\includegraphics[scale=1.2]{figures/Tree1.pdf}},\raisebox{-.5ex}{\includegraphics[scale=1.2]{figures/Tree2.pdf}}\Big\}\,,
\end{equs}    
where in the graphical representation for trees, we always draw the root as the bottom node. 

We also define 
\begin{equs}
    \mathcal{T}_*\eqdef \{\raisebox{+0.05ex}{\includegraphics[scale=1.5]{figures/Xi.pdf}}\}\cup
    \Bigg\{\tau\in\mathfrak{T}_{\leqslant5} :
\begin{array}{c}
\exists\, \underline{\tau}_1\in\tau_1\in\mathcal{T}\,,\;\underline{\tau}_2\in\tau_2\in\mathcal{T},\text{ and}\;n\in N(\underline{\tau}_1)\\
\text{such that}\;\underline{\tau}_2\graft_n\underline{\tau}_1\in\tau
\end{array}
    \Bigg\}\,.
\end{equs}
Observe that $\mathcal{T}\subset\mathcal{T}_*$ and
\begin{equs}
    \tau\in\mathcal{T}_*\setminus\mathcal{T}\Rightarrow{\mathfrak{o}}(\tau)\geqslant3\Rightarrow|\tau|\geqslant\delta\eqdef-1+4H>0\,.
\end{equs}

[Lem 143 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Fix $\gamma''>0,\gamma'''\in\mathbb R$. Let $\mu\in\mathbb R$, $\mathfrak H_{q,\gamma'',\gamma'''}$ be as in \eqref{approxG2} and let
  \begin{eqnarray}
 		X=\hat x+\frac{\mathfrak d q}{2\gamma''} (\mu \hat x+\gamma'' \hat x^2);
		\qquad
		Y={\hat y}.
  \end{eqnarray}
  Then,
  \begin{eqnarray}

    \frak H_{q,\gamma''+\mu q \md,\gamma'''+3\gamma'' q}(\hat x,{\hat y})=    \frak H_{0,\gamma'',\gamma'''}(X,Y)+\mathcal O(q \md^2+q^2\md).
  \end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

