[Theorem 35 of arXiv:2601.16377, '2601.16377'] Suppose that Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic} and
 \ref{Assumptions_offcrit}
 hold. Let $[\mathfrak{a},\mathfrak{b}]$ be a saturation of the equilibrium measure. For each $\eps>0$ there
 exist $\N$-dependent integers $p < q$ and a real $C>0$ independent of $\N$ such that with
 probability greater than $1-C^{-1}e^{-C \N}$ the following two conditions hold:
 \begin{itemize}
  \item $\N \mathfrak{a} \leq \ell_{p}< \N(\mathfrak{a}+\eps)$ and $\N (\mathfrak{b}-\eps) <\ell_{q} \leq \N\mathfrak{b}$;
  \item The particles $\ell_p,\ell_{p+1},\ldots,\ell_{q}$ are densely packed.
 \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 5 (Khinchin's LIL) of arXiv:2608.04644, 'Khinchin's and Chung's Laws of the Iterated Logarithm at Time Zero for the Linear Stochast'] \textcolor{black}{Suppose  Condition~\ref{hypo} holds and that  $H<1$. Then, for every fixed} $x\in\RR^d$,
	\begin{equation}
		\begin{split}
			\limsup_{t \downarrow0} \frac{|u(t, x)|}{t^{H}\sqrt{2 \log\log(1/t)}}=\widetilde{\kappa},\ \ \ a.s.,
		\end{split}
	\end{equation}
	where $\widetilde\kappa$ is defined by
	\begin{equation}
		\widetilde\kappa=
		\begin{cases}
			\displaystyle
            \Biggl(\int_{\mathbb{R}^d} d\xi\,|\xi|^{\ell-d}
			\int_{[0,1]} ds\, s^{2(\beta+\gamma-1)}
			E_{\beta,\beta+\gamma}^2\left(-|\xi|^\alpha s^\beta\right)
			\Biggr)^{\!1/2}, & H_0=1/2,
            \\[2.5ex]
            \Biggl(c_{H_0}\int_{\mathbb{R}^d} d\xi\,|\xi|^{\ell-d}
			\int_{0}^1 \int_0^1ds_1ds_2\,|s_1-s_2|^{2H_0-2}\\
			\qquad\cdot s_1^{\beta+\gamma-1}
			E_{\beta,\beta+\gamma}\left(-|\xi|^\alpha s_1^\beta\right)\,
			s_2^{\beta+\gamma-1}
			E_{\beta,\beta+\gamma}\left(-|\xi|^\alpha s_2^\beta\right)
			\Biggr)^{\!1/2}, & H_0\in(1/2,1).
		\end{cases}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

