[Lemma 26 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb_{\leq n}$, $f:\cube^n\to \Rbb$, $q\in [1,2)$ and $t\geq 0$,
\begin{equation}
    \Vop^k(\Pop_t f) \leq \upe^{-2kt} \Vop^k(f)^{1-\vartheta} \min\left\{\Vop^k(f),\,\left\|\left|\grad^k f\right|\right\|_{\Leb^q}^{2},\, \sum_{J\subseteq[n]:|J|=k}\left\|\Dop_J f\right\|_{\Leb^q}^2\right\}^{\vartheta},
\end{equation}
and similarly, for all $J\subseteq [n]$,
\begin{equation}
    \Vop_J(\Pop_t f) \leq \upe^{-2t |J|} \Vop_J(f)^{1-\vartheta} \min\left\{\Vop_J(f),\,\left\|\Dop_J f\right\|_{\Leb^q}^2\right\}^{\vartheta},
\end{equation}
where $\vartheta=\vartheta(q,t) \triangleq \min\left\{\frac{q}{2-q}\tanh(t), 1\right\}$.

