[Theorem 5 of arXiv:2608.30638, 'On compact steady pluriclosed soliton surfaces'] Let $M$ be a Hopf surface, then $\pi_1(M)$ contains a cyclic subgroup $\langle \gamma\rangle$ with finite index. The action of $\gamma$ on $\mathbb C^2\setminus\{(0,0)\}$ under some holomorphic coordinate can be written as 
    \begin{equation}
        (z_1,z_2)\mapsto (\alpha z_1+\lambda z_2^m,\beta z_2)
    \end{equation}
    for $\alpha,\beta,\lambda\in\mathbb C$ and $m\in\mathbb N$ such that $0<\vert\alpha\vert\leq\vert\beta\vert<1$ and $\lambda\cdot(\alpha-\beta^m)=0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 45 of arXiv:2608.27307, '2608.27307'] Under Assumptions~\ref{ass:basic} and~\ref{ass:rand_ent}, suppose that $E_{+,0}$ is a regular right edge for $\Pi_0$ in the sense of Definition~\ref{def:reg_r_edge}. Then the rightmost edge $E_{+,0}$ of $\bnu_0$ is a regular right edge. Moreover,
        \begin{align}
                \abs{E_{+,0}-E_+}\lesssim t, \qquad c_{{\rm edge},0}\sim1, \qquad \gamma_{+,0}:=(\pi c_{{\rm edge},0})^{2/3}\sim1, \nonumber
        \end{align}
        and the constants in Proposition~\ref{prop:sqrt_edge} and Theorem~\ref{thm:opt_ll} may be chosen uniformly for $Y_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem17 of arXiv:2609.02795, 'Global smooth behavior in Kuznetsov and Westervelt type\\ viscous wave equations:\\ A unif'] Let $h\in \bigcup_{\iota>0} C^{1+\iota}_{loc} (\mathbb{R}^2)$ and
  $f\in \bigcup_{\iota>0} C^{1+\iota}_{loc} (\mathbb{R}^{2n+2})$ be such that there exists $\lambda>1$ with the property that for each $M>0$
  one can find $K_f(M)>0$ such that ((f1 of the paper)) holds.
  Then whenever $u_0\in C^2(\overline{\Omega})$ and $u_{0t} \in \bigcup_{\iota>0} C^{1+\iota}(\overline{\Omega})$ satisfy $u_0=u_{0t}=0$ on $\partial\Omega$,
  for $T_{max}$ and $u$ as correspondingly obtained in Lemma (lem_loc of the paper) it follows that
  \begin{eqnarray}\label{ext1}
	\hspace*{-2mm}
	\mbox{if $T_{max}<\infty$, \ then \  
	either \ } 
	\liminf_{t\nearrowT_{max}} \inf_{x\in\Omega} h\big(u(x,t),u_t(x,t)\big)=0
	\ \mbox{or} \

	\limsup_{t\nearrowT_{max}} \|u_t(\cdot,t)\|_{W^{1,p}(\Omega)} 
	= \infty
  \end{eqnarray}
  for all $p>n\cdot\max\{\lambda,2\}$ fulfilling $p\ge 2\cdot\max\{\lambda,2\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 7 of arXiv:2608.19396, '\bf Penalisation of Two-Dimensional Brownian Motion'] Let $(F_{t})_{t \geq 0}$ be a process belonging to $\mathcal{C}$. Then

  \begin{equation}\frac{\log t}{2 \pi} W^{(2)} (F_t) \underset{t \rightarrow \infty}{\longrightarrow} \mathbf{W}^{(2)}(F_{\infty})

  \end{equation}

[Definition of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] Let $J$ be a set of indices and consider two families of formal variables $\mathbf{x}=(x_{j})_{j\in J}$ and $\mathbf{x^{*}}=(x_{j}^{*})_{j\in J}$.
	    \begin{enumerate}
	        \item A \emph{*-test graph} $T = (G, \gamma, \epsilon )$ in the variables $\mathbf{x}$ is a finite connected multi-digraph $G = (V , E, \mathrm{src}, \mathrm{tar})$ together with edge labels $\epsilon : E \rightarrow \{1,*\}$ and $\gamma : E \rightarrow J$. One can see the maps $\gamma$ and $\epsilon$ as indicating that an edge $e\in E$ is labeled $x_{\gamma(e)}^{\epsilon(e)}$. The maps $\mathrm{src}$, $\mathrm{tar} : E \rightarrow V$ specify the source, $\mathrm{src}(e)$ and target, $\mathrm{tar}(e)$ of each edge $e \in E$. 
            \item A \emph{*-graph monomial} $g=(T,v_{in},v_{out})$ is a *-test graph $T$ together with the data of two vertices  $v_{in}$ and $v_{out}$ in $V$. We refer to the roots $(v_{in}, v_{out}) \in V^{2}$ as the input and the output, respectively, though they need not be distinct. We denote by $\mathcal{G}\langle\mathbf{x},\mathbf{x^*}\rangle$ the set of all such *-graph monomials which can be extended to $\mathbb{C}\mathcal{G}\langle\mathbf{x},\mathbf{x^*}\rangle$ the space of finite linear complex combinations of *-graph monomials in variable $\mathbf{x}$ (graphs are considered up to isomorphisms of graphs preserving labeled and in/outputs).
	    \end{enumerate}

[Lemma Eq 1 int G Ext Gamma H of arXiv:2604.15146, 'Renormalised two-point functions of CLE$_4$ gaskets'] We have the following equality between measures
supported on $\Gamma$:
$$
\nu^{\infty}_{\Gamma}(dz)
=
\1_{z\in\Gamma}
\int_{0}^{2\pi}
G_{\operatorname{Ext}(\Gamma)}(e^{i\theta},\infty)H_{\mathcal{A}_\Gamma}(dz,e^{i\theta})
d\theta
.
$$
In particular,
\begin{equation}

\int_{0}^{2\pi}
\int_{\Gamma}
G_{\operatorname{Ext}(\Gamma)}(e^{i\theta},\infty)H_{\mathcal{A}_\Gamma}(dz,e^{i\theta})d\theta
=1.
\end{equation}

