body:
[Definition def_weak_solution_complete of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] Given $\gamma:[0,1] \to [0,1]$ a measurable function and $F_\pm$ the functions defined in (equation def_F_pm of the paper), we say that $\rho:\Omega_T \to \mathbb{R}$ is a weak solution of \begin{align} 
    \begin{cases}
    \partial_t \rho_t(x) = \Delta \rho_t(x),  &(t,x) \in (0,T)\times (0,1), \\
    \nabla \rho_t(0) = - F_-(\rho(t,0)), &t \in (0,T),\\
    \nabla \rho_t(1) = F_+(\rho(t,1)), &t \in (0,T),\\
    \rho_0(x) = \gamma(x), &x \in [0,1],
    \end{cases} 
\end{align}
if the following two conditions are satisfied:
\begin{enumerate}
    \item $\rho \in L^2([0,T];H^1([0,1]))$ ;
    \item for every $H \in C^{1,2}( {\Omega_T})$,
     {\begin{align} \nonumber
        &\int_0^1 \rho_T(x) H_T(x)dx - \int_0^1 \gamma(x) H_0(x) dx  =\int_0^T \int_0^1 \rho_s(x) \partial_s H_s(x) dx ds \\ 
        &- \int_0^T \int_0^1 \nabla \rho_s(x) \nabla H_s(x) dx ds + \int_0^T \left\{ F_+[ \rho_s(1)] H_s(1) + F_-[ \rho_s(0)] H_s(0) \right\} ds.
    \end{align}}
\end{enumerate}

[Corollary 13 of arXiv:2609.03793, 'Typical martingale diverges on a co-$\sigma$-porous set'] Let $p\in[1, \infty)$ be arbitrary. Then
\begin{equation*}
\Bs{\f\in\M_p;\bs{\eta\in2^\N;\osc f_n(\eta)=\infty}\text{ is comeager in $(2^\N,\rhoexp)$}}
\end{equation*}
is co-$\sigma$-porous in $\M_p$. (Proof in the paper; no proof environment follows the statement in the TeX.)

