[Lemma 2 of arXiv:2603.25615, 'Fourier dimension of Mandelbrot cascades on planar curves'] Suppose that $1\leq q<p < q_{\max}$. If $1 < p/q \leq 2$, for any $1 \leq j \leq n $ and  $I \in \Q_j$, we have

    \begin{equation}
    \E(Y_{j,n }(q,I)^{p/q}) \leq \frac{b^{-2\tau(\frac{p}{2})+\frac{p\tau(q)}{q}}}{1-b^{-\tau(p)+\frac{p\tau(q)}{q}}}\,.    
    \end{equation}
    If $2^k < p/q \leq 2^{k+1}$ for some $k \geq 1$, for any $1 \leq j \leq n$ and $I \in \Q_j$, then 
    \begin{equation}
    \E(Y_{j,n}(q,I)^{p/q}) \leq \left({1-b^{-\tau(2q)+2\tau(q)}} \right)^{-2^{k+1}}.
    \end{equation}

[Proposition BoundedExpectedN of arXiv:2411.12522, 'Canonical insurance models: stochastic equations and comparison theorems'] For  $i,j \in \mathcal{Z}$, $i \neq j$,  $ T \in  [0,\infty)$, and $n \in \mathbb{N}$, it holds that 
	\begin{align*}
		\sup_{0 \leq s \leq t \leq T}\sup_{\omega \in \Omega } \mathbb{E}_{s}^i\big[  \big( N^{ij}(t) - N^{ij}(s)\big)^n\big](\omega) < \infty.
	\end{align*}
	 In particular, for $Y \in \mathbb{Y}$ we have 
	 \begin{align*}
	 	\sup_{0 \leq s \leq t \leq T}\sup_{\omega \in \Omega } \mathbb{E}_{s}^i\big[  |Y(t)-Y(s)|\big](\omega) < \infty.
	 \end{align*}

