[Corollary cor:lbm-first-order-splitting of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Let $x\in\Omega_{\rm LBM}$ and let $\Lambda>0$ be a multiple eigenvalue of
$A_x$.  There exists $q\in\mathcal Q_D$ such that
\begin{equation}
 B_q^\Lambda(M_x)
 =-\gamma\LambdaP_\Lambda^x
   \operatorname{Mult}_q\big|_{E_x(\Lambda)}

\end{equation}
has simple spectrum.  Hence the analytic branches issuing from $\Lambda$
along $M_{x,\tau}^{q}=e^{\gamma\tau q}M_x$ have pairwise distinct first
derivatives at zero.

[Lemma lem:recursion of arXiv:2609.02829, 'Quantitative explosion and percolation of the divisible sandpile'] For all $n \geq 0$ and $x\in\mathbb{Z}^d$,
			\begin{equation}
			u_{n+1}(x) = \biggl(\frac{1}{2d}\sum_{y \sim x} u_n(y) + \zeta(x)\biggr)_+\, .
			\end{equation}

[Lemma of arXiv:2607.14087, 'Stochastic Domination of Gaussian Maxima: A Resolution of the Weak Simplex Conjecture'] \label[lemma]{lem:bivariate-upper-tails}
Let $(G,H)$ be a centered bivariate Gaussian vector with unit variances and
correlation $\rho\in[-1,1]$.  Then
\[
  \lim_{t\to\infty}
  \frac{\mathbb P\{G>t,H>t\}}{\overline\Phi(t)^2}
  =
  \begin{cases}
    0,&\rho<0,\\
    1,&\rho=0,\\
    +\infty,&\rho>0.
  \end{cases}
\]

[Corollary cor:Ito_Lie_series of arXiv:2411.06827, 'The Exponential Lie Series and a Chen--Strichartz Formula for L{\'e}vy Processes'] In terms of the It{\^o} integrals $I_w$ the Chen--Strichartz series is given by
\begin{align*}
\log\bigl(\varphi_t\bigr) &  = 
\log\biggl(\sum\limits_{w\in{\mathbb A}^\ast} I_w(t)D_w\biggr) 
  = \sum\limits_{w\in{\mathbb A}^\ast} I_{w}(t) \biggl(\sum_{\sigma\in{\mathbb S}(|w|)}
\frac{1}{|\sigma|} c_\sigma 
V_{[\exp_{\mathrm H}^\dag (\sigma (w))]_{{\mathrm L}}}\biggr).
\end{align*}

[Proposition 14 (Swapping the local time for GFF) of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] Given two naturals $n>k\ge1$, a real $t>0$ and a function $f\in\Cloc^+$, define
\begin{equation}

U_{n,k}(f):=E^\varrho\biggl(\,\prod_{x\in\BbbL_n}\texte^{-f(\theta_n(x),\sqrt{L_t(x)}-m_n,\,\sqrt{L_t(x)}-\sqrt{L_t(x\cdot)}\,)\,1_{\MM_{n,k}(\sqrt{L_t},\,x)}}\biggr)
\end{equation}
and
\begin{equation}

V_{n,k}(f):=E^\varrho\otimes \wt E\biggl(\,\prod_{x\in\BbbL_n}\texte^{-f(\theta_{n-k}(z),\sqrt{L_t(z)}+h(x)-h(z)-m_n,\,h(x)-h(x\cdot)\,)\,1_{\MM_{n,k}(h,x)\cap \BB_{n,k}(x)}}\biggr),
\end{equation}
where we put $z:=\frakm^k(x)$ to reduce clutter and with the same convention set
 \begin{equation}

\BB_{n,k}(x):=\Bigl\{m_k+k^{1/3}\le m_n-\sqrt{L_t(z)}\le m_k+k^{2/3}\Bigr\}.
\end{equation}
Then
\begin{equation}

\lim_{k\to\infty}\limsup_{n\to\infty}\bigl|U_{n,k}(f)-V_{n,k}(f)\bigr|=0
\end{equation}
holds for all $t>0$ and all $f\in\Cloc^{+}$. Moreover, 
\begin{equation}

\lim_{\ell\to\infty}
\limsup_{k \to \infty} \limsup_{n \to \infty} 
P^\varrho\otimes\wt P\biggl(\,\sum_{x\in\BbbL_n}1_{\MM_{n,k}(h,x)\cap \BB_{n,k}(x)}1_{\{\sqrt{L_t(z)}+h(x)-h(z)>m_n-\lambda\}}>\ell\biggr)=0
\end{equation}
holds for all $t>0$ and all~$\lambda>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:mu-doublePrime of arXiv:2412.09290, 'Asymptotics of Harish-Chandra transform and infinitesimal freeness'] Let $\Psi, \Phi, \mathrm{T}$ be infinitely differentiable functions at $0$ and
  consider the sequences $(c_n)_{n \in \mathbb{N}}, (c'_n)_{n \in \mathbb{N}},
  (c''_n)_{n \in \mathbb{N}}$, where for every $n \in \mathbb{N}$
  \[ c_n := \frac{\Psi^{(n)} (0)}{(n - 1) !}, \text{\quad} c'_n :=
     \frac{\Phi^{(n)} (0)}{(n - 1) !} \text{\quad and\quad} c''_n := 2
     \frac{\mathrm{T}^{(n)} (0)}{(n - 1) !} . \]
  Then for the sequence $(\ensuremath{\boldsymbol{\mu}}''_k)_{k \in \mathbb{N}}$ defined by
  ((Ss of the paper)), for every $k \in \mathbb{N}$,  we have
  \[ \ensuremath{\boldsymbol{\mu}}''_k = \frac{1}{2} \left( \sum_{\pi \in \ensuremath{\operatorname{NC}} (k)}
     \sum_{V \in \pi} c''_{|V|} \prod_{\underset{W \neq V}{W \in \pi}} c_{|W|}
     + \sum_{\pi \in \ensuremath{\operatorname{NC}} (k)} \sum_{\underset{W \neq V}{V, W \in \pi}}
     c'_{|V|} c'_{|W|} \prod_{\underset{U \neq V, W}{U \in \pi}} c_{|U|}
     \right) . \]

