body:
[Theorem prop_4 of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] Let $m\geq1$ be an integer, $0<b<1$, $\|A\|_{m+1}$ be Schatten norm of order $m+1$ for a symmetric matrix $A$ and $r(A)$ be the rank of $A$. Then  
 \begin{eqnarray}

\Pr(\boldsymbol{\Delta}>t)\leq e^{\Lambda_m(t, b)},
\end{eqnarray} 
 where\footnote{The function $\Lambda(t,a)$ in ((en_exp of the paper)) and the functions $\Lambda_m(t,b)$ in ((Lambda_m of the paper)) are not related. }
 \begin{eqnarray}

\Lambda_m(t, b)=\frac{r(A)}{2}\sum_{k=2}^m \frac{b^k}{k}-\kappa_m(b)\min\bigg\{\frac{t^{1+\frac{1}{m}}}{\|A\|_{m+1}^{1+\frac{1}{m}}}, \frac{t}{\|A\|} \bigg\} 
\end{eqnarray}
and 
\begin{eqnarray}

\kappa_m(b)=\frac{m}{2(m+1)}\min\bigg\{\frac{1}{\big((m+1)\theta_m(b)\big)^{\frac{1}{m}}}, b\bigg\}
\end{eqnarray}
with $\theta_m(b)$ as defined in ((theta_func of the paper)).

[Lemma eq:joint-K-subg of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:remainder-tight}
Suppose, without requiring independence, that the coefficient vector
satisfies the joint linear-form estimate
\begin{equation}
 \mathbb E\exp\left\{\sum_{I\in[N]^p}t_IJ_I\right\}
 \le\exp\left\{\frac{K^2}{2}\sum_{I\in[N]^p}t_I^2\right\},
 \qquad t\in\mathbb R^{N^p}.
\end{equation}
Then
\begin{equation}
 \mathbb E\sup_{x\in\mathbb S^{N-1}(1)}\left\lvertR_N(x)\right\rvert\le C_{p,K}
\end{equation}
uniformly in \(N\).  Consequently, there is \(M=M(p,K)\) such that
\begin{equation}
 \inf_N\mathbb P\left(\left\lVertR_N\right\rVert_\infty\le M\right)\ge\frac12.
\end{equation}

