    \begin{equation} 
    \rcP_{\Lambda_{(\rho+1)n}}^\xi[\calH(\rho n,n)]\geq c.\tag{RSW}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 55 (Chaos-degree tightness) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] The packet is degree-tight if
\begin{equation}
 \boxed{\eta_0(Q)\longrightarrow0.}
 \tag{$\mathrm{QT}_2$}
\end{equation}

[Proposition 25 (\textsf{Local total-variation convergence}) of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] For every compact $K\subset\R$,
  \begin{align}
    \sup_{u\in K}
    \|Q_u^\eps-Q_u\|_{\mathrm{TV}}
    \xrightarrow{\eps\to 0}0.
  \end{align}
  Consequently, if $K_1,K_2\subset\R$ are compact and
  $h:K_1\times K_2\times\DN\times\DN\to\R$ is bounded and
  measurable, then
  \begin{align}
    \sup_{\substack{u\in K_1\\v\in K_2}}
    \left|
      \int_{\DN^2} h(u,v,\ga,\wt\ga)
        Q_u^\eps(d\ga)Q_v^\eps(d\wt\ga)
      -\int_{\DN^2} h(u,v,\ga,\wt\ga)
        Q_u(d\ga)Q_v(d\wt\ga)
    \right|\longrightarrow0.
  \end{align}

