[Pro pro2.1 of arXiv:2603.13873, '{Solvability of BSDEs with possibly unbounded stochastic coefficients \\ on a general weig'] Let the assumptions of (pro2.01 of the paper) hold. Then there exists a constant $C_{\bar{p},\theta}>0$ depending only on $\bar{p}$ and $\theta$ such that for each $0\leq r\leq t< +\infty$,
\begin{align*}
\begin{split}
&\mathbb{E}\left[\sup_{s\in[t\wedge\tau,\tau]}\left(e^{\bar{p}\int_{0}^{s}
\bar{\rho}_{r}{\rm d}r}|y_s|^{\bar{p}}\right)\bigg|\mathcal{F}_{r\wedge\tau}\right]+ \mathbb{E}\left[\left(\int_{t\wedge\tau}^{\tau}e^{2 \int_{0}^{s}\bar{\rho}_r{\rm d}r}|z_s|^2{\rm d}s\right)^\frac{\bar{p}}{2}\bigg|\mathcal{F}_{r\wedge\tau}\right]\\
&\hspace{0.6cm}+\mathbb{E}\left[\int_{t\wedge\tau}^{\tau}\bar{p}e^{\bar{p} \int_{0}^{s}\bar{\rho}_r{\rm d}r}(\bar{\rho}_s-\bar{\mu}_s-\frac{\theta}{2[1\wedge(\bar{p}-1)]}
{\bar\nu_s}^2)|y_s|^{\bar{p}}{\rm d}s\bigg|\mathcal{F}_{r\wedge\tau}\right]\\
&\ \ \leq
C_{\bar{p},\theta}\mathbb{E}\left[e^{\bar{p}\int_{0}^{\tau}\bar{\rho}_{r}{\rm d}r}|\xi|^{\bar{p}}+\left(
\int_{t\wedge\tau}^{\tau}e^{ \int_{0}^{s}\bar{\rho}_r{\rm d}r}f_s{\rm d}s\right)^{\bar{p}}\bigg|\mathcal{F}_{r\wedge\tau}\right].
\end{split}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq83 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Define the sub-$\sigma$-algebras $(\mathcal{A}^{(n)})_{n \geq 0}$ of $\mathcal{F}$ by letting, for each $n \in \mathbb{N}_{0}$,
\begin{align}  
\mathcal{A}^{(n)} \coloneqq \sigma( \pi_{v}: v \in \mathcal{I} \, \, \text{such that} \, \, |v| \leq  n).
\end{align}
\noindent We say that a characteristic $\varphi: \Omega \times \mathbb{R} \rightarrow \mathbb{R}$ is an {\sl $h$-dependent descendant characteristic}, for $h \in \mathbb{N}_{0}$, if the map $(\omega, t) \mapsto \varphi(\omega, t)$ is measurable with respect the product $\sigma$-algebra $\mathcal{B}(\mathbb{R})\times \mathcal{A}^{(h)}$, where $\mathcal{B}(\mathbb{R})$ is the Borel $\sigma$-algebra.

