[Thm domain-mon of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $D, \tilde D\subseteq\mathbb C$ be two simply connected domains such that $D\subseteq\tilde D$. Let $\phi$ and $\tilde\phi$ be two GFFs in the respective domains. We have that:
    \begin{enumerate}[label=(\roman*)]
        \item For any $\alpha\in(0,\sqrt{2})$ and any $z,w\in D$, 
        \begin{equation}
             \langle :\! \cos(\alpha\phi(z)) \!: :\! \cos(\alpha\phi(w)) \!: \rangle \geq \langle :\! \cos(\alpha\tilde\phi(z)) \!: :\! \cos(\alpha\tilde\phi(w)) \!: \rangle. 
        \end{equation}
        \item For any $\alpha\in(0,1]$ and any $z,w\in D$, 
        \begin{equation}
             \langle :\! \sin(\alpha\phi(z)) \!: :\! \sin(\alpha\phi(w)) \!: \rangle \leq \langle :\! \sin(\alpha\tilde\phi(z)) \!: :\! \sin(\alpha\tilde\phi(w)) \!: \rangle.
        \end{equation}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:lifts of arXiv:2608.29657, 'Hypocoercivity of Tempered Bouncy Particle Samplers for Heavy-Tailed Targets'] Recall ${\mathcal L}_\sigma g = - \nabla_x^\star \sigma^2 \nabla_x g $ for any $g\in C^2({\mathbb R}^d)$. The following equalities hold:
    \begin{align}
    \Pi\, {\mathcal L}_{\mathrm{tr}} \Pi\, b  = 0 \quad \text{and}\quad \Pi\, {\mathcal L}_{\mathrm{tr}}^\star \Pi\, b  = 0\quad&\text{for any  $b \in C^1_\Pi$;}  \tag{L1}\\
    \Pi\, {\mathcal L}_{\mathrm{tr}}^\star {\mathcal L}_{\mathrm{tr}} \Pi f  = -{\mathcal L}_\sigma \Pi f, \quad &\text{for any } f \in C_\Pi^2;\tag{L2}\\
    \langle {\mathcal L}_{\mathrm{tr}}^\star h, g \rangle_{L^2(\mu_\sigma)} = \langle h, {\mathcal L}_{\mathrm{tr}} g \rangle_{L^2(\mu_\sigma )} , \quad &\text{for any } h \in W_{\mathrm{tr}^\star} \text{ and } g \in W_\mathrm{tr}.  \tag{L3}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] A mild solution $X(\cdot)$  is a strong solution  to (eqSEE of the paper) if the following three conditions hold for all $x \in H$ and $0 \leq s \leq t \leq T$, a.s.,  
    \begin{enumerate}[(i)]
        \item  $X_0 \in D(A), S(t-s) F(s, x) \in D(A)$ and $S(t-s) \widetilde{F}(s, x) \in D(A)$;
        \item  $|A S(t-s) F(s, x)|_H \leq \alpha(t-s)|x|_H$ for some real-valued stochastic process $\alpha(\cdot) \in L_{\mathbb{F}}^{1}(0, T)$ a.s.; 
        \item  $|A S(t-s) \widetilde{F}(s, x)|_H \leq \beta(t-s)|x|_H$ for some real-valued stochastic process $\beta(\cdot) \in L_{\mathbb{F}}^{2}(0, T)$ a.s.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

