[Lem NormalisedDist of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] Let
$\gamma:\left[\tau_{1},\tau_{2}\right]\rightarrow\mathbb{R}^{2}$
be a continuous BV path. There exist  $\delta_1,\delta_2,r\in(0,1)$ such that the following properties hold true. Let $a<b<d$ be elements
of $\left[\tau_{1},\tau_{2}\right]$ such that $\gamma_{a}\neq\gamma_{b}$ 
\[
\left|\gamma_{b}-\gamma_{c}\right|<\delta_{1}\left|\gamma_{b}-\gamma_{a}\right|.
\]for all $c\in[b,d]$. 

\vspace{2mm}\noindent (i) One has
\begin{equation}
\left|\mathcal{A}_{a,d}(\gamma_{b})-\mathcal{A}_{a,d}(\gamma_{c})\right|<\frac{\delta_{1}}{1-\delta_{1}},\ \left|\mathcal{A}_{a,d}(\gamma_{c})-\left(1,0\right)\right|<\frac{2\delta_{1}}{1-\delta_{1}}
\end{equation}for all $c\in[b,d]$;

\vspace{2mm}\noindent (ii) One has 
\begin{equation}
\mathcal{A}_{a,d}(m_{a,b})\subseteq\Big(\frac{1}{2}-\frac{\delta_{1}/2}{1-\delta_{1}},\frac{1}{2}+\frac{\delta_{1}/2}{1-\delta_{1}}\Big)\times\mathbb{R}
\end{equation}and 
\begin{equation}
\overline{B\big({\cal A}_{a,d}(m_{a,b}),r\big)}\bigcup\overline{B\big({\cal A}_{a,d}(m_{a,b})-(\delta_{2},0),r\big)}\subseteq(0,1)\times\mathbb{R},
\end{equation}where $m_{a,b}\triangleq(\gamma_a+\gamma_b)/2$ and $B(x,r)$ denotes the ball centered at $x$ with radius $r$;

\vspace{2mm}\noindent (iii) The four sets \[
{\cal A}_{a,d}\gamma|_{[b,d]},\ {\cal A}_{a,d}\gamma|_{[b,d]}-(1,0),\ \overline{B\big({\cal A}_{a,d}(m_{a,b}),r\big)},\ \overline{B\big({\cal A}_{a,d}(m_{a,b})-(\delta_{2},0),r\big)}
\]are disjoint.

\vspace{2mm}\noindent (iv) Let $L^{a,b}$ denote the straight line joining $\mathcal{A}_{a,d}(\gamma_a)$ and $\mathcal{A}_{a,d}(\gamma_b)$. Suppose that $L^{a,b}$ is not horizontal. Then
\begin{equation}
\overline{B\big({\cal A}_{a,d}(m_{a,b})-(\delta_{2},0),r\big)}\bigcap L^{a,b}=\emptyset.
\end{equation}
\begin{comment}
let $L^{a,b}$ denote the straight line joining the points $\mathcal{A}_{a,d}\gamma_{u}$
and $\mathcal{A}_{a,d}\gamma_{v}$. Then there exists $\delta_{1},\delta_{2},r>0$
such that
\begin{align*}
\mathcal{A}_{a,d}\gamma|_{\left[b,d\right]}, & \mathcal{A}_{a,d}\gamma|_{\left[b,d\right]}-\left(1,0\right)^{T}\\
\overline{B\left(\mathcal{A}_{a,d}\left[\frac{1}{2}\left(\gamma_{a}+\gamma_{b}\right)\right],r\right)} & ,\overline{B\left(\mathcal{A}_{a,d}\left[\frac{1}{2}\left(\gamma_{a}+\gamma_{b}\right)\right]-\left(\delta_{2},0\right)^{T},r\right)}
\end{align*}
are disjoint and
\[
\overline{B\left(\mathcal{A}_{a,d}\left[\frac{1}{2}\left(\gamma_{a}+\gamma_{b}\right)\right],r\right)},\overline{B\left(\mathcal{A}_{a,d}\left[\frac{1}{2}\left(\gamma_{a}+\gamma_{b}\right)\right]-\left(\delta_{2},0\right)^{T},r\right)}\subseteq\left(0,1\right)\times\mathbb{R}.
\]
and if $L^{a,b}$ is not horizontal,
\begin{equation}
\overline{B\left(\mathcal{A}_{a,d}\left[\frac{1}{2}\left(\gamma_{a}+\gamma_{b}\right)\right]-\left(\delta_{2},0\right)^{T},r\right)}\cap L^{a,b}=\emptyset.
\end{equation}
\end{comment} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2608.23989, 'Collision Properties in Discrete and Continuous Time on Bounded-Degree Graphs'] Let~$P$ be an irreducible Markov kernel on $\mathsf S$, and let $G_{\rm disc}$ and $G_{\rm cont}$ be the Green kernels associated with $\mathsf P_{\rm disc}$ and $\mathsf P_{\rm cont}$, respectively. Suppose that, for some~$\alpha>0$,
\begin{equation}
\inf_{x \in \mathsf S} P^2(x,x) \ge \alpha
\end{equation}
Then, there exists~$A = A(\alpha) > 0$ such that
$$ A \cdot G_{\rm disc}( (x,x);(y,y) ) \leq G_{\rm cont}( (x,x);(y,y) ) \leq 2 G_{\rm disc}( (x,x);(y,y) ). $$
for each~$x,y \in \mathsf S$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 18 of arXiv:2506.20411, 'Maximal Counts in the Stopped Occupancy Problem'] For fixed $k\in {\mathbb Z}$, $j\in{\mathbb Z}_{>0}$ and $M_n:=M_{n,1}(\tau_n)$,
\begin{align}
&{\mathbb P}[M_{n}-b_n=k,~\mu_{n, b_n+k}(\tau_n)=j]=\\\notag&\qquad
\int_{-\infty}^\infty p_0\left(e^{(e-1)s+ c_n-k}\right)p_j\left((e-1)e^{(e-1)s+c_n-k}\right)  e^{-s}p_\ell(e^{-s}){\rm d}s+o(1).
\end{align}

[Lemma limit os Delta z at S_1 of arXiv:2609.02073, 'Existence of closed non-planar $p$-elasticae'] Let $(\lambda_n,C^2_n) \to (\lambda,0) \in \partial S_1^\rho$ with $\lambda<p-1$, then
    \begin{equation*}
       \Delta z(\lambda_n,C_n^2) \to \frac{2(p-1)}{p|J_0|} \int_{u_{m}}^1 \frac{(p-1)u-\lambda}{u^{\frac{1}{p}}\sqrt{\left( \frac{(p-1)^2}{p^2}-2\lambda \frac{p-1}{p^2} \right)-\frac{(p-1)^2}{p^2} u^2 + 2\lambda\frac{p-1}{p^2}u}}du =: \Delta z(\lambda, 0).
    \end{equation*}

