[Definition 5 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let $I$ be a solution to~\eqref{eq:SIS epidemic model} with positive paths and $\rho,x_{0} > 0$.
\begin{enumerate}[(i)]
\item We say that $I$ becomes \emph{extinct with exponential rate $\rho$} if 
\begin{equation}
\limsup_{t\uparrow\infty} \frac{1}{t^{\rho}}\log(I_{t}) < 0\quad\text{a.s.}
\end{equation}
In the case $\rho = 1$ we will simply say that $I$ becomes \emph{exponentially extinct}.

\item The solution $I$ is said to \emph{persist above $x_{0}$} if $\limsup_{t\uparrow\infty}I_{t}\geq x_{0}$ a.s. Furthermore, \emph{persistence around $x_{0}$} holds for $I$ if
\begin{equation}
\liminf_{n\uparrow\infty} I_{t} \leq x_{0} \leq \limsup_{t\uparrow\infty}I_{t} \quad\text{a.s}
\end{equation}
\end{enumerate}

[Proposition prop:stable=CL_skewed of arXiv:2412.06374, 'Stable and tempered stable distributions and processes: an overview toward trajectory simu'] Let $X\sim S_\alpha (1,\beta,0)$ where $\alpha \in (0,2)$ and $\beta \in [-1,1]$. For $Y_1,Y_2$ are independent random variables distributed as $S_\alpha (1,1,0)$, it holds that
\begin{align}
X \stackrel{d}{=} \begin{cases}
    \left( \frac{1+\beta}{2} \right)^{1/\alpha} Y_1 - \left( \frac{1-\beta}{2} \right)^{1/\alpha} Y_2& \text{ if } \alpha\neq 1,\\
     \left( \frac{1+\beta}{2} \right)Y_1 - \left( \frac{1-\beta}{2} \right) Y_2 + \sigma\left( \frac{1+\beta}{\pi} \log\left( \frac{1+\beta}{2}\right)-\frac{1-\beta}{\pi} \log\left( \frac{1-\beta}{2}\right)\right)& \text{ if } \alpha=1.
\end{cases}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 15 (Generating function for inversions) of arXiv:2606.18047, 'Analysis of the asymmetric shelf shuffle'] Let $\pi\sim\nu^{(p)}_{n,m}$.  Then
\begin{align}
\E\left[t^{\operatorname{inv}(\pi)}\right]
&=
\sum_{{\bf (a, b)}\in \mathcal{AB}(m, n)}
\left[\begin{matrix} n\\ {\bf (a, b)}\end{matrix}\right]_t
\cdot \prod_{j=1}^{m}t^{\binom{b_j}{2}}\cdot 
\left(\frac{p}{m}\right)^{|{\bf a}|}\left(\frac{q}{m}\right)^{|{\bf b}|}
\\
&=\frac{(t;t)_n}{m^n}[z^n]
\left(\frac{(-qz;t)_\infty}{(pz;t)_\infty}\right)^m.

\end{align}

[Lemma 12 of arXiv:2608.29984, 'On Cauchy Problems for Parabolic Equations with Rough Coefficients'] Assume $a(t,x)$ satisfies the assumptions in Theorem \ref{main} and Theorem \ref{maintwo}, then there exist a universal constant $C_{0}>0$ and a new frequency borderline $K>N+10$ (independent with $\epsilon$), such that
 \begin{equation}
 \||\p_{x}|^{s}(\mathrm{Id}-S_{K})a^{\epsilon}(t,x)\|_{L^{\frac{1}{s},\infty}_{x}}\leq C_{0}\delta_{0},\ \forall t\in[0,T].
 \end{equation}

