[Lemma 20 (First estimates on the asymptotic probability to visit a finite set $A$) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] Fix \(x \in \Z^d\) and \(A \subset \Z^d\) finite.

\begin{enumerate}[(i)]
\item
the probability that a branching random walk visits \(A\) is bounded above as follows:
\begin{equation*}{
  p(x,A) \preceq   \#A \times g_{\theta}(x).
  }\end{equation*}

\item
  Visiting probabilities for a branching random walk and an adjoint
  branching random walks are asymptotically related:
\begin{equation*}{
\widetilde{p}(x,A) \sim_{x \to \infty} p(x,A)^{\alpha-1}L(p(x,A)^{-1}).
}\end{equation*}
\end{enumerate}

As a consequence
\(\widetilde{p}(x,A) \preceq g_{\theta}(x)^{\alpha-1}L(g_{\theta}(x)^{-1})\)
(where the hidden constant depends on \(A\)). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 28 (preconditioned stationarity identity) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] \label[lemma]{lem:precond}
  Let $K_h=R_h\circ\phi_h$ be the clamped kernel \eqref{eq:clamped-kernel} and define, for $x>0$,
  \begin{equation}
    \Psi_h(x)\coloneqq G'(x)\,g_\star'(x)-h^{-1}\bigl(g_\star(x)-g_\star(\phi_h(x))\bigr).
  \end{equation}
  Then, for all $h\le h_0$,  we have
  $\pi_h(\eta)-\pi(\eta)=\pi_h\bigl(\Psi_h\,\mathbf 1_{(0,\infty)}\bigr)$ (which is \cref{eq:precond-identity}).

