[Defi 1 of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] Let $p \in (0, \infty)$ and assume $\{h(n) : n \ge 1\}$ is a sequence of non-negative real numbers. A collection $\{X^n_s : s\in S_n, n \ge 1\}$ of $\cX$-valued random elements is  \textit{$(\nu_n)$-uniformly $p$-th order integrable w.r.t. $\{h(n)\}$} (or $(\nu_n)$-$\UI(p)$ w.r.t. $\{h(n)\}$, for short) if:
	\begin{enumerate}[\rm (a)]
		\item the map $(\omega, s) \mapsto X^n_s(\omega)$ is $\cF \otimes \cS_n/\cB(\cX)$-measurable for every $n \ge 1$,

		\item  the following convergence holds:
		\begin{align}
			\lim_{n \to \infty} \bE\int_{S_n} \lt\|X^n_s\rt\|^p \1_{\{\|X^n_s\| > h(n)\}} \nu_n(\od s)  =0.
		\end{align}
	\end{enumerate}

