body:
[Theorem 200 of arXiv:2601.16377, '2601.16377'] Let $C > 0$. Consider the defining data for a master problem such that
\begin{enumerate}
\item $\boldsymbol{\Theta}$ is positive semi-definite;
\item $\forall h \in [H] \quad \theta_{h,h} \geq \frac{1}{C}$;
\item $H \leq C$ and $|\!|\boldsymbol{\Theta}|\!|_{\infty} \leq C$;
\item the distance between any pair of points in $\bigcup_{h = 1}^{H} \big\{\hat{a}_h^{\mathfrak{m}},\alpha_h,\beta_h,\hat{b}^{\mathfrak{m}}_h\big\}$ is larger than $\frac{1}{C}$ and the absolute value of all these points is smaller than $C$.
\end{enumerate}
Then, the master problem of Definition~\ref{def:master} has a unique solution
 \begin{equation}

 \forall h \in [H]\qquad \forall z \in \amsmathbb{C} \setminus \amsmathbb{A}_h^{\mathfrak{m}}  \qquad F_h(z) = \Op_h\big[\boldsymbol{E}\,;\,\boldsymbol{\kappa}\big](z).
 \end{equation}
For any $h \in [H]$, the solution operator $\Op_h$ is linear in the arguments $(\boldsymbol{E},\boldsymbol{\kappa}$), depends smoothly on the parameters $\boldsymbol{\Theta}$ and $\boldsymbol{\alpha},\boldsymbol{\beta}$ (\textit{i.e.}, for each $z$ the dependence on these parameters is infinitely differentiable, locally uniformly in $z$), depends on the segments $(\amsmathbb{A}_g^{\mathfrak{m}})_{g = 1}^{H}$ and the domains $(\amsmathbb{M}_g)_{g = 1}^{H}$ only through the domain of definition --- the precise meaning of this statement is explained below --- and is continuous in the following sense. Consider any $H$--tuple of contours $(\gamma_h)_{h=1}^H$, with each $\gamma_h\subset \amsmathbb{M}_h$ being a simple loop surrounding $\amsmathbb{A}_h^{\mathfrak{m}}$, and partitioning $\amsmathbb C$ into bounded interior of $\gamma_h$ and unbounded exterior. For any $H$-tuple of compact subsets $(\amsmathbb{K}_h)_{h=1}^H$, with each $\amsmathbb K_h$ being in the exterior of $\gamma_h$ (\textit{cf.} Figure~\ref{Fig:Kdomain})
 there exists a constant $C' > 0$ depending only on these contours, compacts, and on the constant $C$ --- in particular, independent of $\boldsymbol{E},\boldsymbol{\kappa},h$ --- such that for any $\boldsymbol{E},\boldsymbol{\kappa}$ we have
 \begin{equation}
\max_{h \in [H]} \sup_{z \in \amsmathbb{K}_h} \big|\Op_h\big[\boldsymbol{E}\,;\,\boldsymbol{\kappa}\big](z)\big| \leq C' \cdot \Big( \max_{h \in [H]} \sup_{z \in \gamma_h} |E_h(z)| + |\!|\boldsymbol{\kappa}|\!|_{\infty}\Big).
\end{equation}
Besides, if $E_h(z)$ is holomorphic in $\amsmathbb{M}_h$ for each $h \in [H]$, then
\begin{equation}

\forall h \in [H]\qquad \Upsilon_h[\boldsymbol{E}\,;\,\boldsymbol{0}] = 0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 6 (no universal behaviour at the critical dimension) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] Assume that \(\alpha > 2 \text{ and } \frac{2\alpha}{\alpha-1} \in \N\). Also assume that $\theta$, defined here on $\Z^{\frac{2\alpha}{\alpha-1}}$, has a finite moment of order $\delta > \frac{2\alpha}{\alpha-1}$. Consider \(\Tree_{n}\)-walk in \(\Z^{\frac{2\alpha}{\alpha-1}}\) with $\theta$-jumps.

\begin{enumerate}[(i)]
  \item 
If \Cref{Assum:SufficientConditionTransience} holds, then this \(\Tree_{n}\)-walk is transient:
\begin{equation*}{
\frac{R^{\theta}(\Tree_{n})}{n} \xrightarrow[n \to +\infty]{(\P)} \P(\esc_{+}) > 0.
}\end{equation*}
  \item If \(L(n) \to +\infty\) then this \(\Tree_{n}\)-walk is
recurrent:
\begin{equation*}{
\frac{R^{\theta}(\Tree_{n})}{n} \xrightarrow[n \to +\infty]{(\P)}  0.
}\end{equation*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 43 of arXiv:2607.18104, '2607.18104'] Fix initial data $\hfix_0 \in \UC$ and $\hfixp_0 \in \UCp$ such that
\begin{equation}
\hfix_0(x) = \hfixp_0(x)
\end{equation} for all $x\in \R$, where with a slight abuse of notation, we extend $\hfixp$ periodically from $\mathbb{T}$ to $\R$. 
Fix some $a\in \R$. 

Then there exist constants $c,C>0$, and a coupling $\mathbf{P}$ between the periodic KPZ fixed point $\hfixp$ and the KPZ fixed point $\hfix$, started from $\hfixp_0$ and $\hfix_0$, respectively, such that 
\begin{equation}
    \mathcal{A}_{\varepsilon} := \left\{ \hfixp\big(\hfixp_0;y,\varepsilon\big) = \hfix(\hfix_0;y,\varepsilon) \ \forall y \in \Big[a-\frac{1}{4},a+\frac{1}{4}\Big] \cap  \textup{ext}_{\varepsilon}(\hfix_0)\right\}
\end{equation}
satisfies for all $\varepsilon>0$
\begin{equation}
\mathbf{P}\left( \mathcal{A}_{\varepsilon} \right) \geq 1- C\exp(-c\varepsilon^{-1/2}) .
\end{equation} Moreover, we get that for all $y\in \mathbb{T}\setminus\textup{supp}(\hfix_0)$ 
\begin{equation}
   \lim_{\varepsilon \rightarrow 0} \hfix\big(\hfix_0;y,\varepsilon\big) =  \lim_{\varepsilon \rightarrow 0} \hfixp\big(\hfixp_0;y,\varepsilon\big) = -\infty ,
\end{equation} in the sense of almost sure convergence in supremum-norm of the function in $y$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lemmadistance of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] If $\theta\in C^1([0,T])$, then for any $\epsilon\in(0,\frac{\pi}{2})$, there exists a $\lambda_0>0$ such that $\forall\lambda>\lambda_0$, it holds that
$$
\sup_{s\in[0,t]}|\alpha_s-\beta_s|\leq c_{\theta,t}\frac{1-e^{-2\lambda\sin(\epsilon t)}}{2\lambda\sin{\epsilon}},\quad t\in[0,T],
$$
where $c_{\theta,t}:=\sup_{s\in[0,t]}|\dot{\theta}_s|$ and $\alpha_s$, $\beta_s$ are obtained by the following equations
\begin{equation}\left\{
\begin{array}{lllll}
\dot{\alpha}_s=-2\lambda\sin(\alpha_s)-\dot{\theta}_s\\
\dot{\beta}_s=-2\lambda\sin(\beta_s)\\
\alpha_0=\beta_0\in[-\frac{\pi}{2}+\epsilon,\frac{\pi}{2}-\epsilon].
\end{array}
\right.\end{equation}

[Lemma 21 (the map is a contraction) of arXiv:2609.01093, 'Ideal MHD below the classical well-posedness threshold'] With $T_*$ chosen by \eqref{eq:Tstar}, the map $\mathcal M$ satisfies
\begin{equation}
 \|\mathcal M\Ufield-\mathcal M\Vfield\|_{\mathcal Y}
 \le C_\delta T^\varepsilon R(1+R)
       \|\Ufield-\Vfield\|_{\mathcal Y}
 \le\tfrac12\|\Ufield-\Vfield\|_{\mathcal Y}
\end{equation}
for all $\Ufield,\Vfield\in\mathcal U_{R,\delta}$ and every $T\le T_*$.

[Definition 4 of arXiv:2506.09462, 'Transition Path Theory For L\'{e}vy-Type Processes: SDE Representation and Statistics'] The \textbf{$AB$-transition exit distribution} on \(\bar{A} \cap (\partial A + 1)\) and the \textbf{$BA$-transition exit distribution} on \(\bar{B} \cap (\partial B + 1)\) are defined as follows:  
\begin{equation}
    \begin{aligned}
        &\eta^-_A(\d x) = \frac{1}{v^-_A}\rho(x)\mathcal{L}q(x), \quad x \in \bar{A} \cap (\partial A + 1),\\
        &\eta^-_B(\d x) = \frac{1}{v^-_B}\rho(x)\mathcal{L}q(x), \quad x \in \bar{B} \cap (\partial B + 1),
    \end{aligned}
\end{equation}
where \(v^-_A\) and \(v^-_B\) are normalizing constants such that \(\eta^-_A\) and \(\eta^-_B\) define probability measures on \(\bar{A} \cap (\partial A + 1)\) and \(\bar{B} \cap (\partial B + 1)\), respectively.

[Defn def:ifs of arXiv:2412.09535, 'Local limit theorem for joint subgraph counts'] Given downwards closed $\mathcal{H}$, an integer $n$, and some $\eta > 0$, a collection of statistics $\mathcal{F} = (F_H)_{H \in \mathcal{H}}$, where $F_H \in \mathcal{R}_{\mathcal{H},n}$ for all $H \in \mathcal{H}$, is an \vocab{$(\mathcal{H}, n, \eta)$-integral factor system} (abbreviated \vocab{$(\mathcal{H}, n, \eta)$-IFS} or \vocab{IFS} if the parameters are unimportant) if for all $H \in \mathcal{H}$, in $\mathcal{R}_n$ we can write
\[F_H = \sum_{\mathrm{NIV}~\mkern-5mu H' \preceq H} a_{H'} X^*_{H'} = \sum_{\mathrm{NIV}~\mkern-5mu H' \preceq H} b_{H'} \gamma^*_{H'} = \sum_{\mathrm{NIV}~\mkern-5mu H' \preceq H} c_{H'} \gamma_{H'},\]
where
\begin{cond}
\item  all $a_{H'}$ are integers and $a_H = 1$;
\item  $\abs{b_{H'}} \leq \eta n^{(v(H) - v(H'))/2}$ for all $H'$ and $b_H = (p(1-p))^{e(H)/2}$;
\item  $\abs{c_{H'}} \leq \eta n^{(v(H) - v(H'))/2}$ for all $H'$ and $c_H = (p(1-p))^{e(H)/2}$.
\end{cond}

[Lemma structureH-1 of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] A linear functional $L:H_0^1(f)\to\mathbb{R}$ belongs to $H^{-1}(f)$ if, and only if, there exists $P\in L^2(1/f)$ such that 
    \begin{equation*}
        L(H)=\int_0^T\int_0^1 P_t\;\nabla H_t\;dx\;dt,
    \end{equation*}
    for every $H\in C_{c}^{\infty}(\Omega_T)$. In this case, 
    \begin{equation*}
        ||L||^2_{-1,f}=\int_0^T\{\langle P_t, P_t\rangle_{f(t)^{-1}}-c_t\}\;dt,
    \end{equation*}
    where $c_t=\{\langle P_t/f_t\rangle^2\;/\;\langle 1/f(t)\rangle\}\mathds{1}\{\langle 1/f(t)\rangle<\infty\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition pro:asymCell of arXiv:2604.23981, 'Accelerating sampling via asymptotic relaxation enhancing flows'] For $v_n=\nabla^{\perp}\Psi_n$, we have 
    \begin{gather}
    r(v_n)\geq n^2 \delta,
    \end{gather}
     for some $\delta>0$ independent of $n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 8 of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] For all $p \in (0, 1/2]$,
\begin{align*}
    (1 - p)\,\beta_p \le 1 + \log\frac{1}{2p}.
\end{align*}

[Lemma lem:brownian-fixed-gaussian-block of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] For the fixed horizon $T$ and parameters $n\geq2$ and $\alpha\geq0$, set
$
 \mathcal H_{n,\alpha}
 :=L^2((0,T),t^\alpha\,\mathrm d t;\mathcal C_n)
$
and define the operator initially on $C_c^\infty((0,T);\mathcal C_n)$ by
\begin{equation}
 \mathscr H_{n,\alpha}^{\mathrm{Br}}\widehat F
 :=t^{-1}D_\xi^2\operatorname{Sol}_n\widehat F.

\end{equation}
Then $\mathscr H_{n,\alpha}^{\mathrm{Br}}$ extends uniquely to a bounded operator from
$\mathcal H_{n,\alpha}$ into
$L^2((0,T),t^\alpha\,\mathrm d t;L^2(\gamma_d;\mathsf{S}^d))$.
Under the Brownian pullback, this is the $n$th chaos block of the physical
source-to-Hessian map.  In logarithmic time it is represented by the causal
Volterra operator
\begin{equation*}
 (\operatorname{Volt}_{n,\alpha}\widehat F)(\ell)
 =\sqrt{n(n-1)}\int_0^\ell
   e^{-(n-1+\alpha)(\ell-\ell_0)/2}
   \widehat F(\ell_0)\,\mathrm d\ell_0.
\end{equation*}
Its exact operator norm is
\begin{equation}
 \norm{\mathscr H_{n,\alpha}^{\mathrm{Br}}}
 =\norm{\operatorname{Volt}_{n,\alpha}}_{2\to2}
 =\frac{2\sqrt{n(n-1)}}{n-1+\alpha}.

\end{equation}

