[Proposition prop:lil of arXiv:2411.02362, 'Limit theorems for random Dirichlet series: boundary case'] Assume that $\mathbb{E}[\eta]=0$, $\sigma^2=\mathbb{E} [\eta^2]\in (0,\infty)$ and let $\alpha>-1/2$. Then, almost surely,
\begin{equation*}
C\bigg(\bigg(\Big(\frac{2^{2\alpha}}{\sigma^2 \Gamma(1+2\alpha)}\frac{s^{1+2\alpha}}{\log\log 1/s}\Big)^{1/2}\sum_{k\geq 2}\frac{(\log k)^\alpha}{k^{1/2+s}}\eta_k: s\in (0, {\rm e}^{-1})\bigg)\bigg)=[-1,1],
\end{equation*}
where $\Gamma$ is the Euler gamma function. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 3 of arXiv:2608.01419, 'A model of opinion dynamics evolving via a preferential attachment mechanism involving mul'] Recall the function $f$ defined via \eqref{X_{n+1}_conditional_distribution}, and the function $g$ as defined in \eqref{g_defn}. Assume, throughout, that $p\in(0,1)\setminus\{1/2\}$. Then, in each of the following cases, the function $G$, defined in \eqref{G_defn}, has a unique root in $[0,1]$ (lying strictly between $0$ and $1$):
\begin{enumerate}
\item when $f(x)=c$ for all $x\in[0,1]$, for some $c\in(0,1)$;
\item when $f(x)=x$ for all $x\in[0,1]$, and $p\in(0,1/2)$;
\item when $f(x)=x$ for all $x\in[0,1]$, $p\in(1/2,1)$ and either
\begin{equation}
\beta\geqslant \frac{(2p-1)(k-1)}{4(1-p)},
\end{equation}
or \eqref{beta_p_cond} does not hold and one of the following two inequalities is true:
\begin{align}
{}&G\left(\frac{1}{2}-\frac{\sqrt{3(k-1)(2p-1)\{(k-1)(2p-1)-4\beta(1-p)\}}}{6(k-1)(2p-1)}\right)>0,_cond}\\
{}&G\left(\frac{1}{2}+\frac{\sqrt{3(k-1)(2p-1)\{(k-1)(2p-1)-4\beta(1-p)\}}}{6(k-1)(2p-1)}\right)<0;_cond}
\end{align}
\item  when $f(x)=e^{x-1}$ for all $x\in[0,1]$, $k\geqslant 2$, $p\in(0,1/2)$ and $\beta>k(1-2p)$. 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2605.20026, 'Quasihelix properties\\ of selected Volterra Gaussian processes'] Let $\gamma\in[0,1)$. Then for any $0<T_1<T_2$ the following statements hold.
\begin{enumerate}
\item[$(i)$]
Let $\alpha \in (-1/2, 1/2)$.
Then 
\begin{equation}
\ex\left(U^{(2)}(t)-U^{(2)}(s)\right)^2
\sim C(\alpha)(t-s)^{2\alpha+1}s^{-\gamma},
\quad \text{as } t\downarrow s,
\end{equation}
for any $s\in[T_1,T_2]$,
where
\begin{equation}
C(\alpha) = \int_0^\infty \bigl[(1+z)^\alpha-z^\alpha\bigr]^2\,dz
+ \frac{1}{2\alpha+1}
= \frac{\Gamma(\alpha+1)^2} {\Gamma(2\alpha+2)\cos(\pi\alpha)}.
\end{equation}
Consequently, the process $U^{(2)}$ is a local $(\alpha+\frac12,T_1,T_2)$-quasihelix.

\item[$(ii)$]
If $\alpha=1/2$, then the process  $U^{(2)}$ is a local $(1,1-\varepsilon,T_1,T_2)$-generalized quasihelix for any $\varepsilon\in(0,1)$.

\item[$(iii)$]
If $\alpha > 1/2$, then the process $U^{(2)}$ is a local $  (1,T_1,T_2)$-quasihelix.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma unique root of arXiv:2609.02073, 'Existence of closed non-planar $p$-elasticae'] Let $f:[0,\infty)\to \R$ be given as
  \begin{equation*}
    f(x) := \frac{p-1}{p} x^{\frac{p+1}{p-1}} - \frac{\lambda}{p} x^{\frac{1}{p-1}} - C^2 x^{-3}
  \end{equation*}
  with $\lambda \in  \R$ and $C^2>0$. 
  Then $f$ has only one strictly positive root. The sign change at this strictly positive root is negative-positive.

