[Mylem 2.1 of arXiv:2411.08430, 'The Restricted Isometry Property of Block Diagonal Matrices Generated by $\varphi$-Sub-Gau'] $Sub_{\varphi}(\Omega)$  is a Banach space with respect to the norm 
		\begin{equation}
			\tau_{\varphi}(X)=\inf \{a \geq 0: \textsf{E} \exp \{\lambda X\} \leq \exp \{\varphi(a \lambda)\}, \,\,\text{for all}\,\,\lambda \in \mathbb{R}\}.
		\end{equation}
		The norm above is equivalent to the one in Lemma (l2 of the paper), we recommend referring to [Buldyginbook] for proof, with the norm above, for any $u>0$, the  $\varphi$-sub-Gaussian process $(X_{t})_{t\in T}$ satisfies the following incremental inequality:
		\begin{equation}
			\textsf{P}\left(|X_t-X_s| \geqslant u \tau_\varphi(X_t- X_s)\right) \leqslant 2 \exp \left\{-\varphi^*(u)\right\},
		\end{equation}
		where $t,s\in T$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:hl of arXiv:2411.10419, 'Lower bounds on the top Lyapunov exponent for linear PDEs driven by the 2D stochastic Navi'] In the setting of Theorem~(thm:main of the paper) there exists a $ C > 0 $ such that
uniformly over $ M \in \mathbf{N} $ and $ \kappa \in (0, 1] $, the following
differential inequalities hold,
for all $ t \leqslant \inf \{ s \geqslant 0  \; \colon \; \| \mathcal{L}_{M}
\varrho_{s} \| = 0 \} $:
\begin{itemize}
\item If $ \varrho $ is the solution to (equation e:main of the paper) with  $L[u]  = u\cdot
\nabla  $, then
\begin{equ}
\frac{\mathrm{\,d}}{\mathrm{\,d} t} \frac{\| \mathcal{H}_{M} \varrho_{t} \|}{\| \mathcal{L}_{M} \varrho_{t} \|}
\leqslant C M \| u_{t} \|_{\infty} \left(  1 +  \frac{\| \mathcal{H}_{M} \varrho
\|^{2}}{\| \mathcal{L}_{M} \varrho \|^{2}} \right) \;.
\end{equ}
\item If $ \varrho $ is the solution to (equation e:main of the paper) with $L[u]  = u\cdot
\nabla  + \Delta u\cdot \nabla^{-1}$, then
\begin{equ}
\frac{\mathrm{\,d}}{\mathrm{\,d} t} \frac{\| \mathcal{H}_{M} \varrho_{t} \|}{\| \mathcal{L}_{M} \varrho_{t} \|}
\leqslant C M ( \| u_t \|_{\infty} + \|\Delta  u_{t} \|_{\infty} ) \left(  1 +  \frac{\| \mathcal{H}_{M} \varrho
\|^{2}}{\| \mathcal{L}_{M} \varrho \|^{2}} \right) \;.  
\end{equ}
\end{itemize}

