[Lem 8 of arXiv:2603.29549, 'Multitype PCR branching processes'] Let $H$ be the limit in \eqref{Hx}. Then as $n\to \infty$,
\begin{equation}
\bar F^{(n)} (\bar x/b_1^n)\to \frac  {H(x_0)}{x_0 } (x_1,\ldots,x_{d_0},0,\ldots,0),
\quad  \bar x\in \Real_+^d,  
\end{equation}
where the convergence is uniform on compact subsets of $\Real_+^d$ and $x_0=x_1+\ldots +x_{d_0}$.

[Theorem thm:unique of arXiv:2412.04589, 'Inverting the Markovian projection for pure jump processes'] Let $X_t = \sum_{k=1}^\infty \bm{1}_{\{\tau_k \leq t\}}$, $t \geq 0$, be a counting process, with $0 < \tau_1 < \tau_2 < \cdots$ $\mathbb{P}$-a.s. Let $\mathbb{A}^k$ be the natural filtration of the process $(\bm{1}_{\{\tau_k \leq t\}})_{t \geq 0}$ for $k \in \mathbb{N}^*$. Let $\mathbb{G}^0 \coloneqq \mathbb{F}$, $\mathbb{G}^k \coloneqq \mathbb{F} \newtriangledown (\newbigtriangledown_{i=1}^k \mathbb{A}^i)$ for $k \in \mathbb{N}^*$ and $\mathbb{G} \coloneqq \mathbb{F} \newtriangledown (\newbigtriangledown_{i=1}^\infty \mathbb{A}^i)$. Suppose that
	\begin{enumerate}[label=(\roman*), nosep]
		\item $\mathbb{F} = \mathbb{G}^0 \hookrightarrow \cdots \hookrightarrow \mathbb{G}^{k-1} \hookrightarrow \mathbb{G}^k \hookrightarrow \cdots \hookrightarrow \mathbb{G}$;

		\item for each $k \in \mathbb{N}^*$, the process $Z^k_t \coloneqq \mathbb{P}(\tau_k > t \,|\, \mathcal{G}^{k-1}_t)$, $t \geq 0$, has a continuous modification which is strictly positive, where $\mathcal{G}^{k-1}_t$ is the element of $\mathbb{G}^{k-1}$ at time $t$.
	\end{enumerate}
	Moreover, let $\eta$, $\lambda$ be given by Assumption~(asm:1 of the paper), and suppose that the process in (equation eq:X_compen of the paper) is a $\mathbb{G}$-martingale. Then, the law of $X$ is uniquely determined by $\lambda$ and the law of $\eta$.

