[Definition defJVt of arXiv:2506.10448, 'Hitting probabilities and the Ekstr\"om--Persson conjecture'] Given an admissible sequence of open sets $\underline V$, define, for all $t\ge 0$, the hitting 
operator $ \JmuVt\colon \mathcal{K}\to \mathcal{K}$ by setting
\begin{equation}
\JmuVt(K):=\Bigl\{x\in X\mid\sum_{k=1}^\infty \mu\bigl(B(x,r)\cap (K-V_k)\bigr) |V_k|^t
  =\infty\text{ for every }r>0\Bigr\}.
\end{equation}

[Extratheorem 6 of arXiv:2608.19179, 'A random walk on $p$-groups with a symmetric perfect pairing'] \cite[Theorem 2]{Woodetal}
Let $G$ be a finite abelian $p$-group of rank $r$ with a perfect symmetric pairing $<\cdot,\cdot>$. Then:
\[
\probP\Big(\Ker(SymHaar_{n,n}) \cong (G,<\cdot,\cdot>)\Big)= \]
\[\frac{
\prod_{j=n-r+1}^{n} (1-p^{-j}) \prod_{i=1}^{\lceil (n-r)/2 \rceil}(1-p^{1-2i})
}{
\# G
\# Aut(G,<\cdot,\cdot>)
}
\]
where $Aut(G,<\cdot,\cdot>)$ is the group of automorphisms of $G$ that preserve the pairing $<\cdot,\cdot>$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2604.17253, 'Large Deviations for the Nonlinear Schrödinger Equation with Randomized Quasi-Periodic Ini'] The {\em branch set} $\Gamma^{(k)}$ is defined recursively by
\begin{align*}
\Gamma^{(k)} =
\begin{cases}
\{0,1\}, & k = 1; \\
\{0\} \cup \bigl(\Gamma^{(k-1)}\bigr)^3, & k \ge 2,
\end{cases}
\end{align*}
where $0$ corresponds to a linear node and $1$ corresponds to a cubic interaction node.

[Proposition 41 (Completed Harish--Chandra reflection) of arXiv:2608.29585, '2608.29585'] For every zero-framed knot $K$ and every integer $n\ge2$, let
\begin{equation}
 f_K=\widehat\hc
 \bigl(J_K(\mathfrak{gl}_n;q^2)\bigr).
\end{equation}
Then
\begin{equation}
 \mathsf D_c^*f_K=f_K\quad(c\in\Z),
 \qquad
 \mathsf I^*f_K=f_K.
\end{equation}

[Lemma eq:trace-derivative-1 of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:trace-derivatives}
For \(r=1\),
\begin{equation}
 \abs{D\operatorname{Tr} f(A)[C]}
 \le C_f\sqrt n\left\lVertC\right\rVert_{\mathrm{HS}}.
\end{equation}
For \(2\le r\le m+1\),
\begin{equation}
