body:
[Proposition prop subsequential limit of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] Let $\kappa_n \downarrow 4$. Then there exists a subsequence of $(\kappa_n)_{n\ge 0}$, again denoted by $(\kappa_n)_{n\ge 0}$, such that we have the joint convergence in law:
	\begin{equation}
		\begin{pmatrix}
			(\SCL^{\kappa_n}(x))_{x \in \BQ^2} \\
			(\ka_{\kappa_n}^{-1}D^{\kappa_n, \partial}(\SCL^{\kappa_n}(x), \SCL^{\kappa_n}(y)))_{x,y \in \BQ^2}			
			\\
			(K^{\kappa_n, \partial}_{\SCL^{\kappa_n}(x), \SCL^{\kappa_n}(y)})_{x, y \in \BQ^2}			
		\end{pmatrix}
		\mathop{\longrightarrow}\limits_{n\to \infty}^{(\mathrm{d})}
		\begin{pmatrix}
			(\SCL(x))_{x \in \BQ^2} \\
			(D^\partial(\SCL(x), \SCL(y)))_{x,y \in \BQ^2}
			\\
			(K^\partial_{\SCL(x), \SCL(y)})_{x, y \in \BQ^2}
		\end{pmatrix},
	\end{equation}
	where the loops $(\SCL(x))_{x \in \BQ^2} $ have the same law as the loops of a $\CLE_4$ $\Gamma$ in $\BD$ (and will be identified with the loops of $\Gamma$), where we write $\widehat{\Gamma} \defeq \Gamma \cup \{\partial \BD\}$, where $D^\partial$ is a random pseudometric on $\widehat{\Gamma}$, and where $K^\partial_{\SCL(x), \SCL(y)}$ 
	are random compact subsets of $\overline{\BD}$. The above convergence holds for the product topology, and the compact sets converge in the Hausdorff topology.

[Proposition prop:ZIM_tree_monotonicity_mu of arXiv:2607.29409, 'The Zombie Infection Model'] Consider a tree $G=(V,E)$, parameters
		$\mu,\lambda \in (0,\infty)$ and $c\geq1$, and an initial set $\Delta \subset V$ consisting of one connected cluster. Then the following holds:
		\begin{enumerate}[label=\alph*)]
			\item  There is a coupling $\widehat{\BP}^{\ZIM}$ of $\big(\eta_{t}^{(1)}\big) \sim\BP^{\ZIM}_{\lambda,\mu,G,\Delta}$ and $\big(\eta_{t}^{(2)}\big)\sim
				\BP^{\ZIM}_{\lambda, c\mu,G,\Delta}$ such that
				\begin{equation}
					\widehat{\BP}^{\ZIM}\!\left( \eta_{t}^{(1)}
					\geq \eta_{t}^{(2)}\: \forall \: t\in [0,\infty) \right) =1.
				\end{equation}

			\item  There is a coupling $\widehat{\BP}^{\SIR}$ of $\big(\xi_{t}^{(1)}\big) \sim\BP^{\SIR}_{\lambda,\mu,G,\Delta}$ and $\big(\xi_{t}^{(2)}\big)\sim
				\BP^{\SIR}_{\lambda, c\mu,G,\Delta}$ such that
				\begin{equation}
					\widehat{\BP}^{\SIR}\!\left( \xi_{t}^{(1)}
					\geq \xi_{t}^{(2)}\: \forall \: t\in [0,\infty) \right) =1.
				\end{equation}
		\end{enumerate}

[Corollary 11 (Constructive endpoint-resolution bounds) of arXiv:2608.21496, '2608.21496'] Let $d=\lfloor(m-1)/2\rfloor$, let $\xi_{d+1}$ be the largest zero on $[0,1]$ of the shifted Legendre polynomial of degree $d+1$, and put
\begin{equation}
A_{m,L}=\min\left\{\frac1{m+1},\frac{L}{m(m+1)}\right\},\quad
D_{m,N}=\prod_{j=1}^m\frac{N-j}{N+j}.

\end{equation}
Then
\begin{equation}
\begin{aligned}
A_{m,L}D_{m,N}&\le\Delta^{\uparrow,L}_{m,N},\\
\Delta^{\uparrow,L}_{m,N}
&\le\min\left\{B_{m,N},
L\left(1-\xi_{d+1}+\frac1{N+1}\right),1\right\}.
\end{aligned}

\end{equation}
If $L$ is fixed and $m^2/N\to\tau\in(0,\infty)$, then
\begin{equation}
e^{-\tau}\le\liminf\frac{m^2\Delta^{\uparrow,L}_{m,N}}L
\le\limsup\frac{m^2\Delta^{\uparrow,L}_{m,N}}L
\le j_{0,1}^2+\tau,

\end{equation}
where $j_{0,1}\simeq2.4048$ is the first positive zero of $J_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 9 of arXiv:2606.17472, '2606.17472'] Let $n\ge 2$ and $a_1<\cdots <a_n$. Then the following statements hold:
\begin{enumerate}
  \item If $h(x)=0$ for $x<0$, then
  \begin{align*}
    \mu_{\{a_1,...,a_n\}}(dy)=\delta_{a_n}(dy),\qquad k(\{a_1,...,a_n\})=0.
  \end{align*}
   \item If $h(x)=0$ for $x>0$, then
  \begin{align*}
    \mu_{\{a_1,...,a_n\}}(dy)=\delta_{a_1}(dy),\qquad k(\{a_1,...,a_n\})=0.
  \end{align*}
  \item If $h(x)>0$ for $x\neq 0$, then
  \begin{gather*}
    \mu_{\{a_1,...,a_n\}}(dy)=\frac{1}{\bm{1}^T\bm{H}^{-1}\bm{1}}\sum_{i=1}^n (\bm{H}^{-1}\bm{1})_i\delta_{a_i}(dy),\\
    k(\{a_1,...,a_n\})=\frac{1}{\bm{1}^T\bm{H}^{-1}\bm{1}}.
  \end{gather*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 of arXiv:2606.08115, '2606.08115'] Let sequences $\{a_n\}_{n \in \mathbb{N}}$, $\left\{\delta_{n, m}\right\}_{n, m \in \mathbb{N}}$, $\left\{b_{n, m}\right\}_{n, m \in \mathbb{N}}$ be such that the equality $a_n = \delta_{n, m} + b_{n, m}$ takes place for every natural $n, m$. Assume that the following conditions are valid:
\begin{enumerate}
\item[1)] $\delta_{n, m} \ge 0$, $b_{n, m} \ge 0$ for $n$, $m \in \mathbb{N}$;
\item[2)] $\displaystyle \varliminf\limits_{m \to \infty} \varlimsup\limits_{n \to \infty} \delta_{n, m} = 0$;
\item[3)] for every natural $m$ there exists the finite limit $\displaystyle \lim_{n \to \infty} b_{n, m} =: b_{m}$.
\end{enumerate}
Then $a:= \displaystyle \lim_{n \to \infty} a_n = \lim_{m \to \infty} b_{m}< \infty.$ Moreover, if $b_m > 0$ for some $m$, then $a > 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 25 of arXiv:2607.06242, 'Exponential mixing and Freidlin--Wentzell large deviation principle for Markov cocycles'] Under the conditions of Theorem \ref{t.050601}, we have 
  \begin{align*}
    \lim _{R \rightarrow \infty} \limsup _{\varepsilon \rightarrow 0} \varepsilon \ln \mu_\sigma^{\varepsilon}\left(B_R^c\right)=-\infty, \quad m \text{-a.s.}.
  \end{align*}

