[Corollary lem:action_taylor of arXiv:2603.27906, 'Marked GUE-corners process in doubly periodic dimer models'] We have that
\begin{equation}
\re G(0,1)=+\infty, \quad \re G(\infty,1)=+\infty, \quad\text{and} \quad \re G(1,0)= -\infty.
\end{equation}
Furthermore in a neighbourhood of $(z,w)=q_\infty$, with respect to the canonical choice of coordinates,
we denote the function $z\mapsto G(z,w)$ by $G(z)$ (with some abuse of notation). Then we have that

\begin{equation}
 G'(1)=0, \quad\text{and} \quad G''(1)=\sigma^2\quad \text{for some } \sigma^2>0.
\end{equation}

[Theorem thm:GTD of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Let $\kappa>1$, let $(s,\beta)\in(0,\infty)\times(0,1)$ satisfy the numerical stability condition (equation eq:HBstability of the paper), and fix an integer $m\ge3$. With the notation introduced above:
\begin{enumerate}
\item[\rm(i)] There exists a $C^1$ function $f:\mathbb R^2\to\mathbb R$ that is $1$-strongly convex and has $\kappa$-Lipschitz gradient such that
\begin{equation*}
 x_{t+1}^\circ=(1+\beta)x_t^\circ-\beta x_{t-1}^\circ-s\nabla f(x_t^\circ)
 \qquad\text{for every }t
\end{equation*}
if and only if $P_m(s,\beta;\kappa)\le0$. When this condition holds, the potential function $\psi$ defined in (equation eq:GTDpsi of the paper) is one such function and is piecewise quadratic.
\item[\rm(ii)] Suppose $P_m(s,\beta;\kappa)<0$, and let $\psi$ be the potential function in (equation eq:GTDpsi of the paper). Then there is a radius $r_{\max}=r_{\max}(m,s,\beta,\kappa)>0$, given explicitly in the proof, such that $\psi$ is quadratic with Hessian $\mathrm{Id}_2$ on each ball $B(x_t^\circ,r_{\max})$, that is,
\begin{equation}
 \nabla\psi(x_t^\circ+u)=\nabla\psi(x_t^\circ)+u,
 \qquad\lvert u\rvert\le r_{\max}.
\end{equation}
\end{enumerate}

