[Definition 10 of arXiv:2605.30560, 'Projected McKean--Vlasov Dynamics for Entropic Weak Optimal Transport'] For any $\pi \in \Pi(\mu,\nu)$, we formally identify the tangent space as
\begin{align}
T^{\rm ad}_{\pi}\left( \Pi(\mu,\nu)\right)
&\;\simeq\;
\Big(\overline{\nabla^{\rm ad}_{\pi}(\mathcal{V})}^{\,L^2(\pi)}\Big)^{\perp} \\
& \; = \;
\Big\{
g\in T^{\rm ad}_{\pi}\Pc_2(\R^{2d}):\
\int g(x,y)\cdot \nabla^{\rm ad}_{\pi} h(x,y) \, \pi(dx,dy)=0,
\ \ \forall \, h\in \mathcal{V}
\Big\}. \notag
\end{align}

[Defination 16 of arXiv:2511.10814, '\Large \bf \boldmath\ \\ Convergence of the extended Kalman filter with small and state-de'] A  symmetric  matrix  $A \in \mathcal{M}_n(\mathbb{R})$ is 

							\begin{enumerate}
								\item positive definite if  $x^\top Ax>0$  for  all  nonzero $ x \in \mathbb{R}^n$;
								\item positive semi-definite if  $x^\top Ax \geq 0$  for  all  nonzero $ x \in \mathbb{R}^n$.
							\end{enumerate}

[Lemma lemma11 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Let $\varphi$ be a characteristic satisfying (C1 of the paper). Then, for every  $t \in \mathbb{R}$, $u \in \mathcal{I}$ and $k \in \mathbb{N}_{0}$,
\begin{align}
\varphi_{u}^{(k)}(t) \stackrel{a.s.}{=} \mathbb{E}[\varphi_{u}(t) \mid \mathcal{A}_{u}^{(k-1)}].
\end{align}

[Lemma 5 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] Set
\begin{equation}
  c_\alpha
  :=\frac1\pi\int_0^\infty\frac{1-\cos u}{u^\alpha}\,\mathrm du
  =-\frac{1}{2\Gamma(\alpha)\cos(\pi\alpha/2)}>0.

\end{equation}
With respect to Lebesgue measure on \(\mathbb R\setminus\{0\}\), the process
\(Z\) killed at \(T_0\) has Green density
\begin{equation}
  g_\alpha(x,y)
  =c_\alpha\bigl(
       |x|^{\alpha-1}+|y|^{\alpha-1}-|x-y|^{\alpha-1}
     \bigr),
  \qquad x,y\neq0.

\end{equation}

