[Lem 1 of arXiv:2605.02420, '\textbf{Large time behavior of critical marked Hawkes processes with heavy tailed marks an'] Under Assumption \ref{ass:nu_beta}, the function   $H$ given by \eqref{e:Hdef} 
is nondecreasing and for any $x\in[0,1]$ we have
\begin{equation}

 H(x)= Kx^{1+\beta}W(x),
\end{equation}
where $K=\frac{c_\nu}{\beta}\Gamma(1-\beta)$ and $W$ is a nonnegative bounded function satisfying
\begin{equation}
 \lim_{x\to 0+}W(x)=1.

\end{equation}
Moreover, there exists a constant $C>0$ such that for any $0\le x\le y$
\begin{equation}

 0\le H(y)-H(x)\le C(y-x)y^\beta.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:sharper-offdiag of arXiv:2608.18293, 'Critical tensor covariance at the Marchenko--Pastur threshold'] Assume in addition that $\mathbb{E} X^3=0$, let $A$ be complex symmetric, write
$A^\circ$ for its zero-diagonal part, and suppose $d/n\to0$. Then, for all
sufficiently large $n$,
\begin{equation}
 \frac1{p^2}\mathbb{E}|x^{\mathsf T}A^\circ x|^2
 \le \frac{2d(n-d)}{n(n-1)}
 e^{vd^2/(n-2d)}\|A\|_\mathrm{op}^2.

\end{equation}

[Definition LLN_perturbed_process of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] Fix $G \in C^{0,1}(\Omega_T)$. A function  {$\rho \in L^2([0,T],H^1([0,1]))$} such that $0\leq \rho \leq 1$ a.e. in $\Omega_T$ is called a weak solution of 
\begin{align} 
    \begin{cases}
    \partial_t \rho = \Delta \rho-2\nabla\{\sigma(\rho)\nabla G\}\\
    \nabla \rho_t(0) -2\sigma(\rho_t(0))\nabla G_t(0) = -\mathfrak{p}^-(\rho_t(0),G_t(0))\\
    \nabla \rho_t(1) -2\sigma(\rho_t(1))\nabla G_t(1)= \mathfrak{p}^+(\rho_t(1),G_t(1))\\
    \rho(0,x) = \gamma(x)
    \end{cases} 
\end{align} if 
\begin{align*}
    \int_0^1 \left[\rho_t H_t -\gamma H_0 -\int_0^t \rho_s\partial_s H_s\;ds \right] dx &=\int_0^t\int_0^1\{-\nabla\rho_s\nabla H_s+ 2\sigma(\rho_s)\nabla G_s\nabla H_s\}\;dx\;ds\\
    &+ \int_0^t \{\mathfrak{p}^-(\rho_s(0),G_s(0))H_s(0)+\mathfrak{p}^+(\rho_s(1),G_s(1))H_s(1)\} ds,
\end{align*}
for all $t\in [0,T]$ and all test functions $H\in C^{1,2}( {\Omega_T})$.

[Lemma optnprefix of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $n\geq 2$ and let $(u_i)_{1\leq i\leq n}$ and $(q_i)_{1\leq i\leq n}$ be strictly increasing sequences of numbers in $(0,1)$. Let $\zeta\in \mathrm{Prefix}_{n+1}((u_i)_{1\leq i\leq n},(q_i)_{1\leq i\leq n})$ where $\mathrm{Prefix}_{n+1}$ is as in Definition (def:nprefix of the paper). Suppose that $\zeta$ satisfies the assumptions of Proposition (prop:annealed cond of the paper). Let $(X_t)_{t\in [0,1]}$ be the Auffinger--Chen process
		\begin{equation*}
			\begin{cases}
				\mathrm{d} X_t=\xi''(t)\zeta([0,t])\partial_x \Phi_\zeta(t,X_t)\mathrm{d} t+\sqrt{\xi''(t)} \mathrm{d} B_t\\
				X_0=0.
			\end{cases}
		\end{equation*}
		For every $s\in [0,1]$, set
		\begin{equation*}
			H_\zeta(s):=\frac{1}{2}\int_s^1 \xi''(r)\Bigl(\mathbb{E}[(\partial_x\Phi_\zeta(r,X_r))^2]-r\Bigr)\mathrm{d} r.
		\end{equation*}
		Then, the following hold:
		\begin{enumerate}
			\item For every $k\in [n-1]$,
			\begin{equation}
				-\mathbb{E}[\Phi_\zeta(q_k,X_{q_k})]+\frac{1}{2}\int_0^1 t\xi''(t)\zeta([0,t])\mathrm{d} t +\frac{1}{2}\int_0^{q_k}t\xi''(t) \zeta([0,t])\mathrm{d} t=-\mathcal{P}\mathrm{arisi}(\zeta),
			\end{equation}
			\item   \begin{equation}
				-\mathbb{E}[\Phi_\zeta(q_n,X_{q_n})]+\frac{1}{2}\int_0^1 t\xi''(t)\zeta([0,t])\mathrm{d} t +\frac{1}{2}\int_0^{q_n}t\xi''(t) \zeta([0,t])\mathrm{d} t=-f,
			\end{equation}
			\item For every $k\in [n]$,
			\begin{equation}
				\mathbb{E}[(\partial_x\Phi_\zeta(q_k,X_{q_k}))^2]=q_k,
			\end{equation}
			\item  \begin{equation}
				\mathrm{supp}(\zeta)\cap [q_n,1]\subset \underset{[q_n,1]}{\mathrm{arg\,min}}(H_\zeta).
			\end{equation}
		\end{enumerate}

[Proposition 22 of arXiv:2606.31596, 'The Invariant Measure of Multiscale Markov Chains via Fast Arborescence Factorization'] Let $U:X\times\T^{n}\to\R$ be a potential of regularity class $C^2$ with respect to $y\in\T^{n}$. $X$ finite set. $\beta_1,\beta_2>0$.

Let $\frac{1}{h}\in\N$ and $Y_h:=\{0,h,2h,\dots,1-h\}^{n}$ a discrete set of points in $\T^{n}$ with uniform spacing. Define the edge set $E_h:=\{(y,y')\in Y_h\times Y_h\,|\,\exists\,i:\, y_i'=y_i\pm h,\ y_j'=y_j\,\forall\,j\neq i \}$ with rates
\begin{equation} 
	r_x(y,y') \,:=\, e^{-\frac{1}{2}\beta_2\,(U(x,y')-U(x,y))} 

	\,,\quad  (y,y')\in E_h \,.
\end{equation}

Then:
\begin{itemize}

\item[i)] the rates $r_x(y,y')$ are reversible with respect to the measure $\widetilde\nu_x(y)$ defined by \eqref{eq:nuXYsimple};\\

\item[ii)] the effective rates $\bar r(y,y')$ defined by \eqref{eq:weff2},\eqref{eq:Gibbs} are approximately reversible with respect to the effective Gibbs measure $\bar\mu(y)$ defined by \eqref{eq:effGibbs}, precisely:

\begin{equation}
 \bar\mu(y)\; \bar r(y,y') - \bar\mu(y')\; \bar r(y',y) \,=\, O(h^2)\;\bar\mu(y)\,\bar r(y',y) \,.
\end{equation}
\end{itemize}

\begin{comment}
As a consequence the two-scale dynamics $r_N$ defined by \eqref{diffr} has limiting invariant measure
\begin{equation}
\lim_{N\to\infty}\pi_N(x,y) \,=\, \bar\pi(M_y)\, \mu_y(x)\,,\quad (x,y)\in X\times Y_h
\end{equation}
with
\begin{equation}
\bar\pi(M_y) \,=\, \bar\mu(y) \,+ O(h^2)\,\bar\mu(y)\,,\quad y\in Y_h \,.
\end{equation}
\end{comment}

