[Lemma lem:good_convergence of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] Jointly with~(equation eq cv subsequence of the paper),~(equation eq cv Hausdorff balls of the paper) and~(equation eq cv subsequence boundary of the paper), for all $t \in \BQ_{\ge 0}$, $x \in \BD_\BQ$, $\alpha \in \SCS'$, along a subsequence again denoted by $(\kappa_n)_{n \ge 0}$, we have
	\begin{equation*}
		\left(
		\SCB^{\kappa_n, \partial}_{\ka_{\kappa_n} s}(\SCB_{\ka_{\kappa_n}t}^{\kappa_n} (\SCL^{\kappa_n}(x))), \SCB^{\kappa_n, \partial}_{\ka_{\kappa_n} s}(\SCB_{\ka_{\kappa_n}t}^{\kappa_n} (\alpha))
		\right)_{s \in \BQ_{\ge 0}}
		\mathop{\longrightarrow}\limits_{n\to \infty}^{(\mathrm{d})}
		\left( 
		\SCB^\partial_{ s}(\SCB_{t} (\SCL(x))), \SCB_{ s}^\partial(\SCB_{t} (\alpha))
		\right)_{s \in \BQ_{\ge 0}},
	\end{equation*}
	for the product topology where each component is equipped with the Hausdorff topology and $(\SCB^\partial_{ s}(\SCB_{t} (\alpha)))_{s\ge 0}$ (resp.~$(\SCB_{ s}^\partial(\SCB_{t} (\SCL(x))))_{s\ge 0}$) has the same law as a collection of independent uniform explorations of the $\CLE_4$, started from the whole boundary of each connected component of $\BD \setminus \SCB_{t}(\alpha)$ (resp.~$\BD \setminus\SCB_{t}(\SCL(x))$). Moreover, jointly with~(equation eq cv subsequence of the paper),~(equation eq cv Hausdorff balls of the paper),~(equation eq cv subsequence boundary of the paper), and the above convergence, for all $t \in \BQ_{\ge 0}$, $x,y \in \BD_\BQ$, $\alpha \in \SCS'$,
	\begin{equation}

		\left(K^{\kappa_n, \partial}_{\SCB_{\ka_{\kappa_n} t}^{\kappa_n} (\alpha), \SCL^{\kappa_n}(y)}, K^{\kappa_n, \partial}_{\SCB_{\ka_{\kappa_n} t}^{\kappa_n} (\SCL^{\kappa_n}(x)), \SCL^{\kappa_n}(y)} \right)
		\mathop{\longrightarrow}\limits_{n\to \infty}^{(\mathrm{d})}
		\left( K^\partial_{\SCB_t(\alpha), \SCL(y)}, K^\partial_{\SCB_t(\SCL(x)), \SCL(y)}
		\right),
	\end{equation}
	for the Hausdorff topology, where $K^\partial_{\SCB_t(\alpha), \SCL(y)}, K^\partial_{\SCB_t(\SCL(x)), \SCL(y)}$ are random compact subsets of $\overline{ \BD}$.

[Definition def:extFLE of arXiv:2608.05089, 'Correlation decay in area-tilted line ensembles'] For $\mathbf{x}, \mathbf{y} \in \mathbb{A}_+^n$ and functions
$\mathbf{f}, \mathbf{g}: (\ell,r) \to \mathbb{A}_+^n$ with $\mathbf{f} \prec \mathbf{g}$ and $\bm{\lambda} : (\ell,r) \to \mathbb{R}^n$,
let  $\mathcal{L}^{\mathbf{x},\mathbf{y},\bm{\lambda}}_{n,\ell,r,\mathbf{f},\mathbf{g}}$ denote the probability measure
with the following Radon--Nikodym derivative relative to the
Brownian bridge measure $\mathcal{B}^{\mathbf{x},\mathbf{y}}_{n,\ell,r}$:
\begin{equation}
    \frac{d\mathcal{L}^{\mathbf{x},\mathbf{y},\bm{\lambda}}_{n,\ell,r,\mathbf{f},\mathbf{g}}}{d\mathcal{B}^{\mathbf{x},\mathbf{y}}_{n,\ell,r}}(\mathbf{X}_n)
    \propto \Exp{-2 \sum_{i=1}^n \int_\ell^r \lambda^i(t) X^i_n(t) \,dt}
    \ind{\mathbf{X}_n(t) \in \mathbb{A}_+^n \text{ for all } t \in [\ell,r]}
    \mathbf{1}_{\{\mathbf{f} \prec \mathbf{X}_n \prec \mathbf{g}\}}.
\end{equation}
Note that to recover the geometrically increasing area tilts, we should
take $\bm{\lambda}(t) \equiv (1,\lambda,\lambda^2,\dotsb,\lambda^{n-1})$.

[Lemma 7 of arXiv:2505.20799, 'A note on the improved sparse Hanson-Wright inequalities'] Let $\xi$ be a random variable such that for $r\ge r_{0}$
	\begin{align}
		\Vert \xi\Vert_{L_r}\le \sum_{k=1}^{m}C_{k}r^{\beta_{k}}+C_{m+1},\nonumber
	\end{align}
	where $C_{1},\cdots, C_{m+1}> 0$ and $\beta_{1},\cdots, \beta_{m}>0$. Then for $t>0$,
	\begin{align}
		\mathbb{P}\big\{ \vert \xi\vert>e(mt+C_{m+1}) \big\}\le e^{r_{0}}\exp\Big(-\min\big\{\big(\frac{t}{C_{1}}\big)^{1/\beta_{1}},\cdots, \big(\frac{t}{C_{m}}\big)^{1/\beta_{m}}\big\}\Big).\nonumber
	\end{align}

