body:
[Cor consequences of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Assume that $D(\mathcal F_{\beta})\cap X^{a,b}_{p,p'}\neq \emptyset$ and  let $\mathsf{P}^*\in X^{a,b}_{p,p'}$ be the unique minimizer of $\mathcal F_{\beta}$ on $X^{a,b}_{p,p'}$. Then for any $\mathsf{P}\in X^{a,b}_{p,p'}\cap D(\mathcal F_{\beta})$
   \begin{align}
       \frac{\beta }{2a^{\frac{2-p}{p}}} \mathscr W_p^2(\mathsf{P},\mathsf{P}^*)\leq \mathcal F_{\beta}(\mathsf{P})-\mathcal F_{\beta}(\mathsf{P}^*)\leq \frac{a^{\frac{2-p}{p}}}{2\beta } \abs{\partial \mathcal F_{\beta}}^2(\mathsf{P}).
    \end{align}
    Moreover, for any curve of maximal slope $(\mathsf{P}_t)_{t>0}$ w.r.t. $\abs{\partial \mathcal F_{\beta}}$ in $X^{a,b}_{p,p'}$ satisfies for every $t\geq t_0>0$
    \begin{align}
        \frac{\beta }{2a^{\frac{2-p}{p}}}\mathscr W_p^2(\mathsf{P}_t,\mathsf{P}^*)\leq \mathcal F_{\beta}(\mathsf{P}_t)-\mathcal F_{\beta}(\mathsf{P}^*)\leq (\mathcal F_{\beta}(\mathsf{P}_{t_0})-\mathcal F_{\beta}(\mathsf{P}^*))e^{-2\beta a^{\frac{p-2}{p}}(t-t_0)}.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Prop local asymp expect CR 1 8 ver 1 of arXiv:2604.15146, 'Renormalised two-point functions of CLE$_4$ gaskets'] As $\max(\varepsilon_1,\varepsilon_2)\to 0$, we have that
\begin{multline*}
\mathbb{P}(E_{\varepsilon_1,\varepsilon_2}^v)
=
\varepsilon_{1}^{1/8}
\varepsilon_{2}^{1/8}
(\mathbf{C}_{\rm{SLE}4}^{\rm loop})^2
\\
\times
\mathbb{E}
\big[
\CR(z_1,\widehat{D}_{r_0}(z_1))^{-1/8}
\CR(z_2,\widehat{D}_{r_0}(z_2))^{-1/8}
\1_{E_{r_0,\varepsilon_1,\varepsilon_2}}
\1_{\{\mathbb{D}(z_j,r(\varepsilon_j))
\subset
\widehat{D}_{r_0}(z_j), j\in\{1,2\}\}}
\big]
(1+o(1))
.
\end{multline*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 9 (branching capacity defined by the past) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] For all finite sets \(A \subset \Z^{d}\),

\begin{equation*}{
\bcp(A):=\sum_{a \in A} \P(\Tree_{+}^{a} \cap A = \emptyset) = \sum_{a \in A} \P(\Tree_{-}^{a} \cap A = \emptyset).
}\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 31 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$, there exist $C,c>0$ such that for any $T>0$, $D\subset \widetilde{\mathbb{Z}}^d$ and $z_1,z_2,z_3\in \widetilde{\mathbb{Z}}^d\setminus D$ with $\min_{i\neq j}|z_i-z_j|\ge d$, 
	\begin{equation} 
		\mathbb{P}\big( \widehat{\mathcal{L}}_{1/2}^{D,z_1}\ge T \mid  z_1 \xleftrightarrow{(D)} z_2, z_2 \xleftrightarrow{(D)} z_3 \big) \le Ce^{-cT}. 
	\end{equation}

[Theorem 1 of arXiv:2605.15931, '2605.15931'] The sequence of processes $(n^{1/2}(f(X_{\tilde{\tau}^n(X)\wedge .})-f(x)))_{n \in \mathbb{N}}$ converges in the sense of finite-dimensional distributions over any finite collection $\{t_1,t_2,...,t_m\}\subset (0,\infty)$. In particular, for any $\{t_1,t_2,...,t_m\}\subset (0,\infty)$ and $\varphi:\mathbb{R}^{m\times \ell
		}\to \mathbb{R}$ continuous and bounded we have
		$$
		\begin{aligned}
		&|\mathbf{E}[\varphi(n^{1/2}(f(X_{\tilde{\tau}^n(X)\wedge t_1})-f(x)),...,n^{1/2}(f(X_{\tilde{\tau}^n(X)\wedge t_m})-f(x)))]\\
		&-\mathbf{E}[\varphi(J_f(x)\sigma(x)W_{\tau^1(\sigma(x)W)},...,J_f(x)\sigma(x)W_{\tau^1(\sigma(x)W)})]|\,{ \to }\,0
		\end{aligned}
		$$
		{as $n\to \infty$.} However, in general the sequence of processes $(n^{1/2}(f(X_{\tilde{\tau}^n(X)\wedge.})-f(x)))_{n \in \mathbb{N}}$ does not converge weakly to the process $(J_f(x)\sigma(x)W_{\tau^1(\sigma(x)W)})_{t\geq 0}$ - which is a continuous-path process taking the value $J_f(x)\sigma(x)W_{\tau^1(\sigma(x)W)}$ at all $t\geq 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 26 of arXiv:2607.21759, 'Marchenko--Pastur law for tensor powers of exchangeable unconditional vectors'] Let $k = k_n$ and $L = L_n$ satisfy $Lk^2 / n \to 0$. Assume that $\E X_1^2 = 1$, $\frac{1}{n^2} \E\nm{\mathbf X}_4^8  \leq L^2$ for all $n$, and also  
    \begin{equation}
        \frac{1}{n^{2k}} \E\nm{\mathbf X}_2^{4k} \to 1. 
    \end{equation} Then, for any $1 \leq r \leq k$, \begin{equation}
        \frac{1}{n^{2r}} \E\nm{\mathbf X}_2^{4r} \to 1. 
    \end{equation}
    Moreover, we also have \begin{equation}  \E(X_1^2 \dotsm X_k^2) - \frac{1}{n^k} \E\nm{\mathbf X}_2^{2k} \to 0,\end{equation} which implies \[
        \E(X_1^2 \dotsm X_k^2) \to 1.
    \]

