[Theorem 8 of arXiv:2506.20411, 'Maximal Counts in the Stopped Occupancy Problem'] For every $K\in{\mathbb Z}_{>0}$, as $n\to\infty$ locally uniformly in  $s\in {\mathbb R}$
\begin{equation}
d_{\rm TV}\big( (M_{n,i}(\gaa_n+s)-b_n)_{i=1}^K\,,\,(\lceil\xi_i+ (e-1)s+c_n\rceil)_{i=1}^K\big)\to 0,
\end{equation}
where $\xi_i\stackrel{\rm d}{=}{\rm Gumbel}(i)$ is the decreasing sequence of  atoms of\/ $\Xi$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm th:finite_time_identity_non_random_IC of arXiv:2412.03370, 'TASEP with a general initial condition and a deterministically moving wall'] For any $n \in \mathbb{N}$, it holds
	\begin{equation}  \begin{aligned} 
	&\mathbb{P} (x^f_n(T) > s) \\  &= \mathbb{P} ( x_n(t) > s - f(T-t) \ \forall t \in [0,T], \ x_{n-j}(T) > s - x_{1+j}^f \ \forall j \in [n-1]),
	\end{aligned} \end{equation}
	where $[n-1] = \{0, \dots, n-1\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] For $x\neq\wt x$,
  \begin{align}
    \begin{aligned}
      \lim_{\eps\downarrow0}
        \frac1\be T_{1,\eps}(x,\wt x)
      =
      \frac{\al^2}{2}\sgn(\wt x-x)
        \rmP_{\wt x,x}^{\be}(\tau=\infty)
   +
      \al^2\EE\bigl[Q_0^{\be}\{\ga_n>-x\}\bigr]
      -\frac{\al^2}{2}.
    \end{aligned}
  \end{align}

[Theorem t:harris of arXiv:2607.10708, 'A class of Markov processes with resetting and applications to cybersecurity'] Suppose $\alpha >0$ and let  define
\begin{equation}
\varphi_n(t)=\int\exp(t\,\ell(n,z))\,dG(z).
\end{equation}
Suppose that there exists a bounded function $r:\mathbb N\cup\{0\} \to \mathbb R$ that does not change sign and  is bounded away from $0$, and satisfies

\begin{equation} 
\begin{split}
\varphi_{n+1}(r(n+1))\geq 1+ \alpha r(n), \quad \forall n\geq 0, \quad \mbox{if } r(0)>0;\\
\varphi_{n+1}(r(n+1))\leq 1+ \alpha r(n), \quad \forall n\geq 0, \quad \mbox{if } r(0)<0.
\end{split}

\end{equation}
Then,
if $\sup_n \varphi_n(r(n))<\infty$ and $\sup_n r(n)<\infty$, $\mathbb E^{\alpha,x}[T_A]<\infty$.

