body:
[Theorem thm:combined-early-late-bounded of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let
$ \beta \in [ \nicefrac{ 1 }{ 2 } , 1 ) $, $ \varepsilon \in [0,\infty) $, $ \rho, c, q, C_X, L_f, C_{ \mathrm{Loj} } \in (0,\infty) $,
let $ V \subseteq {\mathbb R}^d $ be measurable,
and suppose that the following is true:

\begin{enumerate}[label=(\alph*)]
\item[(a)] 
It holds that
\begin{align}\begin{split} 
  q+3\ln\beta\ge\rho
  .
 \end{split}\end{align}
\item[(b)]  $(X,U)$ is
$(c,q)$-regular on $V$ in the sense of (def:regular of the paper) and uniformly
bounded: for every $\theta\in V$, $i\in\{1,\dots,d\}$ one has
\bas{
  \|X^{(i)}(\theta,U)\|_{L^\infty}\le C_X.
}
\item[(c)] There exists $ F \colon {\mathbb R}^d\to[0,\infty)$ with globally $L_f$-Lipschitz
continuous derivative such that for every $ \theta \in V $ one has
\begin{align}\begin{split} 
  f_X(\theta)=-\nabla F(\theta)
 \end{split}\end{align}
and
\bas{
  F(\theta)\le C_{\mathrm{Loj}}|f_X(\theta)|^2.
}
\item[(d)] The step-size sequence $(\gamma_n)_{n\in{\mathbb N}}$ is
$(0,\infty)$-valued and satisfies for all $ n \in {\mathbb N} \backslash \{ 1 \} $ that
\bas{
  \gamma_n \le C_{\mathrm{Loj}}(C_X+\varepsilon) .
}
\end{enumerate}
Set
\bas{

\begin{aligned}
\kappa_0&=\frac{4}{1-e^{-1/2}},
&\qquad \kappa_1&=\frac{1}{2C_{\mathrm{Loj}}(C_X+\varepsilon)},\\
\kappa_2&=\frac{8\kappa_0^3dL_fC_X^6C_{\mathrm{Loj}}(C_X+\varepsilon)}{c^3}
D_{\rho,3},
&\qquad \kappa_3&=\frac{\kappa_0 dL_fC_X^2}{c}D_{\rho,1},
\end{aligned}
}
and, for every $ n \in {\mathbb N} \backslash \{ 1 \} $,
\bas{
R_n^{\mathrm{early}}
&=d\Bigl(2C_Xn^{1/2}
+\frac{L_f}{2}n\gamma_n\Bigr)e^{-q(n-1)/\kappa_0}\gamma_n.
}
For every $ n \in {\mathbb N}_0 $ set $ t_n = \sum_{ k = 1 }^n \gamma_k $.
Then one has for every $ n \in {\mathbb N} $ that
\bas{

&
  {\mathbb E}\bigl[
    F( \theta_n )
    \1_{ \{ \tau \ge n \} }
  \bigr]
\\ &

  \le
  \bigl[
    F(\theta_0)^{1/2}
    +
    (
      2^{ - 1 } d L_f
    )^{ 1 / 2 }
    \gamma_1
  \bigr]^2
  e^{ \kappa_1 ( t_1 - t_n ) }
  +
  \sum_{ j = 2 }^n
  \left[
    \kappa_2
    \bigl[
      ( j - 1 )^{ - 1 } \vee (1-\beta)
    \bigr]^2
    \gamma_j
    +
    \kappa_3
    \gamma_j^2
    +
    R_j^{ \mathrm{early} }
  \right]
  e^{ \kappa_1 (t_j - t_n) }
  ,
}
where
$
  \tau = \inf\{ n \in {\mathbb N}_0 \colon \theta_n \notin V \}
$.

