body:
[Theorem thm:SIR_monotonicity of arXiv:2607.29409, 'The Zombie Infection Model'] Let $G_{1} = (V_{1}, E_{1})$ and $G_{2} = (V_{2}
		, E_{2})$ be countable, locally bounded and connected graphs. Assume that the
		following conditions hold:
		\begin{enumerate}[label=\roman{*}.]
			\item $\lambda_{1}\leq\lambda_{2}$ and $\mu_{1}\geq\mu_{2}$ 

			\item $V_{1}\subseteq V_{2}$ and $E_{1}\subseteq E_{2}$ 

			\item $\Delta_{1} \Subset V_{1},\Delta_{2} \Subset V_{2}$ with $\Delta_{1}
				\subset \Delta_{2}$ 
		\end{enumerate}
		Then there is a coupling $\widehat{\BP}$ of
		$\big(\xi_{t}^{(1)}\big)\sim\BP_{\lambda_1,\mu_1,G_1,\Delta_1}^{\SIR}$
		and
		$\big(\xi_{t}^{(2)}\big)\sim\BP_{\lambda_2,\mu_2,G_2,\Delta_2}^{\SIR}$
		such that
		\begin{equation}
			\widehat{\BP}\!\left( \xi_{t}^{(1)}\leq \xi_{t}^{(2)}
			\: \forall \: t\in [0,\infty) \right) =1.
		\end{equation}

