body:
[Proposition prop:phi of arXiv:2607.12564, 'Power-law and log-periodic degree tails for a family of probability generating function eq'] The series $\Phi(u):=\sum_{\ell\in\mathbb{Z}}\eta\bigl(\lambda^{\,u-\ell}\bigr)$ converges locally uniformly
on $\mathbb{R}$, and uniformly on $[0,1]$, to a continuous, strictly positive function of period $1$. Moreover, with
$N=\lfloor\log_\lambda x\rfloor$ and $\{\,\cdot\,\}$ denoting the fractional part,
\begin{equation}
\begin{aligned}
  x^{\rho+1}\sum_{n\ge0}\lambda^{-(\rho+1)n}w_j(x\lambda^{-n})
  &=\Phi(\log_\lambda x)-\sum_{\ell<-N}\eta(\lambda^{\{\log_\lambda x\}-\ell})\\
  &=\Phi(\log_\lambda x)+o(1)\qquad(x\to\infty),
\end{aligned}
\end{equation}
the error being uniform in $\{\log_\lambda x\}$.

[Theorem 4 (Deterministic perturbation bound) of arXiv:2609.01319, 'Matched Queries for Curvature and Density at Branching Junctions'] Assume $\sigma_{\min}(B)=\gamma>0$. Let the implemented design be $\widehat B=B+E$ and the observed response be $\widehat y=y+e$. If $\norm{E}_{\op}<\gamma$, the least-squares estimator obeys
\begin{equation}
\norm{\widehat\theta-\theta}
\le
\frac{
 C_{\mathrm{bias}}\sigma^\alpha
 +\norm{e}
 +\norm{E}_{\op}\norm{\theta}
}{\gamma-\norm{E}_{\op}}.

\end{equation}
If the two normalized score fields have stacked errors $\varepsilon_\sigma$ and $\varepsilon_{\lambda\sigma}$, and the center remainder in \cref{eq:provisional-center} is $r_\sigma$, one may take
\begin{equation}
\norm{e}
\le
\frac{\varepsilon_\sigma+\varepsilon_{\lambda\sigma}}{(\lambda-1)\sigma}
+C_{\mathrm{ctr}}\frac{\norm{r_\sigma}}{\sigma^2}.

\end{equation}
Errors in recovered directions and weights enter through $E$ by smooth dependence of the basis on the first-order geometry over any declared separated, positive-weight class. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $W$ be an $N\times N$ GUE matrix. For any $n_1,n_2\in \N\cup\{0\}$ and $\bm{k}\in \N^{n_1}$, $\bm{l}\in \N^{n_2}$ it holds that
\begin{equation}
\Phi_0(\bm{k},\bm{l})=\delta_{n_1,n_2}\frac{\ii^{|\bm{k}|-|\bm{l}|}}{2^{|\bm{k}|+|\bm{l}|}} \prod_{j=1}^n \frac{1}{(k_j-1)!(l_j-1)!}\sum_{\sigma\in S_{n}} \prod_{j=1}^n (k_j+l_{\sigma(j)}-1)!. 

\end{equation}
Here in the case $n_1=n_2$ we denoted $n:=n_1$, and $S_n$ is the set of permutations of $[n]$. For any $d\ge 1$ we further have
\begin{equation}
\Phi_d(\bm{k},\bm{l})=0.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 7 (Branching capacity from escape probabilities) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] The branching capacity (associated with a \(\Tree\)-walk) of a finite
subset \(A \subset \Z^d\) is defined as

\begin{equation*}{
\bcp(A) = \sum_{a \in A} \P(\Tree_{+}^{a} \cap A = \emptyset).
}\end{equation*}
It implicitly depends on \(\mu\) and \(\theta\).

[Defn B-omega-mixing of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] \begin{enumerate}[wide,label=(\roman*),labelindent=0pt]\

\item  The  marks $U$ of the point process $\tilde \mathcal{P}=\sum_{x \in \mathcal{P}}
  \delta_{\tilde{x}}$, $\tilde{x}=(x,U)$, $x\in\mathbb{R}^d$,  $U\in\mathbb{K}$,
satisfy  {\em $\mathbb{B} $-mixing correlations} if
 (equation e.markmixing of the paper) holds when \textnormal{BL}\ is replaced by $\mathbb{B} $; i.e.,
  for all $p,q \in \mathbb{N}$, and all $f \in \mathbb{B} (\mathbb{K}^p), g \in \mathbb{B} (\mathbb{K}^q)$, 
 \begin{align*}
\left|\mathbb {E} _{\bk x1{p+q}}[f(\bk U1{p})g(\bk U{p+1}{p+q})] - \mathbb {E} _{\bk x1p}[f(\bk U1p)] \mathbb {E} _{\bk x{p+1}{p+q}}[g(\bk U{p+1}{p+q})]\right|
\, & \le \, \omega_{p+q}(s), \qquad x_1,\ldots,x_{p+q} \in \mathbb{R}^d,
\end{align*}
where $s = \inf_{i \in \{1,...,p\}, j \in \{p + 1,...,p + q\} } |x_i - x_j|$ and $\omega_k :  [0, \infty) \to [0, 2]$, $k\in\mathbb{N}$ 
is an increasing-decreasing family of functions.

\item  A marked point process $\tilde \mathcal{P} = \{(x, U(x))\}_{x \in \mathcal{P}}$ has  {\em $\mathbb{B} $-mixing
  correlations}  if (equation e.mppmixing of the paper) holds when \textnormal{BL}\ is replaced by $\mathbb{B} $ i.e.,
  for all $p,q \in \mathbb{N}$, and all $f \in \mathbb{B} (\mathbb{K}^p), g \in \mathbb{B} (\mathbb{K}^q)$, 
 \begin{align} \nonumber
& \left|\mathbb {E} _{\bk x1{p+q}}[f(\bk U1{p})g(\bk U{p+1}{p+q})]\rho^{(p+q)}(\bk x1{p+q}) - \mathbb {E} _{\bk x1p}[f(\bk U1p)] \rho^{(p)}(\bk x1{p})\mathbb {E} _{\bk x{p+1}{p+q}}[g(\bk U{p+1}{p+q})]\rho^{(q)}(\bk
x{p+1}{p+q})\right|\\
 &\hspace{0.1\linewidth}\le \omega_{p+q}(s),  \qquad x_1,\ldots,x_{p+q} \in \mathbb{R}^d,
\end{align}
with $s,\omega_k, k \in \mathbb{N}$ as in Item (i). Similarly, a {\em family of marked point processes}   $(\tilde\mathcal{P}_l)_{l \in \mathbb{N}},$ has  $\mathbb{B} $-mixing correlations if Definition~(d.omegahmixing of the paper)(i.family-mixing of the paper) holds when \textnormal{BL}\ is replaced by $\mathbb{B} $. 

\item  If  $(\omega_k)_{k \in \mathbb{N}}$ are fast decreasing functions, then   we respectively speak of  the  {\em fast $\mathbb{B} $-mixing} of  marks, a marked point process, or a family of marked point processes.
\end{enumerate}

[Lemma lem:uniformgreensbound of arXiv:2608.11603, 'Continuous-time directed polymers to the Critical SHF via moments'] {}
	Recall that ${\mathcal{L}}_{\varepsilon,n} = \sum_{k=1}^{n}\mathcal{L}_{\varepsilon}^{(k)}$. Then the following inequality holds:
	\begin{equation*}
		\frac{1}{\lambda + \F{\mathcal{L}}_{\varepsilon,n}(\xi)} \lesssim \frac{1}{\lambda + \frac{1}{2} \Vert \xi\Vert^2} \, ,
	\end{equation*}
	uniformly over $\xi \in \widehat{\mathbb{T}}_{\varepsilon}^{2[\![n]\!]}$ and $\varepsilon > 0$. Moreover, we have the bound
	\begin{equation*}
     \Big|\F{\mathcal{L}}_{\varepsilon,n}(\xi) - \frac{1}{2}\Vert \xi\Vert^2 \,  \Big| \lesssim \varepsilon^{\delta}\Vert \xi\Vert^{2+\delta} \, \, ,
	\end{equation*}
	where $\delta$ is as in Assumption~(assumption2 of the paper). In particular, this implies that the symbol $\F{\mathcal{L}}_{\varepsilon,n}(\xi)$ converges to $\frac{1}{2} \Vert \xi\Vert^2$ uniformly on compact sets.

