[Thm 42 (Domination, strictness and attainment) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] Let $\sigma, \alpha > 0$. Every $X \in \SG(\sigma^2,\alpha)$ satisfies
\begin{align*}
    X \lecx c^{\SG}(\sigma,\alpha)\,\Lap,
\end{align*}
so that the infimum in \eqref{eqn:defcSG} is a minimum, and
\begin{align}
    c^{\SG}(\sigma,\alpha) > \sigma \vee \alpha.

\end{align}
An extremal pair exists: there are a weight $p_a \in (0,1/2)$ and a centered member $Y$ of $\SG(\sigma^2,\alpha)$ carried by two points with masses $p_a$ and $1 - p_a$ such that, with $t \coloneqq c^{\SG}(\sigma,\alpha)\log(1/(2p_a))$ and $f(x) \coloneqq (x-t)_+$,
\begin{align*}
    \E\left[f(Y)\right] = \E\left[f\left(c^{\SG}(\sigma,\alpha)\Lap\right)\right].
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:f-g of arXiv:2410.23944, 'Hitting time mixing for the random transposition walk'] Let $M \in \mathbb{N}$ and $T \subseteq [n]$ such that $M \leq T = n^{o(1)}$. Then,
\begin{itemize}
    \item $\mathbb{P}[\mathcal{G}(T)] = (1+n^{-1+o(1)}){\mathbb{P}[\mathcal{G}(M)]\gamma_t^{|T|-M}}{n^{M-|T|}}$,

    \item $\mathbb{P}[\mathcal{F}(M)] = (1+n^{-1+o(1)})\mathbb{P}[\mathcal{G}(M)]\exp(-\gamma_t)$, 
    \item $\sum_{T \supseteq [M], T \leq n^{o(1)}} \mathbb{P}[\mathcal{G}(T)] \leq n^{o(1)}\mathbb{P}[\mathcal{F}(M)]$. 
\end{itemize}

