[Theorem 12 of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] Consider a \(\Tree\)-walk in \(\Z^{d}\). We assume that there is
\(\delta > d\) such that \(\theta\) has a finite moment of order
\(\delta\). Then for \(d> \frac{2\alpha}{\alpha-1}\), we have
\begin{equation*}{
\bcp(B(0,R)) \asymp \mathrm{Cap}(B(0,R))\times  \P(H(\Tree) > R^{2}).
}\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 14 of arXiv:2606.17472, '2606.17472'] If $h(x)>0$ for $x\neq 0$, then
\begin{align*}
   \lim_{q\to 0}\left(r_q(0)\sum_{i=1}^n \bm{R}_q^{-1}(i,j)\right)= \left(\frac{\bm{H}^{-1}\bm{1}}{\bm{1}^T \bm{H}^{-1}\bm{1}}\right)_j,
\end{align*}
where 
\begin{align*}
    \bm{R}_q:=\Big(r_q(a_i-a_j)\Big)_{i,j=1}^n=\begin{pmatrix}
    r_q(0)&r_q(a_1-a_2)&\cdots &r_q(a_1-a_n)\\
    r_q(a_2-a_1)&r_q(0)&\cdots &r_q(a_2-a_n)\\
    \vdots &\vdots &&\vdots\\
    r_q(a_n-a_1)&r_q(a_n-a_2)&\cdots &r_q(0)
  \end{pmatrix}.
  \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor temper of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Assume that $D(\mathcal F_{\beta})\neq \emptyset$.
    For $0<\beta<\beta'$ let $\mathsf{P}_{\beta}$ and $\mathsf{P}_{\beta'}$ be the unique minimizers of $\mathcal F_{\beta}$ and $\mathcal F_{\beta'}$ on $\mathcal P_{s,1}(\Gamma)$ respectively. Set $\Pi_\beta:= \mathsf{gap}(\mathsf{P}_\beta)$ and $\Pi_{\beta'}:= \mathsf{gap}(\mathsf{P}_{\beta'})$ and assume that there exists $p'\geq p$ such that $\int  \mathsf{s}_0^{p'}\Pi_\beta(d \mathsf{s}),\int  \mathsf{s}_0^{p'}\Pi_{\beta'}(d \mathsf{s})<\infty$. Then \begin{align}
       \mathscr W_p^2(\mathsf{P}_{\beta},\mathsf{P}_{\beta'})\leq \frac{2(\beta'-\beta)}{\beta}\max\left(\int f( \mathsf{s}_0)^{\frac{p}{p-2}}\Pi_\beta(d \mathsf{s}) ,\int f( \mathsf{s}_0)^{\frac{p}{p-2}}\Pi_{\beta'}(d \mathsf{s}) \right)^{\frac{2-p}{p}}\mathcal W^{int}(\mathsf{P}_{\beta})
    \end{align}

