body:
[Thm persistence-extinction of arXiv:2607.05097, 'Asymptotics of Lyapunov Exponents and Phase Transitions for Fluids with Degenerate Forcing'] Let $(z_t,x_t) \in \mathcal{M} \coloneqq \mathbb{R}^d \times \mathbb{R}^n$ denote the solution to
    \begin{equ}
            dz = f(z,x)dt + \sigma dW_t \,,\qquad
            dx = F(z,x)dt \,,
    \end{equ}
    where $W_t$ is a standard $\mathbb{R}^d$-valued Wiener process, $\sigma \in \mathbb{R}$, the functions $f: \mathbb{R}^d \times \mathbb{R}^n \to \mathbb{R}^d$ and $F: \mathbb{R}^d \times \mathbb{R}^n \to \mathbb{R}^n$ are continuously differentiable with locally Lipschitz derivative, and $F(z,0) = 0$ for all $z \in \mathbb{R}^d$. Suppose there exists a function $\bar U: \mathbb{R}^d \times \mathbb{R}^n \to [1,\infty)$ such that:
    \begin{itemize}
        \item $\bar U \in \mathcal{C}^2$ has compact sublevel sets.
        \item There are constants $K,c > 0$ such that
        \begin{equation}
            \mathcal{L} \bar U \leq K - c\bar U \,,
        \end{equation}
        where $\mathcal{L}$ denotes the generator of (equation eq:general-sde of the paper).
        \item There is some $C > 0$ such that for all $z \in \mathbb{R}^d$, $x \in \mathbb{R}^n$
        \begin{equation}
            |\ip{F(z,x),x}| \leq C|x|^2\Big(2K - \frac{\mathcal{L} \bar U}{\bar U} + \frac{\sigma^2|\partial_z \bar U|^2}{\bar U^2}\Big)
        \end{equation}
    \end{itemize}


    Then define the process
    \begin{equation}
        \begin{aligned}
            dZ &= f(Z,0)dt + \sigma dW_t \\
            dv &= [\partial_xF(Z,0)v - \ip{\partial_xF(Z,0)v,v}v]dt \,,
        \end{aligned}
    \end{equation}
    let $P_{\mathrm{inv}}$ denote the set of all invariant measures of $(Z_t, v_t)$ on $\mathbb{R}^d \times S^{n-1}$, and define
    \begin{align*}
        \Lambda^+ &\coloneqq \sup_{\mu \in P_{\mathrm{inv}}} \int \ip{\partial_xF(z,0)v,v}d\mu(z,v) \\
        \Lambda^- &\coloneqq \inf_{\mu \in P_{\mathrm{inv}}} \int \ip{\partial_xF(z,0)v,v}d\mu(z,v) \,.
    \end{align*}

    Denoting $\mathcal{M}_0 \coloneqq \{(z,x) \in \mathbb{R}^d \times \mathbb{R}^n \mid x = 0\}$ we conclude:
    \begin{itemize}
        \item If $\Lambda^- > 0$, (equation eq:general-sde of the paper) has multiple invariant measures, at least one of which gives $\mathcal{M}_0$ measure $0$. Furthermore, for all $\delta > 0$ there is some $\eta > 0$ such that for all $(z_0,x_0) \in \mathcal{M}_+ \coloneqq \mathcal{M}_0^c$ we have
        $$\limsup_{t \to \infty} \frac{1}{t}|\{s \leq t \mid |x_s| < \eta \}| < \delta \quad a.s.$$
        \item If $\Lambda^+ < 0$ and there exists $\epsilon > 0$ and a continuously differentiable function $\Upsilon: \mathbb{R}^d \times \mathbb{R}^n \to [0,\infty)$ such that
        \begin{equation}
        \partial_z\Upsilon f+\partial_x\Upsilon F
\le -\epsilon\Upsilon \text{ on all of } \mathbb{R}^d \times \mathbb{R}^n 
        \end{equation}
 and if $(z_n,x_n) \in \mathbb{R}^d \times \mathbb{R}^n$ is such that $\Upsilon(z_n,x_n)\to0$ implies  $(z_n,x_n)\to 0$,
        then all invariant measures of (equation eq:general-sde of the paper) are supported on $\mathcal{M}_0$ and
        $$\limsup_{t \to \infty} \frac{1}{t}\ln |x_t| < 0 \quad a.s.$$
    \end{itemize}

[Lemma eq:LSI:uvn of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Suppose $(U, W)$ satisfy Assumption (as:results:invMeasure of the paper). Fix $n \in \ensuremath{\mathbb{N}}$. Define the family of functions
\begin{equation}
    U^n_v(x):= \begin{cases}
    U(x) &\quad v  \in \{-n+1,\ldots, n-1\}, \\
    \frac{1}{2}U(x) &\quad v \in \{-n, n\}.
    \end{cases}, \quad x \in \ensuremath{\mathbb{R}}^d,

\end{equation}
and
\begin{equation}
    H_n\big(\mathbf{x}^{(n)}\big) := - \sum_{v = -n}^n \bigg(U^n_v(x_v) + \sum_{u \sim v} \frac{1}{2}W(x_v - x_u) \bigg), \quad \mathbf{x}^{(n)} \in (\ensuremath{\mathbb{R}}^d)^{V_n}.

\end{equation}
Let $\theta^n$ be the Gibbs measure of Definition (def:results:gibbs of the paper). We have the following alternative representation of $\theta^n$:
\begin{equation}
    \theta^{n}(d\mathbf{x}^{(n)}) = \frac{1}{\mathcal{Z}^n} e^{-H_n(\mathbf{x}^{(n)})} d\mathbf{x}^{(n)},

\end{equation}
where $Z^{n}$ was defined in (equation eq:results:gibbsPFN of the paper). Moreover $\theta^n$ is a 1-MRF, and for each $v \in \mathbb{T}_2^n$ and $x_{\partial v} \in (\ensuremath{\mathbb{R}}^d)^{N_v(\mathbb{T}_2^n)}$, the conditional distributions $\theta^n_v$ take the following form:
\begin{equation}
\begin{aligned}
    \theta_v^n\big(dx_v|x_{\partial v}\big) &= \frac{1}{\mathcal{Z}^n_v\big(x_{\partial v}\big)} \exp\bigg( - U^n_v(x_v) - \sum_{u \sim v} W(x_v - x_u) \bigg) dx_v, \\
{\mathcal{Z}^n_v\big(x_{\partial v}\big)} &:= \int_{\ensuremath{\mathbb{R}}^d} \exp\bigg( - U^n_v(x) - \sum_{u \sim v} W(x - x_u) \bigg) dx.
\end{aligned}

\end{equation}
Moreover for each $v$ and $x_{\partial v} \in (\ensuremath{\mathbb{R}}^d)^{N_v(\mathbb{T}_2^n)}$, $\theta^n_v(\cdot | x_{\partial v})$ has finite moments of all orders.

[Theorem thm:spectral_heat of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $\Omega\subset \mathbb G$ be bounded, open set satisfying the volume density condition (see Definition~(def:VDC of the paper)). Then for all $0<\alpha<1$, 
        \begin{align}
            \lim_{t\to 0}\frac{\operatorname{Vol}(\Omega)-\widetilde{H}^{(\alpha)}_\Omega(t)}{t}=\operatorname{Per}^{(\alpha)}_{\mathcal H}(\Omega)
        \end{align}
        whenever $\operatorname{Per}^{(\alpha)}_{\mathcal H}(\Omega)<\infty$.
         In particular, (equation eq:lim_0_1 of the paper) holds for all bounded domains with $C^1$ boundary that does not have any characteristic points. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 of arXiv:2608.27156, 'Traveling Waves in Equity Markets with\\Rank-Based Entry and Exit'] Assume $\sigma^2, \tilde b \in C^1([0,1])$ with $\min_{[0,1]} \sigma^2 > 0$. Let $\tilde f \in C^1([0,1])$ be bistable: $\tilde f(0) = \tilde f(1) = 0$, and $\tilde f$ has exactly one interior zero $q^* \in (0,1)$, with $\tilde f < 0$ on $(0, q^*)$ and $\tilde f > 0$ on $(q^*, 1)$. Assume also that the three zeros are nondegenerate: $\tilde f'(0) < 0$, $\tilde f'(q^*) > 0$, and $\tilde f'(1) < 0$. Then:
\begin{enumerate}[label=(\roman*)]
\item There exist a speed $c \in \R$ and a strictly increasing profile $V \in C^2(\R)$ with $V(-\infty) = 0$ and $V(+\infty) = 1$, solving the traveling-wave equation \eqref{eq:wave-ode}. The pair is unique, in that no other speed admits a wavefront joining $0$ and $1$, and the profile is unique up to translation.
\item $V$ approaches each of its limits exponentially fast. The rate at the end state $e$ is a root of the characteristic equation
\begin{equation}
    \tfrac{1}{2}\,\sigma^2(e)\, r^2 + \big(c - \tilde b(e)\big)\, r + \tilde f'(e) \;=\; 0, \qquad e \in \{0, 1\},
\end{equation}
the positive root at $e = 0$ and the negative root at $e = 1$.
\item The level parameterization of $V$ satisfies the wave identity \eqref{eq:wave-identity-main}, with boundary values $\varphi(0) = \varphi(1) = 0$.
\end{enumerate}

[Proposition 24 of arXiv:2609.00690, 'Boundary behavior and optimal pointwise H\"older exponent of the total local time of $(1+\'] Assume that $0<\xi_0<1+2/\beta$ satisfies
	\begin{equation}
		\exists\,1\leq n_{\xi_0}(\omega)<\infty\ a.s.
		\text{ such that }
		L^x\leq 2^{-\xi_0 n},
		\qquad
		x\in Z_n,\ n\geq n_{\xi_0}(\omega).
	\end{equation}
	Then, for every
	\begin{equation}
		0<\xi_1<
		1+\frac{1+\xi_0}{1+\beta},
	\end{equation}
	we have
	\begin{equation}
		\exists\,1\leq n_{\xi_1}(\omega)<\infty\ a.s.
		\text{ such that }
		L^x\leq 2^{-\xi_1 n},
		\qquad
		x\in Z_n,\ n\geq n_{\xi_1}(\omega).
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:squarefree-profile-error of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:squarefree-rank-one}
Let \(S\subset[N]\) have cardinality \(k\ge p\), put
\[
 v_S=k^{-1/2}\sum_{i\in S}e_i,\qquad
 P_{k,S}(x)=\frac{p!}{k^{p/2}}
 \sum_{\substack{A\subset S\\ |A|=p}}\prod_{i\in A}x_i.
\]
Then
\begin{equation}
 \sup_{x\in\mathbb S^{N-1}(1)}
 \abs{P_{k,S}(x)-\ip{x}{v_S}^p}
 \le\frac{\binom p2}{k}.
\end{equation}

[Defi def:curve of maximal slope of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] [AGS08]
    Let $(S,d)$ be a metric space and $F:S\to (-\infty,\infty]$ measurable. A locally absolutely continuous curve $v:(a,b)\to S$ is a curve of maximal slope for the functional $F$ with respect to its strong upper gradient $g$, if $F\circ v$ is $\mathsf{Leb}_{\IR}-$a.e. equal to  a non-increasing map $f$ and \begin{align*}
        f'(t)\leq -\frac{1}{2}\left\lvertv'\right\rvert^2(t)-\frac{1}{2}g^2(v(t)) \text{ in } (0,\infty).
    \end{align*}

[Lemma 30 of arXiv:2609.04033, 'From configuration spaces to graph complexes via $\mathbf{FA}$-modules'] There is an isomorphism of graded $S_n$-representations $$H^\ast_c(F(S^1\vee S^1,n))\tensor_{\mathbb{Z}_2\times S_3}( Id\boxtimes V_{2,1})\cong\bigoplus_\lambda \Sigma^{|\lambda|} q_\lambda\Phi[n,\lambda^\ast]$$ where

$$
q_{\lambda} = \begin{cases}
	\left\lfloor \ds\frac{a-b+2}{3} \right\rfloor & \text{ if } \lambda = (a,b) \text{ and } a\equiv b \text{ mod } 2, \\ \\
	0 & \text{ else.}
\end{cases} 
$$

[Theorem 6 of arXiv:2606.25501, 'An RDT based approach to large deviations of Wishart and Wigner matrices spectral edges'] (\cite{Gordon85})
 Assume the setup of Theorem \ref{thm:minGordonpos1}. Let $\psi_q(\cdot)$ be an increasing function on the real axis. Then
\begin{equation*}
\mE(\min_{i}\max_{j}\psi_q(X_{ij}))\leq \mE(\min_i\max_{j} \psi_q(Y_{ij})).
\end{equation*}
Also, let $\psi_q(\cdot)$ be a decreasing function on the real axis. Then
\begin{equation*}
   \mE(\max_{i}\min_{j}\psi_q(X_{ij}))\geq \mE(\max_i\min_{j}\psi_q(Y_{ij})).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 of arXiv:2506.17061, 'Non-uniform bounds for non-normal approximation via Stein's method with applications to th'] For $z \ge 5$ and $\xi$ is a random variable satisfying $0\le |\xi|\le |\Delta|$. Then
		\begin{equation}
			\E(f_{z}(W))^2 \le \dfrac{B^p (p^{p/k}+\E|W|^{2p})}{(1+z)^{2p}},
		\end{equation}
		and
		\begin{equation}
			\E(f_{z}'(W+\xi))^2 \le \dfrac{B^p (p^{p/k}+\E|W|^{2p})}{(1+z)^{2p}}.
		\end{equation}

