[Theorem 2 of arXiv:2506.22040, '\vspace{-3em} Khinchin inequalities for uniforms on spheres with a deficit'] Let $d \geq 2$ be a fixed dimension, let $\xi_1, \xi_2, \dots$ be independent random vectors uniform on the unit Euclidean sphere $S^{d-1}$ in $\R^d$. Let $p \geq 2$. For every $n \geq 2$, every real scalars $a_1, \dots, a_n$ with $\sum_{j=1}^n a_j^2 = 1$, we have
\begin{equation}
\E\left|\sum_{j=1}^n a_j\xi_j\right|^p \leq \E\left|\sum_{j=1}^n \frac{1}{\sqrt{n}}\xi_j\right|^p - \tilde{c}_{p,d}\sum_{j=1}^n \left(\frac{1}{n}-a_j^2\right)^2,
\end{equation}
where
\[ 
\tilde{c}_{p,d} = \frac{p(p-2)}{4d}\begin{cases}
\frac{(p+d-2)(p+d-4)}{d(d+2)}, & 2 \leq p \leq 4, \\ 0.385, & p > 4. \end{cases}
 \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 212 (budget constraint) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Fix parameters $\alpha,L,\iota,\epsilon$. Let $M,N\to\infty$ with $M/N\to\alpha$. Let $\omega$ denote a random variable. Let $\bG,\bXi$ be $M\times N$ matrices with i.i.d.\ standard gaussian entries, with rows $\bg^1,\ldots,\bg^M$ and $\bmeta^1,\ldots,\bmeta^M$ respectively,  such that $\bXi$ is independent of $(\bG,\omega)$. Let $\bar{\bx}\equiv \bar{\bx}(\bG)$ and $\hat{\by} \equiv \hat{\by}(\bG,\bXi)$ be $L$-Lipschitz, $\R^N$-valued functions such that 
	\begin{align*}
	&\E(\|\bar{\bx}\|^2)=\E(\|\hat{\by}\|^2)=N,\\
	&\E(\hat{\by}\,|\,\bG)=0 \textup{ almost surely.}
	\end{align*}
Suppose for some $r,s \ge 1$ we have a partition, which is permitted to depend on $(\bG,\omega)$ but not on $\bXi$:
	 \begin{align*}
    [M] = \bigsqcup_{j=1}^r B_j \textup{ with } 
    \frac{|B_j|}{M}
    = \lambda_j(\bG,\omega)\,,\\
    [N] = \bigsqcup_{j=1}^s 
    K_j \textup{ with } 
    \frac{|K_j|}{N}
    = \mu_j(\bG,\omega)\,,
    \end{align*}
such that $\min_j\lambda_j\ge\iota$ and $\min_j\mu_j\ge\iota$ hold $(\bG,\omega)$-almost surely. Then define the random variables
     \begin{align}

    \bbb_j \equiv \bbb(B_j)
        &\equiv 
        \frac{1}{|B_j|}
        \sum_{a\in B_j}
        \frac{(\bmeta^a,\by)}{N^{1/2}}
        \,,\\

    \vvv_j \equiv \vvv(B_j)
        &\equiv 
        \frac{1}{|B_j|}
        \sum_{a\in B_j}
        \frac{(\bar{\bg}^a,\by)^2}{N}
        \,,\\

    \uuu_j \equiv \uuu(B_j)
        &\equiv 
        \frac{1}{|B_j|}
        \sum_{a\in B_j}
        \frac{(\bmeta^a,\bar{\bx})
        (\bar{\bg}^a,\by)}{N}
        \,,\\

    \www_j
    \equiv \www(K_j) 
    &\equiv \frac{1}{|K_j|}
        \sum_{i\in K_j}
        (\by_i)^2\,.\end{align}
Recall the definition of the function $\Cost\equiv\Cost_0$ from \eqref{e:cost}. Then, for all sufficiently large $N$, we have
    \[
    \sum_{j=1}^r
    \frac{|B_j|}{M}
    \Cost(\bbb_j,\vvv_j,\uuu_j)
    \le
    \frac{1}{\alpha}
    \bigg( \sum_{j=1}^s
        \frac{|K_j|}{N}
        (\www_j)^{1/2}\bigg)^2
     +  \epsilon\,,
    \]
with probability at least $1-e^{-cN}$, where $c$ is a positive constant depending on the parameters $\alpha,L,\iota,\epsilon$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb$, $f\in \Sob^k(\Rbb^n,\gamma_n)$, $\kappa\in \Nbb^n$ with $|\kappa|=k$, and $t\geq 0$,
\begin{equation}
    \Dop^\kappa \Pop_t f = \upe^{-t|\kappa|} \Pop_t \Dop^\kappa f,
\end{equation}
and consequently, for all $k\in \Nbb$,
\begin{equation}
    \left|\grad^k \Pop_t f\right| \leq \upe^{-kt}\Pop_t \left|\grad^k f\right|.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 12 of arXiv:2608.18557, 'Randomly Permuted Orthogonal Products and Fast Dimension Reduction'] Let \(I\subseteq [d]\) with \(|I|=m\), let $A,B \in O(d)$, and let \(X\subseteq \mathbb S^{d-1}\). We define the \emph{sampled column energy}
	of \(A\) by
	\begin{equation}
		\kappa_I(A)
		:=
		\frac dm
		\max_{k\in[d]}
		\sum_{j\in I}A_{jk}^2
	\end{equation}
	and the \emph{maximal variance} of \(B\) on \(X\) by
	\begin{equation}
		\Theta_B(X)
		:=
		d\sup_{\substack{x\in X\\k\in[d]}}
		\sum_{j=1}^dB_{kj}^2x_j^2.
	\end{equation}

[Lemma EI2 of arXiv:2607.05418, 'On the Group Randomness of 0-1 Real Sequences from Binary Linear Codes'] Assume $s \in \Omega_p$ and $\tilde{s} \in \widetilde{\Omega}_p$ are derived from exactly the same instant of $p$ (not necessarily distinct) codewords from $\mathcal{C}$. Then the eigenvalues of $\widetilde{\mathcal{G}}_{\tilde{s}}$ and $\mathcal{G}_s$ satisfy
    $$\lambda_{i+1} \leq \tilde{\lambda}_i \leq \lambda_{i-1}$$
    for $1 \leq i \leq p$, where for convention, $\lambda_0=+\infty$ and $\lambda_{p+1}=0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] There exists a constant $C_5>0$, which depends on the following values:

\begin{equation*}
\delta,\quad T, \quad \|v_0\|_{H^1(\Omega)},\quad \int_0^T \|\tilde{z}'(t)\|_{L^2(\Omega)}dt, 
\quad \int_0^T \|\tilde{g}(t)\|_{L^2(\Omega)}^2dt,
\end{equation*}
such that the following boundedness estimates hold for all $\nu \in (0,1)$:

\begin{align*}
&\int_0^T \|(S_{\text{{\tiny $1,\!\delta,\!\nu$}}}(\tilde{z},\tilde{g}))'(t)\|_{L^2(\Omega)}^2dt
+\sup_{0 \le t \le T} \Phi_\nu ((S_{\text{{\tiny $1,\!\delta,\!\nu$}}}(\tilde{z},\tilde{g}))(t))\\
&\hspace*{3cm}+\nu^2 \int_0^T \|(S_{\text{{\tiny $1,\!\delta,\!\nu$}}}(\tilde{z},\tilde{g}))(t)\|_{H^2(\Omega)}^2 dt \le C_5.
\end{align*}

