[Definition def:MP_lin of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] Let $s\in [0,T)$ and $\nu\in\mathcal{P}(\mathbb{R}^d)$. A probability measure $\mathbb{P}=\mathbb{P}_{s,\nu}$, on $(C_{[s,T)},\mathcal{B})$, is a solution to MP$(b,\sigma;s,\nu)$ if: 

\begin{itemize}
\item[(i)] $x_{s} \sim  \nu$ under $\mathbb{P}$;
\item[(ii)] for any $\varphi\in C_0^{\infty}(\mathbb{R}^d)$, the process defined by 
\begin{equation}
M_t : =\varphi(x_{t}) - \varphi(x_{s}) - \int_{s}^t \Big(   \langle  b(r, x_r) , \nabla \varphi(x_{r})  \rangle + \frac{1}{2}\text{tr}\big(\sigma \sigma^\top (r , x_r)  \nabla^2 \varphi(x_r)  \big) \Big) dr , \qquad t\in [s, T),
\end{equation}
is a martingale w.r.t. the natural filtration of $(x_t)_{t\in [s,T)}$.
\end{itemize}

[Theorem main of arXiv:2411.02362, 'Limit theorems for random Dirichlet series: boundary case'] Assume that $\mathbb{E}[\eta]=0$ and $\sigma^2=\mathbb{E}[\eta^2]\in(0,\infty)$. Then
\begin{equation}
C\Big(\Big(\Big(\frac{1}{2\sigma^2\log 1/s\, \log \log\log 1/s}\Big)^{1/2}\sum_{k\ge 2}\frac{(\log k)^{-1/2}}{k^{1/2+s}}\eta_k : s\in(0, {\rm e}^{-{\rm e}})\Big)\Big)=[-1,1]\quad\text{\rm a.s.}
\end{equation}
In particular,
\begin{equation}
\limsup_{s\to 0+}\Big(\frac{1}{\log 1/s\, \log\log\log 1/s}\Big)^{1/2}\sum_{k\ge 2}\frac{(\log k)^{-1/2}}{k^{1/2+s}}\eta_k=(2\sigma^2)^{1/2}\quad\text{\rm a.s.}
\end{equation}
and
\begin{equation}
\liminf_{s\to 0+}\Big(\frac{1}{\log 1/s\, \log\log\log 1/s}\Big)^{1/2}\sum_{k\ge 2}\frac{(\log k)^{-1/2}}{k^{1/2+s}}\eta_k=-(2\sigma^2)^{1/2}\quad\text{\rm a.s.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm main of arXiv:2410.24170, 'Persistent hubs in CMJ branching processes with independent increments and preferential at'] Suppose that $(\mathcal{T}_{i})_{i \in \mathbb{N}_{0}}$ is a generalised preferential attachment tree. Then,
    \begin{enumerate} 
        \item  If \[\sum_{j=0}^{\infty} \frac{1}{F(j)^2} = \infty \quad \text{almost surely},\] then $(\mathcal{T}_{i})_{i \in \mathbb{N}_{0}}$ almost surely does not have a persistent hub. 
        \item  Suppose that the following two conditions are satisfied: 
        \begin{enumerate}
            \item There exists a sequence $(x_{j})_{j \in \mathbb{N}_0}$ with $\sum_{j=0}^{\infty} \frac{1}{x_{j}^2} < \infty$ such that,
				\begin{equation}            
             		F(j) \geq x_{j} \quad \text{almost surely.}
             	\end{equation} 
            \item There exists a $\lambda > 0$ such that 
                \begin{equation} 
                \sum_{i=0}^{\infty} \prod_{j=0}^{i}\E{\frac{F(j)}{F(j) + \lambda}} < \infty.
                \end{equation}
        \end{enumerate}
        Then $(\mathcal{T}_{i})_{i \in \mathbb{N}_{0}}$ has a unique persistent hub almost surely. 
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma random_walk_range of arXiv:2512.06640, 'Existence and sharpness of the phase transition for the frog model on transitive graphs'] Let $G$ be a quasi-transitive graph that is of superlinear polynomial growth.
Consider a continuous-time simple random walk on $G$. 
There exist positive constants $c_0 = c_0(G)$ and $c_1 = c_1(G)$ such that the following is true.
Let $x \in V$ and $a > 1$.
For any $H \subseteq B_x(a)$ with $|H| \leq \frac{3}{4}|B_{x}(a)|$  and any $y \in B_x(a)$, if we define $\widetilde{\mathrm{R}}^{\text{H}}_y(t) := \mathrm{R}_y(t) \cap (B_x(a) \setminus H)$, \footnote{Here we omit the dependency of $\mathrm{R}_{y}^{i}(t)$ on the particle label since this is true for any random walk starting at $y$. We also omit the dependency on $y$ when it is clear from the context.} then

\vspace{2mm}

\begin{align*}
    \mathbb P_y \left( |\widetilde{\mathrm{R}}^{\text{H}}(a^2)| \geq c_1 \cdot \theta(a) \right) \geq c_0 \, ,
\end{align*}
where $\theta(a)$ is defined as 
\begin{align}
    \theta(a) := \begin{cases}
        a^2 & \text{if } d \geq 3, \\
        a^2 / \log a & \text{if } d = 2.
    \end{cases}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:IndS of arXiv:2411.10333, 'Subcritical annulus crossing in spatial random graphs'] We call the following setup the \emph{independent setting}: 
		Let the underlying point process have independent increments and is thus either given by a Poisson point process, cf.~[LastPenrose2017], or by a Bernoulli site-percolated lattice. Further, for a given collection of mutually different vertex pairs \(\{\boldsymbol{x}_{1_1},\boldsymbol{x}_{1_2}\},\dots,\{\boldsymbol{x}_{k_1},\boldsymbol{x}_{k_2}\}\), we have 
	\begin{equation*}\tag{Ind}
\mathbb{P}_\lambda^{\boldsymbol{x}_{1_1},\boldsymbol{x}_{1_2},\dots,\boldsymbol{x}_{k_2}}\Big(\bigcap_{j=1}^k \{\boldsymbol{x}_{i_1}\sim \boldsymbol{x}_{i_2}\} \, \Big| \, \mathscr{V} \Big) = \prod_{i=1}^k \mathbf{p}(\boldsymbol{x}_{i_1},\boldsymbol{x}_{i_2}), 
	\end{equation*} 
	for a suitable, symmetric function \(\mathbf{p}\). Here, \(\mathbb{P}_\lambda^{\boldsymbol{x}_{1_1},\boldsymbol{x}_{1_2},\dots,\boldsymbol{x}_{k_2}}\) denotes the law where the given points \(\boldsymbol{x}_{1_1},\dots,\boldsymbol{x}_{k_2}\) have been added to the graph in the Poisson point process case, or the law conditioned on the event that said vertices survived the site percolation, respectively.

[Proposition prop:equivalence_nonlinear_mp_weak_sol_den of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] Let $\nu\in\mathcal{P}(\mathbb{R}^d)$, and let $\mathbb{P}_{\nu}$ be a probability measure on $(C_{\infty}, \mathcal{B} )$, such that
\begin{equation}
 \mathbb{P}_{\nu}(x_t \in d y) = v_t(y) dy, 
 \qquad t> 0 ,
\end{equation}
and such that
\begin{equation}
\big[(t,x)\mapsto b\big(t,x,v_t( x)\big) v_t(x)\big], \ \big[ (t,x)\mapsto \sigma \sigma^\top \big(t,x,v_t( x)\big) v_t(x)\big] \in L^{1}_{\text{loc}}([0,\infty)\times\mathbb{R}^d).
\end{equation}

Then $\mathbb{P}_{\nu}$ is a solution to D-NL-MP$(b,\sigma;\nu)$ if and only if there exists a (weak) solution $X$ to D-MKV$(b,\sigma;\nu)$ such that $[X] =\mathbb{P}_{\nu} $. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Dfn 150 (chaotic IAMP, phase I) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Similarly to \eqref{eq:A-ell}, define $\bA^{\aux}=\bG^{\aux}/N^{1/2}$.
Take a large integer $\linit\geq 10(\ubl)$ with 
\beq

0  \ll \frac{1}{\linit} \ll 
1-\upp\ll \eta\ll\delta\ll 
  \frac{1}{L}\ll \epsilon \ll \iota' \ll\iota \ll 1\,.
\eeq
(Again, this should not be confused with Assumption~\ref{a:params}, which only applies to Sections~\ref{s:rerand} and \ref{s:sde}.) Consider the IAMP iterates $(\hat{\by}^{\ell},\hat{\bv}^{\ell})_{-\linit\leq \ell\leq -1}$ defined by
\beq
\begin{aligned}
  \hat{\by}^{\ell+1}&=
  \alpha^{-1/2}
  (\bA^{\aux})^{\top}
    \hat{\bv}^{\ell}
  -\alpha^{1/2}
    \hat{\by}^{\ell}\in\bbR^N,
  \\
  \hat{\bv}^{\ell}
  &=\bA^{\aux}\hat{\by}^{\ell}
  -\alpha^{-1/2}\hat{\bv}^{\ell-1}
  \in\bbR^M\,,
\end{aligned}
\eeq
started from
$\hat{\by}^{-\linit}$ a standard gaussian vector in $\R^N$,
and $\hat{\bv}^{-\linit}=\bzero\in\R^M$. As mentioned above, we also consider another input $\tilde{\bz}$
which is $\upp$-correlated with $\bz$ for some constant $\upp\in (0,1)$. Generate iterates $(\tilde{\by}^{\ell},\tilde{\bv}^{\ell})$ for
$-\linit\leq \ell\leq -1$ using the matrix $\tilde{\bG}^{\aux}$,
started from
  \[\begin{aligned}
  \tilde{\by}^{-\linit} &=\hat{\by}^{-\linit} \in \R^N\,, \\ 
  \tilde{\bv}^{-\linit} &=\bzero\in\R^M\,.\end{aligned}
  \]
\textbf{In particular, the initialization $\tilde{\by}^{-\linit}=\hat{\by}^{-\linit}$ is treated as fixed in the algorithm, meaning it will be part of the random seed $\omega$ (see \eqref{e:iamp.chaotic.omega} below).}

[Lemma lem:Olivier of arXiv:2412.02160, 'A functional central limit theorem for weighted occupancy processes of the Karlin model'] Let $\vv G_n = (G_n(t))_{t\in[0,1]}, n\in{\mathbb N}$ be a sequence of stochastic processes defined on a common probability space with a standard Poisson process $(N(t))_{t\ge 0}$, satisfying the following two conditions.
\begin{enumerate}[(i)]
\item For some $p>1/\alpha$ we have
\begin{equation}
{\mathbb E} \abs{G_n(t)-G_n(s)}^{2p}\le C\pp{|t-s|^{\alpha p}\sigma_n^{2p} + |t-s|^\alpha \sigma_n^2}, \quad \mbox{ for all } s,t\in[0,1], n\in{\mathbb N}.
\end{equation}
\item There exists a constant $C_0>0$ such that almost surely,
\begin{equation}
\abs{G_n(t)-G_n(s)}\le C_0\pp{N(nt)-N(ns)+n(t-s)}, \quad\mbox{ for all } 0\le s\le t\le1.
\end{equation}
\end{enumerate}
Then,
\[
\lim_{\delta\downarrow 0}\limsup_{n\to\infty}\mathbb P\pp{\sup_{\substack{s,t\in[0,1]\\
|t-s|\le \delta}}|G_n(t)-G_n(s)|\ge 9\eta\sigma_n}   = 0 \mbox{ for all } \eta>0.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

