[Lemma 25 (minorisation on interior) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] \label[lemma]{lem:scheme-density}
  Let $I,[a,b]\subset(0,\infty)$ be compact and let $T_\star>0$; assume \eqref{eq:nonconvex-hyp}. There
  are thresholds $\theta,T_0>0$, depending only on $\delta,\lambda,\beta$ and the position of
  $I\cup[a,b]$, such that if
  \begin{equation}
    \operatorname{diam}(I\cup[a,b])\ \le\ \theta
    \qquad\text{and}\qquad
    T_\star\ \le\ T_0 ,
  \end{equation}
  then there exist $c_\star,h_2>0$ with
  \begin{equation}
    K_h^{m}(x',\cdot)\ \ge\ c_\star\,\mathrm{Leb}|_{[a,b]},
    \qquad\text{ for $x'\in I,\ \ h\le h_2,\ \ |m-T_\star/h|\le1$.}
  \end{equation}

[Theorem 10 (Structure of the continuation region) of arXiv:2608.12291, 'When should one stop the most exciting game?\\ {\tiny Sequential Inference for win-marting'] There exists a lower semicontinuous boundary $b_T:[0,T)\to(1/2,1)$
such that
\begin{equation}
    \mathcal{C}_T
    =
    \{(t,x)\in\mathcal{S}_T:1-b_T(t)<x<b_T(t)\}.
\end{equation}
The first hitting time in \eqref{eq:definition_optimal_stopping_time} is given by
\begin{equation*}
    \tau^*_T(t,x)=\inf\{0\le u<T-t:X_u^x\not\in(1-b_T(t+u), b_T(t+u))\}\wedge(T-t)
\end{equation*}
and is an optimal stopping time for \eqref{eq:OSP_T} if $T<\infty$ and \eqref{eq:inf_horizon_osp} if $T=\infty$. 
Furthermore,
\begin{equation*}
    \gamma(t)<b_T(t)<1,\qquad t<T.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

