body:
[Theorem 5 of arXiv:2607.13273, 'Asymptotics of transition densities for L\'evy processes with stochastic resetting'] Let $\alpha\in (0,2)$ and $Y_t$ be an isotropic $\alpha$--stable process in $\Rd$, i.e., 
    \[
        \mE e^{i \langle\xi,Y_t\rangle } = e^{-t|\xi|^\alpha}, \quad \xi\in\Rd, t>0.
    \]
    Then the corresponding process with resetting $X_t$ for all $\lambda>0, x\in\Rd, t>0$ has a density $p_\lambda(t,x,y)$
    such that
    \begin{equation}
    p_\lambda(t,x,y)\sim\frac{\mathcal{A}_{d,\alpha}}{\lambda}|y|^{-(d+\alpha)},
	\end{equation}
    where
    \begin{equation}
		\mathcal{A}_{d,\alpha}=\alpha2^{\alpha-1}\pi^{-d/2-1}\sin\left(\frac{\alpha\pi}{2}\right)\Gamma\left(\frac{\alpha}{2}\right)\Gamma\left(\frac{\alpha+d}{2}\right).
    \end{equation}

[Definition 25 of arXiv:2601.16377, '2601.16377'] We introduce a further decomposition of holomorphic functions in $\amsmathbb{M}_h$
\begin{equation}

\Phi_h^{\pm}(z) = \phi_h^{\pm}(z) + \frac{\phi_{h}^{\pm,[1]}(z)}{\N} + \frac{\phi_h^{\pm,[2]}(z)}{\N^2} + \frac{\mathbbm{f}_h^{\pm}(z)}{\N^3}.
\end{equation}
where
\begin{equation}

\begin{split}
\phi_h^{+,[1]}(z) & =  \frac{\phi_h^+(z)}{\hat{b}'_h - z} \cdot \bigg(\sum_{j = 1}^{\iota_h^+} \big(\rho_{h,j}^+ - \theta_{h,h}\big)\bigg), \\
 \phi_h^{-,[1]}(z) & =  \frac{\phi_h^-(z)}{z - \hat{a}_h'} \cdot  \bigg(\sum_{j = 1}^{\iota_h^-} \big(\rho_{h,j}^- - \theta_{h,h}\big)\bigg), \\
\phi_h^{+,[2]}(z) & = \phi_h^{+}(z) \cdot \Bigg[-\frac{\partial_z^3 U_h(z)}{12} + \frac{1}{(\hat{b}'_h - z)^2} \cdot \bigg( \sum_{1 \leq j_1 < j_2 < \iota_h^+} (\rho_{h,j_1}^{+} - \theta_{h,h})(\rho_{h,j_2}^+ - \theta_{h,h})\bigg)\Bigg], \\
\phi_h^{-,[2]}(z) & = \frac{\phi_h^-(z)}{(z - \hat{a}_h')^2} \cdot \bigg(\sum_{1 \leq j_1 < j_2 \leq \iota_h^-} (\rho_{h,j_1}^{-} - \theta_{h,h})(\rho_{h,j_2}^- - \theta_{h,h})\bigg),
\end{split}
\end{equation}
and the error $\mathbbm{f}_h^{\pm}(z)$ is defined to make \eqref{Phifinerdec} holds.

