[Corollary 10 of arXiv:2506.11918, 'Central limit theorems for the Euler characteristic in the Random Connection Model for hig'] Let $(W_n)$ be a sequence in $\Bf$ with $|W_n| \rightarrow \infty$ as $n \rightarrow \infty$.
Assume there is a $p>0$ such that
\begin{align*}
\varphi_j \geq p \qquad \text{for all } j\in \{1,\dots,\alpha\}.
\end{align*}
Then the convergence
\begin{align*}
\frac{\chi_a\big(\Delta_{W_n}\big)-\E{ \chi_a\big(\Delta_{W_n}\big) }}{\sqrt{\V{ \chi_a\big(\Delta_{W_n}\big) }}} \;\xrightarrow{d}\; \mathcal{N}(0,1) \qquad \text{for } n \rightarrow \infty
\end{align*}
holds with the same rates of convergence of the quantities from Theorem \ref{Th:myRCM} as in Theorem \ref{Th:ZGWS1} (when replacing the intensity $\beta$ with $|W_n|$).

[Lemma lem: sub-exponential Lp norm of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] \textnormal{(Subexponential from MGF to $L^p$ bound) }For sub-exponential random variable $X \sim SE(\beta, \alpha)$, defined by the condition:
    \begin{align*}
        \mathbb{E}[e^{\theta|X|}]  \leq A\cdot e^{\beta^2 \theta^2/2}, \quad \forall \theta \in [0,1/\alpha]
    \end{align*}
    We have upper bound for $L^p$ norm, $\forall p \geq 1$, in terms of $\beta$ and $\alpha$.
    \begin{align*}
        \mathbb{E}[|X|^p] &\leq 2e\sqrt{2\beta}A^{1/p} \cdot \bigg( \beta \sqrt{p} + \alpha p \bigg)
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 8 of arXiv:2608.21551, '\bf Sparse Separable Factor Analysis in the Complex Domain with an Application to Local Fi'] Let $\Psib_1,\ldots,\Psib_d$ be diagonal matrices with positive diagonal entries. There exists a unique vector $(c_1,\ldots,c_d)$ satisfying $c_j>0$, $j=1,\ldots,d$, and $\prod_{j=1}^d c_j=1$ such that
\begin{align}
  \min\left\{\diag(c_1\Psib_1)\right\}
  =
  \cdots
  =
  \min\left\{\diag(c_d\Psib_d)\right\}.

\end{align}
The unique rescaling constants are
\begin{align}
  c_j
  &=
  \frac{\overline{\psi}_{\min}}{\psi_{j,\min}},
  \qquad
  \psi_{j,\min}
  =
  \min\left\{\diag(\Psib_j)\right\},
  \qquad
  \overline{\psi}_{\min}
  =
  \left(
    \prod_{\ell=1}^d\psi_{\ell,\min}
  \right)^{1/d}.

\end{align}
The tuple $(c_1\Psib_1,\ldots,c_d\Psib_d)$ is the unique admissible rescaling satisfying \eqref{eq:min-diag}.

