body:
[Theorem 4 of arXiv:2606.07096, 'Non-Selection of Lagrangian Trajectories in the Zero-Noise Limit for a Class of Stochastic'] Let $W^\beta$ be an isotropic $\beta$-stable process with $\beta\in (0,2)$, $\kappa>0$ and let $u\in L^\infty([0,1];C^\alpha(\T^d))$ with\footnote{Compared to the majority of the literature on the topic, the notations for $\alpha$ and $\beta$ in~\eqref{eq:condition_stable_SWP} are reversed.}
    \begin{equation}
        \alpha>1-\frac{\beta}{2}.
    \end{equation}
    Then, for any $x\in\T^d$, there exists a strong, pathwise unique solution to the SDE
    \begin{equation}
        X^\kappa_t = x + \int_0^t u(r,X^\kappa_r) \dd r + \kappa W^\beta_t
    \end{equation}
    and the SDE admits a stochastic flow of diffeomorphisms $\{X^\kappa_{s,t}(x,\omega)\}$.
    Furthermore, for any $\mu_0\in\mathcal{M}(\T^d)$, the map
    \begin{equation}
        \mu^\kappa_t:=\E\big[(X^\kappa_{0,t})_\sharp \mu_0\big] \quad\forall\, t\in [0,1]
    \end{equation}
    is the unique solution in $C_w([0,1];\mathcal{M}(\T^d))$ (in the weak sense) to the PDE
    \begin{equation}
        \partial_t \mu^\kappa + \nabla\cdot (u\, \mu^\kappa) = - \kappa^\beta |\nabla|^\beta \mu^\kappa,\quad\mu^\kappa\vert_{t=0}=\mu_0.
    \end{equation}

[Lemma 38 (Support convergence from a uniform lower mass bound) of arXiv:2607.24561, 'Range convergence and sharp one-arm asymptotics\\for the critical percolation cluster in h'] Let $\mu_n,\mu$ be finite Borel measures on $\R^d$ with
$\mu_n\Rightarrow\mu$ weakly and $\mu\neq0$. Suppose:
\begin{enumerate}[label=\textup{(\roman*)},nosep,leftmargin=2.2em]
\item \emph{(Inner-uniform lower mass bound.)} For every $\rho_0>0$ and
every $\delta>0$ there exist $c=c(\rho_0,\delta)>0$ and $n_0$ such that for
all $n\ge n_0$,
\begin{equation}
\mu_n\bigl(\overline B(x,\delta)\bigr)\ \ge\ c(\rho_0,\delta)
\qquad\text{for every }x\in\supp\mu_n\text{ with }|x|\ge\rho_0\,;
\end{equation}
\item \emph{(Uniform boundedness.)} $R_\ast:=\sup_n\sup\{|x|:x\in\supp\mu_n\}<\infty$;
\item \emph{(Anchored core.)} $0\in\supp\mu$.
\end{enumerate}
Then $\supp\mu_n\to\supp\mu$ in the Hausdorff metric on the space
$\mathcal K(\R^d)$ of nonempty compact subsets of $\R^d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma first order mu of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $q\in [0,1)$, $\mathbf{m}\in (-1,1)^N$, and set $\mu:=\frac{1}{N}\sum_{i=1}^N \delta_{m_i}\in\mathcal{P}((-1,1))$. Let $\zeta\in \mathcal{P}([q,1])$ and let $(X_t^{\mu})_{t\in [q,1]}$ be the Auffinger--Chen process with law-matching condition
		\begin{equation}
			\begin{cases}    \mathrm{d} X_t^\mu=\xi''(t)\,\zeta([0,t])\,\partial_x \Phi_\zeta(t,X^\mu_t)\,\mathrm{d} t+\sqrt{\xi''(t)}\, \mathrm{d} B_t,\\
				\mathrm{Law}\bigl(\partial_x\Phi_\zeta(q,X^\mu_q)\bigr)=\mu.
			\end{cases}
		\end{equation}
		Recall $\mathrm{TAP}(\mu,\zeta)$ from (equation def:TAPmuzeta of the paper). The following assertions hold.
		\begin{enumerate}[label=(\roman*)]
			\item The map $\zeta \mapsto \mathrm{TAP}(\mu,\zeta)$ is strictly convex on $\mathcal{P}([q,1])$.
			\item For every finite signed measure $\eta$ on $[q,1]$ with $\eta([q,1])=0$, the Gâteaux derivative of $\mathrm{TAP}(\mu,\cdot)$ at $\zeta$ in the direction $\eta$ is given by 
			\begin{equation}
				D\mathrm{TAP}(\mu,\cdot)(\zeta)[\eta]=\frac{1}{2}\int_q^1 \xi''(s)\Bigl(\mathbb{E}\bigl[(\partial_x\Phi_\zeta(s,X^\mu_s))^2\bigr]-s \Bigr)\,\eta([0,s])\,\mathrm{d} s.
			\end{equation}
			\item For every $s\in [q,1]$, define 
			\begin{equation}
				H^\mu_\zeta(s):=\frac{1}{2}\int_s^1 \xi''(r)\Bigl(\mathbb{E}\bigl[(\partial_x\Phi_\zeta(r,X^\mu_r))^2\bigr]-r\Bigr)\mathrm{d} r,
			\end{equation}
			and extend it to $[0,1]$ by setting
			\begin{equation}
				    \hat{H}_\zeta^\mu(s):=\begin{cases}
					{H}_\zeta^\mu(q) & \text{if $s\in [0,q)$,}\\
					{H}_\zeta^\mu(s) & \text{if $s\in [q,1]$.}
				\end{cases}
			\end{equation}
			Then $\zeta\in \mathcal{P}([q,1])$ is the unique minimizer of $\mathrm{TAP}(\mu,\cdot)$ if and only if for every $\zeta'\in \mathcal{P}([q,1])$,
			\begin{equation*}
				\int_q^1 \hat{H}^\mu_{\zeta}(s)\, \mathrm{d} \zeta'(s) \geq  \int_q^1 \hat{H}^\mu_{\zeta}(s)\, \mathrm{d} \zeta(s).
			\end{equation*}
			Equivalently, $\zeta\in \mathcal{P}([q,1])$ is the unique minimizer of $\mathrm{TAP}(\mu,\cdot)$ if and only if 
			\begin{equation}
				\mathrm{supp}(\zeta)\subset \underset{[0,1]}{\mathrm{arg\,min}}\, \hat{H}_\zeta^\mu.
			\end{equation}
			\item Let $\zeta\in \mathcal{P}([q,1])$ be the unique minimizer of $\mathrm{TAP}(\mu,\cdot)$. Then, for every $q'\in \mathrm{supp}(\zeta)$,
			\begin{equation}
				\mathbb{E}\bigl[(\partial_x\Phi_\zeta(q',X^\mu_{q'}))^2\bigr]=q'.
			\end{equation}
			(For interior points $q'\in (q,1)$ this is a first-order optimality condition; at the boundary $q'=q$ it follows from the law-matching condition~(equation eq:AC mu of the paper), since $\mathbb{E}[(\partial_x\Phi_\zeta(q,X_q^\mu))^2]=\int m^2\,\mathrm{d}\mu(m)=q$.)
			\item Let $\zeta\in \mathcal{P}([q,1])$ be the unique minimizer of $\mathrm{TAP}(\mu,\cdot)$. Then, for every $q'\in \mathrm{supp}(\zeta)$,
			\begin{equation}
				\xi''(q')\,\mathbb{E}\bigl[(\partial_{xx}\Phi_\zeta(q',X^\mu_{q'}))^2\bigr]\leq 1.
			\end{equation}
			\item Let $\zeta\in\mathcal{P}([q,1])$ be the unique minimizer of $\mathrm{TAP}(\mu,\cdot)$. Then
			\begin{equation}
				q\in \mathrm{supp}(\zeta).
			\end{equation}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2606.30349, 'Attenuated Poisson Dirichlet approximations for divisibility configurations'] Let $\pi_n$ be a uniformly random permutation of $\{1,\dots,n\}$ and let
\begin{align*}
L_1^{(n)} \geq L_2^{(n)} \geq \cdots \geq L_{K_n}^{(n)}
\end{align*}
denote the cycle lengths of $\pi_n$ arranged in decreasing order, where
$K_n$ is the number of cycles of $\pi_n$. Define the random measures
\begin{align*}
\mathcal{X}_n
:=
\sum_{k=1}^{K_n}\delta_{L_k^{(n)}/n}.
\end{align*}
Then $\mathcal{X}_n$ converges in law to a Poisson-Dirichlet distribution. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 25 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let Assumptions~\ref{assump-PDE} and \ref{assump-particles} hold, with $\sigma=0$. Let us further assume that $F \in L^\infty([0,T]; H^\gamma_{2}(\T^d\times \R^d))$ for some $\gamma>0$, and that $\langle v\rangle^k \nabla_{v} F \in L^2([0,T];L^2(\T^d\times\R^d))$.
Then there exists $C>0$ depending on $T,k,A,\gamma,d,p,\vartheta^1,\vartheta^2$ as well as on $\lVert \langle v\rangle^{2k} F^\circ \rVert_{L^2_{x,v}}$, $\lVert F \rVert_{L^\infty_{t} H^\gamma_{2}}$, $ \lVert u \rVert_{L^\infty_{t}L^\infty_{x}}$ and $ \lVert \langle v\rangle^k \nabla_{v} F \rVert_{L^2_{t} L^2_{x,v}}$, such that for any $N\in \N^*$,
\begin{equation*}
\rate \leq C \sigma_{N}^\frac{1}{2} .
\end{equation*}

