[Proposition consgSRRWRRT of arXiv:2604.07227, 'Transition probabilities of step-reinforced random walks'] Let $(\mathscr{F}_n)_{n\geq 1}$ and $(X_k)_{k\geq 1}$ be as defined above. Define a random walk $S=(S_n)_{n\in \mathbb{N}}$ on $G$ by $S_0:=e_G$ and 
\begin{equation}

     S_n := X_1\cdot X_{2}\cdots X_{n}, \quad n\geq 1.
\end{equation}
 Then $S$ is a generalized SRRW with reinforcement parameter $\alpha$, step distribution $\mu$ and transformations $(T_n)_{n\geq 2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 45 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$ with $d\neq 6$, there exist $C,C',c,c'>0$ such that for any $N\ge C$, $v,v'\in \widetilde{B}(cN)$ and $w,w'\in \widetilde{B}(10N)\setminus \widetilde{B}(N)$ with $|w-w'|\ge N$, 
 	  \begin{enumerate}


 	\item  When $ |v-v'|\le 1$, for any $D\subset [\widetilde{B}(C'N)]^c$, 
 	\begin{equation}
 		\mathbb{P}^{D}\big( \mathsf{H}_{v',w'}^{v,w}  \big)\asymp |v-v'|^{\frac{3}{2}}N^{-[(\frac{3d}{2}-1)\boxdot (2d-4)]}; 
 	\end{equation}



 	\item When $ |v-v'|\ge 1$, if there exists $n\in [1,c'N]$ such that $v,v'\in \widetilde{B}(10n)\setminus \widetilde{B}(n)$, then for any $D\subset \widetilde{B}(\frac{n}{C'})\cup [\widetilde{B}(C'N)]^c$, 
 	\begin{equation}
 		\mathbb{P}^{D}\big( \mathsf{H}_{v',w'}^{v,w}  \big)\asymp |v-v'|^{(3-\frac{d}{2})\boxdot 0}N^{-[(\frac{3d}{2}-1)\boxdot (2d-4)]}. 
 	\end{equation}


 \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:CMF of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] (Version of the Cameron--Martin Formula) Let $h \in H_0^1~\cap~H^2$. Then, the measure $T_{+h}(\mu^{\beta})$ is absolutely continuous w.r.t.\ $\mu^{\beta}$, and its Radon--Nikodym density is given by
	\begin{equation}
		\frac{dT_{+h}(\mu^{\beta})}{d\mu^{\beta}} = \exp\left( -(h'', \cdot )_{L} - \frac{1}{2} \| h' \|_{L}^2 \right) \eqqcolon \xi.
	\end{equation}

[Lemma of arXiv:2608.30493, ' f McKean-Vlasov Differential Equations:\ {An introduction and a focus on some kinetic m'] Let $
u\in\mathcal{P}(\mathbb{R}^d)$. A probability measure $\mathbb{P}_{
u}$, on $(C_T,\mathcal{B})$, is a solution to NL-MP$({ f b}^*,{ oldsymbol\sigma}^*;
u)$ if and only if it is a solution to NL-MP$(\widetilde{ f b},\widetilde{ oldsymbol\sigma};
u)$ for any $\widetilde{ f b},\widetilde{ oldsymbol\sigma}$ as defined in (equation eq:def_b_sig_dens_gen of the paper).

