[Thm Thm_monotonicity_alpha of arXiv:2606.22183, 'Expected loss of quasi-arithmetic means of exchangeable random variables'] Let $I\subseteq \mathbb{R}$ be a nonempty open interval, $f:I\to\mathbb{R}$ be a continuous and strictly increasing function, and
 $\alpha:(f(I)-f(I))\to\mathbb{R}_+$ be a Borel measurable even function.
Further, let $(\xi_n)_{n\in\mathbb{N}}$ be a sequence of exchangeable random variables with values in $I$, 
 and $L:I\to\mathbb{R}$ be a function such that the function $L\circ f^{-1}: f(I)\to\mathbb{R}$ is strongly $\alpha$-convex and $\operatorname{\mathbb{E}}(\vert L(\xi_1)\vert)<\infty$.
Then the following assertions hold:
 \begin{itemize}
  \item[(i)] For each $n\in\mathbb{N}\setminus\{1\}$, we have that $\operatorname{\mathbb{E}}\big(L\big( \mathscr{A}_n^{f}(\xi_1,\ldots,\xi_n) \big)\big)\in[-\infty,\infty)$ and
 \begin{align}
  \begin{split}
   \operatorname{\mathbb{E}}\big(L\big( \mathscr{A}_n^{f}(\xi_1,\ldots,\xi_n) \big)\big)
   &\leqslant \operatorname{\mathbb{E}}\big(L\big( \mathscr{A}_{n-1}^{f}(\xi_1,\ldots,\xi_{n-1}) \big)\big) \\
   &\phantom{\leqslant\;} - \operatorname{\mathbb{E}}\left( \alpha\left( \frac{1}{n(n-1)}\sum_{i=1}^{n-1} f(\xi_i) - \frac{1}{n}f(\xi_n) \right)\right).
  \end{split}
 \end{align}
 \item[(ii)]
The sequence $\Big(\operatorname{\mathbb{E}}\big(L\big( \mathscr{A}_n^{f}(\xi_1,\ldots,\xi_n) \big)\big)\Big)_{n\in\mathbb{N}}$ is decreasing.
 \item[(iii)] If, in addition, 
            \begin{itemize}
              \item[(1)] $\mathbb{D}^2(f(\xi_1))\in(0,\infty)$,
              \item[(2)] $\operatorname{Cov}(f(\xi_1),f(\xi_2))\leqslant 0$,
              \item[(3)] $\alpha$ is strictly convex,
              \item[(4)] $\operatorname{\mathbb{E}}\left( \alpha\left( \frac{1}{2}(f(\xi_1) - f(\xi_2)) \right)\right)<\infty$,
              \item[(5)] $\operatorname{\mathbb{E}}\big(L\big( \mathscr{A}_n^{f}(\xi_1,\ldots,\xi_n) \big)\big)>-\infty$, $n\in\mathbb{N}$,
            \end{itemize}
            then the sequence $\Big(\operatorname{\mathbb{E}}\big(L\big( \mathscr{A}_n^{f}(\xi_1,\ldots,\xi_n) \big)\big)\Big)_{n\in\mathbb{N}}$ is strictly decreasing.
 \end{itemize}

[Definition 18 of arXiv:2609.00690, 'Boundary behavior and optimal pointwise H\"older exponent of the total local time of $(1+\'] Let $1<\alpha<2$. A $[0,\infty)$-valued Markov process is called a $\alpha$-stable continuous-state branching process ($\alpha$-stable CSBP) with scaling constant $c_0>0$ if it has transition semigroup $(Q_t)_{t\geq 0}$ defined by
	\begin{equation}
		\int_0^\infty e^{-\lambda y}Q_t(x,\d y)=e^{-xu^\lambda(t)}, \quad \lambda\geq 0,x\geq 0,
	\end{equation}
	where $t\mapsto u^\lambda(t)$ is the unique positive solution of 
	\begin{equation}
		\frac{\d u^\lambda(t)}{\d t}=-c_0[u^\lambda(t)]^\alpha,\quad u^\lambda(0)=\lambda.
	\end{equation}

[Theorem 7 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb_{\leq n}$, $f:\cube^n\to [-1,1]$, and $p\in [1,2)$,
\begin{equation}
    \max_{J\subseteq[n]:|J|=k}\left\|\Dop_J f\right\|_{\Leb^p}^{p} \geq C^{\text{\rm\ref{thm:high-order-partial-isoper-Boolean}}}(p)^k\, \frac{\Wop^{\geq k}(f)}{\binom{n}{k}} \left[1+ \frac{1}{2k} \ln\left(\frac{\binom{n}{k}}{\Wop^{\geq k}(f)}\right)\right]^k,
\end{equation}
where $C^{\text{\rm\ref{thm:high-order-partial-isoper-Boolean}}}(p) = \left(1+\frac{1}{\upe(2-p)}\right)^{-1} \gtrsim 2-p$. (Proof in the paper; no proof environment follows the statement in the TeX.)

