[Maintheorem 4 of arXiv:2609.02878, '2609.02878'] Let $\pi: X\rightarrow Y$ be a $\mathbb{P}^1$-bundle between two projective manifolds. Suppose the
limiting cohomology class of  \eqref{eq:ammp-flow-intro} is the pullback of 
 a K\"ahler class on \(Y\) by $\pi$. Then there exit 
 \(0< c< C<\infty\) such that for any $0\leq t <T$ and $q\in Y$, we have 
 \smallskip
\begin{equation}
 \sup_{x\in X}
 (T-t)|\Rm(g(t))|_{g(t)}(x)\le C, 
\end{equation} 

\begin{equation}
 c\sqrt{T-t}
 \le \operatorname{diam}_{(X,g(t))}X_q
 \le \operatorname{diam}_{(X_q,g(t)|_{X_q})}X_q
 \le C\sqrt{T-t},
\end{equation}

where $X_q=\pi^{-1}(q)$ is the fibre of $X$ over $q$, $\operatorname{diam}_{(X,g(t))}X_q$ is the extrinsic diameter by the ambient distance on \(X\) and $\operatorname{diam}_{(X_q,g(t)|_{X_q})}X_q$ is 
 the intrinsic diameter by the induced metric on \(X_q\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 of arXiv:2606.03534, 'Construction and simulation of a path-valued model of dendrite development'] Assume that $\mu_0 \in \mathcal{N}_\mathcal{S}^{\#}$ has the form 
    \begin{align*}
        \mu = \sum_{i} \delta\{s^i\}
    \end{align*}
    for $s^i \in \mathcal{S}$ (meaning $\kappa^i=1$ for all $i$ in \eqref{Eqn: Form of bfivm's}). Then this remains true of $\mu_t$ for all $t\geq0$.

[Lemma 3 of arXiv:2609.01770, 'Support of Dyson Brownian Motion'] For each $1\le j\le M$, the regular edges of $\supp(\mu_s)$ satisfy
\begin{equation} 
  a_j'(s)=-m_s(a_j(s)),
  \qquad
  b_j'(s)=-m_s(b_j(s)).
\end{equation}

[Proposition prop:left-linf of arXiv:2602.07920, 'On the position matrix of single-shelf shuffle and card guessing'] Let $n\ge 2$ and let $i\in \mathcal{E}_n$. Then
\begin{equation}
\|\widetilde\zeta^{(i)}\|_\infty
:= \max_{1\le a\le n}|\widetilde\zeta^{(i)}(a)|
\le \frac{2^i}{i!(n-i)}.
\end{equation}

