[Theorem 1 of arXiv:2606.07096, 'Non-Selection of Lagrangian Trajectories in the Zero-Noise Limit for a Class of Stochastic'] Let $W$ satisfy Assumption~\ref{ass:noise} and $\alpha_W$ be given by~\eqref{eq:noise_regularity_threshold}.
    Then for any $\alpha \in (\alpha_W,1)$ and $\eps \in (0,1)$, there exist a divergence-free drift $u \in C^\alpha ([0,1]\times \T^2;\R^2)$, a set $A_\eps \subset \T^2$ with $|A_\eps| \geq 1 - \eps $, a vanishing sequence $(\kappa_q )_{q}$, and a constant $c_\eps >0$ such that
    \begin{equation}
        \P\left( \liminf_{q\to\infty}  \dist  (X_1^{\kappa_{2q}} (x, \omega) , X_1^{\kappa_{2q+1}} (x, \omega))  \geq c_\eps> 0\ \text{ for Lebesgue a.e } x\in A_\eps\right)=1.
    \end{equation}

    Furthermore, for any fixed $x \in A_\eps$, one can find a subsequence $\{\kappa_{q'}\}_{q'}$ and deterministic points $y,y'$ in $\T^2$ such that
    \begin{equation}
        \P\left(\lim_{q'\to\infty} X_1^{\kappa_{2q'}} (x, \omega)=y\neq y'=\lim_{q'\to\infty} X_1^{\kappa_{2q'+1}} (x, \omega)\right)=1.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Lemma-Marcus-n of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $l\in\mathbb R$, $s\ge0$ and let (Hypo-Qi of the paper) hold. Let $\mathcal Q_{2,n}$ denote the regular approximation of  $\mathcal Q_2$ provided by Lemma (Lemma:Qn of the paper). Consider the following regularized Marcus flow
		\begin{equation}
			\wp_n(r)\triangleq  \wp_n(r,l,f),\quad  \frac{{\rm d}}{{\rm d}r}\wp_n(r)= l\cdot \mathcal Q_{2,n}\wp_n(r),\quad r\in[0,1],  \quad \wp_n(0) = f\in H^s.
		\end{equation}
		Let $C_{2,1} > 0$ and $C_{2,2} > 0$ be the constants introduced in  (Q-n cancel of the paper) of Lemma (Lemma:Qn of the paper). 
		Let $V\in \mathscr{V}$ $($see (equation SCRV of the paper)$)$.
		Define
		\begin{equation}
			V_s^{\wp_n,f}(r,l)\triangleq V(\|\wp_n(r,l, f)\|_{H^s}^2) - V(\left\lVertf\right\rVert_{H^s}^2),\quad r\in[0,1],\quad f\in H^{s}.
		\end{equation}
		Then we have that for $l\in\mathbb R$
		\begin{align}
			\sup_{n\ge1}\Abs{V_s^{\wp_n,f}(r,l)}
			\leq \left({\rm e}^{2C_{2,1}|l|r}-1\right) V(\left\lVertf\right\rVert_{H^s}^2),\quad r\in[0,1],

		\end{align}
		and
		\begin{align}
			\sup_{n\ge1}\left\{V_s^{\wp_n,f}(1,l)-2l\cdot V'(\|f\|^2_{H^s} )\bIP{\mathcal Q_{2,n}f,f}_{H^s}\right\}\leq \frac{C_{2,2}}{2C_{2,1}^2}\left({\rm e}^{2C_{2,1}|l|}-2C_{2,1}|l|-1\right)V(\|f\|^2_{H^s}).

		\end{align}

