[Lemma decomposition_lemma of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] Fix a path $\pi(t,dx)=\rho_t(x)\;dx$ in $ {\mathcal{D}}([0,T],\mathscr{M}_{ac})$. Assume that $ {\rho}$ is continuous in $\Omega_T$, smooth in time and that there exists an $\epsilon>0$ such that $\epsilon\leq  {\rho}_t(x)\leq 1-\epsilon,$  {for all} $(t,x)\in\Omega_T$ and that $I_{[0,T]}(\rho)<\infty$. We have that $I_{[0,T]}(\rho)=I_{[0,T]}^{(1)}(\rho)+I_{[0,T]}^{(2)}(\rho)$ where
    \begin{equation*}
        I_{[0,T]}^{(1)}(\rho)=\frac{1}{4}||\mathfrak{L}_0||^2_{-1,\sigma(\rho)}\quad\quad\text{and}\quad\quad I_{[0,T]}^{(2)}(\rho)=\int_0^T\Phi_t(a_t,b_t)\;dt,
    \end{equation*}
     {where $a_t$ and $b_t$ were introduced in (equation def_a_and_b of the paper).} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lema_q of arXiv:2607.13302, 'Extending an Order-Statistic Characterization of the Exponential Distribution'] Let $F$ be a distribution function that belongs to $ \mathcal{F}$. If for all natural $q$ holds
\begin{equation}
f^{(q)}(0) = (-1)^qf^{q+1}(0),
\end{equation}
then $f(x) = \lambda e^{-\lambda x}$ for some $ \lambda > 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 23 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, let $E_*$ be a regular right edge in the sense of Definition~\ref{def:reg_r_edge}. Then there exist constants $\eps_*>0$ and $c,C>0$ such that
        \begin{align}
                \inf_{\substack{|z-E_*|<\eps_*  \\ \Im z>0}}|z+g(z)|\geq c,
                \qquad
                \sup_{\substack{|z-E_*|<\eps_*  \\ \Im z>0}}\|\Pi(z)\|\leq C. \nonumber
        \end{align}
        Moreover,
        \begin{align}
                \|\Pi(z_1)-\Pi(z_2)\| \leq C|z_1-z_2|^{1/3} \nonumber
        \end{align}
        for all $z_1,z_2\in\C^+$ satisfying $|z_1-E_*|,|z_2-E_*|<\eps_*$. Consequently, $\Pi$ extends uniquely and continuously to $\{z\in\C:|z-E_*|<\eps_*,\ \Im z\geq0\}$.
        In particular,
        \begin{align}
                \Pi(E_*) := \lim_{\eta\downarrow0}\Pi(E_*+\ii\eta) 
        \end{align}
        is well defined and is a real symmetric invertible matrix.

