body:
[Proposition prop:ladder-estimate-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Fix \(q\in(1,2)\) with \(\rho(q)<1\), let
\(0<\beta<\beta_X(q)\), and fix \(\alpha_{\mathrm{gr}}>1\).  Then there exist
constants
\[
    C_{\mathrm{lad}}<\infty,\qquad
    \tau_{\mathrm{lad}}<\infty,\qquad
    n_0\ge1,
\]
depending on \(q,\beta,\alpha_{\mathrm{gr}}\) and on the law of the cascade,
such that, for every \(n\ge n_0\) and every \(0\le k\le n\),
\begin{equation}
    A^{(q,\alpha_{\mathrm{gr}})}_{k,n}
    \le
    C_{\mathrm{lad}} n^{\tau_{\mathrm{lad}}}2^{-q\beta k}.
\end{equation}
In particular,
\begin{equation}
    A^{(q,\alpha_{\mathrm{gr}})}_{n,n}
    \le
    C_{\mathrm{lad}} n^{\tau_{\mathrm{lad}}}2^{-q\beta n}
    \qquad(n\ge n_0).
\end{equation}

[Thm 12 of arXiv:2609.03268, 'Poincare Polynomials of Heavy-Light Hassett Spaces'] The ordered $r$-Bell numbers $b(n,r)$ defined above satisfies the recurrence 
                $$b(n,r) = r^{n-1}+\sum_{i=1}^{n-1} {n\choose i} r^{i-1}b(n-i,r)$$
                for $n\ge 2$; with the initial condition $b(1,r)=1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:master-generating of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] A geodesic Leech labeling satisfies the following identity.
\begin{equation}
  \sum_{r=1}^{N}z^r
  =P_A(z)+P_B(z)+C_B(z)
  +\frac{P_A(z)^2-P_A(z^2)}2-C_A(z).
\end{equation}

[Definition 11 of arXiv:2608.30875, 'A Decomposition Theorem for Topological Semi-small Maps'] Let $X^{n}$ be an $n$-dimensional pseudomanifold with a filtration
   	$X = X_{n} \supseteq X_{n-2} \supseteq \cdots \supseteq X_{0} \supseteq \emptyset$, and set
   	$U_{k} = X - X_{n-k}$ for $k \geq 2$, with inclusion maps $i_{k}:U_{k} \hookrightarrow U_{k+1}$. Let $\mathcal{L}$ be a local system on $X-X_{n-2}$. Deligne's sheaf complex $IC^{\overline{p}}_{X}(\mathcal{L})$ with respect to the perversity $\overline{p}$ is defined as 
   	\begin{align*}
   		IC^{\overline{p}}_{X}(\mathcal{L}) = \tau_{\leq \overline{p}(n)-n} Ri_{n \ast}  \cdots \tau_{\leq \overline{p}(3)-n} Ri_{3\ast}   \tau_{\leq \overline{p}(2)-n} Ri_{2 \ast} \mathcal{L}[n].
   	\end{align*}

[Theorem thm:mainv1 of arXiv:2609.00324, 'Quantitative Stability for Fractional Yamabe minimizers'] Let $\gamma \in (0,1)$ and $(M^n , [\hat{h}])$ be the conformal infinity of an asymptotically hyperbolic manifold $(X^{n+1},g^+ )$ such that $\Lambda_{\gamma} (M,[\hat{h}]) < \Lambda_{\gamma} (\mathbb{S}^n ,[h_{0}])$. Then, there exist constants $C>0$ and $\theta \geq 0$ such that
    \begin{align*}
        I_{\gamma} [w,\hat{h}]  - \Lambda_{\gamma} (M,[\hat{h}]) \geq C d(w,\mathcal{M})^{2+\theta} \quad \forall w \in H^{\gamma}(M,\mathbb{R}_+),
    \end{align*}
    where
    \begin{align*}
        d(w,\mathcal{M}) := \frac{\inf \{\|w-u\|_{H^{\gamma}(M)} : u \in \mathcal{M} \} }{\|w\|_{H^{\gamma}(M)}},
    \end{align*}
    and $\mathcal{M}$ is the set of minimizers of $I_{\gamma}[-,\hat{h}]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 4 of arXiv:2609.03054, 'The classes of bivariate Schur and Herglotz matrix-valued rational functions: realizations'] Let $F\in{\mathbb C}^{n\times n}(z_1,z_2)$ be a rational function. Then the following conditions are equivalent:
\begin{enumerate}[\rm (i)]
\item $F$ has no poles in $\mathbb D^2$, and the matrix $F(z_1,z_2)$ has nonnegative real part for any $z_1,z_2\in\DD$;
\item $F$ admits a realization of the form
\begin{equation}
F(z_1,z_2)= D+ C(z_1P_1+z_2P_2)\big(I - A(z_1P_1+z_2P_2) \big)^{-1}B
\end{equation}
where the block matrix $\matr{A&B\\C&D} \in\Cmats{(k+n)}{(k+n)}$ is such that
\begin{equation}
\matr{
I - A^* A & -A^* B+ C^* \\ -B^*A+ C & D+D^*- B^*B
} \geq 0,
\end{equation}
$P_1,P_2\in \sqmat{k}$ are positive semidefinite and $P_1+P_2=I_k$.
\end{enumerate}
Additionally, if $F\in\mathbb R^{n\times n}(z_1,z_2)$ then the matrices $A,B,C,D,P_1,P_2$ in {\rm (ii)} may be chosen as real matrices.

