[Lemma lem:factorization_H_theta of arXiv:2609.01825, 'On everywhere locally soluble varieties \\ in families over toric bases'] The height $H\colon \mathbb{Z}^{n+\rho}\to\mathbb{R}_{>0}$ factors through
	\begin{equation*}
	\lVert \cdot \rVert\colon \mathbb{Z}^{n+\rho} \to \mathbb{Z}^{\mathcal{D}}_{\ge 0},\ \vec x \mapsto (\lVert x_d \rVert_\infty)_{d\in \mathcal{D}}
	\end{equation*}
	and the coprimality condition $\theta$, detecting (eq:coprimality-toric of the paper), factors through
	\begin{equation*}
		g\colon \mathbb{Z}^{n+\rho} \to \mathbb{Z}^{\mathcal{D}}_{>0},\ \vec x \mapsto (\gcd(\vec x_d))_{d\in \mathcal{D}}.
	\end{equation*}

[Lemma 12 of arXiv:2608.24675, 'Towards Liouville Quantum Gravity on fractals'] Let $|\gamma|<\sqrt{d_H/C_0}$. Then,
	\begin{equation*}
		\int_K\int_K\frac{1}{d(x,y)^{\gamma^2C}}d\mu(y)\,d\mu(x)<\infty.
	\end{equation*}

[Thm P loc dim of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] Almost surely under $\hat{P}_{\bm{\rho}}$, for every $t \in (0,\infty)$,
  \begin{equation}
    \lim_{r\downarrow0}
    \frac{\log\Pi_t(B(x,r))}{\log r}
    =
    d_{\mathrm{cp}},
    \qquad
    \Pi_t\text{-}\mathrm{a.e.}\ x.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thmInveHyperDeter of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] Let $ x_0 \in S\setminus\partial S$ satisfy $\frac{\partial  \sigma(T/2,x_0)}{\partial\nu}<0$, and  $S$ satisfy the outer  paraboloid condition with

\begin{equation}
K <\frac{-\frac{ \partial
\sigma}{\partial\nu}(T/2,x_0)}{4(|\sigma|_{L^\infty(B_\rho(T/2,x_0))}+1)}.
\end{equation}

If $z \in   L_{{\mathbb{F}}}^2 (\Omega; C([0,T];H_{\rm loc}^1(G)))\cap L_{{\mathbb{F}}}^2 (\Omega; C^{1}([0,T];L^2_{\rm loc}(G))) $ is a solution to the equation     (system1 of the paper) satisfying that

\begin{equation}
z=\frac{\partial z}{\partial\nu} = 0 \quad\mbox{ on } (0,T)\times
S,\;\;{\mathbb{P}}\mbox{-}\hbox{\rm a.s.} ,
\end{equation}

then for the neighborhood ${\cal V}$ given in  (def1 of the paper) and some $\varepsilon\in (0,T/2)$,
it holds that

\begin{equation}
z = 0 \quad\mbox{ in } ({\cal V}\cap {\cal D}_{\rho}^+)\times
(\varepsilon,T-\varepsilon),\;\;{\mathbb{P}}\mbox{-}\hbox{\rm a.s.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2609.01346, '2609.01346'] For all sufficiently small $\delta$ and $0<s<s_1(\delta)$,
\begin{equation}
 0<x_\delta(s)\leq x_\delta(s_\delta^+)\longrightarrow0,
 \qquad 0<r_\delta(s)\leq C(n,k).
\end{equation}

[Cor 33 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma \geq 1$, $0 \leq s \leq t \leq T$, $\delta \in [0, \; 1]$ and $n \in \mathbb{N}_+$. It holds
\begin{align*}
	&	\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \frac{\Theta(n) K_n}{  \sqrt{n} } \int_s^t \dd r \sum_{x} \sum_{z=1}^{L_n-1}   [  H ( \tfrac{ \lfloor x+z - r v_n \rfloor }{n}  ) - H ( \tfrac{ \lfloor x - r v_n \rfloor }{n}  )  ] a(z)   \bar{\xi}_x^{\alpha}( \eta_r^n ) \big[ \bar{\xi} _{x+z}^{\beta}( \eta_r^n ) - \bar{\xi} _{x+1}^{\beta}( \eta_r^n ) \big] \Bigg\}^{2} \Bigg] \\
	\leq & \widehat{C}(t-s)^{1+\delta} \Bigg( \frac{\big[ \Theta(n) K_n\big]^{\delta+1} }{n^{2}} + \big[  K_n \big]^2 f_{\delta}(n)   \Bigg),
\end{align*} 
where $f_{\delta}:\mathbb{N}_+ \mapsto \mathbb{R}$ is given by
\begin{align} 
\forall n \in \mathbb{N}_+, \quad f_{\delta}(n):= 
\begin{dcases}
 (L_n/n)^{ 1 - \delta } \big[ \log(L_n) \big]^{2 \delta} , \quad & \gamma  =1, \\
  (L_n/n)^{ (2-\gamma)(1 - \delta) }     n^{2 \delta (\gamma-1) }, \quad & 1 < \gamma  <2, \\
 n^{2 \delta} \big[ \log(L_n) \big]^{1 - \delta} \big[ \log(n) \big]^{-1-\delta}, \quad & \gamma  =2, \\
 n^{2 \delta}, \quad & \gamma > 2. 
\end{dcases}
\end{align}
Furthermore, if $H \in C_c^2(\mathbb{R})$, the role of $\widehat{C}$ is fulfilled by some constant $C(H)$ satisfying \eqref{Cinvshift}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 5.1 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Let $(E,d)$ be a metric space whose induced topological space is Lusin, and let $\mu$ be a $\sigma$-finite Borel measure on $E$ with full support such that, for some constants $C_0>0$ and $\alpha>0$,
\begin{equation}
    \mu(B(x, r))\le C_0 r^\alpha,\quad \forall x\in E, r>0,
\end{equation}
where $B(x,r):=\{y\in E:d(y,x)<r\}$. Consider a Borel right process $X$ on $E$ whose transition function satisfies the absolute continuity condition (AC) with respect to $\mu$. Assume further that its transition density function satisfies the following sub-Gaussian upper bound estimate: 
\begin{equation}
p(t,x,y)\le \frac{C_1}{t^{\alpha/\beta}}\exp\left\{-C_2\left(\frac{d(x,y)}{t^{1/\beta}}\right)^{\beta/(\beta -1)}\right\}, \quad \forall  t>0, \, x,y\in E,
\end{equation}
for some $\beta>1$ and $C_1,C_2>0$. Then, for any $0<\delta<1$, there exists a constant $C_3>0$, depending only on $C_0, C_1, C_2, \alpha, \beta, \delta$ (not on $x$ or $B$), such that  
\begin{equation}
{\mathbb{P}}^x\left[\sigma_{B}\le t\right] \le C_3 \exp\left\{-C_2(1-\delta)\left(\frac{\widetilde d(x, B)}{t^{1/\beta}}\right)^{\beta/(\beta -1)}\right\}, \quad \forall t>0, \, x\in E, B\in \mathscr{B}^n(E),
\end{equation}
where $C_2$ is the same constant as in (equation subGaussianHKUB of the paper) and $\widetilde{d}(x,B)$ is defined as (equation eq:63 of the paper).

[Corollary 5 of arXiv:2512.19517, 'Spiking and Resetting'] For any $t>0$ and any $0<a\le b\le1$, the probability distribution $P^\varepsilon_c( \cdot \, : \, t,a,b)$ over $\mathbb N_0$ converges in law to a Poisson distribution with parameter 
\begin{equation}

\begin{split}
f(0) \, t\,  \lambda_* ( [a,b]) = f(0)\,  t \, \int_a^b \cfrac{dx}{x^2} = f(0) \, t \,  (a^{-1}- b^{-1}) \  . 
\end{split}
\end{equation}
Furthermore, we have that, for any $n\ge 0$, the function
\begin{equation}

\begin{split}
\Phi_n^\varepsilon: r \in[0,\infty) \mapsto \mathbb P ( e_1^\varepsilon \ge r, N^\varepsilon_{(0,r]} ([a,b]) = n) \in [0,1]
\end{split}
\end{equation}
converges uniformly on any compact interval $[0,t]$, $t>0$, as $\varepsilon$ vanishes to 
\begin{equation}

\begin{split}
\Phi_n: r \in [0,\infty) \mapsto e^{-r f(0)} e^{-r \lambda_* ([a,b]} \frac{(r \lambda_* ([a,b]))^n}{n!} \in [0,1] \ .
\end{split}
\end{equation}

[Lemma expansions of arXiv:2603.27906, 'Marked GUE-corners process in doubly periodic dimer models'] Let~$z_k=1+\frac{Z_k}{N^\frac{1}{2}}$,~$k=1,2$, with $|Z_k|< N^{\frac{1}{2}}$ (on the canonical local chart in this text, at a neighbourhood of $q_{\infty}$). Then, as~$N\to \infty$, we have that
\begin{equation} 
\exp(NG(z_k,w_k))= \exp\left(NG(1)+\frac{\sigma^2}{2}Z_k^2+\mathcal{O}\left(\frac{|Z_k|^3}{N^{\frac{1}{2}}}\right)\right),
\end{equation}
\begin{equation} 
w_k^{r_k}=
Z_k^{-\ell r_k} 
N^{\frac{\ell r_k}{2}} 
\left(B+\mathcal{O}\left(\frac{|Z_k|}{N^{\frac{1}{2}}}\right)\right)^{r_k}
=
Z_k^{-\ell r_k} 
N^{\frac{\ell r_k}{2}} 
B^{r_k}\left(1+\mathcal{O}\left(\frac{r_k |Z_k|}{N^{\frac{1}{2}}}\right)\right),
\end{equation}
and
\begin{equation} 
z_i^{\sqrt{N}\mu_k}=\left(1+\frac{Z_k}{ \sqrt{N}}\right)^{\mu_k\sqrt{N}}=\exp\left(\mu_k Z_k+\mathcal{O}\left(\frac{\mu_k |Z_k|^2}{N^{\frac{1}{2}}}\right)\right),
\end{equation}
where $B$ is as in Lemma (lemma:local_action_function of the paper).

