[Theorem annealed cond of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Suppose that $\xi$ has at least two distinct nonzero coefficients $\beta_p^2$ (mixed case). Let $n\ge2$. Let $\bm{u}=(u_1,\ldots,u_{n})$ and $\bm{q}=(q_1,\ldots,q_n)$
		be strictly increasing sequences in $(0,1)$, and let
		$\zeta\in\mathrm{Prefix}_{n+1}(\bm{u};\bm{q})$.
		Using the notation of~(equation def:Par of the paper), define the \emph{prefix free en\-ergy}
		\begin{equation*}
			\mathcal{P}^{(n)}(\bm{u};\bm{q})
			\;:=\;
			\inf_{\zeta'\,\in\,\mathrm{Prefix}_{n+1}(\bm{u};\bm{q})}
			\mathcal{P}\mathrm{arisi}(\zeta'),
		\end{equation*}
		and the \emph{$n$-step complexity functional at level $f$}
		\begin{equation*}
			\mathcal{C}^{(n)}_f(\bm{u};\bm{q})
			\;:=\;
			u_n\,\bigl(\mathcal{P}^{(n)}(\bm{u};\bm{q})-f\bigr).
		\end{equation*}

		We assume:
		\begin{enumerate}
			\item[\emph{(i)}]
			\emph{(Tail optimality)} The infimum $\mathcal{P}^{(n)}(\bm{u};\bm{q})$ is
			attained at $\zeta$.
			\item[\emph{(ii)}]
			\emph{(Stationarity)} $(\bm{u};\bm{q})$ is a critical point of
			$\mathcal{C}^{(n)}_f$.
		\end{enumerate}
		Fix $\varepsilon\in(0,1)$ and fix an ancestor skeleton
		$(\mathbf{m}^{(1)},\ldots,\mathbf{m}^{(n-1)})$
		satisfying the admissibility conditions stated in Section~(section:multiple of the paper)
		(Definitions~(def:susyreplicas of the paper) and~(def:matchlaw of the paper)).

		Let $\mathcal{N}_\varepsilon(f,\zeta,q_n,\mathbf{m}^{(n-1)})$ be the number of critical points
		$\mathbf{m}$ of $F_{\mathrm{TAP},\zeta}$ lying in the orthogonal band of $\mathbf{m}^{(n-1)}$
		(and satisfying $\tfrac1N F_{\mathrm{TAP},\zeta}(\mathbf{m})\in(f-\varepsilon,f+\varepsilon)$). Set
		\begin{equation*}
			\mathrm{Skel}_{n-1}=\left(\nabla F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(1)}),F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(1)}),\ldots,\nabla F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(n-1)}), F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(n-1)})\right).
		\end{equation*}

		Then
		\begin{multline}
			\lim_{\varepsilon\to0}\lim_{N\to\infty}
			\frac{1}{N}\log\mathbb{E}\Bigl[
			\mathcal{N}_\varepsilon(f,\zeta,q_n,\mathbf{m}^{(n-1)})
			\;\Big|\;
			\mathrm{Skel}_{n-1}=(0,N\mathcal{P}\mathrm{arisi}(\zeta),\ldots,0,N\mathcal{P}\mathrm{arisi}(\zeta))
			\Bigr]
			\geq
			\mathcal{C}_f^{(n)}(\bm{u};\bm{q})
			\\=
			\zeta([0,q_n))\,(\mathcal{P}\mathrm{arisi}(\zeta)-f).
		\end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:uniqueness_heat_eq of arXiv:2606.29622, 'Affine Structure of the Brownian Signature'] Let $(\bm{u}_t)_{t \in [0, T]}$ be an It\^o-admissible solution to (equation eq:heat_eq_coef_sig of the paper), with terminal condition $\bm{u}_T = 0\,$. Assume moreover that there exists $g : \mathbb{R}_+ \to \mathbb{R}_+$ with $g(x) = o(e^{c x^{2}})$ as $x \to \infty$ for some $c > 0\,$, such that 
    \begin{equation}
        \sup_{t \in [0, T]}|\bracket{\bm u_t}{\sigW[s]}| \leq g\left(\sup_{0 \leq r \leq s}|W_r|\right)\,, \quad s \in [0\,,T]\,.
    \end{equation}
    Then $\bm{u} \equiv 0$ on $[0\,,T]\,$.

[Theoremletter Thm:Neumayer of arXiv:2609.00324, 'Quantitative Stability for Fractional Yamabe minimizers'] Let $(M,g)$ be a closed Riemannian manifold of dimension $n\geq 3$ that is not conformally equivalent to the round sphere. Then, there exist constants $C>0$ and $\theta\geq 0$, depending on $(M,g)$, such that
    \begin{align*}
        Q(u)-Y(M,[g]) \geq C d(u,\mathcal{M})^{2+\theta} \quad \forall u \in H^1 (M,\mathbb{R}_+ ),
    \end{align*}
    where $d(-,\mathcal{M})$ is a suitable distance to the set of minimizers $\mathcal{M}$. Moreover, there exists an open dense subset $\mathcal{G}$ in the $C^2$ topology on the space of smooth conformal classes of metrics on $M$ such that if $[g]\in \mathcal{G}$ then $\theta = 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

