 \Delta D^{(q)}(\zeta_1,\zeta_2)= \hat{W}_{q_1}\hat{W}_{q_2} \mathcal{F}^{(q,q)}\big(\hat{W}_{q}F^{(q)}(\zeta_1)\,,\,\hat{W}_{q}F^{(q)}(\zeta_2)\big) \cdot \partial_{\zeta_1}F^{(q)}(\zeta_1) \partial_{\zeta_2}F^{(q)}(\zeta_2).
 \end{equation}

[Mainthm 2 of arXiv:2609.02576, 'Sharp estimates for the Jacobi and trigonometric Dunkl heat kernels'] Let $\al\geq\beta\geq -1/2$, $\al>-1/2$. The non-compact Jacobi heat kernel satisfies  the bound
	\begin{multline*}
		\mathcal{H}_t^{\al,\beta}(x,y)\simeq t^{-1/2} e^{-\frac{(x-y)^2}{4t}} e^{-(\al+\beta+1)^2 t} e^{-(\al+\beta+1)(x+y)}\\
		\times (1+x)(1+y) \frac{(t+1+x+y+xy)^{\al-1/2}}{(t+xy)^{\al+1/2}},
	\end{multline*}
	uniformly in $t>0$ and $x,y>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem prop_5 of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] Let $A$ be a symmetric matrix and 
\begin{eqnarray}

\alpha=\|A\|,\,\,\,\beta=\|A\|_2^2,\,\,\,\gamma=\|A\|_3^3.
\end{eqnarray}
Also, let 
\begin{eqnarray}

\eta_1(t)=\frac{1}{12\gamma^2}(\sqrt{\beta^2+4\gamma t}-\beta)(\beta^2+8\gamma t-\beta\sqrt{\beta^2+4\gamma t}\,)
\end{eqnarray}
and
\begin{eqnarray}

\eta_2(t)=\frac{t}{\alpha}-\frac{3\beta }{4\alpha}\min\bigg\{ \frac{1}{\alpha}, \frac{\sqrt{\beta^2+4\gamma t}-\beta}{2\gamma}\bigg\}.
\end{eqnarray}
Then 
\begin{eqnarray}

\Pr(\boldsymbol{\Delta}>t)\leq \exp\big(-\kappa' \min\{\eta_1(t), \eta_2(t)\}\big),
\end{eqnarray}
where $\kappa'=\frac{b^*}{3}\approx 0.187$ with $b^*$ as the unique solution for $b$ in the equation $\frac{4}{\sqrt{3}}b\sqrt{\theta_2(b)}=1$ and~$\theta_2(b)$~as defined in~((theta_func of the paper)).

[Theorem thm:centrality-detailed of arXiv:2606.02472, 'Correlated uniform attachment trees'] Let $T_{n} \sim \mathrm{UA}(n)$ and recall that $A_K:=A_{K}(n)$ denotes the set of the $K$ most central vertices in~$T_{n}$. 
There exists a universal constant $C < \infty$ 
such that 
for every $K\in \N$, $c > 1$, and $\delta \in(0,c-1)$,
the following holds for all large enough $n \geq n_{0}(K,\delta,c)$: 
\[
\mathbb{P} \left( \babs{ A_{\ceil{c K}} (n) \cap \bclc{0,\ldots, K-1 }
}\geq \bclr{c (1-e^{-1/c})-\delta}K \right) 
\geq 1 - C \left(\frac{   c \log(c K) }{\delta ^2 K}+(0.7)^{\delta K/2}\right).
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 138 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Adopt the notation and assumptions of \Cref{cor:cella2}, and denote
  	\begin{flalign}
		\widetilde{\mathcal{H}} (\hat{x}, \hat{y}) = \mathfrak{d}^{-2} \mathcal{H}_{q;a,b,c} (x, y). 
	\end{flalign}
	\noindent Then, we have $\widetilde\cH(\hat{x},\hat{y})=\frak H_{q,\gamma'',\gamma'''}(\hat x,\hat y)+\mathcal O(\md^2)$, where
  {  \begin{multline}
     \frak H_{q,\gamma'',\gamma'''}(\hat x,\hat y)=\mathtt H_{\gamma''}(\hat x,\hat y)        + \frac{\mathfrak d}{\pi\sqrt{\gamma''}}
        \left[
            \left(\frac{\gamma''}{3}-\frac{q}{6}+\frac{2\gamma'''}{9\gamma''}\right) (2\hat{y}-\gamma''\hat{x}^2)^{3/2}
            - \frac{\gamma'''}{3\gamma''} \hat{y}\sqrt{2\hat{y}-\gamma''\hat{x}^2}
        \right],\\
\mathtt H_{\gamma''}(\hat x,\hat y)
        = \displaystyle\frac{\hat{y}}{2}
        - \frac{1}{\pi}\left[
            \frac{\hat{x}}{2}\sqrt{\gamma''}\,\sqrt{2\hat{y}-\gamma''\hat{x}^2}
            + \hat{y}\,\arctan\!\left(\frac{\sqrt{\gamma''} \hat{x}}{\sqrt{2\hat{y}-\gamma''\hat{x}^2}}\right)
        \right].
    \end{multline}
} (Proof in the paper; no proof environment follows the statement in the TeX.)

