[Definition 6 of arXiv:2607.18104, '2607.18104'] Let $\varepsilon>0$. For all $s<t$, consider the set of points
\begin{equation}
    (z_i)_{i\in \lbr k\rbr} := \{ j\varepsilon \in [s,t] \text{ for some } j\in \N \} 
\end{equation} where $k\in \N_0$ is the number of points, and where we set $z_0=s$ and $z_{k+1}=t$, and $z_{i-1} \leq z_{i}$ for all $i\in \lbr k+1 \rbr$. 
    A geodesic $\pi\in \mathfrak{G}_{(x,s),(y,t)}$ with $(x,s;y,t)\in \R^{4}_{\uparrow}$ is $\boldsymbol{\varepsilon}$\textbf{-good} if for all $i\in \lbr k+1 \rbr$
    \begin{equation}
      \sup_{\ell \in [z_{i-1},z_i]}  \big| \pi(\ell) - \pi(z_{i-1}) \big| \leq \frac{1}{32}  . 
    \end{equation}

[Proposition 11 (Master equation for the eigenvectors) of arXiv:2511.12623, 'The eigenvector bead process'] Assume the spectrum $\{\lambda^{(N)}_j\}_{j=1}^N$ is simple.
Let $\lambda^{(N+1)}_i$ be any zero of \eqref{eq:secular}. Then the overlaps satisfy
\begin{subequations}
\begin{align}
\Omega^{(N)}_{i,j}
&= \frac{1}{\sqrt{\bigl|f'(\lambda^{(N+1)}_i)\bigr|}}\,
   \frac{g_j^{(N)}}{\Delta_{i,j}^{(N)}},
\qquad j=1,\dots,N, \\[4pt]
f'(\lambda)
&= -\left( 1 + \sum_{j=1}^N
           \left(\frac{|g_j^{(N)}|}{\lambda-\lambda^{(N)}_j}\right)^{\!2} \right).

\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

