body:
[Definition 10 of arXiv:2609.02197, '2609.02197'] Let $f \in \mathscr{S}'$ and $h:\mathbb{Z}^d\longrightarrow\mathbb{C}$ be a function such that $$\exists \left(\mu,r\right) \in \mathbb{R}_+\times \mathbb{N},\forall x \in \mathbb{Z}^d,\left|h\left(x\right)\right|\leq \mu\left(1+\left|x\right|\right)^r.$$
\begin{enumerate}
\item The Fourier transform of $f$ is given by
\begin{align*}
\mathscr{F}f: \mathbb{Z}^d &\longrightarrow \mathbb{C} \\ 
m & \longmapsto \left(\mathscr{F}f\right)\left(m\right)=f\left(\psi_{m,1}\right)-\mathrm{i}f\left(\psi_{m,2}\right)
\end{align*}
\item The inverse Fourier transform of $h$ is given by
\begin{align*} 
\mathscr{F}^{-1}h: \mathscr{S} &\longrightarrow \mathbb{C} \\ \varphi & \longmapsto \left(\mathscr{F}^{-1}h\right)\left(\varphi\right)=\sum_{n \in \mathbb{Z}^d}h\left(n\right)\int_{\mathbb{T}^d}\varphi\left(x\right)\mathrm{e}^{2\pi \mathrm{i}\left\langle x,n\right\rangle}\,\mathrm{d}x
\end{align*}
\end{enumerate}

[Corollary 104 of arXiv:2601.16377, '2601.16377'] In the setting of Lemma~\ref{Lemma_continuity_varyinf_ff}, there exists $\varepsilon > 0$ depending only on the constants in the assumptions with the following property. If $\boldsymbol{\mu}^{\textnormal{I}}$ satisfies the off-criticality Assumption~\ref{Assumptions_offcrit} and for any $g,h \in [H]$ and $e \in [\mathfrak{e}]$
\begin{equation}

\begin{split}
\max\big(|\hat a_h^{\prime\,\textnormal{I}}-\hat a_h^{\prime\,\textnormal{II}}|\,,\,|\hat b_h^{\prime\,\textnormal{I}}-\hat b_h^{\prime\,\textnormal{II}}|\,,\,|\theta_{g,h}^{\textnormal{I}} - \theta_{g,h}^{\textnormal{II}}|\,,\,|r_e^{\textnormal{I}}-r_e^\textnormal{II}|\big) & \leq \eps, \\
 \int_{\max (\hat a_h^{\prime\,\textnormal{I}},\hat a_h^{\prime\,\textnormal{II}})}^{\min(\hat b_h^{\prime\,\textnormal{I}},\hat b_h^{\prime\,\textnormal{II}})} \big|V_h^{\textnormal{I}}(x)-V_h^\textnormal{II}(x)\big| \dd x & \leq \eps, \\
\sup_{z\in \amsmathbb{M}_h} \big|\phi^{\pm,\textnormal{I}}_h(z)-\phi^{\pm,\textnormal{II}}_h(z)\big| & \leq \eps,
\end{split}
\end{equation}
then $\boldsymbol{\mu}^{\textnormal{II}}$ also satisfies the off-criticality Assumption~\ref{Assumptions_offcrit}.

[Lemma estimates for discretized coefficients of arXiv:2411.05924, 'Non-negative Martingale Solutions to the Stochastic Porous Medium Equation with Sticky Beh'] For $n\in\mathbb N$, $\mathbf u_n\in \mathbb R^n$, $\theta\in[0,1]$, and $\mu \geq 1$ we have
    \begin{align}

        \left\|\mathbf u_n^{\mu} \odot \mathbf B_n(\mathbf u_n) \Pi_n \right\|_{L_2(U_0, \mathbf H^\theta_n)}^2 &\lesssim \left\|\mathbf u_n^\mu\right\|_{\mathbf H^\theta_n}^2 + \left\|\mathbf u_n^{\mu+1}\right\|_{\mathbf H^\theta_n}^2, \\

        \left\|\mathbf u_n^{\mu} \odot \boldsymbol\Sigma_n (\mathbf u_n)\right\|_{\mathbf H^{\theta}_n}^2 &\lesssim \left\|\mathbf u_n^\mu\right\|_{\mathbf H^{\theta}_n}^2 + \left\|\mathbf u_n^{\mu+2}\right\|_{\mathbf H^{\theta}_n}^2, \\

        \left\|\mathbf r_n(\mathbf u_n)\right\|^2_{\mathbf H^0_n} &\lesssim \|\mathbf u_n\|^2_{\mathbf H^0_n}.
    \end{align}

