[Theorem 1 of arXiv:2608.01419, 'A model of opinion dynamics evolving via a preferential attachment mechanism involving mul'] For the model described in \S\ref{subsec:model_fixed_sample_size}, the sequence $\{(n^{-1}A_{n},n^{-1}B_{n},n^{-1}C_{n})\}$ converges almost surely to a compact, connected, internally chain transitive invariant set, contained in $\mathcal{S}$, corresponding to the autonomous ODE
\begin{equation}
\left(\dot{a}(t),\dot{b}(t),\dot{c}(t)\right)=h\left(a(t),b(t),c(t)\right) \text{ for }t\geqslant 0, \text{ with } (a(0),b(0),c(0))=(A_{N}/N,0,0),
\end{equation}
where the function $h$ is as defined in \eqref{h_defn_fixed_size}, and $A_{N}$ is as defined via \eqref{A_{n}_defn}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 47 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Suppose that $f \in \cB_{p,q}^{\alpha - \beta}$ where $\alpha \in \mbR$ and $p,q \in [1,\infty]$. Then given a $\beta$-regularising kernel $K$ in the sense of \cite[Assumption 5.1]{H0}, we have that \begin{align*}
		\| 2^{n \alpha} & \| \sup_{\psi \in \mcB_{\bar{\alpha}}^r} \langle K \ast f, \psi_y^n \rangle \|_{L^p(\mfK; dz')} \|_{\ell^q(n)} + \| \sup_{\psi \in \mcB^r} \langle K \ast f, \psi_y \rangle \|_{L^p(\mfK ; dy)}
		\\ 
		\lesssim& 	\| 2^{n (\alpha - \beta)} \| \sup_{\psi \in \mcB_{\bar{\alpha} - \beta}^r} \langle f, \psi_y^n \rangle \|_{L^p(\bar{\mfK}; dy)} \|_{\ell^q(n)} + \| \sup_{\psi \in \mcB^r} \langle f, \psi_y \rangle \|_{L^p(\bar{\mfK} ; dy)}
	\end{align*}
	for each $\bar{\alpha} > \alpha$ where $\mcB_\alpha^r$ denotes the set of elements of $\mcB^r$ that annihilate polynomials of degree less than $\alpha$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2606.15843, 'Long-time behaviour of DLRA for SDEs'] Suppose Assumptions (H3), (H7) and (H8) hold.
			Moreover, suppose  Assumption~\ref{AS:relation2} holds. Furthermore, suppose the initial condition $(\zeta,\xi)\in L^p(\Omega,V_r(\bb R^d)\times\bb R^r)$. Then, there exists a constant $C(b,\sigma,p)>0$, one has
             \begin{align}
                \bb E[\|U_t^{(\mu)}\|_{\rrm {HS}}^p]=r^\frac{p}{2},
            \end{align}
             and
			\begin{align}
				\bb E[|Y_t^{(\mu)}|^p]\le \rrm e^{-\lambda \frac{p}{2}t}\bb E[|\xi|^p]+\frac{2C(b,\sigma,p)}{\lambda p},
			\end{align}   
            where $\lambda=2L_{b,7}-2(p-1)L_{\sigma,1}-\frac{2}{p}$.

