[Corollary 132 of arXiv:2601.16377, '2601.16377'] Assume in the setting of Theorem~\ref{Theorem_correlators_expansion} that we have $\theta_{g,g} = 1$ for every $g \in [H]$. Let $h \in [H]$ and set
\begin{equation}

\hat{W}_{1;h}^{[2]}(z) = \Op_{h}\Bigg[\bigg(\frac{1}{s_g^{\circ}}\Big\{\hat{q}^{+,[2]}_{g} + \frac{q_g^+}{2} \big\langle \bth_g^{\otimes 2}\cdot \boldsymbol{\mathcal{F}}_{\bullet,\bullet}(*,*) \big\rangle \Big\}\bigg)_{g = 1}^{H}\,;\,\boldsymbol{0}\bigg],
\end{equation}
where
\begin{equation}

\hat{q}_{h}^{+,[2]}(z) = \frac{q_h^-(z)}{24} \big\langle \bth_h(4\bth_h^2 - 6\bth_h + 3) \cdot \partial_z^2 \mathcal{G}_{\boldsymbol{\mu}}(z)\big\rangle -   \frac{\partial_z^3 U_h(z)}{12} \cdot \phi_h^{+}(z) \cdot e^{\langle \bth_h \cdot \mathcal{G}_{\boldsymbol{\mu}}(z)\rangle}.
\end{equation}
Then, \eqref{eq_x30} and \eqref{eq_x31} can be replaced with
\[
\big|W_{1;h}(z) - \N^{-1}\hat{W}_{1;h}^{[2]}(z)\big| \leq C_1 \N^{-\frac{3}{2} + \varepsilon}, \qquad \big|\hat{W}_{1;h}^{[2]}(z)\big| \leq C_1.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 8 of arXiv:2608.02103, '$p$-Adic Diffusion and Random Walks on $[0,1]$'] The assignment     \begin{equation}
        C[0,1]\ni u(x) \mapsto
            \mathcal{W} u(x) = \int_0^1 w(x,y)( u(y) - u(x))\mathop{dy}
    \end{equation}
    is a well defined linear bounded operator on $C[0,1]$.

[Lemma lem:mainBound of arXiv:2608.13452, 'Wasserstein stability of the zero cell of a Poisson hyperplane tessellation under directio'] Fix \(\gamma>0\), let \(\phi_1,\phi_2\) be nondegenerate even probability measures on $S^{d-1}$, and define stationary Poisson hyperplane processes \(\Psi_1,\Psi_2\) with common intensity \(\gamma\) and directional distributions \(\phi_1,\phi_2\), respectively.
    Let $Z_0(\Psi_1)$ and $Z_0(\Psi_2)$ be the zero cells of \(\Psi_1\) and \(\Psi_2\).
    Then, for $p \in [1, \infty)$,
    \begin{align*}
        W_{\rho_p}\bigl(Z_0(\Psi_1),Z_0(\Psi_2) \bigr) 
        \leq \frac{K_p(\phi_1,\phi_2)}{\gamma} W_{\mathrm{geo}}(\phi_1,\phi_2)^{\frac{1}{p}}, 
    \end{align*} 
    and    
    \begin{align*}
        W_{\Delta}(Z_0(\Psi_1),Z_0(\Psi_2)) 
        \leq \frac{K_\Delta(\phi_1,\phi_2)}{\gamma^d} W_{\mathrm{geo}}(\phi_1, \phi_2)^{\frac{1}{d}},
    \end{align*}
    where

\begin{align} 

        K_p(\phi_1,\phi_2)
        &:= \left(\Gamma(p+1)
        \int_{S^{d-1}} \frac{h(\Pi_1,u)^p + h(\Pi_2,u)^p}{(h(\Pi_1,u) + h(\Pi_2,u)) h(\Pi_1,u)^p h(\Pi_2,u)^p} \sigma(\mathop{}\!\mathrm{d} u) \right)^{\frac{1}{p}}
    \end{align}
    and
    \begin{align}

        K_{\Delta} (\phi_1,\phi_2)
        &:= \frac{K_d (\phi_1,\phi_2)}{2^{d-1}}\left(d!\int_{S^{d-1}}
             h(\Pi_1,u)^{-d} + h(\Pi_2,u)^{-d} \sigma(\mathrm{d}u) \right)^{\frac{d-1}{d}},
    \end{align}
    where $K_d (\phi_1,\phi_2)$ is the constant (equation def:Kp of the paper) for $p = d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition eq:finite-N-hard-slice-assumption of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[proposition]{prop:finite-N-dereg}
Fix \(N\), let \(n=N-1\), and let \(V\) be Borel measurable and bounded
below.  For almost every \(O\in\mathcal O_{N,L}\), suppose that \(g_J(O)\)
has a density \(p_O(g)\) on \(\mathbb R^n\) and that
\((h_J(O),A_J(O))\), conditionally on \(g_J(O)=g\), admits a jointly
measurable regular conditional kernel \(K_O(g,\,\mathrm d h\,\,\mathrm d A)\).  Assume
that versions at \(g=0\) have been fixed for which the hard-slice identity
\begin{equation}
 \mathscr C_{N,L}^J(V)
 =\omega_N\int_{\mathcal O_{N,L}}p_O(0)
   \int_{\mathbb R\times\operatorname{Sym}_n}
   e^{-NV(h)}\left\lvert\det A\right\rvert\,
   K_O(0,\,\mathrm d h\,\,\mathrm d A)\nu_N(\,\mathrm d O)
\end{equation}
holds.
For \(0<\eta\le1\) and \(R\ge1\), put
\[
 \Psi_{O,\eta,R}(g)
 =p_O(g)\int_{\mathbb R\times\operatorname{Sym}_n}
 e^{-NV(h)+\operatorname{Tr} f_{\eta,R}(A)}
 K_O(g,\,\mathrm d h\,\,\mathrm d A).
\]
Assume that \(g\mapsto\Psi_{O,\eta,R}(g)\) is bounded and continuous at zero for almost every \(O\), that
\[
 \int_{\mathcal O_{N,L}}\norm{\Psi_{O,\eta,R}}_\infty\nu_N(\,\mathrm d O)<\infty,
\]
and that
\begin{equation}
 \int_{\mathcal O_{N,L}}\int_{\mathbb R\times\operatorname{Sym}_n}
 e^{-NV(h)}(1+\left\lVertA\right\rVert_{\mathrm{op}})^n p_O(0)
 K_O(0,\,\mathrm d h\,\,\mathrm d A)\nu_N(\,\mathrm d O)<\infty.
\end{equation}
Then
\begin{equation}
 \lim_{R\to\infty}\lim_{\eta\downarrow0}\lim_{\varepsilon\downarrow0}
 \mathbb E\mathcal Z_{N,L}^J(V,\varepsilon,f_{\eta,R})
 =\mathscr C_{N,L}^J(V).
\end{equation}

[Lem 5. lem: convergence of atoms and weights of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] Fix $k \in \mathbb{N}$,
  $\bm{x}_{n} = (x_{1}^{(n)}, \dots, x_{k}^{(n)}) \in F_{n}^{k}$ for each $n$,
  and $\bm{x} = (x_{1}, \dots, x_{k}) \in F^{k}$.
  If $x_{i}^{(n)} \to x_{i}$ in $M$ and $ \nu_{n}(\{x_{i}^{(n)}\}) \to \nu(\{x_{i}\})$ for each $i$,
  then 
  \begin{equation}
    P_{\rho_{n}}^{\nu_{n}}
    \bigl( X_{n}^{\nu_{n}}(t_{1}) = x_{1}^{(n)},\dots, X_{n}^{\nu_{n}}(t_{k}) = x_{k}^{(n)} \bigr) 
    \to
    P_{\rho}
    \bigl( X^{\nu}(t_{1}) = x_{1},\dots, X^{\nu}(t_{k}) = x_{k} \bigr)
  \end{equation}
  for any $t_{1}, \dots, t_{k} \in (0, \infty)$.

