[Definition def:Dtilde of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] For $B \in \mathscr{B}_0$, let $$\widetilde{D}_0(B) = \mathbf 1\Big\{\bigcup_{v\in B} Q(v) = -1\Big\}\,.$$ Now suppose we have defined $(\widetilde{D}_{k-1}(B'))_{B'\in \mathscr{B}_{k-1}}$; for each $B\in \mathscr{B}_k$, we will describe how to assign $\widetilde{D}_k(B)$.  Define 
    \begin{align}
        \mathsf{Dis}_{k-1}(B) & = \{B' \in \mathscr{B}_{k-1}: B' \subset E_{+2}(B)\,,\,\widetilde D_{k-1}(B') = 1\} \,, \\ 
        \mathsf{Bad_{k-1}}(B)& = \{B' \in \mathscr{B}_{k-1}: B' \subset E_{+3}(B)\,,\, \mathsf{StatEquiv}_{k-1}(B')^c \text{ or } \mathsf{InfProp}_{k-1}(B')^c \text{ hold}\}\,. 
    \end{align}
    ($\mathsf{Dis}_{k-1}$ is roughly the set of blocks one scale down that were $1$ in the dominating set, and $\mathsf{Bad}_{k-1}$ are those one scale down that had very atypical events happen for them.) 
    We then set 
    \begin{align*}
        \widetilde{D}_k(B) = 1 - \mathbf 1\{|\mathsf{Dis}_{k-1}(B)| \le s_k\,,\, \mathsf{Bad}_{k-1}(B) =\emptyset\,,\, \mathsf{InfProp}_k(B), \mathsf{LocCoup}_k(B)\}\,.
    \end{align*}

[Prop p:300.2 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Fix $u \geq 0$. For all $k \geq 0$, there exists a bounded function $\varphi^{k}_u :
\mathbb{R}^{{\rm Q}(k)} \to \mathbb{R}_+$ such that, for any measurable positive function $f: {\rm D} \to \mathbb{R}_+$ with compact support,

\begin{equation}

\begin{split}
\lim_{n \to \infty}
\bigg|\mathbb{E} \bigg( \xi_n \exp \bigg\{ -\int f(x) & \big({\bf \Xi}_{n,u}^k \cap {\bf \Gamma}_{n,u}\big)
({\rm d} x)\bigg\} \bigg) \\
& - \mathbb{E} \bigg( \xi_n \exp \bigg\{-\frac{1}{\sqrt{n}} \int \varphi^k_u(\omega) \big(1-{\rm e}^{-f(x)}\big){\bf \Lambda}_{n,u}^{k}({\rm d} x \times {\rm d} \omega)
  \bigg\}\bigg) \bigg| = 0 \,,
\end{split}
\end{equation}
uniformly over all $cF_{t^A_n}$-measurable random variables $\xi_n$ with ${\rm L}^\infty$-norm at most $1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Def 1 of arXiv:2604.24189, 'Malliavin calculus and densities for chaos-driven stochastic differential equations'] An $\R^m$-valued stochastic process $\{F_t\}_{t \geq 0}$ is called a \emph{chaotic process} (over the abstract Wiener space $(\Omega,\mathcal{F},\P,\mathfrak{H})$) if there exists $q \in \N$ such that, for every $t \geq 0$ and every $1 \leq \ell \leq m$, one can find $f_t^\ell \in \mathfrak{H}^{\odot  q}$ satisfying
\begin{equation}
F_t=(I_q(f_t^1),\dots,I_q(f_t^m)).
\end{equation}

[Definition 1 of arXiv:2605.20026, 'Quasihelix properties\\ of selected Volterra Gaussian processes'] A Gaussian process $G=\{G_t,\ t\ge0\}$ is called
\begin{itemize}
    \item[$(i)$] a \emph{$\rho$-quasihelix} if there exist $\rho>0$ and constants $C_1,C_2>0$ such that, for all $t,s\in[0,\infty)$,
    \begin{equation*}
        C_1|t-s|^{\rho}
        \le
        \|G_t-G_s\|_2
        \le
        C_2|t-s|^{\rho};
    \end{equation*}

    \item[$(ii)$] a \emph{local $(\rho,T_1,T_2)$-quasihelix} on the interval $[T_1,T_2]$ if there exist $\rho>0$ and constants $C_1(T_1,T_2),C_2(T_1,T_2)>0$ such that, for all $t,s\in[T_1,T_2]$,
    \begin{equation}
        C_1(T_1,T_2)|t-s|^{\rho}
        \le
        \|G_t-G_s\|_2
        \le
        C_2(T_1,T_2)|t-s|^{\rho};
    \end{equation}

    \item[$(iii)$] a \emph{local $(\rho_1,\rho_2,T_1,T_2)$-generalized quasihelix} on the interval $[T_1,T_2]$ if there exist $\rho_1,\rho_2>0$ and constants $C_1(T_1,T_2),C_2(T_1,T_2)>0$ such that, for all $t,s\in[T_1,T_2]$,
    \begin{equation}
        C_1(T_1,T_2)|t-s|^{\rho_1}
        \le
        \|G_t-G_s\|_2
        \le
        C_2(T_1,T_2)|t-s|^{\rho_2}.
    \end{equation}
\end{itemize}

[Lem 22 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma >0$, $0 \leq s \leq t \leq T$ and $n \in \mathbb{N}_+$. Then
	\begin{align} 
	&	\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \frac{\Theta(n) K_n}{\sqrt{n}} \int_s^t \dd r \sum_x \sum_{y=x+L_n}^{
	x+n-1}  [  H ( \tfrac{y - r v_n }{n}  ) - H ( \tfrac{x - r v_n }{n}  )  ] a(y-x)   \bar{\xi} _x^{\alpha}( \eta_r^n ) \bar{\xi} _y^{\beta}( \eta_r^n ) \Bigg\}^{2} \Bigg] \nonumber \\
		\leq  & \widehat{C} (t-s)^{2} \Bigg\{ \frac{  \big[ \Theta(n) K_n \big]^{2}  }{ n^{4}  } \mathbbm{1}_{ \{ \gamma \geq 1 \} } + \frac{ [ \Theta(n) K_n  ]^{2} }{n^{2}} \sum_{x=L_n}^{n} x^{- 2 \gamma} \Bigg\}. 
	\end{align}
	Furthermore, if $H \in C_c^2(\mathbb{R})$, the role of $\widehat{C}$ is fulfilled by some constant $C(H)$ satisfying \eqref{Cinvshift}.

