[Proposition 31 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] Let \(Z_n^{\mathrm{grid}}\) and \(\widehat{\PP}_n^{\mathrm{grid}}\) be given by
\begin{equation}
  Z_n^{\mathrm{grid}}:=\EE e^{-a_n^HM_n^*},
  \qquad
  \frac{\mathrm d\widehat{\PP}_n^{\mathrm{grid}}}{\mathrm d\PP}
  :=\frac{e^{-a_n^HM_n^*}}{Z_n^{\mathrm{grid}}}.

\end{equation}
Then the global normaliser and component weights satisfy
\begin{equation}
  Z_n^{\mathrm{grid}}
  =\sum_{k=0}^{m_n}p_{n,k}z_{n,k},
  \qquad
  q_{n,k}:=\frac{p_{n,k}z_{n,k}}{Z_n^{\mathrm{grid}}},

\end{equation}
and \((q_{n,k})_{0\leq k\leq m_n}\) is a probability vector.  Set
\begin{equation}
  Y_n^{\mathrm{grid}}
  :=\mathscr M_{L_{n,K_n}^-,L_{n,K_n}^+}
      (\Xi_n^{\mathrm{grid}})
  =\bigl(a_n\tau_n,a_n^HM_n^*,
      \overline L_n^{\mathrm{grid}},
      \overline R_n^{\mathrm{grid}}\bigr),

\end{equation}
where the last equality names the two constant-extended deficit arms.  The
path and marked laws have the exact disintegrations
\begin{equation}
\begin{aligned}
  \mathcal L_{\widehat{\PP}_n^{\mathrm{grid}}}
    (\Xi_n^{\mathrm{grid}})
  &=\sum_{k=0}^{m_n}q_{n,k}\widehat Q_{n,k},\\
  \mathcal L_{\widehat{\PP}_n^{\mathrm{grid}}}
    (Y_n^{\mathrm{grid}})
  &=\sum_{k=0}^{m_n}q_{n,k}
    (\mathscr M_{L_{n,k}^-,L_{n,k}^+})_*
    \widehat Q_{n,k}.
\end{aligned}

\end{equation}

[Proposition 21 of arXiv:2606.03534, 'Construction and simulation of a path-valued model of dendrite development'] When $\ell_t$ is a Brownian motion absorbed at $\ell=0$, the test functions $D$ form a subset of the domain $\mathcal{D}(A)$. More specifically, for all $F \in D$ we have the limit
    \begin{align*}
        \lim_{t\rightarrow0} \frac{T(t)F - F}{t} 
        = \frac{1}{2} Lg(\omega) \, \mathds{1}_{\{ \ell_\omega >0 \}} \,.
    \end{align*}

