body:
[Lemma 64 (All-degree feedback at fixed input weight) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] Assume that the split is grade-wise orthogonal,
\begin{equation}
 A_{a,p}=P_{M_p}x_{a,p},
 \qquad
 r_{a,p}=P_{M_p^\perp}x_{a,p},
 \qquad
 \norm{A_{a,p}}^2+\norm{r_{a,p}}^2=\norm{x_{a,p}}^2,

\end{equation}
and that
\[
 \sum_{a,p}\norm{x_{a,p}}^2\le R^2.
\]
Then
\begin{equation}
 \norm{\widehat\Lambda_s^{(\infty)}h}^2
 \le sR^2\norm{h}^2,
 \qquad
 \boxed{0\le\widehat N_s^{(\infty)}\le sR^2\Id.}

\end{equation}
Moreover,
\begin{equation}
 \sum_{a,p>Q}
 \bigl(\norm{A_{a,p}}^2+\norm{r_{a,p}}^2\bigr)
 =\sum_{a,p>Q}\norm{x_{a,p}}^2
 \le\eta_0(Q)^2.

\end{equation}
If the ambient grades $p>Q$ are omitted, then
\begin{align}
 \norm{\widehat\Lambda_s^{(\infty)}-\widehat\Lambda_s^{[Q]}}
 &\le\sqrt{s}\,\eta_0(Q),
 \\
 \norm{\widehat N_s^{(\infty)}-\widehat N_s^{[Q]}}
 &\le2sR\eta_0(Q).

\end{align}

[Prop ximoments of arXiv:2411.12003, 'Central Limit Theorem for non-stationary random products of $\SL(2, \R)$ matrices'] Assume that the family $\widetilde{\xi}_{a;n}$ satisfies the assumptions ((a:center of the paper))--((a:difference of the paper)) above. Then, there exists a constant $C_{2}$ such that for all $a$ and $n$,
	\begin{equation}
	        {\mathbb E}\, |\widetilde{\xi}_{a;n}|^{2+{\varepsilon}} < C_{2}^{2+{\varepsilon}} n^{1+\frac{{\varepsilon}}{2}}.
	\end{equation}
	As a corollary, for any $p\in [0,2+{\varepsilon}]$, any $a$ and $n$, one has
	\begin{equation}
	        {\mathbb E}\, |\widetilde{\xi}_{a;n}|^{p} < C_{2}^{p} n^{p/2}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 7 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma >0$ and $D_1 \neq 0$. Assume that Hypothesis \ref{hypnonlin} and \eqref{simp} both hold. Consider the Markov process $\{ \eta_{t}^n : t \in [0,T] \}:=\{ \eta_{t \Theta(n)} : t \in [0,T] \}$  with generator given by \eqref{genABC} with $\Theta(n)$  given by \eqref{timescale} and  suppose that it starts from the invariant state $\nu_{\rho}$. For every $n \in \mathbb{N}_+$, define $ \big( \mathcal{Z}_t^{n,+}, \; \mathcal{Z}_t^{n,-}  \big)_{0 \leq t \leq T}$ by \eqref{defZtnHpm}. With respect to the Skorohod topology of $ \mcb{D} \big( [0,T], \;  \mathcal{S}'(\mathbb{R}) \times \mathcal{S}'(\mathbb{R}) \big)$, $\big\{ \big( \mathcal{Z}_t^{n,+}, \; \mathcal{Z}_t^{n,-}  \big)_{0 \leq t \leq T}: \; n \in \mathbb{N}_+ \big\}$ converges in distribution to $\big( \mathcal{Z}_t^{+}, \; \mathcal{Z}_t^{-}  \big)_{0 \leq t \leq T}$, where $(\mathcal{Z}_t^{+})_{0 \leq t \leq T}$ and $(\mathcal{Z}_t^{-})_{0 \leq t \leq T}$ are uncorrelated stationary energy solutions of the stochastic Burgers equations of the form
\begin{equation} 
\dd \mathcal{Z}^{\pm}_t = ( \mathbb{L}^{ \gamma  } + \widehat{\mathbb{L}}_{\lambda^{\pm}}^{ \gamma}) \; \mathcal{Z}_t \; \dd t + \kappa_{\gamma}^{\pm} (\nabla \mathcal{Z}_t)^2 \; \dd t  + \sqrt{2 D_3^{\pm} \; \mathcal{P}^{\gamma} } \; \dd \mathcal{W}^{\pm}_t.
\end{equation}
In the last display, $D_3^{\pm}$ is given by \eqref{defD3}; $(\mathcal{W}_t^{+})_{0 \leq t \leq T}$ and $(\mathcal{W}_t^{-})_{0 \leq t \leq T}$ are independent $\mathcal{S}'(\mathbb{R})$-valued Brownian motions with covariances given by \eqref{covWpm}; and $\kappa_{\gamma}^{\pm}$ is defined by
\begin{equation} 
\kappa_{\gamma}^{\pm}:= - 2 K^{\star} m_a  \frac{(E_A-2 E_B + E_C \mp  \sqrt{\Delta})(E_A-E_C)}{\pm 2  D_1 \sqrt{\Delta} }.
\end{equation}
In the last line, $K^{\star}$, resp. $m_a$, resp. $\Delta$ is given by \eqref{defKstar}, resp. \eqref{defma}, resp. \eqref{defDelta}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 24 of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] Fix \(\beta \in \bigl(2, (\alpha-1)(d-2) \bigr)\), which exists as soon
as \(d > \frac{2\alpha}{\alpha-1}\). There is \(C \in (0,+\infty)\) such
that for all \(R>0\) large enough, for all \(y\) such that
\(\lVert y \rVert > R\), one has \begin{equation*}{
\widetilde{p}_{R}(y) \leq  C \times  \left( \frac{R}{\lVert y \rVert} \right)^{\beta}\times   R^{-2}.
}\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

