body:
[Lemma integral_bound of arXiv:2605.06511, 'Logarithmic Mixing of Random Walks on Dynamical Random Cluster Models'] For all $n \in \mathbb{N}$ sufficiently large, $\mu > 0$ and $\Delta > 0$ such that $\mu \Delta > 2 \log 2$,
		\begin{equation*}
			\int_{0}^{\Delta} \frac{\mu e^{\mu x}}{e^{\mu \Delta} - 1} \left(p + (1-p)e^{-\mu x}\right)^{r - 1} \text{d} x \leq e^{-{\mu \Delta}/{2}} + O\left((\log n)^{-3}\right).
		\end{equation*}

[Definition 22 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $T_1 \in \mathbb{N}$, $\vec{y} \in \mathfrak{W}_2$, $q \in (0,1)$, $c \in [0, q^{-1})$. Let $\Omega_{\ice}(T_1, \vec{y})$ be as in (\ref{Eq.InteractingPairStateSpace}), and define the probability measure on $\Omega_{\ice}(T_1, \vec{y})$ via
\begin{equation}
\mathbb{P}^{T_1, \vec{y}}_{\ice; q,c} (\mathfrak{B}) = \frac{W(\mathfrak{B};q,c) }{Z(T_1, \vec{y}; q,c)}, \mbox{ for } \mathfrak{B} \in \Omega_{\ice}(T_1, \vec{y}).
\end{equation}
In (\ref{Eq.InteractingPairLaw}) we have that $W(\mathfrak{B};q,c)$ is as in (\ref{Eq.InteractingPairWeight}), $Z(T_1, \vec{y}; q,c)$ is as in (\ref{Eq.FinitePartitionFunction}), and $\mathbb{P}^{T_1, \vec{y}}_{\ice; q, c}$ defines a probability measure on $\Omega_{\ice}(T_1, \vec{y})$ in view of Lemma \ref{Lem.FinitePartitionFunction}. If $\mathfrak{L} = (L_1,L_2)$ is a geometric line ensemble with law $\mathbb{P}^{T_1, \vec{y}}_{\ice; q,c}$, we refer to it as an {\em interacting pair of reverse interlacing geometric random walks with parameters $q,c$} or simply as an {\em interacting pair} for short.

[Theorem 3 (Coarse MLSI at all positive temperatures) of arXiv:2608.13677, 'Asymptotically complete free-energy dissipation: \\ a coarse MLSI holds at any positive te'] \label[theorem]{theorem:coarse_MLSI}
    For every \(\epsilon > 0\) there is some \(\delta > 0\) such that for all translation-invariant \(\mu\) it holds that
    \begin{align}
        \sigma(\mu)
        \geq \delta \, (h(\mu) - \epsilon).
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 53 of arXiv:2608.30059, 'Multihomogeneous Measures and Stochastic Polar Representations'] If \(\nu\in M_{\chi,\sigma}(E)\) and  
\(\mathsf K^\ast\mu=\nu\) for some positive measure \(\mu\), then \(\mu\) is nonzero,  \(\sigma\)-finite and for every positive measure \(\lambda\)
\begin{equation}

\mathsf K^\ast\lambda=\nu
\quad\Longleftrightarrow\quad
\int_E\Gamma(x)\,d\lambda(x)=\int_E\Gamma(x)\,d\mu(x)
\quad\text{for every }
\Gamma\in\mathcal H_\rho(E).
\end{equation}

[Lemma 4 of arXiv:2607.11608, '2607.11608'] Let $f$ be a strictly increasing function on $\R_+$
such that   $f(0) = 0$ and its inverse $f^{-1}$ is also strictly increasing.
Then, for any $a, b \ge 0$, we have
\begin{align}
ab \le \int_0^a f(x) dx   +  \int_0^b f^{-1}(x) dx 

\end{align}

\noi
with equality if and only if $b = f(a)$.
In particular, applying \eqref{Young1}
to  $f(x) = e^x - 1$ and $f^{-1}(x) = \log(1+x)$
\textup{(}with $b$ replaced by $b-1$\textup{)}, 
we have 
\begin{align*}
ab \le e^{a} + b \log b - b

\end{align*}

\noi
for any $a \ge  0$ and $b \ge 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor prop:filter of arXiv:2609.00672, 'Deciding superellipticity and computing the Weierstrass normal form'] The vanishing sequence of $H^0(C,\Omega^1)$ at $P$ is

\begin{equation}
s=\bigl(\,na+n-1-(b\,l_i\bmod n) : (a,b)\in A\,\bigr),
\end{equation}

arranged in increasing order.

[Proposition 139 of arXiv:2601.16377, '2601.16377'] Consider a discrete ensemble satisfying Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit}, \ref{Assumptions_analyticity} and the additional Assumption~\ref{Assumptions_extra}. For any $h\in[H]$ and $z\in \amsmathbb M_h\setminus \amsmathbb{A}^{\mathfrak{m}}_h$, we have
\begin{equation}

 \begin{split}
& \quad Q_h^-(z)\,\big\langle \bth_h\cdot \boldsymbol{W}_1(z)\big\rangle + \frac{Q_h^+(z)}{2\N}\big\langle\bth_h\cdot \boldsymbol{W}_1(z)\big\rangle^2+
 \frac{Q_h^+(z)}{2\N}\big\langle \bth_h^{\otimes 2} \cdot \boldsymbol{W}_2(z,z)\big\rangle \\
 & \quad + \frac{Q_h^+(z)}{2\N}\big\langle \bth_h(\bth_h - 1)\cdot \partial_{z} \boldsymbol{W}_1(z)\big\rangle + q_h^{+,[1]}(z) + \frac{q_h^{+,[2]}(z)}{\N} \\
 & = \widetilde R_h(z)+ \mathbbm{Err}_h^{(1)}(z)+ \mathbbm{Err}_h^{(2)}(z),
\end{split}
\end{equation}
Here, $\widetilde R_h(z)$ is a holomorphic function of $z\in \amsmathbb M_h$. If $\hat a'_h \in \amsmathbb{S}_h$, then $\widetilde R_h(\hat a'_h)=0$; if $\hat b'_h\in \amsmathbb{S}_h$, then $\widetilde R_h(\hat b'_h)=0$.

Besides, for any $\eps > 0$ and compact $\amsmathbb{K}_h \subset \amsmathbb{M}_h \setminus \amsmathbb{A}_{h}^{\mathfrak{m}}$, there exists a constant $C > 0$ depending only on $\eps$, these compacts and the constants in the assumptions, such that for $\N$ large enough
\begin{equation}

\sup_{z \in \amsmathbb{K}_h} \big|\mathbbm{Err}_h^{(1)}(z)\big| \leq C \N^{-\frac{3}{2} + \eps}.
\end{equation}
The function $\mathbbm{Err}_h^{(2)}(z)$ is a finite sum --- with a number of terms which does not depend on anything --- of expressions of the form
\begin{equation}

\frac{F(z)}{\N^{q}} \cdot \prod_{i=1}^k \E\Bigg[\prod_{j=1}^{l_i} \partial_z^{d_{i.j}} \Delta G_{g_{i,j}}(z) \Bigg] ,
\end{equation}
for some $q \in \amsmathbb{Z}_{\geq 2}$ and $k,l_1,\ldots,l_k \in \amsmathbb{Z}_{> 0}$ satisfying
  \begin{equation}

  q \leq \sum_{i=1}^k l_i \leq q+1,
  \end{equation}
 some function $F(z)$ which is holomorphic for $z \in \amsmathbb{K}_h$ and bounded from above in absolute value by $C$, and some $d_{i,j} \in \{0,1\}$ and $g_{i,j} \in [H]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:k-lift-TW-max of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] For any given integer  $k\ge1$, define iteratively $G_N^{(i)}$ as a random 2-lift of $G_N^{(i-1)}$ for $i=1,\dots,k$, where    $G_N^{(0)}$ is a uniformly random $d$-regular graph.   If $d\gg N^{2/3+\tau}$, then
\begin{equation}
  (2^{k-1}N)^{\frac{2}{3}}\bigl(\tfrac{\lambda_2(G_N^{(k)})}{\sqrt{d}}-2\bigr)
  \;\xrightarrow[N\to\infty]{\mathrm{D}}\;
  \max_{1\le i\le k} 2^{\frac{2(k-i)}{3}}\mathcal{X}_i,
\end{equation} 
where $\mathcal{X}_i$ are i.i.d. random variable with the same  Tracy-Widom distribution $F_1$.

