[Proposition prop:turning_point of arXiv:2603.27906, 'Marked GUE-corners process in doubly periodic dimer models'] For~$k=1,\dots,\ell$, set~$a_k=\alpha_k\beta_{k-1}^{-1}$ and~$b_k=\alpha_k^{-1}\beta_k$. Then
\begin{equation}
\tau =
\sum_{k=1}^\ell \frac{1+a_k+a_kb_k+a_kb_ka_{k+1}}
{(1+a_k)(1+b_k)(1+a_{k+1})}
\end{equation}
where~$a_{\ell+1}=a_1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:loo-radial of arXiv:2608.18293, 'Critical tensor covariance at the Marchenko--Pastur threshold'] For every fixed $z\in\mathbb{C}_+$,
\begin{equation}
  \max_{1\le\alpha\le m}
  \mathbb{E}\left|a_\alpha(z)-R_{n,\alpha}m_n^{(\alpha)}(z)\right|^2
  \longrightarrow0.

\end{equation}

[Lemma 13 (Burn-in sample size for the empirical denominator) of arXiv:2608.22636, 'Q-Learning with Stable Infinite-Dimensional \\Linear Function Approximation'] Recall the definition of $r_c:=       \frac{c_\wedge}{64(1\vee L_{\kappa,\rho})}$ in Theorem \ref{thm:empirical_normalized_rate}. If
\begin{equation}
        n+1
        \ge
        \frac{256\tmix^2}{c_\wedge^2}
        \log\!\crbk{\frac{2\cN_\rho(r_c)}{\delta}},

\end{equation}
then, with probability at least $1-\delta$,
\[
        \sup_{k\ge n}\norm{\hat c_k-c}
        \le
        \frac{c_\wedge}{4}.
\]

[Proposition prop_1 of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] For $0< b<1$  and integer $m\geq1$ define the sequence of functions  

  \begin{eqnarray}

\theta_m(b)=-\frac{1}{b^{m+1}}\Big(\ln(1-b)+b+\frac{b^2}{2}+\frac{b^3}{3}+\cdots+\frac{b^m}{m}\Big).
\end{eqnarray}  
If $A$ is symmetric, then HWI holds with 
\begin{eqnarray}

\kappa=\frac{b^*}{4}\approx 0.1457, 
\end{eqnarray}
 where $b^*$ is the unique solution for $b$ in the equation\footnote{The equation $2b\theta_1(b)=1$ simplifies to $\ln(1-b)=-\frac{3}{2}b$.  } $2b\theta_1(b)=1$.

