body:
[Lemma 10 of arXiv:2609.02790, 'Full-Model Optimality for Tunable Linear Generative Priors in Compressed Sensing'] Let $M_k = \begin{bmatrix}
        M_{k-1},m_k
    \end{bmatrix} \in \R^{m\times k}$ 
 be a matrix $\in \R^{m \times k}$, where $M_{k-1} \in \R^{m \times (k-1)}$ has full rank, $m_k \in \R^m $ and $k \geq m$.  
 \begin{equation}
     \Tr\Big(M_{k-1}^{\dagger}(M_{k-1}{^{\dagger}})^T\Big) \geq \Tr\Big(M_k^{\dagger}(M_k{^{\dagger}})^T\Big) 
 \end{equation}
and 
\begin{equation}
 \Big(M_{k-1}^{\dagger}(M_{k-1}{^{\dagger}})^T\Big)_{ii} \geq \Big(M_k^{\dagger}(M_k{^{\dagger}})^T \Big)_{ii}   
\end{equation}
$\forall i \in [k-1]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theo thm:Feller of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] Let $\mathbb{X}$ be a (not necessarily transient) standard process. Suppose that for some $\alpha>0$, $\mu$ is $G_\alpha$-Kato, $G_\alpha(\cdot,y), y\in X$ is l.s.c and let $F$ be the fine support of $\mu$. Assume that $F$ is closed. Then
\begin{enumerate}
 \item[\rm(1)] The semigroup  $\check{T}_t$ maps $C_0(F)$ into itself and $\check{T}_t: C_0(F)\to C_0(F)$ has Feller property.
 \item[\rm(2)] The resolvent  $V_\alpha$ maps $C_0(F)$ into itself and $V_\alpha: C_0(F)\to C_0(F)$ has Feller property.
 \end{enumerate}

[Lem 18 of arXiv:2605.30779, '2605.30779'] Let $l \geq 0$ and $\Theta = (\theta_1, \dots, \theta_l)$. For every \(\varepsilon>0\), there exists a random variable \(\mathcal J' =\mathcal J'(\varepsilon)\) such that almost surely,
\begin{equation} 
\left|
a_j^{\Theta}
+\left(\frac{3\pi j}{2}\right)^{2/3}
\right|
\le j^\varepsilon,
\qquad j>\mathcal J'.
\end{equation}

[Theorem 20 (Deterministic error bound \cite{halko2011finding}) of arXiv:2609.02790, 'Full-Model Optimality for Tunable Linear Generative Priors in Compressed Sensing'] Let $A$ be an $m \times n$ matrix with SVD $A=U\Sigma V$, and fix $k \geq 0$. Choose a test matrix $\Omega$, and construct the sample matrix $Y=A \Omega$. Partition $\Sigma$ as 

\[
A = U
\begin{bmatrix}
\Sigma_1 & \\
& \Sigma_2
\end{bmatrix}
\begin{bmatrix}
V_1^{*} \\
V_2^{*}
\end{bmatrix},
\qquad
\Sigma_1 \in \mathbb{R}^{k \times k},\;
\Sigma_2 \in \mathbb{R}^{(n-k)\times(n-k)}.
\]
and define $\Omega_1$ and $\Omega_2$ via $\Omega_1=V_1^\star  \Omega$ and $ \Omega_2=V_2^\star  \Omega$. Assuming that $\Omega_1$ has full row rank, the approximation error satisfies
\begin{equation}
    \left\|\left(\mathbf{I}-P_{Y}\right) A\right\|_F^2 \leq\left\|\Sigma_2\right\|_F^2+ \| \Sigma_2 \Omega_2 \Omega_1^{\dagger} \|_F^2,
\end{equation}

[Definition 1 of arXiv:2506.11918, 'Central limit theorems for the Euler characteristic in the Random Connection Model for hig'] [Simplex functions and integral representations] 
Let $K$ be a simplicial complex with $\dim(K)\leq\alpha$ on the vertex set $\{1,\dots,r\}$ for some $r\in\N$.
\begin{enumerate}
\item Define the simplex function of $K$ by
\begin{align*}
f_K: \X^r \rightarrow [0,1], \qquad f_K(x_1,\dots,x_r):= \prod_{\sigma\in K} \; \varphi_{|\sigma|-1} (x_\sigma),
\end{align*}
where $\varphi_{|\sigma|-1} (x_\sigma)$ denotes the value of $\varphi_{|\sigma|-1}$ evaluated at the points $\{ x_i\,|\, i\in \sigma\}$.
\item The integral representation $I_K$ of $K$ (over an observation window $W$) is defined by
\begin{align*}
I_K(W) \,:=\, \int_{W^r} f_K(x_1,\dots,x_r) \;\; \lambda^r \, (\d {(x_1,\dots,x_r)}).
\end{align*}
We call $K$ the simplicial complex associated to $I_K$.
\item For $m,l\in\{1,\dots,\alpha+1\}$ and $\max\{m,l\}\leq r\leq m+l$, we consider the simplicial complex
\begin{align} 
K_{m,l}^r \,:=\, \Big\langle [1,\dots,m], [1,\dots,m+l-r,m+1,\dots,r] \Big\rangle
\end{align}
on the vertex set $\{1,\dots,r\}$, which is generated by a $(m-1)$-simplex and a $(l-1)$-simplex sharing $m+l-r$ vertices.
Moreover, we denote by $\kappa_{m,l}^r$ the simplex function and by $\z m l r$ the integral representation of $K_{m,l}^r$, which means
\begin{align*}
\z m l r (W) \,:=\, \int_{W^r} \kappa_{m,l}^r(x_1,\dots,x_r) \;\; \lambda^r \, (\d {(x_1,\dots,x_r)}).
\end{align*}
Finally, let $\kappa_m:=\kappa_{m+1,m+1}^{m+1}$ be the simplex function of a simplicial complex generated by an $m$-simplex.
\end{enumerate}

[Dfn 104 (discrete-time occupation measures) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Partition time into intervals $I_d \equiv [q_d,q_{d+1})$, and partition space into rectangles 
	$R_{\vl,j}
	\equiv J_{\vl}
	\times K_j$, as above.
Let $\rho_{\vY,N}$ be the occupation density for $\vY^{\frozen,\bullet,N}$: that is, we let $\rho_{\vY,N}$ be uniform on each $I_d\times R_{\vl,j}$, with
	\[
	\frac{\rho_{\vY,N}(I_d\times R_{\vl,j})}{|I_d|}
	= \mu_{\bullet,\bG^N}
	\Big( \vY^{\frozen,\bullet,N}(q_d) \in R_{\vl,j}\Big)
	\,,\]
where $\mu_{\bullet,\bG^N}$ is as defined in Theorem~\ref{t:tightness}.  Recall from Definition~\ref{d:rerand.Ising} that in the spatial rerandomization, the $a(q_d)\in[M]$ indices and the $i(q_d)\in[N]$ indices evolve completely independently, so the processes $\vY^{\frozen,\bullet,N,\RomI:\RomIII}$ and $Y^{\frozen,\bullet,N,\Ising}$ are independent under $\mu_{\bullet,\bG^N}$. This implies the above is equal to
	\beq
	\mu_{\bullet,\bG^N}
	\bigg( 
	\vY^{\frozen,\bullet,
	N,\RomI:\RomIII}(q_d)
	 \in J_{\vl}
	 \bigg)
	\cdot
	\mu_{\bullet,\bG^N}
	\Big( Y^{\frozen,\bullet,N,\Ising}(q_d) 
	\in K_j \Big)\,.
	\eeq
We similarly let $\rho_{D,N}$ be the signed measure which is uniform on each $I_d\times R_{\vl,j}$, with
	\begin{align}\nonumber
	&\frac{\rho_{D,N}
	(I_d\times R_{\vl,j})}{|I_d|}
	= 
	\bE_{\bG^N} \bigg[
	\frac{\Delta \bar{D}^{\frozen,\RomI,N}(q_d)}
	{\delta_d}
	\ind\Big\{
	\vY^{\frozen,\bullet,N}(q_d) \in R_{\vl,j}
	\Big\}\bigg] \\
	&\qquad\stackrel{\eqref{e:review.b}}{=}
	(p^N)'(q_d)^{1/2}
	\bigg\{ \sum_{B^\frozen \in 
		B^{\frozen,\coarse}}
		\frac{|B^\frozen|}
			{|B^{\frozen,\coarse}|}
	\bbb^{\frozen,N}\Big(q_d, 
		B^\frozen \Big)
	\bigg\}
	\mu_{\bullet,\bG^N}
		\Big( 
		\vY^{\frozen,\bullet,N}(q_d) \in R_{\vl,j}\Big) \nonumber\\
	&\qquad\stackrel{\eqref{e:review.b}}{=}
	(p^N)'(q_d)^{1/2}
	\bbb^{\frozen,\coarse,N}(q_d, B^{\frozen,\coarse}) 
	\mu_{\bullet,\bG^N}
		\Big( 
		\vY^{\frozen,\bullet,N}(q_d) \in R_{\vl,j}\Big)

	\end{align}
with $B^{\frozen,\coarse}=B^{\frozen,\coarse}(q_d,J_{\vl})$ as defined by \eqref{e:coarsened.bucket}, and recalling that the last term above factorizes as in \eqref{e:a.i.factorization}. We similarly define measures $\rho_{V,N}$, $\rho_{U,N}$, 
$\rho_{\www,N}$,
and $\rho_{\rrr,N}$
 using increments of 
$\tilde{Q}^{\frozen,\RomII,N}$, $\tilde{Q}^{\frozen,\RomII,\RomIII,N}$, $\tilde{Q}^{\frozen,\Ising,N}$, and 
$C^{\frozen,\RomIII,N}$ respectively.

[Proposition 9 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, the following statements hold.
        \begin{enumerate}[label=(\roman*)]
                \item There exists a unique holomorphic function $\Pi:\C^+\to\C^{L\times L}$ such that, for every $z\in\C^+$, $\Om(\Pi(z),z)=0$, $\Im\Pi(z)>0$, and $\Im(z^{-1}\Pi_{11}(z))>0$.
                \item Define $\wt T(z):=z^{-1}\Pi_{11}(z)$ and $T(z):=\Pi_{22}(z)$. There exist unique positive semidefinite matrix-valued measures $V_1$ and $V_2$ on $[0,\infty)$, with values in $\C^{M\times M}$ and $\C^{N\times N}$, respectively, such that $V_1([0,\infty))=I_M$, $V_2([0,\infty))=I_N$, and
                      \begin{align}
                              \wt T(z)=\int_{[0,\infty)}\frac{V_1(\dd\la)}{\la-z},\qquad T(z)=\int_{[0,\infty)}\frac{V_2(\dd\la)}{\la-z}. \nonumber
                      \end{align}
                      Moreover, there exists a constant $C_*<\infty$ such that $\supp V_1\cup\supp V_2\subset[0,C_*]$.
                \item Let $\bnu_1:=\avg{V_1}_M$ and $\bnu_2:=\avg{V_2}_N$. Then $\bnu_1$ and $\bnu_2$ are compactly supported probability measures on $[0,\infty)$ and, with $\wt m(z):=\avg{\wt T(z)}_M$ and $m(z):=\avg{T(z)}_N$,
                      \begin{align}
                              \wt m(z)=\int_{[0,\infty)}\frac{\bnu_1(\dd\la)}{\la-z},\qquad m(z)=\int_{[0,\infty)}\frac{\bnu_2(\dd\la)}{\la-z}. \nonumber
                      \end{align}
                      Moreover,
                      \begin{align}
                              g(z)=-\avg{\Sg}_N+\int_{[0,\infty)}\frac{\la\avg{\Sg V_1(\dd\la)}_N}{\la-z}. \nonumber
                      \end{align}
                \item Writing $\bnu:=\bnu_2$, we have $\sup\supp\bnu\sim1$. Moreover, the mass at the origin is
                      \begin{align}
                              \bnu(\{0\})=\left(1-\frac{M}{N}\right)\mb 1\left(\frac{M}{N}\leq1\right). 
                      \end{align}
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:abstract-simple-response of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] If $\Lambda_n^\mu$ is simple, then for every $f\inH_{\mathrm{reg}}$ the two one-sided
derivatives agree and
\begin{equation}
 \partial_f^-\Lambda_n^\mu
 =\partial_f^+\Lambda_n^\mu
 =:\partial_f\Lambda_n^\mu
 =-\kappa\Lambda_n^\mu
 \int_{S} f(\phi_n^\mu)^2\,d\mu.

\end{equation}
If $\int_{S}f\,d\rho=0$, then also
\begin{equation}
 \partial_f\Lambda_n^\mu=\int_{S}f\,d\eta_n^\mu.

\end{equation}

[Proposition 15 of arXiv:2605.03057, 'Uniform-in-time quantitative fluctuations of large scale interacting particle systems'] Assume Assumption~\ref{ass:smooth}. Let $\left(\mu_s\right)_{0\le s\le t}$ be the law flow of the McKean--Vlasov SDE~\eqref{eq:MV}.
Let $\varphi\in C_b^5\left(\R^d\right)$ and let $\left(\psi_s\right)_{0\le s\le t}$ be a classical solution to the backward equation
\begin{equation}

\partial_s\psi_s+\mathcal L_{\mu_s}\psi_s+\mathcal A_{\mu_s}\psi_s=0,\qquad s\in\left[0,t\right),\qquad \psi_t=\varphi.
\end{equation}
Then, the limiting variance in Definition \ref{def:uniform-time-limiting-variance-abs-assump} can be written as
\begin{equation}

\sigma_t^2\left(\varphi\right)
=
\Var\left(\psi_0\left(X_0\right)\right)
+\int_0^t \E\left(\norm{\sigma\left(X_s,\mu_s\right)^\top\nabla\psi_s\left(X_s\right)}^2\right) ds,
\end{equation}
where $X$ solves \eqref{eq:MV}. In particular, $\sigma_t^2\left(\varphi\right)=\lim_{N\to\infty}\sigma_{N,t}^2\left(\varphi\right)$.

[Proposition pr:prob:tail of arXiv:2411.09381, 'On the well-posedness of SPDEs with locally Lipschitz coefficients'] If $L_{\sigma}>0$, then
	\begin{equation}
		\mathrm{P}\left\{ |u_{N+1}(t\,,x)| \ge \mathrm{e}^N\right\}
		\le \exp\left( - \frac{N^{3/2}}{64 L_{\sigma}^2 \sqrt{t}}\right),
	\end{equation}
	uniformly for all $t>0$,  $x\in\mathbb{R}$, and
	\[
		N\ge  4 \log ( 4(\|u_0\|_{L^\infty(\mathbb{R})} +1))\vee
		256 t\max\left(4L_{\sigma}^4, L_b\right).
	\]
	If $\sigma\in L^\infty(\mathbb{R}_+\times\mathbb{R})$, then
	\begin{equation}
		\mathrm{P}\left\{ |u_{N+1}(t\,,x)| \ge \mathrm{e}^N \right\}
		\le \exp\left( - \frac{\mathrm{e}^{2N-4L_bt}}{32\mathrm{e}\left(\|u_0\|_{L^\infty(\mathbb{R})} 
		+ \|\sigma\|_{L^\infty(\mathbb{R}_+\times\mathbb{R})}t^{1/4}+1\right)^2}\right),
	\end{equation}
	uniformly for all $t>0$,  $x\in\mathbb{R}$, and
	\[
		N\ge \tfrac12\log32 + 2L_bt+ \tfrac12 + \log\left( \|u_0\|_{L^\infty(\mathbb{R})} + 
		\|\sigma\|_{L^\infty(\mathbb{R}_+\times\mathbb{R})}t^{1/4}+1\right).
	\]

