body:
[Theorem theo:limitcrowkimura of arXiv:2411.16366, 'Connections between sequential Bayesian inference and evolutionary dynamics'] Assume that $g(x): \mathbb{R}^m \rightarrow \mathbb{R}^m$ and $h(x): \mathbb{R}^m \rightarrow \mathbb{R}^n$ are $C^2$, globally Lipschitz continuous functions satisfying linear growth conditions, i.e. there exists a constant $C > 0$ such that 
	\begin{align*}
		\| h(x) - h(y) \| + \|g(x) - g(y) \| &\leq C\|x - y\|, \enskip x, y, \in \mathbb{R}^m \\
		\| h(x)\| + \|g(x) \| &\leq C(1 + \|x \|), \enskip x \in \mathbb{R}^m
	\end{align*}
	Let $\Sigma$ and $\Xi$ be $m \times m$ and $n \times n$ positive definite matrices respectively. 
	Denote by $\mu_t^d(x)$ the solution to the unnormalised Crow-Kimura replicator-mutator equation with time-varying fitness landscape (equation eq:genquadfit of the paper) with $s < r, r >0$
	\begin{align}
		\nonumber 

		\partial_t \mu_t^d(x) &= \mathcal{L}^\ast \mu_t^d(x) +  \mu_t^d(x) \mathbb{E}_{z \sim \mu_t^d}[f_{t}(x,z)] \\

		& =  \mathcal{L}^\ast \mu_t^d(x) -\frac{r}{2}\|h(x) - \frac{dZ_t^d}{dt}\|_{\Xi}^2 \mu_t^d(x) + s \left \langle h(x) - \frac{dZ_t^d}{dt}, h(z) - \frac{dZ_t^d}{dt} \right \rangle_{\Xi} \mu_t^d(x)
	\end{align}
	Let $q_t(x)$ denote the solution of the modified Zakai equation (presented here in Ito form), 
	\begin{align}



		d q_t = \mathcal{L}^\ast q_t(x) -\frac{s}{2}h(x)^\top \Xi^{-1} h(x) q_t(x)  + (r-s)q_t(x) h(x)^\top \Xi^{-1} dZ_t. 
	\end{align}
	Suppose also that $q_0(x) = \mu_0^d(x) = f(x)$ where $f$ is a uniformly bounded $C^\infty$ probability density function.  Then for any $T > 0$, 
	\begin{align}

		\lim_{d \rightarrow \infty} \mathbb{E} \left[ \sup_{0 \leq t \leq T} |\mu_t^d(x) - q_t(x) |^p\right] = 0, \quad \forall \enskip x \in \mathbb{R}^m 
	\end{align}
	for $p \geq 1$ and $r,s$ additionally satisfying $r-s < \frac{2}{ tC(1+ \mathbb{E}^\mathbb{Q}[|x|^2])p \lambda_\Xi^2 r_1r_2} $, where $r_1,r_2 >1$ and $1/r_1 + 1/r_2 = 1$ and $C$ depends on the linear growth constant of $h(x)$. 
	Importantly, when $r=1, s = 0$, (equation eq:repmutnonlin of the paper) converges to the standard Zakai equation (equation eq:zakai of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Theo3 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that assumptions (A1 of the paper)-(A7 of the paper) hold and  let $\varphi$ be an $h$-dependent descendant characteristic, for some $h \in \mathbb{N}_{0}$, satisfying (C1 of the paper)-(C5 of the paper). Suppose further that $t \in \mathbb{R} \mapsto m_{t}^{\mathbb{E}[\varphi]} e^{-\frac{\alpha}{2}t}(1+t^{2})$ is bounded. Then, as $t \rightarrow \infty$, $t \in \mathbb{G}$,
\begin{align} 
 e^{-\frac{\alpha}{2}t} \mathcal{Z}_{t}^{\varphi}  \xrightarrow[]{\rm st} \sigma_{\varphi} \left( \frac{W}{\beta} \right)^{1/2} \mathcal{N},
\end{align}
\noindent where $\beta \in (0, \infty)$ is defined in (equation eq3 of the paper), $W$ is the limit of Nerman's martingale, $\mathcal{N}$ is a standard normal random variable independent of $\mathcal{F}$ (and thus of $W$) and
\begin{align}
\sigma_{\varphi}^{2} \coloneqq  \int_{\mathbb{G}}  \mathbb{E}[(\chi^{(\varphi+m^{\mathbb{E}[\varphi]}\ast \xi,h)}(s))^{2}] e^{-\alpha s} \ell( {\rm d} s).
\end{align}
\noindent Moreover, if $\sigma_{\varphi}^{2}=0$ then
\begin{align}  
t \in \mathbb{R} \mapsto \sum_{0\leq |u| \leq h-1}\varphi_{u}^{(h-|u|)}(t-S(u))  + \sum_{|u| = h} m^{\mathbb{E}[\varphi]}_{t - S(u)}
\end{align}
\noindent is a version of the process $\mathcal{Z}^{\varphi}$. 
(If $h=0$, the sum $\sum_{0\leq |u| \leq h-1}$ in (equation eq171 of the paper) is defined to be $0$.)

