[Definition def:Phi-Wishart of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Denote
\begin{equation}
(\Phi_2)_{xx'} = \delta_{xx'}\sum_{y\in[M]}\bigl(|H_{xy}|^2-\mathbb{E}[|H_{xy}|^2]\bigr),
\quad
(\Phi_3)_{xx'} = -|H_{x x'}|^2\,H_{x x'},
\end{equation}
for $x,x'\in[N]$, and
\begin{equation}
(\Phi_2)_{yy'} = \delta_{yy'}\sum_{x\in[N]}\bigl(|H_{xy}|^2-\mathbb{E}[|H_{xy}|^2]\bigr),
\quad
(\Phi_3)_{yy'} = -|H_{y y'}|^2\,H^*_{y y'},
\end{equation}
for $y,y'\in[M]$.  In addition,
\begin{equation}
(\Phi_A)_{xy}=A_{xy},
\quad
(\Phi_{A^*})_{yx}=(A^*)_{yx}\end{equation}
For an insertion $\alpha \in \{2,3\}$ and $n \ge 0$, define
\begin{equation}
(\underline{\Phi_\alpha V_{n+\alpha}})_{v_0 v_{n+1}}
= \sum_{v_1,\dots,v_n}
\Biggl[\prod_{i=0}^{n-1} \mathbf{1}(v_i \neq v_{i+2}) \Biggr]
(\Phi_\alpha)_{v_0v_1} \,(Y)_{v_1v_2}\,(Y^*)_{v_2v_3}\,(Y)_{v_3v_4} \cdots (Y/Y^*)_{v_n v_{n+1}},
\end{equation}
where the product alternates between $Y$ and $Y^*$, and   $Y = H$ if $v_1 \in [N]$ and $Y = H^*$ if $v_1 \in [M]$.
For $\alpha\in \{A,A^*\}$, we define 
\begin{equation}
    \underline{\Phi_\alpha V_{n+1}}=\Phi_{\alpha}V_n.
\end{equation}

[Lemma lem:qjellsmall of arXiv:2412.09145, 'Asymptotic expansions for normal deviations of random walks conditioned to stay positive'] For the functions $Q_{j,\ell,m}$ defined in Proposition~(prop:basisconvolution of the paper) one has
\begin{align} 
    e^{-\frac{z^2}{2n}}
    \frac{Q_{j,\ell,m}(z/\sqrt{n})}{n^{\ell+j-m/2}}
=
    O\left(\frac{1}{(\min(\sqrt{n},1+|z|))^{2\ell+2j-m}}
    \right).
\end{align}

