[Definition 27 of arXiv:2604.13454, 'Invariant and periodic measures in classical spin systems on infinite lattices with highly'] Let $(E,\mathscr{B}(E))$ be a locally compact separable metric space. A measure-valued function $\mu:\mathbb{T}\rightarrow\mathscr{P}(E)$ is called a T-periodic measure with respect to the transition semi-group $\mathcal{P}(\cdot,\cdot)$ if for all $0\leq s\leq t$
        \begin{equation*}
            \mu_{s+T}=\mu_s,\quad \mu_{t}=\mathcal{P}^*(s,t)\mu_s.
        \end{equation*}

[Definition def:bochner-verification-class of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Let $I=(r_0,r_1)$ and let $w$ be a regular weight.  For a compact positive
strip $J=[s,r]\Subset I$, define the following joint Bochner energy:
\begin{align}
 \mathfrak B_{J,w}(q)
 :={}&\int_{J\times\mathbb R^d}w\Bigl(
       |D_t^cq|^2+|\Delta_{\mu,g}q|^2+|\operatorname{Hess}_gq|_g^2
+\bigl(1+|c|_g^2+|\nabla^g\log\varrho|_g^2
          +w^{-1}|\mathscr R_{w,t}|_g\bigr)|q|^2\notag \\
 &+\bigl(1+w^{-1}|\mathscr R_{w,t}|_g\bigr)
          |\nabla^gq|_g^2\Bigr)\,\mathrm d\mathfrak m
 +\sum_{t\in\{s,r\}}\int_{\mathbb R^d}
       \bigl(|q(t)|^2+|\nabla^{g_t}q(t)|_{g_t}^2\bigr)\,\mathrm d\mu_t.

\end{align}

The \emph{Bochner verification class} $\mathfrak C_{\rm B}(I,w)$ consists of
the fields $q=S_IF$, with $F\in L_w^2(I)$, such that
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.5em]
\item $q$ vanishes on $(\tau,r_1)\times\mathbb R^d$ for some $\tau<r_1$;
\item $q\in W_{p,\mathrm{loc}}^{1,2}(I\times\mathbb R^d)$ for some $p>d+2$;
\item $\mathfrak B_{J,w}(q)<\infty$ for every compact positive strip
      $J\Subset I$.
\end{enumerate}
The corresponding source class is
\begin{equation*}
 \mathfrak D(I,w)
 :=\{F\in L_w^2(I):S_IF\in\mathfrak C_{\rm B}(I,w)\}.
\end{equation*}

