\end{equation}

[Proposition 252 of arXiv:2601.16377, '2601.16377'] We have $H_1(\mathcal{D},\amsmathbb{Z}) \simeq H_1(\mathsf{G},\amsmathbb{Z})$ and $\textnormal{Im}(\boldsymbol{\Theta}) = \textnormal{span}_{\amsmathbb{R}}(\mathbf{1}_{\mathcal{H}_1},\ldots,\mathbf{1}_{\mathcal{H}_m})$.
\begin{itemize}
\item If $\mathsf{G}$ is bipartite, then we have $m = \textnormal{rank}(\boldsymbol{\Theta}) + 1$ and $H_1(\mathsf{G},\amsmathbb{R}) \cong \textnormal{Ker}(\boldsymbol{\Theta})$.
\item If $\mathsf{G}$ is non-bipartite, then we have $m = \textnormal{rank}(\boldsymbol{\Theta})$ and $\dim H_1(\mathsf{G},\amsmathbb{R}) = \textnormal{corank}(\boldsymbol{\Theta}) + 1$.
\end{itemize}

[Lemma 208 of arXiv:2601.16377, '2601.16377'] Let $p_1(z),\ldots,p_H(z)$ be polynomials of degree (at most) $H-1$, such that
 \begin{equation}

  \oint_{\gamma_h} \frac{p_g(\zeta)}{\sigma(\zeta)} \frac{\dd \zeta}{2\ii\pi}= \delta_{g,h}.
 \end{equation}
 Consider the integral operator $\mathcal{P}^H:\mathscr{L}^2(\gamma^+) \longrightarrow \mathscr{L}^2(\gamma^+)$ given by $\displaystyle f \longmapsto \oint_{\gamma^+} f(w)\, \dfrac{ P^H(z,w)}{2\ii\pi}\dd w$, where
 \begin{equation}

 P^H(z,w)= \frac{p_h(z)}{\sigma(z)},\quad \textnormal{ for } w\in \gamma_h^+, \quad h\in [H].
 \end{equation}
 Then for any polynomial $f(z)$ of degree at most $H-1$, we have
 \begin{equation}

 \mathcal P^H \left[\frac{f}{\sigma}\right](z)=\frac{f(z)}{\sigma(z)}.
 \end{equation}
 Further, for any $f\in \mathscr{L}^2(\gamma^+)$ with vanishing integrals around each $\gamma_h$, $h\in[H]$, we have $\mathcal P^H f=0$.

