[Prop first derivative formula of arXiv:2609.02409, 'Membranes and Maps'] For the unpointed series, we have
    \begin{equation}

        \big[\epsilon_4^0\epsilon_5^{-1}\big]_{\mathrm{CY}} \,
        \mathsf{H}^{\mathrm{st}}\big(~;\epsvec{[5]};u\big)
        =
        u^2 \,
        \Psi\left(
            \frac{1}{2u^2}
            \sum_{i=1}^3
            \left(
                \frac{\kappa(u\epsilon_i)}{u}
                -
                \frac{1}{u^2\epsilon_i}
            \right)
        \right) \,.
    \end{equation}
    For $n\in\{1,2,3\}$, we have
    \begin{equation}
        \big[\epsilon_4^0\epsilon_5^{-1}\big]_{\mathrm{CY}} \,
        \mathsf{H}^{\mathrm{st}}\big(\epsvec[-1]{[n]};\epsvec{[5]};u\big)
        =
        \Psi \big(\mathsf{U}\big(\epsvec{[n]};u\big)\big)
        \frac{(-1)^n}{2}
        \prod_{j=1}^n \prod_{i\neq j}
            \frac{1}{\epsilon_i}\,
        +
        \delta_{n,3}\,
        \frac{2}{u^2\epsilon_1^2\epsilon_2^2\epsilon_3^3} \,,
    \end{equation}
    where
    \begin{equation}

        \mathsf{U}(\epsvec{[n]};u)
        \coloneqq
        \begin{cases}
            \dfrac{1}{u}
            \dfrac{
                \varsigma(u\epsilon_2)\varsigma(u\epsilon_3)
            }{
                \varsigma(u\epsilon_1)
            }
            & n=1 \,,\\[1em]
            \dfrac{1}{u}
            \dfrac{
                \varsigma(u\epsilon_3)^3
            }{
                \varsigma(u\epsilon_1)\varsigma(u\epsilon_2)
            }
            & n=2 \,,\\[1em]
            \dfrac{1}{u}
            \left(\prod_{i=1}^3\varsigma(u\epsilon_i)\right)
            \left(
                \left(\sum_{i=1}^3\kappa(u\epsilon_i)\right)^2
                -\frac14
            \right)
            & n=3 \,.
        \end{cases}
    \end{equation}
    In particular, (thm: lamg lamg-1 limit of the paper) follows. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, the following statements hold.
        \begin{enumerate}[label=(\roman*)]
                \item For every $z\in\C^+$, the MDE \eqref{eq:intro_mde} has a unique solution $\Pi$ satisfying $\Im\Pi(z)>0$ and $\Im(z^{-1}\Pi_{11}(z))>0$. The map $z\mapsto\Pi(z)$ is holomorphic on $\C^+$.
                      There exists a unique probability measure $\bnu$ such that
                      \begin{align}
                              m(z)=\int_{[0,\infty)}\frac{\bnu(\dd x)}{x-z}, \qquad z\in\C^+. \nonumber
                      \end{align}
                      The measure $\bnu$ has support contained in $[0,C_*]$ for some constant $C_*>0$. Moreover, $\sup\supp\bnu\sim1$.
                \item The measure $\bnu$ is absolutely continuous with respect to Lebesgue measure on $(0,\infty)$ and $\bnu(\{0\})=(1-M/N)\mb{1}(M/N\leq1)$.
                      More precisely,
                      \begin{align}
                              \bnu(\dd E)=\bnu(\{0\})\delta_0(\dd E)+\rho(E)\mb 1(E>0)\dd E, \nonumber
                      \end{align}
                      where
                      \begin{align}
                              \rho(E)=\frac{1}{\pi}\lim_{\eta\downarrow0}\Im m(E+\ii\eta). \nonumber
                      \end{align}
                      The density $\rho$ is locally $1/3$-H\"older continuous on $(0,\infty)$ and real analytic on the open set $\{E>0:\rho(E)>0\}$.
                \item The functions $m$ and $g$ defined in \eqref{eq:mg} extend uniquely to locally $1/3$-H\"older continuous functions on $\{E+\ii\eta:E>0,\ \eta\geq0\}$.
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 14 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Assume that~\eqref{co:3},~\eqref{co:6} and~\eqref{co:7} are satisfied. Then
\begin{equation*}
\E\big[|\hat{I}_{t}^{(n)}|^{p}\big] \leq e^{k_{p,j,n}t}\E\big[\xi_{0}^{p}\big] + e^{l_{p,j,n}t}t\max_{i=0,\dots,j}\hat{b}_{0}(t_{i,n},N(t_{i,n}))
\end{equation*}
for all $n\in\N$, $j\in\{0,\dots,k_{n}-1\}$ and $t\in [t_{j,n},t_{j+1,n}]$ with the two non-negative constants
\begin{align*}
k_{p,j,n} &:= \max_{i=0,\dots,j} \big((p-1)\hat{b}_{0} + p(\hat{b}_{k+3} + c_{p}l^{2})\big)(t_{i,n},N(t_{i,n})),
\\
l_{p,j,n} &:= \max_{i=0,\dots,j} \big(2(p-1)\big(\hat{b}_{0} + c_{p}l^{2}\big) + (2p-1)\hat{b}_{k+3}\big)(t_{i,n},N(t_{i,n})).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition eq:mu-mixture of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[proposition]{prop:moment-law}
Fix an integer \(q\ge1\) and \(\sigma>1\).  There exists \(\varepsilon_0>0\) such that, for every \(0<\varepsilon<\varepsilon_0\), one can find a symmetric compactly supported \(C^\infty\) density \(\nu\) for which
\begin{equation}
 \mu=\varepsilon\mathcal N(0,\sigma^2)+(1-\varepsilon)\nu
\end{equation}
has the same moments as \(\mathcal N(0,1)\) through order \(2q\).  The density of \(\mu\) is strictly positive and \(C^\infty\), and \(\mu\) is sub-Gaussian.

