[Theorem 5 (Finite-time convergence of the unnormalized latent recursion) of arXiv:2608.22636, 'Q-Learning with Stable Infinite-Dimensional \\Linear Function Approximation'] Suppose Assumptions~\ref{assump:mdp}, \ref{assump:mix},
\ref{assump:stable_kernels}, and \ref{assump:stepsizes} hold. Moreover, choose $\alpha_{\mrm U}c_\wedge(1-\gamma)=:\lambda_\mrm U>1$ and set 
\begin{equation}
        \epsilon_n^{\mrm U}
        := \sqbk{(n+n_0^\mrm U)\crbk{ 2L_{0,\rho} + 5L_{\kappa,\rho}} \log\!\crbk{
        \frac{5 (n+n_0^{\mrm U})}{n_0^{\mrm U} }}}\inv.

\end{equation}
Then, for every $\delta\in(0,1)$,  with probability at least $1-\delta$, 
\begin{equation}
\begin{aligned}
        \norm{\theta_n^{\mrm U}-\theta^*}&\le
        \frac{3}{1-\gamma}
        \sqbk{\frac{17 n_0^{\mrm U}}{n+n_0^{\mrm U}}}^{\lambda_{\mrm U}} +
        \frac{328\tmix}{c_\wedge (1-\gamma)^2}
        \sqbk{
        \sqrt{\frac{\alpha_\mrm U(\cL_n^\mrm U(\delta) + \log\cN_\rho(\epsilon_n^\mrm U))}{n+n_0^{\mrm U}}}
        +
        \frac{\alpha_{\mrm U}^{2}}{(\lambda_{\mrm U}-1)(n+n_0^{\mrm U})}}
\end{aligned}

\end{equation}
simultaneously for all $n\ge 16\alpha_\mrm U$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition e.Stratification of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] We say that ${\mathbb G}$ is a \emph{Carnot group} of step $k$ if ${\mathbb G}$  is a connected and simply connected Lie group whose Lie algebra $\mathfrak{g}$ is \emph{stratified}, that is, there are non-trivial linear subspaces $V_1,\ldots, V_k$ of $\mathfrak{g}$ such that
\begin{align*}
\mathfrak{g}=V_{1}\oplus\cdots\oplus V_{k},
\end{align*}
and
\begin{align}
& \left[V_{1}, V_{i-1}\right]=V_{i},\hskip0.1in  V_{i} \neq \{0\}, \hskip0.1in 2 \leqslant i \leqslant k,
\notag
\\
& [ V_{1}, V_{k} ]=\left\{ 0 \right\}.
\end{align}

[Theorem thm:resultunknownmask of arXiv:2602.11129, 'Information-Theoretic Thresholds for Bipartite Latent-Space Graphs Under Noisy Observation'] Consider any fixed $p \in (0,1)$. Then, the following holds whenever $d \gg \log(n)^3$.

    \vspace{0.5em}
    If $p \neq \frac{1}{2}$ then:\hspace{1em} $\begin{aligned}[t]
            \dtv{\mathbb{W}(n, m, q, p, d)}{ \mathbb{M}(n, m, p)} &= \begin{cases} 1 - o(1) & \text{if } d \ll nmq^4  \hspace{1.3cm} \text{ or } \hspace{.1cm} d \ll m\sqrt{n}q^2   \\
            o(1) & \text{if } d \gg nmq^4\log(n) \hspace{.1cm} \text{ and } \hspace{.1cm} d \gg m\sqrt{n}q^2 \log(n)
            \end{cases}
        \end{aligned}$

    \vspace{0.5em}
    If $p = \frac{1}{2}$ then:\hspace{1em} $\begin{aligned}[t]
            \dtv{\mathbb{W}(n, m, q, p, d)}{ \mathbb{M}(n, m, p)} &= \begin{cases} 1 - o(1) & \text{if } d \ll nmq^4 \\
            o(1) & \text{if } d \gg nmq^4\log(n)
            \end{cases}
        \end{aligned}$

    \vspace{0.5em}
    \noindent Here, $o(1)$ denotes a function that tends to zero as $n \rightarrow \infty$. Recall further that $m \ge n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lambda close then also w close of arXiv:2603.17858, 'Decay of correlations and zeros for the hard-core model'] Given $\lambda >0$, $C>0$ and $\alpha\in(0,1)$ there exists $C'>0$ such that the following holds. Given sequences $(\lambda_n)$ and $(\widehat\lambda_n)$ in $(0,\lambda]$ satisfying $|\lambda_n-\widehat\lambda_n|<C\alpha^n$ for all $n\in \mathbb N$, the associated orbits $(w_n)$  and $(\widehat w_n)$ satisfy
    \begin{equation*}
        |w_n-\widehat w_n|\leq C' \alpha^n\quad\text{for all }n\in \mathbb N.
    \end{equation*}

