[Proposition prop:approx-fixed-point of arXiv:2608.18293, 'Critical tensor covariance at the Marchenko--Pastur threshold'] For each fixed $z\in\mathbb{C}_+$,
\begin{equation}
  1+zm_n(z)
  =m_n(z)\frac1m\sum_{\alpha=1}^m
  \frac{R_{n,\alpha}}
  {1+c_nR_{n,\alpha}m_n(z)}
  +o_p(1).

\end{equation}

[Coro of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] The equivalent assertions from Theorem (right of the paper) are equivalent to: 
\begin{enumerate}
\item[\rm(5)] $F$ is closed and $\check{R}_\alpha$ is injective on $C_b(X)$ for each $\alpha\geq 0$.
\end{enumerate}

[Definition 55 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let $\mathfrak{j}:=\lfloor (\frac12+\delta)\log_2 N\rfloor$ denote the largest integer such that $2^{\mathfrak{j}} \le N^{1/2+\delta}$. For each $j \in [0, \mathfrak{j}]$, let $a_j$ denote the minimal integer with $q_{a_j} < \max \{2^j N^{5000K\delta-1}, N^{M\delta-1} \}$; observe that the sequence $(a_j)$ is non-increasing in $j$. For each $j \in [0, \mathfrak{j}]$ and $i \in [0, a_j]$, define the sequence $\mathsf{T}_{i,j}$ inductively (starting at $(i,j) = (0, \mathfrak{j})$, and then increasing in $i \in [0, a_j]$ and decreasing in $j \in [0, \mathfrak{j}]$) by setting 
\begin{flalign*} 
	\mathsf{T}_{0,\mathfrak{j}} = N^{2 + M^2 \delta}; \quad \mathsf{T}_{i+1,j} = \mathsf{T}_{i,j} + q_i^{-2/3} N^{4/3 + M^2\delta}; \quad \mathsf{T}_{0,j} = \mathsf{T}_{a_{j+1},j+1},
\end{flalign*} 
observing that
\begin{eqnarray}

	\mathsf{T}_{i+1,j} = \mathsf{T}_{i,j} + \frac{q_i-q_{i+1}}{ q_i} \cdot N^{2+ (M^2+M) \delta}.  
\end{eqnarray}

[Corollary 17 of arXiv:2608.06038, 'Efron type identities\\ for stopping sets and Poisson hulls'] For $B\in\cX_0$ we have
  \begin{equation}

    \Var \partial\eta(B)
    =\Var \lambda_{[\eta]^c}(B)+\BE \partial\eta(B) -2 \,\BE \int_B\I\{x\notin[\eta]\}
    \lambda_B\big([\eta+\delta_x]\setminus[\eta]\big)\,\lambda(dx).
  \end{equation}

[Defn 16 of arXiv:2605.07050, 'Universality of the fluctuations of the free energy in generalized Sherrington--Kirkpatric'] We assume that $\Omega = \Omega'_N \cap \Omega'' \cap \Omega_\caX^\epsilon$, where $\Omega'_N$ is the event in Lemma \ref{lem:Gaussian_second_moment}, $\Omega''$ in \eqref{eq:Omega''}, and $\Omega_\caX^\epsilon$ in Proposition \ref{prop:main}. Note that $\Omega$ is high probability with respect to $\caX$ such that
\begin{itemize}
	\item Lemma \ref{lem:Gaussian_second_moment} holds with $\Omega$,
	\item for the event $\Omega''$, $\Omega \subset \Omega''$, and
	\item the event $\Omega$ is symmetric in the sense that $\Omega$ holds with $(x_1, \dots, x_{i-1}, -x_i, x_{i+1}, \dots, x_N)$ if $\Omega$ holds with $(x_1, \dots, x_{i-1}, x_i, x_{i+1}, \dots, x_N)$ for any $1\le i \le N$.
\end{itemize}

[Corollary 3 (Noncentral chi-square HCM range) of arXiv:2606.22066, 'A Bessel-zero obstruction to hyperbolic complete monotonicity of noncentral chi-square den'] Let \(\mu>0\) and \(\lambda\ge0\).  The noncentral chi-square density \(\chi_{\mu,\lambda}\) is hyperbolically completely monotone if and only if
\begin{equation}
\lambda=0.
\end{equation}
Thus the HCM range is exactly the central gamma line.

