[Definition 3 of arXiv:2607.22416, 'A multi-player optimal stopping game based on a spider Brownian bridge'] We say that $(\tau^{*},\sigma^{*}) \in \sT^\TT \times \sT^\TT$ is a subgame perfect Nash equilibrium of threshold-type if for all $t\in[0,1)$ and $x=X_{t}\in\mathbb{R}$, the stopping times $\tau^{*}_t$ and $\sigma^{*}_{t}$ satisfy  
    \begin{equation*}
        \begin{split}
            R_{1}(t,x;\tau_{t}^{*},\sigma_{t}^{*})=\sup_{\rho \in \sT_t} R_{1}(t,x;\rho,\sigma^{*}_{t}),  \\
            R_{2}(t,x;\tau^{*}_{t},\sigma^{*}_{t})=\sup_{\rho \in \sT_t} R_{2}(t,x;\tau^{*}_{t},\rho).
        \end{split}
    \end{equation*}

[Proposition 23 of arXiv:2605.04359, 'Well-posedness of reflected BSDEs with default time and irregular barrier: An application '] Let $(Y^j,Z^j,U^j)$ be the unique solution of the RBSDE \eqref{basic equation lower} associated
	with data $(\xi^j,f^j)$ for $j \in \{1,2\}$ satisfying assumptions \textbf{(H1)}, \textbf{(H2)}. Then, for any $\beta >2$, there exists a constant $\mathfrak{c}_{\beta}>0$ such that, $s \in [0,T]$,
	\begin{equation*}
		\begin{split}
			&\mathbb{E}\left[\sup_{s \leq t \leq T}e^{\beta A_t} \left| Y^1_t-Y^2_t \right|^2 \mid \mathcal{F}_s  \right]\\
			& \leq \mathfrak{c}_{\beta}\left(\mathbb{E}\left[e^{\beta A_T}\left| \xi^1-\xi^2\right|^2 \mathcal{F}_s \right]\right.\\
			&\qquad \qquad \left.+\mathbb{E}\left[ \left.\int_{s}^{T}  e^{\beta A_r}\left|\dfrac{f^1\left(r,Y^2_r,Z^2_r,U^2_r\right)-f^2\left(r,Y^2_r,Z^2_r,U^2_r\right) }{\alpha_r}\right|^2 dr \right| \mathcal{F}_s\right]  \right).
		\end{split}
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 35 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $0<\gamma<1$, $\alpha\in\R$ and let $\D^{\mathsf s}_{\gamma}(\Delta_T^3;B_\alpha)$ be a subcritical admissible selection domain in the sense of Definition~\ref{def:admissible-selection-domain}.  Then the dyadic recursion above extends uniquely by continuity to a continuous linear map
\begin{equation*}
\hat\Lambda^{\mathsf s}_{S,\gamma,\alpha}:\D^{\mathsf s}_{\gamma}(\Delta_T^3;B_\alpha) \to C^{\gamma}(\Delta_T^2;B_\alpha), \quad H\mapsto \hat\Lambda^{\mathsf s}_{S,\gamma,\alpha}H:= R^{\mathsf s}(H),
\end{equation*}
satisfying
\begin{equation}

\hdd\hat\Lambda^{\mathsf s}_{S,\gamma,\alpha}H=H.
\end{equation}
Moreover,
\begin{equation}

\norm{\hat\Lambda^{\mathsf s}_{S,\gamma,\alpha}H}_{\gamma,\alpha}\le C_{\gamma,\theta,T,S,\mathsf s}\norm{H}_{\gamma,\alpha}.
\end{equation}
For an individual defect outside a fixed linear domain, the same estimate holds with the right-hand side replaced by $C_{\gamma,\theta,T,S}(\norm{H}_{\gamma,\alpha}+C_H)$.

[Theorem 2 (Rank-uniform integer-valued coefficients) of arXiv:2608.29585, '2608.29585'] For every zero-framed knot $K$, there is a unique sequence
$G_k(K;A,q)\in\Z[A^{\pm1},q^{\pm1}]$, $k\ge1$, such that
\begin{equation}
 \HH_r(K;A,q)
 =1+\sum_{k=1}^{r}
 \qbinom{r}{k}\{r+k-1;A\}_k\{-1;A\}G_k(K;A,q)
 \qquad(r\ge0).
\end{equation}
Set
\begin{equation}
 \mathsf H_0(K;A,q)=1,\qquad
 \mathsf H_k(K;A,q)=\frac{\{-1;A\}G_k(K;A,q)}{\{k\}!}
 \quad(k\ge1).
\end{equation}
Then, for every $k\ge0$,
\begin{equation}
 \mathsf H_k(K;A,q)\in\mathscr I_q^{\ge2},\qquad
 \mathsf H_k(K;q^n,q)=H_k^{(n)}(K;q)
 \quad(n\ge2).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2609.01098, 'Gaussian upper bounds for averaged heat semigroups on graphs'] Let  $C,r_0>0$ and $n>2$ and assume that, for all $B(r)\subset  X$, $r\geq r_0$, and all $U\subset B(r)$, we have the Faber-Krahn inequality
\begin{equation*}
\lambda(U):=
\inf_{0\neq f\in\mathcal{C}_c(U)}
\frac{\cE(f)}{\|f\|_2^2}\geq \frac{C}{r^2}\left(\frac{m(B(r))}{m(U)}\right)^\frac{2}{n}.
\end{equation*}
Then there are constants $C'=C'(C,n)>0$ and $r'=r'(r,S)>0$ such that,
for all $x,y\in X$ and $t\geq r^2\geq r'^2$, we have
\begin{multline*}
\mathcal{P}_r(t,x,y)
 \leq 
\frac{C'}{\sqrt[2q(t)]{m(B_{x}(r))m(B_{y}(r))}}\\
\cdot 
\frac{\left(1\vee S^{-2}\sqrt{\rho(B_x(r),B_y(r))^2S^2+t^2}-t\right)^{\frac{n}{2}}}{\sqrt[\frac{2q(t)}{q(t)-1}]{m(B_x(\sqrt t))m(B_y(\sqrt t))}}
 \euler^{-S^{-2}t\zeta(\rho(B_x(r),B_y(r))S/t)}.
\end{multline*}
Moreover, for all $x\in X$ and $r_0\leq r_1\leq r_2$, we have
\begin{equation*}
m(B_x(r_2))\leq C'\left(\frac{m(B_x(r_2))}{m(B_x(r_0))}\right)^{\sqrt[4n]{{S}/{r_1}}}
\left(\frac{r_2}{r_1}\right)^{n} m(B_x(r_1)).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop prop3 of arXiv:2606.28631, '\Large \bf On the maximal displacement of subcritical branching random walks with stretche'] Assume {\bf(H2)}.  Let $\delta, \beta \in (0,1)$ be fixed.

	(i) For all $k\in \mathbb{N}$ with $k\delta\geq K_0$ and $x>K_0$, 
	\begin{align}
		&\frac{e^{\lambda x^b}}{\ell(x) x^a } \sum_{n=1}^\infty \beta^{n}\widetilde{\mathbb{P}}\left(\max_{1\leq j \leq n} S_j \leq x, x-S_n\in [(k-1)\delta, k\delta) \right) \lesssim_\beta  \frac{e^{\lambda (k\delta)^b}}{\ell(k\delta) (k\delta)^a }.
	\end{align}
	(ii) For each $0\leq p< q$, 
	\begin{align}
		& \lim_{x\to+\infty} \frac{e^{\lambda x^b}}{\ell(x) x^a } \sum_{n=1}^\infty \beta^{n}\widetilde{\mathbb{P}}\left(\max_{1\leq j \leq n} S_j \leq x, x-S_n\in [p, q) \right) \nonumber\\
		&=\frac{1}{\mathbb{E}(e^{\gamma X})}\int_p^q \sum_{j=0}^\infty \frac{\beta^{j+1}}{1-\beta} \widetilde{\mathbb{P}}\left(z> -\min_{0\leq k\leq j} S_k \right)\mathrm{d} z. 
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 8 of arXiv:2605.02420, '\textbf{Large time behavior of critical marked Hawkes processes with heavy tailed marks an'] a) Suppose that Assumption \ref{ass:beta_general} is satisfied and that $f$ is of the form \eqref{e:f_sum} with all $\theta_k$ nonnegative, $f_T$ is given by \eqref{e:fT} with $F_T=T^{1+\beta}$ and $g_T$ is as in Proposition \ref{prop:Laplace}. Then 
 \begin{equation}
 H(g_T(t))\le f_T(t), \qquad \textrm{ for any}\ t\ge 0.

\end{equation}
Moreover, there exists $T_0\ge 1$ (which may depend on $f$)  and $C>0$ such that for any $T\ge T_0$ we have
\begin{equation}
Tg_T(tT)\le C f^{1/(1+\beta)}(t), \qquad t\ge 0.

\end{equation}
 Thus
  \begin{equation}
 \limsup_{T\to \infty}\int_0^\infty g_T(t)dt<\infty.

 \end{equation}
 b) If the number of offspring of a single particle has finite variance and $F_T=T^2$ then \eqref{e:Hg_le_f}-\eqref{e:limsup_g_T}
  follow with $\beta=1$ and $F_T=T^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm wzw of arXiv:2608.29018, 'Sharp Restricted Isometry Thresholds for\\ Global Minima of Rank-Restricted Matrix LASSO'] {WangZhangWang2021}}}]
 Fix integers $k>r_{\star}\ge1$ and write $t=k/r_{\star}$.
Suppose $\operatorname{rank}(X_{\star})\ler_{\star}$ and $\mathcal{A}\in\operatorname{RIP}(\delta,k)$. If
\begin{equation}
\delta<\sqrt{\frac{t-1}{t}},
\end{equation}
then every convex matrix-LASSO solution satisfies 
\begin{equation}
\normF{X_{\lambda}-X_{\star}}\lesssim\sqrt{r_{\star}}\,\lambda+\normtwo{\xi}+\frac{\normtwo{\xi}^{2}}{\sqrt{r_{\star}}\,\lambda},
\end{equation}
where the hidden constant depends only on $\delta$ and $t$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 8 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ be an integer and let $ (X_{N}= I_{p} (f_{N}), N\geq 1)$ with $f_{N}\in H^{ \odot p}$ for every $N\geq 1$. Assume that $(X_{N}, N\geq 1)$ satisfies (\ref{c1}). Let $ (\mathbb{Y}_{N}= (Y_{1,N},..., Y_{d, N}), N\geq 1)$ such that for every $j=1,..., d$, 
		\begin{equation}
			Y_{j, N}= \sum _{q=1}^{N_{0, j}}I_{q} ( g_{q, N} ^{(j)}), \mbox{ with } g_{q, N}^{(j)} \in H ^{\odot q}.
		\end{equation}
		Assume (\ref{c4}), which is equivalent to 
		\begin{equation}

			\mathbf{E}\left[ X_{N} I_{p}(g ^ {(j)}_{p,N})\right]\to _{N \to \infty} \rho _{j}, \mbox{ for } j=1,...,d.
		\end{equation} Then
		\begin{enumerate}
			\item If $\mathbb{Y}_{N} \to _{N \to \infty} \mathbb{Y}$ in $ L^{2}(\Omega)$, then 
			\begin{equation*}
				(X_{N}, \mathbb{Y}_{N})\to \xrightarrow[N\to\infty]{(d)} (Z, \mathbb{Y}),
			\end{equation*}
			where $Z\sim N(0, \sigma ^{2})$ and the characteristic function of the random vector $(Z, \mathbb{Y})$ is given by (\ref{phi}). 
			\item If $\max_{j=1,..., d}N_{0, j}\leq p$ and $ \mathbb{Y}_{N} \xrightarrow[N\to\infty]{(d)} \mathbb{Y}$,  then 
			\begin{equation*}
				(X_{N}, \mathbb{Y}_{N})\xrightarrow[N\to\infty]{(d)}  (Z, \mathbb{Y}),
			\end{equation*}
			where $Z\sim N(0, \sigma ^{2})$ and the characteristic function of the random vector $(Z, \mathbb{Y})$ is given by (\ref{phi}). 
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

