[Proposition lemma:cif of arXiv:2604.17253, 'Large Deviations for the Nonlinear Schrödinger Equation with Randomized Quasi-Periodic Ini'] For all $k\geq1$, the following estimates hold: 

\begin{enumerate}[label=(\arabic*)]

\item 
\begin{align}
\mathfrak C^{(k,\gamma^{(k)})}(\spadesuit^{(k)})
=\prod_{j=1}^{2\sigma(\gamma^{(k)})}\left\{c(\boldsymbol m^j)g_{\boldsymbol{m}^j}\right\}^{\ast^{[j-1]}}.
\end{align}
Moreover, under the decay property (equation eq:decayall of the paper), it holds that
\begin{align}
|\mathfrak C^{(k,\gamma^{(k)})}(\spadesuit^{(k)})|&\leq
{\varepsilon^{-(1+\eta)\sigma(\gamma^{(k)})}}\prod_{j=1}^{2\sigma(\gamma^{(k)})}\tnorm{\boldsymbol{m}^j}_{-(\rho-\kappa)}\nonumber\\
&={\varepsilon^{-(1+\eta)\sigma(\gamma^{(k)})}}
\prod_{j=1}^{2\sigma(\gamma^{(k)})}\prod_{s=1}^{d}\prod_{q=1}^{\nu_s}\left(1+|m^{j}_{s,q}|\right)^{-(\rho_{s,q}-\kappa_{s,q})}; 

\end{align}

\item 
\begin{align}
|\mathfrak I^{(k,\gamma^{(k)})}(t,\spadesuit^{(k)})|\leq\frac{t^{\ell(\gamma^{(k)})}}{\mathfrak D(\gamma^{(k)})},
\end{align}
where
\begin{align*}
\mathfrak D(\gamma^{(k)}) =
\begin{cases}
1, & \gamma^{(k)}=0\in\Gamma^{(k)},\ k\geq1,\\[4pt]
1, & \gamma^{(1)}\in\Gamma^{(1)},\\[4pt]
\displaystyle \ell(\gamma^{(k)})\prod_{j=1}^3\mathfrak D(\gamma_j^{(k-1)}), & \gamma^{(k)}=(\gamma_j^{(k-1)})\in(\Gamma^{(k-1)})^3; 
\end{cases}
\end{align*}

\item 
\begin{align}
|\mathfrak F^{(k,\gamma^{(k)})}(\spadesuit^{(k)})|\leq {\varepsilon^{\alpha\ell(\gamma^{(k)})}}.
\end{align}

\end{enumerate}

[Defn def:monotonecurve of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Let $\mathcal{G}$ be a $C^0$-foliation on $\mathbb{T}^2$, and $\gamma : S^1 \rightarrow \mathbb{T}^2$ be a piecewise $C^1$ closed embedded curve on $\mathbb{T}^2$. We say that $\gamma$ is \textbf{positively (resp.~negatively) monotone} with respect to $\mathcal{G}$ if $\gamma$ decomposes into finitely many $C^1$ subarcs, each of which is either
\begin{itemize}
    \item Contained in a leaf of $\mathcal{G}$, or
    \item Positively (resp.~negatively) transverse to $\mathcal{G}$
\end{itemize}
and $\gamma$ is not entirely contained in a leaf of $\mathcal{G}$.

[Lemma 18 (Coupling to GFF) of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] Fix~$n>k\ge1$ and~$t>0$. There exists a coupling of the local time $L_t$ and two GFFs~$h$ and~$\tilde h$ on~$\T_n$ such that
\begin{equation}

h\,\independent L_t\quad\wedge\quad\tilde h \,\,\independent\,\,\bigl\{L_t(z)\colon z\in\T_{n-k}\bigr\}
\end{equation}
and such that the following holds almost surely:
\begin{equation}

\forall x\in\T_{n-k}\colon\,\,\tilde h(x) = h(x)
\end{equation}
and
\begin{equation}

\forall x\in\T_n\smallsetminus\T_{n-k}\colon\,\,L_t(x)+\bigl[h(x)-h(z)\bigr]^2 = \Bigl(\tilde h(x)-\tilde h(z)+\sqrt{L_t(z)}\Bigr)^2,
\end{equation}
where we used the shorthand~$z:=\frakm^k(x)$
 to make \eqref{E:3.25} easier to parse. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 55 of arXiv:2608.27630, 'Oriented planar maps and \\ annular mating of trees'] There exists a constant $C_\gamma>0$, such that 
    \begin{equation}
        \|\MA^{1, 0 }(a, b)\| = C_\gamma\frac{b}{a^2+b^2-2ab\cos\theta}.
    \end{equation}

