[Proposition prop.L2FluxDeg2 of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] The following $L^2$ and flux estimates hold for the two-scale expansion $\widetilde{G}_\lambda$:
		\begin{enumerate}
			\item There exists a finite positive constant $C(c_{-},c_{+},\rho)$ such that the  two-scale expansion satisfies
			\begin{equation*}
				\norm{\widetilde{G}_\lambda-\overline{G}_\lambda}^2_{L^2}\leqslant C3^{3m}\expec{\overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda}.
			\end{equation*}
			\item There exists an exponent $\alpha(c_{-},c_{+}, \mathbf{r}) > 0$ and a finite positive constant $C(c_{-},c_{+}, \mathbf{r},\rho)$ such that the following estimate holds for any $V\in L^2$ satisfying $\left\langle V,-{\overbracket[1pt][-1pt]{\mathcal{L}}} V \right\rangle<\infty$:
			\begin{equation*}
				\left|\expec{V,-\mathcal{L}\widetilde{G}_\lambda+{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda}\right|\leqslant C\left\langle V,-{\overbracket[1pt][-1pt]{\mathcal{L}}} V \right\rangle^{\frac{1}{2}}\left(3^{-\alpha m}\expec{\overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda}^{\frac{1}{2}}+3^{7m} \expec{-{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}} \overline{G}_\lambda}^{\frac{1}{2}}\right).
			\end{equation*}
		\end{enumerate}

