[Proposition 9 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] The following estimates hold uniformly for small $\eps$.
\begin{enumerate}[label=\textup{(\roman*)}]
\item If $k>2$ and $4-2k<\delta<0$, then
\begin{equation}
  \norm{S(\omega_\eps)-\pi^*S(\omega)}
  _{C^{0,\alpha}_{\delta-4}}
  \le C\Theta_\eps,
\end{equation}
where \(\Theta_\varepsilon=r_\varepsilon^{3-\delta}+\varepsilon^{2k-2}r_\varepsilon^{4-\delta-2k}\). Moreover,
\begin{equation}
  \Theta_\varepsilon\to0
  \qquad\text{and}\qquad
  \varepsilon^{\delta-2}\Theta_\varepsilon\to0
  \qquad\text{as }\varepsilon\to0.
\end{equation}
\item If $k=2$ and $-1<\delta<0$, then
\begin{equation}
  \norm{S(\omega_\varepsilon)
  -
  \pi^*S(\omega)
  -
  \varepsilon^2 h_S}_{C^{2,\alpha}_{\delta-4}}
  \le Cr_\eps^{4-\delta},
\end{equation}
where \(h_S\) is defined as in Lemma \ref{k2:lem:Green-correction}. Moreover,
\begin{equation}
  r_\varepsilon^{4-\delta}\to0
  \qquad\text{and}\qquad
  \varepsilon^\delta r_\varepsilon^{4-\delta}\to0
  \qquad\text{as }\varepsilon\to0.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 145 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Fix $h>0$ and a base point ${\hat x}_0\ge 0$. Let ${\hat x}_1={\hat x}_1^{[M]}$ be chosen so that
	\begin{align*}
		U_{h;M,Q}'({\hat x}_0)=U_{h;0,0}'({\hat x}_1)
	\end{align*}
	(suppressing from the notation the dependence of $\hat{x}_1$ on $\hat{x}_0$ and $Q$.)
		The choice $M=-2{\hat x}_0-\eta$, for sufficiently small $\eta>0$, has the following property: for each fixed $h'\in(0,h]$, there is a constant
		$c=c(h',h,{\hat x}_0)>0$, such that
		\begin{align}
			\partial_hU_{h';M,Q}({\hat x}_0)-\partial_hU_{h';0,0}({\hat x}_1^{[-2 {\hat x}_0-\eta]})
			\ge cQ\eta.

		\end{align}
                For $0<\varepsilon<h$ one has $\inf\{ c(h',h,{\hat x}_0):h'\in [\varepsilon,h]\}>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 23 of arXiv:2608.24675, 'Towards Liouville Quantum Gravity on fractals'] Let $|\gamma|<\sqrt{d_H/C_0}$. Then, $\mathbb{P}$-a.s. it holds that:
    \begin{enumerate}[wide=0em,itemsep=.25em,label={\rm(\roman*)}]
        \item There exists a unique PCAF $\{A_t^\gamma\}_{t\geq 0}$ with Revuz measure $\nu^\gamma$.
        \item The time-changed process $\{B_t^\gamma\}_{t\geq 0}$ given by~\eqref{E:def_LBM_SG} is a $\nu^\gamma$-symmetric Hunt process with associated Dirichlet form
        \begin{equation}
            \mathcal{E}^\gamma(u,v)=\mathcal{E}(u,v),\qquad\mathcal{F}^\gamma=\mathcal{F}_e\cap L^2(K,\nu^\gamma).
        \end{equation}       
    \end{enumerate}

[Theorem eq:DPalm1 of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For all non-negative measurable functions $f$ on $(\Omega,{\mathcal F })$,
\begin{align}
\mathbb{E}_{{\mathcal V }}^0 [f({\mathcal H })]= \sum_{l\in \{1,2\}}\frac{\Lambda_l}{\lambda_{{\mathcal V }}} \mathbb E_{{\mathcal V }_l}^0 [f({\mathcal H })]+ \sum_{ l\neq r, k\in\{1,2\}} \frac{\Lambda^{(k)}_{l,r}}{\lambda_{\mathcal V }}\mathbb{E}^0_{{\mathcal V }_{l,r}^{(k)}} [f ({\mathcal H })],

\end{align}

in terms of the pure and mixed Palm probability measures $\mathbb E_{{\mathcal V }_l}^0$, for $l\in\{1,2\}$, and $\mathbb{E}_{{\mathcal V }^{(k)}_{l,r}}^0$, for $l\neq r, k\in\{1,2\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

