	\begin{equation}
		\frac{|{\mathbf W}_n^{k}(u) \setminus {\mathbf W}_n^{k,\epsilon}(u)|}{\sqrt{n}} \overset{\mathbb{P}}{\longrightarrow}0,  
	\end{equation}
	in the limit as $n \to \infty$, followed by $k \to \infty$ and finally $\epsilon \to 0$. To this end, we first observe that, in the notation of Lemma~(l:1103.7 of the paper), we have
	\begin{equation}
		\frac{|{\mathbf W}_n^{k}(u) \setminus {\mathbf W}_n^{k,\epsilon}(u)|}{\sqrt{n}} \leq |{\mathbf W}_n^{\widetilde{{\rm D}}}(u)|,	
