[Prop support and density of 231 permuton of arXiv:2604.23751, 'Large deviation principles for pattern-avoiding permutations, and limit shapes for constra'] Let $f\in\mathcal{F}$, and let $\mu_f$ be the unique permuton with RLM curve $f$.
    Assume the following:
    \begin{enumerate}
        \item $f$ is increasing and continuous on $[0,1]$. 
        In particular, there is a unique $x^*\in(0,1)$ such that $f(x^*) = 1-x^*$.
        \item The graph $G_f$ of $f$ is invariant under the symmetry $(x,y) \mapsto (1-y, 1-x)$, that is: 
        \[ \text{for all } x\in[0,1],\quad f(1-f(x)) = 1-x .\]
        \item $f$ is strictly convex.
    \end{enumerate}
    Then $\mu_f$ equals $\mu_\nearrow + \mu_\searrow$ where:
    \begin{itemize}
        \item $\mu_\nearrow$ is the pushforward of the measure with cumulative distribution function (CDF) 
        \[ F_\nearrow : x\in[0,1] \mapsto \left\{
        \begin{array}{ll}
            f(x)
            &\text{ if } x\le x^* \,;\\
            1 + x- 2x^*
            &\text{ if } x\ge x^* \,;
        \end{array}
        \right. \]
        via $x\mapsto(x,f(x))$;
        \item $\mu_\searrow$ is the pushforward of the measure with CDF
        \[ F_\searrow : x\in[0,1] \mapsto \left\{
        \begin{array}{ll}
            x - f(x)
            &\text{ if } x\le x^* \,;\\
            2x^* - 1
            &\text{ if } x\ge x^* \,;
        \end{array}
        \right. \]
        via $x\mapsto(x,1-x)$.
    \end{itemize}
    The support of $\mu_\nearrow$ is the graph $G_f$ of $f$, and the support of $\mu_\searrow$ is the antidiagonal line from $(1,0)$ to $(x^*, f(x^*))$.

[Lemma 17 of arXiv:2606.23383, 'Near-Lipschitz stability of the Kim--Milman flow map'] Suppose $\mu$ satisfies \eqref{theta} with $L_t \defeq L_t(\mu)$ as in \eqref{eq:def-L_t}. For any $\nu \in \cP_2(\R^d)$,\looseness-1
\begin{align*}
\frac{\dd}{\dd t} \bigl(2 L_t^2\, {\mathsf H}(q_t^\nu\mmid q_t^\mu) \bigr)^{1/2} \leq
-\FI(q^\nu_{t}\mmid q^\mu_{t})^{1/2} - \theta_{t}\,\bigl(2 L_{t}^2\, {\mathsf H}(q_{t}^\nu\mmid q_{t}^\mu) \bigr)^{1/2} \,.
\end{align*}

