body:
[Theorem thm:Ikeda-Watanabe of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $X=(X_t)_{t\geqslant 0}$ be a Feller process defined on a locally compact separable metric space $(M,d)$. Assume that there exists a positive kernel $\Pi(x,E)$, $x\in M$, $E\in\mathcal{B}(M)$ such that 
	\begin{enumerate}[leftmargin=*]
		\item  $\Pi(x,E)<\infty$ if $d(x,E)>0$, 
		\item  for any bounded $f\in C(M)$ and a bounded open set $D$ with $d(D,\operatorname{supp}(f))>0$, 
		\begin{align*}
			\frac{P_t f(x)}{t} \mbox{ is uniformly bounded in $x\in D$, $t>0$},
		\end{align*}
		and 
		$\lim_{t\downarrow 0}\frac{P_t f(x)}{t}=\int_M f(y)\Pi(x,dy)$ for every $x\in D$,
	\end{enumerate}
	then for any open set $\Omega\subset M$, $E\in\mathcal{B}(M)$ satisfying $d(E,\Omega)>0$, and $\lambda>0$,
	\begin{align}
		\mathbb{E}_x\left[e^{-\lambda \tau_\Omega}, X_{\tau_\Omega}\in E\right]=\int_\Omega G^\lambda_\Omega(x, dy)\Pi(y,E),
	\end{align}
	where $G^\lambda_\Omega(x,E)=\int_0^\infty e^{-\lambda s} p_\Omega(s,x,E)ds$. Therefore, the joint distribution of $(\tau_\Omega, X_{\tau_\Omega})$ on the event $\{X_{\tau_\Omega}\neq X_{\tau_\Omega -}\}$ is given by 
	\begin{align*}
		\mathbb{P}_x\left(\tau_\Omega\in ds, X_{\tau_\Omega}\in dz\right)=\int_\Omega p_\Omega(s,x,dy)\Pi(y, dz).
	\end{align*} 
	Moreover, (equation eq:Laplace_transform of the paper) holds for $\lambda=0$ if $\mathbb{E}_x[\tau_D]<\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm intro local curve GW g formula of arXiv:2609.02409, 'Membranes and Maps'] Suppose that $\mathsf{T}$ acts on the fibers of the local curve $Z$ with weights $\epsilon_2,\ldots,\epsilon_5$ satisfying the Calabi--Yau condition $\sum_i \epsilon_i=0$. If (conj:GW:vertex of the paper) holds for $n=1$, then
    \begin{equation}

        \GWargs{Z}{\mathsf{T}}{[C]}
        =
        \prod_{i=2}^5 \big(
            2 \sinh \tfrac{\epsilon_i}{2}
        \big)^{g_C - 1 - \deg \cL_i}
        =
        \hat{\mathsf{A}}_{\mathsf{T}}\big( \overline{M}_{g_C}(Z,[C]) \big) \,.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:quadratic-martingale-proof of arXiv:2608.18320, 'Asymptotics for Beta-Splitting Trees via Homogeneous Fragmentations and Meromorphic Potent'] For every $\beta>-2$,
    \begin{equation}
            W_\beta(t)=e^{r_\beta t}S_2(t)\longrightarrow W_\beta(\infty),
