[Lemma 8 of arXiv:2606.03534, 'Construction and simulation of a path-valued model of dendrite development'] Recall that $\gamma_s^\ell(dp, dq)$ is the joint distribution of the pair $(p,q)=(\inf_{0\leq r \leq s} \ell_r, \ell_s)$ at time $s$ for a length process started at $\ell$. When the length process $\ell_t$ is a Brownian motion absorbed at $\ell=0$ we have, 
\begin{align*}
    \gamma_t^\ell(dp,dq) &= \frac{2(\ell+q-2p)}{\sqrt{2\pi t^3}} \, \exp\bigg( -\frac{(\ell+q-2p)^2}{2t}\bigg) \, \mathds{1}_{\{ 0 < p < \ell\wedge q \}}\,dp \, dq \, \\
    &+ 2\Bigg(1 - \Phi\bigg(\frac{\ell}{\sqrt{t}}\bigg)\Bigg) \delta_{(0,0)}(dp,dq) \,.
\end{align*}

[Lemma 23 of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] \label[lemma]{lem:density-bound}
Let $\delta \in (1,2)$ and $\alpha=1/h$.  There are $C,h_0>0$, depending only on the model parameters, such that the driftless kernel's one-step probability of landing in a near-boundary layer is bounded uniformly in the starting point,
\begin{equation}
  \sup_{x\ge0} P_x^{G=0}\bigl(u_{T_\alpha}\in(0,\epsilon]\bigr)\ \le\ C\,\epsilon^\delta,
  \qquad 0<\epsilon\le 2\sqrt h,\ \ h\le h_0 .
\end{equation}
Consequently, if $G'\in C_{\mathrm b}([0,\infty))$, then $\mathcal{R}_h\subseteq(0,\|G'\|_\infty h]$ gives the one-step routing bound $\sup_{x\ge0}K_h(x,\mathcal{R}_h)=O(h^\delta)$; and for any stationary distribution $\pi_h$ of $K_h$ (\cref{thm:ula-exists}), stationarity gives $\pi_h(\mathcal{R}_h)\le\sup_{x\ge0}K_h(x,\mathcal{R}_h)=O(h^\delta)$.

[Proposition q_inverse of arXiv:2608.07236, 'Negative association of Busemann functions \\in exponential last-passage percolation'] We have
\eeq{ 
h = \begin{cases}
\sigma_m \sigma^m h &\text{if $\textup{\texttt{slope}}_m(h) >\textup{\texttt{slope}}_{m+1}(h)$}\\
\sigma^m \sigma_m h &\text{if $\textup{\texttt{slope}}_m(h) <\textup{\texttt{slope}}_{m+1}(h)$}.
\end{cases}
} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 128 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] For any $x \in [0, a]$, let $\gamma_x = \gamma (x) \in \mathbb{R}_{\ge 0}$ denote the minimal real number such that $(x, \gamma_x) \in \mathfrak{A}_{q;a,b,c}$ is on the arctic boundary. In this way, we parameterize the (union of the southwest and south parts of) the arctic boundary by $(x, \gamma_x)_{x \in [0, a]}$. We further define $\xi_x = \xi(x)$ by  
	\begin{flalign*}
		\xi_x = u_x ( \gamma_x), \quad \text{so that} \quad  \gamma_x = z_x ( \xi_x)
	\end{flalign*}
	where the latter holds since we more generally have $z_x (u_x (y)) = y$, by \cite[Equation (222)]{DLE}.\footnote{Indeed, \cite[Equation (222)]{DLE} (with the $(\mathsf{q},\kappa)$ there equal to $(\mathfrak{q}^{-1},0)$ here) gives $q^{z_x (u_x(y))} = V(u_x(y)) - q^{x} U(u_x(y))$; by \eqref{equationu} (and \cite[Remark 5.6]{DLE}), this yields $z_x (u_x (y)) =y$.} We frequently abbreviate $\xi_x' = \xi' (x)$, $\gamma_x' = \gamma' (x)$, and $\gamma_x'' = \gamma'' (x)$.

[Lemma lem:e1 of arXiv:2412.01995, 'Exciting games and Monge-Amp\`{e}re equations'] For any $N \in \mathbb N$, we have that
\begin{align}
\lVert g^n \rVert_{C^1(\bar \Omega_N)} \leq K(N) \quad \text{for all $n \geq N+10$},
\end{align}
where $K(N)$ is a positive constant depending only on $N$.

