[Theorem thm:MSlin_gen of arXiv:2604.28068, 'Mean-square Stability and Bifurcations for Dissipative SDEs'] Let ${\widetilde{Y}}$ be the solution of (equation eq:sdeLinMult of the paper), $M$ be as defined in Lemma (lem:arnold of the paper) and let $P$ be the solution of (equation eq:Pode of the paper). 
Construct a new vector-valued process $Q(t):=[\mathrm{vec}(P(t))^T,M(t)^T]^T$, $t\geq 0$, and set 
\begin{align*}
\tilde{A}&:=(\mathbb{I}_d\otimes A)+(A\otimes\mathbb{I}_d);
\\ \tilde{B}_i&:=(\Gamma_i\otimes B_i)+(B_i\otimes \Gamma_i);
\\ \tilde{C}_i&:=(\Gamma_i\otimes \mathbb{I}_d)\Gamma_i.
\end{align*}
Then $Q$ satisfies the linear ODE
\begin{equation}
Q'(t)=\mathbb{A} Q(t)+S,
\end{equation}
where $\mathbb{A} \in\mathbb{R}^{(d^2+d)\times(d^2+d)}$ is the block matrix  
\begin{equation}
\mathbb{A}:= \begin{pmatrix}
    \tilde{A} +\sum_{i=1}^m B_i\otimes B_i& (\mathbb{I}_d\otimes \Lambda)+(\Lambda\otimes\mathbb{I}_d)+\sum_{i=1}^m\tilde{B}_i\\
    0 & A
\end{pmatrix},
\end{equation}
and $S\in\mathbb{R}^{d^2+d}$ is the stacked vector $\left[\left(\sum_{i=1}^m\tilde{C_i}\right)^T,\,\Lambda^T\right]^T$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:M2_bound of arXiv:2605.21265, 'The non-Hermitian minor process'] Consider $|z_j|\le\sqrt{x_j}-\theta$ and $w_j\in \mathbf{C}\setminus\mathbf{R}$ for $j=1,2$. For any $B_1,B_2\in\mathbf{C}^{(2k_1)\times (2k_1)}$ it holds that
\begin{equation}
x_1\left\vert\left\langle M_{1\widetilde{2}}^{B_1}B_2\right\rangle\right\vert \le \|B_1\|\|B_2\|\sqrt{\frac{x_1\pi\rho_1}{\eta_1}\frac{x_2\pi\rho_2}{\eta_2}}.

\end{equation}
Assume further that $|\Re w_j|\le c\eta_j$ for sufficiently small $c>0$. Then we have
\begin{equation}
x_1\left\vert \left\langle M_{1\widetilde{2}}^{E_\sigma}B\right\rangle\right\vert + x_1\left\vert \left\langle M_{1\widetilde{2}}^{B}E_\sigma\right\rangle\right\vert \lesssim \left(|x_1-x_2|+|z_1-z_2|+|w_1|+|w_2|\right)\|B\|\sqrt{\frac{x_1\pi\rho_1}{\eta_1}\frac{x_2\pi\rho_2}{\eta_2}},

\end{equation}
for $\sigma:=\mathrm{sgn}(\Im w_1\Im w_2)$ and $E_\sigma:=E_\sigma^{(k_1)}$. This bound holds uniformly in $x_j\in [c_0,1]$ with $x_1\le x_2$, $|z_j|< \sqrt{x_j}$, for any fixed $c_0>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2609.01296, 'Asymptotic safety regions for Gabor frames generated by Hermite functions'] For every $\eta,\delta>0$ and every $\rho\in(0,\frac12)$, there exists $n_{\eta,\delta,\rho}\in\N$ such that, for every $n\geq n_{\eta,\delta,\rho}$, the region
    \begin{equation}
        \left\{
            (a,b)\in\R_+^2:
            ab\leq n^{-\frac23-\eta}
        \right\}
        \cup
        \left\{
            (a,b)\in\R_+^2:
            ab\leq\frac12-\rho,\quad
            \min\{a,b\}\leq n^{-\frac12-\delta}
        \right\}
    \end{equation}
    is contained in the frame set of the $n$-th Hermite function. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 (Center-bias expansion) of arXiv:2609.01319, 'Matched Queries for Curvature and Density at Branching Junctions'] Under \cref{ass:jet,eq:provisional-center}, uniformly on compact normalized query sets,
\begin{equation}
\cD^{c_\sigma}_{\sigma,\lambda}(z)
=G(z)-\frac{1}{\lambda}\nabla F_0(z)b+O(\sigma^\alpha),

\end{equation}
where $\nabla F_0$ is the $D\times D$ Jacobian of the tangent score. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2608.26619, 'Uniqueness of Positively Curved Ancient Ricci Flows on Surfaces with Boundary'] For all $t<0$, 
    \begin{equation}
        A(t) \leq D\cdot L(t) \leq \frac{2\pi}{k}D.
    \end{equation}
    Moreover we have
    \begin{equation}
        \lim_{t\to -\infty}Q(t) := \int_{\bD} R\, dA_{g(t)} =0,\quad \lim_{t\to -\infty}L(t) =\frac{2\pi}{k}.
    \end{equation}

[Theorem 33 (Subsequential convolution factorization) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] Fix $Q,d<\infty$.  Let
\[
 X_{n,a}
 =\sum_{q=1}^{Q}I_q^{W_n}
 \left(\frac{x_{n,a,q}}{\sqrt{q!}}\right),
 \qquad
 \sup_n\sum_{a,q}\norm{x_{n,a,q}}^2\le R^2.
\]
There is a subsequence for which the factorization in
\eqref{overview:eq:noncanonical} holds.  More precisely, the feedback
construction gives
$
 X_n=A_n^J+B_n^J
$
such that, on one limiting probability space,
\begin{equation}
 A_n^J\Longrightarrow A^J\quad(J\text{ fixed}),
 \qquad
 A^J\longrightarrow A_*\quad\text{in }L^2,

\end{equation}
and, after extracting $\Cov(X_n)\to\Sigma$,
\begin{equation}
 C=\Sigma-\Cov(A_*)\succeq0.

\end{equation}
For every $t\in\R^d$,
\begin{align}
 &\limsup_{n\to\infty}
 \left|
 \E e^{it\cdot X_n}
 -\E e^{it\cdot A_*}e^{-\frac12t^{\mathsf T}Ct}
 \right|\notag\\
 &\quad\le
 \frac{\sqrt5}{2}|t|^2R^2
 \sqrt{\frac{\mu_Qa_Q}{J}}
 +|t|\norm{A^J-A_*}_2
 +\frac{|t|^2}{2}\norm{C^J-C}_{\op},

\end{align}
where $C^J=\Sigma-\Cov(A^J)$.

[Thm 2 (\cite{Quasi}, Theorem 1) of arXiv:2606.07194, 'Survival Probability of Markov Linear Reccurence Sequence in a Random Environment: Subcrit'] Let $\{X_n\}$ be a positive Markov chain with certain extinction.
Suppose that there exists a set $K\subset \mathbb{N}$ such that:
\begin{enumerate}
\item[QS1)] for some positive $C_1$, $\varepsilon$ and all $n\in \mathbb{N}$ 
$${\bf P}(X_i\not\in \{0\}\cup K, 1\le i\le n|X_0=j)\le C_1 (R+\varepsilon)^{-n},\ j\in K;$$
\item[QS2)] for some $j\in K$, $C_2>0$ and for all $i\in K$ and $n\in \mathbb{N}$
$${\bf P}(T>n|X_0=i)\le C_2 {\bf P}(T>n|X_0=j);$$
\item[QS3)] for some finite subset $K_1\subset \mathbb{N}$, a natural number $n_0$ and a positive constant $C_3$ for all $i\in K$ 
$${\bf P}(\exists j\le n_0:\ X_j\in K_1|X_0=i)\ge C_3.$$
\end{enumerate}
Then
\begin{enumerate}
\item[1)] $\pi P_{+} =  R^{-1} \pi$, where $\pi$ is a probability distribution on $\mathbb{N}$;
\item[2)] for some non-negative function $f:\mathbb{N}\to \mathbb{R}$ we have $P_{+} f = R^{-1} f$, and $\sum_{i>0} f(i) \pi_i=1$;
\item[3)] for all $i\in \mathbb{N}$ we have
\begin{equation}

\lim_{n\to\infty} R^{-n} {\bf P}(T>n|X_0=i)=f(i);
\end{equation}
\item[4)] for all $i,j\in \mathbb{N}$ we have
\begin{equation}

\lim_{n\to\infty} {\bf P}(X_n=j|X_0=i, T>n)= \pi_j.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:results:gibbs of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] For $n \in \ensuremath{\mathbb{N}}$, $n > 2$, define the \emph{Gibbs measure} $\theta^n \in \mathcal{P}((\ensuremath{\mathbb{R}}^d)^{V_n})$ by
\begin{equation}
    \theta^n(d\mathbf{x}^{(n)}) := \frac{1}{\mathcal{Z}^n} \exp\bigg( - \frac{1}{2}\sum_{(u, v) \in E_n} Q(x_u, x_v)\bigg)  d\mathbf{x}^{(n)},

\end{equation}
where $Q$ is given by  
\begin{equation}
    Q(x, y) := U(x) + U(y) + 2W(x - y), \quad x, y \in \ensuremath{\mathbb{R}}^d,

\end{equation}
and $\mathcal{Z}^n$ is the associated normalization constant or \emph{partition function}:
\begin{equation}
    \mathcal{Z}^n := \int_{(\ensuremath{\mathbb{R}}^d)^{V_n}} \exp\bigg( - \frac{1}{2}\sum_{(u, v) \in E_n} Q(x_u, x_v)\bigg) d\mathbf{x}^{(n)}.

\end{equation}
Note that if $(U, W)$ satisfy Assumption (as:results:invMeasure of the paper), then $\mathcal{Z}^n$ is finite and $\theta^n$ has finite moments of all orders.

[Definition 9 of arXiv:2609.02197, '2609.02197'] For all $j \in \mathbb{N},$ let
\begin{align*} 
\left\Vert\cdot\right\Vert_{j,\mathscr{S}}: C^{\infty}\left(\mathbb{T}^d,\mathbb{R}\right)&\longrightarrow \mathbb{R}_+ \\ \varphi & \longmapsto \left\Vert \varphi\right\Vert_{j,\mathscr{S}}=\max_{\substack{q \in \mathbb{N}^d\\ \left|q\right|\leq j}}\sup_{x \in \mathbb{T}^d}\left|\partial^q\varphi\left(x\right)\right|
\end{align*}
\begin{enumerate}
\item The Schwartz space is the vector space \gls{pc2}$:=C^\infty\left(\mathbb{T}^d,\mathbb{R}\right)$ equipped with the topology generated by the family of semi-norms $\left(\left\Vert\cdot\right\Vert_{n,\mathscr{S}}\right)_{n \in \mathbb{N}}.$
\item The space of tempered distributions is the vector space
\\
\gls{pc1}$:=\left\{f \in \mathbb{R}^{\mathscr{S}},\exists (\mu,r) \in \mathbb{R}_+\times \mathbb{N},\forall \varphi \in \mathscr{S},\left|f\left(\varphi\right)\right|\leq \mu\left\Vert\varphi\right\Vert_{r,\mathscr{S}}\right\}$
\\
$\cap\left\{f \in \mathbb{R}^{\mathscr{S}},\forall \left(\alpha,\varphi_1,\varphi_2\right) \in \mathbb{R}\times\mathscr{S}^2,f\left(\alpha\varphi_1+\varphi_2\right)=\alpha f\left(\varphi_1\right)+f\left(\varphi_2\right)\right\}$ equipped with the weak$^*$ topology $\sigma\left(\mathscr{S}',\mathscr{S}\right).$
\item Let $\left(f_n\right)_{n \in \mathbb{N}}$ be a sequence in $\mathscr{S}'.$ We say that $\left(f_n\right)_{n \in \mathbb{N}}$ converges in $\mathscr{S}'$ if and only if there exists $f \in \mathscr{S}'$ such that for all $\varphi \in \mathscr{S},\lim_{m\to+\infty}f_m\left(\varphi\right)=f\left(\varphi\right).$
\end{enumerate}

