[Lemma lem:g of arXiv:2608.18320, 'Asymptotics for Beta-Splitting Trees via Homogeneous Fragmentations and Meromorphic Potent'] Fix an integer $n\geq0$, $\gamma\in(0,1)$, and
$0\le\ell\le r\le1$ such that $n+1-r>0$,
\[
        \alpha:=n+1-r>0.
\]
For an integer $N\geq1$, set $R_N:=N-\gamma$, and let $D_N$ be the
positively oriented boundary of the square
\[
        \left\{
        w\in\mathbb C:
        |\operatorname{Re} w|\leq R_N,\quad
        |\operatorname{Im} w|\leq R_N
        \right\}.
\]
Then
\begin{equation}
        \sup_{\ell\leq\eta\leq r}
        \sup_{w\in D_N}
        |g(n+\eta,w)|
        =
        \mathrm{O}(
        R_N^{-\alpha})=
        \mathrm{O}(N^{-\alpha}),
        \qquad \text{as $N\to\infty$.}
\end{equation}
Consequently, for all sufficiently large $N$ and every
$\eta\in[\ell,r]$, the function $f_{n+\eta}$ does not have zeros nor
poles on $D_N$, and
\begin{equation}
        \sup_{\ell\leq\eta\leq r}
        \sup_{w\in D_N}
        \left|
        \frac1{f_{n+\eta}(w)}
        -
        \frac1{c(n+\eta)}
        \right|=
        \mathrm{O}(N^{-\alpha}).
\end{equation}

