[Proposition 247 of arXiv:2601.16377, '2601.16377'] Let $\boldsymbol{v} \in \amsmathbb{R}^H$ be non-zero and such that $\pi_{\boldsymbol{v}}^{\circ}$ is a bijection.
\begin{enumerate}
\item[(H1)] $\textnormal{gr}_{\boldsymbol{v}}(p_1,p_2)$ is a well-defined symmetric and pluriharmonic function of $(p_1,p_2) \in \Sigma_{\boldsymbol{v}} \times \Sigma_{\boldsymbol{v}} \setminus (\Delta_{\boldsymbol{v}} \cup \Delta_{\boldsymbol{v}}^*)$ which is independent on the choice of paths of integration;
\item[(H2)] $\textnormal{gr}_{\boldsymbol{v}}(p_1,p_2) + 2\text{\foreignlanguage{russian}{B}}_{\boldsymbol{w}_1,\boldsymbol{w}_2} \big( \log|z_1 - z_2^*| - \log|z_1 - z_2|\big)$ is a pluriharmonic function of $(p_1,p_2)$ near $\Delta_{\boldsymbol{v}} \cup \Delta_{\boldsymbol{v}}^*$ in the $(\boldsymbol{w}_1,\boldsymbol{w}_2)$-th sheet;
\item[(H3)] $\textnormal{gr}_{\boldsymbol{v}}(p_1,p_2) = - \textnormal{gr}_{\boldsymbol{v}}(p_1^*,p_2) = - \textnormal{gr}_{\boldsymbol{v}}(p_1,p_2^*)$;
\item[(H4)] if $p_1$ or $p_2$ is a real point, then $\textnormal{gr}_{\boldsymbol{v}}(p_1,p_2) = 0$.
\item[(H5)] Let $(f_{h}(z))_{h = 1}^{H}$ be an $H$-tuple of functions such that $f_{h}(z)$ is a holomorphic function of $z$ in a neighborhood of $[\alpha_h,\beta_h]$ and takes real values on the real line. Denoting $f_{\boldsymbol{w}_i}$ the function on $\amsmathbb{B}_{\boldsymbol{w}_i}^+ \subset \Sigma_{\boldsymbol{v}}$ and equal to $f_{h} \circ Z_{\boldsymbol{v}}$ on the $h$-th segment when it is part of $\amsmathbb{B}_{\boldsymbol{w}_i}^+$ (\textit{i.e.} for $h \in \textnormal{supp}(\boldsymbol{w}_i)$), we have
\begin{equation}

\begin{split}
& \sum_{h_1,h_2 = 1}^{H} (w_{1})_{h_1} (w_{2})_{h_2}\oint_{\gamma_{h_1}} \oint_{\gamma_{h_2}} \mathcal{F}_{h_1,h_2}(z_1,z_2) f_{h_1}(z_1) f_{h_2}(z_2) \dd z_1 \dd z_2 \\
& = -\frac{1}{4\pi^2} \iint_{\amsmathbb{B}_{\boldsymbol{w}_1}^{+} \times \amsmathbb{B}_{\boldsymbol{w}_2}^{+}} \textnormal{gr}_{\boldsymbol{v}}(p_1,p_2) \dd f_{\boldsymbol{w}_1}(p_1) \dd f_{\boldsymbol{w}_2}(p_2).
\end{split}
\end{equation}
\item[(H6)] The result of 5. is unchanged if we add to $\mathcal{B}_{\boldsymbol{v}}$ in the Definition~\ref{def:Hvv} of $\textnormal{gr}_{\boldsymbol{v}}$ a bidifferential proportional to $\frac{\dd z_1\dd z_2}{(z_1 - z_2)^2}$.
\end{enumerate}

[Proposition prop:optsimp of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] For all $c\neq  \sref,$  define
\begin{align}

    {R}_{edge} (\cc) := \min_{\pi\in \mathcal{B}_{h}(\cc) }J^\nu_\k(\pi)\quad \text{ and } \quad {\mathcal M}_{edge}(\cc)\coloneqq \argmin_{\pi\in \mathcal{B}_h(\cc)}J^\nu_\k(\pi)
\end{align}
with $\mathcal{B}_{h}(\cc)$ being the constraint set defined in (equation eqn:Medge of the paper), 
and let
\begin{equation}
    {\mathcal M}(\cc):=\pr{\UGW_1(\mu^{(\pi)}):\pi\in {\mathcal M}_{edge}(\cc)}.
\end{equation}
Then for any open set ${\mathcal O} \subset\P(\TkaXinf)$ with ${\mathcal M} (c) \subset {\mathcal O}$, the following conditional limits hold:
\begin{align}
    &\lim_{\delta\to 0}\limsup_{n\to \infty}\frac{1}{n}\log\mathbb{P}\left(U_n\notin {\mathcal O} \ \vert \ \{\mathbb{E}_{L_n}\sqpr{S_h}\geq c-\delta\right)<0.\\
    &\lim_{\delta\to 0}\limsup_{n\to \infty}\frac{1}{n}\log\mathbb{P}\left(U_n\notin {\mathcal O} \ \vert \ \{\mathbb{E}_{L_n}\sqpr{S_h}\leq c+\delta\right)<0.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

