[Proposition 5 of arXiv:2608.05842, 'Asymptotic Expansion of the Kallianpur–Striebel Formula under Perturbations of Linear Mode'] For any $0\leq t\leq T$, it holds
  \begin{align}
    U_t^\epsilon Z_t^\epsilon
    =&Z_t^0 U_t^\epsilon\left( 1+\sum_{i=1}^{n-1}I_t^{i,\epsilon}+R_t^\epsilon \right),
  \end{align}
  where
  \begin{align}
    r_s^{1,\epsilon}=&H_s^\epsilon - c(s)X_s\nonumber\\
    \begin{split}
      I_t^{i,\epsilon}=&\int_0^t\int_0^{t_{i}}\cdots \int_{0}^{t_2} (r_{t_1}^{1,\epsilon})^\top (\sigma(t_1)\sigma(t_1)^\top)^{-1} (dY_{t_1}^\epsilon-c(t_1)X_{t_1}dt_1)\\
  &\times \cdots \times (r_{t_i}^{1,\epsilon})^\top (\sigma(t_i)\sigma(t_i)^\top)^{-1} (dY_{t_i}^\epsilon-c(t_i)X_{t_i}dt_i),
    \end{split}\\
    \begin{split}
      R_t^\epsilon=&\int_0^t\int_0^{t_{n}}\cdots \int_{0}^{t_2} K_{t_1}^\epsilon(r_{t_1}^{1,\epsilon})^\top (\sigma(t_1)\sigma(t_1)^\top)^{-1} (dY_{t_1}^\epsilon-c(t_1)X_{t_1}dt_1)\\
  &\times \cdots \times (r_{t_n}^{1,\epsilon})^\top (\sigma(t_n)\sigma(t_n)^\top)^{-1} (dY_{t_n}^\epsilon-c(t_n)X_{t_n}dt_n),
    \end{split} \\
    \begin{split}
      K_t^\epsilon=&\exp\left( \int_0^t(r_s^{1,\epsilon})^\top (\sigma(s)\sigma(s)^\top)^{-1} (dY_s^\epsilon-c(s)X_sds)\right.\\
  &\left.-\frac{1}{2}\int_0^t(r_s^{1,\epsilon})^\top(\sigma(s)\sigma(s)^\top)^{-1} r_s^{1,\epsilon} ds\right),
    \end{split}  
  \end{align}
  and
  \begin{align}
    \begin{split}
      Z_t^0=&\exp\left( \int_0^t(c(s)X_s)^\top (\sigma(s)\sigma(s)^\top)^{-1} dY_s^\epsilon\right.\\
  &\left.-\frac{1}{2}\int_0^t(c(s)X_s)^\top(\sigma(s)\sigma(s)^\top)^{-1} c(s)X_s ds\right).
    \end{split}    
  \end{align}

