body:
[Definition 22 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $\gamma\in(0,1)$ and $\alpha\in\mathbb R$. A {\bf compatible frozen quotient family} is a family $\mathfrak r=(\mathfrak r^\tau)_{\tau\in[0,T]}$ such that
\begin{enumerate}
\item for every $\tau\in[0,T]$, $\mathfrak r^\tau\in \mathfrak C^{\gamma}(\Delta^2_\tau;B_\alpha)$;

\item for every $0\le \tau'\le \tau\le T$, $\operatorname{Res}_{\tau,\tau'}\mathfrak r^\tau=\mathcal T_{\tau,\tau'}\mathfrak r^{\tau'}$;

\item the family is uniformly bounded in quotient seminorm $\sup_{\tau\in[0,T]}\|\mathfrak r^\tau\|_{\mathfrak C_2^{\gamma,\alpha}(\tau)}<\infty$.
\end{enumerate}
We denote by $\mathfrak Q_{\mathrm{fr}}^{\gamma,\alpha}$ the vector space of all compatible frozen quotient families, endowed with the seminorm $$\|\mathfrak r\|_{\mathfrak Q_{\mathrm{fr}}^{\gamma,\alpha}}:=\sup_{\tau\in[0,T]}\|\mathfrak r^\tau\|_{\mathfrak C_2^{\gamma,\alpha}(\tau)}.$$

[Proposition Heat Kernel contraction and spectral gap of arXiv:2411.09614, 'Moment estimates for the stochastic heat equation on Cartan-Hadamard manifolds'] Let $M$ be a Riemannian manifold, and $P_t$ be the heat kernel at time $t>0$. 
    \begin{enumerate}[label=(\roman*)]
        \item If $u_0\in L^\infty(M)$, then for all $x\in M$ we have \begin{equation}
            \abs{P_tu_0(x)}\leq \norm{u_0}_{\infty}
        \end{equation}
        The following assume additionally that $M$ is a Cartan-Hadamard manifold with $\sec_M\leq -K_1<0$.
        \item If $u_0\in L^r(M)\cap L^\infty(M)$, $2\leq r<\infty$, then for all $t>0,x\in M$ we have \begin{equation}
            \abs{P_tu_0(x)}\leq C e^{-\frac{(n-1)^2}{2r}K_1t}\norm{u_0}_\infty.
        \end{equation}
        \item If $u_0\in L^r(M)\cap L^\infty(M)$, $1\leq r\leq 2$, then for all $t>0,x\in M$ we have \begin{equation}
            \abs{P_tu_0(x)}\leq C e^{-\frac{(n-1)^2}{4}K_1t}\norm{u_0}_\infty.
        \end{equation}
    \end{enumerate}

