body:
[Theorem annLDPthm of arXiv:2603.22652, 'A cohesive account on the ergodic behaviours and scaling limits of Random Walks in Cooling'] Let $\tau$ be a resampling map, let $X = (X_n, n \in {\mathbb {N}})$ follow the law of the annealed RWCRE defined in (equation eq:annealed_rwcre of the paper), and let $\mu_n$ be the probability measure on ${\mathbb {R}}$ defined by $\mu_n(A): = {\mathbb {P}}(X_n/n \in A)$. 

If there is a function $\Lambda: {\mathbb {R}}\to {\mathbb {R}}$ that is strictly convex and such that
for all $\theta \in {\mathbb {R}}$,
\begin{equation}
    \begin{aligned}
        \lim_n \frac{1}{n} \log {\mathbb {E}}[e^{\theta X_n}]&= \lim_n \sum_k \frac{T_{k,n}}{n} \frac{1}{T_{k,n}} \log {\mathbb {E}}[e^{\theta Z_{T_{k,n}}}] = \Lambda(\theta).
    \end{aligned}
\end{equation}
Then, $(\mu_n, n \in {\mathbb {N}})$ satisfies the large deviation principle in the sense of Definition III.6 of [dH00] with rate $n$ and function $I$ given by 
\begin{equation}
I(x) = \sup\{x \theta - \Lambda(\theta):   \theta \in {\mathbb {R}}\}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 8 of arXiv:2512.08595, 'Small time asymptotics of spectral heat content of isotropic processes'] Let $X=(X_t)_{t\ge 0}$ be a translation invariant, isotropic stochastic process on $\R^d$ satisfying Assumption~\ref{assump1}. Then for any nonnegative $f\in C^{1,\kappa}_c(\R^d)$,
		\begin{align*}
			\lim_{t\downarrow 0} \frac{\mathcal{R}^X_f(t)}{\mu(t)} = \int_{\R^d} |\nabla f(x)| dx,
		\end{align*}
		where $\mu(t)$ is defined in \eqref{eq:mu_sigma}. In particular, the above limit holds for all compactly supported smooth functions. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem wlln of arXiv:2604.12815, 'On ergodicity of the SAGA-LD algorithm\thanks{The author gratefully acknowledges the suppo'] Let $W_{n}$, $n\in\mathbb{N}$ be a real-valued process with $\alpha_{W}(n)\to 0$, 
$n\to\infty$ such that 
\begin{equation}
\lim_{V\to\infty}\sup_{n\geq 1}\frac{1}{n}\sum_{j=1}^{n}E[|W_{j}|1_{\{|W_{j}|\geq V\}}]\to 0,\ V\to\infty.	
\end{equation}
Then
\begin{equation}
E\left[\left|\frac{\sum_{j=1}^{n}[W_{j}-E[W_{j}]]}{n}\right|\right]\to 0,\ n\to\infty.	
\end{equation}
\hfill $\Box$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 of arXiv:2604.07478, 'Mixing Times and Cutoff for the Rook's Walk'] Fix $m\in \{0,\dots,d\}$ and let $\phi_m$ be as above. Then,
   \[\phi_m^2(0) \leq {d \choose m}\]
   \begin{proof}

     \[\phi_m^2(x) = \frac{K_m^2(x)}{\langle K_m, K_m\rangle_\pi}\]
     Specializing to $x=0$, by Def. \ref{krav_def} we have
   \begin{align*}
   K_m(0) &= \sum_{j=0}^m (-1)^j(0)_j(d-0)_{m-j}(n-1)^{m-j}\\
   &= (d)_{m}(n-1)^{m} \tag{$\because (0)_j = 0, \quad\forall j>0$}\\
   \therefore \quad K_m^2(0) &= (d)^2_{m}(n-1)^{2m}
   \end{align*}
     Proposition 3.1 in \cite{coleman_krawtchouk_2011} gives,
     \[\langle K_m, K_m\rangle_\pi = n^d(n-1)^m(d)_m\]
   Therefore,
   \[\phi^2_m(0) = \frac{(d)_m^2(n-1)^{2m}}{n^d(n-1)^m(d)_m} = \frac{(d)_m(n-1)^{m}}{n^d} \leq (d)_m = {d \choose m}\]

   \end{proof}

