body:
[Prop 14 of arXiv:2608.03956, 'From Triangular Array Progression\\ to Near-Log-Concave State Transitions'] The following properties hold for $\T^{(1)}$:
\begin{enumerate}
\item For every $n\geq 5$ and any $k\geq 0$, $\sup(\T^{(1)}_{n,*}) = \sup(\T^{(1)}_{n+k,*})$.
\item For every $j\geq 2$ and any $k\geq 1$, $\sup([\T^{(1)}_{j-1,j},\ldots,\T^{(1)}_{j-1+k,j}]) = \T^{(1)}_{j,j}$.
\end{enumerate}

[Prop 7 of arXiv:2604.02129, 'Realisation of constraints in underdamped Langevin dynamics'] Given $\eps>0$, let $(Q_t,P_t)$ be the solution to~\eqref{eq:abc-slow},\eqref{eq:intro-InfFriction-withFD-Fast} with corresponding initial data $(Q^i_0,P^i_0)$ for $i=1,2$. Recall the definition of the potential $V$ from~\eqref{eq:Valpha} for any  parameter value $\alpha\geq 0$. Further let $T\geq 1$ be fixed.
    \begin{enumerate}[label=(\roman*)]
        \item
        For any $t\geq 0$ we have
        \begin{align}
        \E\Bigl[|Q_t^{1} - Q_0^{1}|^2 \Bigr] &\leq 
        \begin{dcases}
        C_1 \Bigl(  \eps t+ \eps^2 |P_0^{1}|^2   \Bigr) \ \ &\text{if $\alpha=0$,}\\
         C_2 \Bigl( \eps t+ \eps^2 \Bigl(   (1+t^2) |Q_0^{1}|^2 + |P_0^{1}|^2  \Bigr) \Bigr) \ \ &\text{if $\alpha>0$,}
        \end{dcases}
        \\
        \E \Bigl[  \bigl| P^1_t \bigr|^2 \Bigr] & \leq 
        \begin{dcases}
        C_3 \Bigl( \eps^2+  e^{-\frac{C_4}{\eps}t}  |P^1_0|^2   +\beta^{-1} \Bigr) \ \ &\text{if $\alpha=0$,}\\
        C_5 \Bigl(\eps^2+ \eps^2 \left|Q^1_0\right|^2 +  \Bigl(e^{-\frac{C_6}{\eps}t} + \eps^4\Bigr) |P^1_0|^2   +\beta^{-1} \Bigr) &\text{if $\alpha>0$,}
        \end{dcases}

        \end{align}
    where the constants $C_i>0$ for $i\in\{1,\ldots 6\}$ are independent of $\eps$ and $t$.
        \item 
    Let $(q_t,p_t)\in \R^{2(d-k)}$ with initial data $(q_0,p_0)=(Q_0^2,P_0^2)$ evolve according to~\eqref{eq:limit-gen} with $\hat q=Q^1_0 \in \R^k$. We have 
    \begin{align}
        \E\biggl[\sup_{t\in [0,T]}\biggl|\begin{pmatrix}q_t - Q^{2}_t \\ p_t - P^{2}_t\end{pmatrix}\biggr|^2\biggr] \leq 
        \begin{dcases}
             \eps C_7 e^{C_8 T} T^2 \Bigl( T+\eps |P_0^{1}|^2\Bigr) \ \ &\text{if $\alpha=0$}, \\
             \eps C_9 T  \Bigl(T+\eps  \left|Q^1_0\right|^2  + \eps |P_0^{1}|^2  \Bigr)   &\text{if $\alpha>0$},
        \end{dcases} 
    \end{align}
        where $C_7,C_8,C_9>0$ are independent of $\eps$ and $T$.
    \end{enumerate}

[Lemma 17 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] Let $B=B_r(0)$ and let $F:\ZZ^d\to\RR$ be a non-negative function.
    \begin{enumerate}[label=(\alph*),ref=\thelemma(\alph*)] 
        \item 
        If $r\ge2\rd(0)$, then
        \begin{equation}
                \fint_{\frac12 B}F\,\lesssim\, \fint_{x\in B}\fint_{B_\diamond(x)}F\,\lesssim\, \fint_{2B}F.
        \end{equation}
        \item 
         If $r\le 2\rd(0)$, then for any $p\in(0,1)$,
        \begin{equation}
            \sup_{x\in B}\Big(\fint_{B_{{\diamond}}(x)} F\Big)^p\,\lesssim \,\fint_{x\in 5B}\Big(\fint_{B_{{\diamond}}(x)} F\Big)^p.
        \end{equation}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 121 ({\cite{DLE}}) of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] The following statements hold for any $(x, y) \in \overline{\mathfrak{L}}_{q;a,b,c}$.

		\begin{enumerate} 

			\item We have that  
			\begin{flalign}

				\arg f (x,y) = \pi (1 - \partial_y \mathcal{H}_{q;a,b,c} (x,y)); \qquad \arg (f (x,y)-1) = \pi (1 + \partial_x \mathcal{H}_{q;a,b,c} (x,y)).
			\end{flalign} 

			\item We have that $(x, y) \notin \mathfrak{L}_{q;a,b,c}$ if and only if $f(x, y) \in \mathbb{R}$. 

			\item We have that $(x,y) \in \mathfrak{L}_{q;a,b,c}$ if and only if both roots of \eqref{equationu} are not real. Moreover,  $(x, y) \in \mathfrak{A}_{q;a,b,c}$ if and only if \eqref{equationu} has a double (real) root for $u$.

		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2506.20411, 'Maximal Counts in the Stopped Occupancy Problem'] For any fixed $i\ge1$ and $\eps>0$,
there exist constants $C_{\cdot}$ and $c_{\cdot}$ (that may depend on $i$ and $\eps$)
such that for all $n\ge i$ and $k\ge0$,
\begin{align}
{\mathbb P}[M_{n,i}(\tau_n)-b_n>k]&
\leq  \CC e^{-(1-\varepsilon)k/e},
\\
{\mathbb P}[M_{n,i}(\tau_n)-b_n\le-k]&
\leq  \CC e^{-\cc e^{\ccname{\ccb} k}}
\leq  \CC e^{- k}
.\end{align}

[Lemma 96 of arXiv:2601.16377, '2601.16377'] Take two variational data satisfying Assumptions~\ref{Assumption_A} and \ref{Assumption_B} with $\iota_h^{-,\textnormal{I}}=\iota_h^{-,\textnormal{II}}=2$, differing by their segment endpoints $\hat{a}_{h}^{\prime\,\textnormal{I}}$ and $\hat{a}_{h}^{\prime\,\textnormal{II}}$ for a single $h \in [H]$, and by the potentials
\begin{equation*}
\begin{split}
V_h^{\textnormal{I}}(x) & = -2\, \mathrm{Llog}(x - \hat{a}_{h}^{\prime\,\textnormal{I}}) + V_h^0(x), \\
V_h^{\textnormal{II}}(x) & = -2 \,\mathrm{Llog}(x - \hat{a}_{h}^{\prime\,\textnormal{II}}) + V_{h}^{0}(x).
\end{split}
\end{equation*}
Assume furthermore that $\boldsymbol{\mu}^{\textnormal{I}}$ satisfies Assumption~\ref{Assumption_C} and $\hat{a}_{h}^{\prime\,\textnormal{I}}$ belongs to a saturation of $\boldsymbol{\mu}^{\textnormal{I}}$. Then, there exists $M > 0$ depending only on the constants in the assumptions, such that for $|\hat{a}_{h}^{\prime\,\textnormal{I}} - \hat{a}_{h}^{\prime\,\textnormal{II}}| < \frac{1}{M}$ and for any measurable function $f$ with finite $|\!|f|\!|_{\frac{1}{2}}$ we have
\begin{equation}

 \bigg| \int_{\amsmathbb R} f(x)\dd(\mu^{\textnormal{I}}-\mu^{\textnormal{II}})(x)\bigg| \leq M \cdot \big(|\!|f|\!|_{\frac{1}{2}} + |\!|f|\!|_{\infty}\big) \cdot |\hat{a}_{h}^{\prime\,\textnormal{I}} - \hat{a}_{h}^{\prime\,\textnormal{II}}|.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 13 (Exact matrix-scale data) of arXiv:2608.07820, 'Linear Spectral Statistics for Entrywise-Transformed Spiked Wigner Matrices under Shifted '] Under W3, W4, W5, and the spike assumption, the array
\(M_N^{(4)}\) has the following properties for all sufficiently large \(N\):
\begin{enumerate}[label=(A\arabic*)]
\item its upper-triangular entries are independent and uniformly bounded after
      multiplication by \(\sqrt N\);
\item its deterministic mean matrix is exactly that of \(M_N^f\);
\item its centered variance profile is exactly that of \(M_N^f\);
\item its edgewise third and fourth cumulants are exactly those of the target;
\item
\begin{equation}
 \max_{i<j}
 \left|
 \cum_4(\widehat Y_{s_{ij}})-\kappa_4^{f,\nu}
 \right|\longrightarrow0;
\end{equation}
\item the fourth-moment Lindeberg condition is eventually identically zero.
\end{enumerate}

[Lemma 18 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] For $a,b,c\in\R$ and $y\geq 0$ we have
\begin{equation*}
\max_{x\in [0,y]} a + bx + cx^{2} = 
\begin{cases}
a - \frac{(b^{+})^{2}}{4c} & \text{if $c < 0$ and $b < -2cy$}\\
a + by + cy^{2}& \text{if $c < 0$ and $b\geq -2 cy$}\\
a + (b + cy)^{+}y & \text{otherwise}
\end{cases}
.
\end{equation*}

