[Corollary cor:hyperbolic-interior of arXiv:2609.00777, 'Universal murmuration and Hecke augmentation'] Let
\[
R_0=\frac{2P^{k/2}}{\sqrt{X+Y}}.
\]
Then
\begin{equation*}
\frac{\zeta(2)\pi}{XY}
\sum_{1\leq r<R_0}\mathcal H_k(r)
=
B\sum_{1\leq r<R_0}
C(r)\sqrt{\frac{4P^k}{X}-r^2}
+
O_{k,\varepsilon}\left((P^kXY)^\varepsilon\mathcal E_{\mathrm{hyp}}\right)
+O_k\left(\frac{P^{k-2}}X\right),
\end{equation*}
where
\begin{equation*}
\mathcal E_{\mathrm{hyp}}
=
\frac{P^{11k/10}}{Y^{2/5}X^{9/10}}
+
\frac{YP^k}{X^2}
+
\frac{P^kY^{1/2}}{X^{3/2}}
+
\frac{P^k}{X^{1/2}Y^{13/18}}
+
\frac{P^k}{XY^{1/9}}.
\end{equation*}

