[Definition def:pseudo-deriv of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] Under Assumption~(ass:params of the paper) with $\beta > 1$, for
$k \in \{0,1,\ldots,n-1\}$ and $t \in \mathbb{R}$, define the
\emph{$k$-th pseudo-derivative} of $X^{(n)}_H$ at $t$ by
\begin{equation}

X^{(n,k)}_H(t)
:= \int_\mathbb{R}
\frac{\partial^k f_n}{\partial t^k}(t,u;H,\alpha)\,dM_\alpha(u).
\end{equation}
For $k = 0$, we interpret $\partial^0 f_n/\partial t^0 = f_n$ and thus
$X^{(n,0)}_H(t) = X^{(n)}_H(t)$.

[Lemma 46 of arXiv:2601.16377, '2601.16377'] Suppose that for any $h\in[H]$, $\nu_h$ is an integrable signed measure such that
\begin{equation}

  \sum_{g,h = 1}^{H}  \int_{\hat a'_g}^{\hat b'_g} \int_{\hat a'_{h}}^{\hat b'_{h}} \Big|\theta_{g,h}\log|x-y|
  \Big|\, \dd|\nu_g|(x)\,\dd |\nu_{h}|(y) < +\infty,
 \end{equation}
 Then both \eqref{eq_functional_quadratic} and \eqref{eq_functional_quadratic_alternative} exist and coincide. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 1 (A first general non-asymptotic bound) of arXiv:2605.05986, '\bf Convergence rate of the occupation measure of { classes of ergodic processes toward th'] Let $p\!\in (0, +\infty)$ and let $d\ge1$.  There exists a positive constant $K_{p,d}$ such that for every  $\mu,\nu\!\in{\cal P}_p(\ER^d)$
\begin{equation}
{\cal W}_p^p(\mu,\nu) \le K_{p,d} \sum_{n\ge 0}2^{pn} \sum_{\ell\ge 0}2^{-p\ell}\sum_{F\in {\cal P}_{\ell}}\big| \mu(2^nF\cap \B_n)�- \nu(2^nF\cap \B_n)�\big|,
\end{equation}
where $2^nF = \{2^nx, \; x\!\in F\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:iso_action of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Given $\underline{\tau}, \underline{\sigma} \in \boldsymbol{\mathfrak{T}}$ and $f\in\mathrm{Iso}(\underline{\tau},\underline{\sigma})$, we define an induced linear isomorphism $\hat f: \mathcal{H}^{\underline{\tau}} \rightarrow \mathcal{H}^{\underline{\sigma}}$ and, for any $k \in \{1,{\mcb{n}}\}$, a bijection $\tilde f^{[k]}: (\R^k)^{N(\underline{\tau})} \rightarrow (\R^k)^{N(\underline{\sigma})}$ by setting
\begin{equs}
\hat f:\mathcal{H}^{\underline{\tau}} 
\ni
\bigotimes_{n \in N(\underline{\tau})}
e_{n}
&\mapsto 
\bigotimes_{m \in N(\underline{\sigma})} e_{f^{-1}(m)} \in \mathcal{H}^{\underline{\sigma}}\;,\\
\tilde f^{[k]}:(\R^{k})^{N(\underline{\tau})} 
\ni
\big(x_n: n \in N(\underline{\tau})\big) 
&\mapsto 
 \big(x_{f^{-1}(m)} : m \in N(\underline{\sigma})\big) \in (\R^{k})^{N(\underline{\sigma})}\;.
\end{equs}
We also lift $f$ to a map $\mathbf{f}:{\mcb{B}}[\underline{\tau}]\rightarrow {\mcb{B}}[\underline{\sigma}]$ by setting $$\text{$\mathbf{f}$}F() \eqdef \big(\mathrm{Id}_{\R^{\mcb{n}}}\otimes \hat f\big) \circ F(\tilde f^{[{\mcb{n}}]} \, )\,.$$ 
Overloading notation, we also lift $f$ to a map $\text{$\mathbf{f}$}:\text{${\mcb{C}}$}[\underline{\tau}]\rightarrow \text{${\mcb{C}}$}[\underline{\sigma}]$ by setting $$\text{$\mathbf{f}$}F() \eqdef \hat f \circ F\big( 
 (\mathrm{Id}_{[0,1]}\otimes \tilde{f}^{[1]})  \big)\,.$$

[Theorem thm:RvT of arXiv:2603.22652, 'A cohesive account on the ergodic behaviours and scaling limits of Random Walks in Cooling'] {AveChidCosdHol22}}] 
\text{}\\ \vspace{-.5cm}

\begin{itemize}
\item[{\rm(a)}] If $\alpha$ is right-transient, then $(\alpha,\tau)$ is right-transient for all cooling maps $\tau$, that is, such that (equation effective-cooling of the paper) is valid.

\item[{\rm(b)}] If $\alpha$ is recurrent, then $(\alpha,\tau)$ is recurrent when

\begin{equation} 
\liminf_{n\to\infty} \abs{{\mathbb {E}} \left[ \frac{X_n}{\sqrt{\mathsf{Var} (X_n)}} \right]} = 0.
\end{equation}

The latter holds for all symmetric $\alpha$ and all $\tau$,
and also for all non-symmetric $\alpha$ when $\tau$ is such that

\begin{equation}
\liminf_{k\to\infty} \frac{1}{k^\gamma} \log T_k >0 \text{ for some } \gamma > \frac34.
\end{equation}

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 of arXiv:2511.09280, 'Random Walk conditioned to stay above a non-flat floor: curvature effects'] Let \(\beta\in (0,1/6)\). There are \(n_0,\lambda_0, r_0\geq 0\), and \(c>0\) such that for any \(n\geq n_0\), any \(\lambda_0 \leq \lambda \leq n^{\beta}\), \(1\leq  k \leq n\), \(L\geq r_0\sqrt{\lambda} n^{2/3}\),
	\begin{equation*}
		P\bigl(\bar{A}_{k,k+L}^{\lambda} \bigr)
		\leq
		\exp(-c\tfrac{\lambda L}{n^{2/3}}).
	\end{equation*}

