[Theorem 5 (Wendel's formula: Combinatorial version) of arXiv:2608.16752, 'Absorption Probabilities for Random Convex Hulls: Distribution-Freeness via the Wall-Cross'] Let $n, d \ge 1$ be integers with $n \geq d+1$.
For every regular $X \in \R^{d\times n}$, the cardinality of the set $\mathcal M(X)$ is given by
\begin{align*}
    |\mathcal M(X)| = 2 \sum_{j=0}^{d-1} \binom{n-1}{j}.
\end{align*}
In particular, this cardinality is the same for all regular $X$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:T1-0 of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] Given that there is a handover at time $0$, the time to the next handover is defined as  

\begin{equation}
T:=\inf\left\{s>0: \forall t\in (0,s], {\mathcal H }\left(S_t \right)=0, \text{ but } {\mathcal H }\left(\overline{S_s}\right)= 2\right\},

\end{equation}

which is equivalent to $T_1(0)$ under the handover Palm probability distribution.

[Theorem Thm-(u P)-long-time of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let the conditions of Theorem (Thm-(u P)-local of the paper) hold and
		$$\theta\in\left(\frac{d}{2}+p,{s-\max \{3\zeta,1\}}\right).$$
		\begin{enumerate}[label={\bf{(\arabic*)}},leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item $($\textbf{Global regularity and continuous dependence on initial data}$)$  Under (Hypo-DNI-1 of the paper), the Cauchy problem (equation Target problem (u P) damp of the paper) admits a global $H_{\rm div}^s$ solution. For $V\in\mathscr{V}$  as specified in (Hypo-DNI-1 of the paper), we have
			\begin{equation}
				\mathbb{E} \left[V(\|u(t)\|_{H^s}^2)\Big|\mathcal{F}_0\right]  
				\leq \Big(V(\|u_0\|^2_{H^s})+\mathscr{G}_2t\Big) {\rm e}^{\mathscr{G}_1t},
				\quad t>0.
			\end{equation}
			Moreover, 
			if $\{u_{0,m}\}_{m\ge1}$ are $\mathcal{F}_0$-measurable $H_{\rm div}^s$-valued random variables such that 
			\begin{equation}
				\sup_{m\ge1}\|u_{0,m}\|_{H^s}\le R\quad \text{for some}\  R>0 \quad  \text{and}\quad  \lim_{m\to\infty}\|u_{0,m}-u_0\|_{H^{\theta}}=0 \quad{\mathbb P}\text{-}{\rm a.s.},
			\end{equation}
			then the corresponding sequence of solutions $\{u_{m}\}_{m\ge1}$ with $u_m|_{t=0}=u_{0,m}$ satisfies
			\begin{equation}
				\lim_{m\to\infty}
				\mathbb{E} \left[1\land \|u_{m}(t)-u(t)\|^2_{H^{\theta}}\Big|\mathcal{F}_0\right]=0, \qquad t>0.
			\end{equation}

			\item  $($\textbf{Uniform-in-time estimate and invariant probability measure}$)$ If (Hypo-DNI-1 of the paper) is strengthened to (Hypo-DNI-2 of the paper), then $u$ satisfies 
			\begin{equation}
				\mathbb{E}\left[V(\|u(t)\|_{H^s}^2) \Big| \mathcal{F}_0\right]  
				\leq V(\|u_0\|^2_{H^s}), \qquad t\ge0.
			\end{equation}
			Moreover, on $\mathbb T^d$, there exists an
			invariant 
			measure $\mu$ 
			in the sense of Definition (IM definition of the paper) with $E=H_{\rm div}^s$. 

			\item $($\textbf{Uniqueness of invariant probability measure}$)$ Let $M=M_{\theta,d}>0$ be a constant satisfying $\|\cdot\|_{W^{p,\infty}}\leq M \|\cdot\|_{H^\theta}$ for $\theta>d/2+p$. If (Hypo-DNI-3 of the paper) holds, then  
			\begin{equation}
				\int_0^t\mathbb{E}  \left[V\left(\frac{\|u(t')\|^2_{W^{p,\infty}}}{M^2}\right)\Bigg|\mathcal{F}_0\right]{\,\rm{d}} t'
				\leq  \frac{V(\| u_0\|^2_{H^\theta})}{\mathscr{G}_3}\left(1-{\rm e}^{-\mathscr{G}_3t}\right),
				\quad t>0,
			\end{equation}
			As a consequence of (equation u Wlip -> 0 of the paper) and $V(0)=0$, it follows that
			the Dirac measure centered at $0$ is the \textbf{unique invariant probability measure} on both $\mathbb T^d$ and $\mathbb R^d$ when $\widetilde h(0)=0$.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

