[Lem 15 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let \( \Omega \subset \R^n \) be an open convex subset and $\phi\in\text{\rm SCL}\,(\Omega)$. If $\phi$ is differentiable at $x\in\Omega$ and there exists $\lambda>0$ such that
	\begin{align*}
		|p-D\phi(x)|\leqslant \lambda|y-x|,\qquad\forall y\in\Omega, p\in D^+\phi(y).
	\end{align*}
	Then the function
	\begin{align*}
		\psi(y)=\phi(x)+D\phi(x)\cdot(y-x)-\frac{\lambda}{2}|y-x|^2,\qquad y\in\Omega,
	\end{align*}
	is of class $C^{\infty}$ and touches $\phi$ from below at $x$ in $\Omega$.

[Lemma lem-Ward of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] Let $\mathcal A$ be a Hermitian matrix. Define its resolvent as $R(z):=(\mathcal A-z)^{-1}$ for any $z= E+ \mathrm{i} \eta\in \mathbb{C}_+$. Then, we have 
    \begin{equation}
    \begin{split}
\sum_x \overline {R_{xy'}}  R_{xy} = \frac{R_{y'y}-\overline{R_{yy'}}}{2\mathrm{i} \eta},\quad
\sum_x \overline {R_{y'x}}  R_{yx} = \frac{R_{yy'}-\overline{R_{y'y}}}{2\mathrm{i} \eta}.
\end{split}
\end{equation}
As a special case, if $y=y'$, we have
\begin{equation}
\sum_x |R_{xy}|^2 =\sum_x |R_{yx}|^2 = \frac{\im R_{yy}}{ \eta}.
\end{equation}

[Definition eq:H+H- of arXiv:2412.03366, 'Regularity of Weighted Tensorized Fractional Brownian Fields and associated function space'] For $\alpha \in [0,1]$ and $H \in (0,1)$, we set
\begin{equation}
H_\alpha^+ := (1+\alpha)H \quad \text{ and } \quad H_\alpha^- := (1-\alpha)H    
\end{equation} 
and we define the Gaussian field $\{X^{\alpha,H}_{(x_1,x_2)}\}_{(x_1,x_2) \in \mathbb{R}^2}$ by 
\begin{equation}
X^{\alpha,H}_{(x_1,x_2)} :=  \int_{\mathbb{R}^2}  \frac{(e^{i x_1 \xi_1}-1) (e^{i x_2 \xi_2}-1)}{\phi_{\alpha,H}(\xi_1,\xi_2)}  d\hat{\bf{W}}({\boldsymbol{\xi}}) 
\end{equation}
where the function
\[\phi_{\alpha,H}(\xi_1,\xi_2)=\min(\vert \xi_1 \vert, \vert \xi_2 \vert)^{H_\alpha^- +\frac{1}{2}}\max (\vert \xi_1 \vert, \vert \xi_2 \vert)^{H_\alpha^++\frac{1}{2} }\]
denotes the square root of the inverse of the spectral density of the field.

[Lemma 13 of arXiv:2606.01742, 'Large deviation principles for SPDEs with locally Lipschitz coefficients'] Assume that Hypotheses \ref{cond-initial}, \ref{cond-dif}  and  \ref{3} hold. If $L_{\sigma}>0$, then
\begin{align*}
\mathbb{P}\left\{\left|u_{N+1}^{ \varepsilon,h_\varepsilon}(t,x)\right|\geq e^N\right\}\leq \exp\left(-\frac{N^{\frac{3}{2}}}{2^{8}\e L_{\sigma}^2t^{\frac{1}{2}}}\right)
\end{align*}
uniformly for all $t>0$, $x\in\R$, $\e>0$,
$$N\geq \max\left\{\left(\max(2^{13}\e^2L_{\sigma}^4t,2^{11}\e^2L_{b}t)\right),4\left[\log \left(4\left(\|u_0\|_{L^\infty(\R)}+1\right)\right)+64M^4L_{\sigma}^4t\right]\right\},$$
and for every $M\geq L_b^{1/4}L_{\sigma}^{-1}$.
 If $\sigma\in L^{\infty}(\R_+\times\R)$, then
\begin{align*}
\mathbb{P}\left\{\left|u_{N+1}^{ \varepsilon,h_\varepsilon}(t,x)\right|\geq e^N\right\}\leq \exp\left(-\frac{e^{2N-4L_bt}}{8\left(4\e+1\right)\left(\|u_0\|_{L^\infty(\R)}+\|\sigma\|_{L^\infty(\R+\times\R)}t^{\frac{1}{4}}+1\right)^2}\right)
\end{align*}
uniformly for all $t>0$, $x\in\R$, $\e>0$ and
\begin{align*}
N\geq\frac{1}{2}+\frac{3}{2}\log2+2L_bt+\frac{1}{2}\log(4\e+1)+\log\left(\|u_0\|_{L^\infty(\R)}+\|\sigma\|_{L^\infty(\R+\times\R)}t^{\frac{1}{4}}+1\right).
\end{align*}

