body:
[Proposition 9 (GFT) of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $W^{(1)}=\big(w^{(1)}_{ab}\big)_{a,b=1}^N$ and $W^{(2)}=\big(w^{(2)}_{ab}\big)_{a,b=1}^N$ be two Wigner matrices satisfying Assumption~\ref{ass:momass}. Fix $\Gamma\in\N$ and assume that 
\begin{equation}
\E \big(w^{(1)}_{ab}\big)^{\gamma_1}\big(w^{(1)}_{ba}\big)^{\gamma_2} = \E \big(w^{(2)}_{ab}\big)^{\gamma_1}\big(w^{(2)}_{ba}\big)^{\gamma_2},\quad \gamma_1+\gamma_2\le \Gamma,\, \gamma_1,\gamma_2\in\N\cup\{0\},

\end{equation}
Let $\Delta^{(j)}$ be defined as in \eqref{eq:def_Delta} but with $W$ replaced by $W^{(j)}$, $j=1,2$. Then for any fixed $n_1,n_2\in\N\cup\{0\}$ and $\bm{k}\in\N^{n_1},\bm{l}\in\N^{n_2}$ it holds that
\begin{equation}
\E \left[\eta^{|\bm{k}|+|\bm{l}|}\Delta^{(1)} (\bm{k})\overline{\Delta^{(1)}(\bm{l})}\right]=\E \left[\eta^{|\bm{k}|+|\bm{l}|}\Delta^{(2)} (\bm{k})\overline{\Delta^{(2)}(\bm{l})}\right] + \mathcal{O}\left(N^{-(\Gamma-3)/2+\xi}\right),

\end{equation}
for any fixed $\xi>0$, uniformly in $z\in\mathcal{D}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2601.20502, 'Optimal matching under size priority'] The subspace $\mathcal{L}_{U,\mathcal{M}}(\mathcal{G}^{\star}) \subseteq \mathcal{L}_{U}(\mathcal{G}^{\star})$ is defined as the set of 
elements $\mu$ of $\mathcal{L}_{U}(\mathcal{G}^{\star})$ such that for $(G,o,w,(f_i)_{i \in \{1,..,I\}}) \sim \mu$, we have that $f_I(u,v)$ maps $E$ to $\{0,1\}$ and the subset $\{(u,v), f_I(u,v)=1 \}$ almost surely induces a matching on $G$ in the sense that
\begin{align*}
    \mathbb{P}\left( \exists u,u',v \in V, u \neq u' \text{ and } f(v,u)=f(v,u')=1\right)=0.
\end{align*}
Similarly we can define the edge rooted version $\mathcal{L}_{U,\mathcal{M}}(\hat{\mathcal{G}}^{\star})$.

[Theorem thm:bilinear of arXiv:2608.01253, 'The pseudo-quantum representation of \\finite reversible Markov chains'] The pseudo-wave and pseudo-density obey

\begin{equation}
\dot\Phi_z=K\Phi_z,\qquad \dot\rho_z=[K,\rho_z]=K\rho_z-\rho_zK.

\end{equation}

Moreover, for all $z$,

\begin{equation}
\rho_z^{T}=\rho_z,\qquad
\operatorname{Tr}\rho_z=\Phi_z^{T}\Phi_z=\Phi_0^{T}\Phi_0,
\qquad
\rho_z^{2}=(\operatorname{Tr}\rho_z)\,\rho_z.

\end{equation}

[Lem second_moment_interpol of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Let $\mathsf{P}_i\in \mathcal P_{s,1}(\Gamma)$, $i=0,1$ with $\int \xi(\Lambda_1)^2\mathsf{P}_i(d\xi)<\infty$ and  $ \mathsf{Q}\in  \mathsf{Cpl}_{s,m}(\mathsf{P}_0,\mathsf{P}_1).$ Set $\mathsf U:=\iota( \mathsf{Q})$ and  $\mathsf{P}_t:= \mathsf{gap}^{-1}\left((T_t)_{\#}\mathsf U\right)$. Then for $0\leq t\leq 1$ and $n\in \IN$ 
    \begin{align*}
        \int \xi(\Lambda_n)^2\mathsf{P}_t(d\xi)\leq (1-t)\int \xi(\Lambda_n)^2\mathsf{P}_0(d\xi)+ t\int \xi(\Lambda_n)^2\mathsf{P}_1(\xi).
    \end{align*}

[Lemma 35 of arXiv:2608.27307, '2608.27307'] Let $C>0$ be a constant,  $\xi\geq0$, and  $\zeta\in[N^{-C},N^C]$. Suppose there exists a constant $q\in[0,1)$ such that for any $\te\in[\zeta, N^C]$, we have the implication
        \begin{align}
                \xi\prec\te \quad\Longrightarrow\quad \xi\prec\te^q\zeta^{1-q}. \nonumber
        \end{align}
        If $\xi\prec N^C$, then $\xi\prec\zeta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let Assumptions~\ref{assump-PDE}~and~\ref{assump-particles} hold, and in particular let $p\in (d,+\infty)$, $\gamma \in (\tfrac{d}{p},1)$ and an integer $k \geq 3$ for which these assumptions hold. Assume further that the cut-off parameter satisfies
${A\geq \| u\|_{L^{\infty}_{t,x}}}$, and if $d=3$, that $\frac{\gamma}{2} + \frac{3}{2}(\frac{1}{2}-\frac{1}{p}) <1$. Then the following holds:
\begin{itemize}
\item If $\sigma>0$, then for any $q\in [1,+\infty)$, there exists $C = C(q,d,\gamma,p,A,\sigma)>0$ such that for any $N\in \N^*$,
\begin{align*}
\Big(\E &\sup_{t\in[0,T]} \big\| u^{N}_t- u_t \big\|_{ \gamma,p}^{2q}\Big)^{\frac{1}{q}}
+  \Big(\E \sup_{t\in[0,T]} \big\| \langle v \rangle^{k}(F_{t}^{N}-F_{t}) \big\|_{L^{2}_{x,v}}^{2q} \Big)^{\frac{1}{q}} \\
& \leq C \bigg( \big(\E \big\| u^{\circ,N}-u^\circ \big\|_{\gamma, p}^{2q}\big)^{\frac{1}{q}} +   \big(\E \big\| \langle v \rangle^{k} (F_{0}^{N}-\vartheta^N\ast F^\circ) \big\|_{L^{2}_{x,v}}^{2q}\big)^{\frac{1}{q}}\\
&\quad + N^{-2(\alpha-\beta)} +N^{-2\beta(\gamma-\frac{d}{p})} + N^{-(\frac{1}{2} - d\beta -(d+1)\alpha)} + \ratetilde^2 \bigg) + 2 \rate^2 ,
\end{align*}
where
\begin{equation}

\rate^2 = \sup_{t\in[0,T]} \big\| u_t^{(N)} - u_t \big\|_{ \gamma,p}^2 +  \sup_{t\in[0,T]} \big\| \langle v \rangle^{k} (F^{(N)}_{t}\ast \vartheta^{N} - F_{t}) \big\|_{L^{2}_{x,v}}^2
\end{equation}
and
\begin{equation}
\ratetilde^2 = \sup_{t\in[0,T]} \big\| \langle v \rangle^{k} (F^{(N)}_{t}\ast \vartheta^{N} - F^{(N)}_{t}) \big\|_{L^{2}_{x,v}}^2
\end{equation}

\item If $\sigma=0$, then for any $q\in [1,+\infty)$ and any $\varepsilon>0$, there exists $C = C(q,d,\gamma,p,A,\varepsilon)>0$ such that for any $N\in \N^*$,
\begin{align*}
\Big(\E &\sup_{t\in[0,T]} \big\| u^{N}_t- u_t \big\|_{ \gamma,p}^{2q}\Big)^{\frac{1}{q}}
+  \Big(\E \sup_{t\in[0,T]} \big\| \langle v \rangle^{k}(F_{t}^{N}-F_{t}) \big\|_{L^{2}_{x,v}}^{2q} \Big)^{\frac{1}{q}} \\
& \leq C \bigg( \big(\E \big\| u^{\circ,N}-u^\circ \big\|_{\gamma, p}^{2q}\big)^{\frac{1}{q}} +   \big(\E \big\| \langle v \rangle^{k} (F_{0}^{N}-\vartheta^N\ast F^\circ) \big\|_{L^{2}_{x,v}}^{2q}\big)^{\frac{1}{q}} +\ratetilde^2 \\
&\quad + N^{-2(\alpha-\beta)} + N^{-2\beta(\gamma-\frac{d}{p})+\varepsilon} + N^{-(\frac{1}{2} - d\beta -(d+1)\alpha)}
\bigg) \, \frac{1}{1-\tilde\gamma} e^{CT\big(1+\sigma_{N}^{-2} + \sigma_{N}^{-\frac{1}{1-\tilde\gamma}}\big)}
 + 2 \rate^2,
\end{align*}
where
\begin{equation}
\tilde{\gamma} = \frac{1}{2} \Big(\gamma + d\big(\frac{1}{2}-\frac{1}{p}\big)\Big) \vee \frac{\gamma+1}{2} \in (0,1) .
\end{equation}

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

