body:
[Lemma eq:boundary of arXiv:2609.01776, 'On the Cuspidal Cohomology of Iwahori Congruence Subgroups of $\mathrm{SL}(3, \mathbb{Z})$'] The dimension of the homology of the boundary of $X^\text{BS}_\mathcal{I}$ is given by the following formula:
    \begin{equation}
    \dim H_3(\partial X_\mathcal{I}^\text{BS}, \mathbb{C}) = 1 + 6\,\dim S_2(\Gamma_0(2, p)).
    \end{equation}

[Lemma 20 (Metric comparison on the Stiefel manifold) of arXiv:2608.17374, '\textbf{On the Pseudo-Mixing of Kac's Walk}'] Let $D$ be the Riemannian distance on $\mathrm{St}(n,k)$ induced by the Frobenius
inner product from the embedding $\mathrm{St}(n,k)\subset \mathbb{R}^{n\times k}$.
Then, for all $X,Y\in \mathrm{St}(n,k)$,
\begin{equation}

\|X-Y\|\leq D(X,Y).
\end{equation}
Moreover, there are universal constants $\rho_D>0$ and $C_D<\infty$, independent
of $n$ and $k$, such that whenever $\|X-Y\|\leq \rho_D$,
\begin{equation}

D(X,Y)\leq \|X-Y\|+C_D\|X-Y\|^2.
\end{equation}

[Lem Lemma_A.2 of arXiv:2412.03370, 'TASEP with a general initial condition and a deterministically moving wall'] Let $(x(t),t\geq 0)$ be a TASEP with step initial condition and let $\alpha \in (0,1)$. Then, it holds
	\begin{equation}
	\lim_{T \to \infty} \mathbb{P}( x_{\alpha T}(T) \geq (1-2 \sqrt{\alpha})T - s c_1(\alpha) T^{1/3}) = F_{\textup{GUE}}(s), 
	\end{equation} where $c_1(\alpha) = \tfrac{(1-\sqrt{\alpha})^{2/3}}{\alpha^{1/6}}$.

	In addition, we have the following estimates on the lower and the upper tail:
	uniformly for all large times $T$ and for $\alpha$ in a closed subset of $(0,1)$, there exist constants $C,c > 0$ such that
	\begin{equation}
	\mathbb{P}( x_{\alpha T}(T) \leq (1-2\sqrt{\alpha})T - s c_1(\alpha) T^{1/3}) \leq C e^{-c s} \ \ \textrm{for} \ s > 0 
	\end{equation}
	and
	\begin{equation}
	\mathbb{P}(x_{\alpha T}(T) \geq (1-2 \sqrt{\alpha})T + s c_1(\alpha) T^{1/3}) \leq C e^{-c s^{3/2}} \ \ \textrm{for} \ 0 < s = o(T^{2/3}). 
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2605.09372, 'Sharp weighted norm estimates for martingale square functions'] Let $1<p<\infty$. Given a matrix weight $W\in A_p$, we have
\begin{equation}
		\int_{\Omega}\sup_n \left[ \mathbb E_{n}\left(\big\|W^{\frac{1}{p}} \widehat{W}_{n}\big\|g\right)\right]^{p'}d\mathbb P\lesssim_{p,d}[W]_{A_p}^{p'}\|g\|_{L_{p'}}^{p'},\quad \forall\, 0\leq g\in L_{p'}.
	\end{equation}

