    \theta_s &= \frac{C |J_0| ((p-1)k^p - \lambda)}{k^{2p-2}|J_0|^2-p^2C^2}, \\
    z_s &= \frac{(p-1)k^p-\lambda}{|J_0|}.
  \end{split}
  \end{equation*}

