[Definition 7 (Bounded support condition) of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] A random matrix $X$ is said to satisfy the {\it bounded support condition} with parameter $q$ if
\begin{equation}
\max_{i,\mu}\abs{x_{i\mu}} \prec q, 
\end{equation}
Here $q$ is a deterministic parameter, typically satisfying \(n^{-1/2} \le q \le n^{-c_\phi}\) for some small constant \(c_\phi>0\). Whenever \eqref{eq_support} holds we say that $X$ has support $q$. In particular, under the arbitrarily high-moment assumption (\ref{eq_highmoment}) one may take $q=n^{-1/2}$ by Lemma \ref{momentmethod}.

[Corollary 18 (\textsf{Four-moment-influence bound on Rademacher chaos}) of arXiv:2608.12451, '2608.12451'] Let $F\in L^4(\PP)$ belong to the $d$-th Rademacher chaos
and satisfy  the lattice condition \eqref{cond_La}
with shift $\theta>0$.  
Put
\noi
\begin{align}
 \mathfrak d(F)
 :=|\cR(F)|
 + (2d)!\binom{2d}{d}m_2(F)\cM(F)
\notag
\end{align}
with $\cM(F)$ the maximal influence as in \eqref{Rad_inf}.
Then, with   $c_\theta:= (1-e^{-\theta})/\theta$,

\noi
\begin{align}
 &\dTV\bigl( F+\theta,P_\theta\bigr)
  \leq c_\theta\bigg[
 |m_2(F)-\theta|
 +\frac{2d-1}{2d}\sqrt{\mathfrak{d}(F)}
 +\frac23\sqrt{m_2(F)\mathfrak{d}(F)}
 +2\mathfrak{d}(F)
 \bigg].
\notag\end{align}

[Theorem thm:rlpts of arXiv:2603.22652, 'A cohesive account on the ergodic behaviours and scaling limits of Random Walks in Cooling'] Assume $\mu = \alpha^{{\mathbb {Z}}}$ satisfies (equation eq:mu_iid of the paper), with $\alpha$ a uniformly elliptic probability measure on $(0,1)$, (equation eq:ue of the paper), non-lattice, (equation non-lattice of the paper), and fluctuation parameter $s \in [0,1) \cup (2,\infty)$. Assume that $(X^{(k)}, k \in {\mathbb {N}})$ are independent and that $ X^{(k)}= (X^{(k)}_n, n \in {\mathbb {Z}}_+)$ is distributed according to(equation eq:annealed_rwre of the paper), $ X^{(k)}$ is RWRE under the annealed law $\mu$ fixed above. Let $\tau$ be a resampling map, as in  (equation cooling-general-tau of the paper) and let $ \mathfrak{X}=\prt{\mathfrak{X}_n, n\in{\mathbb {Z}}_+}$ be the sequence with $\mathfrak{X}_n$ as defined in (equation fluctuation-basic-decomposition of the paper) when $a_n$ is given by (equation alpha-a-var-scaling of the paper). Then the sequence $\mathfrak{X}$ is tight in the weak topology and its limit points are characterised as follows. Let $\lambda_{\tau,n} = (\lambda_{\tau,n}(k), k \in {\mathbb {N}})$ with $\lambda_{\tau,n}(k)$ as defined in (equation variance-lambda-scaling of the paper). If $(n_i)_{i\in{\mathbb {N}}_0}$ is such that
\begin{equation}
\lim_{i\to\infty} \lambda^{\downarrow}_{\tau,n_i}(k) =: \lambda_*(k) \qquad \forall\,k \in {\mathbb {N}}_0,
\end{equation}
then $\lambda_* = (\lambda_*(k), k \in {\mathbb {N}}) \in \ell_2({\mathbb {N}})$ and

\begin{equation}
\mathfrak{X}_{n_i}
\overset{L^2}{\longrightarrow}
W_s^{\otimes \lambda_*}
+ a(\lambda_*)\,\Phi \qquad \forall\,p>0,
\end{equation}

where $a(\lambda_*) := (1 - \|\lambda_*\|_2^2)^{\tfrac12}$, $\Phi$ is a standard normal random variable, and $W_s^{\otimes \lambda_*} $ is as in (equation e:Smix of the paper).

[Lemma 21 of arXiv:2605.03057, 'Uniform-in-time quantitative fluctuations of large scale interacting particle systems'] Assume Assumption~\ref{ass:second-malliavin-uniform}. Let $\hat{\omega}$ be the constant defined via \eqref{eq:def-omega-second-malliavin}. Fix
$ 0 \le r \le s \le u $, $ i,j,k \in \left\{ 1,\dots,N \right\} $, and
$ \alpha,\beta \in \left\{ 1,\dots,m \right\} $. Define, for every $\rho \in [s,u]$,
\begin{equation*}
Y_\rho^{q,j,k,\alpha,\beta}
=
D_r^{k,\beta} D_s^{j,\alpha} X_\rho^{q,N}\quad\mbox{and}\quad
\bar v(\rho)
=
\frac1N \sum_{q=1}^N
\E\left(
\norm{Y_\rho^{q,j,k,\alpha,\beta}}^4
\right)^{1/4}.
\end{equation*}
Then, there exists a constant $ C > 0 $, depending only on the constants in
Assumption~\ref{ass:second-malliavin-uniform}, such that the following bounds hold.

\begin{enumerate}
\item[(i)] The initial condition in Lemma~\ref{lem:secondSDE} satisfies
\begin{align}

&\E\left(\norm{
\mathcal I_{r,s}^{i,j,k,\alpha,\beta}
}^4
\right)^{1/4}
\le
C e^{-\hat{\omega} (s-r)}
\left(
\mathbf{1}_{\left\{ i=j=k \right\}}
+
\frac1N
\left(
\mathbf{1}_{\left\{ i=j \right\}}
+
\mathbf{1}_{\left\{ i=k \right\}}
\right)
+
\frac1{N^2}
\right).
\end{align}

\item[(ii)] For every $ \rho \in [s,u] $,
\begin{equation}

\E\left(
\abs{G_{r,s}^{i,j,k,\alpha,\beta}(\rho)}^4
+
\norm{H_{r,s}^{i,j,k,\alpha,\beta}(\rho)}^4
\right)^{1/4}
\le
2^{1/4}\gamma \bar v(\rho).
\end{equation}

\item[(iii)] For every $ \rho \in [s,u] $,
\begin{align}

&\E\left(
\norm{R_{r,s}^{i,j,k,\alpha,\beta}(\rho)}^4
+
\norm{S_{r,s}^{i,j,k,\alpha,\beta}(\rho)}^4
  \right)^{1/4}\nonumber \\
  &\qquad\qquad\qquad\qquad
\le
C e^{-\hat{\omega} (\rho-r)}
\left(
\mathbf{1}_{\left\{ i=j=k \right\}}
+
\frac1N
\left(
\mathbf{1}_{\left\{ i=j \right\}}
+
\mathbf{1}_{\left\{ i=k \right\}}
+
\mathbf{1}_{\left\{ j=k \right\}}
\right)
+
\frac1{N^2}
\right).
\end{align}
\end{enumerate}

