[Lem balanced-rip of arXiv:2608.29018, 'Sharp Restricted Isometry Thresholds for\\ Global Minima of Rank-Restricted Matrix LASSO'] One has \begin{subequations}
\begin{align}
\mathsf{X}\ge{} & \Bigl(\bigl[(\alpha+\beta)^{2}-4\alpha\beta\bigr]t\nonumber \\[-1mm]
 & \quad-\bigl[(\alpha+\beta)^{2}-2\alpha\beta\bigr](2-t)\delta\Bigr)\mathsf{H}^{2}\nonumber \\[-1mm]
 & -2\alpha\beta(2-t)\delta\mathsf{T}^{2},\\
\mathsf{Y}\ge{} & t[t-(2-t)\delta]\mathsf{H}^{2},\qquad0<t<1,\\
\mathsf{Z}\ge{} & [t(2-t)-(t^{2}-2t+2)\delta]\mathsf{H}^{2}\nonumber \\[-1mm]
 & -2(t-1)\delta\mathsf{T}^{2},\qquad1\le t<4/3.
\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 195 of arXiv:2601.16377, '2601.16377'] The \emph{even} Green function is defined for any two points $p_1,p_2 \in \Sigma^{\textnormal{half}}$
\begin{equation}

\textnormal{Gr}^+(p_1,p_2) = \textnormal{Gr}(p_1,p_2) + \textnormal{Gr}(\overline{\varsigma}(p_1),p_2).
\end{equation}
where $\textnormal{Gr}$ is the usual Green function for $\Sigma^{\textnormal{half}}$ and $\overline{\varsigma}$ is the anti-holomorphic involution on $\Sigma^{\textnormal{half}}$ that sends a point $p \in \Sigma^{(q,\textnormal{L})}$ with coordinate $z$ to the point $\overline{\varsigma}(p)$ with coordinate $z^* \in \Sigma^{(q,\textnormal{R})}$. We define the \emph{even Gaussian free field} to be the centered (generalized) Gaussian field with covariance $\textnormal{Gr}^+$.

[Definition def:lf-strip of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] Let $(h, \mathbf{c})$ be sampled from $C_{\mathcal{S}}^{(\beta_1, +\infty), (\beta_2, -\infty), (\beta_3, s_3)}P_{\mathcal{S}}\times[e^{(\frac{\beta_1+\beta_2+\beta_3}{2}-Q)c}dc]$ with $\beta_1, \beta_2, \beta_3\in\mathbb{R}$,  $s_3\in\partial\mathcal{S}$ and
		{$$C_{\mathcal{S}}^{(\beta_1, +\infty), (\beta_2, -\infty), (\beta_3, s_3)} = e^{(-\Delta_{\beta_3}+\frac{(\beta_1+\beta_2)\beta_3}{4})|\textup{Re}s_3|+\frac{(\beta_1-\beta_2)\beta_3}{4}\textup{Re}s_3}.$$}
		Let $\phi(z) = h(z)+\frac{\beta_1+\beta_2-2Q}{2}|\textup{Re}z|+\frac{\beta_1-\beta_2}{2}\textup{Re}z+\frac{\beta_3}{2}G_{\mathcal{S}}(z, s_3)+\mathbf{c}$. We write $\textup{LF}_{\mathcal{S}}^{(\beta_1, +\infty), (\beta_2, -\infty), (\beta_3, s_3)}$ for the law of $\phi$.

