body:
[Theorem th:rescaledescapeprob of arXiv:2411.13505, 'Capacity of loop-erased random walk'] There exists a nontrivial random variable $X_\infty$ such that
\begin{equation}
	X_\infty=\lim_{n\rightarrow\infty} X_n
\end{equation}
almost surely and in $L^p$ for all $p>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 22 of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] \begin{equation*}{
\P(\Tree^{x}\cap B(0,R) \neq  \emptyset) \asymp \P(H(\Tree) > R^{2}) \mathrm{Cap}(B(0,R))g_{\theta}(x),
}\end{equation*}
where we recall that \(\asymp\) means here that the two terms have the same order for
large \(x\) and \(R\), up to some constants that do not depend on \(x\)
or \(R\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor LDP_uniform_321 of arXiv:2604.23751, 'Large deviation principles for pattern-avoiding permutations, and limit shapes for constra'] For all $n \geq 1$, let $\sigma_n$ be a uniform random $321$-avoiding permutation of size $n$.
    Then, the permutons $\mu_{\sigma_n}^\diagup$ satisfy a large deviation principle at speed $n$ with rate function
    \[\overline{H}(\mu) := \left\{
    \begin{array}{ll}
      \inf_{0 \le \nu \le \mu_{\diagup}} H(\proj(\mu_{{\begin{tikzpicture}[scale=.4]
  \draw (0,0) -- (0.5,0) -- (0.5,0.5);
  \draw[thick,dotted] (0,0) -- (0.5,0.5);
\end{tikzpicture}}}+\nu)) & \textrm{if } \mu \in  \mathcal P_{\Av(321)},\\
      \infty & \textrm{otherwise.}
    \end{array}
\right.\]
The same LDP holds for the permutons $\mu_{\sigma_n}.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 89 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let ${\bf L}^{\pm}$ denote the line parallel to the $y$-axis and with $x$-coordinate $x^\pm$, defined by
	\begin{flalign*}
		 x^-= \mathfrak{l}_{q'} (kN^{-1});\qquad     x^+= \bar{x} + N^{B\delta/9} \td_{\bar z}.  
	\end{flalign*}

[Lemma TISGM-to-cavity of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] Given any $\pmb\rho\in \TISGM^{\psi,\bar\psi}_{T^{\k}}$, its boundary law $\ell\in \P(\X)$ is a fixed point of the recursion $\BP:\P(\X)\rightarrow \P(\X)$ defined by
    \begin{align}
        \BP\ell(x)=\frac{1}{\zeta}\bar\psi(x)\cpr{\sum_{z\in \X}\psi(x,z)\ell(z)}^{\k-1},\quad \forall x\in \X,
    \end{align}
    where $\zeta$ is the normalizing constant. In fact, there is a one-one correspondence between the set $\TISGM^{\psi,\bar\psi}_{T^\k}$ and the set of fixed points $\Delta^*\coloneqq\pr{\ell\in \P(\X): \BP\ell=\ell}$. 
    Moreover, for any $\ell\in \Delta^*$, the edge marginal $\pi_{\pmb \rho_1}$ of the TISGM $\pmb \rho$ corresponding to $\ell$ satisfies  
    \begin{align}
        \pi_{\pmb\rho_1}(x,z)\propto \ell(x)\psi(x,z)\ell(z),\quad \forall x,z\in \X.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 3 (Wirtinger test) of arXiv:2609.01296, 'Asymptotic safety regions for Gabor frames generated by Hermite functions'] Let $g\in L^2(\mathbb R)$ be nonzero. Define
\begin{equation}
    \delta_g:= \frac{1}{2} \inf_{x\in[0,1]}
    \sqrt{\frac{\displaystyle\sum_{k\in\mathbb Z}|\widehat g((x-k))|^2}{\displaystyle\sum_{k\in\mathbb Z}(x-k)^2|\widehat g((x-k))|^2}}.
\end{equation}
Then, the Gabor system $\mathcal{G}(g,\delta \mathbb Z\times \mathbb Z)$ is a frame for $L^2(\mathbb R)$ for all $\delta < \delta_g$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop special_ziggurats of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Assume that $\mathcal{Z}(\Phi) \neq \varnothing$.
    \begin{enumerate}
        \item If $M \cong S^1 \times D^2$, then $\Phi$ is orbit equivalent to the suspension of a homeomorphism of $D^2$, and $\mathcal{Z}(\Phi)$ is a single point, the homological longitude.
        \item If $M \cong \mathbb{T}^2 \times I$, then $\Phi$ is orbit equivalent to the suspension of a homeomorphism of an annulus, and $\mathcal{Z}(\Phi)$ is a nontrivial interval contained in the locus of homological longitudes (for a framing coming from the product structure).
    \end{enumerate}

