body:
[Proposition prop:CE-law of arXiv:2509.04333, 'The limiting law of the Discrete Gaussian level lines'] Let $V\subset \mathbb Z^2$ be a connected domain, and consider the \ensuremath{\mathbb Z\textsc{gff}}\xspace model ${\widehat\pi}_V^\xi$ with boundary conditions $\xi$ that are $1$ on a $*$-connected path in $\partial_{\mathtt v} V$ and $0$ elsewhere so that they induce a unique disagreement polymer $(\gamma,\{D_i\},\{h_i\})$ in $V\cup \partial_{\mathtt v} V$ that contains boundary disagreements. Then for $\beta\geq \beta_0$, the law of this unique disagreement polymer is given by 
		\begin{equation}
			{\widehat\pi}^\xi_V(\gamma) =\frac1{Z} \exp\bigg(-{\ensuremath{\mathscr E}}_\beta(\gamma) + \sum_{\substack{{\ensuremath{\mathsf W}} \subset V \\ 
					{\ensuremath{\mathsf W}} \cap \Delta_\gamma \neq \emptyset}} \Phi({\ensuremath{\mathsf W}})\bigg)
		\end{equation}
		for a normalizer $Z = Z(\xi,V,\beta)$ and a decoration function $\Phi({\ensuremath{\mathsf W}})$ as per (def:disagree-polymer-len-energy-decor of the paper).

[Proposition 2 of arXiv:2609.01346, '2609.01346'] With the unit normal
$\nu=(\sin\theta,-\cos\theta\,\omega)$, equation
\eqref{eq:self-similar} is equivalent, away from $\cos\theta=0$, to
\begin{equation}
\begin{cases}
\dfrac{dx}{ds}=\cos\theta,\\
\dfrac{dr}{ds}=\sin\theta,\\[2mm]
A\left(\dfrac{\cos\theta}{r}\right)^{k-1}\dfrac{d\theta}{ds}
=x\sin\theta-r\cos\theta
+B\left(\dfrac{\cos\theta}{r}\right)^k.
\end{cases}
\end{equation}

[Lemma 14 (Truncated spacetime estimate) of arXiv:2608.25971, 'Positive \texorpdfstring{$\tau$}{tau}-bi-Ricci curvature and Mean curvature flow with surg'] Fix $\eta>0$ under \eqref{eq:normalized-space-form-setting}, and choose $ r>{(n+2)}/{2}$.  
There is $p_0=p_0(n,\alpha,\eta,r)$ such that the following holds.  If
$p\geq p_0$, $\sigma=p^{-1}$, $f=f_{\sigma,\eta}$, and
\begin{equation*}
 k\geq k_0:=1+\sup_{M_0}f_+,
 \qquad f_k=(f-k)_+,
\end{equation*}
then
\begin{align}
 &\sup_{0\leq s<T}\int_{M_s}f_k^p\,d\mu
 +\int_0^T\!\!\int_{M_s}
   \left(f_k^{p-2}|\nabla f|^2
   +f_k^{p-1}H^{\sigma-4}|\mathcal D|^2
   +H^2f_k^p\right)d\mu\,ds\notag\\
 &\hspace{35mm}\leq
 C\int_0^T\!\!\int_{\{f(\cdot,s)>k\}}
   \bigl(H^2f_+^p+1\bigr)d\mu\,ds,

\end{align}
where $C=C(n,\alpha,\eta,p)$.  Moreover,
\begin{equation}
 \int_0^T\!\!\int_{M_s}\bigl(H^2f_+^p+1\bigr)^r\,d\mu\,ds
 \leq C(n,\alpha,\eta,p,r).
\end{equation}

[Lemma lem:B.9_Chebyshev of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] For any  fixed  number $t>0$, let $n = \lfloor tM\rfloor$, then for  $y\in\mathbb{R}$,
\begin{equation}
\lim_{M\to\infty}
\frac{1}{n+1}\,
U_n\!\Bigl(1 + \frac{y}{2M^2}\Bigr)
\;=\;
\frac{\sin\bigl(t\sqrt{-y}\bigr)}{t\sqrt{-y}},
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:UB-LD-any-point of arXiv:2509.04333, 'The limiting law of the Discrete Gaussian level lines'] There exists $c_0>0$ such that, for $\beta$ large and every $V \subset \mathbb Z^2$, $h \geq 2$, and $x \in V$,
		\begin{equation}
			{\widehat\pi}_V^0(\phi_x = h) \leq \exp\bigg(-2\pi\beta\frac{h^2}{\log h} + c_0 \frac{h^2}{\log^2 h}\bigg)\,.
		\end{equation}

[Lemma 28 of arXiv:2606.23099, 'Path-dependent Affine Processes'] Assume the linear growth condition \eqref{LG-condition-existence}. Suppose $X = (X(t))_{t \in [0,T]}$ is a solution to equation \eqref{path_dependent_sde_existence}
    with initial condition $X(0)$ being $\ccF_0$-measurable and satisfying $E[\|X(0)\|^{2m}] < \infty$ for some $m \geq 1$. Then,
    \begin{equation}
        E\left[\sup_{t \in [0,T]} \|X(t)\|^{2m}\right] \leq (1+3E[\|X(0)\|^{2m}])e^{3C_{LG}T(T+4)}.
    \end{equation}
    In particular, $X$ satisfies $E[\int_{0}^{T} \|X(s)\|^{2m} dt] < \infty$.

