[Corollary 15 of arXiv:2609.02878, '2609.02878'] Fix \(q\in V\), where \(V\Subset Y^{\rm rv}\) lies in a Zariski product
region on whose preimage \cref{lem:general-block-volume} applies.  If
\(t_i\nearrow T\), \(\tau_i=T-t_i\), and
\begin{equation}
 \Omega_i(R):=
 \pi^{-1}\!\left(B_\eta(q,R\sqrt{\tau_i})\right)
\end{equation}
then, for every fixed \(R<\infty\),
\begin{equation}
 \Vol_{\tau_i^{-1}g(t_i)}\Omega_i(R)\le C_R
\end{equation}
for all sufficiently large \(i\).

[Definition def:unravel of arXiv:2608.08375, 'Algebraic formulas for first-passage times of Markov processes in the linear framework: ge'] Let $G$ be a strongly connected graph, and let $v \in \mathcal{V}(G)$. Then the unravelling of $G$ at vertex $v$, denoted $\mathcal{U}_v[G]$, has vertices $\mathcal{V}(\mathcal{U}_v[G]) = \mathcal{V}(G) \cup \{v^+\}$. The edges and labels of $\mathcal{U}_v[G]$ are acquired from those of $G$ through the following rules. Choose $j, k \in \mathcal{V}(G)$. 
\begin{enumerate}
    \item If $j \to_G k$ with $k \neq v$, then $j \to_{\mathcal{U}_v[G]} k$ and $\ell(j \to_{\mathcal{U}_v[G]} k) = \ell(j \to_G k)$.
    \item If $j \to_G v$, then $j \to_{\mathcal{U}_v[G]} v^+$ and $\ell(j \to_{\mathcal{U}_v[G]} v^+) = \ell(j \to_G v)$.
\end{enumerate}
There are no other edges in $\mathcal{U}_v[G]$.

[Cor const maps loc model of arXiv:2609.02409, 'Membranes and Maps'] For $Z=\mathbb{C}^{5}$, (conj:index of the paper) is equivalent to the identity
    \begin{equation}

        \GWargs{\mathbb{C}^{5}}{\mathsf{T}}{0}
        =
        \frac{1}{2}
        \sum_{g>1}
            \frac{B_{2g-2}}{2g-2}
            \left[
                \frac{\sum_{i=1}^5 \varsigma(2u\epsilon_i)}{\prod_{i=1}^5 \varsigma(u\epsilon_i)}
            \right]_{2g-2}
            u^{2g-2} \,,
    \end{equation}
    where $\sum_{i=1}^5\epsilon_i=0$. \qed (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 28 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb_{\leq n}$, $f:\cube^n\to \Rbb$, and $1\leq q\leq p\leq 2$,
\begin{align*}
    &\left\|f\right\|_{\Leb^\infty}^{2-p} \left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p} \geq M(p)^k\Vop^{k}(f) \\
    &\hspace{1cm} \cdot\left[1+ \frac{q}{2k(2-q)}\max\left\{\ln^+\left(\frac{\Vop^k(f)}{\left\|\left|\grad^k f\right|\right\|_{\Leb^q}^2}\right),\, \ln^+\left(\frac{\Vop^k(f)}{\sum_{J:|J|=k} \left\|\Dop_J f\right\|_{\Leb^q}^2}\right)\right\}\right]^\frac{kp}{2},
\end{align*}
where $M(p) = p \, 2^{-\frac{p}{2}} \max_{x\geq 0} \frac{1-\upe^{-x}}{x^{p/2}}\gtrsim 1$.

