[Lemma 20 (Slope-measure representation) of arXiv:2607.29560, 'Tractable Relaxations of Multivariate Stochastic Dominance via Optimal Transport and CVaR'] Let $u$ be a nonconstant increasing concave function on $[0,\overline x]$ with
$0<u'_+(0)<\infty$. There is a unique probability measure $\Pi_u$ on
$(0,\overline x]$ such that
\begin{equation}

u(x)=u(0)+u'_+(0)
\int_{(0,\overline x]}\min\{x,t\}\,\Pi_u(dt).
\end{equation}
For $x\in(0,\overline x]$,
\begin{equation}

\Pi_u([x,\overline x])=
\frac{u'_-(x)}{u'_+(0)}.
\end{equation}

[Defn ising of arXiv:2608.06500, 'Free energy of Ising models under a spectral condition'] For a weighted graph $G=(\text{\boldmath $A$},\text{\boldmath $h$})$ on $[N]$, the \emph{Ising
    model} is the probability measure $\mu_G$ on $\{-1,1\}^N$
    assigning a mass of

    \begin{align}
    \mu_G(\text{\boldmath $\sigma$})=\frac1{Z(G)} \exp\left( \frac12\<\text{\boldmath $\sigma$},
    \text{\boldmath $A$}\text{\boldmath $\sigma$}\> + \<\text{\boldmath $h$}, \text{\boldmath $\sigma$}\> \right)
\end{align}

    to spin configurations $\text{\boldmath $\sigma$}\in\{-1,1\}^N$. Here,

    \begin{align}
    Z(G) = \sum_{\text{\boldmath $\sigma$}\in\{-1,1\}^N} \exp\left( \frac12\<\text{\boldmath $\sigma$},
    \text{\boldmath $A$}\text{\boldmath $\sigma$}\> + \<\text{\boldmath $h$}, \text{\boldmath $\sigma$}\>
    \right)
    \end{align}

    is the \emph{partition function} of the model. We furthermore
    define the \emph{normalized free energy} or \emph{free energy
    density} of the model as

    \begin{align*}
F(G) = \frac1N \log Z(G).
\end{align*}

[Lemma 12 (Single-target order criterion) of arXiv:2608.16701, 'Order-Sensitive Fast-Synapse Limits in Sparse Excitatory--Inhibitory Threshold--Reset Netw'] The excitatory-first and inhibitory-first families produce different firing
counts on $[0,4\varepsilon]$ if and only if
\begin{equation}
 \boxed{x+a-b<\theta\le x+a.}

\end{equation}
In that case the excitatory-first target fires once and the
inhibitory-first target does not fire.

[Proposition 5 ({\cite[Lemma 3.11) of arXiv:2607.18104, '2607.18104'] {GZ:fractal}}]
There exist constants $c,C>0$, such that for all  $\phi>0$,
\begin{align*}
&\P\Bigg(\TF_{s+\theta^{-1}}(\pi) \geq \phi \theta^{-2/3}\log^{3}\big(1+\theta\lVert (x,s;y,t)\rVert_2\big),\,\,\,\forall(x,s;y,t)\in \R^{4}_{\uparrow},\pi\in \mathfrak{G}_{(x,s),(y,t)}, \theta\geq 2(t-s)^{-1}\Bigg)\\
&\leq C\exp\big({-c \phi^{9/4}}\big). 
\end{align*} By symmetry, the result holds with $s+\theta^{-1}$ replace by  $t-\theta^{-1}$. Hence,  
\begin{equation}
\begin{split}

&\P\Bigg(\TF(\pi) \geq \phi  |t-s|^{2/3}\log^{3}\bigg(1+\frac{\lVert (x,s;y,t)\rVert_2}{|t-s|}\bigg),\,\,\,\forall (x,s;y,t) \in \R^{4}_{\uparrow},\pi\in \mathfrak{G}_{(x,s),(y,t)}\Bigg)  \\
&\leq C\exp({-c \phi^{9/4}}).   
\end{split}

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 19 ({\cite{QAlg05}*{\S~3.2 Corollary 5.4}}) of arXiv:2609.03836, 'Koszul Orlik--Solomon Algebras from Non-supersolvable Arrangements'] \label[Thm]{thm:regularity_Koszul}
    Suppose $R$ and $S$ are  standard graded $\mathbb{K}$-algebras and we are given a surjective graded $\mathbb{K}$-algebra homomorphism $R \twoheadrightarrow S$. Assume that $S$ has a linear free resolution as a left $R$-module.
    Then $R$ is Koszul if and only if $S$ is Koszul. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 15 of arXiv:2608.25094, 'Noising-Denoising by Large Temperature Schr\"{o}dinger Bridges'] Retain the setting of Theorem \ref{thm:compact-manifold}. When $\mu = \nu$, it holds that
    \begin{align}
        \lim\limits_{T \to +\infty} \exp(\lambda_1 T)(H(Q^{T}|P^{T})+H(P^{T}|Q^{T})) &= \sum_{i \in \mathcal{I}_{1}}p_i^2,
    \end{align}
    where $p_i = \langle \rho, \psi_i \rangle_{L^2(\diffref)}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi def:regular of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $c,q\in(0,\infty)$.
We say that an innovation $ (X, U ) $ is \emph{$(c,q)$-regular}
on a set $ \mathcal V \subseteq {\mathbb R}^d $
if and only if for all $\theta\in \mathcal V$, $i\in\{1,\dots,d\}$, $\lambda\in[0,\infty)$
we have that
\bas{
  - \ln {\mathbb E}[e^{-\lambda X^{(i)}(\theta,U)^2}]\ge (c\lambda)\wedge q.
}

[Lemma twop-head of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] The two point Palm probability distribution of the head point process is 

\begin{equation}
\mathbb{P}_{{\mathcal H }}^{(t, h),(t', h')}(B):=\mathbb{P}\left({\mathcal H }^{(t, h), (t', h')}\in B\right),{\nonumber}

\end{equation} 

for any $B\in {\mathcal M }(\mathbb{H}^+)$, with ${\mathcal H }^{(t, h), (t', h')}:={\mathcal H }+ \delta_{(t, h)}+\delta_{(t', h')}$
and ${\mathcal H }$ the stationary version of the head point process. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 4 of arXiv:2606.29512, '2606.29512'] A real-, vector-, or tensor-valued function
on $\Omega\times[0,T]\times\mathbb \cR$
is called admissible if
$f=f^M+f^B$  
for some $\cO\otimes\cB(\mathbb\cR)$-measurable 
functions $f^M$, $f^B$, and 
a constant $\hat f>0$ and a nonnegative optional process
$\bar f=(\bar f_t)_{t\in[0,T]}$ exist such that 
\begin{equation}

\left(
\dashint_{B_\rho}{\bf1}_{\cR}|f^M(t,x)|^r\,dx
\right)^{1/r}
\le
\hat f\,\rho^{-1} \quad \text{for $\mathbb{P}\otimes dt$-a.e 
$(\omega,t)\in\Omega\times[0,T]$}
\end{equation}
for all $B_\rho\in\mathbb B_\rho$, $\rho\leq1$, 
and
\begin{equation}

\operatorname*{ess\,sup}_{x\in\cR}
|f_t^B(x)|
\leq \bar f_t \,\, \text{(a.s.)},
\quad
\sup_{\omega\in\Omega}
\int_0^T \bar f_t^2\,dt<\infty.
\end{equation}

