[Dfn 1. dfn: resistance forms associated with electrical networks of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] [{Resistance forms associated with electrical networks}]  

  Let $G$ be an electrical network.
  For functions $f,g: V_{G} \to \mathbb{R}$,
  we set 
  \begin{equation}
    \mathcal{E}_{G}(f, g) 
    \coloneqq 
    \frac{1}{2} 
    \sum_{x, y \in V_{G}} 
    \mu_{G}(x,y) (f(x) - f(y)) (g(x) - g(y))
  \end{equation}
  (if the right-hand side is well-defined).
  We then set $ \mathcal{F}_{G} \coloneqq \{ f \in \mathbb{R}^{V_{G}} \mid \mathcal{E}(f, f) < \infty \}$
  and, for each $x, y \in F$,
  \begin{equation}
    R_{G}(x,y) 
    \coloneqq 
    \sup 
    \{
      \mathcal{E}(f, f)^{-1} \mid f \in \mathcal{F},\, f(x)=1,\, f(y) = 0
    \},
  \end{equation}
  where we define $\sup \emptyset \coloneqq 0$.

[Defi mean of arXiv:2411.04157, 'Stochastic homogenization of dynamical discrete optimal transport'] We say that $(\theta_{xy})_{x,y\in \mathcal X}$ is a \emph{family of mean functions} if the following conditions hold:
\begin{enumerate}
        \item For each $x,y\in\mathcal X$, $\theta_{xy}\in C( [0,\infty)\times [0,\infty);[0,\infty))$ is positively $1$-homogeneous, jointly concave, nondecreasing in each variable and normalized (that is $\theta(1,1)=1$).
        \item For each $x,y\in\mathcal X$ and $r,s\geq 0$, $\theta_{xy}(r,s)=\theta_{yx}(s,r)$.
    \end{enumerate}

[Lemma 19 of arXiv:2608.27630, 'Oriented planar maps and \\ annular mating of trees'] For any $a,b,c>0$ and with $\mathbb{a}$ as in~\eqref{eq: gamma correlated BM},
     \begin{equation}

        B^{\gamma, \bH}_{0, -a+ib} = B^{\gamma,  \bbR_+^2-c}_{0, -a+ib} + \mathbb{a} \int_0^\infty \big( B^{\gamma, \bbR_+^2-c}_{0, -c+i d} \oplus B^{\gamma, \bH}_{-c+i d, -a+ib} \big) \d d
