[Proposition 5 of arXiv:2603.28170, 'Stabilization time of finite configurations with a second class particle in discrete TASEP'] \begin{enumerate}
\item
For $p=1/2-\lambda/(2\sqrt n)$, there is a constant $c$ that depends only on $\lambda$ such that for all $n$ almost surely
\begin{equation}
\E\left(M-K\bigm|M\right)\le c\sqrt{n}.
\end{equation}
\item
For $p<1/2$ fixed, there is a deterministic constant $c$ such that $\E\left(M-K\bigm|M\right)\le c$ almost surely for all $n$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2605.14206, 'The clumsy coupon collector's problem'] The ordinary generating function of $G$ is
  \[
      \phi_G(z)
      = \sum_{\ell=0}^m \frac{m^{\underline{\ell}}
                \left(1-p\right)^\ell}{\left(m/z - 1\right)^{\underline{\ell}}}
      = \sum_{\ell=0}^m \binom{m}{\ell} \binom{m/z-1}{\ell}^{-1} \left(1-p\right)^\ell.
  \]
  \begin{proof}
    This proof mimics the previous one.
    For any $k \in \{ 1, 2, \ldots, m \}$ and $x \in (0, 1)$ it holds, via integration by parts,
    \begin{align*}
      &\quad\,\int_0^\infty \left[ (1-p)\left(e^{xt/m} - 1\right) + 1\right]^k e^{-(1-(m-k)x/m)t} \, dt\\
      &= \frac{k\left(1-p\right) x}{m \left(1 - \left(m-k\right) x/m \right)}
      \int_0^\infty \left[(1-p)\left(e^{xt/m} - 1\right) + 1\right]^{k-1} e^{-(1-(m-k+1) x/m)t} \, dt\\
      &\quad\, + \frac{1}{1-\left(m-k\right)x/m}.
    \end{align*}
    The Laplace--Borel transform combines with $m$ applications of this fact to give us
    \begin{align*}
      \phi_G(x) &= \int_0^\infty
        \left[ (1-p) \left( e^{xt/m} - 1 \right) + 1 \right]^m
        e^{-t} \, dt\\
        &= \sum_{\ell=0}^m \frac{m^{\underline{\ell}} \left(1-p\right)^\ell x^\ell}{m^\ell
        \prod_{k \leqslant \ell} (1-k\,x/m)}\\
        &= \sum_{\ell=0}^m \frac{m^{\underline{\ell}} \left(1-p\right)^\ell
          }{
            (m/x - 1)^{\underline{\ell}}}
        = \sum_{\ell = 0}^m \frac{\binom{m}{\ell}}{\binom{m/x-1}{\ell}} (1-p)^\ell,
        \quad 0 < x < 1. \qedhere
    \end{align*}
  \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma le:laplace-tail-bound2 of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $ c, q \in (0,\infty) $, $ \beta \in (0, 1) $, $ n_0, n \in {\mathbb N} $ with $ n_0 < n $.
Let $ V_n^* $ be a nonnegative random variable which satisfies for all $ \lambda \in [0,\infty) $ that
\bas{
  - \ln
  \mathbb{E}\bigl[
    e^{ - \lambda V_n^* }
  \bigr]
  \ge
  \sum_{ k = n_0 + 1 }^n
  \min\Bigl\{ q, c \frac{1-\beta}{1-\beta^n} \beta^{n-k} \lambda \Bigr\} .
}
Then 
\bas{
{\mathbb P}\Bigl(V_n^*\le \frac c2\,\frac{1-\beta^{n-n_0}}{1-\beta^n}\Bigr)
\le \exp\Bigl(-\frac q2\,\frac{1-\beta^{n-n_0}}{1-\beta}\Bigr).
}
If, in addition, $n-n_0\ge \frac12(1-\beta)^{-1}$, then
\bas{
{\mathbb P}\Bigl(V_n^*\le \frac c2\,(1-e^{-1/2})\Bigr)
\le \exp\Bigl(-\frac q2\,\frac{1-e^{-1/2}}{1-\beta}\Bigr).
}

