[Proposition prop:dgt4-linearization of arXiv:2609.02829, 'Quantitative explosion and percolation of the divisible sandpile'] Fix $T>0$ and let $n_R\coloneqq\lfloor R^2T\rfloor$. For every
	$\varphi\in C_c^\infty(\mathbb{R}^d)$,
	\begin{equation}
	\begin{aligned}
		\mathbb{E}\Biggl[\Biggl(
		R^{(d-4)/2}
		\Biggl(
		u_{n_R}-\mathbb{E} u_{n_R}(0)
		-\sum_{j=0}^{n_R-1}
		\left(1-\frac{j}{R^2T}\right)^\kappa P^j\zeta
		\Biggr)^{(R)}(\varphi)
		\Biggr)^2\Biggr]
		\longrightarrow0\, .
	\end{aligned}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:annular-frequency-grid-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] For every \(n\ge1\), there exists a finite set \(\mathcal N_n\subset\{\xi\in\mathbb{R}^2:2^n\le\lvert\xi\rvert\le2^{n+1}\}\) such that for every \(\xi\) with \(2^n\le\lvert\xi\rvert\le2^{n+1}\), there exists \(\eta\in\mathcal N_n\) satisfying
\begin{equation}
\lvert\xi-\eta\rvert\le \frac{1}{8\pi}2^{-(s/2+\varepsilon)n}.
\end{equation}
Moreover,
\begin{equation}
\#\mathcal N_n\le C2^{(2+s+2\varepsilon)n}.
\end{equation}

[Theorem 48 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] For a normed space $E$ the following conditions are equivalent:
\item[(i)] $\dim E<\8$;
\item[(ii)] $F:=\Co_{\ph}\left(\Ba_{E^{*}},\mathrm{w}^{*}\right)$ is a regular sublattice of $\Co\left(\Ba_{E^{*}},\mathrm{w}^{*}\right)$;
\item[(iii)] $F$ is $1$-monotonically bounded;
\item[(iv)] $F$ is semicontinuous, that is $\Ba_{F}$ is order closed in $F$;
\item[(v)] $F$ is pointwise demicontinuous;
\item[(vi)] $F$ is not anti-demicontinuous, that is the order adherence of $\Ba_{F}$ is not equal to $F$.

[Theorem MixEV of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] In the setting of (mix of the paper), let $O \in C_c^{\infty}\left(\mathbb{R}^n\right)$ be an arbitrary smooth, compactly supported function. If (equation eq:condA1 of the paper) holds for $k=1$, then for any fixed $n\in \mathbb{N}$, there exists a constant $c>0$ so that 
\begin{align}
 &\left|	\mathbb{E} O\pa{\gamma_+ \left({D N}\right)^{2/3}\left({E^+-\lambda_1}\right),\ldots,\gamma_+ \left({D N}\right)^{2/3}\left({E^+-\lambda_n}\right)}\right.\nonumber \\
 &\left.-\mathbb{E} O\pa{ \left({D N}\right)^{2/3}\left({2-\mu_1}\right),\ldots, \left({D N}\right)^{2/3}\left({2-\mu_n}\right)}   \right|\le N^{-c} ,
\end{align}

where $\mu_1\ge\mu_2\ge\cdots\ge\mu_n$ denote the largest $n$ eigenvalues of a $DN\times DN$ GUE. The corresponding edge universality result also holds for $\gamma_-(DN)^{2/3}(\lambda_{DN}-E^-,\ldots,\lambda_{DN-n}-E^- )$ at the left edge $E^-$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop prop of arXiv:2411.01847, 'Well-Posedness of Stochastic Chemotaxis System'] For every $m\geq 1$, the process  $U_n(t)$ satisfies the following equation in $L^2(\mathcal{O})$ for $t< \tau_m$,
    \begin{align}
        U_n(t) = \int_0^{t} \left( -A U_n(s) - \nabla \cdot R_n \left( \chi u(s) \nabla G * u(s) \right) + R_n g(u(s)) \right) \, ds

        + \int_0^{t} R_n \sigma(u(s)) \, dW_s.
    \end{align}

