[Theorem 4 of arXiv:2608.27143, 'An approximate zero bias transformation for random sums: Applications to sampling with out'] Let $X_1,X_2,\ldots$ be independent mean zero random variables such that $\Var(X_i) = \sigma_i^2$. Let $W=\sum_{i=1}^NX_i$, where $N$ is a discrete random variable with support being a subset of $\mathbb{N}_0$ and independent of all $X_i$.
		Define $\sigma^2 := \Var(W) = \sum_{i=1}^\infty\sigma_i^2 P(N\ge i)$. Let $I$ be as in \eqref{Idef}.  Then
	\begin{align*}
		\left|\E h\left(\frac{W}{\sigma}\right)-N(h)\right|\leq \frac{||f'_h||}{\sigma^3}\sum_{i=1}^\infty \left({1\over 2}\E|X_i|^3+ \sigma_i^2\E|X_i| \right)P^2(N\ge i)+2 ||f^{'}_{h}|| \cdot {P(N < I)},
	\end{align*}
	where $N(h) = \E h(Z)$ with $Z \sim \mathcal{N}(0,1)$, $h \in \mathcal{H}_1$ and $f_h$ is the solution to the Stein's equation. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 112 of arXiv:2601.16377, '2601.16377'] Consider the variational datum \eqref{eq_ZW_data_1}-\eqref{eq_ZW_data_2} and suppose that the sextuple
 \[
 (\theta, \hat n, \hat A_1', \hat A_2', \hat B_1', \hat B_2')
 \]
 belongs to the domain $\mathcal D$ of Definition~\ref{Definition_ZW_set}. Then the simplified equilibrium measure $\widetilde \mu$ has a single band $(\alpha,\beta)$ and its density inside the band is given by
 \begin{equation}

 \forall x \in (\alpha,\beta)\qquad \widetilde \mu(x) =\frac{1}{\pi\theta}\,\arctan\Bigg(\hat D' \frac{\sqrt{(x - \alpha)(\beta - x)}}{q^+(x)}\Bigg),
 \end{equation}
 where $\arctan(z)$ takes values between $0$ and $\pi$ for $z\in [-\infty,+\infty]$ with $\arctan(\pm \infty)=\tfrac{\pi}{2}$,
 \begin{equation}

\begin{split} q^+(z) & = 2z^2 - (\hat{A}'_1 + \hat{A}'_2 + \hat{B}'_1 + \hat{B}'_2)z + \hat{B}'_1\hat{B}'_2 + \hat{A}'_1\hat{A}'_2 - \theta\hat{n}(\theta\hat{n} + \hat{D}') \\
\alpha & = \frac{1}{(\hat{D}')^2}\Big(-(\hat{A}'_1 + \hat{A}'_2 + \hat{B}'_1 + \hat{B}'_2)(\hat{D}' + \theta\hat{n})\theta\hat{n} + (\hat{B}'_1\hat{B}'_2 - \hat{A}'_1\hat{A}'_2)(\hat{D}' + 2\theta\hat{n})- \sqrt{\Delta} \Big), \\
 \beta & = \frac{1}{(\hat{D}')^2}\Big(-(\hat{A}'_1 + \hat{A}'_2 + \hat{B}'_1 + \hat{B}'_2)(\hat{D}' + \theta\hat{n})\theta\hat{n} + (\hat{B}'_1\hat{B}'_2 - \hat{A}'_1\hat{A}'_2)(\hat{D}' + 2\theta\hat{n}) + \sqrt{\Delta}\Big), \\
 \Delta & = 4\theta\hat{n}(\hat{D}' + \theta\hat{n})\hat{D}'_{1,1}\hat{D}'_{1,2}\hat{D}'_{2,1}\hat{D}'_{2,2} > 0.
\end{split}
\end{equation}
Besides, if the parameters are in $\mathcal{D}^{\tau}$ with $\tau \in \{\pm 1\}$, then
\begin{itemize}
\item[$\bullet$] if $\tau\,q^+(\hat{A}_1') > 0$, then $[\hat{A}'_1,\alpha]$ is a void;
\item[$\bullet$] if $\tau\,q^+(\hat{A}_1') < 0$, then $[\hat{A}'_1,\alpha]$ is a saturation;
\item[$\bullet$] if $\tau\,q^+(\hat{B}_1') > 0$, then $[\beta,\hat{B}'_1]$ is a void;
\item[$\bullet$] if $\tau\,q^+(\hat{B}_1') < 0$, then $[\beta,\hat{B}'_1]$ is a saturation.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 27 of arXiv:2605.30560, 'Projected McKean--Vlasov Dynamics for Entropic Weak Optimal Transport'] Suppose $(\X_n)_{n \in \mathbb N} \in \rm FP_2(\mu,\nu)$. If $\AW_2(\X_n, \mathbb X) \to 0$ for some $\mathbb X \in \rm FP_2(\mu,\nu)$, then we have 
    \begin{align*}
       \liminf_{n\to \infty} \tilde I(\X_n) \geq \tilde I(\mathbb X). 
    \end{align*}
In particular, $t \mapsto \tilde I(\pi_t)$ is l.s.c. where $(\pi_t)_{t \geq 0}$ is the solution to \eqref{eq:SDE}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 23 of arXiv:2606.21111, 'On Elephant Random Walk with Delayed Amnesia'] The following almost sure convergence results hold true:\\
\noindent{(i)} For $0\le p< (4a-1)/4a$, we have
\begin{equation*}
	\lim_{n\to\infty}\frac{G_n}{n}=0\ \ \text{a.s.},
\end{equation*}
\noindent{(ii)} for $p= (4a-1)/4a$, we have
\begin{equation*}
	\lim_{n\to\infty}\frac{G_n}{\sqrt{n}\log n}=0\ \ \text{a.s., and}
\end{equation*}
\noindent{(iii)} for $(4a-1)/4a<p\le 1$, we have
\begin{equation*}
\lim_{n\to\infty}\frac{G_n}{n^{2a(p-1)+1}}=\frac{L}{(2a(p-1)+2)}\ \ \text{a.s.},
\end{equation*}
where $L$ is as given in \eqref{Lvariab}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:HB-BAOAB of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Let $(X_k,V_k)_{k\ge0}$ be the BAOAB chain, with $\xi_k$ the Gaussian variable used in the $k$th step. Let $\xi_0\sim\mathcal N(0,\mathrm{Id}_d)$ be independent of $(\xi_k)_{k\ge1}$, or alternatively let $\xi_0$ be the zero vector, and define the auxiliary variable $X_{-1}$ by
\begin{equation}
 V_0=\frac{2\beta}{(1+\beta)h}(X_0-X_{-1})
 +\frac{\varsigma}{1+\beta}\,\xi_0-\frac h2\nabla U(X_0).
\end{equation}
Then, for $k\ge0$,
\begin{equation}
 X_{k+1}=X_k+\beta(X_k-X_{k-1})-s\nabla U(X_k)+\widetilde\zeta_{k+1},
 \qquad
 s=\frac{h^2}{2}(1+\beta),
\end{equation}
where
\begin{equation}
 \widetilde\zeta_{k+1}=\frac h2\varsigma\,(\xi_k+\xi_{k+1}).
\end{equation}
If $\xi_0\sim\mathcal N(0,\mathrm{Id}_d)$, the sequence $(\widetilde\zeta_k)_{k\ge1}$ is a centered stationary $1$-dependent Gaussian sequence with
\begin{equation}
 \mathbb E[\widetilde\zeta_k\widetilde\zeta_k^\top]=\frac{h^2}{2}(1-\beta^2)\mathrm{Id}_d,
 \qquad
 \mathbb E[\widetilde\zeta_k\widetilde\zeta_{k+1}^\top]=\frac{h^2}{4}(1-\beta^2)\mathrm{Id}_d.
\end{equation}
If (equation eq:vpair-baoab of the paper) is imposed with $\xi_0=0$, then $\widetilde\zeta_1=\frac h2\varsigma\,\xi_1$ has the smaller covariance $\frac{h^2}{4}(1-\beta^2)\mathrm{Id}_d$, while (equation eq:zetacov-baoab of the paper) holds from the second update onward.

