[Lemma lem:matrix_local of arXiv:2603.27906, 'Marked GUE-corners process in doubly periodic dimer models'] For $(z_1,w_1)$ and $(z_2,w_2)$ in a neighbourhood of $q_{\infty}$, let
~$z_i=1+\frac{Z_i}{N^\frac{1}{2}}$,~$i=1,2$, and set
\begin{equation}
\tilde g(\ell x+i,2y+j)=\prod_{m=1}^i(1+\alpha_m^{-1}\beta_m)(1+\alpha_{m+1}\beta_m^{-1})\alpha_{i+1}^{-j},
\end{equation}
and let~$\nu$ be given in~(equation eq:period_function of the paper). Then, as~$N\to \infty$, 
\begin{multline} 
\boldsymbol{\mathcal{M}}_{i_1,j_1,i_2,j_2}\left(z_1,w_1;z_2,w_2\right)

= \nu(\ell-i_2,j_2)\frac{Z_1^{i_1}}{Z_2^{i_2}}\frac{\tilde g(\ell x_2+i_2,2y_2+j_2)}{\tilde g(\ell x_1+i_1,2y_1+j_1)}\frac{N^{\frac{i_2}{2}}}{N^{\frac{i_1}{2}}}\left(1+\mathcal{O}\left(\frac{|Z_1|+|Z_2|}{N^{\frac{1}{2}}}\right)\right),
\end{multline}
where, assuming $|Z_k|\leq N^{\frac{1}{2}}$, the implicit constant in the remainder term is independent of $Z_k, x_k, i_k, y_k, j_k$, $k=1,2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem finite-persistence-claims of arXiv:2410.24170, 'Persistent hubs in CMJ branching processes with independent increments and preferential at'] Assume Assumption~(ass:gen-ass of the paper) is satisfied. Then, with regards to the process $(\mathscr{T}_{t})_{t \geq 0}$, we have the following claims:
\begin{enumerate}
    \item  We have $\lim_{n \to \infty} \max_{u \in \mathscr{T}_{\tau_{n}}} \outdeg{u, \mathscr{T}_{\tau_{n}}} = \infty$ almost surely. 

    \item  If $\sum_{i=1}^{\infty} (X_{i} - X'_{i})$ converges almost surely, then for any $u, v \in \mathcal{U}$ we have 
    \begin{equation} 
    \Prob{\win(u,v) \cup \win(v,u)} = 1.
    \end{equation}
    \item  If $\sum_{i=1}^{\infty} (X_{i} - X'_{i})$ diverges almost surely, there exists an increasing function $\phi\colon \mathbb{N} \rightarrow \mathbb{N}$ such that, for any $u \in \mathcal{U}$, $j \in \mathbb{N}$ we have 
    \begin{equation} 
    \Prob{\exists k \leq \phi(j)\colon \sum_{\ell = 1}^{k} X(uj\ell) < \sum_{\ell = j+1}^{k} X(u\ell)} \geq 1/2.
    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 61 of arXiv:2607.18104, '2607.18104'] For each $j\in \N$, consider families of ASEPs on the integers $(\eta_t^{N,i,1,j})_{t \geq 0}$ and $(\eta_t^{N,i,2,j})_{t \geq 0}$ under the patched coupling with $i \in \lbr M \rbr$ and $N \in \N$. We define the $\boldsymbol{(\delta,N)}$\textbf{-patched ASEP} $(\eta^{\textup{patch},N,i}_t)_{t \geq 0}$, taking values in $\{0,1\}^{\Z/N\Z}$, as follows. First, let $j=1$, and define
\begin{equation}
\eta^{\textup{patch},N,i}_t(x) := \begin{cases} \eta_t^{N,i,1,1}(x) & \text{ if } (x,t) \in \mathcal{I}_{\delta,N}^{\rho}\big(0,\frac{1}{2}\big) ,   \\
\eta_t^{N,i,2,1}(x) & \text{ if } (x,t) \in \mathcal{I}_{\delta,N}^{\rho}\big(\frac{1}{2},1\big) , 
\end{cases}
\end{equation} where the points $x$ are understood modulo $N$. 

In order to define $\eta^{\textup{patch},N,i}_t$ for $t>\delta N^{3/2}$, we proceed inductively. Suppose that we have constructed $(\eta^{\textup{patch},N,i}_t)_{t \in [0,j \delta N^{3/2}]}$ for some $j\in \N$ (the base case $j=1$ is covered above). Then consider two families of ASEPs $(\eta^{N,i,1,j+1}_t)_{t \geq 0}$ and $(\eta^{N,i,2,j+1}_t)_{t \geq 0}$, started at time $j\delta N^{3/2}$, where assign for all $i\in \lbr M \rbr$
\begin{equation}
\begin{split}
        \eta^{N,i,1,j+1}_{j\delta N^{3/2}}(x) &= \bar{\eta}^{N,i}_{j\delta N^{3/2}}(x) \ \forall x \colon (x,j\delta N^{3/2}) \in \mathcal{I}_{\delta,N}^{\rho}\Big(-\frac{1}{8},\frac{5}{8}\Big) , \\
        \eta^{N,i,2,j+1}_{j\delta N^{3/2}}(x)&=  \bar{\eta}^{N,i}_{j\delta N^{3/2}}(x) \ \forall x \colon (x,j\delta N^{3/2}) \in \mathcal{I}_{\delta,N}^{\rho}\Big(\frac{3}{8},\frac{9}{8}\Big)  .
\end{split}
\end{equation} For all other $x$, we assign independent Bernoulli-$\rho$-random variables.
Then $(\eta^{N,i,1,j+1}_t)_{t \geq 0}$ and $(\eta^{N,i,2,j+1}_t)_{t \geq 0}$ evolve according to the patched coupling between time $j\delta  N^{3/2}$ and $(j+1)\delta N^{3/2}$, independently of the processes up to time $\delta j N^{3/2}$. Set for all $s \in [j \delta N^{3/2},(j+1)\delta N^{3/2}]$,
\begin{equation}
\eta^{\textup{patch},N,i}_{s}(x) := \begin{cases} \eta_{s}^{N,i,1,j+1}(x) & \text{ if } (x,s) \in \mathcal{I}_{\delta,N}^{\rho}\big(0,\frac{1}{2}\big) ,   \\
\eta_s^{N,i,2,j+1}(x) & \text{ if } (x,s) \in \mathcal{I}_{\delta,N}^{\rho}\big(\frac{1}{2},1\big) . 
\end{cases}
\end{equation}

[Lemma 9 (Polynomial Gaussian envelope) of arXiv:2609.01319, 'Matched Queries for Curvature and Density at Branching Junctions'] Fix a compact $\cQ\subset\R^D$. There are $c>0$ and constants $C_{m,\cQ}$ such that the following holds. Let $v\in\Sph^{D-1}$, $u\ge0$, and let $q_t=uv+t\xi$ for $0\le t\le1$, with $\norm{\xi}\le u/2$. For every fixed mixed-derivative order $m$ of $K_z(q)=e^{-\norm{z-q}^2/2}$ in $(z,q)$,
\begin{equation}
\abs{\partial^m K_z(q_t)}
\le C_{m,\cQ}(1+u)^{m}e^{-cu^2},
\qquad z\in\cQ.

\end{equation}
The same form holds for vector and matrix derivatives.

[Proposition prop:tree of arXiv:2604.17253, 'Large Deviations for the Nonlinear Schrödinger Equation with Randomized Quasi-Periodic Ini'] For all $k\geq1$, we have
\[
{c}_k(t,\boldsymbol{n})
=
\sum_{\gamma^{(k)}\in\Gamma^{(k)}}
\sum_{\substack{\spadesuit^{(k)}\in{\mathrm D}^{(k,\gamma^{(k)})}\\
\lambda(\spadesuit^{(k)})=\boldsymbol{n}}}
\mathfrak C^{(k,\gamma^{(k)})}(\spadesuit^{(k)})
\mathfrak I^{(k,\gamma^{(k)})}(t,\spadesuit^{(k)})
\mathfrak F^{(k,\gamma^{(k)})}(\spadesuit^{(k)}),
\]
where for $0\in\Gamma^{(k)}$,
\begin{align*}
\mathfrak C^{(k,0)}(\spadesuit^{(k)})
&={c}(\lambda(\spadesuit^{(k)}))g_{\lambda(\spadesuit^{(k)})},\\
\mathfrak I^{(k,0)}(t,\spadesuit^{(k)})
&=e^{-\mathrm{i} Q(\lambda(\spadesuit^{(k)})) t},\\
\mathfrak F^{(k,0)}(\spadesuit^{(k)})
&=1;
\end{align*}
for $1\in\Gamma^{(1)}$,
\begin{align*}
\mathfrak C^{(1,1)}(\spadesuit^{(1)})
&=\prod_{j=1}^3\{{c}(\boldsymbol{n}^j)g_{\boldsymbol{n}^j}\}^{\ast^{[j-1]}},\\
\mathfrak I^{(1,1)}(t,\spadesuit^{(1)})
&=\int_0^t e^{-\mathrm{i} Q(\lambda(\spadesuit^{(1)}))(t-s)}
\prod_{j=1}^{3}
\left\{e^{-\mathrm{i} Q(\boldsymbol{n}^j) s}\right\}^{\ast^{[j-1]}}
\,\mathrm{d}s,\\
\mathfrak F^{(1,1)}(\spadesuit^{(1)})
&=\mathrm{i}{\varepsilon^\alpha} ;
\end{align*}
and for $\gamma^{(k)}=(\gamma_j^{(k-1)})_{j=1}^3$,
\begin{align*}
\mathfrak C^{(k,\gamma^{(k)})}(\spadesuit^{(k)})
&=\prod_{j=1}^3
\left\{\mathfrak C^{(k-1,\gamma_j^{(k-1)})}(\spadesuit_j^{(k-1)})\right\}^{\ast^{[j-1]}},\\
\mathfrak I^{(k,\gamma^{(k)})}(t,\spadesuit^{(k)})
&=\int_0^t e^{-\mathrm{i} Q(\lambda(\spadesuit^{(k)}))(t-s)}
\prod_{j=1}^3
\left\{\mathfrak I^{(k-1,\gamma_j^{(k-1)})} (s,\spadesuit_j^{(k-1)})\right\}^{\ast^{[j-1]}}
\,\mathrm{d}s,\\
\mathfrak F^{(k,\gamma^{(k)})}(\spadesuit^{(k)})
&=\mathrm{i}{\varepsilon^\alpha} \prod_{j=1}^3
\left\{\mathfrak F^{(k-1,\gamma_j^{(k-1)})}(\spadesuit_j^{(k-1)})\right\}^{\ast^{[j-1]}}.
\end{align*}

[Prop 69 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] The following holds if the constant $L$ entering \Cref{yy} is chosen to be sufficiently large. Let the constants $A,B,R$ satisfy
			\begin{eqnarray}

				B \ge 1000 R \ge 1000A \ge 30000. 
			\end{eqnarray}
			Let $q$ satisfy \eqref{eq:condizq}; let $\md,\omega > 0$ satisfy \eqref{condizd} and \eqref{domega}; and let the point $w_0$ around which the cell $\mathcal Y$ is centered satisfy the assumptions in \Cref{def:w0}. Also let $q'$ satisfy
			\begin{align}

				\begin{aligned} 
					&  q' \in [q - N^{R\delta-1} \omega, q].
				\end{aligned}
			\end{align}
			Further assume:
			\begin{enumerate}
				\item [(i)]   For all $w \in \mathcal Y$, we have 
				\begin{eqnarray}

					H_0 (w) \le \cH_\mq (w).
				\end{eqnarray}

				\item [(ii)]  For all $w \in \mathcal Y$ such that $(\mathtt{d}_w \mathtt{e}_{w;q'})^{1/2} \ge \omega^{-1}$ and $\mathtt{d}_w^{1/2} \mathtt{e}_{w;q'}^{3/2} \ge N^{A\delta-1}$, we have
				\begin{eqnarray} 

					H_0 (w) \le \cH_{\mq'} (w) .
				\end{eqnarray}
			\end{enumerate}

			\noindent Apply the Glauber dynamics restricted to  $\mathcal Y$ with {ceiling constraint $\cH_{q'}$ in the region  $\mathcal R:=\{w:(\mathtt{d}_w \mathtt{e}_{w;q'})^{1/2} \ge \omega^{-1}, \mathtt{d}_w^{1/2} \mathtt{e}_{w;q'}^{3/2} \ge N^{A\delta-1}\}$ and ceiling constraint  $\cH_q$ in $\mathcal{Y} \setminus \mathcal R$.} Then, w.o.p., it holds
			\begin{eqnarray}

                          H_t (z) \le \cH_{\mq'} (z) + N^{\delta-1}
			\end{eqnarray}
			 for each $t \in [\mq^{-1} N^{1+10B\delta} \omega,N^{5}]$  and $ z \in \mathcal Y^-$ such that $ \mathtt{d}_z \in (L^{-2} \mathfrak{d}, L^2 \mathfrak{d})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

