[Theorem thm:SaS-integral of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] Let $M_\alpha$ be a S$\alpha$S random measure with control measure $m$
and $\alpha \in (1,2]$.
\begin{enumerate}[label=(\roman*)]
\item \textbf{Existence and characteristic function.}
  $\int_E f\,dM_\alpha$ is a well-defined S$\alpha$S random variable
  if and only if $f \in L^\alpha(E,m)$, with
  \begin{equation}

  \mathbb{E}\!\left[e^{i\theta\int_E f\,dM_\alpha}\right]
  = \exp\!\left(-|\theta|^\alpha \int_E |f|^\alpha\,dm\right),
  \quad \theta \in \mathbb{R},
  \end{equation}
  and scale $\bigl\|\int_E f\,dM_\alpha\bigr\|_\alpha
  = \|f\|_{L^\alpha(E,m)}$.
\item \textbf{Linearity.}
  For $f, g \in L^\alpha(E,m)$ and $a, b \in \mathbb{R}$:
  \[
  \int_E (af+bg)\,dM_\alpha
  = a\int_E f\,dM_\alpha + b\int_E g\,dM_\alpha
  \quad \text{a.s.}
  \]
\item \textbf{Finite-dimensional distributions.}
  For $f_1,\ldots,f_m \in L^\alpha(E,m)$:
  \begin{equation}

  \mathbb{E}\!\left[\exp\!\Bigl(i\sum_{j=1}^m \theta_j
    \int_E f_j\,dM_\alpha\Bigr)\right]
  = \exp\!\left(-\int_E\Bigl|\sum_{j=1}^m \theta_j f_j\Bigr|^\alpha
    \,dm\right).
  \end{equation}
\item \textbf{$L^\alpha$ continuity.}
  If $\|f_k - f\|_{L^\alpha(E,m)} \to 0$, then
  $\int_E f_k\,dM_\alpha \to \int_E f\,dM_\alpha$ in probability.
\end{enumerate}

[Theorem eq:theta-logpotential of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[theorem]{thm:theta}
Let
\begin{equation}
 \theta_p(u)=\frac12-\frac12\log p-\frac{u^2}{2}
 +\int\log\abs{\sqrt{2p(p-1)}\lambda-pu}\,\rho_{\mathrm{sc}}(\,\mathrm d\lambda).
\end{equation}
Then
\begin{equation}
 \theta_p(u)=\frac12\log(p-1)
 -\frac{p-2}{4(p-1)}u^2-\mathcal I_p(u).
\end{equation}
For every continuous \(V\) bounded below,
\begin{equation}
 \Phi_p^{\rm bulk}(V)
 :=\sup_{u\in\mathbb R}\{\theta_p(u)-V(u)\}
\end{equation}
is the iterated determinant/delta de-regularization of the Gaussian pressure in (thm:gaussian-variational of the paper); see (thm:dereg-variational of the paper).  Moreover,
\begin{equation}
 \theta_p(u)=\inf_{V\in\mathcal V_\infty}
 \{\Phi_p^{\rm bulk}(V)+V(u)\},
\end{equation}
where \(\mathcal V_\infty=\bigcap_{m\ge2}\mathcal V_m\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 (Coefficientwise local regime) of arXiv:2609.02590, 'Directional Optimal Sub-Gamma Scales for Infinitely Divisible Laws'] If $d\geq\sqrt{3}/2$, then
\begin{equation}
 M_p(t)\leq\frac{1}{1-(d/3)t},
 \qquad 0\leq t<3/d.

\end{equation}

