body:
[Thm superlinear of arXiv:2410.24170, 'Persistent hubs in CMJ branching processes with independent increments and preferential at'] Suppose that $(\mathcal{T}_{i})_{i \in \mathbb{N}_{0}}$ is a generalised preferential attachment tree, with deterministic values $(f(j))_{j \in \mathbb{N}_{0}}$. Moreover, assume that, for some $\kappa > 0$, we have 
\begin{equation} 
\max_{i \leq n} \frac{f(i)}{i+1} \leq \kappa \frac{f(n)}{n+1}.
\end{equation}
Then, almost surely, $(\mathcal{T}_{i})_{i \in \mathbb{N}_{0}}$ contains a unique persistent hub. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:Ising-phase-transition of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] Fix $0\neq c\in [-\k,\k],$ and recall the definition of $\smref$ from (equation eqn:smref of the paper). Then the following statements hold:

\begin{enumerate} 
    \item If $\cc \in [-\k, \smref)$, then there exists a unique $\beta = \beta (c,p) \in [-\infty,0)$ such that 
    \begin{align*}
    \lim_{\delta \downarrow 0} \lim_{n \to \infty} \Prob(U_n \in \cdot  \mid \Conset_n(c_\delta)) =\delta_{ \ising_\k^\sharp(\beta,B)},
    \end{align*}
    where $B=\log \cpr{p/(1-p)},$ and $\ising_\k^\sharp(\beta, B)$ is as specified in Definition (\oldref{def:Ising-on-tree})(2) and (equation eqn:freezing-anti of the paper). Moreover, $\beta(-\k,p)=-\infty$ and the unique $\beta$ is such that the consensus of $\ising_\k^\sharp(\beta,0)$ is $\cc$.
    \item If $c \in (\smref, \k]$ and $p\neq 1/2$,  then the following is true:
    \begin{enumerate}
        \item If $p>1/2$, then there exists a unique $\beta = \beta (c,p) \in (0,\infty]$ such that
        \begin{align*}
        \lim_{\delta \downarrow 0} \lim_{n \to \infty} \Prob(U_n \in \cdot  \mid \Conset_n(c_\delta)) =\delta_{ \ising_\k^+(\beta,B)},
        \end{align*}
        where $B=\log \cpr{p/(1-p)}>0$ and $\ising_\k^+(\beta, B)$ is as specified in Definition (\oldref{def:Ising-on-tree})(1c) and (equation eqn:freezing-ferro of the paper). Moreover, $\beta(\k,p)=\infty$ and the unique $\beta$ is such that the consensus of $\ising_\k^+(\beta,B)$ is $\cc$;
        \item If $p<1/2$, then there exists a unique $\beta = \beta (c,p) \in (0,\infty]$ such that
        \begin{align*}
        \lim_{\delta \downarrow 0} \lim_{n \to \infty} \Prob(U_n \in \cdot  \mid \Conset_n(c_\delta)) =\delta_{ \ising_\k^-(\beta,B)},
        \end{align*}
        where $B=\log \cpr{p/(1-p)}<0$ and $\ising_\k^-(\beta, B)$ is as specified in Definition (\oldref{def:Ising-on-tree})(1d) and (equation eqn:freezing-ferro of the paper). Moreover, $\beta(\k,p)=\infty$ and the unique $\beta$ is such that the consensus of $\ising_\k^-(\beta,B)$ is $\cc$;
    \end{enumerate}
    \item If $c \in (\smref, \k]$  and $p=1/2$, in which case $\smref=0$,  then the following is true:
    \begin{enumerate}
        \item If, in addition, $c\in (0, \k/(\k-1)]$, then $U_n$ given $\Conset_n(c)$ converges to the unique Ising measure $\ising_\k^*(\tanh^{-1}(\cc/\k),0)$ as specified in Definition (\oldref{def:Ising-on-tree})(1a). In particular, the consensus of $\ising_\k^*(\tanh^{-1}(c/\k),0)$ is $\cc$;
        \item If $c \in (\k/(\k-1),\k]  $, then there exists a unique $\beta = \beta(c,0) \in (\betacrit(\k,0),\infty]$ such that  $U_n$ given $\Conset_n(c)$ asymptotically lies in $\{\ising_\k^+\cpr{\beta,0},\ising_\k^-\cpr{\beta,0}\}$, where $\ising_\k^+(\beta,0)$ and $\ising_\k^-(\beta,0)$ are as specified in Definition (\oldref{def:Ising-on-tree})(1c)(1d) and (equation eqn:freezing-ferro of the paper). In other words,  for any $\varepsilon > 0,$ we have
    \begin{align*}
        \lim_{\delta \downarrow 0} \limsup_{n \to \infty} \frac{1}{n} \log \Prob(U_n \notin B_\varepsilon(\pr{\ising_\k^+\cpr{\beta,0},\ising_\k^-\cpr{\beta,0}}) \mid \Conset_n(c_\delta)) < 0,
    \end{align*}
    where $B_\varepsilon(\{\ising_\k^+\cpr{\beta,0},\ising_\k^-\cpr{\beta,0}\})$ denotes an $\varepsilon$-neighborhood of $\{\ising_\k^+\cpr{\beta,0},\ising_\k^-\cpr{\beta,0}\}$ in $\P(\TkaXinf).$
    Furthermore, $\beta(\k,0)=\infty$ and the unique $\beta$ is such that the consensus of $\ising_\k^+(\beta,0)$ is $\cc$. 

    \end{enumerate}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 15 of arXiv:2609.01190, 'Rough differential equations on manifolds via natural bundles'] Let $m,n\in\Nsf$, let $[S,T]\subseteq\Rsf$ be an interval, let $p\in [1,3)$, and let $\omega$ be a control function on the interval $[S,T]$. Let $X=(X^\tau)$ be an $n$-dimensional branched rough path on $[S,T]$ with regularity $p$ and control $\omega$. Let $M$ be an $m$-dimensional manifold and let $f: M\to R_n^2M$ be a rough velocity field. We say that a function $Y: [S,T]\to M$ is an \emph{integral curve} of the rough velocity field $f$ driven by the rough path $X$ if it is continuous and if for every compact interval $I\subseteq [S,T]$ and every chart $(U,x)$ around $Y(I)$ there exists $C\in (0,\infty)$ such that the inequality
		\begin{equation}

			\left|
				Y^i(t) - Y^i(s) 
				- \sum_{\tau\in \Fcal_n^2} \frac{1}{\sigma(\tau)} f_{\tau}^i(Y(s)) X^{\tau}(s,t) 
			\right| 
			\leq C\omega(s,t)^\frac{3}{p}
		\end{equation}
holds for every $i\in \llbracket 1,m \rrbracket$ and $(s,t)\in\Delta I$. Here, $Y^i=x^i\circ Y$ ($i\in \llbracket 1,m \rrbracket$) are the components of the coordinate representation of $Y$ in chart $(U,x)$ and $f_\tau^i$ ($i\in \llbracket 1,m \rrbracket$ and $\tau\in\Fcal_n^2$) are the components of the representation of $f$ in the induced chart $(\overline{U},\overline{x})$ on $R_n^2M$.

