[Lemma 18 (Lipschitz regularity of Parisi functional) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] There is a constant $C>0$ such that, for every $t, t' \ge 0$, $p,p' \in \mcl Q_{\infty, \le \lambda_\infty}^\sS$, and $q,q' \in \mcl Q_1^\sS$, we have
\begin{gather*}
    \Ll|\sP_{t,q}(p)-\sP_{t',q'}(p')\Rr|\leq C\Ll(\Ll|t-t'\Rr|+\Ll|p-p'\Rr|_{L^1}+\Ll|q-q'\Rr|_{L^1}\Rr),
    \\
    \Ll|\partial_q\psi\Ll(q+t\nabla\xi(p)\Rr)-\partial_q\psi\Ll(q'+t'\nabla\xi(p')\Rr)\Rr|_{L^1}\leq C\Ll(\Ll|t-t'\Rr|+\Ll|p-p'\Rr|_{L^1}+\Ll|q-q'\Rr|_{L^1}\Rr).
\end{gather*}

[Prop 64 (Bulk mixing) of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] The following holds if the constant $L$ in \Cref{def:bulkcells} is large enough. Fix real numbers $q \ge \overline{q}$ and a point $z_0 \in \mathfrak{L}_{q}$ satisfying \eqref{eq:distanzabis} and  
\begin{flalign}

	0 \le q - \overline{q} < N^{5A\delta/4-1} (\mathfrak{d}_{z_0} \mathfrak{e}_{z_0;q})^{-1/2}.
\end{flalign}

\noindent Further assume that $H_0 (z) \le
        \mathcal{H}_{q} (z)+N^{\delta-1}$ for each $z \in 
        \mathfrak{Y}$. 
        Under the Glauber dynamics restricted to $\mathfrak Y$, with the ceiling constraint $\cH_q+N^{\delta-1}$ on $\mathfrak{Y}$, 
        we have w.o.p. 
        \begin{eqnarray}

H_t (z) \le \mathcal{H}_{\bar q} (z),  
        \end{eqnarray}
        for all
        \begin{equation}

          z\in \mathfrak{Y}^-,\qquad t \in[\mathtt t,N^{5}
            ],  \quad \mathtt t:= q^{-1} N^{1+6 A\delta}(\md_{z_0}\me_{z_0;q})^{-1/2}.
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 3 of arXiv:2608.12291, 'When should one stop the most exciting game?\\ {\tiny Sequential Inference for win-marting'] Under Assumption \ref{asmp:state_dynamics}, there exists a jointly measurable version of $(t,x,\omega)\mapsto X^x_t(\omega)$ such that on compacts of $\mathcal{S}$,
    \begin{equation*}
        (t,x)\mapsto X^x_t
    \end{equation*}
    is continuous almost surely.

