[Proposition prop:full-cm-extension of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] For a potential-realizable response satisfying
\begin{equation}
 \overline{H_{\mathrm{reg}}}^{H}=H,
 \qquad
 \int_{S}f\,d\rho=0\quad(f\inH_{\mathrm{reg}}),

\end{equation}
the map $f\mapstoB_f^\Lambda(\mu)$ extends uniquely from $H_{\mathrm{reg}}$ to a
continuous linear map on $H$, characterized in any orthonormal basis
$(\phi_i)_{i=1}^r$ of $E_\mu(\Lambda)$ by
\begin{equation}
 \left(\inner{B_f^\Lambda(\mu)\phi_j}{\phi_i}
              _{L^2(\mu)}\right)_{i,j=1}^r
 =-\kappa\Lambda
 \left(\inner{U_\mu\Theta_\mu(\phi_i,\phi_j)}{f}_{H}
  \right)_{i,j=1}^r,
 \qquad f\inH.

\end{equation}
For $f\notinH_{\mathrm{reg}}$, this notation refers only to the continuous extension;
no analytic perturbation path is asserted.

[Theorem 3 of arXiv:2608.27630, 'Oriented planar maps and \\ annular mating of trees'] The measure $m(\d\tau)$ in \eqref{eq: MA 01 defn intro} is given by
    \begin{equation}
        C_\gamma \ab[\vartheta_3(0,e^{-\theta\tau}) - \vartheta_3(\theta, e^{-\theta\tau})]\d\tau,
    \end{equation}
    where $C_\gamma$ normalizes $m$ to be a probability measure and $\vartheta_3$ is as defined in \eqref{eq: theta 3 definition}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 3 ({\cite[Proposition~1.6) of arXiv:2607.18104, '2607.18104'] {DOV:DirectedLandscape}}]
Let $K \subseteq \R^{4}_{\uparrow}$ be compact. Let $\mathcal{L}=(\mathcal{L}(x,s;y,t))_{(x,s;y,t) \in \R^4_{\uparrow}}$ be a full-space directed landscape, and $\Lsta$ from \eqref{eq:StationaryDL} the respective stationary directed landscape. For all $\xi,\tau,\psi>0$, consider the events 
\begin{equation*}
\begin{split}
   \mathsf{A}_{\xi,\tau}(\psi):=  \Big\{ &\Big| \Lsta(x,s;y,t)- \Lsta(x^{\prime},s^{\prime};y^{\prime},t^{\prime}) \Big| \leq \psi \text{ for all } (x,s;y,t),(x^{\prime},s^{\prime};y^{\prime},t^{\prime}) \in K \\ &\text{ such that } |x-x^{\prime}|,|y-y^{\prime}| \leq \xi \text{ and }  |s-s^{\prime}|,|t-t^{\prime}| \leq \tau \Big\} .
\end{split}
\end{equation*} 
Then there exist constants $c,C>0$, depending only on $K$, such that for all $\xi,\tau,\phi>0$ 
\begin{equation*}
 \P\left( \mathsf{A}_{\xi,\tau}\Big( \phi\big(\tau^{1/3}\log^{2/3}(\tau^{-1}+1) + \xi^{1/2}\log^{1/2}(\xi^{-1}+1)\big)\Big) \right) \geq 1
 - C \exp(-c\phi^{3/2}) . 
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

