[Lemma 40 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] There exists a constant $C_{29}>0$, which depends on the following values:

\begin{equation*}
 T, \quad \|u_0\|_{H^1(\Omega)}, \quad \|v_0\|_{H^1(\Omega)}, \quad \|w_0\|_{H^1(\Omega)},
\end{equation*}

such that the following uniform estimate holds:

\begin{equation*}
\sup_{\delta \in (1,\infty)} \left\{ \|v_{\text{{\tiny $\delta$}}}'(t)\|_{L^\infty (0,T\,;L^2(\Omega))}+
\left( \sup_{0 \le t \le T} \|v_{\text{{\tiny $\delta$}}}(t)\|_{H^1(\Omega)} \right)^2 \right\} \le C_{29}.
\end{equation*}

[Proposition 32 of arXiv:2608.18834, 'The Parabolic Anderson Model's Total Mass at Small Times: Geometry, Fluctuations, and Reno'] Let $\ka>0$. Define the function
\begin{align}

\msf r_\ka(t)=\begin{cases}
0&\rho>0,\\
-\ka^2\mf b\,t\log(1/t)+\mf e_\ka\,t&\rho=0,\\
\tfrac{\ka^2\mf b}{(1+\rho)\rho}t^{1+\rho}&\rho<0,
\end{cases}
\end{align}
where $\mf e_\ka\in\mbb R$ is as in Corollary \ref{Corollary: Limits of E minus Renormalization}.
There exists $\th_\ka>0$ such that for every $t\in(0,\th_\ka)$,
\begin{align}

\mbf E\big[\msf M_{\ka}(t)\big]
&=\mr e^{\msf r_\ka(t)}\int_D\mbf E\left[\mbf 1_{\{\tau_D(B^x)>t\}}\mr e^{\frac{\ka^2}{2}\ga_t(B)}\right]\d x,\\

\mbf{Var}\big[\msf M_{\ka}(t)\big]
&=\mr e^{2\msf r_\ka(t)}\int_{D^2}\mbf E\Bigg[\mbf 1_{\cap_{i\leq2}\{\tau_D(B^{x_i}_i)>t\}}\mr e^{\sum_{i=1}^2\frac{\ka^2}{2}\ga_t(B_i)}
\left(\mr e^{\ka^2\al_t(x)}-1\right)\Bigg]\d x.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2608.28505, 'Quagmires and large Suslin forests'] A $(\kappa, \lambda)$-forest is \emph{Suslin} if the following conditions hold:
\begin{enumerate}
\item for every $x \in [\lambda]^{< \kappa}$, $|\{f \in F : \mathrm{dom}(f) = x\}| < \kappa$,
\item for every $A \in [\lambda]^\kappa$ and $f : A \rightarrow 2$, there exists $x \in [A]^{< \kappa}$ such that $f \upharpoonright x \not\in F$,
\item the forest $F$ ordered by reverse inclusion is $\kappa$-cc.
\end{enumerate}

[Theorem thm:positive-global-results of arXiv:2608.18320, 'Asymptotics for Beta-Splitting Trees via Homogeneous Fragmentations and Meromorphic Potent'] Let $\beta>0$. Then
\begin{equation}
        U_\beta(\mathrm{d} x)
        =
        \eta_\beta\delta_0(\mathrm{d} x)
        +
        \left[
        \frac1{\mu_\beta}
        +
        \sum_{\rho\in\mathcal E_\beta}
        u_{\beta,\rho}(x)
        +
        \sum_{s\in\mathcal S_\beta}
        \frac{e^{sx}}{\phi_\beta'(s)}
        \right]\mathrm{d} x.
\end{equation}
The last series converges locally absolutely and uniformly for $x>0$.
Equivalently, as an identity of meromorphic functions,
\begin{equation}
        \frac1{\phi_\beta(z)}
        =
        \eta_\beta
        +
        \frac1{\mu_\beta z}
        +
        \sum_{\rho\in\mathcal E_\beta}
        \mathcal P_{\beta,\rho}(z)
        +
        \sum_{s\in\mathcal S_\beta}
        \frac1{\phi_\beta'(s)(z-s)},
\end{equation}
where the last series converges locally absolutely and uniformly on
$\mathbb C\setminus\mathcal Z_\beta$. Consequently, for every $n\ge2$,
\begin{equation}        \mathsf E D_n
        =
        \frac{h_{n-1}}{\mu_\beta}
        -\frac{\phi_\beta''(0)}{2\mu_\beta^2}
        -\sum_{\rho\in\mathcal E_\beta}
        \mathcal B_{\beta,\rho}(n)
        -\sum_{s\in\mathcal S_\beta}
        \frac{\Gamma(-s)\Gamma(n)}
        {\phi_\beta'(s)\Gamma(n-s)},
\end{equation}
and the last series converges absolutely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem eq:subexp-counter-strict of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[theorem]{thm:subexp-counterexample}
Fix \(p\ge3\) and \(\alpha\in(0,2)\).  There exists a symmetric probability law \(\mu=\mu_{p,\alpha}\) with a strictly positive \(C^\infty\) density such that:
\begin{enumerate}[label=(\roman*),leftmargin=2em]
\item \(\mu\) has Weibull tails of index \(\alpha\) and all moments finite; when \(\alpha\ge1\), it is subexponential in the sense of (def:subexp of the paper);
\item \(\mu\) matches the standard Gaussian moments through order \(2p\);
\item for some compact interval \(B\subset(0,\infty)\),
\begin{equation}
 \liminf_{N\to\infty}\frac1N\log\mathbb E_\mu\operatorname{Crt}_N^J(B)
 \ge0>
 \lim_{N\to\infty}\frac1N\log\mathbb E\operatorname{Crt}_N^G(B).
\end{equation}
The same strict inequalities hold for local maxima, with the Gaussian
term interpreted via a \(\limsup\); after replacing \(B\) with \(-B\),
they also hold for local minima.
\end{enumerate}
Thus \(2p\)-moment matching does not imply universality of these unregularized
energy-window counts for any subquadratic Weibull tail.  In particular,
the failure occurs within the subexponential class for every
\(\alpha\in[1,2)\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 of arXiv:2506.18558, '2506.18558'] Suppose that Assumptions {\rm\ref{A1}} and {\rm\ref{A2}} hold. For any $p\ge 4$ and  $T>0$, there exists a constant $C_{p,T}>0$ such that for any $\varepsilon>0$, $x\in\RR^{n}$ and $ y\in \RR^{m}$,
\begin{align}
\mathbb{E}\left(\sup_{t\in [0, T]}|X_{t}^{\varepsilon}|^p\right)\le  C_{p,T}(1+|x|^p+|y|^p)
\end{align} and
\begin{align}
\sup_{t\in [0,T]}\mathbb{E}|Y_{t}^{\varepsilon}|^p\le  C_{p,T}(1+|x|^p+|y|^p).
\end{align}
Moreover, for any $h>0$ with $0\le  t<t+h\le  T$,
\begin{align}
\mathbb{E}\left(\sup_{t\le  s\le  t+h}|X_{s}^{\varepsilon}\!-\!X_{t}^{\varepsilon}|^{4}\right)
\le  C_{T}\left(1+|x|^{4}+|y|^{4}\right) h^{2}.
\end{align}

