[Lem ;lh of arXiv:2604.12462, 'Stochastic analysis of Beckner's and related functional inequalities'] We have 
\begin{align}
 J(s,x)\le \frac{2\Gamma (1+1/q)}{p\Gamma (1+1/q-p/q)}
 \!\left( 
 \frac{q^{2}}{2}
 \right) ^{p/q}\!s^{p/q}
\end{align}
for all $s,x\ge 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2 of arXiv:2506.20411, 'Maximal Counts in the Stopped Occupancy Problem'] Let $t=t(L,u)\geq 0$ and  integer $r=r(L,v){\geq0}$ for large enough $L$ be given by
\begin{eqnarray}
t&:=&L +  m\log L + u,\\
r&:=&eL+ \left((e-1)m-\frac{1}{2}\right)\log L+v.
\end{eqnarray}
Then, as $L\to\infty$,
\begin{align}
 \overline{P}_r(t)&\sim \frac{1}{e-1}p_r(t),
\\
\log p_r(t)&=
\\\notag&\hskip-3em
-L + (e-1)u-v -   \log\sqrt{2\pi e} -\frac{1}{2}\log\left( 1+\frac{v}{eL}\right) - \frac{(eu-v)^2}{2(eL+v)}+O\left(\frac{\log L} {L^{1/2}} \right)
\end{align}
uniformly in $u,v$ within the range
\begin{eqnarray}
\frac{u}{L}+1&\ge&\varepsilon,\\
|eu-v|&=&O(L^{1/2})

\end{eqnarray}
 for any fixed $\varepsilon>0$.

[Prop triple hodge formulas 2 of arXiv:2609.02409, 'Membranes and Maps'] Suppose that $\epsilon_1+\epsilon_2+\epsilon_3=0$. Then the following identities hold.
    \begin{enumerate}[label=\textup{(\roman*)}]
        \item \emph{One marking:}
        \begin{equation}

            \mathsf{H}\bigl(z;\epsvec{[3]};\mathrm{i} u\bigr)
            =
            -
            \frac{1}{u^2 z}
            \prod_{i=1}^3 \frac{\gamfct{-z\epsilon_i}{u}}{\epsilon_i} \,.
        \end{equation}

        \item \emph{Two markings:}
        \begin{align}
            \mathsf{H}\bigl(z,\epsilon_1^{-1};\epsvec{[3]};\mathrm{i} u\bigr)
            &=
            -\frac{z}{u^2(\epsilon_1 z + 1)}
            \frac{
                \cS(u\epsilon_2z)\cS(u\epsilon_3z)
            }{
                \cS\bigl(u(\epsilon_1z+1)\bigr)
            }
            \prod_{i=1}^3 \frac{\gamfct{-z\epsilon_i}{u}}{\epsilon_i} \,,

            \\
            \mathsf{H}^{\mathrm{st}}\bigl(z,-z;\epsvec{[3]};\mathrm{i} u\bigr)
            &=
            -\frac{1}{\epsilon_1\epsilon_2\epsilon_3}
            \Psi\left(
                \frac{z^2}{u^2\cS(u)^2}
                \sum_{i=1}^3
                \epsilon_i\cS(2u\epsilon_i z)
            \right) \,.

        \end{align}

        \item \emph{Three markings:}
        \begin{align}
            \mathsf{H}\bigl(z,\epsvec[-1]{[2]};\epsvec{[3]};\mathrm{i} u\bigr)
            &=
            -\frac{z}{u^2\epsilon_1\epsilon_2}
            \cS(u\epsilon_3z)^2
            \prod_{i=1}^3 \frac{\gamfct{-z\epsilon_i}{u}}{\epsilon_i} \,,

            \\
            \mathsf{H}\bigl(z,-z,\epsilon_1^{-1};\epsvec{[3]};\mathrm{i} u\bigr)
            &=
            \frac{z^2}{u^2\epsilon_1^2\epsilon_2\epsilon_3}
            \frac{\cS(u\epsilon_2z)\cS(u\epsilon_3z)}
            {\cS(u\epsilon_1z)\cS(u)} \,.

        \end{align}

        \item \emph{Four markings:}
        \begin{align}
            \mathsf{H}\bigl(z,\epsvec[-1]{[3]};\epsvec{[3]};\mathrm{i} u\bigr)
            &=
            -\frac{z^2}{u\epsilon_1 \epsilon_2 \epsilon_3}
            \cS(u)
            \left(
                \kappa(u)
                +
                \sum_{i=1}^3 \kappa(u\epsilon_i z)
            \right)
            \prod_{i=1}^3
                \cS(u\epsilon_i z)
                \frac{\gamfct{-z\epsilon_i}{u}}{\epsilon_i} \,,

            \\
            \mathsf{H}\bigl(z,-z,\epsvec[-1]{[2]};\epsvec{[3]};\mathrm{i} u\bigr)
            &=
            -\frac{z^2}{u^2\epsilon_1^3\epsilon_2^3}
            \frac{\cS(u\epsilon_3z)^3}{\cS(u\epsilon_1z)\cS(u\epsilon_2z)} \,.

        \end{align}

        \item \emph{Five markings:}
        \begin{equation}

                \mathsf{H}\bigl(z,-z,\epsvec[-1]{[3]};\epsvec{[3]};\mathrm{i} u\bigr)
                =
                \frac{z^4}{\epsilon_1^2\epsilon_2^2\epsilon_3^2}
                \cS(u)
                \prod_{i=1}^3\cS(u\epsilon_i z)
                \left[
                    \left(
                        \sum_{i=1}^3
                        \kappa(u\epsilon_i z)
                    \right)^2
                    - \frac{1}{4}
                \right] \,.
        \end{equation}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm cont-XOR of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $D\subset\mathbb C$ be a bounded, simply connected domain. Let $\tau$ be the continuum XOR-Ising model with free/free boundary conditions in $D$. Then, there exists a collection $(\mu_k)_{k=1}^\infty$  of measures supported on $(C_k)_{k=1}^\infty$ such that 
    \begin{align*}
        \tau = \lim_{N\to \infty}\ \sum_{k=1}^{N} \xi_{k} \mu_{k},
    \end{align*}
    where $(\xi_k)_{k=1}^\infty$ are i.i.d. symmetric signs. The sum converges almost surely in the Sobolev space $H^{s}(\mathbb C)$ for $s<-1$, under \emph{any ordering} that is independent of the collection of signs. Moreover, 
    \begin{enumerate}[label=(\roman*)]
        \item The excursions $C_k$ are connected and pairwise disjoint almost surely.
        \item Each measure $\mu_k$ is a deterministic function of the respective excursion $C_k$.
        \item The set of excursions $(C_k)_{k=1}^\infty$ is locally finite. That is, almost surely for any $\rho>0$ there are  finitely many $C_k$ with diameter greater than $\rho$. 
        \item For any continuous, bounded function $f:\mathbb C\to\mathbb R$, 
        \begin{align}
        \mathbb E\left[\sum_{k=1}^\infty(\mu_k,f)^2\right ]<\infty,
        \end{align} 
        and thus 
        \begin{equation}
           (\tau,f) = \lim_{N\to\infty} \sum_{k=1}^N \xi_k(\mu_k,f) \quad\text{in}\quad L^2(\mathbb P).
        \end{equation}
    \end{enumerate}
    The same statement holds for\footnote{In this case, one needs to be careful to work in a domain $D$ whose boundary has small enough dimension (or, instead, restrict to the local Sobolev space $H^s_{loc}(D)$).} the XOR-Ising model with $+/+$ boundary conditions in $D$ by adding a symmetry-breaking (positive) measure $\mu_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 8 (Sharpness of the cubic order) of arXiv:2608.04799, '2608.04799'] Fix \(0<a<b<\infty\) and \(R_0\in\mathbb Z_{\ge0}\), and put
\(K_0=[a,b]\times\{0,\ldots,R_0\}\).  There are positive constants
\(A_-,A_+,B_-,B_+\), depending on \(K_0\) and \(\lambda\), such that
\begin{equation}
  A_-^q e^{-B_-q^3}
  \le \alpha_\lambda^{(q)}(K_0^q)
  \le A_+^q e^{-B_+q^3},
  \qquad q\ge1.
\end{equation}
Consequently, the power \(q^3\) in the uniform finite \(n\) estimate
\eqref{eq:main-uniform-bound} cannot be replaced by \(q^{3+\varepsilon}\),
for any \(\varepsilon>0\), while retaining a prefactor exponential in \(q\)
and constants independent of \(n,q\).

