body:
[Lemma 10 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] We have the following convergence as $m \to \infty$:

\begin{equation}
S_{\text{{\tiny $1,\!\delta,\!\nu$}}}(\tilde{z}_m,\tilde{g}_m) \longrightarrow S_{\text{{\tiny $1,\!\delta,\!\nu$}}}(\tilde{z},\tilde{g}) \quad \left\{
\begin{array}{l}
\text{in} \quad C([0,T]\,;L^2(\Omega)),\\[0.1cm]
\text{weakly in} \quad W^{1,2}(0,T\,;L^2(\Omega)),\\[0.1cm]
\text{weakly$^*$ in} \quad L^\infty (0,T\,;H^1(\Omega)),\\[0.1cm]
\text{weakly in} \quad L^2(0,T\,;H^2(\Omega)),
\end{array}
\right.
\end{equation}

whenever a sequence $\{(\tilde{z}_m,\tilde{g}_m)\}_{m \in \mathbb{N}} \subset D(S_{\text{{\tiny $1,\!\delta,\!\nu$}}})$ and a pair 
$(\tilde{z},\tilde{g}) \in D(S_{\text{{\tiny $1,\!\delta,\!\nu$}}})$ satisfy the following convergence as $m \to \infty$:

\begin{equation}

(\tilde{z}_m,\tilde{g}_m) \longrightarrow (\tilde{z},\tilde{g}) \quad \text{in} \quad C([0,T]\,;L^2(\Omega)) \times L^2(0,T\,;L^2(\Omega)),
\end{equation}

and the following boundedness:

\begin{equation}
\sup_{m\,\in\,\mathbb{N}} \int_0^T \|z_m'(t)\|_{L^2(\Omega)} dt < \infty.
\end{equation}

