[Thm 11 of arXiv:2506.18834, '\large\bf On the random-time and finite-time ruin probability for widely dependent claim s'] In a nonstandard renewal risk model,
let $Z_i,\ i\ge1$ be WLOD random variables with dominating coefficients $g_{L,H}(n),\ n\ge1$.
If
\begin{eqnarray}
g_{L,H}(n)=o(e^{an})\ \ \ \ \ \ \ \text{for some }\ \ a>0,\ \ \ \text{as}\ \ \ n\to\infty,
\end{eqnarray}
then for each $\delta>0$, there exists $r=r(H)>0$ such that
\begin{eqnarray}
Ee^{rN(t)}\textbf{\emph{1}}_{\{N(t)>(1+\delta)\mu_H^{-1}t\}}\to0,\ \ \ \ \ \ \ \text{as}\ \ \ t\to\infty.
\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, there exists a constant $c_1>0$ such that, uniformly for $z\in\mb D(\tau,\eta_0)$, the following estimates hold.
        \begin{enumerate}[label=(\roman*)]
                \item The off-diagonal blocks satisfy
                      \begin{align}
                              \avg{\Pi_{21}\Sg\Pi_{21}^*}_N=\avg{\Pi_{12}^*\Sg\Pi_{12}}_N\leq1-c_1. 
                      \end{align}
                \item The diagonal blocks satisfy
                      \begin{align}
                              \|\Sg^{1/2}\Pi_{11}\Sg^{1/2}\|_{\rr{hs}}+\|\Pi_{22}\|_{\rr{hs}}\sim1. 
                      \end{align}
                \item The two imaginary parts are comparable:
                      \begin{align}
                              \frac{\Im m}{\eta+\Im g}\sim1,\qquad \Im m\sim\Im g. 
                      \end{align}
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:eude of arXiv:2604.17253, 'Large Deviations for the Nonlinear Schrödinger Equation with Randomized Quasi-Periodic Ini'] Consider the randomized quasi-periodic Cauchy problem (equation eq:nls of the paper)--(equation eq:initialdata of the paper) together with (cor:polynomial_decay of the paper). 
Then there exists a positive time
\[
{
{T_\varepsilon = \mathcal O\left(\varepsilon^{-\alpha+1+\eta}\right)},
}
\]
where $\eta$ is chosen in accordance with (equation eq:delta of the paper), and a randomized spatially quasi-periodic solution of the form
\begin{align}
{u}(t,\boldsymbol{x})
= \sum_{\boldsymbol{n}\in\mathbb{Z}^\nu}
{c}(t,\boldsymbol{n})
e^{\mathrm{i}\langle \boldsymbol{n}\boldsymbol{\Omega}, \boldsymbol{x}\rangle}
\end{align}
defined on $[0,T_\varepsilon]$, with Fourier coefficients satisfying the uniform-in-time decay estimates
\begin{align}
\sup_{t\in[0,T_\varepsilon]}
|{c}(t,\boldsymbol{n})|
\lesssim {\varepsilon^{-\frac{1}{2}-\frac{\eta}{2}}}\tnorm{\boldsymbol{n}}_{-\frac{\rho-\kappa}{2}}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:sep2 of arXiv:2606.02472, 'Correlated uniform attachment trees'] If $\bclr{T_n^{1}, T_n^{2} }_{n\in \N}$ is distributed according to the measure $\alpha{\text -}\mathrm{CUA}$, then for all $\varepsilon>0$ there exist $m,K,\ell \in \N$ such that for all $n \geq m$
    \ba{
        \mathbb{P} \left(\frac{1}{\ell + 1} \sum_{j=0}^{\ell} \frac{1}{2^j K \log(n)} \left( \sum_{x \in A_{2^j K}^{1}(n)} \deg_{T_n^{1}}(x) -  \sum_{x \in A_{2^j K}^{2}(n)} \deg_{T_n^{2}}(x) \right)^2  < 2-0.05 \alpha \right) > 1-\varepsilon .
    } (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2 (Janssen test) of arXiv:2609.01296, 'Asymptotic safety regions for Gabor frames generated by Hermite functions'] Let $g\in L^2(\mathbb R)$, $\|g\|_2=1,$ and let $\Lambda \subset \R^2$ be a lattice.
    The Gabor system $\G(g,\Lambda)$ is a frame for $L^2(\R)$ if
    \begin{equation}
        \sum_{\lambda^\circ \in \Lambda^\circ} |V_g g(\lambda^\circ)| < 2,
    \end{equation}
    where the notation $\Lambda^\circ$ stands for the adjoint lattice. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 11 of arXiv:2609.01296, 'Asymptotic safety regions for Gabor frames generated by Hermite functions'] For every $\varepsilon>0$ and $0<\rho<\frac{1}{2}$, there exists $n_{\varepsilon, \rho} \in \N$ such that, whenever $n\geq n_{\varepsilon, \rho}$ and a pair of parameters $a,b>0$ satisfies
    \begin{equation}
        \min\{a,b\} \leq n^{-\frac{1}{2}- \varepsilon}, \quad ab \leq \frac{1}{2}-\rho,
    \end{equation}
     the Gabor system $\mathcal{G}_n(a,b)$ forms a frame for $L^2(\R)$.

