body:
[Lemma lema_orig_teska of arXiv:2607.13302, 'Extending an Order-Statistic Characterization of the Exponential Distribution'] For $1 \leq j < k \leq n$ and any $r \geq 1$ it holds that
    \begin{align}
        &\frac{1}{(k-1)!}\sum_{i=0}^{r+1} (i+k-1)! \binom{n-k}{i} \genfrac{\{}{\}}{0pt}{}{k+r+1}{i+k} \nonumber \\
        & \qquad = \frac{1}{(k-j-1)!} \sum_{i=0}^{r+1} (k-j-1+i)! \binom{n-k+j}{i} \sum_{l=k-2}^{k+r-1} \genfrac{\{}{\}}{0pt}{}{l-j+2}{k-j+i} \nonumber \\
        & \qquad \qquad \qquad \qquad \qquad \times \sum_{s=0}^{k+r-l-1} \binom{n-k}{s} \frac{(s+j-1)!}{(j-1)!} \genfrac{\{}{\}}{0pt}{}{j+k+r-l-1}{s+j}
    \end{align}

[Definition 5 of arXiv:2506.09462, 'Transition Path Theory For L\'{e}vy-Type Processes: SDE Representation and Statistics'] The \textbf{$AB$-transition entrance distribution} in \(\bar{B} \cap (B + 1)\) is defined as:  
\begin{equation*}
    \eta^+_B(\d x) = \frac{1}{v_B^+}\rho(x)\overleftarrow{\mathcal{L}}\overleftarrow{q}(x)\d x, \quad x \in \bar{B} \cap (B + 1),
\end{equation*}
and analogously, the \textbf{$BA$-transition entrance distribution} on \(\bar{A} \cap (A + 1)\):  
\begin{equation}
    \eta^+_A(\d x) = \frac{1}{v_A^+}\rho(x)\overleftarrow{\mathcal{L}}\overleftarrow{q}(x)\d x,
\end{equation}
where \(v_A^+\) and \(v_B^+\) are normalizing constants such that these define probability measures.

[Corollary 45 (One-species formula for balanced models) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Assume that $\xi$ is balanced with respect to $\lambda$. Then, for every $t\geq0$,
\begin{equation}

    \lim_{N\to\infty}\bar F_N(t,0)=\sup_{a\in\mcl Q_\infty}\inf_{r\in\mcl Q_\infty}\left\{\psi_\circ(r)-\la r,a\ra_{L^2}+t\int_0^1\xi_\star(a(v))\,\d v\right\}.
\end{equation}
In particular, for the explicit balanced models in Lemma~\ref{l.power_series_balanced_models}, the effective one-species covariance function is
\begin{equation}

    \xi_\star(x)=\sum_{p\geq1}\beta_p^2x^p,\qquad \beta_p^2=\sum_{s_1,\ldots,s_p\in\sS}\Delta^2_{s_1,\ldots,s_p}\lambda_{s_1}\cdots\lambda_{s_p}.
\end{equation}

[Theorem 6 (Utility representation) of arXiv:2607.29560, 'Tractable Relaxations of Multivariate Stochastic Dominance via Optimal Transport and CVaR'] For every $\gamma\in[0,1]$,
\begin{equation}

\mathfrak D_{s,\lambda,\gamma}(P,Q)
=
\sup_{u\in\mathcal U_{s,\lambda,\gamma}}
\left\{
\int_Du\,dP-
\int_Du\,dQ
\right\}.
\end{equation}
Consequently,
$P\preceq_{s,\lambda,\gamma}^{\rm CSD}Q$ if and only if
$P\preceq_{s,\lambda,\gamma}^{\mathcal U}Q$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:lbm-square-transversality of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] For every $a=(a_1,\ldots,a_N)\in\mathbb R^N$,
\begin{equation}
 \sum_{i=1}^Na_i\phi_i^2M_x=0
 \quad\Longrightarrow\quad
 a_1=\cdots=a_N=0,

\end{equation}
and
\begin{equation}
 \sum_{i=1}^Na_i\Lambda_i\phi_i^2M_x=0
 \quad\Longrightarrow\quad
 a_1=\cdots=a_N=0.

\end{equation}

[Proposition 18 of arXiv:2511.12623, 'The eigenvector bead process'] We have almost surely
\[
\lim_{N \to \infty}
\left(
1 
+ \sum_{j \in \mathbb{Z}} \frac{\gamma_j^{N}}{\mu_j^{N} - z}
- \frac{\Gamma_N}{z}
\right)
=
 \sum_{j \in \mathbb{Z}} \frac{\gamma_j}{\mu_j - z}
+ \frac{E+q-1}{2E},
\]
for all $z \in \mathbb{R} \setminus \{\mu_j\}_{j \in \mathbb{Z}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2 of arXiv:2608.05842, 'Asymptotic Expansion of the Kallianpur–Striebel Formula under Perturbations of Linear Mode'] Let $\{\xi_t\}_{t\geq 0}$ be a $\mathbb{R}^{d_2}$-dimensional progressively measurable process independent of $W$, and assume
  \begin{align*}
    \int_0^tE\left[ |\xi_s|^2 \right]ds<\infty.
  \end{align*} 
  for every $t\geq 0$. Then, 
  \begin{align*}
    M_t=&\exp\left( \int_0^t \xi_s^\top (\sigma(s)\sigma(s)^\top)^{-1} \sigma(s) \, dW_s \right. \\
    &\quad \left. - \frac{1}{2} \int_0^t \xi_s^\top (\sigma(s)\sigma(s)^\top)^{-1} \xi_s \, ds \right).
  \end{align*}
  is a martingale.

  Furthermore, if we define a probability measure $Q$ on $\mathcal{F}_T$ by 
  \begin{align*}
    Q(A)=E[1_AM_T]~~(A\in \mathcal{F}_T)
  \end{align*}
  for a fixed $T$, then for any multi-dimensional random variable $U$ which is independent of $W$, the law of $(U,\{Y_t^\epsilon\}_{0\le t\le T})$ under $Q$ coincides with the law of $(U,\{\tilde Y_t^\epsilon\}_{0\le t\le T})$ under $P$, where
  \begin{align*}
    d\tilde{Y}_t^\epsilon=\{H_t^\epsilon+\xi_t\}dt+\sigma(t)dW_t,~~\tilde{Y}_0^\epsilon=0.
  \end{align*}

[Lemma lemme approx kappa to 4 of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] {BECriLQG}}]
	Jointly for all $n\ge 1$,
	\begin{equation*}
	\left( (D^{\kappa,n}_t)_{t\ge 0}, \tau^{\kappa,n}, (e^{\kappa,n}_k)_{1 \le k \le \Lambda^{\kappa,n}}\right) \mathop{\longrightarrow}\limits_{\kappa \downarrow 4}^{(\mathrm{d})}
	\left( (D^n_t)_{t\ge 0}, \tau^n, (e^{n}_k)_{1 \le k \le \Lambda^n}\right),
	\end{equation*}
	where the first coordinate converges in the space $\SD$, the second one converges in $\BR$ and where the excursions converge for the topology of uniform convergence on compact subsets. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Pro 16 of arXiv:2605.30779, '2605.30779'] There exists a coupling under which
\(\widetilde{\mathcal G}_{N,r}\) and \(\mathcal G_{r-1}\) are defined
on the same probability space and
\begin{equation*} 
\widetilde{\mathcal G}_{N,r}
\xrightarrow{\mathrm{mer}}
\mathcal G_{r-1}
\qquad\text{almost surely}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 34 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] [Level lines of the macroscopic shape]


		For any $a, b, c >0$, $\mq \in \mathbb{R}$ and $0<h<b$, define $\mathcal{U}_{\mq; a, b, c}^h : [0,a+c]\mapsto [0,b+c] $ by setting
		\begin{equation} 
                  \mathcal{U}_{\mq; a, b, c}^h (x) = y\in [0,b+c]: \mathcal{H}_{\mq; a, b, c}(x,y)=h.
		\end{equation}
 If instead $h=0$ or $h=b$, then given $x$ there may exist multiple $y$ satisfying $ \mathcal{H}_{\mq; a, b, c}(x,y)=h$. In that case,  we define
 \begin{flalign}

   \begin{aligned}
                  \mathcal{U}_{\mq; a, b, c}^0 (x) & = \sup\{y\in [0,b+c]: \mathcal{H}_{\mq; a, b, c}(x,y)=0 \}; \\
                  \mathcal{U}_{\mq; a, b, c}^b (x) & = \inf\{y\in [0,b+c]: \mathcal{H}_{\mq; a, b, c}(x,y)=b\}.
                  \end{aligned}
                \end{flalign}
Also, define
                 $\mathfrak{l}_{\mq; a, b, c} : [0,y^W_{q;a,b,c}] \rightarrow [0,x^{SW}_{q;a,b,c}]$  by letting
                  $\mathfrak{l}_{\mq; a, b, c} (y)$ be the $x$ coordinate of the unique point of $\mathfrak A^{SW}_{q;a,b,c}$ with vertical coordinate $y$ (namely, so that $(\mathfrak{l}_{q;a,b,c}, y) \in \mathfrak{A}^{SW}_{q;a,b,c}$). 
                  Note that  $ \mathfrak{l}_{\mq; a, b, c} (0)=x^{SW}_{q;a,b,c}$ and $\mathfrak{l}_{\mq;a,b,c}(y^W_{q;a,b,c})=0$.
                See Figure \ref{fig:U}. As usual, if either $q=0$ or $a=b=c=1$, we drop these indices from the notation.

[Lemma lem:poisson-collisions-proof of arXiv:2608.18320, 'Asymptotics for Beta-Splitting Trees via Homogeneous Fragmentations and Meromorphic Potent'] There is a universal constant $C<\infty$ such that, conditionally on
    $\mathbf P(t)$,
    \begin{equation}
            d_{\rm TV}\left(\mathcal L(C_n(t)\mid\mathbf P(t)),\operatorname{Poisson}(\mu_n(t))\right)
            \le Cn^3\left[S_2(t)^2+S_3(t)\right].
    \end{equation}

[Corollary cor:two-atom-contrast of arXiv:2608.20295, 'Physical-Support Confidence Sets for Highly Coherent Dictionaries'] Let $r=2$ and write
\[
    x_1=\bar\beta+\frac d2,
    \qquad
    x_2=\bar\beta-\frac d2 .
\]
Fix $d_0\ne0$ and a sign-preserving compact coefficient set satisfying
$|d-d_0|\le\epsilon_d\le|d_0|/2$. For the orientation orbit that rotates
$v_1-v_2$ while fixing $v_1+v_2$,
\begin{equation}
\begin{aligned}
&\inf_{\bar\beta',d'\in\mathbb R}
\left\|
    \mu_{\phi,\bar\beta,d}
    -
    \mu_{\phi',\bar\beta',d'}
\right\|_2
\\
&\quad=
\frac{
    \lambda_\star s|d|
    \|v_1-v_2\|_2
}{2}
|\sin(\phi-\phi')|.
\end{aligned}

\end{equation}
Hence
\[
    \chi_s
    \asymp
    \frac{
        \lambda_\star
        \|v_1-v_2\|_2
        |d_0|
    }{2},
\]
and calibration and deployment information become comparable at
\begin{equation}
    |d_0|
    \asymp
    \sigma\sqrt{\frac NT}\,s^2.

\end{equation}
When $d=0$, the deployment distribution is exactly invariant along this
orientation path, so additional deployment replicates provide no orientation
information and the resolution remains calibration-limited. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:abstract-derivative-collapse of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] For every $f\inH_{\mathrm{reg}}$ and $1\le i,j\le r$,
\begin{equation}
 \dot{a}_{0,f}(\phi_i,\phi_j)
 =-\kappa\Lambda\int_{S}f\phi_i\phi_j\,d\mu.

\end{equation}

[Proposition 51 of arXiv:2608.27307, '2608.27307'] Under Assumptions~\ref{ass:basic} and~\ref{ass:rand_ent}, suppose that $E_+$ is a regular right edge in the sense of Definition~\ref{def:reg_r_edge}. Then there exists $c>0$ such that, for every fixed $x\in\R$,
\begin{align}
        \bb P\left(\gamma_+N^{2/3}\bigl(\la_1(W_t)-E_+\bigr)\leq x-N^{-c}\right)-N^{-c}&\leq \bb P\left(\gamma_+N^{2/3}\bigl(\la_1(W)-E_+\bigr)\leq x\right) \nonumber\\
        &\leq \bb P\left(\gamma_+N^{2/3}\bigl(\la_1(W_t)-E_+\bigr)\leq x+N^{-c}\right)+N^{-c}.

\end{align}

