[Lem 85 (Controlling the difference between the discrete and continuum time-derivatives) of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Fix $\alpha<0, \tau>1$. The derivative operator $\partial_s : C^{\alpha,\tau}_\mathfrak s(\Psi_T) \to C_\mathfrak s^{\alpha-2,\tau}(\Psi_T)$ which was defined in Remark \ref{d/dx}, is a bounded linear map. Furthermore, let $D_N$ be as in Definition \ref{dnlnkn}. Then we have the operator norm bounds 
 \begin{align*}\sup_{N\ge 1}\|D_N\|_{C^{\alpha,\tau}_\mathfrak s(\Psi_T)\to C_\mathfrak s^{\alpha-2,\tau}(\Psi_T)}&<\infty. \\ \|D_N-\partial_s\|_{C^{\alpha,\tau}_\mathfrak s(\Psi_T) \to C^{\alpha-4,\tau}_\mathfrak s(\Psi_T)} &\leq \frac12 N^{-1}.
 \end{align*}

[Cor 122 (regularity for limiting coefficients) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Consider the limiting coefficients from
Definition~\ref{d:cts.coeffs}. Recall also that $\rho_{\vY}$ denotes the occupation measure of the limiting process $\vY(t)$, and let $\rho_s$ be the measure conditional on time $s$.  The bounds from  Corollary~\ref{c:t.smooth.regularity.N} and 
Lemma~\ref{l:sp.smooth.cty} pass to these limiting objects:
\begin{enumerate}[(a)]
\item Similarly to  Corollary~\ref{c:t.smooth.regularity.N}\ref{c:t.smooth.regularity.N.a}, 
we have
	\begin{align*}
	&\Big(
	\|\tB\|_\infty
    +
    \|\partial_y\tB\|_\infty
 + \tep \|\partial_t \tB\|_\infty\Big)^2\\
	&\qquad+ \max\bigg\{
    \|\bar{A}\|_\infty
    +\|\partial_y\bar{A}\|_\infty
    + \tep\|\partial_t\bar{A}\|_\infty
    : \bar{A}\in\{ \tV,\tU,\trrr,
	\twww\}
    \bigg\} 
	\le 
	\bigg(\frac{\trK L}{\sep}\bigg)^{O(1)} \,.
	\end{align*}
The analogous bound holds for $(\iB,\iV,\iU,\ir,\iw)$.
\item  Similarly to  Corollary~\ref{c:t.smooth.regularity.N}\ref{c:t.smooth.regularity.N.b}, 
we have 
	\[\max\bigg\{
	\bigg\|\frac{\partial}{\partial y}
    \Big[\bar{A}^{1/2}\Big]\bigg\|_\infty
    +\tep\bigg\|\frac{\partial}{\partial t}
    \Big[\bar{A}^{1/2}\Big]\bigg\|_\infty
	:\bar{A}\in\{\tF,\twww\}\bigg\}
	\le 
	\bigg(\frac{\trK L}
		{\sep}
		\bigg)^{O(1)}\,.
		\]
The analogous bound holds for $\iF$ and $\iw$.
\item  Similarly to Lemma~\ref{l:sp.smooth.cty},
for all $0\le s\le t\le1$ we have
	\begin{align*}
	\Big\|\overline{
	\sphi*\varrho_s}-
		\overline{
		\sphi*\varrho_t}\Big\|_\infty
	&\le
	\bigg(\frac{L}{\sep}\bigg)^{O(1)}
	(t-s)^{1/2}\,\\
	\Big\|\sphi*\varsigma_s-\sphi*\varsigma_t\Big\|_\infty
	&\le
	\bigg(\frac{L}{\sep}\bigg)^{O(1)}
	(t-s)^{1/2}\,.
	\end{align*}
\end{enumerate}

\begin{proof}
Corollary~\ref{c:t.smooth.regularity.N}, 
together with the 
convergence result of Lemma~\ref{l:limit.coefs}, implies claims \eqref{c:reg.in.limit.a} and \eqref{c:reg.in.limit.b}. Claim \eqref{c:reg.in.limit.c} follows using Fatou's lemma.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:results:LSI of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Suppose $(U, W)$ satisfy Assumption (as:results:LSI of the paper). Then the following properties are satisfied:
\begin{enumerate}
    \item The family of Gibbs measures $\{\theta^n\}_{n \geq 1}$ satisfies a uniform log-Sobolev inequality. That is, there exists $C_\theta \in (0, \infty)$ such that for all $n \in \ensuremath{\mathbb{N}}$, we have
    \begin{equation}

        \mathcal{H}(\Lambda | \theta^{n}) \leq 2 C_\theta \mathcal{I}(\Lambda | \theta^{n}), \quad \Lambda \in \mathcal{P}\big((\ensuremath{\mathbb{R}}^d)^{V_n}\big).
    \end{equation}
    \item  There exists $C_0  \in (0, \infty)$ such that for all $\nu \in \tilde{\mathcal{M}}_{2, d}$ satisfying \begin{equation}
    \int_{(\ensuremath{\mathbb{R}}^d)^{3}} \Big(|b(\mathbf{x})|^2 + \big|\nabla_{\mathbf{x}} \log \nu(\mathbf{x})\big|^2\Big) \nu(d\mathbf{x}) < \infty,

\end{equation}we have the following modified log-Sobolev inequality: \begin{equation}
        \mathbb{H}_2(\nu) - \mathbb H_2^* \leq C_0 \mathbb{I}_2(\nu),

    \end{equation}
   where $\mathbb H_\star$ is as defined in (equation eq:results:Hstar of the paper).
    \item If $\lambda \in \tilde{\mathcal{M}}_{2, d}$ and $(\mu, \gamma)$ is a linear growth solution to the $2$-MLFE on $[0, \infty)$, with initial condition $\lambda$, then there exists $c, C \in (0, \infty)$ such that the following inequality holds: 
        \begin{equation}

        \mathbb{H}_2(\mu_t) - \mathbb H_2^* \leq C \exp(-ct), \quad \text{for a.e. } t \geq 0.
    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

