[Lemma lem:corrector_construction of arXiv:2411.06861, 'Quenched invariance principle for random walks in random environments admitting a cycle de'] Suppose Assumption~(ass:P of the paper) and (ass:finite_H_-1_norm of the paper) hold. Then, for each $i = 1, \dots, d$,

  \begin{enumerate}[(i)]
  \item
    there exists a random field $\chi^{i}\colon \Omega \times \mathbb{Z}^{d} \to \mathbb{R}$ that satisfies the cocycle property such that its restriction $\chi^{i}\big|_{\Omega \times \mathcal{N}} \in L^{2}_{\mathrm{pot}}$, and, for $\mathbb{P}$-a.e.\ $\omega$ and every $x \in \mathbb{Z}^{d}$,

    \begin{align}

      L^{\omega} \chi^{i}(\omega, x) \;=\; V^{i}(\omega, x). 
    \end{align}

  \item
    $\Phi^{i} \ensuremath{\mathrel{\mathop:}=} \Pi^{i} - \chi^{i}$ satisfies $\Phi^{i}\big|_{\Omega \times \mathcal{N}} \in L^{2}_{\mathrm{cov}}$, and, for $\mathbb{P}$-a.e.\ $\omega$ and every $x \in \mathbb{Z}^d$,
    \begin{align}

      L^{\omega}\Phi^{i}(\omega, x) \;=\; 0.
    \end{align}
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:rectangle of arXiv:2607.14087, 'Stochastic Domination of Gaussian Maxima: A Resolution of the Weak Simplex Conjecture'] \label[lemma]{lem:rectangles}
Let $V=(V_1,\ldots,V_m)$ be a centered Gaussian vector with
$\operatorname{Var}(V_i)=1$ for every $i$.  For
$r_1,\ldots,r_m\in[0,\infty]$,
\begin{equation}
  \mathbb P\{|V_i|\leq r_i\text{ for all }i\}
  \geq\prod_{i=1}^m\mathbb P\{|Z|\leq r_i\},
  \qquad Z\sim\mathcal N(0,1).
\end{equation}
If $0<r_i<\infty$ for every $i$, then equality in
(equation eq:rectangle of the paper) holds if and only if
$\operatorname{Cov}(V)=I_m$.

[Lem annulus-coupling-estimate-linear of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] Fix $r/100 \le m \le  (R-r)/2$. There exist $C(d), \beta_0(d)<\infty$ such that the following holds for all $\beta>\beta_0$:
    \begin{align*}
        \|\pi_{A_{r,R}}^\pm ( \cdot \mathord{\upharpoonright}_{\Lambda_{r+m}}) - \pi_{A_{r,r+2m}}^\pm (\cdot \mathord{\upharpoonright}_{\Lambda_{r+m}})\|_{{\textsc{tv}}}  \le Ce^{ - \beta m}\,.
    \end{align*}

[Lemma 19 (Dynamic master inequalities for cumulants) of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $W$ be an $N\times N$ Wigner matrix satisfying Assumption~\ref{ass:momass}. For any fixed $p, n,S\in \N$ with $p\ge 3$ it holds that
\begin{equation}
\begin{split}
\Xi_t^{(p)}(n,S) \lesssim &\Xi_0^{(p)}(n,S) + \int_0^t \left(\Xi^{(p)}_s(n,S-1) +\frac{1}{N}\Xi^{(p)}_s(n+1,S+2)\right) \dif s\\
+&\int_0^s\left(\sum_{S'\le S} \frac{1}{N\eta^{S-S'+2}}\Xi^{(p)}_s(n-1,S') + \sum_{S'\le S-2} \frac{1}{\eta^{S-S'+1}}\Xi^{(p)}_s(n-2,S')\right)\dif s\\
+&\int_0^s\left(\sum_{S'\le S} \frac{1}{N\eta^{S-S'+2}}\Xi^{(p-1)}_s(n-1,S') + \sum_{S'\le S-2} \frac{1}{\eta^{S-S'+1}}\Xi^{(p-1)}_s(n-2,S')\right)\dif s,\\
\Theta_t^{(p)}(n,S) \lesssim &\Theta_0^{(p)}(n,S) + \int_0^t \left(\Theta^{(p)}_s(n,S-1) +\frac{1}{N}\Theta^{(p)}_s(n+1,S+2)\right) \dif s\\
+&\int_0^t \left(\frac{1}{N}\Theta_s^{(p-1)}(n-1,S) +\Theta_s^{(p-1)}(n-2,S-2)\right)\dif s,
\end{split}

\end{equation}
for any fixed $\xi>0$, uniformly in $t\in [0,T]$ and $z=z_T\in\mathcal{D}$.

[Proposition 3 of arXiv:2608.24675, 'Towards Liouville Quantum Gravity on fractals'] ~\cite[Proposition 2.8]{BC23}
There exists constants $C_0,c_0>0$ such that
    \begin{equation}
      c_0\log\frac{1}{d(x,y)} \leq k_{d_S}(x,y)\leq  C_0\Big(1+\log\frac{1}{d(x,y)}\Big).
    \end{equation}

