[Definition of arXiv:2503.21737, 'High-intensity Voronoi percolation on manifolds'] Let \(r, \rho > 0\).
    We say that a locally finite point set \(\xi\subset\mathbb R^d\) is \emph{\((r,\rho)\)-robust}, when the following holds for all \(x,y \in \xi \cap B_{\mathbb R^d}(0,r)\):
    \begin{enumerate}
        \item If the (Euclidean) Voronoi cells of \(x\) and \(y\) intersect in \(B_{\mathbb R^d}(0,2r)\), then there exists a \(w_{xy} \in B_{\mathbb R^d}(0,2r)\) such that
        \begin{equation*}
            \mathrm{d}_{\mathbb{R}^d}(w_{xy},x) = \mathrm{d}_{\mathbb{R}^d}(w_{xy}, y) < \mathrm{d}_{\mathbb{R}^d}(w_{xy}, \xi\setminus\{x,y\}) - \rho \cdot r.
        \end{equation*}
        \item If the (Euclidean) Voronoi cells of \(x\) and \(y\) do not intersect then
        \begin{equation*}
            \max\{ \mathrm{d}_{\mathbb{R}^d}(w,x), \mathrm{d}_{\mathbb{R}^d}(w,y) \} > \mathrm{d}_{\mathbb{R}^d}(w, \xi) + \rho \cdot r
        \end{equation*}
        holds for all \(w \in B_{\mathbb R^d}(0,2r)\).
    \end{enumerate}

[Lemma 19 of arXiv:2606.31596, 'The Invariant Measure of Multiscale Markov Chains via Fast Arborescence Factorization'] Let $\hat \tau\in \hat{\mathcal T}^F$. Let $M\in \mathcal M$ be a minimal class. The following properties are satisfied:
\begin{itemize}	
\item[i)] $\hat\tau$ contains no edges going out from $M$, if $\hat \tau$ is rooted inside $M$;
\item[ii)] $\hat\tau$ contains only one edge (necessarily slow) going out from $M$, if $\hat \tau$ is not rooted inside $M$;
\item[iii)] $\hat \tau$ contains no slow edges connecting two vertices of $M$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma sym-path-to-fwick of arXiv:2411.06131, 'Non-Markovian dynamics: the memory-dependent probability density evolution equations'] {ducan2000stochastic}}]
	If $ F\in \mathscr{L}^2_{\phi}(0, T)$, then the symmetric pathwise integral $\int_{0}^{t} F_s  \circ \mathrm{d} B^H_s$ and the FWIS integral $\int_{0}^{t} F_s \diamond\mathrm{d}B^H_s$ exist, and the following equality is satisfied:
	\begin{equation}
	\int_{0}^{t} F_s  \circ \mathrm{d} B^H_s= \int_{0}^{t} F_s \diamond\mathrm{d}B^H_s+\int_{0}^{t}D^{\phi}_sF_s\mathrm{d}s, \,  \forall t\in[0,T], \,a.s.,
	\end{equation}
	where $ D^{\phi}_t F_t $ is the Mallivian derivative of $F_t$ {\rm [ducan2000stochastic]}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb$, $f\in \Sob^k(\Rbb^n,\gamma_n)$ with $\left\|f\right\|_{\Leb^\infty}\leq 1$, and $p\in [1,2]$,
\begin{equation}
    \left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p} \geq C^{\text{\rm\ref{thm:high-order-Poincare-type-Gaussian}}}(p)^k\Wop^{\geq k}(f),
\end{equation}
with $C^{\text{\rm\ref{thm:high-order-Poincare-type-Gaussian}}}(p) = C^{\text{\rm\ref{thm:high-order-Poincare-type-Boolean}}}(p) \gtrsim 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 of arXiv:2608.04644, 'Khinchin's and Chung's Laws of the Iterated Logarithm at Time Zero for the Linear Stochast'] Recall that $H$ is defined in \eqref{def:H}. Suppose that  Condition \ref{hypo}  holds  and that $H<1$.  Then, for every fixed $x\in\mathbb{R}^d$, the following assertions hold.
\begin{itemize}
	\item[(1)] For every $t\ge0$,
	\begin{equation}
		\|u(t,x)\|_{L^2(\Omega)}^2
		=
		\textcolor{black}{\widetilde{\kappa}}^2 t^{2H},
	\end{equation}
	where $\textcolor{black}{\widetilde{\kappa}}$ is given by \eqref{def:tilde:kappa}.

	\item[(2)] The process $\{u(t,x)\}_{t\ge0}$ is a centered Gaussian self-similar process with Hurst index $H$.
\end{itemize}

