[Lemma lem_flow_1 of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] Suppose that $H_{t_0}$ and $ \Lambda_{t_0}$ satisfy the assumptions (for $H$ and $\Lambda$) in (mix of the paper). Consider the characteristic flow in  (flow of the paper) with $z_{t_0}=E_{t_0}+\mathrm{i} \eta_{t_0} \in \bf D\left({\tau}\right)$, where \smash{$\eta_{t_0}\gtrsim N^{-1/3+\tau_e}$} for a constant $\tau_e>0$ and $t_c-t_0 \sim N^{-\varepsilon_g}$ for a constant $\varepsilon_g\in \pa{0,({1/8})\wedge ({\delta_A/4})}$. Define 
\[t_m:=\inf\ha{t\ge t_0: N\eta_t\im m\left({z_t}\right)\le N^{C_0\varepsilon_g}}\] 
for an absolute constant $C_0>6$. Then, for any $(z_1)_t, (z_2)_t\in \{z_t, \overline z_t\}$ and all $t\in [t_0,t_m]$, we have that
    \begin{equation}
        \begin{aligned}
            \left\|L_{(1,2), t}-K_{(1,2), t}\right\|_2 \prec \frac{\left(t_c-t_0\right)^2}{\left(t_c-t\right)^2}\left\|L_{(1,2), t_0}-K_{(1,2), t_0}\right\|_2+\frac{1}{N\left(t_c-t\right)^2\left(\operatorname{Im} m_t\right)^2}.
        \end{aligned}
    \end{equation}
Combining this with (equation t_eta of the paper), (equation im_m_t_sim_through_evolution of the paper), and (equation largG_Ent of the paper), and applying the estimates (equation 1-M of the paper) and (equation 1-M-2 of the paper) below to bound \smash{$\|\p{1-\widehat M_{\left({1,2}\right)}}^{-1}\|$}, we obtain that for all $t\in\left[{t_0,t_m}\right]$,
    \begin{equation}
        \begin{aligned}
            \left\|L_{(1,2), t}-K_{(1,2), t}\right\|_2 \prec \frac{N^{\varepsilon_g}}{N\left(t_c-t\right)^2\left(\operatorname{Im} m_t\right)^2}\ .
        \end{aligned}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2609.02175, '2609.02175'] Let $V_1,V_2\in C_c^\infty(\mathbb R^n)$, $n\geq3$, and let
	$\lambda>0$ satisfy
	\begin{equation}
		\lambda>\sup_{\mathbb R^n}V_j,
		\qquad j=1,2.
	\end{equation}
Assume moreover the virial condition
\begin{equation}
	2(\lambda-V_j(x))-x\cdot\nabla V_j(x)>0,
	\qquad x\in\mathbb R^n,
	\qquad j=1,2.
\end{equation}
	If
	\begin{equation}
		\|S_1(\lambda,h)-S_2(\lambda,h)\|_
		{\mathcal B(L^2(\mathbb S^{n-1}))}
		=
		o(1),
		\qquad h\to0,
	\end{equation}
	then
	\begin{equation}
		V_1=V_2.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop graph of arXiv:2411.06861, 'Quenched invariance principle for random walks in random environments admitting a cycle de'] For any $d \geq 2$, there exist constants $c_{\mathrm{reg}} , C_{\mathrm{reg}}, C_{\mathrm{S}_1}, C_{\mathrm{P}}\in (0, \infty)$ that depend at most on $d$,  
  such that for any $x \in \mathbb{Z}^d$, $n\in \mathbb{N}$ the following holds true:

  \begin{enumerate}[(i)]
  \item (Volume regularity) 

    \begin{align}
      c_{\mathrm{reg}}\, n^d \;\leq\; |B(x, n)| \;\leq\; C_{\mathrm{reg}}\, n^d.
    \end{align}

  \item (Sobolev inequality) 
  For every function $u\colon \mathbb{Z}^d \to\mathbb{R}$ with $\supp{u} \subset B(x, n)$,

    \begin{align} 
      \Norm{u}{d/(d-1), B(x, n)}
      \;\leq\;
      C_{\mathrm{S_1}}\, \frac{n}{\abs{B(x, n)}}\, \sum_{\{y, y'\} \in E_d} |u(y) - u(y')|.
    \end{align}


  \item (Weak Poincar\'{e} inequality) 

    For every function $u\colon \mathbb{Z}^d \to\mathbb{R}$

    \begin{align}
      \Norm{u - (u)_{B(x, n)}}{1, B(x, n)}

      \;\leq\;
      C_{\mathrm{P}}\, \frac{n}{\abs{B(x, n)})} 
      \sum_{\substack{y, y' \in B(x, n)\\ \{y, y'\} \in E_d}}
      \mspace{-24mu}|u(y) - u(y')|,
    \end{align}

    where $(u)_{B(x, n)} \ensuremath{\mathrel{\mathop:}=} \frac{1}{|B(x, n)|} \sum_{y \in B(x, n)} u(y)$.
  \end{enumerate}

