[Cor 9 of arXiv:2606.30349, 'Attenuated Poisson Dirichlet approximations for divisibility configurations'] Define
\begin{align*}
\widetilde S_m
:=
\frac{1}{\log m}
\sum_{p\le m}\log(p)\,\mathbbm{1}_{\{\xi_p\ge1\}}.
\end{align*}
Then there exists a universal constant $C>0$ such that
\begin{align*}
\big|\Pb[\widetilde S_m\le z]-e^{-\gamma_{\mathrm E}}\mathcal{I}[\rho](z)\big|
\le
\frac{C(1+1/z^2)}{\log m}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:der-mart-multi-bis of arXiv:2608.20537, 'Persistent anisotropy in multi-dimensional\\ branching Brownian motion'] Let $\beta_t$ satisfy (equation eq:integral-condition of the paper).
  Then for every nonempty open $U' \Subset U$, there exists $t_{\textnormal{max}}(d,U') \leq -T$ and $c(d,U') > 0$ such that
  \begin{equation}

    h_T(t, r, \theta) \geq c [b_{\left |t \right|} - r] \mathrm{e}^{-[b_{\left |t \right|} - r]}
  \end{equation}
  for all $t \leq t_{\textnormal{max}}$, $\theta \in U'$, and $b_{\left |t \right|} - r \in [4 \log \left |t \right|, \left |t \right|/8]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 17 of arXiv:2604.05910, '\textbf{Well-posedness and Hurst parameter estimation for fluid equations driven by fracti'] {\em(Young integral)}
    Let  $\xi\in\mathcal{Y}$. Then 
     there exists a map $\mathcal{I}: \mathcal{Y} \to C([0,T];\cB_\delta)\cap C^\gamma([0,T];\cB_{\delta-\gamma}) $ such that $\mathcal{I}_0=0$ which satisfies for every $0\leq s \leq t\leq T$ and $0\leq \theta<2\gamma$ the estimate:
    \begin{align} 
    \| (\delta^S \mathcal{I}(\xi))_{s,t} - S_{t-s}\xi_{s,t}\|_{\delta-\gamma+\theta} \lesssim [W^H]_\gamma \|\xi\|_{\mathcal{Y}} |t-s|^{2\gamma-\theta}.
    \end{align}
    In particular, the convolution 
   \begin{align*}
      \mathcal{I}_t(\xi) := \lim\limits_{\pi\in\cP([0,t]),|\pi|\to 0} \sum\limits_{[u,v]\in\pi} S_{t-u}\xi_{u,v} 
   \end{align*}
   exists in $\cB_{\delta-\gamma}$.

[Theorem 153 of arXiv:2601.16377, '2601.16377'] Consider a discrete ensemble satisfying Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit}, \ref{Assumptions_analyticity} and suppose that the equilibrium measure has no saturations. Let $\eps>0$ be small enough, so that the $\eps$-neighborhoods of the bands are pairwise disjoint. Let $L \in \amsmathbb{Z}_{> 0}$ and a $L$-tuple of integers $\boldsymbol{k} \in [H]^{L}$ both independent of $\N$, let a (possibly $\N$-dependent) $L$-tuple of functions $\boldsymbol{f}(z)$ such that $f_l(z)$ is a holomorphic function of $z$ in a $\N$-independent complex neighborhood of $[\alpha_{k_l}-\eps,\beta_{k_l}+\eps]$ for any $l \in [L]$. Assume there exists a constant $C > 0$ such that $\max_{l} \sup_{z} |f_l(z)| \leq C$.

 Let $\textnormal{\textsf{\textbf{Gau\ss{}}}}[\boldsymbol{f}]$ be a $L$-dimensional random Gaussian vector with covariance
 \begin{equation}

\textnormal{\textsf{Cov}}_{l_1,l_2}[\boldsymbol{f},\boldsymbol{f}] = \oint_{\gamma_{k_{l_1}}} \oint_{\gamma_{k_{l_2}}}
 f_{l_1}(z_1) f_{l_2}(z_2)\,\mathcal{F}_{k_{l_1},k_{l_2}}(z_1,z_2)\,\frac{\dd z_1 \dd z_2}{(2\ii\pi)^2},
\end{equation}
 and mean equal to the sum of $\mathbbm{Rest}[f_l]$ from \eqref{eq_x164} and $\mathbbm{Rest}'[f_l]$ from \eqref{eq_x257}\footnote{The appearance of this term is caused by the centering with respect to localized equilibrium measure in Corollary~\ref{Corollary_CLT_relaxed} versus the equilibrium measure of the original ensemble in our treatment through \eqref{eq_x256}. The term is just the difference of two centerings.}, and independent of the $K$-dimensional discrete Gaussian vector $\textnormal{\textsf{\textbf{Gau\ss{}}}}_{\amsmathbb{Z}}$ appearing in Theorem~\ref{Theorem_CLT_for_filling_fractions}.

 Then, we have as $\N \rightarrow \infty$
 \begin{equation}

\left( \textnormal{\textsf{Lin}}_{k_l}[f_l] - \N \int_{\alpha_{k_l}}^{\beta_{k_l}} f_l(x)\mu_{h^{k_l}}(x)\dd x \right)_{l = 1}^{L} \,\,\stackrel{\textnormal{d}}{\sim} \,\,\textnormal{\textsf{\textbf{Gau\ss{}}}}[\boldsymbol{f}] + \Big( \big\langle (\textnormal{\textsf{\textbf{Gau\ss{}}}}_{\amsmathbb{Z}} - \N \hat{\boldsymbol{n}}^{\boldsymbol{\mu}}) \cdot \boldsymbol{\omega}_{k_l}[f_l] \big\rangle \Big)_{l = 1}^{L},
 \end{equation}
where the convergence in the sense of Definition~\ref{Definition_asymptotic_equivalence} is uniform for fixed constants in the assumptions. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 23 of arXiv:2606.23099, 'Path-dependent Affine Processes'] Equation \eqref{eq:path-dep-inhom-heston-vol} possesses a $[0,\infty)$-valued continuous weak solution $V$.
    Furthermore,
    \begin{equation}
        S(t) = S(0)e^{\int_{0}^{t} \eta(s)\sqrt{V(s)}\bigl(\sqrt{1-\rho^2}dW_1(s) + \rho dW_2(s)\bigr) - \int_{0}^{t} \tfrac{\eta(s)^2V(s)}{2} ds}, \quad t \in [0,T],
    \end{equation}
    is a solution of \eqref{eq:path-dep-inhom-heston-spot-price}, and $S$ is a martingale.

