[Lemma 18 (bound on the discrete Poisson solution) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] \label[lemma]{lem:poisson-sup}
  Suppose \cref{ass:contraction} holds.  For bounded measurable $\eta\colon[0,\infty)\to\mathbb R$, the Neumann series $g\coloneqq \sum_{n\ge0}K_h^n(\eta-\pi_h(\eta))$ converges and solves $(I-K_h)g=\eta-\pi_h(\eta)$, with
  \begin{equation}
    |g(x)|\le C\,h^{-1}\,V(x)\,\snorm{\eta}_\infty,\qquad x\in[0,\infty),\ \ h\in(0,h_0].
  \end{equation}

[Corollary cor:Poisson_fringe of arXiv:2607.22291, 'Rare subtree patterns in size-conditioned Bienaymé trees: Poisson approximation and declum'] Assume that $\mu$ is critical and belongs to the domain of attraction
of an $\alpha$-stable law for some $\alpha\in(1,2]$. Let $(k_n)_{n\geq 0}$ be
an integer sequence such that $k_n\to\infty$ and $k_n=o(n)$.
Suppose that, for every $k\ge1$ and every plane tree $\tau$, $
G_k(\tau)=1
\implies
|\tau|=k$.
Then:
\begin{enumerate}
\item[(i)] If $(n\pi_n)$ is bounded, then
\begin{equation}

d_{\mathrm{TV}} \left(
\# \{u \in \mathcal{T}^{n} : G_{k_{n}}( \mathcal{T}^{n}_{u})=1\},
\mathrm{Poisson}(n \pi_{n})
\right)
\quad \mathop{\longrightarrow}_{n \rightarrow \infty} \quad 0.
\end{equation}

\item[(ii)] If $n\pi_n\to\infty$, then
$$
\frac{
\#\{u\in\mathcal T^n: G_{k_n}(\mathcal T^n_u)=1\}
}{n\pi_n}
\quad \mathop{\longrightarrow}^{(\P)}_{n \rightarrow \infty} \quad 1.
$$
In particular,
$$
\#\{u\in\mathcal T^n: G_{k_n}(\mathcal T^n_u)=1\}
\quad \mathop{\longrightarrow}^{(\P)}_{n \rightarrow \infty} \quad \infty.
$$
\end{enumerate}

[Theorem thm:existence of time dep non rev of arXiv:2607.02367, 'Flux solutions for stochastic chemical systems with sources and sinks'] Assume that $(\Omega, \mathcal R, \mathcal R_s, \mathcal K , \mathcal K_s) $ is a non-bidirectional chemical system with sources and sinks and that the set of reactions $\mathcal R $ is conservative. Assume moreover that $f_0 \in \mathcal P (\mathbb N^M)$ is such that 
\[ 
\sum_{ n \in \mathbb N^M } |n| f_0(n) < \infty . 
\]
    There exists a weak solution $f:  [0, \infty ) \rightarrow \mathcal P (\mathbb N^M) $ that satisfies 
    \begin{align*}
    \sum_{  n \in \mathbb  N^M  } \varphi(n) \partial_t   f (t, n) &=    \sum_{ \rho =1}^r  R_\rho(n) \left[ \varphi(n+ S_\rho) - \varphi(n)  \right] +    \sum_{ k \in \Omega_c }  A_k (n)   \left[ \varphi(n+ e_k ) - \varphi(n)  \right] \\
    & +    \sum_{ k \in \Omega_c } B_k (n)   \left[ \varphi(n-  e_k ) - \varphi(n)  \right] 
    \end{align*}
    for every $ \varphi \in c_{ 00 } ( \mathbb N^M) $. (Proof in the paper; no proof environment follows the statement in the TeX.)

