[Theorem 3 ({\cite[Theorem~1.1) of arXiv:2609.00936, 'Extended Abstract of Counting Divisorial Contractions with Centre a $cA_n$-Singularity'] {Kaw02}, \cite[Theorem~1.13]{Kaw03} and \cite[Theorem~6.1]{Pae24Counting}}] 
Let $k$ be a positive integer and $P$ a $cA_k$ singularity of a terminal variety~$X$. Let $\varphi\colon Y \to X$ be a proper birational morphism with centre~$P$. Then $\varphi$ is a divisorial contraction if and only if one of the following holds:
\begin{enumerate}
\item  $\varphi$ is locally analytically equivalent to the $(r_1, r_2, a, 1)$-blowup of $\mathbb V(f)$ at $\bm 0$ where $f \in \mathbb C\{x, y, z, t\}$ is such that
  \begin{enumerate}
  \item  $r_1, r_2$ and $a$ are positive integers such that $r_1 \leq r_2$, $a(k+1) = r_1 + r_2$ and $a$ is coprime to both $r_1$ and $r_2$, and
  \item  $f = xy + g(z, t)$ where $\operatorname{wt} g = r_1 + r_2$,
  \end{enumerate}
\item  $k = 1$ and $\varphi$ is locally analytically equivalent to the $(1, 5, 3, 2)$-blowup of $\mathbb V(f)$ at $\bm 0$ where $f \in \mathbb C\{x, y, z, t\}$ is such that
  \begin{enumerate}
  \item  $f = xy + z^2 + t^3$,
  \end{enumerate}
\item  $k = 2$ and $\varphi$ is locally analytically equivalent to the $(4, 3, 2, 1)$-blowup of $\mathbb V(f)$ at $\bm 0$ where $f \in \mathbb C\{x, y, z, t\}$ is such that
  \begin{enumerate}
  \item  $f = x^2 + y^2 + z^3 + x t^2$.
  \end{enumerate}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem closure of arXiv:2608.29018, 'Sharp Restricted Isometry Thresholds for\\ Global Minima of Rank-Restricted Matrix LASSO'] Under the same conditions as \lemref{head-controls}.
If 
\begin{equation}
\lambda\ge2\frac{1+\rho_{\delta,t}}{1-\rho_{\delta,t}}\lambda_{0},
\end{equation}
 then \begin{subequations}
\begin{align}
\normtwo{A\sigma} & \le\frac{4\tau_{\delta,t}}{1-\rho_{\delta,t}}\sqrt{r_{\star}}\,\lambda,\\
\normtwo{\sigma} & \le\frac{16\tau_{\delta,t}^{2}}{(1-\rho_{\delta,t})^{2}}\sqrt{r_{\star}}\,\lambda.
\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:upper_lower_general of arXiv:2411.03609, 'Asymptotically optimal Wasserstein couplings for the small-time stable domain of attractio'] Let $\bm{X}$ be in the domain of non-normal attraction of an $\alpha$-stable process $\bm{Z}$.\\ 
{\normalfont(a)} Let $\alpha\in(0,2)\setminus\{1\}$ and Assumption~(\nameref{asm:C}) hold for some $\delta>0$ and $p\ne\alpha-1$. Suppose $G$ is $C^1$ with derivative $\widetilde{G}(t)/t$, where $|\widetilde{G}|\in\mbox{SV}_0$. Further suppose there exists some $\phi\in\mbox{SV}_0\cap\mbox{SV}_\infty$ satisfying $\phi(x)\geqslant\sup_{t>0,y\in[x\wedge 1,x\vee1]}\widetilde{G}(yt)/\widetilde{G}(t)$ for $x>0$. Define $L(t)\coloneqq |\widetilde{G}(t)|/G(t)$, then, for any $q\in(0,1]\cap(0,\alpha)\setminus\{\alpha/(p+1),\alpha/(\alpha\delta+1)\}$ with $\mathds{E}[|\bm{X}_1|^q]<\infty$, we have $\mathcal{W}_q(\bm{X}^t,\bm{Z})=\mathcal{O}(L(t)^q)$ as $t \downarrow 0$ and
\begin{align*}
    \max\{\mathcal{W}_q(\bm{X}^t_1,\bm{Z}_1)
    ,\mathcal{W}_q(\bm{X}^{2t}_1,\bm{Z}_1)\}
    \geqslant \frac{q\log 2}{3}\mathds{E}\big[|\bm{Z}_1|^q\big]\cdot L(t),
    \quad \text{for all sufficiently small }t >0.
\end{align*}
{\normalfont(b)} Define iteratively the functions $\ell_1(t)=\log(e+t)$ and $\ell_{n+1}(t)=\log(e+\ell_n(t))$ for $t\geqslant 0$ and $n\in\mathbb{N}$. Suppose $G(t)$ is eventually equal to $\ell_n(1/t)^{q_n}\cdots\ell_m(1/t)^{q_m}$ where $1\leqslant n\leqslant m$ in $\mathbb{N}$ and either $q_n,\ldots,q_m\geqslant 0$ with $q_n,q_m>0$ or $q_n,\ldots,q_m\leqslant 0$ with $q_n,q_m<0$. Then $G$ satisfies the assumptions of Part (a). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition banachmazur of arXiv:2411.14177, '\textbf{Invariant Sublinear Expectations}'] Let $\ell_{\infty}$ be the space of all bounded sequences. A positive linear functional $\Lambda: \ell_{\infty} \rightarrow \mathbb{R}$ is a Banach-Mazur limit if
    \begin{enumerate}
        \item $\quad \Lambda(\boldsymbol{e})=1$, where $\boldsymbol{e}=(1,1,1, \ldots)$,
        \item $\quad \Lambda\left(x_1, x_2, \ldots\right)=\Lambda\left(x_2, x_3, \ldots\right)$ for each $\left(x_1, x_2, \ldots\right) \in \ell_{\infty}$.
    \end{enumerate}

[Theorem 4 (Exact CNN representation of the slope change classifier) of arXiv:2609.00402, '2609.00402'] Let \(T\geq5\), \(\mathcal I=\{3,\ldots,T-2\}\), and \(B=2(T-4)\). Let $\bm L=(1,\ldots,1)$, $\bm k=\{k_{b,1}=T:b=1,\ldots,B\}$, $\bm{\mathcal P}=
\{(\operatorname{Pool}_{b,1},w_{b,1},s_{b,1})
=(\operatorname{Id},1,1):b=1,\ldots,B\}$, $\bm C=\{C_{b,0}=1,C_{b,1}=1:b=1,\ldots,B\}$, $\bm m=(1,\ldots,1)$. For every \(\lambda>0\), there exists $f_{S,\lambda}\in
\mathcal F_{\mathrm{CNN}}
(T,B,\bm L,\bm k,\bm{\mathcal P},\bm C,\bm m)$ such that $\mathbb I\{f_{S,\lambda}(\bm X)>0\}
=\mathbb I\{S(\bm X)>\lambda\}$ for every $\bm X\in\mathbb R^T$. Consequently, $h_{S,\lambda}\in \mathcal H_{\mathrm{CNN}} (T,B,\bm L,\bm k,\bm{\mathcal P},\bm C,\bm m)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop_8 of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] Let $\lambda_1,\cdots, \lambda_k$ be as in ((poloi_1 of the paper)). If
\begin{eqnarray}

t+b_k\ge\frac{\sum_{i=k+1}^n \lambda_i^2}{a_k},
\end{eqnarray}
then 
\begin{eqnarray}

\Pr(\boldsymbol{\Delta}>t)\leq e^{-\frac{\kappa(t+b_k)}{a_k}}\prod_{i=1}^k \Big(2\kappa\frac{- \lambda_i}{a_k}+1\Big)^{-\frac{1}{2}},
\end{eqnarray}
where $a_k, b_k$ are given in ((a_k_b_k of the paper)) and $\kappa$ is given in ((HW_constant of the paper)).

