[Theorem 49 (Factor capture and positive exhaustion) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] One has
\begin{equation}
 0\le\widehat N_q\le QR^2\Id.

\end{equation}
Applying the top-eigenspace rule to
$\widehat E_q=R_q^*\widehat N_qR_q$ gives
\begin{equation}
 \sum_{a,q}\norm{P_{\widehat V_*}r_{a,q}}^2
 \ge
 \widehat\kappa_{Q,d}
 \frac{\widehat{\mathfrak H}_Q(A,r)}{R^2},
 \qquad
 \boxed{\widehat\kappa_{Q,d}=\frac1{dQ^2}}.

\end{equation}
At extraction level $J$, stop when
\begin{equation}
 \widehat{\mathfrak H}_Q(A,r)
 \le
 \widehat\delta_J
 :=
 \frac{dQ^2R^4}{J}.

\end{equation}
Fewer than $J$ promotions occur, and along the nested trajectory
\begin{equation}
 \sum_{j\ge0}
 \widehat{\mathfrak H}_Q(A^{[j]},r^{[j]})
 \le dQ^2R^4,
 \qquad
 \widehat{\mathfrak H}_Q(A^{[J]},r^{[J]})
 \longrightarrow0.

\end{equation}
Consequently every proper residual--residual raw contraction and every
active--residual raw contraction tends to zero, while residual covariance is retained.

[Proposition prop:positive_parity_implies_signed_monotonicity of arXiv:2605.15401, 'Noise Tradeoffs, Stationary Information Flow, and Structural Balance in Unit-Birth Network'] Assume that for each ordered pair $j\neq i$ such that $f_i$ depends nontrivially on $x_j$, the map $x_j\mapsto f_i(x_{-i})$ is globally either nondecreasing or nonincreasing. Then the following are equivalent:
\begin{enumerate}
\item every cycle in the underlying signed graph, obtained by ignoring edge orientation, has positive parity, that is, contains an even number of negative edges;

    \item the signed interaction graph is structurally balanced;
    \item there exists $\sigma\in\{-1,1\}^N$ such that
    Assumption~(ass:signed_monotonicity of the paper) holds.
\end{enumerate}
In particular, every structurally balanced interaction graph yields a
signature $\sigma$ for which (equation eq:signed_monotonicity of the paper) holds. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:W-tail of arXiv:2608.23135, 'Graph distance and effective resistance of the random walk trace in four and five dimensio'] There exists $C<\infty$ such that
\begin{equation*}

   \mathbb{P}\bigl(W\ge C\sqrt\delta\,n(\log n)^{-3/2}\bigr)
   \le C\sqrt\delta+o_n(1).
\end{equation*}

[Theorem 5 of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] Suppose we are in Scenario~\eqref{Scenario_1}, and let $H_{0}$, defined in \eqref{H_{0}_defn}, satisfy the criterion:
\begin{equation}
(q_{1}+q_{2})\max\left\{\sup\left\{\left|\frac{\partial}{\partial x}H_{0}(x,y)\right|:(x,y)\in\mathcal{S}\right\},\sup\left\{\left|\frac{\partial}{\partial y}H_{0}(x,y)\right|:(x,y)\in\mathcal{S}\right\}\right\}<1.}
\end{equation}
Then there exists a unique root, say $(x^{*},y^{*})$, of the function $h$, defined in \eqref{h_H_defns}, in the set $\mathcal{S}$, and irrespective of whether the samples are drawn with replacement or without, the sequence $\{(n^{-1}A_{n},n^{-1}B_{n})\}$ converges almost surely to $(x^{*},y^{*})$. The same conclusion remains true if $g\in\mathcal{C}^{(1)}(\mathcal{S})$ and 
\begin{equation}
(q_{1}+q_{2})\max\left\{\sup\left\{\left|\frac{\partial}{\partial x}g(x,y)\right|:(x,y)\in\mathcal{S}\right\},\sup\left\{\left|\frac{\partial}{\partial y}g(x,y)\right|:(x,y)\in\mathcal{S}\right\}\right\}<1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_necessary_estimates of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] For any fixed integer $p\in \mathbb{N}$, let $(\Lambda_i)_{1\le i \le p}$ be an arbitrary sequence of $D\times D$ block matrices similar in form to $\Lambda$, consisting of $N\times N $ deterministic blocks $A_i$ and $A_i^*$ with $\|A_i\|=\mathrm{o}(1)$. Let $(B_i)_{1\le i \le p}$ be an arbitrary sequence of deterministic matrices satisfying $\|B_i\|\le 1$.  
Furthermore, consider a sequence of spectral parameters $z_i=E_i+\mathrm{i} \eta_i\in \mathbb{C}_+$ for $i\in[\![{p}]\!]$, satisfying $\left\lvert z_i \right\rvert\le \tau^{-1}$ for a small constant $\tau>0$.  
Suppose the anisotropic local law (equation eq:aniso_local of the paper) holds for all $G_i-M_i$, where $G_i\equiv  G(z_i,H,\Lambda_i)$ and $M_i\equiv M(z_i,\Lambda_i)$ is the deterministic limit of $G_i$ as defined in (defn_Mm of the paper) with parameter $z_i$. 
Moreover, denote $m_i\equiv \left\langle M_i \right\rangle$ and assume that $ N\eta_i \im m_i (z_i) \gtrsim 1$ for all $i\in [\![{p}]\!]$. Then, for any deterministic unit vectors ${\bf{u}}, {\bf{v}}\in\mathbb{C}^{DN}$ and $s_i\in \{\emptyset,*\}^{p}$, the following estimates hold:
    \begin{equation}
        \begin{aligned}
                {\bf{u}}^*\pa{\prod_{i=1}^p G_i^{s_i} B_i}{\bf{v}}\prec \frac{\pa{\max_{1\le i\le p} \im m_i}^{1_{p\ge 2}}}{\eta^{p-1}},\qquad \avga{\prod_{i=1}^p G_i^{s_i} B_i}\prec \frac{\pa{\max_{1\le i\le p} \im m_i}^{1_{p\ge 2}}}{\eta^{p-1}},
        \end{aligned}
    \end{equation}
    where we denote $\eta:=\min_{i}\eta_i$ and adopt the convention that $G_i^\emptyset=G_i$. 

    We denote by $\Pi_l$ a product consisting of $l$ elements in $\ha{G_i^{s}:i\in [\![{p}]\!],s\in \{\emptyset,*\}}$, along with some elements from $\left\{{M_i}\right\}$ and \smash{$\left\{{E_a}\right\}_{a=1}^D$}. Moreover, suppose all $\Lambda_i$ have the form $\Lambda_i=c_i\Lambda$ for some deterministic coefficients $c_i$ of order $\mathrm{O}(1)$. Then, we have the following estimates.
    \begin{enumerate}
        \item A loop containing one factor of $\Lambda$ satisfies that
    \begin{equation}
    \left\langle\Pi_l \Lambda\right\rangle \prec \begin{cases} N^{-1}\left\lVert \Lambda \right\rVert_{\text{\rm{HS}}}^2=D\left\langle \Lambda^2 \right\rangle, & \text { if } l=0, \\ N^{-1 / 2}\lVert \Lambda \rVert_{\text{\rm{HS}}}\cdot \pa{\max_{1\le i\le p} \im m_i }^{\mathbf 1_{l\ge 2}}\cdot \eta^{-(l-1)}, & \text { if } l \ge 1.\end{cases}
    \end{equation}
    \item A loop containing two factors of $\Lambda$ satisfies that
    \begin{equation}
        \left\langle\Pi_{l_1} \Lambda \Pi_{l_2} \Lambda\right\rangle \prec \begin{cases}N^{-1}\lVert \Lambda \rVert_{\text{\rm{HS}}}^2=D\left\langle \Lambda^2 \right\rangle, & \text { if } l_1+l_2=0, \\ N^{-1}\lVert \Lambda \rVert_{\text{\rm{HS}}}^2\cdot \pa{\max_{1\le i\le p} \im m_i}^{\mathbf 1_{l_1+l_2\ge 2}} \cdot \eta^{-(l_1+l_2-1)},  & \text { if } l_1+l_2 \ge 1.\end{cases}
    \end{equation}
    \end{enumerate}
    The same estimates also hold if some $\Lambda$ factors on the LHS of (equation one_loop_estimate of the paper) and (equation two_loop_estimate of the paper) are replaced by ${\widetilde{\Lambda}}$ (defined in (lem_regular_estimate_localized_eigenvector of the paper)) or ${\widehat{\Lambda}}_t$ (defined in (lem_regular_estimate_localized_eigenvalue of the paper)) for $t\in\left[{0,1}\right]$.

