body:
[Mylem Lem_decoupling of arXiv:2411.08430, 'The Restricted Isometry Property of Block Diagonal Matrices Generated by $\varphi$-Sub-Gau'] Let $F$ be a convex function satisfying $F(x)=F(-x), \forall x\in \mathbb{R}$.  Assume $\xi=(\xi_{1}, \cdots, \xi_{n})^\top$ and $ \eta=(\eta_{1}, \cdots, \eta_{n})^\top$ are random vectors with independent centered entries. Let for any $t>0$ and $i\ge 1$, the independent random variables $\xi_{i}, \eta_{i}$ satisfy for  some $c\ge 1$
	\begin{align}
		\textsf{P}\{ \xi_{i}^{2}\ge t \}\le c\textsf{P}\{ c\vert \eta_{i}\tilde{\eta}_{i}\vert\ge t \},\nonumber
	\end{align}
	where $\tilde{\eta}_{i}$ is an independent copy of $\eta_{i}$. 
	Then, there exists a constant $C$ depending only on $c$ such that
	\begin{align}
		\textsf{E}\sup_{A\in \mathcal{A}}F\big(\xi^\top A\xi-\textsf{E}\xi^\top A\xi\big)\le \textsf{E}\sup_{A\in \mathcal{A}}F\big( C\eta^\top A\tilde{\eta}\big)\nonumber
	\end{align}
	where  $\mathcal{A}$ is a set of $n\times n$ fixed matrices. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 2 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ and 	let $ (X_{N}= I_{p} (f_{N}), N\geq 1)$ with $ f_{N} \in H ^{\odot p}$. Assume 
		\begin{equation}
			X_{N} \xrightarrow[N\to \infty]{(d)} N(0, \sigma ^{2}),
		\end{equation}
		where $\sigma ^{2}>0$. Then
		\begin{enumerate}
			\item  For every $ g\in H ^{\odot p}$, we have
			\begin{equation*}
				\langle f_{N}, g\rangle _{ H ^{\otimes p}} \to _{ N \to \infty} 0.
			\end{equation*}
			\item For every sequence $(g_{N}, N\geq 1)\subset H ^{\odot p}$ which converges in $ H ^{\otimes p}$, 
			\begin{equation*}
				\langle f_{N}, g_{N}\rangle _{ H ^{\otimes p}} \to _{ N \to \infty} 0.
			\end{equation*}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem non-expl of arXiv:2410.24170, 'Persistent hubs in CMJ branching processes with independent increments and preferential at'] Assume that Items~(item:mutual-independence of the paper) and~(item:finiteness of the paper) of Assumption~(ass:gen-ass of the paper) are satisfied, and for $\alpha > 0$, we have 
\begin{equation} 
\sum_{j=1}^{\infty} \E{e^{-\alpha \sum_{i=1}^{j} X_{i}}} < 1.
\end{equation} 
Then, for any $t >0$, $|\mathscr{T}_{t}| < \infty$.

