[Lemma 7 of arXiv:2609.01346, '2609.01346'] Fix $\rho_*>1$ and define
\begin{equation}
 \vartheta_*=\arccos(\rho_*^{-\lambda}),
 \quad
 \tau_*=\int_1^{\rho_*}\frac{d\rho}
 {\sqrt{1-\rho^{-2\lambda}}},
 \quad
 \xi_*=\int_1^{\rho_*}\frac{\rho^{-\lambda}\,d\rho}
 {\sqrt{1-\rho^{-2\lambda}}}.
\end{equation}
Then, as $\delta\downarrow0$,
\begin{align}
 x_\delta(\delta\tau_*)&=\delta\xi_*+O(\delta^{k+2}),\\
 r_\delta(\delta\tau_*)&=\delta\rho_*+O(\delta^{k+2}),\\
 \theta_\delta(\delta\tau_*)&=\vartheta_*+O(\delta^{k+1}).

\end{align}

[Lem 53 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Fix a real number $K$ satisfying \eqref{eq:costanti}; $\mathtt{d} \in [N^{-1/2}, 1)$; and real numbers $q \ge q' \ge 0$ with $\varepsilon_0\ge q \ge N^{3500K\delta-2/3} \mathtt{d}^{-1/3}$. Consider the Glauber dynamics $(H_t)_{t \ge 0}$ starting from an initial condition $\mu\in\mathcal P^+$ and assume that, w.o.p., 
	\begin{flalign}

		\begin{aligned} 
			& H_0 (w) \le \mathcal{H}_q (w) + N^{K\delta-1}, \qquad \text{for all $w \in \mathfrak{X}$}; \\
			& H_0 (w) \le \mathcal{H}_q (w), \qquad \qquad \qquad \text{for all $w \notin \mathfrak{L}_q^+ ({K\delta})$}. 
		\end{aligned} 
	\end{flalign} 

	\noindent Denoting $\mathsf{t} = q^{-1} \mathtt{d}^{-1/3} N^{4/3+15000K\delta}$, the following holds w.o.p. for any $t \in [\mathsf{t}, N^5]$. For any $z \in \mathfrak{X}$ satisfying
	\begin{flalign}

		\mathtt{d}_z \ge N^{-K\delta} \mathtt{d}; \qquad \mathtt{d}_z^{1/2} \mathtt{e}_{z;q'}^{3/2} \le N^{K\delta-1}, \qquad \text{and} \qquad N^{K\delta} (q-q') \le N^{-2/3} \mathtt{d}_z^{-1/3},
	\end{flalign}
	\noindent we have
	\begin{flalign}

		\begin{aligned}
			& H_t (z) \le \mathcal{H}_{q'} (z) + N^{\delta/4-1}, \qquad \text{and} \qquad H_t (z) \le \mathcal{H}_{q'} (z),  \quad \text{if $z \notin \mathfrak{L}_{q'}^+ (\delta)$}.
		\end{aligned} 
	\end{flalign} (Proof in the paper; no proof environment follows the statement in the TeX.)

