body:
[Theorem 5 of arXiv:2604.09248, '\bfseries Limit laws for longest edges in empty region graphs'] Let $\eta_t$ be a stationary Poisson process on $\RR^d$ with intensity $t\geq 2$. To each pair of distinct points $x,y\in\RR^d$ we associate a compact set $S(x,y)$ such that $(x,y)\mapsto S(x,y)$ is measurable and the following assumptions for pairs of distinct points $(x,y),(u,v)\in(\RR^d)^2$ are satisfied:
\begin{itemize}
    \item[(i)] $\vol(S(x,y))=\gamma\|x-y\|^d$ for some $\gamma\in(0,\infty)$,
    \item[(ii)] $S(x,y)\subseteq B^d({x+y\over 2},\alpha\|x-y\|)$ for some {$\alpha\in(\frac{1}{2},\infty)$,}
    \item[(iii)] $\vol(S(x,y)\setminus S(u,v)) \geq \beta\|{x+y\over 2}-{u+v\over 2}\|\|x-y\|^{d-1}$ for some $\beta\in(0,\infty)$ if $\|x-y\|\geq\|u-v\|$ and $S(x,y)\cap S(u,v)\neq\varnothing$,
    \item[(iv)] $S(x,y)=S(y,x)$.
\end{itemize}
Define the point process
$$
\xi_t := {1\over 2}\sum_{(x,y)\in\eta_{t,\neq}^2}\mathbbm{1}\{(\eta_t-\delta_x-\delta_y)(S(x,y))=0\}\delta_{\big({x+y\over 2},\,\gamma t\|x-y\|^d-\log(t)-\log(\kappa_d/(2\gamma)),\,\mathrm{span}\{x-y\}\big)}
$$
on $\RR^d\times\RR\times\LL^d$, denote by $\zeta$ a Poisson process on $\RR^d\times\RR\times\LL^d$ with intensity measure $\vol\otimes\mu\otimes\nu$, and let $W\in\mathcal{B}(\RR^d)$ with $\vol(W)<\infty$ and $b\in\RR$. Then, for any $t\geq 2$,
\begin{equation}
\mathrm{d}_{\mathrm{KR}}(\xi_t|_{W\times[b,\infty)\times\LL^d},\zeta|_{W\times[b,\infty)\times\LL^d}) \leq \begin{cases}
        c\log^{-(d-2)}(t), & d \ge 3,\\
        c\log^{-1/2}(t), & d=2,
    \end{cases}
\end{equation}
where $c\in(0,\infty)$ is a constant only depending on $d$, $\vol(W)$, $b$, $\alpha$, $\beta$, and $\gamma$. {Moreover, one has $\xi_t\overset{d}{\longrightarrow} \zeta$ as $t\to\infty$.} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm thm_1 of arXiv:2503.22334, 'Probabilistic analysis of optimal multi-pivot QuickSort'] Let $K\in {\mathbb N}$ and $\lambda\in \mathbb{R}$. For the normalization $Y_n:=(X_n-{\mathbb E}\left[X_n\right])/n$ as $n\to\infty$ we have 
\begin{align*}
   Y_n&\stackrel{d}{\longrightarrow} Z_K,\\
   {\mathbb E}\left[\exp(\lambda Y_n)\right] &\longrightarrow {\mathbb E}\left[\exp(\lambda Z_K)\right]<\infty,
\end{align*}
where the distribution of $Z_K$ is determined as the unique centered, square integrable probability measure such that
\begin{align}
Z_K \overset{\text{d}}{=} \sum_{i=0}^{K} \kl*{D_i Z_K^{(i)}+\alpha_K D_i \ln\left(D_i\right)}+l_{\mathrm{opt}}(D),
\end{align}
where $D,Z_K^{(0)},\dots,Z_K^{(K)}$ are independent and $Z_K^{(i)}$ has the same distribution as $Z_K$ for all $i=0,\dots,K$.
Moreover, we have moments convergence, i.e., all moments of $Y_n$ converge to the moments of $Z_K$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 (Potter bound at $0$) of arXiv:2604.00642, 'Quantitative central limit theorem for an integrated periodogram via the fourth moment the'] For any slowly varying $L$ at $0$ and any $\varepsilon>0$, there exist $C_\varepsilon$ and $\delta>0$ such that
for all $0<|\lambda|,|\omega|\le\delta$,
\[
\frac{L(\omega)}{L(\lambda)}
\le C_\varepsilon\Big(\big(\tfrac{|\omega|}{|\lambda|}\big)^{\varepsilon} \vee \big(\tfrac{|\omega|}{|\lambda|}\big)^{-\varepsilon}\Big).
\]

[Lemma tilde of arXiv:2605.05904, 'Schr\"odinger's problem with constraints'] Suppose Assumption (a:main of the paper) holds and consider a filtered probability space $(\Om,\cG, \bbG, \bbQ)$, with $\bbG=(\cG_t)_{t\in [0,1]}$ satisfying the usual conditions, which supports a 2-dimensional standard Brownian motion $(\beta_1,\beta_2)$  as well as a $\cG_0$-measurable random variable $Z_1$ with $\bbQ(Z_1\in dz)=f_1(z)\eta(dz)$.  Then there exits a unique  $\bbG$-adapted  strong solution to 
\begin{equation}
\begin{split}
    dZ_t&= \chf_{Z_t\in E}\left\{b(t,Z_t) + \sigma^2(t,Z_t)\bigg(\frac{q_y(t,1;Z_t,Z_{1})}{q(t,1;Z_t,Z_{1})}\chf_{Z_{1}\in E}+ \frac{L_z(t,1;Z_t)}{L(t,1;Z_t)}\chf_{Z_{1}=\ell}\bigg)\right\}dt \\
&+\chf_{Z_t\in E}\sigma(t,Z_t)d\beta^1_t, \quad t<1,\quad Z_0=z_0;  \\
dY_t &=\chf_{Y_t\in E}\left\{b(t,Y_t) + \sigma^2(t,Y_t)\frac{\rho_y(t,Y_t,Z_{1})}{\rho(t,Y_t,Z_{1})}dt + \chf_{Y_t\in E}\sigma(t,Y_t)d\beta^2_t\right\},\quad t<1,\quad Y_0=z_0. 
\end{split}
\end{equation}
Moreover, $Z_t \to Z_1$ a.s., and, in its own filtration, $Y$ follows
\begin{equation}
dY_t =\chf_{Y_t\in E}\left\{\Big(b(t,Y_t)+\sigma^2(t,Y_t)\frac{\pi^1_y(t,Y_t)}{\pi^1(t,Y_t)}\Big) dt +\sigma(t,Y_t)dB^Y_t\right\},
\end{equation}
where $B^Y$ is a Brownian motion adapted to the natural filtration of $Y$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2608.21701, 'Superdiffusivity of random walks on the three-dimensional randomly oriented Manhattan latt'] Let $R$ be a positive diagonal operator with Fourier multipliers $(\mathfrak r^{(n)})_{n\ge 1}$ satisfying \eqref{eq:mul.symm}.
Let $\widetilde R$ be a positive diagonal operator with Fourier multipliers $(\widetilde{\mathfrak r}^{(n)})_{n\ge 1}$ such that, for every $j\in[d]^n$ and every $p\in\mathbb T_j^d$,
\begin{align}

&\frac{1}{(2\pi)^{d-1}} \sum_{i=1}^d \sin^2\Big(\sum_{\ell=1}^n p_\ell^i\Big) \int_{\mathbb T_i^d} \mathfrak{r}_{j,i}^{(n+1)}(p,q)\rmd q \le \widetilde{\mathfrak{r}}_{j}^{(n)}(p).
\end{align}
Then
\begin{equation}

V_{\rm Diag}(R,f) \le \langle f,\widetilde R f\rangle_{\ell^2(U,d,n)}.
\end{equation}
If \eqref{eq:diag.criterion} holds with the opposite inequality, then \eqref{eq:diag.criterion.forms} also holds with the opposite inequality.

