[Definition def:freezing-ising of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] For any $B\in \R$, the ferromagnetic Ising measure on $T^\k$ with freezing temperature and 
         plus/minus boundary condition are defined as follows: 
    \begin{equation}
        \ising_\k^+(\infty,B)=\ising_\k^+(\infty)\coloneqq \delta_{T^{\k,+}},\quad \ising_\k^-(\infty,B)=\ising_\k^-(\infty)\coloneqq \delta_{T^{\k,-}}.
    \end{equation}

         In the antiferromagnetic regime, for any $B\in \R$, extend the definition of the unique $\TIS$ Ising measure $\ising_\k^\sharp$ to the following antiferromagnetic Ising measure on $T^\k$ with freezing temperature: 
    \begin{equation}
        \ising_\k^{\sharp}(-\infty,B)=\ising_\k^{\sharp}(-\infty)\coloneqq \frac{1}{2}\delta_{T^{\k,\pm}}+\frac{1}{2}\delta_{T^{k,\mp}}.
    \end{equation}

[Lem 52 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $x\in \Lambda_n$ and $y\sim x$. One has
\begin{equation}
	\mathbf P^{\emptyset}_{\beta_c}[y\connect{\mathcal M_n\:}\mathbb H_n]=\langle \sigma_y\sigma_{\mathcal R_n(y)}\rangle_{\beta_c},
\end{equation}
and
\begin{equation}
    \mathbf E^{\emptyset}_{\beta_c}\Big[\mathds{1}\{0,x\in \mathcal{S}_n,\: y \xleftrightarrow[]{\:\mathcal M_n\:} \mathbb H_n \}\langle\sigma_0\sigma_x\rangle_{\mathcal{S}_n,\beta}\Big]
    \leq
   \Big(\langle \sigma_0\sigma_x\rangle_{\beta_c}-\langle \sigma_0\sigma_{\mathcal{R}_n(x)}\rangle_{\beta_c}\Big)\langle \sigma_y \sigma_{\mathcal{R}_n(y)}\rangle_{\beta_c}.
\end{equation}

[Lem 51 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] There exists $K_1>0$ such that, for every $n\geq 1$,
\begin{equation}
	\mathbf E^{\emptyset}_{\beta_c}[\mathds{1}_{0\in \mathcal S_n}\varphi_{\beta_c}(\mathcal S_n)]\leq K_1 (\log n)^{\mathds{1}_{d=4}}.
\end{equation}

