[Theorem thm:inverse of arXiv:2608.23742, 'Second-order fusion asymptotics for $\Sine_\beta$ correlation functions'] Let $\beta>0$, $m\ge2$, and $m\beta>1$. Let $X_{\beta,m\beta/2}$ denote the zero set of $\xi^{\beta,m\beta/2}$, equivalently the $\mathsf{HP}_{\beta,m\beta/2}$ point process. Then
\begin{equation}
\mathbb E\sum_{x\in X_{\beta,m\beta/2}}\frac1{x^2}
=\frac{m\beta}{4(m\beta-1)(2m+1)}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 12 (Long-time bounds for the propagated test functionals) of arXiv:2605.03057, 'Uniform-in-time quantitative fluctuations of large scale interacting particle systems'] Assume Assumption~\ref{ass:coeff-level-new}, and let $ \varphi \in C_b^7\left( \R^d \right) $.
Then, there exists a constant $C > 0$ such that the following hold.
\begin{enumerate}
\item[(i)] For $\ell \in \left\{ 1,2 \right\}$, $ \sup_{t \ge 0}
\norm{P_t\Phi_{\ell}}_{M^5\big( \Ptwo \big)}
\le C$.

\item[(ii)] For $\ell \in \left\{ 1,2 \right\}$ and every $t \ge 0$,
  $\sup_{x,y \in \R^d,\, \mu \in \Ptwo}
\abs{\partial_{\mu\mu}^2 P_t\Phi_{\ell}\left( \mu \right)\left( x,y \right)}
\le C e^{-\omega t}$.

\item[(iii)] For $\ell \in \left\{ 1,2 \right\}$ and every $t \ge 0$,
  $ \norm{\Gamma P_t \Phi_\ell}_{M^5\big( \Ptwo \big)}
\le C e^{-\omega t}$.
\end{enumerate}

[Proposition 1 of arXiv:2609.01850, 'A comparison theorem for relative regular holonomic $\shd$-modules'] Let $F$ be an object of $\rD^\rb_{\Rc}(\pOS)$. Then, the support of $F$ satisfies: 
\begin{equation}
\supp F=\bigcup\limits_{i\in I}X_i\times S_i
\end{equation}
for some compact subanalytic contractible subsets $X_i$ of $X$ and some closed analytic subsets $S_i$ of $S$, and, locally on $X$, the set $I$ is finite.
Moreover, the sets $S_i$ are independent of the family $(X_i)_{i\in I}$.

[Definition 9 (see \cite{paper1}) of arXiv:2609.01114, 'Unbalanced spectral Tur\'an problem for color-critical graphs with prescribed large maximu'] Let $F$ be a graph with $\chi(F)=r+1\ge3$.  Define
	\begin{equation*}
		t_F:=\inf\left\{t\in[-1,1):\,\limsup_{n\to\infty}\frac{\ex(n,\mathcal M(\partial_c F))}{n^{1+t}}<+\infty\right\}.
	\end{equation*}
	Then $t_F\in\{-1\}\cup[0,1)$, where the gap $(-1,0)$ is excluded by \cite[Theorem 2.36]{Furedi-Simonovits}.  For each fixed boundary family used below, we choose an exponent $s_F\in[0,1)$ large enough so that
	\begin{equation*}
		\max\{0,t_F\}\le s_F
		\quad\text{and}\quad
		\ex(n,\mathcal M(\partial_c F))=O_{F}(n^{1+s_F}).
	\end{equation*}
	The value of $s_F$ is not assumed to be optimal.

