[Definition def:int:local of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Let $\kappa, d \in \ensuremath{\mathbb{N}}$ and $T \in (0, \infty)$. Let $U, W:\ensuremath{\mathbb{R}}^d \rightarrow \ensuremath{\mathbb{R}}$ be continuously differentiable functions. Define the function
\begin{equation}
        b(\mathbf{x}) := \nabla U(x_0) + \sum_{v = 1}^\kappa \nabla W(x_0 - x_v).

    \end{equation}
Let $\lambda \in {\mathcal{M}_{\kappa, d}}$. A solution to the \emph{$\kappa$-regular Markov local-field equation}, (henceforth abbreviated to \emph{$\kappa$-MLFE{}}), on $[0, T]$ with potentials $(U, W)$ and initial law $\lambda$ is a tuple 
    \begin{equation*}
        \Big((\Omega, \mathcal{F}, \mathbb{F}, \mathbb P), (\mu, \gamma), (\mathbf{B}, \mathbf{X})\Big)
    \end{equation*}
    such that
    \begin{enumerate}
        \item $(\Omega, \mathcal{F}, \mathbb P)$ is a probability space with a filtration $\mathbb{F} = (\mathcal{F}_t)_{t \in [0, T]}$.
        \item $\mathbf{B} := (B_v)_{v \in \{0, \ldots, \kappa\}}$ is a family of $d$-dimensional independent $\mathbb{F}$-Brownian motions on $[0, T]$.
        \item $\mathbf{X} := (X_v)_{v \in \{0, \ldots, \kappa\}}$ is a family of $\mathbb{F}$-adapted $d$-dimensional continuous processes on $[0, T]$. Moreover, $\mathbf{X}$ is a Markov process with respect to its natural filtration.
        \item $\mu$ satisfies $\mu = \mathcal{L}(\mathbf{X})$, $\mu_0 = \lambda$, and $\mu \in \mathcal{M}_{k,d}^T$. 
        \item The measurable function $\gamma: [0, T] \times \ensuremath{\mathbb{R}}^d\times \ensuremath{\mathbb{R}}^d \rightarrow \ensuremath{\mathbb{R}}^d$ satisfies
        \begin{equation}
            \gamma(t, X_0(t), X_1(t)) = \mathbb E\big[ b(\mathbf{X}(t) ) \big| X_0(t), X_1(t) \big], \quad {\mu}_t\text{-almost surely for a.e. }t \in [0, T]

        \end{equation}
        \item $\mathbf{X}$ satisfies the following system of SDEs for $t \in (0, T]$:
        \begin{equation}

        \begin{split}
            dX_0(t) &= -b(\mathbf{X}(t)) dt + \sqrt{2} dB_0(t), \\
            dX_v(t) &= -\gamma(t, X_v(t), X_0(t)) dt + \sqrt{2} dB_v(t), \quad v = 1, \ldots, \kappa.
        \end{split}
        \end{equation}
        \item For each $v \in \{1, \ldots, \kappa\}$
        \begin{align}
            \int_0^T \Big( \big|b\big(\mathbf{X}(t)\big)\big|^2 + \big| \gamma\big(t, X_0(t), X_v(t)\big) \big| ^2 + \gamma\big(t, X_v(t), X_0(t)\big)\big|^2 \Big) dt < \infty \quad \text{a.s.}

        \end{align}
    \end{enumerate}
    Further, the tuple is said to be a solution to the $\kappa$-MLFE{} on $[0, \infty)$ if all properties hold with $[0, T]$ replaced with $[0, \infty)$

