[Prop 88 of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] In any dimension, one has uniqueness of the martingale problem for the SPDEs appearing in Theorems \ref{main1} $-$ \ref{main4}. More precisely, we have the following result.

     Fix $\alpha<0$, $\tau\in \mathbb R$, $p\in\mathbb Z_{\ge 0},$ and coefficients $\gamma_{  k_1,k_2}\in\mathbb R$. Consider any $C([0,T], C^{\alpha,\tau}(\mathbb R^d))$-valued random process $u(t,\bullet)$ adapted to the canonical filtration, with $u(0,\bullet)\equiv 0$. If the processes 
\begin{align*}
    M_t(\phi)&:= u(t,\phi) - u(0,G_t*\phi)- \frac12 \int_0^t  u(s,\Delta \phi)\dr s \\ G_t(\phi) &:= M_t(\phi)^2 -  \sum_{\#(  k_1)=p, \#(  k_2)=p} \gamma_{  k_1,  k_2} \int_0^t \int_{\mathbb R^2} \partial^{  k_1 }\phi(a) \partial^{  k_2 }\phi(a)\cdot (\mathfrak H_0 *G_t)(a)^2\dr a \dr s
\end{align*}
are both martingales for every $\phi\in C_c^\infty(\mathbb R^d)$, then $u(t,\bullet)$ must have the same law as the solution of the additive-noise SPDE given by \begin{equation}\partial_t \mathcal U(t,   x) = \frac12\Delta \mathcal U(t,   x) + \eta(t,x),
\end{equation}
where $\eta$ is the Gaussian noise on $\mathbb R^d\times \mathbb R_+$ that has covariance structure given by $$\mathbb E[(\eta(t,\bullet),\phi)_{L^2(\mathbb R^d)}^2] = \sum_{\#(  k_1)=p, \#(  k_2)=p} \gamma_{  k_1,  k_2} \int_{\mathbb R^2} \partial^{  k_1 }\phi(a) \partial^{  k_2 }\phi(a)\cdot (\mathfrak H_0 *G_t)(a)^2\dr a,\;\;\;\;\;\;\;\;\;\;\;t>0, \;\phi\in C_c^\infty(\mathbb R^d).$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 of arXiv:2512.08595, 'Small time asymptotics of spectral heat content of isotropic processes'] Let $\Omega$ be a bounded, open set in $\R^d$ with finite perimeter. Then, 
		\begin{align*}
			\liminf_{t\downarrow 0}\frac{\Vol(\Omega)-Q^X_\Omega(t)}{\mu(t)}\ge \Per(\Omega).
		\end{align*}
		\begin{remark}
			When $\Omega$ has $C^{1,1}$ boundary, the above proposition can be proved using a half-space argument similar to the proof of  \cite[Lemma~3.1]{ParkSong2022}. However, the argument in the aforementioned paper requires the $R$-smooth boundary condition, which does not hold when $\partial\Omega$ is not $C^{1,1}$. 
		\end{remark} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary coro:U=U of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] If   $t_N \ll n_j=O(N^{\frac{1}{3}})$ and $  \theta\gamma n^2 t_N \ll N $,  then
    \begin{equation}
        \mathbb{E}\Big[\prod_{j=1}^s \mathrm{Tr} \frac{1}{n_j+1}U_{n_j}(\frac{H}{2})\Big]=\mathbb{E}\Big[\prod_{j=1}^s \mathrm{Tr} \frac{1}{n_j+1}U_{n_j}(\frac{\widehat{H}}{2})\Big]+o(1).
    \end{equation}

[Lemma 9 (Passing-row slack) of arXiv:2609.01570, 'A Proof of Fraenkel's Conjecture'] Let \(n=|A|-1\).  If the \(s\)-row has mass at least one, then
\begin{equation}
 E:=N\left(1-\sum_{a\ne s}\frac1{d_a}\right)
 <\frac{8n}{7}.
\end{equation}
Call each \(a\in A\setminus\{s\}\) \emph{good} if and only if
\(a\mid Q-s\) or \(a\mid Q+s\), and
\emph{bad} otherwise.
If \(W\) is the sum of these bad elements (with the empty sum understood as
zero), then
\begin{equation}
 W<\frac{16n}{7}.
\end{equation}

[Lem thinning of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] For each $n \geq 1$, let ${\rm Y}_n$ be a random subset of ${\rm D}_n$ which is $L_{t^A_n}({\rm D}_n)$-measurable. Given $u \geq 0$, define the sets ${\rm Z}_n(u):={\rm W}_n(u) \cap {\rm Y}_n$, ${\rm X}_n(u+1):={\rm S}_n(u+1) \cap {\rm Y}_n$ and 
	\begin{equation}
		\mathbb{Z}_n(u):=\{ z \in \mathbb{X}_{n-r_n} : {\rm Z}_n(u) \cap {\rm Q}(z;n-r_n) \neq \emptyset\}.
	\end{equation} Then, there exist constants $C,c > 0$ (which depend only on $u$) such that, if $n$ is sufficiently large, for each $s > 0$ we have
	\begin{equation}
		\mathbb{P}\left(|\mathbb{Z}_n(u)|>s \sqrt{n}\right) \leq C(1+s^{-1})\mathbb{P}(|{\rm X}_n(u+1)|>cs). 
	\end{equation}

[Definition D:Rho of arXiv:2412.03521, 'On ergodic properties of stochastic PDEs'] A function $\rho:\mathbb{R}^d\mapsto \mathbb{R}$ is called an \textup{admissible weight
  function} if it is a strictly positive, bounded, continuous, and $L^1
  (\mathbb{R}^d)$-integrable function such that for all $T > 0$, there exists a constant
  $C_\rho(T)$ satisfying
  \begin{equation}
    \big(p(t,\cdot)*\rho(\cdot)\big)(x) \le C_\rho(T) \rho(x)
    \quad \text{for all $t\in[0,T]$ and $x\in\mathbb{R}^d$.}
  \end{equation}

[Prop 7463 of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $ ( X, U ) $ be a $ ( c, q ) $-regular innovation
on a measurable set $ \mathcal V $ and let $ ( \theta_n ) $ be an \RMSprop\ algorithm
with arbitrary parameter tuple $ ( \beta, \varepsilon, (\gamma_n), \theta_0 ) $ as in the introduction.
Let $ n_0 \in {\mathbb N}_0 $ and let $ \tau $ be the stopping time given by
\bas{ 
 \tau=\inf\{n\ge n_0: \theta_n\not\in \mathcal V\}.}

One has for every $n\in{\mathbb N}_0\cap [n_0,\infty)$, $i\in\{1,\dots,d\} $, $ \lambda\in[0,\infty)$ that
\bas{
-\ln {\mathbb E}\bigl[e^{-\lambda (v_n^{(i)}+\1_{\{ n\le \tau\}^c}\infty)}|\mathcal F_{n_0}\bigr]\ge\sum_{k=n_0+1}^n \left( c \frac{1-\beta}{1-\beta^n} \beta^{n-k} \lambda \right) \wedge q +\frac{1-\beta^{n_0}}{1-\beta^n} \beta^{n-n_0} \lambda  v_{n_0}^{(i)} .
}
In the case $n=n_0=0$, the last term on the right-hand side is understood as zero.

