[Lemma eq:T1-l of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For any $\rho\geq 0$, under the Palm probability measure of pure handovers of type $\bbinom{1}{i,i}$ with ${\tau}_p={\tau}_n=i$, the Laplace transform of $T$ is
\begin{align}
\mathbb{E}^0_{{\mathcal W }_i}\left[e^{-\rho T}\right]

&= 
\frac {4\lambda_i^2v_i^2} {L_i}
\int_{(\mathbb{R}^+)^3} \zeta_{i,i}(h,t',h'){\rm d}t' {\rm d}h' {\rm d}h,

\end{align}

for $i=1,2$, where the function $\zeta_{1,1}(h,t',h')$ is determined in ((eq:T12d of the paper)) and $\zeta_{2,2}(h,t',h')$, in ((eq:zeta1 of the paper)). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem eq:ap1:linGrowthCondition of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Fix $T \in (0, \infty)$. Suppose $f:[0, T] \times \mathbb{R}^m \rightarrow \mathbb{R}^m$ is a measurable function that satisfies the linear growth condition \begin{equation}
    \sup_{t \leq T}|f_t(x)| \leq C_f(1 + |x|), \quad \text{a.e. }x \in \ensuremath{\mathbb{R}}^d,

\end{equation}
for some $C_f \in (0, \infty)$. Suppose $\mu_0 \in \mathcal{P}(\ensuremath{\mathbb{R}}^m)$ satisfies has finite entropy and second moment. Then the following properties hold.
\begin{enumerate}
    \item The Fokker-Planck equation  (equation eq:ap1:formalPDE of the paper) has a unique weak solution $\{\mu_t\}_{t \in [0, T]}$ such that $\mu_t \in \mathcal{P}(\ensuremath{\mathbb{R}}^m)$ is a probability measure for all $t \in [0, T]$. Moreover, $\mu_t$ has a finite second moment, that is,
\begin{equation}

    \sup_{t \in [0, T]} \int_{\ensuremath{\mathbb{R}}^m} |x|^2 \mu_t(x)dx < \infty.
\end{equation}    
    \item There exists a positive locally H\"older continuous function $\mu:[0, T] \times \ensuremath{\mathbb{R}}^{m} \rightarrow (0, \infty)$ such that $\mu_t(dx) = \mu_t(x) dx$.  The H\"older coefficient and exponent of $\mu$ depends only on $(m,T)$, the linear growth condition of $f$, and the initial condition $\mu_0$. Moreover, $\mu_t \in W^{1, p}_{loc}(\ensuremath{\mathbb{R}}^m)$ for almost every $t \in [0, T]$ and $\mu \in H^{1, p}_{loc}(\ensuremath{\mathbb{R}}^m_T)$ for all $p \geq 1$.
    \item  For every $t \in [0, T]$, we have
\begin{equation}

    \int_0^t \int_{\ensuremath{\mathbb{R}}^{m}} \frac{|\nabla \mu_s(x)|^2}{\mu_s(x)} dx ds < \infty.
\end{equation}
Moreover, we have $\mu \in H^{1, 1}(\ensuremath{\mathbb{R}}^m_T)$ and $\mu_t \in W^{1, 1}(\ensuremath{\mathbb{R}}^m)$ for almost every $t \in (0, T)$.  
\item We have for all $t \in [0, T]$ that
\begin{equation}
    \int_{\ensuremath{\mathbb{R}}^m} \mu_t(x) |\log \mu_t(x)| dx < \infty

\end{equation}
and
\begin{equation}
        \int_0^T \int_{\ensuremath{\mathbb{R}}^m} \mu_t(x) |\log \mu_t(x)| dx < \infty.

\end{equation}
\end{enumerate}

[Dfn of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] On ${\mathbb{R}}^d$ ($d\ge 3$),  we say a function $h: {\mathbb{R}}^d\rightarrow {\mathbb{R}}$ is in Kato class $\mathbf{K}_{d,k}$ (for $k=1,2$) if
\begin{equation*}
\lim_{r\downarrow 0}\sup_{x\in {\mathbb{R}}^n} \int_{|x-y|<r} \frac{\left|h(y)\right|}{|x-y|^{d-k}}dy=0.
\end{equation*}

[Defn Two-valued sets of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $a,b\in \mathbb R$ and let $u$ be a harmonic function in $D$. Let $\phi$ be a GFF with boundary condition $u$ in $D$.  We say that a random closed set $\mathds A_{-a,b}^u$ is a two-valued set with boundary condition $u$ if
\begin{itemize}
    \item $(\phi,\mathds A_{-a,b}^u)$ is a local set,
    \item there exists a random function $h_{\mathds A_{-a,b}^u}$ such that 
    \[
        (\phi_{\mathds A_{-a,b}^u},f)=\int_{D\backslash \mathds A_{-a,b}^u} h_{\mathds A_{-a,b}^u}(z) f(z)dz
        \quad \text{a.s.}
    \]
    for all $f \in C_c^\infty(D)$,
    \item the function $h_{\mathds A_{-a,b}^u}-u$ takes values in the set $\{-a,b\}$.
\end{itemize}

[Lemma Radial Lemma of arXiv:2608.27248, 'Optimal Transport and the ABP Method in Higher Codimension'] The function $F_B$ belongs to $\mathrm{BV}_{\mathrm{loc}}(0,\infty)$ and
\begin{equation*}
\mathrm dF_B(r)\leq2|\mathbb{S}^3|r\,\mathrm dr
\end{equation*}
in the sense of distributions.  If $0\notin\operatorname{int}B$, then
\begin{equation}
 \mathrm dF_B(r)\leq|\mathbb{S}^3|r\,\mathrm dr.
\end{equation}

