\begin{equation}
P = \begin{pmatrix}
\alpha_{(11)}+\alpha_{(12)}& \alpha_{(21)}+\alpha_{(22)}\\
\alpha_{(11)}+\alpha_{(21)}& \alpha_{(12)}+\alpha_{(22)}
