[Definition 13 of arXiv:2608.26084, 'Localic Esakia Duality\\via Conic Frames'] A localic relation~$R$ is called:
	\begin{itemize}
		\item \emph{reflexive} if $\Delta\subseteq R$;
		\item \emph{transitive} if $R\circ R\subseteq R$;
		\item \emph{anti-symmetric} if $R\cap R^\op \subseteq \Delta$.
	\end{itemize}
	Combined, we say~$R$ is a:
	\begin{itemize}
		\item \emph{preorder} if it is reflexive and transitive;
		\item \emph{partial order} if it is an anti-symmetric preorder.
	\end{itemize}

[Prop starting-point of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] There exists $C>0$ such that for all $\beta$, for any $\ell \times h$ rectangle $R$ with $h \ge \log \ell$, with any boundary conditions $\tau$, has mixing time at most $e^{ 8 \beta h}$. As a consequence, for all $n \in [N_0,N]$, we have 
    \begin{align*}
        \mathcal A (L_n, t, e^{ - t e^{ - 8\beta \kappa_N \sqrt{L_n}}})  \qquad \text{and} \qquad \mathcal B(L_n, t, e^{-t e^{- 16\beta \kappa_N \sqrt{L_n}}}) \quad \text{hold}\,.
    \end{align*}

[Proposition 7 (products in the $Y$ scale) of arXiv:2609.01093, 'Ideal MHD below the classical well-posedness threshold'] Let $\preg\ge0$ and
\begin{equation}
 \sreg>\frac{n-1}{2},\qquad \sreg+\preg>\frac n2.
\end{equation}
Then $Y^{\sreg,\preg}$ is a Banach algebra and is a multiplier on $H^{\sreg}$:
\begin{equation}
 \|fg\|_{Y^{\sreg,\preg}}\le C\|f\|_{Y^{\sreg,\preg}}\|g\|_{Y^{\sreg,\preg}},
 \qquad
 \|fg\|_{H^{\sreg}}\le C\|f\|_{H^{\sreg}}\|g\|_{Y^{\sreg,\preg}}.
\end{equation}
By interpolation, the second estimate also holds with $H^\varsigma$ in place of $H^{\sreg}$ for
$0\le\varsigma\le\sreg$.  In particular, at $(\sreg,\preg)=(s-1,1)$,
\begin{equation}
 \|fg\|_{H^\varsigma}\le C\|f\|_{H^\varsigma}\|g\|_{Y^{s-1,1}}
 \quad(0\le\varsigma\le s-1),
\end{equation}
and, after taking $L^2$ in time and using Corollary~\ref{cor:trace-Y},
\[
 \|fg\|_{L^2_tH^{s-1}}
 \le C\|f\|_{L^2_tH^{s-1}}\|g\|_{H^{s-1,1}_{\breg}}.
\]
The hypotheses \eqref{eq:Y-product-range} coincide with the embedding range
\eqref{eq:Y-embed-range}.

[Lemma 138 of arXiv:2601.16377, '2601.16377'] Choose $\theta > 0$, real parameters $\hat{a},\mathfrak{a},\hat{b},\mathfrak{b}$, and a twice continuously differentiable function $f$ in the range required by the formulae below. We introduce shifted parameters
\[
\hat{a}' = \hat{a} + \frac{\frac{1}{2} - \theta}{\N},\qquad \mathfrak{a}' = \mathfrak{a} + \frac{\frac{1}{2} - \theta}{\N},\qquad \hat{b}' = \hat{b} + \frac{\theta - \frac{1}{2}}{\N},\qquad \mathfrak{b}' = \mathfrak{b} + \frac{\theta - \frac{1}{2}}{\N}.
\]
If $\N(\mathfrak{a} - \hat{a})$ is $\theta$ times a positive integer $M$, we have
\begin{equation}

\begin{split}
& \quad \sum_{i = 0}^{M - 1} f\bigg(\hat{a} + \frac{i\theta}{\N}\bigg) - \frac{\N}{\theta} \int_{\hat{a}'}^{\mathfrak{a}'} f(x)\dd x \\
& = \frac{\theta -1}{2\theta}\big(f(\mathfrak{a}') - f(\hat{a}')\big) + \frac{2\theta^2 - 6\theta + 3}{24\theta \N}\big(f'(\mathfrak{a}') - f'(\hat{a}')\big) + O\bigg(\frac{1}{\N^2}\bigg).
\end{split}
\end{equation}
If $\N(\hat{b} - \mathfrak{b})$ is $\theta$ times a positive integer $M$, we have
\begin{equation}

\begin{split}
& \quad \sum_{i = 1}^{M} f\bigg(\mathfrak{b} + \frac{i\theta}{\N}\bigg) - \frac{\N}{\theta} \int_{\mathfrak{b}'}^{\hat{b}'} f(x)\dd x \\
& = \frac{\theta -1}{2\theta}\big(f(\mathfrak{b}') - f(\hat{b}')\big) + \frac{2\theta^2 - 6\theta + 3}{24\theta \N}\big(f'(\hat{b}') - f'(\mathfrak{b}')\big) + O\bigg(\frac{1}{\N^2}\bigg).
\end{split}
\end{equation}
If $\N(\mathfrak{a} - \mathfrak{b})$ is $\theta$ times a positive integer $M$, we have
\begin{equation}

\begin{split}
& \quad \sum_{i = 1}^{M - 1} f\bigg(\mathfrak{b} + \frac{i\theta}{\N}\bigg) - \frac{\N}{\theta} \int_{\mathfrak{b}'}^{\mathfrak{a}'} f(x)\dd x \\
& = \frac{\theta -1}{2\theta}\big(f(\mathfrak{b}') + f(\mathfrak{a}')\big) + \frac{2\theta^2 - 6\theta + 3}{24\theta\N}\big(f'(\mathfrak{a}') - f'(\mathfrak{b}')\big) + O\bigg(\frac{1}{\N^2}\bigg).
\end{split}
\end{equation}

