[Proposition 18 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let Assumption~\ref{assump-PDE} and the same assumptions as in Proposition \ref{propu} hold. In particular, recall that $p> d$, $\gamma\in (\frac{d}{p}, 1)$ and that if $d=3$, $\frac{\gamma}{2} + \frac{3}{2}(\frac{1}{2}-\frac{1}{p}) <1$. Let $q \geq 1$ and $\varepsilon\geq 0$, with $\varepsilon=0$ allowed if $\lim \sigma_{N}=\sigma>0$. Then there exists $C=C(A,k,\gamma,p,d)>0$ and $\mathfrak{C}_{\varepsilon} >0$ such that for any $t\leq T$ and any $N\in \N^*$, we have
\begin{align}
& \bigg(\E \sup_{s\in[0,t]} \big\|\langle v \rangle^{k} (F_{s}^{N} - \tilde{F}_{s}^{N}) \big\|_{L^{2}_{x,v} }^{2q}
+ \sigma_N^{2q}\, \E \bigg[ \Big(\int_{0}^t \big\lVert \langle v \rangle^k \nabla_{v} (F_{s}^{N} - \tilde{F}_{s}^{N})\big\rVert_{L^{2}_{x,v}}^{2} \dd s\Big)^q\bigg] \bigg)^{\frac{1}{q}} \nonumber\\
 & \leq C  \big(\E \big\| \langle v \rangle^{k} (F_{0}^{N}-\tilde{F}_{0}^N) \big\|_{L^{2}_{x,v}}^{2q}\big)^{\frac{1}{q}}
  + C \Big( N^{-2(\alpha-\beta)} + \mathfrak{C}_{\varepsilon} N^{-2\beta(\gamma-\frac{d}{p})+\varepsilon} + N^{-(\frac{1}{2} - d\beta -(d+1)\alpha)} \Big)\nonumber\\
 &\quad + C (1+\sigma_{N}^{-2}) \int_{0}^t \big(\E \sup_{r\in[0,s]} \big\| \langle v \rangle^{k} (F_{r}^{N} - \tilde{F}_{r}^{N}) \big\|_{L^{2}_{x,v} }^{2q}\big)^{\frac{1}{q}} \dd s \\
&\quad + C (1+\sigma_{N}^{-2}) \int_{0}^{t}  \big(\E \big\|u^{N}_s -u^{(N)}_s \big\|_{L^\infty_{x}}^{2q}\big)^{\frac{1}{q}} \dd s.\nonumber
\end{align}
Here and in the rest of the paper, if $\sigma>0$, then one can choose $\varepsilon=0$ and $\mathfrak{C}_{0}<\infty$.

