\\ &= \Prob{\sum_{i=1}^{n-1} X_{i} < \sum_{i=n}^{\phi_{n}-1} (X_{i} - X'_{i})} + \Prob{\sum_{i=n}^{\phi_{n}-1} (X_{i} - X'_{i}) < -\sum_{i=1}^{n-1} X_{i}} = 2\Prob{\sum_{i=1}^{n-1} X_{i} < \sum_{i=n}^{\phi_{n}-1} (X_{i} - X'_{i})},
\end{align*}
\end{linenomath*}
where that latter follows from the fact that $X_{i} - X'_{i} \sim X'_{i} - X_{i}$. Therefore, 
\begin{linenomath*}
    \begin{align} 
        \nonumber \Prob{\sum_{i=1}^{\phi_{n} - 1} X_{i} < \sum_{i=n}^{\phi_{n}-1} X'_{i}} & = \frac{1}{2} \Prob{\bigg(\sum_{i=1}^{n-1} ...","release_manifest_digest":"sha256:d8fe58c62fb3f77ea47242cccfbc2f4ae48af86a386ae4b58e0837893b5f896a","revision_digest":"sha256:664da58b3353cd7de36a613523d9616382da8d8f2fef464657ca1e060609c268","source_id":"arxiv:2410.24170","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

