[Thm 15 (Fourier transform of $\xi_M$ and $\xi_M^c$) of arXiv:2603.27433, 'The $k$-cycle shuffling with repeated cards'] We have
\[
\widehat{\xi_M}(\lambda)
=
\frac{K_{\lambda,\mu}+K_{\lambda',\mu}}{d_\lambda}\,\Id_{d_\lambda}, \quad\widehat{\xi_M^c}(\lambda)
=
\frac{K_{\lambda,\mu}-K_{\lambda',\mu}}{d_\lambda}\,\Id_{d_\lambda},
\]
where
\[
\mu=\mu_M:=(n-M,1,1,\dots,1)\vdash n,
\]
and $K_{\alpha,\mu}$ denotes the Kostka number.

Moreover, if $\l_1<n-M$ and $l(\l)<n-M$, then $\widehat{\xi_M}(\lambda)=\widehat{\xi_M^c}(\lambda)=0$. If $\l_1\ge n-M$, we have
$$\widehat{\xi_M}(\lambda)=\binom{M}{\,n-\lambda_1\,}\frac{
d_{\lambda^*}}{d_\lambda}\,\Id_{d_\lambda},\quad\widehat{\xi_M^c}(\lambda)=\binom{M}{\,n-\lambda_1\,}\frac{
d_{\lambda^*}}{d_\lambda}\,\Id_{d_\lambda}.$$
If $l(\l)\ge n-M$, we have
$$\widehat{\xi_M}(\lambda)=\binom{M}{\,n-l(\lambda)\,}\frac{
d_{\lambda^\bullet}
}{d_\lambda}\,\Id_{d_\lambda},\quad\widehat{\xi_M^c}(\lambda)=-\binom{M}{\,n-l(\lambda)\,}\frac{
d_{\lambda^\bullet}
}{d_\lambda}\,\Id_{d_\lambda}.$$

[Lemma 67 of arXiv:2607.18104, '2607.18104'] Fix some $M\in \N$ and $n\in \N$. 

Assume that for all $i\in \lbr M\rbr$, we have  $\hfix^{\per,(i),\varepsilon}_0$ in $\UCp$ converging to some $\hfix^{\per,(i)}_0 \colon \mathbb{T}\rightarrow \R$ as $\varepsilon \rightarrow 0$ with respect to the UC topology, and initial data $\hfix^{(i),1,\varepsilon,j}_0$ and $\hfix^{(i),2,\varepsilon,j}_0$ in $\UC$ with
\begin{equation}
    \begin{split}
        \hfix^{(i),1,\varepsilon,j}_0(x) &= \hfix^{\textup{patch},n^{-1},\varepsilon}\big(\hfix^{\per,(i),\varepsilon}_0;x,(j-1)n^{-1}\big) \ \forall x\in \Big[ -\frac{1}{8}, \frac{5}{8}\Big] \\
        \hfix^{(i),2,\varepsilon,j}_0(x) &= \hfix^{\textup{patch},n^{-1},\varepsilon}\big(\hfix^{\per,(i),\varepsilon}_0;x,(j-1)n^{-1}\big) \ \forall x\in \Big[ \frac{3}{8}, \frac{9}{8}\Big] , 
    \end{split}
\end{equation}
 such that $\hfix^{(i),1,\varepsilon,j}_0$ and $\hfix^{(i),2,\varepsilon,j}_0$ converge to some $\hfix^{(i),1,j}_0$ and $\hfix^{(i),2,j}_0$ in $\UC$. Then for all $j\in \N$, there exist full-space KPZ fixed points $\hfix^{1,j}$ and $\hfix^{2,j}$ such that as $\varepsilon \rightarrow 0$
\begin{equation}
\begin{split}
    \hAeps_{1,j}\big( \hfix^{(i),1,\varepsilon,j}_0;\cdot,t\big) &\rightarrow \hfix^{1,j}\big(\hfix^{(i),1,j}_0;\cdot,t\big) ,  \\
    \hAeps_{2,j}\big( \hfix^{(i),2,\varepsilon,j}_0;\cdot,t\big) &\rightarrow \hfix^{2,j}\big(\hfix^{(i),2,j}_0;\cdot,t\big) , 
\end{split}
\end{equation} jointly in $i\in \lbr M \rbr$, and $t \in [0,n^{-1}] \cap \mathcal{T}$ with respect to the topology of uniform convergence on compact subsets. On the left sides of \eqref{eq:ASEPconvPatchtwice}, 
the functions $\hAeps_{1,j}\big(\hfix_0^{(i),1,\varepsilon,j};\cdot,t\big)$ and $\hAeps_{2,j}\big(\hfix_0^{(i),2,\varepsilon,j};\cdot,t\big)$ are coupled according to $\Ppatch$. On the right sides of \eqref{eq:ASEPconvPatchtwice}, the functions $\hfix^{1,j}(\hfix^{(i),1,j}_0;\cdot,t)$ are coupled through \eqref{eq:VariationFixedPeriodic} for all $i\in \lbr M \rbr$  under the same directed landscape $\mathcal{L}^{1,j}$; the functions $\hfix^{2,j}(\hfix^{(i),2,j}_0;\cdot,t)$ are coupled through \eqref{eq:VariationFixedPeriodic} for all $i\in \lbr M \rbr$  under the same directed landscape $\mathcal{L}^{2,j}$, and $\mathcal{L}^{1,j}$ and  $\mathcal{L}^{2,j}$  are coupled under some probability measure $\mathbf{P}$, so that
\begin{equation}
  \mathbf{P}\big(  \mathcal{A}^{j}_{n} \big) \geq 1 - C_0\exp(-c_0 n ) 
\end{equation}
holds for some $c_0,C_0>0$, which do not depend on $j$ and $n$, and all $n\in \N$.

[Theorem thm:archimedean_dense of arXiv:2411.07113, '\begin{LARGE}On differentiability and mass distributions of topologically typical multivar'] The following assertions hold:
\begin{description}
    \item[(i)] The family $\{C\in \mathcal{C}_{ar,abs}^d\colon\mathrm{supp}(\mu_C)=\mathbb{I}^d\}$ is dense in $(\mathcal{C}_{ar}^d,d_\infty)$,
    \item[(ii)] The family $\{C\in \mathcal{C}_{ar,dis}^d\colon\mathrm{supp}(\mu_C)=\mathbb{I}^d\}$ is dense in $(\mathcal{C}_{ar}^d,d_\infty)$,
    \item[(iii)] The family $\{C\in \mathcal{C}_{ar,sing}^d\colon\mathrm{supp}(\mu_C)=\mathbb{I}^d\}$ is dense in $(\mathcal{C}_{ar}^d,d_\infty)$.
\end{description}

[Lemma lem:abstract-countable-submersion of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Let the selected response functionals satisfy (equation eq:abstract-RT of the paper).  Then there
are $g_1,\ldots,g_M\in\mathcal Q$ such that
\begin{equation}
 \det(\ell_{n_i}^\mu(g_j))_{i,j=1}^M\ne0.

\end{equation}

[Theorem 9 of arXiv:2609.02175, '2609.02175'] Let $g_1$ and $g_2$ be smooth Riemannian metrics on
	$\mathbb R^n$, $n\geq3$. Assume that there exists $R>0$ such that
	\begin{equation}
		\operatorname{supp}(g_j-g_0)
		\Subset B(0,R),
		\qquad j=1,2,
	\end{equation}
	and that $(B(0,R),g_j)$ is simple for $j=1,2$.
	Assume moreover that $(B(0,R),g_1)$ satisfies one of the
	following conditions:
	\begin{enumerate}
		\item the sectional curvature is non-positive;
		\item there are no focal points;
		\item the sectional curvature is non-negative.
	\end{enumerate}
	If
	\begin{equation}
		\|S_{g_1,h}(\lambda)-S_{g_2,h}(\lambda)\|
		_{\mathcal B(L^2(\mathbb S^{n-1}))}
		=
		o(1),
		\qquad h\to0,
	\end{equation}
	then there exists a diffeomorphism
	\begin{equation}
		\psi:B(0,R)\longrightarrow B(0,R),
		\qquad
		\psi|_{\partial B(0,R)}
		=
		\operatorname{Id},
	\end{equation}
	such that
	\begin{equation}
		g_1
		=
		\psi^*g_2.
	\end{equation}

[Lemma 8 of arXiv:2608.06646, 'Three-dimensional stochastic wave equation with non-Lipschitz coefficients'] For all integers $n$, let $E_n$ be defined in~\eqref{E:EventsEn}. Then we have
\begin{align}
    E_1\bigcap\dots\bigcap E_{n-1}\bigcap F_n\subset E_1\bigcap\dots\bigcap E_{n}\,.
\end{align}

[Thm 5 (Convergence of normalized trace) of arXiv:2604.26499, 'Spectrum of Random Matrices with Exploding Moments'] Let $M$ be the matrix same as in Condition \ref{cond:matrixcond_1_NonHer}.
For any partition $\pi\in\mathcal P(k)$, let
$$
\tau_N^{nh}[T_\pi]
=
\frac{1}{N}
\sum_{\phi:V\to[N]\atop\mathrm{injective}}
\prod_{(u,v)\in E}
m_{\phi(u)\phi(v)},
$$
be defined for $M$ same as in \eqref{eq:tauN_def}.
Then, as $N\to\infty$, the following hold.
\begin{enumerate}
      \item For $\alpha>1$ and for every $T_\pi$ we have
    $$
    \mathbb{E}[\tau_N^{nh}[T_\pi]] \longrightarrow 0 .
    $$
    \item For $\alpha=1$ we have
    $$
    \mathbb{E}\big[\tau_N^{nh}[T_\pi]\big]
   \longrightarrow
    \tau^{nh}[T_\pi]
   :=
    \begin{cases}
   \displaystyle\prod_{k\ge2} C_{k}^{\,q_{k}}, & \text{if $T_\pi$ is a fat tree},\\[0.8em]
    0, & \text{otherwise,}
   \end{cases}
   $$
  where $q_{k}$ denote the number of unordered vertex pairs $\{i,j\}$ such that there are exactly $k$ edges between these vertices.

\item For $\alpha<1$ we have 
    \begin{align*}
\mathbb{E}\big[\tau_N^{nh}[T_\pi]\big] \sim
\begin{cases}
0, & \parbox[t]{0.6\textwidth}{\setstretch{0.9}\raggedright
$T_\pi$ contains any edge of multiplicity one (in any direction) or any vertex with a single loop (or both),}\\[0.6em]
O(N^{|V|-1-\alpha \mathfrak{p}}), & \text{otherwise,}
\end{cases}
\end{align*}
where $|V|$ is the number of vertices of $T_\pi$, and $\mathfrak{p}$ is the number of edges of the graph obtained by forgetting the multiplicity and orientation of the edges of the graph $T_\pi$.
\end{enumerate}

