[Proposition prop:equivalence_nonlinear_mp_weak_sol of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] Let $\nu\in\mathcal{P}(\mathbb{R}^d)$, and let $\mathbb{P}_{\nu}$ be a probability measure on $(C_{\infty}, \mathcal{B} )$, such that
\begin{equation}
\big[(t,x)\mapsto {\bf b}(t,x,{\boldsymbol\mu}_t)\big], \ \big[ (t,x)\mapsto {\boldsymbol\sigma} {\boldsymbol\sigma}^\top(t,x,{\boldsymbol\mu}_t)\big] \in L^{1}_{\text{loc}}([0,\infty) \times \mathbb{R}^d , \overline{\boldsymbol\mu}), 
\end{equation}

with ${\boldsymbol\mu}_t:= \mathbb{P}_{\nu}(x_t \in d y)$ and $\overline{\boldsymbol\mu}$ as in Notation (not:measure_dt_dx of the paper). 

Then $\mathbb{P}_{\nu}$ is a solution to NL-MP$({\bf b},{\boldsymbol\sigma};\nu)$ if and only if there exists a (weak) solution $X$ to MKV$({\bf b},{\boldsymbol\sigma};\nu)$ such that $[X] =\mathbb{P}_{\nu} $.

[Lemma 103 of arXiv:2601.16377, '2601.16377'] Take two variational data satisfying Assumptions~\ref{Assumption_A_prime} and \ref{Assumption_B}, differing by their matrices of interactions $\boldsymbol{\Theta}^{\textnormal{I}}$ and $\boldsymbol{\Theta}^{\textnormal{II}}$, by their segment endpoints $(\hat{a}_{h}^{\prime\,\textnormal{I}},\hat{b}_{h}^{\prime\,\textnormal{I}})_{h=1}^{H}$ and $(\hat{a}_{h}^{\prime\,\textnormal{II}},\hat{b}_{h}^{\prime\,\textnormal{II}})_{h=1}^H$, by their potentials $(V^{\textnormal{I}}_h)_{h=1}^H$ and $(V^{\textnormal{II}}_h)_{h=1}^H$, by the right-hand sides $(r_e^{\textnormal{I}})_{e=1}^{\mathfrak{e}}$ and $(r_e^{\textnormal{II}})_{e=1}^{\mathfrak{e}}$ of the affine constraints \eqref{eq_equations_eqs}. There exists $M > 0$ depending only on the constants in the assumptions, such that for any measurable function $f$ with finite $|\!|f|\!|_{\frac{1}{2}}$ and $|\!|f|\!|_{\infty}$ we have
\begin{equation}

 \begin{split}
&  \bigg| \int_{\amsmathbb R} f(x)\dd(\mu^{\textnormal{I}}-\mu^{\textnormal{II}})(x)\bigg| \leq M \cdot \big(|\!|f|\!|_{\frac{1}{2}}+|\!|f|\!|_{\infty}\big)  \\
& \quad \times \Biggl[ \sum_{e=1}^{\mathfrak e} \bigl|r_e^{\textnormal{I}}-r_e^{\textnormal{II}}\bigr| + \sum_{g,h=1}^H \bigl|\theta^{\textnormal{I}}_{g,h}- \theta^{\textnormal{II}}_{g,h}\bigr| + \sum_{h=1}^H \Big(\bigl|\hat{a}_{h}^{\prime\,\textnormal{I}}-\hat{a}_{h}^{\prime\,\textnormal{II}}\bigr|+ \bigl|\hat{b}_{h}^{\prime\,\textnormal{I}}-\hat{b}_{h}^{\prime\,\textnormal{II}}\bigr| + \sup_{x} \bigl|V_h^{\textnormal{I}}(x) - V_{h}^{\textnormal{II}}(x)\bigr|\Big)\Biggr]^{\frac{1}{2}},
 \end{split}
 \end{equation}
 where the supremum ranges over $x \in [\max(\hat{a}_{h}^{\prime\,\textnormal{I}},\hat{a}_{h}^{\prime\,\textnormal{II}}),\min(\hat{b}_{h}^{\prime\,\textnormal{I}},\hat{b}_{h}^{\prime\,\textnormal{II}})]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:local_hajek of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] As in (equation eq:hatngrhovdef of the paper), let us write
\begin{equation}
    \widehat{\mathsf{N}}_G^{\rho \to v}(x) = \mathsf{N}_G^{\rho \to v}(x) - \mathsf{d}_\rho p^{\mathsf{e}-1} n^{\mathsf{v}-2} \mathsf{deg}_v(x).
\end{equation}
Then for all $\zeta \in (0,\frac{3}{4})$, there is some $c > 0$ such that
\begin{equation}
    \mathbb{P} \mleft[ \mleft| \widehat{\mathsf{N}}_G^{\rho \to v}(X) - \mathbb{E} \mleft[ \widehat{\mathsf{N}}_G^{\rho \to v}(X) \mright]\mright| > n^{\mathsf{v}-1.75+\zeta} \mright]
    \leq \Exp{-c n^{\frac{4}{3} \zeta}}.
\end{equation}
In particular, for all $\xi > 0$ we have
\begin{equation}
    \operatorname{Var} \mleft[
        \widehat{\mathsf{N}}_G^{\rho \to v}(x)
    \mright] \lesssim n^{2\mathsf{v} - 3.5 + \xi}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Dfn 36 (Laplace benchmark) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] The standard Laplace variable $\Lap$ has density
\begin{align*}
    \frac{1}{2}e^{-|x|}, \qquad x \in \R,
\end{align*}
and satisfies
\begin{align*}
&&
    \E[\Lap] &= 0, &
    \E[|\Lap|] &= 1, &
    \E\left[e^{\lambda \Lap}\right] &= \frac{1}{1 - \lambda^2}
    \quad (|\lambda| < 1). &
&\end{align*}

[Lemma lem:largest-fragment-collision-proof of arXiv:2608.18320, 'Asymptotics for Beta-Splitting Trees via Homogeneous Fragmentations and Meromorphic Potent'] For every fixed $x\in\mathbb R$, put
    \begin{equation}
            t_n(x):=\frac{2\log n+x}{r_\beta}.
    \end{equation}
    Then
    \begin{equation}
            nP_*(t_n(x))\longrightarrow0,
            \qquad\text{in probability}.
    \end{equation}

[Corollary 11 of arXiv:2607.13273, 'Asymptotics of transition densities for L\'evy processes with stochastic resetting'] If $\frac{t}{|y|^{\alpha/2}}<M$ for some $M>0$, then
    \begin{equation}
        p(t,y)\sim \left(\frac{m^{1/\alpha}}{2\pi}\right)^{\frac{d-1}{2}} e^{mt-m^{1/\alpha}|y|} |y|^{-\frac{d+1}{2}}\eta\left(\dfrac{t}{|y|^{\alpha/2}}\sqrt{2^\alpha m},1\right).
    \end{equation}

