            &\lim_{n\rightarrow\infty} \int_0^T \left\langle I_n \psi(r), \1_{\widetilde u_n(r) > 0} \Sigma_n (\widetilde u_n(r)) \right\rangle \mathrm d r = \int_0^T \left\langle \psi(r), \1_{\widetilde u(r) > 0} \Sigma(\widetilde u(r)) \right\rangle\mathrm d r.
        \end{aligned}
    \]

