[Lemma Malianx of arXiv:2411.06131, 'Non-Markovian dynamics: the memory-dependent probability density evolution equations'] If $ A_t, B_t $ and $ C_t $ are measurable and essentially bounded deterministic functions in $ t $, then, Eq. ((mSDEline of the paper)) admits a unique solution. Moreover, let $X_t$ be the solution of ((mSDEline of the paper)), then
	\begin{equation}
	D^{\phi}_tX_t= X_t\int_{0}^{t}\phi(t,s)C_s\mathrm{d}s, \, \forall t\in[0,T], \, a.s.
	\end{equation}

[Lemma 28 of arXiv:2512.04807, 'Existence and uniqueness of the canonical Brownian motion in non-simple conformal loop ens'] Suppose that $\rform{\cdot}{\cdot}{\Gamma}$ is a weak \clekp{} resistance form. Then almost surely the following holds. Let $V \in \metregions$ and $V_1,\ldots,V_n \in \metregions$, $n \in \N$, such that $V_i \cap V_j = \emptyset$ for $i \neq j$ and $\bigcup_i \ol{V_i} \cap \Upsilon_\Gamma = \ol{V} \cap \Upsilon_\Gamma$. Then
 \begin{align*}
  \rfdomainres{V}{\Gamma} &= \{ f : f|_{V_i} \in \rfdomainres{V_i}{\Gamma} \text{ for each } i \} ,\\
  \text{and}\quad
  \rformres{V}{f}{f}{\Gamma} &= \sum_i \rformres{V_i}{f}{f}{\Gamma} .
 \end{align*}

[Definition 45 (Property~\ref{prop:digits}: Matching digits) of arXiv:2603.28734, 'Free energy analyticity of the disordered XY model and Debye screening in the 2D Coulomb g'] Consider fixed constants $\epsilon\in[0,1]$ and $k\in\Z_{\geq 0}$.
    We say that a Glauber dynamic $R$ \emph{matches digits up to $(\epsilon,k)$}
    if we may find an event $M\subset\Sigma$ of $\diff\iota$-probability at least $1-\epsilon$ such that:
    \begin{itemize}
        \item For any $u\in V$ and $\iota\in M$, we have
        \[
            \big\{
                \{R_{u,\iota}(\tau)_{1,u}\}_k=\{R_{u,\iota}(\tau')_{1,u}\}_k \text{ for all $\tau,\tau'\in \Pi_G$}
            \big\}
        \]
        \item For any $u\in V$ and $\tau\in\Pi_G$,
        the event $M$ and the random variable $\lfloor R_{u,\iota}(\tau)_{1,u}\rfloor_k$
        are $\diff\iota$-independent.
    \end{itemize}
    The event $M$ is called the \emph{matching event}.

[Corollary 41 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $\mu$ be an even, log-concave probability measure on $\R$ with density. 

For any pair of measurable functions $f, g:\R \to [0,\infty)$ and any non-decreasing measurable function $W: \R_+ \to (0, \infty)$ satisfying the pointwise relation
\begin{equation}

f(x)^{\frac{1}{2}} g(y)^{\frac{1}{2}} \leq W\left(\frac{|x-y|}{2}\right) \quad \text{for all } x, y \in \R,
\end{equation}
one has the functional inequality
\begin{equation}

\left( \int_{\R} f(x) \, d\mu(x) \right)^{\frac{1}{2}} \left( \int_{\R} g(y) \, d\mu(y) \right)^{\frac{1}{2}} \leq  \int_{\R} W(|r|) \,d\mu(r).
\end{equation}

[Theorem 1 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Fix $T > 0$. Let $h_\eps$ denote the BPHZ solution of the KPZ equation with initial data $\psi \in C^\vartheta(\mathbb{T})$ for $\vartheta \in (0,1/2)$ driven by $\xi_\eps = \xi \ast \rho^\eps$ where $\xi$ is space-time white noise and $\rho$ is a non-negative symmetric standard mollifier. Then for any $\kappa > 0$
	\begin{align*}
		\limsup_{M \to \infty} \sup_{\eps > 0} \mathbb{P} ( \eps^{-1/2} \| h_\eps - h \|_{C^{-\kappa}([0,T] \times \mathbb{T})} > M) = 0.
	\end{align*}
	Furthermore, the rate $\eps^{1/2}$ implied by the above statement is sharp since, writing $w_\eps = \eps^{-1/2} (h_\eps - h)$, we have that $(h_\eps, h, w_\eps)$ converges in law in $C^{1/2-\kappa}((0,T] \times \mathbb{T}) \times C^{1/2-\kappa}((0,T] \times \mathbb{T}) \times C^{-\kappa}((0,T] \times \mathbb{T})$ to $(h, h, w)$ where $w$ is the BPHZ solution of
	\begin{align*}
		(\partial_t - \partial_x^2) w = 2 \partial_x w \partial_x h +  c_1 \tilde{\xi}_1+c_2\tilde{\xi}_2
	\end{align*}
	with initial data $0$ where $c_1$, $c_2$ are strictly positive constants and $\tilde{\xi}_1$, $\tilde{\xi}_2$ are partially correlated\footnote{the precise covariance matrix is provided in Proposition~\ref{prop:new_noise_conv} below} space-time white noises  independent from $\xi$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $W$ be a Wigner matrix satisfying Assumption~\ref{ass:momass}. Fix a (small) $\varepsilon>0$ and a (large) $C>0$. For any fixed $p,n,S\in\N$ it holds that 
\begin{equation}
\Psi^{(p)}(n,S) \lesssim  N^{-(p-2)/2+\xi} \left( N^{-1} + \bm{1}_{n\ge p} N^{(n-p)/2}\right),

\end{equation}
for any fixed $\xi>0$, uniformly in $z\in\mathcal{D}_g(\varepsilon,C)$, which is defined in~\eqref{eq:def_D_global}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2604.04747, 'Scaling limit and density conjecture for activated random walk on the complete graph'] \thlabel{lem:max-tail}
    For $x=x_n$ and $T=T_n$ satisfying  $x = \Omega(\sqrt{\log n})$, $x = o(n^{1/6})$, and $\log n \ll T \ll 1/\mu_x$, 
    \begin{equation*}
        \mathbf{P}(m(T) \ge x) \sim \mu_x \,T.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:fourthcumu2 of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] In the setting of (lemma_G_large_2 of the paper), let $B$ be an arbitrary deterministic matrix with $\|B\|\le 1$. Then, we have that
    \begin{equation}
    \begin{aligned}
    \mathbb{E} \langle(G_1 - M_1)B\rangle 
    =&~\frac{\kappa^{(2,2)}  \langle \mathrm{diag}(M_1)^2 \rangle }{N}\left[ \langle M_1BM_1\mathrm{diag}(M_1)\rangle   +   \frac{ \langle M_1^2 \mathrm{diag}(M_1)\rangle}{1-\langle M_1^2\rangle } \langle M_1^2B\rangle\right]\\
    &~ + \mathrm{O}_\prec\qa{\pa{\frac{1}{\im m (z) }\wedge N^{\varepsilon_g}}\cdot{\pa{ N^{-3/2}\eta^{-1}+N^{-2}\eta^{-2}}}}.
    \end{aligned}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2606.04950, 'The Tricomi equation in the hyperbolic half plane under additive space-time Gaussian White'] Problem \eqref{1bis} admits a unique solution, in the above mild random-field sense, which is a Gaussian random field with representation
\begin{align}
U(t,x)=\sum_{m,n\geq 1}u_{mn}(t,x)\mathtt{z}_{mn},\quad t\geq 0,x\in\mathbb{R},
\end{align}
where
\begin{align*}
u_{mn}(t,x):=\frac{(-i)^n}{2\pi}\int_{\mathbb{R}}\int_{0}^te^{ix\xi}C(t,s,|\xi|)\psi_m(s)\varphi_n(\xi)dsd\xi.
\end{align*}
Here, for \(\rho>0\),
\begin{align}
C(t,s,\rho):= -\frac{\pi}{\rho^{2/3}}\!
\left[ \mathrm{Bi}(-\rho^{2/3}t)\,\mathrm{Ai}(-\rho^{2/3}s)
- \mathrm{Ai}(-\rho^{2/3}t)\,\mathrm{Bi}(-\rho^{2/3}s)\right],\quad s,t\geq 0, 
\end{align}
and \(C(t,s,0):=t-s\). The functions $\mathrm{Ai}$ and $\mathrm{Bi}$ are the Airy functions. The series in \eqref{solution series} converges in $\mathbb{L}^2(\Omega,\mathcal{F},\mathbb{P})$ and almost surely. Furthermore,
\begin{align}
\mathbb{E}[|U(t,x)|^2]&=\frac{1}{2\pi^2}\int_0^{+\infty}\int_0^{t}\left|C(t,s,\rho)\right|^2ds d\rho<+\infty,\quad t\geq 0,x\in\mathbb{R}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

