[Thmintro ET of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Let $\mathcal{F}$ be a $C^0$-foliation on $M$ transverse to $\partial M$.
    \begin{enumerate}
        \item (Coarse version) Assume that $(M,\mathcal{F})$ is not homeomorphic to either of the following:
        \begin{itemize}
            \item $S^1 \times D^2$ with the standard foliation by disks,
            \item $\mathbb{T}^2\times I$ with a foliation semi-conjugate to an irrational foliation.
        \end{itemize}
        Then for every $\varepsilon > 0$, there exists a positive (resp.~negative) contact structure $\xi$  which is $\varepsilon$-close to $T\mathcal{F}$ in the $C^0$ topology, and whose boundary foliation dominates a foliation $\mathcal{G} = \mathcal{G}_\varepsilon$ on $\partial M$ which is monotone equivalent to $\partial \mathcal{F}$.
        \item (Fine version) If moreover $\mathcal{F}$ has neither compact planar leaves nor $\mathbb{T}^2$-type planar minimal sets (\zcref{def:pems}), then $\mathcal{G}$ can be chosen isotopic to $\partial \mathcal{F}$ along $\partial M$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 54 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Fix constants $M,K$ satisfying \eqref{eq:costanti}. Define the sequence of real numbers $q_0, q_1, \ldots $ by, for each $i \ge 0$, setting $q_0 = \varepsilon_0$ and
\begin{flalign}

	q_{i+1}= q_i - \Delta_i, \qquad \text{where} \qquad \Delta_i = q_i^{1/3} N^{-2/3-M\delta}.	
\end{flalign}

\noindent We will always work with values of $i$ for which $q_i>0$.

[Definition 3 of arXiv:2605.03851, 'The Relay Random Tree:\\A stochastic geometry approach of multihop relay in an urban visib'] \textbf{Shade.}

Let $\landsc$ be a landscape, $(x_1, y_1)$ a point of $\Half$, and $(a, b)\in \landsc$ a building. We call the \textit{shade} of $(a, b)$ from $(x_1, y_1)$ the set of points right to $a$ that form a lower angle with $(x_1, y_1)$ than $(a, b)$ does:
\[S^{(x_1, y_1)}_{(a, b)} = \left\{ (x, y)\in \Half:x \geq a,\  \frac{y-y_1}{x-x_1}\leq \frac{b-y_1}{a-x_1}\right\}.\]

[Definition of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] We call an $ H $-valued, $ \mathbf{F} $-adapted, continuous stochastic process $ X(\cdot) $ a mild solution to (eqSEE of the paper) if   $F(\cdot, X(\cdot)) \in L^1(0, T ; H)$ a.s., $\widetilde{F}(\cdot, X(\cdot)) \in L_{\mathbb{F}}^{2}(0, T; H)$, and for any $t \in[0, T]$,
    \begin{align*}
    X(t)\!=\!S(t) X_0\!+\!\int_0^t\! S(t\!-\!s) F(s, X(s)) d s\!+\!\int_0^t\! S(t\!-\!s) \widetilde{F}(s, X(s)) d W(s),  \;\,  \text { a.s. }
    \end{align*}

[Lemma 19 of arXiv:2605.09372, 'Sharp weighted norm estimates for martingale square functions'] Let $1<r<p<\infty$. Given a scalar weight $w\in A_p$, we have
	\begin{equation*}
		\left\|\mathcal T_{w,r}f\right\|_{L_p(\Omega)} \lesssim_{p,d}[w]_{A_p}^{\max\{\frac1r ,\frac1{p-1}\}} \|f\|_{L_p(\Omega)},\quad\forall f\in L_p(\Omega).
	\end{equation*}

[Lemma of arXiv:2609.03959, 'The combinatorial Hopf algebra of signed graphs'] Given a graph $G = (V,E)$

\begin{equation}
    w_G(x,t) = \sum_{\kappa: V \rightarrow [t]}x^{rk(I(\kappa))}.
\end{equation}

[Define 8 of arXiv:2506.10522, 'On the Law of the Iterated Logarithm for $m$-dependent stationary random variables under s'] Another countably sub-additive capacity generated by $\mbE$ can be defined as follows:
 \begin{equation} \tildeCapc(A)=\inf\Big\{\lim_{n\to\infty}\mbE[\sum_{i=1}^n g_i]: I_A\le \sum_{n=1}^{\infty}g_n, 0\le g_n\in\mathcal{H}\Big\},\;\;\; A\in\mathcal F.
\end{equation}

[Proposition lem:A of arXiv:2609.01776, 'On the Cuspidal Cohomology of Iwahori Congruence Subgroups of $\mathrm{SL}(3, \mathbb{Z})$'] Let $p$ be a rational prime and let $e_1, e_2, e_3$ be the standard basis of column vectors in $\mathbb{Q}^3$.  A set of representatives of $\mathcal{I}(3, p)$-orbits of maximal proper parabolic $\mathbb{Q}$-subgroups of $\mathrm{SL}(3)$ is given by
    \begin{align*}
        P_1 = \mathrm{Stab}\langle e_1 \rangle, && P_1^T  = \mathrm{Stab}\langle e_2, e_3 \rangle, \\
        P_2 = \mathrm{Stab}\langle e_2 \rangle, && P_2^T = \mathrm{Stab}\langle e_1, e_3 \rangle, \\
        P_3 = \mathrm{Stab}\langle e_3 \rangle, && P_3^T = \mathrm{Stab}\langle e_1, e_2 \rangle. 
    \end{align*}
    Moreover, a set of representatives of $\mathcal{I}(3, p)$-orbits of minimal parabolic $\mathbb{Q}$-subgroups of $\mathrm{SL}(3)$ is given by
    \begin{align*}
        P_1 \cap P_2^T, && P_1 \cap P_3^T, \\ 
        P_2 \cap P_3^T, && P_2 \cap P_1^T, \\
        P_3 \cap P_1^T, && P_3 \cap P_2^T.
    \end{align*}

[Definition 7 (Definition 4.1 of \cite{Chen2024}, with the omitted $\lambda^2S_{2424}$ term restored; cf.\ Definition 4.1 of \cite{Brendle2019}) of arXiv:2608.26598, 'Pinching cones for positive isotropic curvature in dimensions seven and eight'] Assume $0<b\le\tilde b_{max,2}$ and let $a=b+\frac{n-2}{2}b^2$. We denote by
        $\tilde{\mathcal{E}}(b)$ the set of all $S\in\CB(\mathbb{R}^n)$ such that
        $l_{a,b}(S)\in C(b_{max,2})$ and
        \begin{equation}
            Z:=S_{1313}+\lambda^2S_{1414}+S_{2323}+\lambda^2S_{2424}-2\lambda S_{1234}
            +\sqrt{2a}(1-\lambda^2)\bigl(\Ric(S)_{11}+\Ric(S)_{22}\bigr)\geq 0
        \end{equation}
        for every orthonormal four-frame $\{e_1,e_2,e_3,e_4\}$ and every $\lambda\in[0,1]$. We then
        define $\tilde C(b)=l_{a,b}(\tilde{\mathcal{E}}(b))$.

