body:
[Thm of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] Under the same assumption of Theorem (windingangletheorem of the paper). If $\theta$ is piecewise $C^1$ on $[0,T]$ and $\theta_T-\theta_0\in(4k\pi+\pi,4k\pi+3\pi)$ for some integer $k$, then $\gamma$ has finite radius of convergence for its logarithmic signature.
\begin{proof}
It is implied by Corollary (ODEequivalence of the paper), Remark (piecewiseC2path of the paper) and the calculation in (equation signcalculation of the paper). Actually, we have 
\begin{equation*}
\begin{aligned}
&\int_l^{l+\pi}\rho_T^\lambda\cos(\varphi_T^\lambda-\zeta)d\zeta\\
\to&~e^{\lambda T}\prod_{k=1}^{n-1}\cos\left(\frac{\theta_{T_k+}-\theta_{T_k-}}{2}\right)\int_l^{l+\pi}\cos\left(\zeta-\frac{\theta_0}{2}\right)\cos\left(\zeta-\frac{\theta_T}{2}\right)d\zeta\\
=&\frac{e^{\lambda T}\pi}{2}\prod_{k=1}^{n-1}\cos\left(\frac{\theta_{T_k+}-\theta_{T_k-}}{2}\right)\cos\left(\frac{\theta_T-\theta_0}{2}\right).
\end{aligned}
\end{equation*}
W.L.O.G. we can assume the all the intersection angles $|\theta_{T_k+}-\theta_{T_k-}|<\pi$ for any $k$. Actually, we have to assume this to make the ODE system consistent on each piece $\gamma|_{[T_k,T_{k+1}]}$, otherwise the condition has to change. Because $\prod_{k=1}^{n-1}\cos\left(\frac{\theta_{T_k+}-\theta_{T_k-}}{2}\right)>0$, it follows that
$$
\int_l^{l+\pi}\rho_T^\lambda\cos(\varphi_T^\lambda-\zeta)d\zeta\to-\infty~~~\Longleftrightarrow~~~\cos\left(\frac{\theta_T-\theta_0}{2}\right)<0,
$$
which finishes the proof.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem L1 of arXiv:2609.01350, 'New classes of trace-form permutation polynomials and their compositional inverses'] Let $a, b \in \mathbb F_{2^n}$ , $b \neq 0$ and $f(x) = x^3 + ax + b, g(y) = y^2 + by + a^3$. Let $y_1$, $y_2$ be two roots of $g(y)$. The factorizations of $f(x)$ are characterized as follows:
\begin{enumerate}
\item $f = (1, 1, 1)$ if and only if ${\rm Tr}_2^{2^n} \left( \frac{a^3}{b^2} \right) = {\rm Tr}_{2}^{2^n}(1)$, and $y_1, y_2$ are cubes in $\mathbb F_{2^n}$ (resp. $\mathbb F_{2^{2n}}$) if $n$ is even (resp. odd);
\item $f = (1, 2)$ if and only if ${\rm Tr}_2^{2^n} \left( \frac{a^3}{b^2} \right) \neq {\rm Tr}_2^{2^n}(1)$;
\item $f = (3)$ if and only if ${\rm Tr}_2^{2^n} \left( \frac{a^3}{b^2} \right) = {\rm Tr}_2^{2^n}(1)$, and $y_1, y_2$ are not cubes in $\mathbb F_{2^n}$ (resp. $\mathbb F_{2^{2n}}$) if $n$ is even (resp. odd).
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Pro 12 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let \( \Omega \subset \R^n \) be an open convex subset and $\phi\in\text{\rm SCL}\,(\Omega)$. Then
	\begin{align*}
		\reg(\phi)=\big\{x\in\Omega:\partial_P \phi(x)\neq\varnothing\big\},\qquad \cut(\phi)=\big\{x\in\Omega:\partial_P \phi(x)=\varnothing\big\}.
	\end{align*}
	Moreover, for any $x\in\reg(\phi)$, $\phi$ is differentiable at $x$ and $\partial_P \phi(x)=\{D\phi(x)\}$.

[Definition def:indicators of arXiv:2607.22291, 'Rare subtree patterns in size-conditioned Bienaymé trees: Poisson approximation and declum'] Let $G$ be a $ \{0,1\}$-valued function defined on the set of all finite plane trees. 
For every  sequence $\mathbf{x}=(x_1, \ldots, x_n) \in \mathbb{Z}_{\geq -1} ^{n}$ and for every $M \in \mathbb{N} \cup \{\infty\}$ we define $I_1^{(M)}$ as follows:
\begin{enumerate}
\item[--] if $\zeta(\mathbf{x})=\infty$ or $\zeta(\mathbf{x})>M$, set $I_1^{(M)}(\mathbf{x}) = 0$;
\item[--] if  $\zeta(\mathbf{x}) \leq M$ set $I_1^{(M)}(\mathbf{x})=G(T(\mathbf{x}_{1}, \ldots,\mathbf{x}_{\zeta(\mathbf{x})}))$.
\end{enumerate}
Then, for every $1 \leq i \leq  n$, define $I_i^{(M)}(\mathbf{x}) =I^{(M)}_{1}(x_i, x_{i+1}, \ldots, x_n, x_1, \ldots, x_{i-1})$.

[Definition 15 of arXiv:2606.07096, 'Non-Selection of Lagrangian Trajectories in the Zero-Noise Limit for a Class of Stochastic'] Let $W$ satisfy Assumption~\ref{ass:noise} and let $u \in L^q([0,1]; C^\alpha(\T^d))$ with $(q,\alpha)$ satisfying the condition~\eqref{eq:condition_SWP_time_integrable} from Remark~\ref{rem:regbynoise_time_integrability} (so that $X^\kappa$ is well-defined for any $\kappa>0$); let $\eps\in (0,1)$.
    We say that $u$ has the \emph{$(1-\eps)$-non-selection property} if there exists $ A \subset \T^d$ with $| A| \geq 1 - \eps $ and a constant $c_\eps >0$ such that:
\begin{itemize}
    \item  there exists a sequence $\{ \kappa_q \}_{q}$ such that
    \begin{equation*}
        \P\left(  \omega\in \Omega: \liminf_{q\to\infty} \dist ( X_1^{\kappa_{2q}}( x, \omega), X_1^{\kappa_{2q+1}}( x, \omega))\geq c_\eps> 0\,, \text{ for a.e. } x \in A\right) =1\,,
    \end{equation*}
    \item for any $x \in  A$, there exist a subsequence $\{\kappa_{q'}\}_{q'}$ and points $y, y' \in \T^d$ such that
    $$ X_1^{\kappa_{2q'}} ( x,  \omega) \rightarrow y \neq y' \leftarrow X_1^{\kappa_{2q'+1}} ( x, \omega).\quad \text{for $\P$-a.e. } \omega\in\Omega.$$
\end{itemize}

[Definition def:sol_gen_SDE of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] Let $s\in [0,T)$. A (general) solution to SDE$(b,\sigma;s)$ is a 
triple $( (\mathcal{F}_t)_{t},W, X)$, where: 
\begin{itemize}
\item[(i)] $(\mathcal{F}_t)_{t\in [s,T)}$ is a filtration on a probability space $(\Omega , \mathcal{F}, \mathbb{P})$, satisfying the usual assumptions of completeness and continuity from the right;
\item[(ii)] $W=(W_t)_{t\in [s,T)}$ is a $q$-dimensional (uncorrelated) Brownian motion (starting at $s$) with respect to $(\mathcal{F}_t)_{t\in [s,T)}$;
\item[(iii)] $X=(X_t)_{t\in [s,T)}$ is an $\mathbb{R}^d$-valued process, adapted to  $(\mathcal{F}_t)_{t\in [s,T)}$, such that: 
\begin{itemize}

\item the processes $(b(t,X_t))_{t\in [s,T)}$ and  $(\sigma(t,X_t))_{t\in [s,T)}$ are progressively measurable and such that 
\begin{equation}
\int_s^t |b(r,X_r)| dr + \int_s^t \big|\sigma\sigma^\top(r,X_r)\big| dr  <\infty, \qquad \mathbb{P}\text{-almost surely.}
\end{equation}

\item 
the following representation holds $\mathbb{P}$-almost surely:
\begin{equation}
X_t = X_s + \int_s^t b(r,X_r) dr + \int_s^t \sigma(r,X_r) dW_r ,\qquad t\in [s,T).
\end{equation}
\end{itemize} 
\end{itemize}

