[Proposition 6 (Gauss divisible case) of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Assume the set-up \eqref{eq:OU_flow}--\eqref{eq:char_flow} and denote $X_t:=N\eta_t\langle G_t-m_t\rangle$ for $t\in [0,T]$. For any fixed $p,q\in\N\cup\{0\}$ with $p+q\ge 3$ it holds that
\begin{equation}
\kappa_{p,q}\left(X_t\right) = \frac{\eta_t^{p+q}}{N^{(p+q-2)/2}}K_{p,q}(z_t)\kappa_{p+q}^{\mathrm{d}}(t) + \frac{N^\xi}{N\eta_t} \mathcal{O}\left( \frac{1}{N^{(p+q-3)/2}}+ \frac{1}{(N\eta_t)^{p+q-3}}\right),

\end{equation}
for any fixed $\xi>0$, uniformly in $t\in [0,T]$ and $z=z_T\in\mathcal{D}$. Here $\kappa^\dif_{p+q}(t):=\kappa_{p+q}\left(N^{1/2} (W_t)_{11}\right)$ and $K_{p,q}$ is defined in \eqref{eq:def_K}. We further have
\begin{equation}
\kappa_{p,0}\left(N\eta_t\langle G_t-m_t\rangle\right) = \frac{\eta_t^p}{N^{(p-2)/2}}\left(K_{p,0}(z_t)\kappa_p^{\mathrm{d}}(t) + \mathcal{O}\left(\frac{1}{N^{1/2}}\right)\right),

\end{equation}
for any fixed $p\in\N$, $p\ge 3$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: a prioiri of arXiv:2411.04157, 'Stochastic homogenization of dynamical discrete optimal transport'] Suppose (equation path of the paper) and (equation degree of the paper) in Assumption (ass: graph of the paper) hold. Let $\bar m^\varepsilon_0,\bar m^\varepsilon_1 \in {\mathcal P}({\mathcal X_{\varepsilon}})$. Then
\begin{equation}
    c(\lambda,\max_{x\in {\mathcal X_{\omega,\varepsilon}}}\deg(x)) W_1^2(\bar m^\varepsilon_0,\bar m^\varepsilon_1) \leq \min_{\substack{m^\varepsilon_0 = \bar m^\varepsilon_0,\\ m^\varepsilon_1 = \bar m^\varepsilon_1}}\mathcal{A}_{\varepsilon}(m^\varepsilon,J^\varepsilon)  \leq C(R,\Lambda)(W_2^2(\bar m^\varepsilon_0,\bar m^\varepsilon_1)+\varepsilon^2).
\end{equation}

[Lem 26 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $\chi$ and $\beta$ be as above. Then, under the assumptions of Theorem \ref{Théorème central}, we have
        \begin{equation}
        \begin{split}
            \log\det\Bigl(\widetilde{q}_N +\beta\chi\pr{\beta^{-1}\widetilde{q}_N}\Bigl) &= N^d\biggl(\int_{\T^{2d}}\log\Bigl(q(\rho)+\beta\chi(\beta^{-1}q(\rho))\Bigl)d\rho\\
            &\mm+\mc{O}\pr{N^{-\min(\varrho,{\kappa_1})\eta}}+\mc{O}\pr{\pr{N^{1-\eta}\alpha}^{-1}}\biggl).
        \end{split}
    \end{equation}

