[Theorem inv th2Pre of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] Let $h \in L_{\mathbb{F}}^2 (0, T ; H^1 (G^{\prime} ) )$ and $R \in C^{1,3}(\overline{Q})$ satisfy

\begin{align}
    |R(t, x)| \neq 0 \quad \text { for all }(t, x) \in[0, T] \times \overline{G}.
\end{align}

Assume that $ g= a_{3} y $, where $a_{3} \in L^{\infty}_{\mathbb{F}}(0,T; W^{2, \infty}(G))$.
If
\begin{align*}
    y \in L_{\mathbb{F}}^2 (0, T ; H^2(G) \cap H_0^1(G) )  \cap L_{\mathbb{F}}^2 (\Omega ; C ([0, T] ; H_0^1(G) ) )
\end{align*}
satisfies (system2bu of the paper) and
\begin{align*}
    & \frac{\partial y}{\partial \nu}=0 \quad \text { on }(0, T) \times \partial G, ~ \text{${\mathbb{P}}$-a.s.},
\end{align*}
then
\begin{align*}
h (t, x^{\prime} )=0 & \text { for all } (t, x^{\prime} ) \in(0, T) \times G^{\prime},~ \mbox{${\mathbb{P}}$-a.s.}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 of arXiv:2608.29585, '2608.29585'] Fix $n\ge2$.  For $0\le j\le k$,
\begin{equation}
 D_{k,j}^{(n)}
 =(-1)^{k-j}\{j\}!\{k-j\}!
 \frac{\{n+j+k\}!}
      {\{n+j-1\}!\{n+2j\}}.
\end{equation}
The displayed quotient is a Laurent polynomial.

[Proposition prop.H1TwoScale of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] There exists a finite positive constant $C(c_{-},c_{+},\mathbf{r},\rho)$ such that for every $\lambda\in(0,\tfrac{1}{2})$, the following estimates about the expectation and variance of the carr\'e du champ of $\widetilde{G}_\lambda$ hold:
		\begin{multline}
			\left|\mathbb{E}_\rho\left[\sum_{b\in(\mathbb{Z}^2)^*}\left(c_b(\pi_b\widetilde{G}_\lambda)^2\right)\left(\eta\right)\right]-2\expec{\overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}}\overline{G}_\lambda}\right|\\
			\leqslant C\sqrt{\log (\lambda^{-1})}(3^{-\alpha m}\sqrt{\log(\lambda^{-1})}+3^m),
		\end{multline}
		\begin{equation}
			\mathbb{V}\!\mathrm{ar}_\rho\left[\sum_{b\in(\mathbb{Z}^2)^*}\left(c_b(\pi_b\widetilde{G}_\lambda)^2\right)(\eta)\right]\leqslant C 3^{18m}\log(\lambda^{-1}).
		\end{equation}

