[Lemma 37 of arXiv:2603.28734, 'Free energy analyticity of the disordered XY model and Debye screening in the 2D Coulomb g'] Let $(t,x) \in L  \cdot (\Z_{\leq 0} \times \Z^d)$ such that $(t,x)$ is $(L  ,\delta)$-mixed. 
Then, the following statements are true:
\begin{itemize}
\item For any $r \in [-L  (t+1), -L  t]$, the distributions of $R^{\Lambda_{2n_L  }(v), -(t+1)n_L  , -r}(\alpha^\pm)|_{\Lambda_{n_L  }(x)}$ are given by the measure $\mu^{\SWM}_{\Lambda_{2n_L  }}(\cdot|_{\Lambda_{n_L  }(x)})$.
\item For any $r \in [-L  (t+1), -L  t]$, the random variables $R^{\Lambda_{2n_L  }(x), -(t+1)n_L  , -r}(\alpha^\pm)|_{\Lambda_{n_L  }(x)}$ are independent of the Poisson process on the set $(\Lambda_{2n_L  }(x) \times [-(t+1)n_L  , tL  ] )^c$. 
\end{itemize}

[Theorem 12 (Solution of Problem~\ref{fractional-problem}) of arXiv:2608.25164, 'A time-fractional Kalman filter'] Problem~\ref{fractional-problem} has a unique solution. First, $H$ is the
unique bounded deterministic solution of the following equation on the
triangular domain $0\leq s\leq t\leq T$:
\begin{align}
H(t,s)
=K_X(t,s)-\int_0^s\frac{G^2(r)}{D^2(r)}
H(t,r)H(s,r)dr.                                               
\end{align}
Define
\begin{align}
A(t,s)&=\frac{G^2(s)}{D^2(s)}H(t,s),
&
B(t,s)&=\frac{G(s)}{D^2(s)}H(t,s),                            
\end{align}
and the resolvent kernels
\begin{align}
Q_1(t,s)&=-A(t,s),\nonumber\\
Q_{n+1}(t,s)&=-\int_s^tA(t,r)Q_n(r,s)dr,\qquad n\geq1,         \\
Q_H(t,s)&=\sum_{n=1}^{\infty}Q_n(t,s).                        
\end{align}
Set
\begin{align}
m_H(t)
 &=m(t)+\int_0^tQ_H(t,s)m(s)ds,                               \\
L_H(t,u)
 &=B(t,u)+\int_u^tQ_H(t,s)B(s,u)ds.                           
\end{align}
Then the unique best estimate is
\begin{align}
\widehat X(t)=\E[X(t)\mid\mathcal Y_t]
=m_H(t)+\int_0^tL_H(t,u)dY(u).                             
\end{align}
Equivalently, it is the unique adapted solution of
\begin{align}
\widehat X(t)
=m(t)+\int_0^t\frac{G(s)}{D^2(s)}H(t,s)
\big[dY(s)-G(s)\widehat X(s)ds\big].                          
\end{align}
The minimum mean-square error is
\begin{align}
S(t)
=H(t,t)
=K_X(t,t)-\int_0^t\frac{G^2(r)}{D^2(r)}H^2(t,r)dr.             
\end{align}
Moreover,
\begin{align}
\widehat X(0)=m(0),\qquad
H(t,0)=K_X(t,0),\qquad
S(0)=K_X(0,0).                                                
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

