F_m(\omega(t)) \to F(\omega(t)),\, \forall t\in [0, T],\quad
\|\nabla^2 F_m -\nabla^2 F\|_{\mathcal{W}^{0}_{\omega, \pi}}\xrightarrow{m\to \infty} 0.
}
\eq{
\mathcal{W}^{2}_{\omega, \pi}:=\Big\{F\in W^{2,1}(\Rr^d)\colon\, \exists (F_m)_{m\geq 1}\  \text{\rm satisfying } \eqref{2eq:W2pomega}\Big\}.
}

