body:
[Corollary downright_path of arXiv:2608.07236, 'Negative association of Busemann functions \\in exponential last-passage percolation'] For every down-right path $\mathcal{Y} = \{\mathbf y_i\}_{i\in \mathbb{Z}}$, every choice of $\rho_1,\dots,\rho_n \in (0,1)$, and every $t_1,\dots,t_n \in \mathbb{R}$, we have
\begin{subequations} 
\begin{align} 
\mathbb{P}\Big(\bigcap_{i=1}^n \Big\{B^{\rho_{i}}_{\mathbf y_{i}, \mathbf y_{i+1}} > t_i\Big\}\Big) 
&\leq \prod_{i=1}^n\mathbb{P}\big( B^{\rho_{i}}_{\mathbf y_{i}, \mathbf y_{i+1}} > t_i\big) \\
\text{and} \quad 
\mathbb{P}\Big(\bigcap_{i=1}^n \Big\{B^{\rho_{i}}_{\mathbf y_{i}, \mathbf y_{i+1}} < t_i\Big\}\Big) 
&\leq \prod_{i=1}^n\mathbb{P}\big( B^{\rho_{i}}_{\mathbf y_{i}, \mathbf y_{i+1}} < t_i\big).
\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 of arXiv:2604.13454, 'Invariant and periodic measures in classical spin systems on infinite lattices with highly'] Let $k\in\mathbb{N}$, $x\in\ell^{2\theta}_{\rho}(\mathbb{Z}^+)$ and $T\geq0$ be given.  Then for all $\epsilon>0$, there exist $\delta>0$ and $V\in\mathbb{N}$ satisfying: whenever $n\geq V$ and $y\in\{z\in\ell^{2\theta}_{\rho}(\mathbb{Z}^+);\Vert z-x\Vert_{2,\rho}\leq\delta\}$, we have 
        \begin{equation*}
            \mathbb{E}\sup\limits_{t\in[0,T]}\Vert X_{(k)}^{(n),x}(t)-X_{(k)}^{(n),y}(t)\Vert_{\mathbb{R}^{\Lambda_k}}^2\leq \epsilon.
        \end{equation*}

