[Definition 1 (Lower-buffered quantile) of arXiv:2608.22227, '\fontsize{18pt}{20pt}\selectfont \bf Risk-Sensitive Reinforcement Learning with Smoothed Q'] For \(\beta\in(0,1)\) and \(q\in(0,1]\), define \(\ell_\beta(q)\coloneqq \min\{\beta,q\}.\) For a real-valued random variable \(X\), its lower-buffered \(q\)-quantile is $Q_q^\beta(X)\coloneqq\frac{1}{\ell_\beta(q)}
\int_{q-\ell_\beta(q)}^{q} Q_u(X)\,du$.
For the endpoint cases, we use the conventions \( Q_0^\beta(X) = \inf\operatorname{supp}(X)\) and \( Q_0^\beta(X) =\sup\operatorname{supp}(X)\).

[Lemma 14 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$, $D\subset \widetilde{\mathbb{Z}}^d$, $n\ge 10$ and $v,w\in \widetilde{\mathbb{Z}}^d\setminus D$ with $|v-w|\ge 2n$, 
 	\begin{equation}
 	\begin{split}
  		\mathbb{P}^D\big(v \xleftrightarrow{\ge 0} w \big) \lesssim  \big( \mathrm{dist}(v,D)\land 1 \big)^{\frac{1}{2}}  
  		\cdot |\partial\mathcal{B}_{{v}}(n)|^{-1}  \sum\nolimits_{z\in \partial\mathcal{B}_{{v}}(n)}  \mathbb{P}^D\big( z  \xleftrightarrow{\ge 0} w  \big).
  		 	\end{split}
 	\end{equation}

