body:
[Thm 5 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $0<\eta<1/4$ and $\varrho\in \hspace{0.1cm} ]0,1]$. Let $p\in \mathscr{C}^{0,\varrho}_{\mathrm{pw}}S_d$ and let $\mathscr{U}_p$ be given in \eqref{Ensemble des singularités}. We assume that there exist ${\kappa_2}\in \hspace{0.1cm} ]0,1]$ such that, for $0\leq t\ll 1$,
    \begin{equation*}
        \mathrm{Vol}\pr{\acc{\rho\in \T^{2d}\m|\m \bb{p(\rho)}^2\leq t}}=\mc{O}(t^{\kappa_2})
    \end{equation*}
    and ${\kappa_1}\in \hspace{0.1cm} ]0,1]$ such that for $0\leq t\ll 1$,
    \begin{equation*}
        \mathrm{L}\Bigl(\pr{\mathscr{U}_p+B(0,t)}\cap[0,1]^d\Bigl)=\mc{O}(t^{{\kappa_1}}).
    \end{equation*}
    Let $N\gg 1$ and $\alpha$ be such that
    \begin{equation*}
        N^{-\eta\min(\varrho,{\kappa_1})}\ll\alpha\ll 1.
    \end{equation*}
    Then, for all $\psi\in \mathscr{C}^\infty_c(\R)$,
    \begin{equation*}
       \mathrm{tr}\!\croch{\psi\pr{\frac{\widetilde{q}_{N}}{\alpha}}} =N^d\pr{\int_{\T^{2d}}\psi\pr{\frac{\bb{p(\rho)}^2}{\alpha}}d\rho+o(1)}.
    \end{equation*}
    If $\chi\in \mathscr{C}^\infty_c(\R,[0,+\infty[)$, such that $\chi(0)>0$ then,
    \begin{equation*}
        \begin{split}
            \log\det\pr{\widetilde{q}_N+\alpha\chi\pr{\frac{\widetilde{q}_N}{\alpha}}} &= N^d\biggl(\int_{\T^{2d}}\log\pr{\bb{p(\rho)}^2}d\rho+o(1)\biggl).
        \end{split}
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 3 of arXiv:2604.13454, 'Invariant and periodic measures in classical spin systems on infinite lattices with highly'] (weak martingale solutions). Given a probability measure $\mu$ on $\ell_\rho^{2\theta}(\mathbb{Z}^+)$, a weak martingale solution of equation (\ref{INFSDE2}) with initial condition $\mu$ is a triple $(\tilde{X},\tilde{W})$, $(\tilde{\Omega},\tilde{\mathscr{F}},\tilde{\mathbb{P}})$, $\{\tilde{\mathscr{F}}_t\}$, where
    \begin{itemize}
        \item[(i)] $(\tilde{\Omega},\tilde{\mathscr{F}},\tilde{\mathbb{P}})$ is a probability space, and $\{\tilde{\mathscr{F}}_t\}$ is a filtration of sub-$\sigma$-fields of $\tilde{\mathscr{F}}$ satisfying the usual conditions,
        \item[(ii)] $\tilde{W}=\{\tilde{W}(t),\tilde{\mathscr{F}_t};0\leq t\leq \infty\}$ is cylindrical Wiener process on $\ell^{2}(\mathbb{Z}^+)$, $\tilde{X}=\{\tilde{X}(t),\tilde{\mathscr{F}_t};0\leq t\leq \infty\}$ is an adapted process in $\ell_\rho^{2}(\mathbb{Z}^+)$ and 
        \begin{equation*}
             \tilde{X}(\cdot,\tilde{\omega})\in L^{\infty}(0,T;\ell_\rho^{2\theta}(\mathbb{Z}^+))\bigcap C([0,T];\ell_\rho^{2}(\mathbb{Z}^+)) \quad \tilde{\mathbb{P}}-a.s.
        \end{equation*}
        for every $T>0$,
        \item[(iii)] the integral version of (\ref{INFSDE2})
        \begin{equation*}
            \tilde{X}(t)=\tilde{X}(0)+\int_0^tA\tilde{X}(s)+F(\tilde{X}(s))ds+\int_0^tBd\tilde{W}(s), t\in [0,\infty),
        \end{equation*}
        holds $\tilde{\mathbb{P}}$ almost surely in $\ell_\rho^{2}(\mathbb{Z}^+)$,
        \item[(iv)] $\tilde{X}(0)$ has law $\mu$.
    \end{itemize}

[Prop 2 of arXiv:2604.02129, 'Realisation of constraints in underdamped Langevin dynamics'] Given $\eps>0$, let $(Q_t,P_t)$ be the solution of the spatially confined dynamics~\eqref{eq:abc-slow},\eqref{eq:intro-Spat-Cons-Fast} with corresponding initial datum $(Q^i_0,P^i_0)$ for $i=1,2$. 
    Let $(q_t,p_t)\in \R^{2(d-k)}$ with the same initial data $(q_0,p_0)=(Q^2_0,P^2_0)$ evolve according to~\eqref{eq:limit-gen} with $\hat q=0 \in \R^k$. Recall the definition of the potential $V$ from~\eqref{eq:Valpha} and the parameter $\alpha\geq 0$. 
    We have  
\begin{align}
  \mathbb{E} \biggl[\sup_{t\in[0,T]}  \biggl|\begin{pmatrix}
       q_t - Q^{2}_t \\ p_t-P^{2}_t  
    \end{pmatrix} \biggr|^2 \biggr] \leq
    \begin{cases}
    C_3 e^{C_4 T} \Bigl(
          T \bigl|Q_0^{1}\bigr|^2 + \eps T \bigl|P_0^{1}\bigr|^2 + \eps T^2 \Bigr) \ \  &\text{if $\alpha=0$}\\
     C_5 \left( \eps T + |Q^1_0|^2 + \eps |P^1_0|^2 \right) &\text{if $\alpha>0$}. 
    \end{cases}      
\end{align}
For $\alpha>0$ (i.e. $V$ has a quadratic part) we additionally have the uniform-in-time ($L^1$-)estimate 
\begin{align}
\mathbb{E} \biggl[\sup_{t \geq 0}  \biggl|\begin{pmatrix}
       q_t - Q^{2}_t \\ p_t-P^{2}_t  
    \end{pmatrix} \biggr| \biggr] &\leq
    C_6  \Bigl(\sqrt{\eps} + \sqrt{\eps}  \bigl|P_0^{1}\bigr|  +\bigl|Q_0^{1}\bigr|\Bigr).
    \end{align}
The constants $C_3,C_4, C_5, C_6>0$ above are independent of $\eps$ and $T$. (Proof in the paper; no proof environment follows the statement in the TeX.)

