body:
[Pro 13 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let \( \Omega \subset \R^n \) be an open convex subset and $\phi\in\text{\rm SCL}\,(\Omega)$. For any $x\in\Omega$, the following statements are equivalent.
	\begin{enumerate}[(i)]
		\item $x\in\reg(\phi)$.
		\item $\phi$ is differentiable at $x$, and there exists an open neighborhood \( V \) of \( x \) and $C>0$ such that
		\begin{equation}
			|\phi(y)-\phi(x)-D\phi(x)\cdot(y-x)|\leqslant \frac{C}{2}|y-x|^2,\quad \forall y\in V.
		\end{equation}
		\item $\phi$ is differentiable at $x$, and there exists an open neighborhood \( V \) of \( x \) and $\lambda>0$ such that
		\begin{align*}
			|p-D\phi(x)|\leqslant\lambda|y-x|,\quad \forall y\in V,\ p\in D^+\phi(y).
		\end{align*}
	\end{enumerate}

