[Lemma 17 of arXiv:2608.16752, 'Absorption Probabilities for Random Convex Hulls: Distribution-Freeness via the Wall-Cross'] Let $K\subset\R^{d}$ be a nonempty compact convex set and let $v\in \R^d$, $v\neq0$. Let $\pi$ be the orthogonal projection onto $v^{\perp}$. Then
\begin{equation}
    \mathbb{1}_{\{0\in\Conv(K\cup\{v\})\}}
   +\mathbb{1}_{\{0\in\Conv(K\cup\{-v\})\}}
   =\mathbb{1}_{\{0\in K\}}+\mathbb{1}_{\{0\in\pi K\}} .
\end{equation}
 If additionally $0\notin\partial K$ and $0\notin\partial_{v^{\perp}}(\pi K)$, where the latter boundary is taken in $v^{\perp}$, then
\begin{equation}
    \mathbb{1}_{\{0\in\Conv(K_{+}\cup\{v\})\}}
   +\mathbb{1}_{\{0\in\Conv(K_{-}\cup\{-v \})\}}
   =\mathbb{1}_{\{0\in K\}}+\mathbb{1}_{\{0\in\pi K\}},
\end{equation}
whenever $K_{+}$ and $K_{-}$ are nonempty compact convex sets in $\R^d$
whose Hausdorff distance to $K$ is smaller than $\eps$, where $\eps>0$ is a sufficiently small number  depending only on $K$ and $v/\|v\|$.

[Lemma L:ZPL of arXiv:2411.13257, '\titlefont \vspace{-5ex} Inference by Multiple Identical Observers'] For $F \in {{\mathcal F}_W}$ and $y \in {\mathcal Z}$, 
\begin{equation} 
 P_L( F \cap \{Z_S=y\}) 
  =  {\mathbb E} \Big(  \frac{ 1_F L_y}{X} \Big | X\ge 1 \Big), 
\end{equation}
and 
\begin{equation} 
  P_L( F | Z_S=y) 
  = \frac{ {\mathbb E}\big(  { 1_F L_y}{X^{-1}} \Big | X\ge 1 \big) }
      {  {\mathbb E}\big(  { L_y}{X^{-1}} \Big | X\ge 1  \big) }.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2606.13264, 'Interference Queueing Networks: A Replica Mean-Field Approach in the Symmetric Setting'] We say that $Q$ is associated if for any $f$ and $g$ increasing real function for the partial order on $\mathbb{N}^N$, and $t \in \mathbb{R}^+ $
    \begin{align}
        &\mathbb{P}^{Q(t)}(fg)\geq \mathbb{P}^{Q(t)}(f)\mathbb{P}^{Q(t)}(g) \Leftrightarrow \mathbb{E}[f(Q(t))g(Q(t))]\geq\mathbb{E}[f(Q(t))]\mathbb{E}[g(Q(t))]
    \end{align}

[Thm 15 of arXiv:2604.24189, 'Malliavin calculus and densities for chaos-driven stochastic differential equations'] Under the conditions of Theorem \ref{thm:MallDiff}, we have, for all $1 \leq k \leq d$ and $t\in (0,T]$
\begin{enumerate}[(a)]
	\item 	
	\begin{align}
		D X_t^k &=  \sum_{\ell=1}^{m} \int_{0}^{t} \Theta_{t}^{k l}(r) d DF^l(r)\nonumber\\
		&:=\lim_{|\mathcal{P}|\to 0}\sum_{\ell=1}^{m}\sum_{[u,v]\in \mathcal{P}} \Theta_{t}^{k l}(u) (DF^l(v)-DF^l(u)),
	\end{align}
	where $\Theta^{k,\ell}_t$ is given by \eqref{eq:Theta} and the above limit is in $\HHH$, along an arbitrary sequence of partitions of $[0,t]$ with mesh tending to zero.
	Furthermore, for any $\beta\in (0, H-\frac{1}{2})$ there exists a constant $C>0$ such that
	\begin{align}
		&\left\|\sum_{\ell=1}^{m} \int_{s}^{t} \Theta_{t}^{k l}(r) d DF^l(r)- \sum_{\ell=1}^{d}\Theta_{t}^{k l}(s)\big(DF^l(t)-D^{(l)}F(s)\big)\right\|_{\HHH}\\
		&\leq C \sum_{\ell=1}^{m}\|\Theta_{t}^{k l}\|_{\mathcal{C}^{H-\beta_1}} \|DF^l\|_{\mathcal{C}^{H-\beta_2}} |t-s|^{2(H-\beta)};\nonumber
	\end{align}	
	uniform in $s,t\in [0,T]$. 
	\item for all $h \in \mathfrak{H}$, 
	\begin{align}
		&\left<D X_t^k, h\right>_{\HHH} =  \sum_{\ell=1}^{m} \int_{0}^{t} \Theta_{t}^{k l}(s) d \left<DF^l(s), h\right>_{\HHH}\nonumber\\
		&:=\lim_{|\mathcal{P}|\to 0}\sum_{\ell=1}^{m}\sum_{[u,v]\in \mathcal{P}} \Theta_{t}^{k l}(u) \left<DF^l(v)-DF^l(u),h\right>_{\HHH},	
	\end{align}
	where the limit is along an arbitrary sequence of partitions of $[0,t]$ with mesh tending to zero.
\end{enumerate}

[Lemma 6 (Eichelsbacher and L\"{o}we \cite{eichelsbacher2010stein}) of arXiv:2506.17061, 'Non-uniform bounds for non-normal approximation via Stein's method with applications to th'] Let $z\in\R$ and let $P_k$, $f_z$ and $g_z$ be defined as above. The following statements hold.
		\begin{itemize}
			\item[(i)] For $x>0$, we have
			\begin{equation}
				1-P_k(x) \le \min \left(\frac{1}{2}, \frac{b_k}{2 k a_k x^{2 k-1}}\right) \exp \left(-a_k x^{2 k}\right),
			\end{equation}
and therefore, for $x<0$, we have
			\begin{equation}
				P_k(x)=1-P_k(-x) \le \min \left(\frac{1}{2}, \frac{b_k}{2 k a_k |x|^{2 k-1}}\right) \exp \left(-a_k x^{2 k}\right).
			\end{equation}
			\item[(ii)] The explicit formular for $f_z$ is
			\begin{equation}
				f_z(x) =
				\begin{cases}
					(1-P_k(z))P_k(x)\exp({a_kx^{2k}})b_k^{-1} &\text{if }\ x < z,\\
					P_k(z)(1-P_k(x))\exp({a_kx^{2k}})b_k^{-1} &\text{if }\ x \ge z.
				\end{cases} 
			\end{equation}
			\item[(iii)] The explicit formular for $f_{z}'$ is
			\begin{equation}
				f_{z}'(x) =
				\begin{cases}
					(1-P_k(z))\left[1 + 2ka_kx^{2k-1}P_k(x)\exp({a_kx^{2k}})b_k^{-1}\right] &\text{if }\ x < z,\\
					P_k(z)\left[(1-P_k(x))2ka_kx^{2k-1}\exp({a_kx^{2k}})b_k^{-1}-1\right] &\text{if }\ x \ge  z. 
				\end{cases} 
			\end{equation}
			\item[(iv)] 
			For all $x\in\R$, we have
			\begin{equation}
				0 < f_z(x) \le \dfrac{1}{2b_k}, \text{ and }
				|f_{z}'(x)| \le 1.
			\end{equation}
			\item[(v)] For $x< z$, we have
			\begin{equation*}
				g_z(x)=(1-P_k(z))\left[b_{k}^{-1}P_k(x)\exp(a_kx^{2k}) \left((4k^2-2k)a_kx^{2k-2} + 4k^2a_k^2x^{4k-2}\right) + 2ka_kx^{2k-1}\right].
			\end{equation*}
		\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defin 13 of arXiv:2609.00974, 'On Algebraic Integrability\\ of Vector Fields \\ with Rational Function Coefficients\\ tha'] We introduce a notation for an $n$-coefficients of an element.
\begin{enumerate}
    \item Let $k$ be a field. Let $K$ be $k[x]$, or $k((x))$ Laurent series. Let $n$ be an integer.
    Let $f\in K$ be given by $f=\ldots+a_{-1}x^{-1}+a_0+a_1x+a_2x^2+\ldots$, where $a_i\in k$. We define:
    \begin{equation}
        [x^{n}]f \coloneqq a_n \in k.
    \end{equation}
    \item Let $K$ be a generic point of a curve with a coordinate $x$, or $k((x))$.
    Then, $1,x,x^2,\ldots,x^{p-1}$ is a $p$-basis of $K$ over $K^p$.
    Let $n\in \{0,1,\ldots,p-1\}$. Let $f\in K$. It has a unique presentation of the form $f=a_0+a_1x+a_2x^2+\ldots+a_{p-1}x^{p-1}$, where $a_i\in K^p$. We define:
    \begin{equation}
        \widetilde{[x^{n}]}f \coloneqq a_n \in K^p.
    \end{equation}

\end{enumerate}

[Corollary cor:LackerZhang of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Suppose $(U, W)$ satisfies Assumption (as:results:fixedPoint of the paper). Let $\nu_0$ be a solution to the Cayley fixed point{} in the sense of Definition (def:results:CBP of the paper). Then, $(F, 0)$
    solves the Lacker-Zhang fixed point problem with
    \begin{equation}
        F(x) = \frac{1}{\kappa}\Big(U(x) + \log \nu_0(x) \Big), \quad x \in \ensuremath{\mathbb{R}}^d.

    \end{equation} Conversely, if $(F, C)$ solves the Lacker-Zhang fixed point problem, then there is a solution $\nu$ to Cayley fixed point{} in the sense of Definition (def:results:CBP of the paper) characterized by its marginal $\nu_0$, which is given by
    \begin{equation}
        \nu_0(x) = \frac{1}{\mathcal{Z}_F} e^{-U(x) - \kappa F(x)}, \quad  \mathcal{Z}_F := \int_{\ensuremath{\mathbb{R}}^d}  e^{-U(y) - \kappa F(y)} dy, \quad x \in \ensuremath{\mathbb{R}}^d.

    \end{equation}

[Lemma 11 of arXiv:2506.11918, 'Central limit theorems for the Euler characteristic in the Random Connection Model for hig'] Let $K$ be a simplicial complex on $r$ vertices with $m$ connected components and assume that (\ref{Integrabilitaet}) holds.
Then the integral representation $I_K(W)$ of $K$ over an observation window $W$ satisfies 
\begin{align*}
I_K(W) \,\leq\, \nu^{r-m} |W|^m.
\end{align*}

[Lem A. lem: precompactness in tau for hatC of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] A non-empty subset $\{\mathcal{X}_{\alpha} = (S_{\alpha}, d^{\alpha}, \rho_{\alpha}, f_{\alpha}) \mid \alpha \in \mathcal{A} \}$
  of $\mathfrak{M}_{c}(\tau^{\widehat{C}_{c}(M, \cdot)})$ 
  is precompact if and only if the following conditions are satisfied.
  \begin{enumerate} [label = (\roman*)]
    \item 
      The subset $\{(S_{\alpha}, d^{\alpha}, \rho_{\alpha}) \mid \alpha \in \mathcal{A}\}$ is precompact 
      in pointed the Gromov-Hausdorff topology
      (recall this from Remark (3. rem: Gromov-Hausdorff topology of the paper)).
    \item 
      It holds that 
      \begin{equation}
        \lim_{\delta \to \infty} 
        \sup_{ \alpha \in \mathcal{A}} 
        \sup_{\substack{x, y \in \dom(f_{\alpha})\\ d^{M}(x,y) \leq \delta}} 
        d^{\alpha}(f_{\alpha}(x), f_{\alpha}(y)) 
        = 0.
      \end{equation}
  \end{enumerate}

