[Lem b of arXiv:2411.11759, 'Milstein-type schemes for McKean--Vlasov SDEs driven by Brownian motion and Poisson random'] Let Assumptions \mbox{\normalfont  (asum:ic of the paper)} to \mbox{\normalfont  (asum:lin1 of the paper)} and \mbox{\normalfont  (asum:lin** of the paper)} 
   to \mbox{\normalfont  (asum:convergence2 of the paper)}  hold
		with  
  $\bar p\geq \max\{2,\eta/8+1\}(\varepsilon+2)(\eta+1)(\eta+2)/{\varepsilon}\color{black}$ 
  where $\varepsilon\in(0,1)$.
			Then,  	
		\begin{align*}
			E\int_{0}^{t}&e_s^{i,N,n}\Big\{ b\big( x_s^{i, N,n},\mu_s^{x, N,n}\big)-(\widehat b)_{tam}^{\displaystyle{n}}\big(x_{\kappa_n(s)}^{i,N,n},\mu^{x,N,n}_{\kappa_n(s)}\big)\Big\}ds
   \\
   &\leq K\int_{0}^{t} \sup_{i \in \{1,\ldots,N\}}\sup_{r\in[0,s]}E|e_r^{i,N,n}|^2ds+Kn^{-1-\frac{2}{\varepsilon+2}}
		\end{align*}
	for any $t\in[0,T]$ and $i\in\{1,\ldots,N\}$ where  $K>0$ is a  constant independent of $N$ and $n$.

