body:
[Definition 64 of arXiv:2608.26084, 'Localic Esakia Duality\\via Conic Frames'] An \emph{Esakia frame} is a pair~$(E,\dc)$ such that:
	\begin{enumerate}[label=(E\arabic*),start=0]
		\item $(E,\dc)$ is a conic frame;
		\item $E$ is a Stone frame;
		\item $\dc$ is a closure operator;
		\item $(E,\dc)$ is closed;

		\item $\Kdc(E)$ Boolean generates~$K(E)$.
	\end{enumerate}

[Theorem 56 (Habiro diagonal lift) of arXiv:2608.29585, '2608.29585'] Let $K$ be a zero-framed knot, let $n\ge2$, and let
$1\le s\le n-1$.  Then
\begin{equation}
 \mathscr J_K^{(n,s)}(q)=\sum_{k=0}^{\infty}
 \left(\prod_{i=0}^{k-1}\{-s-i\}\{n-s+i\}\right)
 H_k^{(n)}(K;q)
\end{equation}
defines an element of $\Hab$.  If $\zeta$ has order $L>s$, then
\begin{equation}
 \mathscr J_K^{(n,s)}(\zeta)=J_{L-s}^{SU(n)}(K;\zeta).
\end{equation}
Moreover, \eqref{eq:ordinary-Habiro-series} is the image of
\eqref{eq:colored-lift} under the continuous specialization $x=q^{-s}$.

[Theorem 3 (A representation congruence modulo $32$) of arXiv:2609.03238, 'Representation Defects and Cassels Pairings for Congruent Number Curves'] Assume \eqref{eq:layer}.  Then
\begin{equation}
\frac{r_f(pq)-r_g(pq)}{32}
 =\frac{r_a(pq)-h(-pq)}{16}
 \equiv\Pi(p,q)\pmod2.
\end{equation}
Equivalently,
\[
r_a(pq)\equiv h(-pq)+16\Pi(p,q)\pmod{32}.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition pro: Moment Bounds on hat q for JSQ of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] \textnormal{(Moment Bounds on $\hat{q}_{\Sigma}$)}

    Under the assumption (ass:heavy_overload of the paper), with $\hat{q}_{\Sigma}:= \sum_i q_i - \frac{\lambda-\mu}{\gamma}$, we have the moment bounds for any $p\geq 1, p\in \mathbb{R}$:
    \begin{align*}
        \mathbb{E}[|\hat{q}_{\Sigma}|^p]^{1/p} &\leq \max\{C_{\lambda,\mu,n}'' \cdot\frac{\sqrt{p}}{\sqrt{\gamma}} + C_{\lambda,\mu,n}'\cdot p, \: n(A_{\lambda,\mu,n} +\frac{1}{n}) \frac{p}{\log(1+\frac{n\gamma}{\lambda}p)}\} \\
        \mathbb{E}[|\hat{q}_{\Sigma}|^p]^{1/p} &\geq  C_{4,\lambda,\mu} \exp(-8(15+A_{\lambda,\mu})\frac{\lambda}{\gamma p}) \frac{p}{\log(1+\frac{p\gamma}{\lambda})}
    \end{align*}
    Constants $C_{\lambda,\mu,n}'$, $C_{\lambda,\mu,n}''$ and $A_{\lambda,\mu,n}$ are defined in (equation eq: subexpo L-p norm JSQ of the paper) and (equation eq: MGF upper bound JSQ of the paper), respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:D12 of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] If $m\ge40$ and there are two large spokes, then
\begin{equation}
  D_1=|C(\zeta)-1|\le m-\frac34,
\end{equation}
\begin{equation}
  D_2=|C(\zeta^2)-1|\le m+\frac12.
\end{equation}

