body:
[Prop 6 (Markov setting) of arXiv:2605.05986, '\bf Convergence rate of the occupation measure of { classes of ergodic processes toward th'] Let $(P_t)_{t\ge0}$ denote a  Markov transition semi-group defined on bounded $\R$-valued Borel functions defined on $\R^d$. Let $\mu_0\!\in {\cal P}_q(\R^d)$ for some $q> 1$ 
and 

let $\psi:\ER\rightarrow[0, +\infty)$ and $\ee\!\in \mathbb{L}^1([0, +\infty))$  be  Borel functions such that,
\begin{equation}
\begin{cases}
(i)& \;\forall t\ge0,\forall\, x \!\in \R^d, \quad \|P_t(x,dy)-\nu\|_{TV}\le \psi(x)\ee(t),\\
(ii)& \;\sup_{t\ge 0} \mu_0P_t \left(\psi^{q}+ |\cdot|^{q}\right)<+\infty.
\end{cases}
\end{equation}
Then, $\nu$ is the unique invariant distribution  of  $(P_t)_{t\ge 0}$, $\nu\!\in {\cal P}_q(\R^d)$  and  $\AUN$ holds true for every $t_0>0$  with $\beta=\frac 12 (1-\frac{1}{q})$, $\pi_t=\frac{1}{2}(\bar \nu_t+\nu)$ so that the bounds~\eqref{eq:boundsabstrait} of~\cref{thm:possiblynonmarkov} are in force. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2 of arXiv:2607.24533, 'Colored Markov-Modulated Brownian Motion for Preemptive Workload Stacks'] {Suppose that Assumptions~\ref{assump:intensity} and~\ref{assump:stability} hold.}
Then, using the active-time MMBM of Lemma~\ref{lem:active-censoring} and iterating from $c=C$ down to $c=2$, the depletion probability matrix defined in \eqref{eq:Phi-y} admits the representation
\begin{align*}
\vect{\Phi}_c(y)=e^{\vect{U}_c y},\qquad y>0,
\end{align*}
where $\vect U_c$ is the unique depletion exponent solving
\begin{equation}

\tfrac12(\vect{\Delta}_{\sigma}^{(c)})^2\vect U_c^2
+\vect{\Delta}_{\mu}^{(c)}\vect U_c
+\widetilde{\vect T}^{(c)}
=\vect0,
\end{equation}
for which $0$ is a simple eigenvalue with right eigenvector $\e$, and all nonzero eigenvalues lie in the open left half-plane.

{At color $1$, under the corresponding conditions in Assumption~\ref{assump:stability}:}
\begin{itemize}
\item \emph{Hold-and-jump model.} Color $1$ is depleting, and \eqref{eq:layer-qme} and {\eqref{eq:neg_drift}} again give a unique depletion exponent $\vect U_1$, with $\vect\Phi_1(y)=e^{\vect U_1 y}$, $y>0$.

\item \emph{Regulated-base model.} Color $1$ is regulated rather than depleted, and there is instead a unique stationary regulated-MMBM decay exponent $\vect K_{\mathrm{reg}}$ solving
\begin{equation}

\tfrac12 \vect{K}_{\mathrm{reg}}^{2}(\vect{\Delta}_{\sigma}^{(1)})^{2}-\vect{K}_{\mathrm{reg}}\vect{\Delta}_{\mu}^{(1)}+\widetilde{\vect{T}}^{(1)}=\vect{0},
\end{equation}
with eigenvalues in the open left half-plane, giving the anchor density
\begin{equation}

\vect{\nu}^{\mathrm R}(x)=\vect{g}_{\mathrm{reg}}e^{\vect{K}_{\mathrm{reg}}x},
\qquad x>0,
\end{equation}
where $\vect{g}_{\mathrm{reg}}$ satisfies the reflecting boundary condition
\begin{equation}

\vect{g}_{\mathrm{reg}}\left(\tfrac12\vect{K}_{\mathrm{reg}}(\vect{\Delta}_{\sigma}^{(1)})^{2}-\vect{\Delta}_{\mu}^{(1)}\right)=\vect{0},
\end{equation}
fixing its direction up to scale.
\end{itemize}

[Corollary anisotropic Lp Sobolev corollary of arXiv:2608.27248, 'Optimal Transport and the ABP Method in Higher Codimension'] Under the assumptions of Theorem (Polya Szego theorem of the paper), every
$u\in W_0^{1,p}(\Sigma)$, $1<p<n$, satisfies
\begin{equation}
 \left(\int_\Sigma |u|^{p^*}\,\mathrm d\mu\right)^{1/p^*}
 \leq A_{n,p}
 \left(\frac{\omega_n}{V_*(\mathcal E)}\right)^{1/n}
 \left(\int_\Sigma
  h_{\mathcal E}(\nabla^\Sigma u)^p\,\mathrm d\mu\right)^{1/p}.
\end{equation}
The constant is optimal uniformly over the stated class.  In particular,
$\mathcal E=\mathbb{B}^{n+m}$ gives the sharp inequality
\[
 \|u\|_{L^{p^*}(\Sigma)}
 \leq A_{n,p}\|\nabla^\Sigma u\|_{L^p(\Sigma)}
\]
for minimal submanifolds of codimension at most four.

[Theorem 9 of arXiv:2608.19179, 'A random walk on $p$-groups with a symmetric perfect pairing'] The Markov chain generated by $\Delta_S$  on the state space $X_S$ is reversible with respect to the probability measure:
\begin{equation}

\frac{
\prod_{i=1}^{\infty}(1-p^{1-2i})
}{
\# G
\# Aut(G,<\cdot,\cdot>)
}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 120 (Complex slope) of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] For any $u \in \mathbb{C}$, define 
		\begin{flalign}

                  	f_0 (u) = \displaystyle\frac{(\mathfrak{q}^{u-b - c} - 1) (\mathfrak{q}^{u} - 1)}{(\mathfrak{q}^{u+a} - 1) (\mathfrak{q}^{u - b} - 1)}; \qquad U(u) = \mathfrak{q}^{u} \cdot \displaystyle\frac{f_0 (u)}{1 - f_0 (u)}; \qquad V(u) = \displaystyle\frac{\mathfrak{q}^{u}}{1 - f_0 (u)}. 
		\end{flalign} 

		\noindent For any $(x, y) \in \mathbb{R}^2$, define $u = u(x,y) = u_q (x, y)$ to be the unique solution in $\overline{\mathbb{H}}$ to the equation
		\begin{flalign}

                  	\mathfrak{q}^y =  V(u) - \mathfrak{q}^x \cdot U(u),
		\end{flalign}
		whenever \eqref{equationu}, which is quickly verified to be a quadratic equation in $\mathfrak q^u$, has at most one real root. In this case, define the \emph{complex slope} $f_x(y):=f (x, y) $ by
		\begin{flalign}

			f (x,y) = \displaystyle\frac{\mathfrak{q}^{u} - \mathfrak{q}^{y}}{\mathfrak{q}^{u} - \mathfrak{q}^{y-x}}.
		\end{flalign}

[Lemma gap_convergence of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] For any fixed $\delta >0$ and $f$ of the form (Form of f of the paper) with $supp (f) \subset [-K_f, \infty), $ for some $K_f>0$, uniformly in $x\in[-(\mu -\lambda)t-\delta\sqrt{t},-(\mu -\lambda)t+\delta\sqrt{t}]$, we have
\begin{equation}
  \begin{aligned}
    &\lim_{t\to\infty}\mathbb{E}[1-e^{-\sum_{i = 1}^{n(t)} f(x_{i}+\chi_{k}^{i}(t) - \lambda t)}|x+M_{t} -\lambda t\ge -K_{f}]\\
    & = \int_{-\infty}^{\infty}\mu \mathbb{E}[1-e^{-\int f(y+z)\mathcal{D}^{\mu}(dz) }]e^{-\mu y}e^{-\mu K_{f}}dy. 
 \end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 8 of arXiv:2609.01101, '2609.01101'] There is $A_0\ge1$ such that, uniformly for
\begin{equation*}
1\le\lambda\le\tfrac12\log T
\qquad\hbox{and}\qquad |b_i|\le T/2,
\end{equation*}
one has
\begin{equation}
(2+\lambda)^{-A_0}B(T,\mathbf b,\mathbf a)
\ll H_\lambda(T)
\ll(2+\lambda)^{A_0}B(T,\mathbf b,\mathbf a),
\end{equation}
where
\begin{equation}
H_\lambda(T)=\sum_{n=1}^{\infty}
\frac{|c_{\mathbf b}(n)|^2}{n^{1+\lambda/\log T}}.
\end{equation}
Also, for some $A_1\ge1$,
\begin{equation}
(\log T)^{-A_1}\ll B(T,\mathbf b,\mathbf a)
\ll(\log T)^{A_1}.
\end{equation}

