[Definition 34 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Given $T > 0$, $\vartheta \in (2\kappa, 1/2 - 2\kappa)$ and $\zeta \in [0, \zeta_0)$, we write $\mathcal{D}^{(\zeta)}_T(\vartheta)$ for the subset of $\mathcal{D}_T^{\gamma - N\zeta, \vartheta - N\zeta}(\tilde \mfT^\zeta) \times \mathcal{D}_T^{\gamma - N\zeta, \vartheta - N\zeta}(\tilde \mfT^\zeta) \times \mathcal{D}_T^{3/2 + 2 \kappa - N\zeta, - \kappa - N\zeta}(\tilde \mfT^\zeta)$ consisting of triples $(\Hb, \Hp, \tilde{\mathcal{W}})$ with the property that $\partial_x \Hb - \<b1>, \partial_x \Hp - \<p1>$ are valued in the sector spanned by the trees of $|\cdot|_\fs$-degree at least $- 2 \kappa$.

	When we wish to emphasise the dependence of $\mathcal{D}^{(\zeta)}_T(\vartheta)$ on the model $Z \in \cM_{\mathrm{adm}}(\tilde{\mfT}^\zeta)$ we will instead write $\mathcal{D}^{(\zeta)}_T(\vartheta;Z)$.

	In order to formulate continuity statements, we write $\mathcal{O}_T = [-1,T] \times \mathbb{T}$ and equip the total space
	\begin{align*}
		\mathfrak{D}^{(\zeta)}_{T} = \{(Z, \Hb, \Hp, \mathcal{W}) \in \cM_{\mathrm{adm}}(\tilde{\mfT}^\zeta) \times \mathcal{D}^{(\zeta)}_{T}(\vartheta; Z) \}
	\end{align*}
	with the metric
	\begin{align*}
		d_{\mathfrak{D}^{(\zeta)}_{T}} ((Z,\Hb, \Hp, \mathcal{W}),& (\bar{Z}, \bar{\mathcal{H}}_{\<bsq>}, \bar{\mathcal{H}}_{\<psq>}, \bar{\mathcal{W}})) =  \| Z ; \bar{Z} \|^{(\zeta)}_{\gamma; \mathcal{O}_T} + \| \mathcal{H}_{\<bsq>}; \bar{\mathcal{H}}_{\<bsq>}\|^{(\zeta)}_{\gamma - N\zeta, \vartheta - N\zeta; \mathcal{O}_T}
		\\
		&+  \| \mathcal{H}_{\<psq>}; \bar{\mathcal{H}}_{\<psq>}\|^{(\zeta)}_{\gamma - N\zeta, \vartheta - N\zeta; \mathcal{O}_T} + \| \mathcal{W}; \bar{\mathcal{W}}\|^{(\zeta)}_{3/2 + 2 \kappa - N\zeta, - \kappa - N\zeta; \mathcal{O}_T},
	\end{align*}
	where $\|\cdot \, ; \cdot\|$ denote the usual comparison quantities for pairs of models and for modelled distributions over possibly different models \cite{H0}, the superscript $(\zeta)$ indicating that the respective norms are defined on the regularity structure $\tilde\mfT^\zeta$.

[Theorem thmISPC of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] Let $ g(t,x) = g_{1}(t) g_{2}(x) $, where $ g_{2} \in H^{1}(G) $ is nonzero.
For any $t_0\in (0,T]$, there exists a positive constant $\mathcal{C}=\mathcal{C}(t_0)$ such that for some generic constant $\gamma\in (0,1)$ (which is independent of $t_0$), it holds that

\begin{equation}
| y(t_0) |_{L^2_{\mathcal{F}_{t_0}}(\Omega;L^{2}(G))}
+ | g_{1} |_{L^{2}_{\mathbb{F}}(t_{0},T)}
\leq
\mathcal{C}(g_2) |y|_{L^{2}_{\mathbb{F}}(0,T; L^{2}(G))}^{1-\gamma}
| y(T) |_{L^2_{\mathcal{F}_{T}}(\Omega;H^{1}(G))}^{\gamma},
\end{equation}

where $y(\cdot)$   is the solution to (eqISPTerEq of the paper) and $\mathcal{C}(g_2)$ is a constant depending on $|\nabla g_2|_{L^{2}(G)}$.

