[Definition def:mixing of arXiv:2411.10333, 'Subcritical annulus crossing in spatial random graphs'] We say that \(\mathscr{G}\) is \emph{mixing} for \(\lambda>0\) if, for all \(|x|\ge 10\), we have 
  		\begin{equation*}\tag{\(\mathscr{M}\)}
  		 	\lim_{r\to\infty}\big|\operatorname{Cov}_\lambda\big(\1_{\mathcal{G}(r)}, \1_{\mathcal{G}(xr,r)}\big)\big| = 0.
  		\end{equation*}
  		We denote this property by \(\mathscr{M}_\lambda\). We say that the graph is \emph{uniformly mixing} for \(\lambda>0\), denoted by \(\overline{\mathscr{M}}_\lambda\), if, for any \(|x|\ge 10\), we have
  		\begin{equation*}\tag{\(\overline{\mathscr{M}}\)}	            \lim_{r\to\infty}\sup_{\lambda'<\lambda}\big|\operatorname{Cov}_{\lambda'}\big(\1_{\mathcal{G}(r)}, \1_{\mathcal{G}(xr,r)}\big)\big| = 0.
  		\end{equation*}
  		In some situations we require a polynomial decay of the correlations. If this is the case, we say that \(\mathscr{G}\) is \emph{polynomially mixing} for \(\lambda>0\) with exponent \(\xi=\xi_\lambda<0\) if, for any \(|x|\ge 10\), we have
  		\begin{equation*}\tag{\({{\mathscr{P}}\!\!{\mathscr{M}}}\)}
 		\limsup_{r\to\infty}\frac{\log\big|\operatorname{Cov}_{\lambda}\big(\1_{\mathcal{G}(r)}, \1_{\mathcal{G}(xr,r)}\big)\big|}{\log r}\leq \xi
 		\end{equation*}
 		and denote this property by \({{\mathscr{P}}\!\!{\mathscr{M}}}_\lambda^{\xi}\).

[Definition 3 of arXiv:2608.25971, 'Positive \texorpdfstring{$\tau$}{tau}-bi-Ricci curvature and Mean curvature flow with surg'] After choosing the normal so that $H\geq n\kappa$, a hypersurface satisfies the
\emph{quantitative $\tau$-bi-Ricci pinching condition} with constant
$\alpha_0>0$ if
\begin{equation}
 P_{ij}^{(\tau)}
 \geq\alpha_0 H|\lambda_p-\lambda_q|
 \qquad(i\ne j,\ p,q\text{ arbitrary}).
\end{equation}

[Lem 9 of arXiv:2604.26316, 'Smallest distances between zeros of Gaussian analytic functions'] As $n\to\infty$, one has the convergence,  $$
		\abs{\tilde{\mathcal I}_n}
		\stackrel{\text { }}- \abs{\mathcal I_n}\to0 \,\, \mbox{ in probability. }$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Def1 definition:snakePath of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] Fix $(\mu , {\mathrm{w}}) \in \Theta$.  An element  $(\upvarrho , \omega) \in 
\mathbb{D}(\mathbb{R}, \mathcal{M}_f(\mathbb{R}_+) \times \mathcal{W}_{E})$  is called a snake path started from $(\mu , {\mathrm{w}})$ if the following properties hold:
\begin{enumerate}
    \item[\emph{(S1)}]   $(\upvarrho_0 , \omega_0) = (\mu,  {\mathrm{w}})$  and $\omega\in \mathcal{S}^\circ_{\mathrm{w}}$;
    \item[\emph{(S2)}] For every  $s \geq 0$, we have  $(\upvarrho_s, \omega_s) \in \Theta$; in  particular   $H(\upvarrho) = \zeta(\omega)$.
\end{enumerate}
The family of snake paths started from some fixed $(\mu , {\mathrm{w}}) \in \Theta$ is denoted by $\mathcal{S}_{\mu , {{\mathrm{w}}}}$, and when $(\mu , {\mathrm{w}})$ is of the form $(0,y)$ for some $y \in E$, we simply write $\mathcal{S}_{y}$. 
We set 
\begin{equation*}
   \mathcal{S} := \bigcup_{(\mu , {\mathrm{w}})\in \Theta}\mathcal{S}_{\mu , {\mathrm{w}}} 
\end{equation*}
for the collection of snake paths.

[Theorem 20 (first-order expansion of the bias: the sharp rate) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] Let the assumptions of \cref{thm:ula-bias} hold, and fix $\delta\in(1,2)$.  Then, for every bounded measurable $\eta\colon[0,\infty)\to\mathbb R$,
  \begin{equation}
    \pi_h(\eta)-\pi(\eta)\;=\;K_\star\,\hat\eta(0)\,h\abs{\log h } \;+\;O\bigl(h\,\snorm{\eta}_\infty\bigr),
    \qquad \hat\eta(0)\coloneqq \eta(0)-\pi(\eta),
  \end{equation}
  with the observable-independent constant
  \begin{equation}
    K_\star\;=\;\tfrac12\,(\delta-1)\,\beta\,G'(0)^2\,\pi(\{0\}) .
  \end{equation}
  Equivalently, $\pi_h=\pi+K_\star\,h\abs{\log h } \,(\delta_0-\pi)+O(h)$ in total variation. (Proof in the paper; no proof environment follows the statement in the TeX.)

