      \W_{d_{\Theta\sigma}}&\left(\mu Q_\sigma, \nu Q_{\s}\right)\leq \W_{d_{\s}}(\mu,\nu) \text{ for all } \mu,\nu\in \mathcal{P}(E),
    \end{align*}
