[Lemma of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] Fix $T>0$ and $\gamma\in\mathscr{M}_{ac}$. Let $\rho\in  {\mathcal{D}}([0,T], \mathscr{M}_{ac})$ be such that $I_{[0,T]}(\rho|\gamma)<\infty.$ Then, $\rho(0,x)=\gamma(x).$ Moreover, for each $M>0$, $G\in C^2([0,1])$ and $\varepsilon>0$, there exists a $\delta>0$ such that 
    \begin{equation*}
        \sup_{\rho:I_T(\rho|\gamma)\leq M}\sup_{|t-s|\leq\delta}|\langle \rho_t, G\rangle-\langle \rho_s, G\rangle|\leq \varepsilon.
    \end{equation*}
    In particular, $\rho$ belongs to $C([0,T],\mathscr{M}_{ac})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 27 of arXiv:2604.01978, 'Homogenized Transformers'] For all $k\in \naturals$, we denote $\mathfrak{X}^{k}((\S^{d-1})^n)$ the set of vector fields admitting a derivative of order $k$, endowed with the norm 
    \begin{equation*}
        \|V\|_{\mathfrak{X}^{k}((\S^{d-1})^n)}\coloneqq \max_{X\in (\S^{d-1})^n}\left(\|V(X)\|+\max_{j\in[k]}\|\nabla^{j}V(X)\|\right)
    \end{equation*}

[Thm first main of arXiv:2412.05950, 'Quantitative particle approximation of nonlinear stochastic Fokker-Planck equations with s'] Assume $(\mathbf{A}^V)$, $(\mathbf{A}^c)$, $(\mathbf{A}^F)$,  and $(\mathbf{A}^K)$, let $T_{max}$ be the maximal existence time for ((SPDE_Ito of the paper)) and fix $T \in \left(0,T_{max}\right)$. In addition, let the dynamics of the particle system be given by ((particles of the paper)) with $\nu=Id$, $\sigma$ independent of the space  and  for any $m \ge 1$,
				\begin{align*}
					\sup_{N \in \mathbb{N}} \Big \| \left\| \rho^N_0 \right\|_{q} \Big \|_{{L^m(\Omega)}} < \infty
				\end{align*}
				with $ d \geq 1$, $q>d$ given by $(\mathbf{A}^K)$ and  $\beta \in \left(0,\frac{1}{2\big[1 + \frac{1}{d} - \frac{1}{q}\big]}\right) $.
				Then

				\begin{align*}
					\Big \| \left\|\rho - \rho^N \right\|_{T,q} \Big \|_{L^m(\Omega)}  &\le C \Big \| \left\|\rho_0 - \rho^N_0 \right\|_{q} \Big \|_{L^m(\Omega)} + C N^{-\varkappa} \, \nonumber 
				\end{align*}
				where
				\begin{align*}
					\varkappa = \min \left(\frac{\beta}{d}\gamma,\frac{1}{2}-\beta\Big(1 + \frac{1 }{d}-\frac{1}{q}\Big) \right)
				\end{align*}
				\noindent and $\rho$ is a  solution of SPDE (equation SPDE_Ito of the paper) with initial condition $\rho_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm potential-zero of arXiv:2411.16376, 'Higher order approximations in arcsine laws for subordinators'] Let $X=(X_t)_{t\geq0}$ be a killed subordinator which is not identically zero. Assume that the Laplace exponent $\Phi(z)$ satisfies the following condition:
\begin{enumerate}[label={\upshape (\Alph*')}]
\item There exist constants $n\in\ensuremath{\mathbb{N}}\cup\{0\}$, $c_0\in(0,+\infty)$, $c_1,\dots,c_n\in\ensuremath{\mathbb{R}}\setminus\{0\}$ and $\beta_0<\beta_1<\dots<\beta_n<+\infty$ with $\beta_0\in(0,1]$, and a locally integrable function $R:(0,+\infty)\to(0,+\infty)$ such that $R(t)$ is non-increasing on $(r,+\infty)$ for some $r>0$, $R(t)=o(t^{-1-\beta_n})$, as $t\to+\infty$, and
\begin{align}
    \frac{d}{dz}
    \bigg(
    \frac{1}{\Phi(z)}
    -
    \sum_{k=0}^n
    \frac{1}{c_k z^{\beta_k}}
    \bigg)
    =
    O(R(|z|)),
    \quad
    \text{as $z\to\infty$ in $\{z\in\ensuremath{\mathbb{C}}\mid {\rm Re}\,z>0\}$}.	
\end{align}
\end{enumerate}
Then the potential measure $U|_{(0,+\infty)}$ restricted over $(0,+\infty)$ admits a continuous density $u(x)$ $(0<x<+\infty)$ which can be estimated as
\begin{align}
   u(x)
   =
   \sum_{k=0}^n
   \frac{x^{-1+\beta_k}}{c_k\Gamma(\beta_k)}+O(\varepsilon_1(x)),
   \quad\text{as $x\to0+$,}
\end{align}
where
\begin{align}
    \varepsilon_1(x)
    =
    x^{-2}R(x^{-1})+x^{-1}\int_{x^{-1}}^{+\infty} R(t)\,dt.	
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Let $\mathcal{G}$ denote the standard horizontal foliation on the neighborhood $N(\mathcal{W}) = [-1,2]^2_{x,z}$ of the square window $\mathcal{W} = [0,1]^2$, i.e., $\mathcal{G}$ is tangent to $\partial_x$. Let $\star \in \{ \sharp, \flat\}$. A \textbf{$\star$~modification of $\mathcal{G}$ in $N(\mathcal{W})$} is a smooth foliation $\mathcal{G}^\star$ on $N(\mathcal{W})$ satisfying
     \begin{itemize}
        \item $T\mathcal{G}^\star$ is either tangent or transverse to $T \mathcal{G}$; it is positively transverse if $\star = \sharp$ and negatively transverse if $\star = \flat$,
         \item $\mathcal{G}^\star$ coincides with $\mathcal{G}$ near $\partial N(\mathcal{W})$,
         \item $\mathcal{G}^\star$ is transverse to $\mathcal{G}$ in a neighborhood of $\mathcal{W}$.
     \end{itemize}

[Lemma 27 (\textsf{Convergence of the mollified sign kernels}) of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] Fix $\wt x\in\R$ and a compact set
  $K\Subset\R\setminus\{\wt x\}$.  For every
  $i,j\in\{0,\dots,n\}$,

  \noi
  \begin{align}

  \begin{aligned}
   & \sup_{u\in K}\bigg|
      \int_{\DN^2}
      \Psi^\eps(\wt x+\wt\ga_i-u-\ga_j)
      Q_{\wt x}^\eps(d\wt\ga)Q_u^\eps(d\ga) \\
     &\qquad\qquad\qquad  -\frac12    \int_{\DN^2}    \sgn(\wt x+\wt\ga_i-u-\ga_j)   Q_{\wt x}(d\wt\ga)Q_u(d\ga)
    \bigg|\xrightarrow{\eps\to 0} 0. 
  \end{aligned}
  \end{align}
  In addition, for every $j\in\{1,\dots,n\}$ and every compact
  $K\subset\R$,
  \begin{align}
    \sup_{u\in K}
    \bigg|    \int_{\DN}\Psi^\eps(u+\ga_j)Q_u^\eps(d\ga)     -\frac12\int_{\DN}\sgn(u+\ga_j)Q_u(d\ga)    \bigg|
    \xrightarrow{\eps\to 0} 0. 
  \end{align}

[Definition def:tridwn of arXiv:2412.04589, 'Inverting the Markovian projection for pure jump processes'] Under the setting of Definition~(def:vee of the paper), we define $\mathbb{F} 
ewtriangledown \mathbb{G}$, $
ewbigtriangledown_{i \in I} \mathbb{F}^i$ and $\mathbb{F} 
ewtriangledown \mathcal{G}$ as the right-continuous regularization of $\mathbb{F} \lor \mathbb{G}$, $ igvee_{i \in I} \mathbb{F}^i$ and $\mathbb{F} \vee \mathcal{G}$, respectively.

[Lemma Eq:weakconvergence of arXiv:2606.03079, 'Mean Field Limits for Stochastic, Underdamped Reactive Langevin Dynamics Models'] (Weak Convergence). For any $\Phi \in \mathcal{S}$ and $0 \leq r_{1} \leq r_{2} \cdots \leq r_{W}=s<t<T$ and $\{\psi_{w}\}_{w=1}^{W} \subset$ $B\left(\otimes_{j=1}^{J} M_{F}(\mathbb{R}^{d}\times \mathbb{R}^{d})\right)$, we have that
\begin{equation}
\lim_{\zeta \rightarrow 0} \mathbb{E}\left[\left\{\Phi(\bm{\mu}_{t}^{\zeta})-\Phi(\bm{\mu}_{s}^{\zeta})-\int_{s}^{t}(\mathcal{A} \Phi)(\bm{\mu}_{r}^{\zeta}) d r\right\} \prod_{w=1}^{W} \psi_{w}\left(\bm{\mu}_{r_{w}}^{\zeta}\right)\right]=0.
\end{equation}

