[Theorem thm:bicausaltptmapsbetweenSDEsdegen of arXiv:2412.02948, 'Causal transport on path space'] Let $\eta := \mu^{\sigma,b}_z $ and $\nu := \mu^{\overline{\sigma}, \overline{b}}_{\tilde{z}}$.


   For $T : \mathcal{W}^d \rightarrow \mathcal{W}^d$, define  $T_t\del{\omega} := T\del{\omega}\del{t} \in \mathbb{R}^{d}$ for $t \in \sbr{0,1}$. $T$ is a bicausal Monge map from $\eta$ to $\nu$ if and only if\;\footnote{We thank Y. Jiang for the sufficiency part of this theorem.} there exists some $\del{\mathcal{H}^\eta_{t}}_{t \in \sbr{0,1}}$-progressively measurable process $Q : \sbr{0,1} \times \mathcal{W}^d \rightarrow \mathcal{O}^d$ 







     such that $\del{T_t}_{t \in \sbr{0,1}}$ is a $\deln{\eta, \del{\mathcal{H}^\eta_t}_{t \in \sbr{0,1}}}$-semimartingale satisfying 
     \begin{equation}

     T_t = \tilde{z} + \int_0^t \overline{b}\del{s,T} ds + \int_0^t \overline{\sigma}\del{s,T} Q_s \sigma^\dag\del{s,X} dM^\eta_s 
     \; \eta\text{-a.s.}

     \end{equation}
      and
      \begin{equation}

     \overline{\sigma}\del{t,T} Q_t = \overline{\sigma}\del{t,T} Q_t \sigma^\dag\del{t,X}\sigma\del{t,X} \qquad d\eta\otimes dt\quad -{\rm a.e. }  
      \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop.SobolevNorm of arXiv:2606.13442, 'Scaling limit of additive functionals for reversible non-gradient exclusion process: criti'] We have the following estimates for $\overline{g}_\lambda$:
		\begin{enumerate}
			\itemThe first order finite difference of $\overline{g}_\lambda$ satisfies:
			\begin{equation*}
				\sum_{x,y\in\mathbb{Z}}\left({\mathsf{D}}_1\overline{g}_\lambda(x,y)\right)^2 = \frac{1}{2} \mathbf{D}(\rho)^{-1}\chi(\rho)^{-2}\expec{\overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}}\overline{G}_\lambda}.
			\end{equation*}
			\item The second order finite difference of $\overline{g}_\lambda$ satisfies:
			\begin{equation*}
				\sum_{x,y\in\mathbb{Z}}\left({\mathsf{D}}_1{\mathsf{D}}_2\overline{g}_\lambda(x,y)\right)^2\leqslant\frac{1}{4} \mathbf{D}(\rho)^{-2}\chi(\rho)^{-2}\expec{-{\overbracket[1pt][-1pt]{\mathcal{L}}}\overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}}\overline{G}_\lambda},
			\end{equation*}
			\begin{equation*}
				\sum_{x,y\in\mathbb{Z}}\left({\mathsf{D}}_1{\mathsf{D}}_1\overline{g}_\lambda(x,y)\right)^2\leqslant \frac{1}{4}\mathbf{D}(\rho)^{-2}\chi(\rho)^{-2}\expec{-{\overbracket[1pt][-1pt]{\mathcal{L}}}\overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}}\overline{G}_\lambda}.
			\end{equation*}
			\item For every fixed constant $s\geqslant 1$, there exists a positive constant $C(\rho)$ such that for every $\ell\in\mathbb{Z}_{+}$, the following estimate holds:
			\begin{equation*}
				\sum_{x\in\mathbb{Z}}\sum_{|y-x|\leqslant s}\left({\mathsf{D}}_1\overline{g}_\lambda(x,y)\right)^2
				\leqslant s\cdot C(\rho)\left( \ell^{-1}\expec{\overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}}\overline{G}_\lambda}+\ell\expec{-{\overbracket[1pt][-1pt]{\mathcal{L}}}\overline{G}_\lambda,-{\overbracket[1pt][-1pt]{\mathcal{L}}}\overline{G}_\lambda}\right).
			\end{equation*}
		\end{enumerate}

