[Corollary 7 (Renormalized scale derivative) of arXiv:2609.01319, 'Matched Queries for Curvature and Density at Branching Junctions'] For fixed $1<\lambda\le\lambda_{\max}$ and compact $\cQ$,
\begin{equation}
\sup_{z\in\cQ}\norm{\cD_{\sigma,\lambda}(z)-G(z)}
\le C_{\cQ,\lambda}\sigma^\alpha.

\end{equation}
Equivalently,
$G(z)=\partial_\sigma[\sigma s_\sigma(x_0+\sigma z)]|_{\sigma=0^+}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (Edge case) of arXiv:2511.12623, 'The eigenvector bead process'] Fix an integer \(\ell\ge 1\).
For \(1 \leq i,j \leq \ell \), the overlap matrix converges to the identity matrix, i.e.~$\lim_{N\to\infty}(\Omega_{i,j}^{(N)})_{1\leq i,j\leq \ell}=I_{\ell}$ (in agreement with \cite{bao2025}). Furthermore, the leading-order correction scales as $O(N^{-1/3})$ and is given by:
\begin{equation}
  N^{1/3}\bigl(\Omega^{(N)}_{i,j}-(I_{\ell})_{i,j}\bigr)\;
  \mathrel{\underset{N\to\infty}{\overset{d}{\sim}}}\;
  \begin{cases}
    \dfrac{\overline{g_i}\, g_j}{\alpha_j-\alpha_i}, & i\neq j,\\[0.6ex]
    0, & i=j,
  \end{cases}
  \qquad 1\leq i,j\leq \ell.
\end{equation}

\noindent
Here \((\alpha_i)_{i=1}^\ell\) follow the Airy$_{\beta}$ point process, and \((g_i)_{i=1}^\ell\) are i.i.d.\ standard Gaussians \(\mathcal{N}_\beta(0,1)\) independent of \((\alpha_i)\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem local curve GW universal series of arXiv:2609.02409, 'Membranes and Maps'] There exist universal series $A,B_2,\ldots,B_5$ in $\epsilon_2,\ldots,\epsilon_5$ such that
    \begin{equation}
        \GWargs{Z}{\mathsf{T}}{[C]} = A^{g_C -1}\prod_{i=2}^5 B_i^{\deg \cL_i} \,.
    \end{equation}
    At this stage, we do not impose the Calabi--Yau condition. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm main2 of arXiv:2411.13926, 'Random walks on random walks:\\ non-perturbative results in high dimensions'] Consider the RWRW model  on $\mathbb{Z}^d$ with $\lambda \in [0,\infty)$. 
\begin{itemize}
\item[a)] (weak) annealed Functional Central Limit Theorem (waFCLT):\\
If $d\geq 5$ and there is an $\alpha \in \ensuremath{\mathbb{R}}^d$ such that the variance of $\alpha \cdot X_n$ diverges, then there is a slowly varying function  $h\colon [0,\infty) \rightarrow \ensuremath{\mathbb{R}}$ such that
\begin{equation}
\left( \frac{\alpha \cdot X_{\lfloor nt\rfloor}- \alpha \cdot v\lfloor nt\rfloor}{\sqrt{nh(n)}} \right)_{t \in [0,1]} \overset{P_{\ensuremath{\mathbb{P}}}}{\implies} (B_t)_{t \in [0,1]}
\end{equation}
where $\overset{P_{\ensuremath{\mathbb{P}}}}{\implies}$ denotes convergence in distribution under the annealed law $P_{\ensuremath{\mathbb{P}}}$ as $n\rightarrow \infty$ with respect to the Skorohod topology and  $(B_t)$  is a standard Brownian motion on $\ensuremath{\mathbb{R}}$.\\  
If, moreover, $d\geq 9$, then there is a $\sigma \in (0,\infty)$ such that $h(n)=\sigma$. 
\item[b)] annealed Functional Central Limit Theorem (aFCLT):\\
If $d\geq 9$ and $(X_t)$ is truly d-dimensional, then 
\begin{equation}
\left( \frac{ X_{\lfloor nt\rfloor}- v\lfloor nt\rfloor}{\sqrt{n}} \right)_{t \in [0,1]} \overset{P_{\ensuremath{\mathbb{P}}}}{\implies} (B_t^{\Sigma})_{t \in [0,1]}
\end{equation}
where $(B_t^{\Sigma})$ is a Brownian motion on $\ensuremath{\mathbb{R}}^d$ with covariance matrix $\Sigma>0$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 33 of arXiv:2606.09904, 'Non-explosion principles for branched rough differential equations with unbounded coeffici'] For any \(f \in \CF_{N - 1}\) and \(n \le N - |f|\), we have that 
  \begin{equation}
    \|D^n \partial^f_X \phi(Y)\|_{\infty; I_r} \lesssim l(r)^{(1 - n)\alpha + \delta}
  \end{equation}
  for any \(r, \delta > 0\). Moreover, in the special case where \(n = 1\), we have that 
  \begin{equation}
    \|D\partial^f_X \phi(Y)\|_{\infty; I_r} \lesssim (\log l(r))^{\gamma \Lambda_1([f])}. 
  \end{equation}

