[Proposition prop:lbm-response-realization of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] For every $\mu\in\mathcal M_{\rm LBM}$ and every $u,v$ in a common
positive eigenspace of $A_\mu$,
\begin{equation}
 \Theta_\mu(u,v)=uv\,\mu\in\mathcal M_{\rm fe}(D).

\end{equation}
The map $U_\mu=U_D$ in (equation eq:lbm-response-space of the paper) is linear and
injective, and
\begin{equation}
 \inner{U_\mu\sigma}{f}_{H}
 =\int_Df\,d\sigma,
 \qquad
 \sigma\in\mathcal M_{\rm fe}(D),\quad f\in C_c^\infty(D).

\end{equation}
Thus the LBM response is faithfully potential-realizable in the sense of
Definition~(def:response-realization of the paper).

[Defn hext of arXiv:2608.27939, 'Entropy and domination for quasi-Hitchin representations'] Let $\mathcal{P}(g_1,g_2)$ be the (possibly infinite) collection of plaques separating $g_1$ from $g_2$, with the linear order induced by the transverse orientation. A map $$M:\mathcal{P}(g_1,g_2) \to \mathrm{SL}_n(\mathbb{C})$$
is said to be \textit{H\"{o}lder-extendable} if there exist constants $A,\nu>0$ such that 
\begin{equation*}
    \lVert M(T) - \text{I}\rVert \leq A d_\infty(x_{T,1}, x_{T,3})^\nu
\end{equation*}
where $(x_{,1}, x_{T,2},x_{T,3})$ are the ordered set of vertices of $T$ between $g_1$ and $g_2$ and $d_\infty$ is a metric on the ideal boundary of $\tilde{S}$ that is the standard metric on the circle.

[Corollary 7 (Simplex cap) of arXiv:2607.23980, 'Sharp small-deviation inequalities for sums of independent\\nonnegative random variables'] Let $y=(y_1,\ldots,y_n)\in[0,\infty)^n$, and write $s(y)=\sum_i y_i$. If $s(y)>0$ and $0\le t\le s(y)/(n+1)$, then
\begin{equation}
 \Pp_D\left(\sum_{i=1}^n y_iD_i\ge t\right)
 \ge\left(1-\frac{t}{s(y)}\right)^n.
\end{equation}
Moreover, for every $\delta>0$, if $s(y)\ge n+\delta$, then
\begin{equation}
 \Pp_D\left(\sum_{i=1}^n y_iD_i>1\right)\ge b_{n,\delta},
 \qquad
 K_n(y)\le1-b_{n,\delta}.
\end{equation}

[Theorem 1 of arXiv:2606.22656, 'Fluctuations of Point Vortex Ensembles\\ at Small Negative Inverse Temperature'] There exists $0<\beta_0<8\pi$ such that, for every $0<\beta<\beta_0$,
\begin{equation*}
    \lim_{N\to\infty} Z_N(\beta)=\dettwo(I-\beta G)^{-1/2}.
\end{equation*}
As a consequence, the law of $\omega_N$ on $\D'(\T)$ under the positions' distribution $\nu_{N,\beta}(dx^N)$ weakly converges to $\mu_\beta$ for $\beta<\beta_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:differentiated-linear-estimate of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Let $\alpha\geq0$ and assume Assumptions~(ass:reference-diffusion of the paper) and
(ass:drift-multiplier of the paper).  For
\begin{equation*}
 F\in H_{x,\alpha}^1,\qquad
 \psi\in H^1(\mu_T),\qquad u=\mathcal U(F,\psi),
\end{equation*}
one has $\mathfrak g[u,F]\in L_\alpha^2(\mathbb R^d)$ and
$D_xu\in H_{x,\alpha}^1(\mathbb R^d)$, with
\begin{equation}
 D_xu
 =\mathcal P_1^{-1}(D_xF,D_x\psi)
 =\mathcal U(\mathfrak g[u,F],D_x\psi).

\end{equation}
If, in addition, $w$ is a regular weight of order $\alpha$,
$C_w(X)<\infty$, and $\psi\in H^2(\mu_T)$, then
$\mathsf G u\in H_{x,\alpha}^1(\mathsf{S}^d)$.  For every $\kappa\geq1$, the following
estimate holds with
$C=C\bigl(T,\lambda,\Lambda,M_1(a),\operatorname{osc}_\alpha(w),C_w(X),
\Lambda_b\bigr)>0$:
\begin{equation}
 \left\lVert D_x\mathsf G u\right\rVert_{w_\kappa}
 \leq C_{w_\kappa}(X)\left\lVert D_xF\right\rVert_{w_\kappa}
 +C\left(\left\lVert F\right\rVert_{w_\kappa}
          +T^{\alpha/2}\norm\psi_{H^2(\mu_T)}\right).

\end{equation}

[Proposition prop:inverse_kasteleyn_matrix of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] {borodin-gr2009q}}]

	The inverse Kasteleyn matrix is expressed through the two-dimensional correlation kernel
	$\widetilde{K}$ (equation eq:K_kernel_two_dimensional of the paper)
	as follows:
	\begin{equation}

		\mathrm{Kast}^{-1}\left( s,x;t,y \right)
		=
		\frac{G(s,x)}{G(t,y)}
		\frac{\mathbf{1}_{s=t}\mathbf{1}_{x=y}- \widetilde{K}(s,x;t,y)}{\mathsf{w}_{q,\kappa}(x-\tfrac s2+1)},
	\end{equation}
	where
	$(s,x)$ and $(t,y)$ are the coordinates of a black (resp., white) triangle.
	The factor $G$ is
	\begin{equation}

		G(t,x)\coloneqq
		\frac{1}{\sqrt{\widetilde{w}_t(x)}}
		\frac{(-1)^{x} \kappa^{-t}
		q^{x(T+N-t-1)+t(S/2-1/2)+t(t+1)/4} \left(1-\kappa^2 q^{2x-t-S+1}\right)}
		{(\frac{1}{q}; \frac{1}{q})_{S+N-1-x} (q;q)_{T-S+x-t} (\kappa^2 q^{x-T+1}; q)_{T+N-t}}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2608.21816, 'On P\'olya's 4D random walk constant'] In dimension 4, the return probability is given by
\begin{equation*}
p(4)=1-1/u(4)=0.1932016732\ldots, 
\end{equation*}
where
\begin{align}
u(4)&=\frac{3\Gamma(\frac{1}{3})^9}{16\pi^6}\,{}_4F_3\bigg({\frac{1}{6},\frac{1}{3},\frac{1}{3},\frac{1}{2} \atop \frac{2}{3},\frac{5}{6},\frac{5}{6}} \; \bigg| \;1\bigg)-\frac{64\sqrt{3}\,\pi^3}{3\Gamma(\frac{1}{3})^9}\,{}_4F_3\bigg({\frac{1}{2},\frac{2}{3},\frac{2}{3},\frac{5}{6} \atop \frac{7}{6},\frac{7}{6},\frac{4}{3}} \; \bigg| \;1\bigg)  \\
&=\frac{\Gamma(\frac{1}{3})^6}{2^{5/3}\pi^4}\,{}_5F_4\bigg({\frac{1}{3},\frac{1}{3},\frac{1}{2},\frac{1}{2},\frac{1}{2} \atop \frac{5}{6},\frac{5}{6},\frac{5}{6},1} \; \bigg| \;1\bigg) \\
&=1.2394671218\ldots. \nonumber
\end{align}

