[Definition def: cycle conditon of arXiv:2411.06861, 'Quenched invariance principle for random walks in random environments admitting a cycle de'] A random vector $\Psi\colon \Omega \times \mathcal{N} \to \mathbb{R}$, satisfies the \emph{cycle condition} if for any sequence $(x_{0}, \cdots, x_{n})$ in $\mathbb{Z}^{d}$, with $x_{0} = x_{n}$ and $(x_{j-1}, x_{j}) \in \vec{E}_d$, $1 \leq j \leq n$, it holds that

  \begin{align}

    \sum_{j=1}^{n}\Psi(\tau_{x_{j-1}}\omega, x_{j} - x_{j-1}) \;=\; 0.
  \end{align}

[Lemma 9 of arXiv:2608.23462, '2608.23462'] Let $p \geq 2$ and $\beta >0$. Assume that Assumption~\ref{assu:frozenLipschitz} is satisfied and the frozen variable is $p$-dissipative with constant $\beta$. Then, the following holds:
\begin{enumerate}
    \item[(i)] For all $x\in \R^{d_1}$, $y_1,y_2 \in \R^{d_2}$, and $t\geq 0$ we have
        \begin{align*}\|\hat{Y}^{x,y_1}_t-\hat{Y}_t^{x,y_2}\|_{L^p(\hat{\P})} \leq e^{-\beta t}|y_1-y_2|.\end{align*}
    \item[(ii)] There exists a $C_{\beta,p} > 0$ such that for all $x_1,x_2 \in \R^{d_1}$, $y \in \R^{d_2}$, and $t\geq 0$ we have
    \begin{align*}
        \|\hat{Y}^{x_1,y}_t-\hat{Y}^{x_2,y}_t\|_{L^p(\hat{\P})} \leq C_{\beta,p} |x_1-x_2| .
    \end{align*}
    \item[(iii)] There exist $C_{\beta,p}^{(1)}, C_{\beta,p}^{(2)} > 0$ such that for all $x \in \R^{d_1}$, $y \in \R^{d_2}$, and $t\geq 0$ we have       
    \begin{align*}
    \| \hat{Y}^{x,y}_t\|_{L^p(\hat{\P})} \leq \left\{ e^{-p(\beta  /2) t}|y|^p + C_{\beta,p}^{(1)} \right\}^{1/p} \leq e^{-(\beta  /2) t}|y| + C_{\beta,p}^{(2)}. 
    \end{align*}
\end{enumerate}

