body:
[Lemma 8 (Signed Bell generating function) of arXiv:2606.22066, 'A Bessel-zero obstruction to hyperbolic complete monotonicity of noncentral chi-square den'] With \(d_m\) as in Proposition~\ref{prop:bell-obstruction},
\begin{equation}

\sum_{n=0}^{\infty}
\mathcal B_n(d_1,\dots,d_n)\frac{z^n}{n!}
=
e^{-bz}F_a(b\theta z).
\end{equation}
Equivalently,
\begin{equation}

\sum_{n=0}^{\infty}
(-1)^n\mathcal B_n(d_1,\dots,d_n)\frac{t^n}{n!}
=
e^{bt}F_a(-b\theta t).
\end{equation}
Moreover, equivalently as an ordinary Taylor expansion,
\begin{equation}

e^{bt}F_a(-b\theta t)
=
\sum_{n=0}^{\infty}
\frac{b^n}{(a)_n}L_n^{(a-1)}(\theta)t^n,
\end{equation}
where \(L_n^{(a-1)}\) denotes the generalized Laguerre polynomial, with normalization
\begin{equation}
L_n^{(a-1)}(\theta)
=
\frac{(a)_n}{n!}\,{}_1F_1(-n;a;\theta).
\end{equation}
Consequently,
\begin{equation}

(-1)^n\mathcal B_n(d_1,\dots,d_n)
=
\frac{n!b^n}{(a)_n}L_n^{(a-1)}(\theta).
\end{equation}

