body:
[Lem 152 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Given any $\upp,\eta\in (0,1)$, if $\linit$ is sufficiently large
depending on $\upp,\eta$, then
  \[
        \sup_{1\leq \ell\leq 3\linit/4}
        \lt\{
        \plim_{N\to\infty} 
  \bigg\{
  \frac{|(
  \hat{\by}^{-\ell},
  \tilde \by^{-\ell})|}{N}
  +\frac{| (
  \hat{\bv}^{-\ell},
  \tilde\bv^{-\ell})|}{M}\bigg\}
        \rt\}
  \leq \eta\,.
  \]

\begin{proof} 
From \eqref{eq:example-AMP-for-correlated-disorder} and the surrounding discussion, we have
        \begin{align}
         \nonumber
    & \frac{(\hat{\by}^{-1},\tilde{\by}^{-1})}{N}
    \simeq
    \upp
    \cdot
    \frac{(\hat{\bv}^{-2},\tilde{\bv}^{-2})}{M}
    \simeq
    \upp^2
    \cdot  \frac{(
    \hat{\by}^{-2},\tilde\by^{-2})}{N}  \\
    &\qquad\simeq 
    \dots
    \simeq
    \upp^{2(\linit-1)}
    \frac{(\hat{\by}^{-\linit},
    \tilde\by^{-\linit})}{N}
  \simeq
  \upp^{2(\linit-1)} \,.
  \end{align}
The claim follows.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:u-left-nonzero of arXiv:2602.07920, 'On the position matrix of single-shelf shuffle and card guessing'] Fix $i\in \mathcal{E}_n$. For $0\leq t\leq n-1$
\begin{equation}
  \widetilde{w}^{(i)}_t
  =
  \begin{cases}
    0, & t<i,\\[4pt]
    \displaystyle
    \frac{1}{t-i+1}\binom{t}{i}\,\frac{(n-1-i)!}{(n-1-t)!},
      & t\ge i.
  \end{cases}
\end{equation}
Then, $(\widetilde{w}^{(i)})^{\top}T=2^{-i}(\widetilde{w}^{(i)})^{\top}$. Furthermore, $\langle \widetilde{w}^{(i)}, {w}^{(j)}\rangle=\delta_{i, j}$ for any $i, j\in \mathcal{E}_n$.

