[Lemma 10 (Four-dimensional three-form algebra) of arXiv:2608.30638, 'On compact steady pluriclosed soliton surfaces'] Let $(V,g)$ be an oriented real four dimensional vector space endowed with a positive definite metric $g$. If $\theta$ is a one-form and
$H=-*\theta$, then for every vector $X\in V$,
\begin{equation}
 \iota_XH=-*(\theta\wedge X^\flat),
 \qquad
 H^2=2\bigl(|\theta|^2g-\theta\otimes\theta\bigr).
\end{equation}
Thus $H^2\geq0$ and, wherever $H\ne0$,
\begin{equation}
 \ker H^2=\{X:\iota_XH=0\}=\mathbb R\theta^\sharp.
\end{equation}

[Lemma 6.2 of arXiv:2507.06186, '2507.06186'] For every $\ka>0$, there exists some $\th_\ka>0$ such that
for every $m=1,2$ and $t\in(0,\th_\ka)$ the following sequences of random variables are uniformly integrable:
\[\big\{\msf T_{\ka,\eps}(t)^m\mr e^{-mt\msf c_{\ka,\eps}}:\eps>0\big\}
\qquad\text{and}\qquad
\big\{\msf M_{\ka,\eps}(t)^m\mr e^{-mt\msf c_{\ka,\eps}}:\eps>0\big\}.\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2608.29316, 'Powers of the Dirac Operator on $S^1\times S^{n-1}$'] Let $\m(V)$ and $\nu(V)$ be the eigenvalues of $\a^0A$ and $A\a^0$ on $V$ type $K=\spin(2)\times\spin(n)$ finite space, respectively. Then, with respect to the diagrams
\begin{equation*}
\setlength{\extrarowheight}{7pt}
\left(\begin{array}{cc}
\frac{\m(V_{NW})}{\m(V_O)}&\frac{\m(V_{NE})}{\m(V_O)}\\
\frac{\m(V_{W})}{\m(V_O)}&\frac{\m(V_{E})}{\m(V_O)}\\
\frac{\m(V_{SW})}{\m(V_O)}&\frac{\m(V_{SE})}{\m(V_O)}\\
\end{array}\right)\text{ and }
\left(\begin{array}{cc}
\frac{\nu(V_{NW})}{\nu(V_O)}&\frac{\nu(V_{NE})}{\nu(V_O)}\\
\frac{\nu(V_{W})}{\nu(V_O)}&\frac{\nu(V_{E})}{\nu(V_O)}\\
\frac{\nu(V_{SW})}{\nu(V_O)}&\frac{\nu(V_{SE})}{\nu(V_O)}\\
\end{array}\right),
\end{equation*}
we get
\begin{equation*}
\setlength{\extrarowheight}{7pt}
\left(\begin{array}{cc}
\frac{-f+J+1+r+\Xi\e/2}{-f+J+1-r-\Xi\e/2}&\frac{f+J+1+r-\Xi\e/2}{f+J+1-r+\Xi\e/2}\\
\frac{-f+1/2+r-\Xi\e J}{-f+1/2-r+\Xi\e J}&\frac{f+1/2+r+\Xi\e J}{f+1/2-r-\Xi\e J}\\
\frac{-f-J+1+r-\Xi\e/2}{-f-J+1-r+\Xi\e/2}&\frac{f-J+1+r+\Xi\e/2}{f-J+1-r-\Xi\e/2}
\end{array}\right)\text{ and }
\left(\begin{array}{cc}
\frac{-f+J+1+r-\Xi\e/2}{-f+J+1-r+\Xi\e/2}&\frac{f+J+1+r+\Xi\e/2}{f+J+1-r-\Xi\e/2}\\
\frac{-f+1/2+r+\Xi\e J}{-f+1/2-r-\Xi\e J}&\frac{f+1/2+r-\Xi\e J}{f+1/2-r+\Xi\e J}\\
\frac{-f-J+1+r+\Xi\e/2}{-f-J+1-r-\Xi\e/2}&\frac{f-J+1+r-\Xi\e/2}{f-J+1-r+\Xi\e/2}
