[Definition def:underline of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] Suppose that $f$ and $g$ are matrix-valued functions. Define
\begin{equation}
\underline{g(H)Hf(H)} := g(H)Hf(H)-\widetilde{\mathbb{E}}g(H)\widetilde{H}(\partial_{\widetilde{H}}f)(H) - \widetilde{\mathbb{E}}(\partial_{\widetilde{H}}g)(H)\widetilde{H}f(H),
\end{equation}
where $\widetilde{H}$ is an indepdent copy of $H$, $\widetilde{\mathbb{E}}$ denotes the partial expectation with respect to $\widetilde H$, and $(\partial_{\widetilde{H}}f)(H)$ denotes the directional derivative of the function $f$ in the direction $\widetilde H$ at the point $H$, i.e.,
\begin{equation}
[(\partial_{\widetilde{H}}f)(H)]_{xy} = (\widetilde{H}\cdot \nabla f(H))_{xy} := \sum_{\alpha,\beta\in \mathcal{I}}\widetilde{H}_{\alpha\beta}\frac{\partial f(H)_{xy}}{\partial H_{\alpha\beta}}.
\end{equation}

[Lemma compression2 of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $\zeta$ be a probability measure on $[0,1]$ with an $(n+1)$-atom prefix $\{0,q_1,\ldots,q_n\}$, where $0<q_1<\cdots<q_n<1$.
		Define $q_{ij}:=q_{\min(i,j)}$ for $i,j\in[n]$, and set
		\begin{equation*}
			\Delta_k :=
			\begin{cases}
				- \zeta(\{q_k\}) & \text{if } k \in [n-1],\\
				\zeta([0,q_n)) & \text{if } k = n.
			\end{cases}
		\end{equation*}
		Let $(\mathbf{m}^{(1)},\ldots,\mathbf{m}^{(n)})\in \mathrm{SUSY}_n(\zeta,\varepsilon)$, where $\mathrm{SUSY}_n(\zeta,\varepsilon)$ is as in Definition (def:susyreplicas of the paper), and define
		\begin{equation*}
			z^{(i)} :=- \sum_{k=1}^n \xi'(q_{ik})\, \Delta_k\, \mathbf{m}^{(k)},
			\qquad i \in [n].
		\end{equation*}
		Then for every $i,j\in [n]$,
		\begin{equation*}
			\langle z^{(i)}+\partial_m h_\zeta(q_i,\mathbf{m}^{(i)}),\,\mathbf{m}^{(j)}\rangle
			= N\,\xi'(q_{ij})\int_{q_j}^1 \zeta([0,t])\,\mathrm{d} t+O(N\varepsilon).
		\end{equation*}

[Defn def local solution' of arXiv:2411.01847, 'Well-Posedness of Stochastic Chemotaxis System'] We say that $(u,v,\tau)$ is a local mild solution to the system ((main2 of the paper)) if
	\begin{enumerate}
    \item$\tau$ is a stopping time, and $(u, v)$ is a progressively measurable stochastic process that takes values in $C(\bar{\mathcal{O}})\times W^{1,\infty}(\mathcal{O})$.

    \item There exists a non-decreasing sequence of stopping times $\{\tau_l, l \geq 1\}$ such that $\tau_l \uparrow \tau$ almost surely as $l \to \infty$, and for each $l$, the pair $(u(t), v(t))$ satisfies:
   \begin{align*}
    u(t) &= e^{-tA} u_0 - \int_0^{t} e^{-(t - s) A} \left( \nabla \cdot \left( \chi u(s) \nabla v(s) \right)-g(u(s))\right)\, ds\\
    &\quad + \sum_{i=1}^{\infty}b_i\int_0^t e^{-(t - s) A}\|u(s)\|_q^ru(s)  \, dW^i_s,\\
    v(t) &= G * u(t),
    \end{align*}
    for all $t \leq \tau_l$.
\end{enumerate}

[Proposition prop:ribbon of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let $X$ be the deformed Gaussian random matrix from Definition (def:inhomo of the paper), where $W_N$ is GOE ($\beta=1$) or GUE ($\beta=2$). Define
\begin{equation}
b_{m} = \begin{cases}
    \left(\frac{1}{2} - \frac{1}{k+1}\right)\binom{2k}{k}, & m=2k, \\
    0, & m=2k+1,
\end{cases}
\end{equation}
and for any diagram $\Gamma$,
\begin{equation}
    \mathfrak{F}_{\Gamma}(\{l_i\}) =
\sum_{\eta: V(\Gamma) \to [N]} 
\sum_{\substack{w_e \ge 1 \\ \sum_{e \in \partial D_j} w_e = l_j \ \forall j}}
\prod_{(x,y) \in E_{\mathrm{int}}} p_{w_e}(\eta(x), \eta(y))
\prod_{(z,w) \in E_{\mathrm{b}}} (A^{w_e})_{\eta(z) \eta(w)},
\end{equation}
with the convention that for each trivial diagram (i.e., a single isolated vertex), the contribution is \(N \delta_{l_i, 0}\). Here, the outer sum is taken over all vertex labelings \(\eta : V(\Gamma) \to [N]\).
Then for any integers $m_1,\dots,m_s \ge 0$,
\[
\mathbb{E}\left[ \prod_{j=1}^{s} \mathrm{Tr}(X^{m_j} + b_{m_j}\mathbf{I}) \right] =
{\sum_{\substack{0 \le l_j \le m_j \\ l_j \equiv m_j \!\!\!\!\pmod{2}}}}'
\prod_{j=1}^{s} \binom{m_j}{\frac{m_j - l_j}{2}}
\sum_{\Gamma \in \mathscr{D}_{s;\beta}} \mathfrak{F}_{\Gamma}(\{l_i\}),
\]
where in ${\sum}'$ the binomial coefficient is replaced by $\frac{1}{2}\binom{m_j}{m_j/2}$ if $l_j = 0$.

[Definition 25 of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] A measurable function \(f:(0,+\infty)\mapsto (0,+\infty)\) is said to be

\begin{itemize}
\item
  \emph{slowly varying} at \(+\infty\) when

  \begin{equation*}{
  \forall \lambda>0,\ \frac{f(\lambda x)}{f(x)} \xrightarrow[x \to \infty]{} 1;
  }\end{equation*}
\item
  \emph{regularly varying with index \(\beta \in \R\)} (or
  \emph{\(\beta\)-varying}) at \(+\infty\) when

  \begin{equation*}{
  \forall \lambda>0,\ \frac{f(\lambda x)}{f(x)} \xrightarrow[x \to \infty]{} \lambda^{\beta},
  }\end{equation*}

  or equivalently when \(x \mapsto x^{-\beta}f(x)\) is a slowly varying
  function at \(+\infty\).
\end{itemize}

