[Theorem thm:stein of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Let $X$ be as in (equation eq:tilt of the paper) and $f : \mathbb{R}^N \to \mathbb{R}$ be some function satisfying $\mathbb{E}[f(X)] = 0$.
Define $b, \delta_0, \delta_1, \delta_1', \delta_2, \delta_3$ as above, and let $Z \sim \mathcal{N}(0,1)$.
Then we have
\begin{align}
    \mathbf{d}_\mathrm{Was}(f(X),Z) &\leq \frac{C}{|b|} \mleft(\delta_0 + \delta_1 + \delta_2 + \delta_3\mright), \\
    \text{and} \qquad \mathbf{d}_\mathrm{Kol}(f(X),Z) &\leq \frac{C}{|b|} \mleft(\delta_0 + \delta_1' + \delta_2 + \delta_3\mright),
\end{align}
for some absolute constant $C$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 6 (Exact ordered tuple formula) of arXiv:2608.04799, '2608.04799'] If \(K\le n\) and
\(k_i+r_i-1\le\binom{k_i}{2}\) for every \(i\), then
\begin{equation}
  L_n(\mathbf k,\mathbf r)=\frac{(n)_K}{\prod_{i=1}^q k_i!}\prod_{i=1}^q c(k_i,k_i+r_i-1)\,p_n^{K+R-q}(1-p_n)^{A},
\end{equation}
where
\begin{equation}
\begin{aligned}
  A
  &=K(n-K)
    +\sum_{1\le i<j\le q}k_ik_j
    +\sum_{i=1}^q
      \left\{\binom{k_i}{2}-(k_i+r_i-1)\right\}
  \\
  &=Kn-\frac{K^2}{2}-\frac{3K}{2}-R+q.
\end{aligned}
\end{equation}
If the feasibility conditions fail, then \(L_n(\mathbf k,\mathbf r)=0\).

[Proposition prop:Q_path_expansion of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Define  a family of  polynomials $\mathcal{Q}_n(x)$ recursively by
\begin{equation} 
\mathcal{Q}_0(x) = 1, \quad
\mathcal{Q}_1(x) = x - 1, \quad
\mathcal{Q}_n(x) = (x - 1 - \alpha)\mathcal{Q}_{n-1}(x) - \alpha \mathcal{Q}_{n-2}(x) \quad (n \ge 2),
\end{equation}
with the convention that $\mathcal{Q}_n(x) = 0$ for $n < 0$. Then for $X = (H+A)(H+A)^*$ and  for each $n \ge 0$, we have
\begin{equation}
\mathcal{Q}_n(X)
= \sum_{k \ge 0} \sum_{\alpha \in \{2,3,A,A^*\}^k} \sum_{\substack{\ell_0 + \cdots + \ell_k = 2n}}
V_{\ell_0}\,\underline{\Phi_{\alpha_1} V_{\ell_1}} \cdots \underline{\Phi_{\alpha_k} V_{\ell_k}}.
\end{equation}
Here, each $\alpha_i$ denotes insertion of $\Phi_2$, $\Phi_3$, $\Phi_A$, or $\Phi_{A^*}$, and the indices satisfy $\ell_i \ge 0$ with $\sum \ell_i = 2n$.

