[Thm 5 of arXiv:2605.05986, '\bf Convergence rate of the occupation measure of { classes of ergodic processes toward th'] Let $(X_t)_{t\ge0}$ denote an $({\cal F}_t)_{t\ge0}$-adapted right continuous  process with values in $\ER^d$. Let $q>1$, $\gamma\in(0,1/2]$, {$\nu\in{\cal P}(\ER^d)$},  and a bounded function $e:\ER_+\rightarrow\ER_+$ such that

\begin{equation}
\ATROIS\quad\begin{cases} (i)\;  \|{\cal L}(X_{t}|{\cal F}_s)-\nu\|_{TV}\le \Upsilon_{t,s} \,\ee(t-s)\;\mbox{  for all $s$, $t\!\in \R_+,\;0\le s\le t$},\\
(ii)\; \int_0^t e(s)ds \le O( t^{1-2\gamma})<+\infty \mbox{ as }t\to+\infty,  \\
(iii)\; C_q=\sup_{t\ge 0}\big(\sup_{s{\le}  t} \E\, \Upsilon_{t,s}^{q}+{\sup_{t\ge0}\E\,|X_t|^{q}}\big)<+\infty,
\end{cases}
\end{equation}
where, for  every $s\ge 0$, $\big(\Upsilon_{t,s}(\omega))_{ \omega�\in \Omega, t\ge s}$ denotes a  family of  ${\cal B}or\big([s,+\infty)\big)\otimes{\cal F}_s$-measurable   non-negative random variables. 

Then $\nu(|\cdot|^q)<+\infty$  and

$\AUNgamma$ holds  for every $\tzero>0$ with $\beta=\beta(q)=\frac 12 (1-\frac{1}{q})$, $\pi_t=\frac{1}{2}(\bar \nu_t+\nu)$. Thus, 
for every $\tzero>0$,  there exists a positive constant $K= K_{b,\s,p,d,t_0}$ such that, for every $t\ge \tzero$, 

\begin{equation}
\E\, {\cal W}^p_p(\nu_t,\nu) \le K {\Mpiq}\left\{ \begin{array}{ll}
		t^{-\frac{{2\gamma} pq}{(q+1)d}}\mbox{\bf 1}_{\{p< \frac{dq}{d+q}\}}+t^{-\frac{{2\gamma}(q-p)}{q+1}}\mbox{\bf 1}_{\{  \frac{dq}{q+1}<p<q\}} &\mbox{if  $\,p< \frac{d}{2}(1+\frac 1q)$},\\
		t^{-\frac{{2\gamma}(q-p)}{q+1}} \mbox{\bf 1}_{\{d_-<q<d_+\}} + t^{-{\gamma}}\log(1+t) \mbox{\bf 1}_{\{d_+<q\}}& \mbox{if  $\,p= \frac{d}{2}(1+\frac 1q)$},\\
		 t^{-{\gamma}}\mbox{\bf 1}_{\{\frac{d}{2}\frac{q+1}{q}<p<\frac{q-1}{2}\}}+t^{-\frac{{2\gamma}(q-p)}{q+1}}\mbox{\bf 1}_{\{\frac{q-1}{2}<p<q\}}	&\mbox{if  $\,p>\frac{d}{2}(1+\frac 1q)$,}








			\end{array}\right.
\end{equation}
where $d_-:= \frac{d+\sqrt{d^2+8d}}{4}<d_+ := \frac{d+1+\sqrt{(d+1)^2+4d}}{2}$ and  ${\Mpiq}$ satisfies ${\Mpiq} \le 1\vee \sup_{t\ge t_0}\E\,|X_t|^{q}$. 

 In particular, if $C_q<+\infty$ for any $q>0$, then for every $d\in\mathbb{N}^*$, $p>0$ and $\varepsilon>0$, a finite positive constant $\bar{K}= \bar{K}_{p,\ve}$ exists such that
\begin{equation}
\big\| {\cal W}_p(\nu_t,\nu) \big\|_p\le \bar{K}     
							\left\{ \begin{array}{ll}
 t^{-\frac{{2\gamma}}{d}(1-\ve)}&\mbox{ if $p\le \frac d2$}\\
t^{-\frac{{\gamma}}{p}} &\mbox{ if $p>\frac d2$}.
							\end{array}\right.
\end{equation}
In the sequel,~\eqref{eq:toutunbis} will be shortly (and slightly abusively) written:
$$
\big\| {\cal W}_p(\nu_t,\nu) \big\|_p\lesssim t^{-{2\gamma}\left(\frac{1}{2p}\wedge\left(\frac{1}{d}\right)^{-}\right)}.
$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 5 of arXiv:2608.01419, 'A model of opinion dynamics evolving via a preferential attachment mechanism involving mul'] Recall the model described in \S\ref{subsec:model_growing_sample_size}, and assume that 
\begin{equation}_sequence_conditions}
\sum_{n\geqslant N}\frac{k_{n}}{s_{n+1}}\text{ diverges}, \sum_{n\geqslant N}\frac{k_{n}^{2}}{s_{n+1}^{2}}\text{ converges, and }0<\eta_{1}=\inf_{n\geqslant N}\frac{s_{n+1}}{(n+1)k_{n}}\leqslant\sup_{n\geqslant N}\frac{s_{n+1}}{(n+1)k_{n}}=\eta_{2}<\infty,
\end{equation}
where $s_{n}$ is as defined in \eqref{beta_{n}_s_{n}_defns}. Assume that one of the following is true:
\begin{enumerate}[label=(A\arabic*), ref=A\arabic*]
\item When $g$ is Lipschitz on $[0,1]$, each of the series $\sum_{n\geqslant N}(n+1)^{-1}k_{n}^{-1/2}$ and $\sum_{n\geqslant N}s_{n+1}^{-1}k_{n}^{1/2}$ converges.
\item When $g\in\mathcal{C}^{(1)}[0,1]$, each of the series 
\begin{equation}
\sum_{n\geqslant N}(n+1)^{-1}k_{n}^{-1/2}\omega_{g'}(k_{n}^{-1/2}),\ \sum_{n\geqslant N}s_{n+1}^{-1}k_{n}^{1/2}\omega_{\varphi'}(k_{n}^{-1/2}) \text{ and }\sum_{n\geqslant N}s_{n+1}^{-1}k_{n}^{1/2}\omega_{\psi'}(k_{n}^{-1/2})_convergence_criteria}
\end{equation}
converges, where $\varphi(x)=xg(x)$ and $\psi(x)=xg(x)+(1-x)\{1-g(x)\}$ for all $x\in[0,1]$. If each of $\sum_{n\geqslant N}s_{n+1}^{-1}$ and $\sum_{n\geqslant N}s_{n+1}^{-1}k_{n}^{1/2}\omega_{g'}(k_{n}^{-1/2})$ converges, then so do the second and third series of \eqref{C^{1}_convergence_criteria}.
\item When $g\in\mathcal{C}^{(2)}[0,1]$, each of the series $\sum_{n\geqslant N}(n+1)^{-1}k_{n}^{-1}$ and $\sum_{n\geqslant N}s_{n+1}^{-1}$ converges.
\end{enumerate}
Then the sequence $\{(n^{-1}A_{n},s_{n}^{-1}B_{n},s_{n}^{-1}C_{n})\}$ converges almost surely to a (possibly path dependent) compact, connected, internally chain transitive invariant set, contained in $\hat{\mathcal{S}}$, corresponding to the differential inclusion $(\dot{a}(t),\dot{b}(t),\dot{c}(t))\in F(a(t),b(t),c(t))$ for $t\geqslant 0$, where we define, using \eqref{hat{h}_defn_growing_size}: 
\begin{equation}
F\left(\begin{bmatrix}
a\\
b\\
c
\end{bmatrix}\right)=\left\{\begin{bmatrix}
\eta\hat{h}_{1}(a,b,c)\\
\hat{h}_{2}(a,b,c)\\
\hat{h}_{3}(a,b,c)
\end{bmatrix}:\eta\in[\eta_{1},\eta_{2}]\right\}, \text{ for each }\begin{bmatrix}
a\\
b\\
c
\end{bmatrix}\in\hat{\mathcal{S}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:first-shell of arXiv:2608.29403, 'Kac's Walk on Rotation Matrices Mixes in $\boldsymbol{\Theta(n^2)}$ Steps:\\ A Proof Disco'] Assume $n\ge4$ and $m\le cN$, where $c\ge1$.  The expectation is over
both the independent uniform coordinate planes and their independent
uniform angles.  Then
\[
 \boxed{
 \mathbb E\|\mathcal C_1\|^2
 \le \frac{2n(n-1)}{n+2}(c^2+2c)
 \le 2n(c^2+2c).}
\tag{3.2.9a}
\]

