[Lemma discretization estimates for function powers of arXiv:2411.05924, 'Non-negative Martingale Solutions to the Stochastic Porous Medium Equation with Sticky Beh'] There exists a constant $C > 0$, independent of $n\in\mathbb N$, such that for any $\mathbf u_n \in \mathbb R^n_+$, $\theta\in[0,1]$, and $\mu \geq 1$ it holds
    \[
        \begin{aligned}
            \left\| \mathfrak P^{-1}_n (\mathbf u_n)^\mu \right\|_{H^\theta_0} \leq C \left\| \mathfrak P^{-1}_n (\mathbf u_n^\mu) \right\|_{H^\theta_0}.
        \end{aligned}
    \]

[Definition def:kernel of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] For $t, u \in \mathbb{R}$ and parameters satisfying
Assumption~(ass:params of the paper), the \emph{regularized kernel of $n$-MFSM}
is
\begin{equation}

f_n(t,u;H,\alpha)
:= \frac{1}{\Gamma(\gamma(t)+1)}
\left[
(t-u)_+^{\gamma(t)}
- \sum_{k=0}^{n-1}\frac{t^k}{k!}\,(-u)_+^{\gamma(t)-k}
\prod_{j=0}^{k-1}\bigl(\gamma(t)-j\bigr)
\right],
\end{equation}
where $x_+ := \max\{x,0\}$ with $0_+^0 := 1$, and the empty product
(for $k=0$) equals $1$.

[Lemma our_B5 of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] There exists a finite constant $C_0$ that depends on $R^{\pm}$ and $l$ such that 
    \begin{equation}
    \begin{split}
    &\int_0^t\int_0^1\frac{(\nabla\rho_s)^2}{\sigma(\rho_s)}dx\;ds+\int_0^t\Big|F_{-}(\rho_s(0))\log\Big(\frac{\rho_s(0)}{1-\rho_s(0)}\Big)\Big|\;ds\\
    &+\int_0^t\Big|F_{+}(\rho_s(1))\log\Big(\frac{\rho_s(1)}{1-\rho_s(1)}\Big)\Big|\;ds\leq C_0 t+\int_0^1 V_0(\gamma)\;dx-\int_0^1 V_0(\rho_t)\;dx,
    \end{split}
    \end{equation}
    where $V_0(x)=x\log(x)+(1-x)\log(1-x).$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem HT comp of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] For each $a > 0$ and $t > 0$, set 
  \begin{equation}
    F(a,t)
    \coloneqq 
    \left\{ s \in \supp \mathcal{C}_t \,\middle |\,
    \varlimsup_{\delta \downarrow 0}
    \frac{\mathcal{C}_t([s-\delta,s+\delta])}{\Psi_{\mathrm{ct}}(\delta)}
    < a\right\}.
  \end{equation}
  Then, for all sufficiently small $a > 0$, $\mathcal{H}_{\Psi_{\mathrm{ct}}}(F(a,t)) = 0$ for all $t > 0$,
  $\hat{P}_{\bm{\rho}}$-a.s.

[Theorem thm:combined-early-late-numerical-time of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $\rho,c,q,C_X,L_f,C_{\mathrm{Loj}},C_{\mathrm{dec}}
\in(0,\infty)$. Set
\bas{
\textcolor{magenta}{
  \eta
  =
  [
    2 C_{ \mathrm{Loj} } ( C_X + 1 )
  ]^{ - 1 }
}
  .
}
Then there exist $ C_0, C_1 \in (0,\infty) $ such that the following is true.

Let $ \beta \in [ \nicefrac{ 1 }{ 2 }, 1 ) $,
$ \varepsilon \in [ 0, 1 ] $ satisfy
\bas{
\textcolor{magenta}{
  q+3\ln\beta\ge\rho
}
  .
}
Let $V\subseteq{\mathbb R}^d$ be measurable, let $(X,U)$ be $(c,q)$-regular on
$V$ in the sense of (def:regular of the paper) and assume for every
$\theta\in V$, $i\in\{1,\dots,d\}$ that
\bas{
\textcolor{magenta}{
  \| X^{ (i) }( \theta, U ) \|_{ L^{ \infty } } \le C_X
}
  .
}
Let $ F \colon {\mathbb R}^d \to [0,\infty) $ have a globally $ L_f $-Lipschitz continuous
derivative and assume for every $\theta\in V$ that
\bas{
\textcolor{magenta}{
  f_X(\theta)=-\nabla F(\theta)
}
\qquad
\text{and}
\qquad
\textcolor{magenta}{
  F(\theta)\le C_{\mathrm{Loj}}|f_X(\theta)|^2
}
  .
}
Let $ ( \gamma_n )_{ n \in {\mathbb N} } $ be decreasing and $ (0, C_{ \mathrm{Loj} } (C_X + \varepsilon) ] $-valued and

assume for every $ j, n \in {\mathbb N} $ with $ 1 < j \le n $ that
\bas{
\textcolor{magenta}{
  \gamma_j
  \le
  \gamma_n
  C_{\mathrm{dec}}
  \exp\bigl(
  \textstyle
    \frac{ \eta }{ 2 } \sum_{ k = j + 1 }^n \gamma_k
  \bigr)
}
  .
}
Let $ \theta_0 \in {\mathbb R}^d $ and let $(\theta_n)_{n\in{\mathbb N}_0}$ be the \RMSprop\
algorithm driven by $(X,U)$ with parameter tuple
$(\beta,\varepsilon,(\gamma_n)_{n\in{\mathbb N}},\theta_0)$ defined above.
Define
$
  \tau = \inf\{ n \in {\mathbb N}_0 \colon \theta_n \notin V \}
$.
Then one has for every $ n \in {\mathbb N} $ that
\bas{

\textcolor{magenta}{
  {\mathbb E}\bigl[
    F(\theta_n)
    \1_{ \{ \tau \ge n \} }
  \bigr]
\le
  \exp\bigl(
  \textstyle
    - \eta \sum_{ k = 2 }^n \gamma_k
  \bigr)
  \,
  \bigl[
    F( \theta_0 )^{ 1 / 2 }
    +
    \gamma_1
    ( 2^{ - 1 } L_f d )^{ 1 / 2 }
  \bigr]^2
  + C_0 \gamma_n
  + C_1 ( 1 - \beta)^2
}
  .
} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lm 14 of arXiv:2609.02576, 'Sharp estimates for the Jacobi and trigonometric Dunkl heat kernels'] Let $t\geq 1$ and $0<y\le x<\infty$ be such that $x\le 2t$. The following identity holds:
	\begin{equation}
		\frac{D H_t^{\psi_2^+}(x,y)}{H_t^{\psi_2^+}(x,y)}=I_1(x,y,t) +I_2(x,y,t),
	\end{equation}
	where $|I_1(x,y,t)|\lesssim t^{-3/2}$ and $I_2(x,y,t)\geq 0$.

