[Lem decconditions of arXiv:2412.09535, 'Local limit theorem for joint subgraph counts'] Suppose there is a nonempty subset $\mathcal{H}' \subseteq \mathcal{H}$ and some $\eps > 0$ such that
\begin{cond}
    \item  \label[scond]{scond:g1} We have one of the following:
    \begin{cond}
        \item  \label[scond]{scond:g1a} $\Delta^2_H N_{H, e} \leq n^{-\eps}$ for all $H \in \mathcal{H}'$ and $e \in A$;
        \item  \label[scond]{scond:g1b} For $e \in A$ we always have
        \[\abs*{\sum_{H \in \mathcal{H}'} \Delta_H \;\smashoperator{\sum_{\substack{H'\cong H \\ E(H') \cap A = \set{e}}}} \zeta_{E(H') \setminus A}} \leq 1.1\pi\sqrt{p(1-p)}.\]
    \end{cond}
    \item  \label[scond]{scond:g2} $\sum_{H \in \mathcal{H}'} \sum_{e \in A} \Delta^2_H N_{H, e} \geq n^\eps$;
    \item  \label[scond]{scond:g3} $\sum_{e \in A}  \Delta^2_H N_{H, e} \leq n^{-\eps}$ for all $H \in \mathcal{H} \setminus \mathcal{H}'$;
    \item  \label[scond]{scond:g4} $\sum_{\abs{S} \geq 2} \Delta^2_H N_{H, S} \leq n^{-\eps}$ for all $H \in \mathcal{H}$;
    \item  \label[scond]{scond:g5} We have
    \[\sum_{(H_1,H_2,H_3,H_4) \in Q} \Delta_{H_1}\Delta_{H_2}\Delta_{H_3}\Delta_{H_4} \leq n^{-\eps} \paren*{\sum_{H \in \mathcal{H}'} \sum_{e \in A} \Delta^2_H N_{H, e}}^2,\]
    where $Q$ is the set of quadruples $(H_1,H_2,H_3,H_4)$ of subgraphs such that
    \begin{cond}
        \item  \label[scond]{scond:g5a} $H_1, H_2, H_3, H_4$ are isomorphic to elements of $\mathcal{H}'$ and are rainbow ($\Delta_{H_i}$ denotes $\Delta_H$ where $H\in\mathcal{H}'$ is isomorphic to $H_i$);
        \item  \label[scond]{scond:g5b} $E(H_1) \cap A = E(H_2) \cap A = \set{e}$ for some $e \in A$;
        \item  \label[scond]{scond:g5c} $E(H_3) \cap A = E(H_4) \cap A = \set{e'}$ for some $e' \in A$;
        \item  \label[scond]{scond:g5d} $(E(H_1) \cup E(H_2)) \cap (E(H_3) \cup E(H_4))$ is nonempty;
        \item  \label[scond]{scond:g5e} No edge lies in exactly one of the $E(H_i)$.
    \end{cond}
\end{cond}
Then $\sete_{G(n,p)}[e^{if}] = n^{-\omega_{\lambda,\ell,\eps}(1)}$.

