[Prop Quantitative Approximation Probability  of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] For any fixed $k$, there exist constants $C(T,k), C'(T,k)$ such that
    \begin{equation*}
        \mathbb{P}\bigg(\sup_{t \in [0,T]}|a_j^{(n)}(t)-\tilde{a}_j^{(n)}(t)|>C(T,k)\frac{\log(n)^j}{\sqrt{n}} \text{ for some } j\leq k\bigg) < C'(T,k)n^{-2},
    \end{equation*}
    and
    \begin{equation*}
        \mathbb{P}\bigg(\sup_{t \in [0,T]} \frac{1}{\sqrt{n}}|b_j^{(n)}(t)^2-\tilde{b}_j^{(n)}(t)^2|>C(T,k)\frac{\log(n)^{2j}}{\sqrt{n}} \text{ for some } j \leq k\bigg) < C'(T,k)n^{-2}.
    \end{equation*}

