[Prop 10 of arXiv:2604.24189, 'Malliavin calculus and densities for chaos-driven stochastic differential equations'] Let $F=\{F_t=(I_q(f_t^1),\ldots,I_q(f_t^m))\,,\;t\in \R_+\}$ be an $\R^m$-valued chaos process on an abstract Wiener space $(\Omega,\mathcal{F},\P,\mathfrak{H})$, and assume that $F$ satisfies hypothesis $\mathbf{(H_2)}$ with $H\in(\tfrac{1}{2},1)$.
	Let $R=\{R^h_{t,\varepsilon}\,;\;t\in\R,\, \varepsilon\in\R,\, h\in\HHH\}$ and $S=\{S^{h}_{t,\varepsilon}\,;\;t\in\R,\, \varepsilon\in\R,\, h\in\HHH\}$ be the $\R^m$-valued stochastic processes defined, respectively, by
 \begin{align}
	R_{t,\varepsilon}^h=F_t(\bullet + \varepsilon\,j(h)) \quad \text{ and } \quad S^{h}_{t,\varepsilon} = \sum_{k=0}^{q}  \frac{\varepsilon^k}{k!}\langle D^k F_t,h^{\otimes k} \rangle_{\mathfrak{H}^{\otimes k}}.
 \end{align}
Then the following hold:
\begin{enumerate}[(a)]
	\item $S$ is a version of $R$;
	\item for every $h\in \HHH$, almost every $\omega\in\Omega$ and every $\varepsilon\in\R$, one has $S^{h}_{\star,\varepsilon}(\omega)\in W_{2}^{1-\alpha}\left(0, T ; \mathbb{R}^{m}\right)$;
	\item for every $\beta\in(0,H-\tfrac{1}{2})$ and $1-\alpha = H-\beta$, and for almost every $\omega\in\Omega$, the map from $\R$ into $W_{2}^{1-\alpha}\left(0, T ; \mathbb{R}^{m}\right)$ defined by $\varepsilon\mapsto S^{h}_{\star,\varepsilon}(\omega)$ is of class $\mathcal{C}^{\infty}$. Moreover, for every $h\in \HHH$, almost every $\omega\in\Omega$, every $\varepsilon\in\R$ and every $\ell \in \N$,
	$$
\frac{d^\ell}{d\varepsilon^\ell} S^{h}_{\star,\varepsilon}(\omega)= \left\{
\begin{array}{lcl}
\sum_{k=l}^{q}\frac{\varepsilon^{k-l}}{k!} \left<D^kF_\star(\omega) ,h^{\otimes k}\right>_{\HHH^{\otimes k}}, & \text{if }& 0 \leq \ell \leq q\\
0,&  \text{if }& \ell >q.
\end{array}\right.
$$
\end{enumerate}

[Lem typT poly UB of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] For any $\ell \in \mathbb{N}$ and $a \in (0,\infty)$,
  \begin{equation}
    \sup_{\bm{x} \in M^k}
    \hat{P}_{\bm{x}}\!\left(C_{\delta_\ell} \geq a \Psi_{\mathrm{ct}}(\delta_\ell)\right) 
    \leq 
    \tilde{c}_1 \ell^{-\tilde{c}_2 a^{2/\hat{d}_{\mathrm{s}}^*}}.
  \end{equation}

[Proposition 11 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] $F$ is $r$-semicontinuous if and only if the common order and uo closure of $\Ba_{F}$ is contained in $r\Ba_{F}$. Moreover, the following conditions are equivalent:
\item[(i)] $F$ is topologically semicontinuous;
\item[(ii)] The norm topology is semicontinuous;
\item[(iii)] The common order and uo closure of $\Ba_{F}$ is norm bounded;
\item[(iv)] Order closure preserves norm bounded sets;
\item[(iv')] Uo closure preserves norm bounded sets.

[Lem 18 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] For every $n \in \mathbb{N}_+$, it holds
\begin{align} 
 \sup_{r \in [0,T]} \Bigg\{ \frac{1}{n} \sum_{x} \big[  \widehat{\mathbb{L}}_{n, \lambda}^{ \gamma} H ( \tfrac{x + q_n^r }{n}  ) \big]^{2}  \Bigg\} \leq | \lambda| K_n C(\gamma,H).
\end{align}
Moreover, if $H \in C_c^{2}(\mathbb{R})$, then the role of $C(\gamma,H)$ above is fulfilled by some constant $C(H)$ satisfying \eqref{Cinvshift}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] For  $\mathsf{P}_i\in \mathcal P_{s,1}(\Gamma)$, $i=0,1$ we denote by $ \mathsf{Cpl}_{s,m}(\mathsf{P}_0,\mathsf{P}_1)$ the set of all $\sigma$-finite stationary  (with respect to the shifts $(\theta_x)_{x\in \IR^2}$) measures  $ \mathsf{Q}$ on $\Gamma_{\IR^2}$ such that:
    \begin{itemize}
        \item[i)] The Palm measure $ \mathsf{Q}^0$ of $ \mathsf{Q}$  is a probability measure and $(\mathrm{Pr}^{\Gamma}_i)_{\#} \mathsf{Q}^0=\mathsf{P}_i^0$ for $i=0,1$.
        \item[ii)]  The measure $ \mathsf{Q}$ is concentrated on the set of monotone configurations $\bar\xi\in \Gamma_{\IR^2}$.
    \end{itemize}

[Lem 9 of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] For all $p \in (0,1)$,
\begin{align*}
    p(1-p)\sqrt{\frac{2\beta_p}{1 - 2p}} \le \frac{1}{2},
\end{align*}
with equality if and only if $p = 1/2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

