body:
[Theorem 14 of arXiv:2606.31596, 'The Invariant Measure of Multiscale Markov Chains via Fast Arborescence Factorization'] Let $x \in \hat V$. The weight of the set $\mathcal T_{x}$ of arborescences of $(V,E)$ and the reduced weight of the set $\hat{\mathcal T}_{x}$ of arborescences of $(\hat V,\hat E)$ are related by:
\begin{equation} 
	r\left(\mathcal{T}_x\right) = r\left(\mathcal{F}_{\hat V}\right)\, \hat{r}\left(\hat{\mathcal{T}}_x\right)
\end{equation}
where $\mathcal{F}_{\hat V}$ denotes the collection of spanning forests of $(V,E)$ with root set $\hat V$.

[Lemma lem:dotG of arXiv:2411.07157, 'Rough differential equations in the flow approach'] For every $N\in\N$, we have
\begin{equs}        
    \norm{\mathcal{P}_{N,\mu}\dot G_\mu}_{\mathcal{L}^{p,\infty}}&\lesssim \mu^{-1/p}\;\mathrm{for}\;\mathrm{all}\;p\in[1,\infty]
    \end{equs}
uniformly in $\mu\in(0,1]$.

[Lemma 38 of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] Given $k\ge \ell\ge 1$, $\sigma\in(0,1/10)$ and $f\in C_\cc(\R^{\ell})$ let
\begin{equation}

\Xi_k(f):=E\Biggl(f\Bigl(\{X_j+j\slb\}_{j=1}^{\ell}\Bigr)\biggl(\,\prod_{j=1}^{k} \wt P(M_{j}'\le t)|_{t:=X_j+j\slb}\biggr)\,1_{\{X_k\in[k^{\sigma},k^{1-\sigma}]\}}X_k\Biggr),
\end{equation}
where~$X$ is the random walk with step distribution $\NN(0,1/2)$. Let~$\delta\in(0, 1/2)$. Then $\epsilon_{n,k}(u,f)$ defined for each~$u>0$ and $n\ge k$ by
\begin{equation}

E_{Q_{n,u,u}}\Bigl(f\bigl(\{h(x_0)-h(x_j)\}_{j=1}^\ell\bigr)\Bigr)=\frac{4u}n\Xi_k(f)+\frac un\epsilon_{n,k}(u,f)
\end{equation}
obeys
\begin{equation}

\lim_{k\to\infty}\limsup_{n\to\infty}\sup_{n^{\delta}\le u\le n^{1-\delta}}\bigl|\epsilon_{n,k}(u,f)\bigr|=0.
\end{equation}
Moreover, writing $1$ for the constant function equal to~$1$, we have
\begin{equation}

0<\inf_{k\ge1}\Xi_k(1)\le\sup_{k\ge1}\Xi_k(1)<\infty.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:main_thm of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] For the matrix  $X_N=\Sigma_N \circ W_N +A_N$ as in Definition (def:inhomo of the paper), let $r$ be any fixed nonnegative integer and $0 \leq q \leq r$, assume that eigenvalues of $A_N$ satisfy   
        \begin{equation}
            a_j = 1 + \tau_j N^{-\frac{1}{3}}, \quad\tau_j \in \mathbb{R},\quad j=1,\ldots,q, 
        \end{equation} 
        and   
        \begin{equation}
           a_j \in (-1,1),  \quad j=q+1,\ldots,r.
        \end{equation} 
          If Markov chain   $([N],P_N)$ satisfies  the Short-to-Long Mixing conditions (itm:B1 of the paper) and (itm:B2 of the paper) with $\theta\, t_N\ll N^{\frac{1}{3}}$, then the first $k$ largest  eigenvalues of $X_N$ 
converge   in distribution  to those of  deformed GOE/GUE matrix. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 25 of arXiv:2608.19065, 'Boundedly exchangeable graphs'] Let $B, C \in \widehat{\Bcal}(S)$ be disjoint such that $\pbb(\nu(B) = 0) < 1$ and $\pbb(\nu(C) = 0) < 1$, and let $A^{B \cup C}$ be a jointly exchangeable matrix associated with $\xi$ on $B \cup C$. Then there exist a random partition of $\nbb$ into subsequences $(b_i)$ and $(c_i)$ such that a.s.\
    \begin{align*}
        A^B_{ij} &\coloneqq A^{B \cup C}_{b_ib_j}, \\
        A^C_{ij} &\coloneqq A^{B \cup C}_{c_ic_j}
    \end{align*}
    are jointly exchangeable matrices associated with $\xi$ on $B$ and $C$, respectively. Moreover, the matrix $A^{BC}_{ij} \coloneqq A^{B \cup C}_{b_ic_j}$ is separately exchangeable.

[Defn d:connective-constant-pp of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] For a graph $\Psi = \Psi(\cdot)$ on the input process $\mathcal{P}$, the  
 {\em averaged connective constant} $\bar{\Delta} \in [0,\infty]$
is defined as 
\begin{equation}
\bar{\Delta} := \inf\Bigl\{\delta\ge 0: \forall\, p \in \mathbb{N} \;  \exists \, m_p \in \mathbb{N} \text{\ such that for all $m\ge m_p$}, \,
\mathfrak{n}_{p}(m)\le \delta^m\Bigr\},
\end{equation}
where \begin{equation}
\mathfrak{n}_p(m):=\sup_{B\in\mathcal{B}_b(r_0,n_0)}\sup_{x_1,\ldots, x_p\in B}
  \mathbb {E} _{\bk x1p}[N(x_1, m; \Psi(\mathcal{P}\cap B))],
\end{equation}
 with \(N(x_1, m;\Psi(\mathcal{P}\cap B))\) being the number of  self-avoiding paths of length \(m\) starting from \(x_1 \in \mathcal{P} \cap B\) in  $\Psi(\mathcal{P}\cap B)$, where $\mathcal{B}_b(r_0,n_0)$, defined in~(equation e.particular-sets of the paper), are the sets of the form large windows
$W_n$, possibly intersected with finite unions of balls of sufficiently large
radius.

[Proposition prop:cp-upper of arXiv:2607.00731, 'Sharp Asymptotics for the Largest Component in the Subcritical Regime of Preferential Atta'] Let $(d_n)_{n\ge 1}$ be deterministic degree sequences, and write
\(\ell_n = \ell(\mathbf d_n)\), \(D_n = D_{\mathbf d_n}\),
\(\Delta_n = \Delta(\mathbf d_n)\), and \(\phi_n = \phi_{\mathbf d_n}\).

Assume that:
\begin{enumerate}
\item $D_n \Rightarrow D$ for some random variable \(D\) taking values in \(\mathbb Z_{\ge0}\);
\item $Q(d_n)\to 0$;
\item $\mathbb P(D=0)>0$ and $\mathbb P(D=1)>0$;
\item $\mathbb P(D_n=0)>0$ and $\mathbb P(D_n=1)>0$ for all large $n$;
\item $\mu_4(d_n)\le \Delta_n^{1/2}$ and $\Delta_n\le n^{1/6}$ for all large $n$.
\end{enumerate}
Assume further that, for all large $n$, the equation $\phi_n'(\theta)=0$ has a smallest positive solution $\theta_n\in(0,1)$, and define
\begin{equation}
T_n:=\frac{1}{-\log\phi_n(\theta_n)}
\left[
\log n+\frac{3}{2}\log\bigl(-\log\phi_n(\theta_n)\bigr)
-\frac12\log\phi_n''(\theta_n)
+\log\mathbb E\!\left(D_n e^{\theta_n D_n}\right)
\right].
\end{equation}
If $\theta_n\ell_n/T_n\to\infty$, then for every fixed $\delta>0$,
\begin{equation}
\mathbb P\bigl(L_1(\mathrm{CM}(d_n))\le (1+\delta)T_n\bigr)\to 1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:mixing of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Let $\Lambda^*$ and $\eta,\gamma > 0$ be, respectively, the set and constants given in
Proposition (prop:goodset of the paper).
Suppose $x \in \Lambda^*$ and $x' \in \Omega$ with $\mathbf{d}_\mathrm{Ham}(x,x') = 1$.
Under the monotone coupling of the $\mu_\mathsf{H}^\eta(n,p)$ Glauber dynamics, for all $t \leq e^{\gamma n}$,
\begin{equation}
    \mathbb{E}\mleft[\mathbf{d}_\mathrm{Ham}(X_t^x,X_t^{x'})\mright] \leq \mleft(1-\frac{\kappa}{n^2}\mright)^t + e^{-\Omega(n)}.
\end{equation}
In particular, for all $t \geq n^3$,
\begin{equation}
    \mathbb{P}\mleft[X_t^x \neq X_t^{x'}\mright] \leq e^{-\Omega(n)}.
\end{equation}
Moreover, for any $z \in \Lambda^*$ and $t \geq n^3$, we have
\begin{equation}
    \mathbf{d}_\mathrm{TV}(X_t^z, X) \leq e^{-\Omega(n)}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 9 (Overshoot bound) of arXiv:2604.23133, 'High-Precision Framework for Expected Hitting Times Analysis in the Dice-Sum Process'] Assume the setup and notation of Proposition~\ref{prop:square_cutoff}, and let $K = \sqrt{N} \in \mathbb{N}$.  
Define
\begin{align*}
L_N &:= \frac{1}{6}\sum_{j=0}^{\infty}
\Bigl((K+1+j)^2 - K^2 - 5\Bigr)\,
\Bigl(\tfrac{5}{7}-\varepsilon_N\Bigr)^j
\Bigl(\tfrac{2}{7}-\varepsilon_N\Bigr), \\[4pt]
U_N &:= \sum_{j=0}^{\infty}
\Bigl((K+1+j)^2 - K^2 - 1\Bigr)\,
\Bigl(\tfrac{5}{7}+\varepsilon_N\Bigr)^j
\Bigl(\tfrac{2}{7}+\varepsilon_N\Bigr).
\end{align*}
Then, for all $K \ge 4$ and every $s \in \{0,1,\dots,N\}$,
\begin{equation}
L_N \;<\; \mathbb{E}_s\!\bigl[T-\omega_N \,\big|\, A_N\bigr]
 \;<\; U_N.
\end{equation}

[Definition def:ap1:wp of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] A family of measures $\{\mu_t\}_{t \in [0, T]}$ is a weak solution to (equation eq:ap1:formalPDE of the paper) with drift $f$ and initial condition $\mu_0 \in \mathcal{P}(\ensuremath{\mathbb{R}}^m)$ if for all $\phi \in C^{2, 1}(\ensuremath{\mathbb{R}}^m_T) \cap C(\ensuremath{\mathbb{R}}^m \times [0, T))$ such that there exists $R \in (0, \infty)$ such that for all $t \in [0, T]$ and $x \not \in B_R$, we have $\phi_t(x) = 0$,  we have
\begin{equation*}
    \int_{\ensuremath{\mathbb{R}}^m} \phi_t(x) \mu_t(dx) = \int_{\ensuremath{\mathbb{R}}^m} \phi_0(x) \mu_0(dx) + \int_0^t \int_{\ensuremath{\mathbb{R}}^d} (\partial_s \phi_s(x) + \Delta _s\phi(x) - f_s(x) \cdot \nabla \phi_s(x) )\mu_s(dx) ds
\end{equation*}
for almost every $t \in [0, T]$. We let $\mu(dt, dx) := \mu_t(dx) dt$ denote such a weak solution.

