[Prop 60 (Key estimate for the QVF) of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Let $\phi \in C_c^\infty(\mathbb R)$. Let $\z:I\to\mathbb R$ be the specific function from Definition \ref{z}. For all $t>0$,
		\begin{align}

			\lim_{N \to \infty}\;  \Ex\bigg[ \bigg( Q_N^{\z}(t,\phi)-Q_N^{\z}(\varepsilon,\phi) -\gamma(\z)\int_\mathbb R \int_\varepsilon^t G(2s,x)^2 \phi(x)\dr x \dr s\bigg)^2 \bigg] = 0.
		\end{align}

[Prop pro:limit_thm_2.2 of arXiv:2412.03370, 'TASEP with a general initial condition and a deterministically moving wall'] Recall $\tilde{x}_n(0)=x_n^f$ and suppose $\{x_n^f, n \in \mathbb{N}\}$ fulfils Assumption~(assumpt:2.9 of the paper). Then, it holds 
	\begin{equation}
	\begin{aligned} 
	\lim_{T \to \infty} \mathbb{P}(\tilde{x}_{\alpha T}(T) > g_\alpha T - S T^{1/3})
	&= \mathbb{P} \left( \sup_{\tau \in \mathbb{R}} \{ \mathcal{A}_2(\tau) - \tau^2 - y(-\tau) \} < c_1^{-1} S \right)
	\end{aligned}  
	\end{equation}
	with $g_\alpha = 1-d^{-1}-d\alpha$ and $c_1 = (1-d^{-1})^{2/3} d^{1/3}$. 

	Suppose $\{x_n^f,n \in \mathbb{N}\}$ fulfils Assumption~(assumpt:2.7 of the paper). Then, we have $g_\alpha = 1-2\sqrt{\alpha}$. If $d = \tfrac{1}{\sqrt{\alpha}}$, then it holds
	\begin{equation}
	\begin{aligned} 
	\lim_{T \to \infty} \mathbb{P}(\tilde{x}_{\alpha T}(T) > g_\alpha T - S T^{1/3})
	&= \mathbb{P} \left( \sup_{\tau \leq 0} \{ \mathcal{A}_2(\tau) - \tau^2 - y(-\tau) \} < c_1^{-1} S \right).
	\end{aligned}   
	\end{equation}
	If $d < \tfrac{1}{\sqrt{\alpha}}$, then it holds
	\begin{equation}
	\lim_{T \to \infty} \mathbb{P}(\tilde{x}_{\alpha T}(T) > g_\alpha T - S T^{1/3}) = F_{\textup{GUE}}(c_1^{-1} S).    
	\end{equation}
	In both cases, we have $c_1 = (1-\sqrt{\alpha})^{2/3} \alpha^{-1/6}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 23 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Let $\gamma = 1/16$. For every $R>0$, there is a constant $C>0$ such that
\begin{align}
    \sup_{t\leq R,\ |q|_{L^1}\leq R,\ x\in[0,3]^{\N^4}}\Ll|\tilde F^x_N(t,q) - \bar F^x_{N+1}(t,q)\Rr|\leq CN^{-\gamma},\quad\forall N\in\N.
\end{align}

