[Corollary 10 of arXiv:2608.27143, 'An approximate zero bias transformation for random sums: Applications to sampling with out'] Let $n_1, n_2, n_3\in \mathbb{N}$ be such that $n_1< n_2< n_3$. Let $X_1,X_2,\ldots$ be mean zero random variables with finite variances.
Suppose that
$X_1,\ldots,X_{n_1}$, $X_{n_1+1},\ldots X_{n_2}$, $X_{n_2+1},\ldots X_{n_3}$    and  $X_{n_3+1}, X_{n_3+2}, \ldots $ 
form four independent groups of i.i.d.\ random variables, where the distributions may differ among the four groups. Let $W=\sum_{i=1}^N X_i$, where $N$ is a Poisson random variable  with parameter $\lambda$, independent of $\{X_i\}_{i=1}^\infty$, and let
 $\sigma^2$ be defined as in \eqref{TH:AI1}. Then
			\begin{align}
				d_1\!\left(\mathcal{L}(W/\sigma), \mathcal{L}(Z) \right)
				&\le \frac{1}{\sigma^3} \sum_{i=1}^{n_{1}} 
				\left(\mathbb{E}|X_1|^3 + 2\,\mathbb{E} X_1^2 \,\mathbb{E}|X_1|\right) P^2(N \ge i) \nn\\[4pt]
				&\quad + \frac{1}{\sigma^3} \sum_{i=n_{1}+1}^{n_2} 
				\left(\mathbb{E}|X_{n_{1}+1}|^3 + 2\,\mathbb{E} X_{n_{1}+1}^2  \,\mathbb{E}|X_{n_{1}+1}|\right) P^2(N \ge i)\nn \\[4pt]
				&\quad + \frac{1}{\sigma^3} \sum_{i=n_{2}+1}^{n_3} 
				\left(\mathbb{E}|X_{n_{2}+1}|^3 + 2\,\mathbb{E} X_{n_{2}+1}^2  \,\mathbb{E}|X_{n_{2}+1}|\right) P^2(N \ge i)\nn \\[4pt]
				&\quad + \frac{1}{\sigma^3} \sum_{i=n_{3}+1}^{\infty} 
				\left(\mathbb{E}|X_{n_{3}+1}|^3 + 2\,\mathbb{E} X_{n_{3}+1}^2  \,\mathbb{E}|X_{n_{3}+1}|\right) P^2(N \ge i) \nn\\[4pt]
				&\quad + \frac{2\sqrt{2}}{\sqrt{\pi}} 
				\Bigg(1 -\sum_{i=1}^{n_1}\frac{1}{\lambda^2_1\sigma^2} \, {P}^2(N \ge i) -\sum_{i=n_1+1}^{n_2}\frac{1}{\lambda^2_2\sigma^2} \, {P}^2(N \ge i)\nn\\&\quad\quad\quad\quad  -\sum_{i=n_2+1}^{n_3}\frac{1}{\lambda^2_3\sigma^2} \, {P}^2(N \ge i)-\sum_{i=n_3+1}^{\infty}\frac{1}{\lambda^2_4\sigma^2} \, {P}^2(N \ge i)\Bigg).
			\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 (Non-degenerate support) of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $\chi$ be either real or complex random variable. Denote the law of $\chi$ by $\mu$, which is a probability measure on $\R$ or $\C$, respectively. We say that $\chi$ has non-degenerate support if the following holds:
\begin{itemize}
\item[$\bullet$]  [Real case] The support of $\mu$ contains infinitely many points.
\item[$\bullet$]   [Complex case] There is no nonzero polynomial $P(z,\overline{z})\not\equiv 0$, such that the support of $\mu$ is contained in the zero set of $P$.
\end{itemize}

[Lemma 24 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] There exists a constant $C_{15}>0$, which depends on $\delta$, $T^*$, $\|u_0\|_{H^1(\Omega)}$, $\|v_0\|_{H^1(\Omega)}$ and $\|w_0\|_{H^1(\Omega)}$, such that

\begin{align*}
&\sup_{\nu \in (0,1),\,\varepsilon \in (0,1)} \left\{ \left( \sup_{0 \le t \le T^*} \|u_{\text{{\tiny $\delta,\!\varepsilon,\!\nu$}}}(t)\|_{H^1(\Omega)} \right)^2
+\int_0^{T^*} \|u_{\text{{\tiny $\delta,\!\varepsilon,\!\nu$}}}'(t)\|_{L^2 (\Omega)}^2dt\right.\\
&\hspace*{4cm}\left.+\int_0^{T^*} \|u_{\text{{\tiny $\delta,\!\varepsilon,\!\nu$}}}(t)\|_{H^2(\Omega)}^2dt \right\} \le C_{15}.
\end{align*}

[Definition 1 of arXiv:2607.04193, 'Onsager--Machlup Functionals for Generalized Newtonian Equations of Motion with Time-Varyi'] Let $f \in L^1([a,b];\mathbb{R})$. For $\alpha > 0$, the operators
    \begin{align*}
        (I_{a^+}^\alpha f)(x) &:= \frac{1}{\Gamma(\alpha)} \int_a^x (x - y)^{\alpha-1} f(y) \, dy, \quad x \ge a, \\
        (I_{b^-}^\alpha f)(x) &:= \frac{1}{\Gamma(\alpha)} \int_x^b (y - x)^{\alpha-1} f(y) \, dy, \quad x \le b,
    \end{align*}
    are called the left-sided and right-sided Riemann--Liouville fractional integrals of order $\alpha$, respectively.

[Theorem 7 (Deterministic nonlinear reservoir kernel) of arXiv:2608.20998, 'Free-Probability Kernels for Zero-Rollout Hyperparameter Selection in Reservoir Computing'] Let $\psi\in C_b^1(\mathbb R)$. For fixed $L,t,s$ and a deterministic
bounded input sequence,
\begin{equation}
K_{\psi,n,\theta}^{(L)}(t,s)
\xrightarrow{\mathbb P}
K_{\psi,\theta}^{(L)}(t,s)
\qquad (n\to\infty).

\end{equation}
The convergence is with respect to the joint randomness of
$W_r^{(n)}$ and $W_{\rm in}^{(n)}$.

[Theorem 1 (Main theorem) of arXiv:2607.23980, 'Sharp small-deviation inequalities for sums of independent\\nonnegative random variables'] Let $n\ge1$, let $X_1,\ldots,X_n$ be independent nonnegative random variables with $\E X_i\le1$, and put $S=\sum_iX_i$. For $\delta>0$, set
\begin{equation}
 b_{n,\delta}=
 \begin{cases}
 \displaystyle \delta\left(\frac{n}{n+\delta}\right)^n,&0<\delta<1,\\[0.8em]
 \displaystyle \left(1-\frac1{n+\delta}\right)^n,&\delta\ge1.
 \end{cases}
\end{equation}
Then
\begin{equation}
 \Pp\left(S<\E S+\delta\right)\ge b_{n,\delta}.
\end{equation}
For every $n$ and every $\delta\ge1$, the bound is optimal. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma covariance identity of arXiv:2606.01683, 'Singular-value gap of nonreversible Markov processes'] For $u\ge s$ and $g,h \in L^2(\mu)$,
\begin{align*}
\mathds{E}_\mu[\overline{g(X_s)}h (X_u)]
=
\langle g,P_{u-s}h\rangle.
\end{align*}

[Dfn of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] [{The local Hausdorff topology}]
  We call $\lHausdMet{S}{\rho_{S}}$ the \textit{local Hausdorff metric (with the root $\rho_{S}$)}
  and the topology induced from the local Hausdorff metric the \textit{local Hausdorff topology}.

[Lem lall of arXiv:2608.27939, 'Entropy and domination for quasi-Hitchin representations'] For $L>0$, let $\mathcal S(L)$ be the set of closed geodesics on $X$ of length at most $L$. There exist
constants $0< \beta < 1$ and $c>0$ such that
\begin{equation}
 \liminf_{L\to\infty}
 \frac{
   \left|
     \left\{
       \gamma\in\mathcal S(L):
       N_{A,B}(\gamma)\geq\beta\,\ell_X(\gamma)
     \right\}
   \right|
 }{
   |\mathcal S(L)|
 }
 \geq c.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 of arXiv:2608.21701, 'Superdiffusivity of random walks on the three-dimensional randomly oriented Manhattan latt'] The following properties hold for the functions $L$, ${\rm LB}_m$ and ${\rm UB}_m$:
\begin{itemize}
    \item[i.] the functions $L$, ${\rm LB}_m$, and ${\rm UB}_m$ are non-increasing in the first variable, and
\begin{equation}

1\le {\rm LB}_m(x,z)\le \sqrt{L(x,z)}\le {\rm UB}_m(x,z)\le L(x,z)\quad\text{for } x>0,\ z>1;
\end{equation}
\item[ii.] for every $0<\alpha<1$,
\begin{align}

\int_\alpha^1 \frac{\rmd r}{r{\rm LB}_m(r,z)} &\le 2{\rm UB}_m(\alpha,z) + \frac{{\rm UB}_m(\alpha,z)}{z}\quad\text{and}\\

\int_\alpha^\beta \frac{\rmd r}{r{\rm UB}_m(r,z)} &\ge 2\left( {\rm LB}_{m+1}(\alpha,z) - {\rm LB}_{m+1}(\beta,z) \right)\quad \text{for every $0<\alpha<\beta\le1$};
\end{align}
\item[iii.] for every fixed $c_0>0$, there exists $C<\infty$ such that, for all $\gamma\in[c_0z^{-1},1]$, $r\in(0,1)$, $m\ge0$, and $z>1$,
\begin{align} 
{\rm LB}_m(\gamma r,z) &\le {\rm LB}_m(r,z) \left[ 1+ C\frac{(m+1)(1+\log z)}{z} \right],
\\

{\rm UB}_m(\gamma r,z) &\le {\rm UB}_m(r,z) \left[ 1+ C\frac{(m+1)(1+\log z)}{z} \right];
\end{align}
\item[iv.] for each fixed $B>1$ there exists $C_{B}<\infty$ such that,
whenever $s,t\in(0,1)$, $m\ge0$, $z>1$, and $B^{-1}s\le t\le Bs$,
\begin{equation}

C_{B}^{-1}{\rm LB}_m(s,z) \le {\rm LB}_m(t,z) \le C_{B}{\rm LB}_m(s,z);
\end{equation}
\item[v.] for every fixed $B\in(0,\infty)$, there exists $C_B<\infty$ such that, for all $r\in(0,1)$, $m\ge0$, and $z>1$,
\begin{equation}

{\rm LB}_{m+1}(Br,z) \ge {\rm LB}_{m+1}(r,z) \left[ 1- C_B\frac{m+1}{z} \right] - C_B{\rm LB}_{m+1}(1,z).
\end{equation}
\end{itemize}

