[Corollary eq:pc-opt of arXiv:2607.14087, 'Stochastic Domination of Gaussian Maxima: A Resolution of the Weak Simplex Conjecture'] \label[corollary]{cor:finite-energy}
In the preceding model, the optimal correct-decoding probability is
\begin{equation}
  P_{\mathrm c}^*(E,M)
  =p_M\!\left(\sqrt{\frac{2EM}{(M-1)N_0}}\right),
  \qquad M\geq2.
\end{equation}
Hence, for $0\leq\epsilon<1$,
\begin{equation}
  M^*(E,\epsilon)
  =\max\!\left(
    \{1\}\cup
    \left\{M\geq2:
      p_M\!\left(\sqrt{\frac{2EM}{(M-1)N_0}}\right)
      \geq1-\epsilon
    \right\}
  \right).
\end{equation}
If $0<\epsilon<1-1/M$, there is a unique $a_{M,\epsilon}>0$ satisfying
$p_M(a_{M,\epsilon})=1-\epsilon$, and the minimum energy for $M$ messages at error \(\epsilon\) is
\begin{equation}
  E^{*}(M,\epsilon)
  =\frac{N_0}{2}\frac{M-1}{M}a_{M,\epsilon}^2.
\end{equation}
For $\epsilon\geq1-1/M$, $E^{*}(M,\epsilon)$ is zero, whereas for
$\epsilon=0$ it is infinite. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2506.15159, 'Conditional central limit theorems for exponential random graphs'] Let $N=n(n-1)/2$. 
Then, conditioning on $E_n/N=\widetilde p_n$, we have,
\ben{
d_{\mathcal{W}}\left(\frac{V_n -\mu_{ V_n}}{\sigma_{ V_n}},Z\right)\leq C_\varepsilon n^{-\frac{1}{2}+\varepsilon}
}
for any $\varepsilon>0$,
where $C_\varepsilon$ is a constant depending only on $\varepsilon$ and $B$, $Z\sim N(0,1)$ is a standard normal random variable,
\begin{align}
    \mu_{V_n}&=N(n-2)\widetilde p_n^2+\frac{2N\t q_n^2\sum_{l=2}^m\beta_{ln}s_l\t p_n^{e_l}}{1-2\t q_n\sum_{l=2}^m\beta_{ln} s_l \t p_n^{e_l-1}},\quad \t q_n=1-\t p_n,  \\ \sigma_{ V_n}^2&=\frac{Nn\t p_n^2\t q_n^2}{\left(1-2\t q_n\sum_{l=2}^m\beta_{ln}s_l\t  p_n^{e_l-1}\right)^2}, 
\end{align}
and $e_l$ and $s_l$ are the numbers of edges and two stars, respectively, contained in $H_l$, $2\leq l\leq m$, in the definition of the ERGM \cref{eq:ERGM}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 30 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] Let \(f:X^{m+r}\dashrightarrow Z^m\) be an almost holomorphic fibration from a compact K\"ahler manifold onto a normal compact K\"ahler space which is not uniruled, and assume that a general fibre is biholomorphic to \(\PP^r\). Let \(\omega\) be a K\"ahler metric on \(X\) with positive scalar curvature, and let \(a:=[\omega]\cdot [L]\), where \(L\) is a line in a general fibre.  If
\begin{equation}
        \min_XS(\omega)\,a=2\pi r(r+1),
\end{equation}
then the universal cover splits holomorphically and isometrically as
\begin{equation}
        (\widetilde X,\widetilde\omega)
        \cong
        (\PP^r,a\omega_{\mathrm{FS}})\times(Y,\omega_{\mathrm{RF}}),
\end{equation}
where \(\omega_{FS}\) is the Fubini--Study metric and \(\omega_{RF}\) is Ricci-flat.

[Lemma 5 of arXiv:2607.11608, '2607.11608'] Let $s\in \R$ and $f_M$ as in \eqref{fM}. Then, 
\begin{align}	
&\int_{\R^d}|f_M|^2dx=1, \\
& \int_{\R^d} |f_M|^{p}dx \sim M^{\frac{dp}{2}-d}, \\
& \int_{\R^d} |\mathcal{L}^{\frac{s}{2}}f_M|^{2}dx\les M^{2s},

\end{align}
for any $p>0$, $M\gg 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 27 of arXiv:2609.01114, 'Unbalanced spectral Tur\'an problem for color-critical graphs with prescribed large maximu'] Let	$ V_i':=V_i\setminus (L\cup K) $. Then, for every $i\in[p]$, every $j\in[p]\setminus\{i\}$, and every $v\in V_i'$, we have
	\begin{equation*}
		d_{V_j'}(v)\geq
		\begin{cases}
			\bigl(\frac1p-16\varepsilon\bigr)D, & \text{if } p=2,\\
			\bigl(\frac1p-20\varepsilon\bigr)D, & \text{if } p\geq 3.
		\end{cases}
	\end{equation*}

[Corollary 20 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] Let $H\in\left(0,1\right)$ and $(\mathbf{x}_t)_{t\geq 0}$ be a solution to \eqref{eq:fast system simplified} in the setting \nameref{S2} with non-null $\Sigma$. Then, for almost every $\tau\ge0$, it holds that
\begin{align*}
    &\left| AC_\infty(\tau)\left[\mathbf{v}\right]
    - \left( c_1(\lambda^*) e^{-i B(\lambda)\tau}
    + c_2(\lambda^*) e^{i B(\lambda)\tau} \right)
    \right|\\
    =& \cO\left(-A(\lambda)\right) + \cO\left(\left|\left| \mathbf{e}_1^*(\lambda) - \mathbf{e}_1^*(\lambda^*) \right|\right| \right) + \cO\left(\left|\left| \mathbf{e}_2^*(\lambda) - \mathbf{e}_2^*(\lambda^*) \right|\right| \right)
\end{align*}
for any $\mathbf{v}$ in a dense subset of $\R^2$ and in the limit $\lambda\to\lambda^*$. The complex parameters $c_j(\lambda)$ are defined for any $j\in\{1,2\}$ and $\lambda\leq \lambda^*$ by
\begin{align*}
    c_j(\lambda):= \frac{ \left|\left\langle \mathbf{v}, \mathbf{e}_j(\lambda) \right\rangle\right|^2 \left|\left| \Sigma^\text{T} \mathbf{e}_j^*(\lambda) \right|\right|^2}{ \left|\left\langle \mathbf{v}, \mathbf{e}_1(\lambda) \right\rangle\right|^2 \left|\left| \Sigma^\text{T} \mathbf{e}_1^*(\lambda) \right|\right|^2 + \left|\left\langle \mathbf{v}, \mathbf{e}_2(\lambda) \right\rangle\right|^2 \left|\left| \Sigma^\text{T} \mathbf{e}_2^*(\lambda) \right|\right|^2},
\end{align*}
for $\mathbf{v}$ in the dense subset mentioned above. Moreover, we have that
\begin{align*}
    AC_\infty(\tau)\left[\mathbf{v}\right] =& c_1(\lambda^*) e^{-i B(\lambda^*)\tau}
    + c_2(\lambda^*) e^{i B(\lambda^*)\tau} + \cO\left(-A(\lambda)\right) \\
    &+ \cO\left(\left|\left| \mathbf{e}_1^*(\lambda) - \mathbf{e}_1^*(\lambda^*) \right|\right| \right) + \cO\left(\left|\left| \mathbf{e}_2^*(\lambda) - \mathbf{e}_2^*(\lambda^*) \right|\right| \right) + \cO\left( |B(\lambda)-B(\lambda^*)| \right) .
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

