body:
[Lemma 12 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] There exist $C=C_d>1$ and a stationary $\frac 1{8}$-Lipschitz random field $\rd\ge 2$ such that:
    \begin{itemize}
        \item For all $x\in\ZZ^d$ and $R\ge r_\diamond(x)$,
            \begin{gather}
                \Big(\fint_{\BB_R(x)}a_e^{d+1}\Big)^{\frac1{d+1}} \le C\expec{a^{d+1}}^{\frac1{d+1}};\quad
\Big(\fint_{\BB_R(x)}a_e^{-(d+1)}\Big)^{\frac1{d+1}}\le C\expec{a^{-(d+1)}}^{\frac1{d+1}}.
            \end{gather}
            \item   $\rd$ satisfies the following moment bound: there exists $c_0>0$ such that
            \begin{equation}
		\expec{r_\di^{c_0\gamma}}^{\frac1\gamma}\lesssim  \gamma^{\frac1{d+1}}\Gamma^{2}.
            \end{equation}
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Conj local curve GW vs M2 of arXiv:2609.02409, 'Membranes and Maps'] ((conj:GW:vertex of the paper), $n=1$) For every Calabi--Yau local curve over $\bP^1$ equipped with a Calabi--Yau $\mathsf{T}$-action, we have
    \begin{equation}

        \GWargs{Z}{\mathsf{T}}{[\bP^1]}
        =
        \hat{\mathsf{A}}_{\mathsf{T}}\Big( \overline{M}_{0}\big(Z,[\bP^1]\big) \Big) \,.
    \end{equation} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Definition 13 of arXiv:2609.01190, 'Rough differential equations on manifolds via natural bundles'] Let $m,n\in\Nsf$, let $M$ be an $m$-dimensional manifold, and let $(U,x)$ be a chart on $M$. Let $f: M\to R_n^2M$ be a rough velocity field whose representation in the induced chart $(\overline{U},\overline{x})$ on $R_n^2M$ is $(f^i_\tau)$. Let also $\delta: M\to\Rsf$ be a smooth function. A \emph{rescaling} of $f$ by $\delta$ is the rough velocity field $\widetilde{f}: M\to R_n^2M $ whose representation $(\widetilde{f}^i_\tau)$ in chart $(\overline{U},\overline{x})$ is given by 
	\begin{equation}

		\widetilde{f}^i_{\ta} = \delta f^i_{\ta}, 
			\quad 
		\widetilde{f}^i_{\tab} = \delta^2f^i_{\tab},
			\quad \mbox{and} \quad 
		\widetilde{f}^i_{\tc} = \frac{\partial \delta}{\partial x^j}f^j_{\ta}\delta f^i_{\tb} + \delta^2f^i_{\tc}
	\end{equation}
for $i\in \llbracket 1,m \rrbracket$ and $\alpha,\beta\in\llbracket 1,n \rrbracket$.

[Lemma lem:gammas of arXiv:2412.09145, 'Asymptotic expansions for normal deviations of random walks conditioned to stay positive'] The coefficients $\gamma_{q,j,\ell}$ are given by
\begin{align} 
    \gamma_{q,j,\ell}
=
    \frac{(-1)^q2^j}{2^q(2j-1)!!}
    \sum
        \prod_{i=1}^{j-q}
            (\ell+2a_i-i-1/2)
\end{align}
where the sum is taken over all subsets $(a_1, a_2, \dots, a_{j-q})$ of the set $(1,2,\dots, j)$. If $j=q$ then we consider the sum equal to $1$.

