body:
[Definition def:branching-number:growth of arXiv:2411.14111, 'Stochastic processes on preferential attachment models'] The \emph{branching number} of a tree $\Gamma$, denoted by $\rm{br}(\Gamma)$, is defined as
	\eqan{
		\rm{br}(\Gamma)=&~\inf\Big\{ \lambda>0:\liminf\limits_{\Pi\to\infty}\sum\limits_{u\in\Pi} \lambda^{-|u|}=0 \Big\}\\
		=&~\sup\Big\{ \lambda>0:\liminf\limits_{\Pi\to\infty}\sum\limits_{u\in\Pi} \lambda^{-|u|}=\infty \Big\}\nn\\
		=&~\inf\Big\{ \lambda>0:\inf\limits_{\Pi}\sum\limits_{u\in\Pi} \lambda^{-|u|} \Big\}
		~,\nn}
	whereas the \emph{growth} of $\Gamma$, denoted by $\rm{gr}(\Gamma)$, is defined as
	\eqn{
		{\rm{gr}}(\Gamma)=\inf\Big\{ \lambda>0:\liminf\limits_{n\to \infty} {M_n}\lambda^{-n}=0\Big\}=\liminf\limits_{n\to\infty}M_n^{1/n}
		~,}
	where $M_n$ is the size of the $n$-th generation in the tree $\Gamma$.

[Definition 4 of arXiv:2504.02435, 'Poisson-Voronoi percolation in higher rank'] A countable group~$\Gamma$ has the {\em FIID sparse unique infinite cluster property} if there exists a Cayley graph ${\rm Cay}(\Gamma)$ of~$\Gamma$ such that
    \begin{equation} 
    \inf \bigg\{ \int_{\omega\in \mathcal U(G)} {\rm deg}_\omega(1_{\Gamma}) \, d \mu(\omega) \colon \mu\in F_{{\rm IID}}(\Gamma,\mathcal U({\rm Cay}(\Gamma))) \bigg\} = 0,
    \end{equation}
    where $\mathcal U({\rm Cay}(\Gamma))$ is the set of subgraphs of ${\rm Cay}(\Gamma)$ with a unique infinite cluster, $F_{{\rm IID}}(\Gamma,\mathcal S(\Gamma))$ is the set of $\Gamma$-invariant probability measures on $\mathcal U({\rm Cay}(\Gamma))$ which are factors of iid~processes on $\Gamma$ and $1_\Gamma$ denotes the identity of $\Gamma$.

[Theorem existencUnicit of arXiv:2609.03909, 'Conic Pseudo-Finslerian Mechanical Systems'] Let $\mathcal{L}$ be a regular Lagrangian. 
Then a smooth curve $\gamma = (x_1, \ldots, x_n)$ is an $\mathcal{L}$-geodesic if and only if it satisfies
\begin{equation}
\frac{d^2 x_i}{dt^2} 
+ \sum_j g^{ij}(v) 
\left(
  \frac{\partial^2 \mathcal{L}}{\partial v_j \partial x_i} \frac{d x_i}{dt} 
  - \frac{\partial \mathcal{L}}{\partial x_j}
\right) = 0,
\end{equation}
where $g^{ij}(v)$ denotes the inverse matrix of 
$g_{ij}(v) = g_v^{\mathcal{L}}\!\left(\frac{\partial}{\partial x_i}, \frac{\partial}{\partial x_j}\right)$.
In particular, for each $v \in \mathcal{U}$ there exists a unique maximal $\mathcal{L}$-geodesic $\gamma_v : I_v \to M$ such that $\gamma_v'(0) = v$ and $0 \in I_v$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thmISPHyper of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] Let $ h \in L^{2}_{\mathbb{F}}(0,T; H^{1}(G')) $, $ g \in L^{2}_{\mathbb{F}}(0,T; H^{1}(G)) $ and $ R \in C^{3}(\overline{Q}) $ satisfy 
\begin{align}

    |R(t, x)| \neq 0 \quad \text { for all }(t, x) \in  [0,T] \times \overline{G}.
\end{align}
If $ z \in \mathbb{H}_{T} $ satisfies (systemHyper of the paper) and 
\begin{align*}
    & \frac{\partial z}{\partial \nu} = \frac{\partial z_{x_{1}}}{\partial \nu} = 0 \quad \text { on }(0, T) \times \partial G, ~ \text{${\mathbb{P}}$-a.s.},  \\
    & z(T) = z_{t}(T) =0  \text { in } G, ~ \text{${\mathbb{P}}$-a.s.},  \\
    &
\end{align*}
then 
\begin{align*}
    h (t, x^{\prime} )=0 & \text { for all } (t, x^{\prime} ) \in(0, T) \times G^{\prime},~ \text{${\mathbb{P}}$-a.s.}  \\
    g(t, x)=0 & \text { for all }(t, x) \in(0, T) \times G, ~ \text{${\mathbb{P}}$-a.s.} 
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor boundary-modification of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] Let $R_{L_n}$ be as earlier, i.e., $L_n \times e^{ - \beta} \sqrt{\bar \kappa N} \sqrt{L_n}$, and let $|\Delta| = s\bar \kappa N$. Assume that 
    \begin{align*}
        \mathbf{E}^\Delta[\|\mu_t^\pm - \pi^\tau\|] \le \delta \qquad \forall \mathbf{P}\in \mathcal D(R_{L_n})\,.
    \end{align*}
    Then $\mathcal A(L_n,\tilde {t}_n,\tilde \delta _n)$ holds with $\tilde \delta_n = 8\delta_n + e^{ - e^{8\beta s\bar \kappa N}}$ and $\tilde t_n = 4\beta |E(\Lambda)|  \log 2 \cdot t_n \cdot  e^{4\beta s \bar \kappa N}$. 
    Analogously, $\mathcal A(L_n,t_n,\delta_n)$ implies $\mathbf{E}^\Delta[\|\mu_{t_n}^\pm - \pi^\tau\|]\le \tilde \delta_n$, and similar statements hold if we replace $R_{L_n}$ by $Q_{L_n}$ and $\mathcal A(L_n,\tilde t_n,\tilde \delta_n)$ by $\mathcal B(L_n,\tilde t_n',\tilde \delta_n')$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] Suppose that $U,V:\ZZ^d\to\RR$ are non-negative and there exists $p>1$ such that 
    \begin{equation}
        \fint_{B} U^p\,\le\,  \fint_{2B} V^p + C \Big(\fint_{2B}U\Big)^p 
    \end{equation}
    for a constant $C$ and all balls $B$. Then there exists $\bar p>p$ depending on $C$ and $p$ such that for any $p\le q \le \bar p$,
    \begin{equation}
        \fint_{B} U^{q}\,\lesssim \,\fint_{2B} V^{q} + \Big(\fint_{2B}U\Big)^{q}. 
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition Rnsecbase of arXiv:2604.07227, 'Transition probabilities of step-reinforced random walks'] Assume that $\alpha \in [0,1]$, then the elephant polynomials $(R_n(x))_{n\geq 1}$ defined by ((defelepoly of the paper)) can be written as 
    \begin{equation}

    R_n(x) =\sum_{k=0}^{\lfloor \frac{n}{2} \rfloor} (-1)^k \lambda_{n,k}x^{n-2k}(1-x^2)^k, \quad x\in \mathbb{R},
  \end{equation}
  where $\lambda_{n,k}$ $(k=0,1,2\dots, \lfloor n/2 \rfloor)$ are non-negative numbers. Moreover, for any $n\geq 1$,
  \begin{equation}

 e^{-\frac{(1-\alpha)n}{3+\alpha}}\binom{n}{2k} \alpha^k \leq \lambda_{n,k} \leq \binom{n}{2k} \alpha^k, \quad k\in \left\{0,1,\dots, \lfloor \frac{n}{2} \rfloor\right\}.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm p:300.3 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Let $u \geq 0$.
\begin{equation}

\lim_{k \to \infty}
\limsup_{n \to \infty} \mathbb{P} \big( {\mathbf G}_n(u) \setminus 
{\mathbf W}_n^k(u) \neq \emptyset \big) = 0 \,.
\end{equation}
Morevoer,
\begin{equation}

\frac{ \big| {\mathbf W}_n(u) \setminus 
{\mathbf W}_n^k(u) \big|}{\sqrt{n}} \overset{\mathbb{P}}\longrightarrow 0 \,,
\end{equation}
as $n \to \infty$ followed by $k \to \infty$, and 
\begin{equation}

\frac{\big|{\rm W}_n^{[r_n, n-r_n]}(u)  \big|}{\sqrt{n}}
	\overset{\mathbb{P}}{\underset{n \to \infty}\longrightarrow} 0 \,.
\end{equation}
as $n \to \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 130 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] For any $x \in [0,a]$, define $A = A_x$ by
	\begin{flalign} 

		A = f_0'' (\xi_x) - \displaystyle\frac{\mathfrak{q}^{x + \xi_x - \gamma_x} (\mathfrak{q}^{x + \xi_x - \gamma_x} + 1)}{(\mathfrak{q}^{x + \xi_x - \gamma_x}-1)^3} \cdot (\mathfrak{q}^{-x}-1) (\log \mathfrak{q})^2.
	\end{flalign}

	\noindent Further denoting
	\begin{flalign}

		\Gamma_{x;1} = -\displaystyle\frac{f_x (\gamma_x)}{( f_x (\gamma_x) - 1 )^2} \cdot \log \mathfrak{q}; \qquad \Gamma_{x;2} = ( f_x (\gamma_x)-1 )^2 \cdot \displaystyle\frac{\mathfrak{q}^{3\xi_x - 3\gamma_x-x} (\log \mathfrak{q})^3}{A (1 - \mathfrak{q}^{-x})^3},
	\end{flalign}

	\noindent we have 
	\begin{flalign}

		\gamma_x'' = \Gamma_{x;1} + \Gamma_{x;2}.
	\end{flalign}

	\noindent In particular, 
	\begin{flalign}

		\Gamma_{x;2} = \gamma_x'' - \gamma_x' (1 - \gamma_x') \log \mathfrak{q}. 
	\end{flalign} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm ext metric gap of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] The space $\mathcal P_{s,1}(\Gamma)$ equipped with $\mathscr W_p$, $p\geq 1$, is a geodesic extended metric space. 
    For $\mathsf{P}_0,\mathsf{P}_1\in \mathcal P_{s,1}(\Gamma)$ and an $\mathscr W_p-$optimal $ \mathsf{Q}\in  \mathsf{Cpl}_{s,m}(\mathsf{P}_0,\mathsf{P}_1)$, the curve 
    \begin{align}
        [0,1]\ni t\mapsto \mathsf{P}_t= \mathsf{gap}^{-1}((T_t)_{\#}\iota( \mathsf{Q}))
    \end{align}
    defines a constant speed geodesic.

[Lemma lemma13 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that assumptions (A1 of the paper)-(A4 of the paper) hold and that $\mu_{\alpha}$ is spread-out such that there exists a Stone's decomposition of its associated renewal measure $e^{-\alpha x} \nu^{(\infty)}({\rm d}x)$ that satisfies (S1 of the paper). Furthermore, suppose that
\begin{align} 
\beta \coloneqq \int_{[0,\infty)} x e^{-\alpha x} \mu({\rm d}x) \in (0,\infty).
\end{align}
\noindent Let $\varphi$ be a non-negative characteristic that vanishes on the negative half-line (i.e., $\varphi(t)= 0$, for $t<0$) such that $t \in \mathbb{R} \mapsto \mathbb{E}[\varphi](t)$ is c\`adl\`ag, $\varphi(t) \in L^{1}(\Omega, \mathcal{F}, \mathbb{P})$, and 
\begin{align} 
\mathbb{E}[\varphi(t)] \leq C e^{(\alpha-\delta) t} \mathbf{1}_{[0,\infty)}(t), \quad \text{for every} \, \, t \in \mathbb{R},
\end{align}
\noindent for some $\delta \in (\varepsilon, \alpha)$ and finite constant $C > 0$, where $\varepsilon \in (\alpha/2, \alpha)$ is as in (S1 of the paper). Then, 
\begin{align} 
m_{t}^{\mathbb{E}[\varphi]} = \mathbf{1}_{[0,\infty)}(t) e^{\alpha t} \beta^{-1} \int_{0}^{\infty} \mathbb{E}[\varphi(x)] e^{-\alpha x} {\rm d} x + r(t), 
\end{align}
\noindent where $r: \mathbb{R} \rightarrow \mathbb{R}$ is a function  satisfying $|r(t)| \leq C^{\prime} e^{(\alpha-\varepsilon)t} \mathbf{1}_{[0,\infty)}(t)$  for all $t \in \mathbb{R}$ and some finite constant $C^{\prime} > 0$.

