body:
[Lemma lem:centered-cubic-label of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] Put
\begin{equation}
 S_1=\sum_{i=1}^t(\ell_i-1),\qquad
 S_2=\sum_{i=1}^t(\ell_i^2-1),\qquad
 Y_x=2x+4-S_1,\qquad L=S_2-4,
\end{equation}
and define
\begin{equation}
 P_{\boldsymbol\ell}(x)=Y_x^3+LY_x.
\end{equation}
Then
\begin{equation}
 48\sum_{0\leq j_i<\ell_i}M_{x-J}
 =R P_{\boldsymbol\ell}(x)
\end{equation}
whenever all $x-J\geq0$.  Consequently every set in
Lemma~(lem:stable-suspended-chart of the paper) satisfies the exact integer identity
\begin{equation}
 48|hA_t|=R\,G_{\boldsymbol\ell}(u,v,b,c),
\end{equation}
where
\begin{equation}
 G_{\boldsymbol\ell}(u,v,b,c)=
 P_{\boldsymbol\ell}(h)-P_{\boldsymbol\ell}(u)
 +P_{\boldsymbol\ell}(v)-P_{\boldsymbol\ell}(b)
 -P_{\boldsymbol\ell}(c)\in\mathbb Z_{>0}.
\end{equation}
Uniformly on the construction,
\begin{equation}
 |hA_t|\asymp_t Rh^3\asymp_t h^{t+3}.
\end{equation}

[Theorem 18 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] Let $H\in\left(0,1\right)$ and $(\mathbf{x}_t)_{t\geq 0}$ be a solution to \eqref{eq:fast system simplified} in the setting \nameref{S2}. For any $\tau\ge0$, it holds that
\begin{align}
    \begin{split}
    &V_\infty(\tau)\left[ \mathbf{e}_{j_1}^*(\lambda), \mathbf{e}_{j_2}^*(\lambda) \right]\\
    =& \left(-\zeta_{j_1}(\lambda)-\overline{\zeta_{j_2}(\lambda)}\right)^{-1} H \left\langle  \mathbf{e}_{j_2}^*(\lambda), Q \mathbf{e}_{j_1}^*(\lambda)\right\rangle P(\zeta_{j_1}(\lambda),\zeta_{j_2}(\lambda),H,\tau) ,
    \end{split}
\end{align}
with $\zeta_1(\lambda)= A(\lambda) + i B(\lambda)= \overline{\zeta_2(\lambda)}$ and for any $j_1,j_2\in\{1,2\}$. Under the assumption that $\Sigma$ is not null, it follows that
\begin{align}
    |V_\infty(\tau)\left[ \mathbf{v}_1, \mathbf{v}_2 \right]|\asymp& |A(\lambda)|^{-1},
\end{align}
for almost every $\tau\ge0$ and any $\mathbf{v}_1, \mathbf{v}_2 \in \R^2$ such that
\begin{equation} 
    \begin{split}
        &e^{-i B(\lambda^*)\tau} \left\langle  \mathbf{e}_{1}^*(\lambda^*), Q \mathbf{e}_{1}^*(\lambda^*)\right\rangle \overline{\left\langle \mathbf{v}_1, \mathbf{e}_{1}(\lambda^*) \right\rangle} \left\langle \mathbf{v}_2, \mathbf{e}_{1}(\lambda^*) \right\rangle\\
        &+
        e^{i B(\lambda^*)\tau} \left\langle  \mathbf{e}_{2}^*(\lambda^*), Q \mathbf{e}_{2}^*(\lambda^*)\right\rangle \overline{\left\langle \mathbf{v}_1, \mathbf{e}_{2}(\lambda^*) \right\rangle} \left\langle \mathbf{v}_2, \mathbf{e}_{2}(\lambda^*) \right\rangle \neq 0.
    \end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 15 (Uniform global $C^0$ estimate) of arXiv:2608.29736, '2608.29736'] There exists \(C>0\), independent of \(t\), such that
\begin{equation}
-C\leq u_t\leq0\qquad\text{on }M,\qquad 0<t\leq t_0.
\end{equation}

[Lemma 14 of arXiv:2607.11608, '2607.11608'] Given $N\ge M\gg 1$, define $Z_M$ by its coefficients in the eigenfunction expansion of $\L$ as follows. For $0\le n\le M$, $\widetilde{Z}_M(n,t)$ is a solution of the following differential equation:
\begin{align*}
\begin{cases} d\widetilde{Z}_M(n,t)=\nu^{-1}_n\sqrt{M}(\widetilde{Y}_N(n,t)-\widetilde{Z}_M(n,t))dt \\ {\widetilde{Z}}_{M}|_{t=0}=0,
\end{cases}
\end{align*}
where 
\begin{align*}
\widetilde{Y}_N(n,t)=\int_{\R^d}Y_N(t,x)h_n(x)dx, 
\end{align*}
and we set ${\widetilde{Z}}_{M}\equiv 0$ for $n>M$. Then, 
\begin{align}
Z_M(t,x):=\sum_{n=0}^{M}{\widetilde{Z}}_{M}(n,t)h_n(x)

\end{align}
is a centered Gaussian process in $L^{2}(\R^d)$, which satisfies $\P_{M}Z_M=Z_M$. Moreover, we have 
\begin{align}
&\E\big[\|Z_M\|^2_{L^{2}(\R^d)}\big]\sim \log M, \notag\\
&\E\bigg[2\textup{Re}\int_{\R^d}Y_N \overline{Z_M}dx-\int_{\R^d}|Z_M|^2dx\bigg]\sim \log M, \\
&\E\bigg[\Big|\!\!:\!\!\|Y_N-Z_M\|^2_{L^{2}(\R^d)}\!\!:\!\!\Big|^2 \bigg]\les M^{-1}\log M, \notag\\
&\E\bigg[\Big|\!\int_{\R^d}Y_N f_Mdx\Big|^2 \bigg]+\E\bigg[\Big|\!\int_{\R^d}Z_Mf_M dx\Big|^2 \bigg]\les M^{-\frac{3}{2}},\notag\\
& \E\bigg[\int_{0}^{1}\left\|\frac{d}{ds} Z_M(s)\right\|^2_{\mathcal{H}^1(\R^d)}ds\bigg]\les M, \notag
\end{align}
for any $N\ge M\gg 1$, where $Z_M=Z_M(1)$ and 
\begin{align*}
\!\!:\!\!\|Y_N-Z_M\|^2_{L^{2}(\R^d)}\!\!:=\|Y_N-Z_M\|^2_{L^{2}(\R^d)}-\E\big[\|Y_N-Z_M\|^2_{L^{2}(\R^d)}\big].
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:optimalGaussian of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Let $\kappa>1$ and set
\begin{equation*}
 h_*=\frac{2}{\sqrt{\kappa+1}},
 \qquad
 \gamma_*=\sqrt{\kappa+1}\,\log\frac{\sqrt\kappa+1}{\sqrt\kappa-1},
\end{equation*}
so that
\begin{equation*}
 \beta_*=e^{-\gamma_*h_*}=\left(\frac{\sqrt\kappa-1}{\sqrt\kappa+1}\right)^2,
 \qquad
 s_*=\frac{h_*^2}{2}(1+\beta_*)=\frac{4}{(\sqrt\kappa+1)^2}.
\end{equation*}
Let $U_H(x)=\frac12x^\top Hx$ on $\mathbb R^d$ with $\mathrm{Id}_d\preceq H\preceq\kappa\mathrm{Id}_d$, and write $Q=Q_{h_*,\gamma_*}^{U_H}$. Then $Q$ has a unique invariant law $\pi_H$, and $\pi_H$ is a centered Gaussian. For every initial state $z\in\mathbb R^d\times\mathbb R^d$,
\begin{equation*}
 \limsup_{n\to\infty}\lVert \delta_zQ^n-\pi_H\rVert_{\mathrm{TV}}^{1/n}
 \le\sqrt{\beta_*}=\frac{\sqrt\kappa-1}{\sqrt\kappa+1},
\end{equation*}
and for suitable $z$ the limit exists and equals $\sqrt{\beta_*}$. Moreover, there are initial states $z,\widetilde z$ with
\begin{equation*}
 \lim_{n\to\infty}\norm{\delta_zQ^n-\delta_{\widetilde z}Q^n}_{\mathrm{TV}}^{1/n}
 =\sqrt{\beta_*}.
\end{equation*}

[Defn 18 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let $\phi\in\text{\rm SCL}\,(\T^n)$. We define the function of \emph{degree of regularity} of $\phi$ as
	\begin{align*}
		R_\phi(x)=
		\begin{cases}
			\inf\{\lambda\geqslant0: |p-D\phi(x)|\leqslant\lambda\cdot d(y,x),\forall y\in\T^n, p\in D^+\phi(y)\},&x\in \reg(\phi),\\
			+\infty,&x\in\cut(\phi),
		\end{cases}
	\end{align*}
	and the sub-level set of $R_\phi$ as
	\begin{align*}
		F(\phi,\lambda)=\{x\in\T^n: R_\phi(x)\leqslant\lambda\},\qquad\lambda\geqslant0.
	\end{align*}

[Definition 9 (Free independence \cite{NS2006, mingoFreeProbabilityRandom2017}) of arXiv:2606.31528, 'Well-posedness and stationary distribution of free stochastic differential equations'] Subalgebras $\mathscr{A}_1,\dots,\mathscr{A}_m \subset \mathscr{A}$ are said to be \emph{freely independent} if for every $n\in\mathbb{N}$, every choice of indices $i_1,\dots,i_n \in \{1,\dots,m\}$ with $i_k \neq i_{k+1} \text{ for all } k,$
and every choice of operators $X_k \in \mathscr{A}_{i_k}$ satisfying $\tau(X_k)=0$ for all $k=1,\dots,n$, one has
\begin{equation*}
\tau(X_1\cdots X_n)=0.
\end{equation*}

[Prop 27 (Exact fixed-weight formula) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] For $a > 0$ and $p \in (0, 1/2]$,
\begin{align}
    \nu^{\SG}_{\max}(p,a)
    = \inf_{0 < \lambda < 1/a} \frac{1}{\lambda}\,g_p^{-1}\!\left(\frac{\lambda^2}{2(1 - a\lambda)}\right)
    = a \inf_{0 < \theta < 1} \frac{1}{\theta}\,g_p^{-1}\!\left(\frac{\theta^2}{2a^2(1-\theta)}\right).

\end{align}
Consequently,
\begin{align}
    c^{\SG}(1,a)
    = \sup_{0 < p \le 1/2} \frac{a(1-p)}{1 + \log\frac{1}{2p}}
    \inf_{0 < \theta < 1} \frac{1}{\theta}\,g_p^{-1}\!\left(\frac{\theta^2}{2a^2(1-\theta)}\right).

\end{align}

