[Proposition 2 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let $p=1$ and~\eqref{co:1}--\eqref{co:3} be satisfied. Then~\eqref{eq:SIS epidemic model} admits a unique strong solution $I$ such that $I_{0} = \xi_{0}$ a.s.~and
\begin{equation}
\E\big[I_{t}\big] \leq e^{\int_{0}^{t}\hat{b}_{k+2}(s,N(s))\,\mathrm{d}s}\E\big[\xi_{0}\big] + \int_{0}^{t}e^{\int_{s}^{t}\hat{b}_{k+2}(\tilde{s},N(\tilde{s}))\,\mathrm{d}\tilde{s}}\hat{b}_{0}(s,N(s))\,\mathrm{d}s
\end{equation}
for all $t\geq 0$. Moreover, the following two assertions hold:
\begin{enumerate}[(i)]
\item If $\hat{b}_{k+2}^{+}(\cdot,N)$ and $\hat{b}_{0}(\cdot,N)$ are integrable, then $\sup_{t\geq 0}\E[I_{t}] < \infty$. In this case, we have $\lim_{t\uparrow\infty} \E[I_{t}] = 0$ as soon as $\int_{0}^{\infty}\hat{b}_{k+2}^{-}(s,N(s))\,\mathrm{d}s = \infty$.

\item If $\xi_{0} = i_{0}$ a.s.~and~\eqref{co:4} holds, then $0 < I < N$ a.s.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:small-jumps of arXiv:2608.28004, 'Hausdorff Dimension of the Set of Extreme Points\\ of a Random Countable Stable Zonotope'] For every \(q>0\), there exists \(C_q<\infty\), depending only on \(d\),
\(\alpha\), and \(q\), such that
\begin{equation}
    \mathbb E\bigl[(1+M_Q)^N V_Q^{\,q}\bigr]
    \leq C_q\,\delta^{q}
\end{equation}
uniformly over all positive integers \(n\) and all \(Q\in\mathcal Q_n\).

[Definition 9 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Given regularisation scales $0 < \delta < \eps$, throughout this section, we define the smooth and stationary random noise assignment $\tilde{\pi}^{\eps, \delta}: \tilde{\mfL}_- \to C^\infty(\mbR^2)$
	\begin{align*}
		\tilde{\pi}^{\eps, \delta} \<b0> &= \xi_\eps, \quad \tilde{\pi}^{\eps, \delta} \<p0> = \xi_{\delta}, \quad \tilde{\pi}^{\eps, \delta} \<s(1)0> = \eps^{-1/2} \partial_x K \ast \xi_{\eps, \delta}
		\\
		\tilde{\pi}^{\eps, \delta} \<bs(2)0> &= \eps^{-1/2} \partial_x K \ast \xi_{\eps, \delta} \partial_x K \ast \xi_{\eps} - \ell(\<bs(2)0>), \\
		\tilde{\pi}^{\eps, \delta} \<ps(2)0> &= \eps^{-1/2} \partial_x K \ast \xi_{\eps, \delta} \partial_x K \ast \xi_{\delta} - \ell(\<ps(2)0>),
	\end{align*}
	where $\ell(\<bs(2)0>)$ and $\ell(\<ps(2)0>)$ are such that $\mathbb{E}[\tilde{\pi}^{\eps, \delta} \tau(0)] = 0$ for $\tau \in \{\<bs(2)0>, \<ps(2)0>\}$.

	We write $\tilde{Z}^{\eps, \delta} = (\tilde{\Pi}^{\eps, \delta}, \tilde{\Gamma}^{\eps, \delta})$ for the corresponding BPHZ model.

[Proposition 11 of arXiv:2608.21551, '\bf Sparse Separable Factor Analysis in the Complex Domain with an Application to Local Fi'] For $j=1,\ldots,d$, let $\Lambdab_j\in\CC^{p_j\times k_j}$ be a nonzero true loading matrix, and let $\widehat{\Lambdab}_j$ denote its estimate. Define the orthogonal projector onto the column space of $\widehat{\Lambdab}_j$ by
\begin{align*}
  \widehat{\Pb}_j
  &=
  \widehat{\Lambdab}_j
  \left(
    \widehat{\Lambdab}_j^\star
    \widehat{\Lambdab}_j
  \right)^+
  \widehat{\Lambdab}_j^\star,
\end{align*}
where $+$ denotes the Moore--Penrose pseudoinverse. The weighted null-space projection error is
\begin{align}
  \operatorname{err}_{\Lambdab_j}^2
  &=
  \frac{
    \left\|
      \left(
        \Ib_{p_j}-\widehat{\Pb}_j
      \right)
      \Lambdab_j
    \right\|_F^2
  }{
    \|\Lambdab_j\|_F^2
  }.

\end{align}

Let $  \Lambdab_j = \Ub_j\Deltab_j\Vb_j^\star$ be a ``compact'' singular value decomposition of $\Lambdab_j$, where
$r_j=\operatorname{rank}(\Lambdab_j)$. For $i=1,\ldots,r_j$, let $\ub_{(j)i}$ denote the $i$th column of $\Ub_j$, and let $d_{(j)i}>0$ be the corresponding singular value. Define $\omega_{(j)i}\in[0,\pi/2]$ by
\begin{align}
  \cos\left(\omega_{(j)i}\right)
  &=
  \left\|
    \widehat{\Qb}_j^\star\ub_{(j)i}
  \right\|_2,

\end{align}
where the columns of $\widehat{\Qb}_j$ form an orthonormal basis for the column space of $\widehat{\Lambdab}_j$. The
angle between $\ub_{(j)i}$ and the estimated loading space is $\omega_{(j)i}$. Then,
\begin{align}
  \operatorname{err}_{\Lambdab_j}^2
  &=
  \sum_{i=1}^{r_j}
  v_{(j)i}
  \sin^2\left(\omega_{(j)i}\right),
  \qquad
  v_{(j)i}
  =
  \frac{
    d_{(j)i}^2
  }{
    \displaystyle
    \sum_{\ell=1}^{r_j}d_{(j)\ell}^2
  }.

\end{align}
In particular, $\operatorname{err}_{\Lambdab_j}^2\in[0,1]$.

[Lemma 16 of arXiv:2607.13401, 'Total variation cutoff for Kac's walk on the sphere'] For every \(0\le s_0<\infty\), there are constants
\(\eta_0=\eta_0(s_0)>0\) and \(C=C(s_0)<\infty\) such that the following
holds.  Let \(\alpha,\beta\in\mb R^m\) satisfy
\[
        \sum_i\alpha_i=\sum_i\beta_i=0,
        \qquad
        \norm{\alpha}_\infty\norm{\beta}_\infty\le\eta_0 .
\]
Then, for every \(|s|\le s_0\),
\begin{equation}
        \mb E_\Pi
        \exp\left\{
        s\sum_{i=1}^m\alpha_i\beta_{\Pi(i)}
        \right\}
        \le
        \exp\left\{
        C s^2
        \frac{\norm{\alpha}_2^2\norm{\beta}_2^2}{m}
        \right\},
\end{equation}
where \(\Pi\) is a uniform random permutation of \(\{1,\ldots,m\}\).

[Corollary 28 of arXiv:2608.12291, 'When should one stop the most exciting game?\\ {\tiny Sequential Inference for win-marting'] The second spatial derivative of the value function admits the representation
    \begin{equation*}
        \partial_{xx} V_T(t,x)=\begin{cases}
            -2\frac{c(t)+\partial_tV_T(t,x)}{\sigma^2(x)} & \text{for }(t,x)\in\mathcal{C}_T\\
            g''(x)&\text{for }(t,x)\in(\mathcal{D}_T)^\circ.
        \end{cases}
    \end{equation*}

[Lemma 7 of arXiv:2512.04297, 'Mixing at the Batchelor Scale for White-In-Time Flows'] Let $f_0 \in L^2_0(\tor^2) \setminus \{0\}$. For every $(k,l)\in \Z^2 \setminus \{0\}$ we have 
    \begin{equation}
        \P\big(\widehat{f}_{k,l}(t) = 0, \forall\, t\geq 0\big) = 0.
    \end{equation}

