[Theorem 2 (Finite \(n\) enumerative convergence) of arXiv:2608.04799, '2608.04799'] Fix \(\lambda\in\mathbb R\), let \(p_n\) be given by
\eqref{eq:pn-intro}, and let \(\Xi_n\) be given by \eqref{eq:Xi-intro}.

\begin{enumerate}[label=(\roman*),leftmargin=2.2em]
\item For every fixed \(q\ge1\), the factorial moment measures satisfy
\begin{equation}
  \alpha_{\Xi_n}^{(q)}\xrightarrow{v}\alpha_\lambda^{(q)}
  \qquad\text{on }E^q.
\end{equation}
In fact, the stronger uniform local asymptotic in
Proposition~\ref{prop:local} holds.

\item There is a unique point process
\(\Xi_\lambda^{\mathrm{enum}}\) on \(E\) whose Laplace functional is
\begin{equation}
\begin{aligned}
  \mathbb E e^{-\langle f,\Xi_\lambda^{\mathrm{enum}}\rangle}
  =\sum_{q=0}^\infty\frac{(-1)^q}{q!}
  \int_{E^q}\prod_{i=1}^q(1-e^{-f(z_i)})
  \,\mathrm d\alpha_\lambda^{(q)}(\mathbf z)
\end{aligned}
\end{equation}
for every \(f\in C_c^+(E)\), and
\begin{equation}
  \Xi_n\Rightarrow\Xi_\lambda^{\mathrm{enum}}
  \qquad\text{in }M_{\mathrm p}(E)
\end{equation}
under the vague topology.
\end{enumerate}
In \eqref{eq:enum-Laplace-theorem}, the \(q=0\) term is one: by convention
\(\alpha_\lambda^{(0)}\) is unit mass on the singleton \(E^0\), and the empty
product equals one. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 7 of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] For all $p \in (0, 1/2]$,
\begin{align*}
    (1 - p)\sqrt{\frac{2\beta_p}{1 - 2p}} \le 1 + \log\frac{1}{2p},
\end{align*}
with equality if and only if $p = 1/2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theo 11 of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] Let $\{K_n : n \ge 1\} \subseteq \cK(\cX)$ and let $p \in [1, \infty)$. Assume that $\{X^n_s : s \in S_n, n \ge 1\}$ is $(\nu_n)$-$\CUI(p)$ w.r.t. $\{K_n\}$. Assume for any $n \ge 1$, there exists $D_n \in \cS_n \otimes \cS_n$ such that:
	\begin{enumerate}[\rm (a)]
		\item  $\lim_{n \to \infty} N(K_n, \ep)^{1 - (\frac{1}{p} \wedge \frac{1}{2})} \lt\|K_n\rt\| ((\nu_n \otimes \nu_n) (D_n))^{\frac{1}{p} \wedge \frac{1}{2}} = 0$ for all $\ep >0$,

		\item  $X^n_s$ and $X^n_t$ are diagonally negatively dependent for $(\nu_n \otimes \nu_n)$-a.e.\ $(s, t) \in (S_n \times S_n) \backslash D_n$.
	\end{enumerate}
	Then, we have 
	\begin{align}
		\lim_{n \to \infty} \bE \lt\| \int_{S_n} \lt(X^n_s - \bE X^n_s\rt) \nu_n(\od s) \rt\|^p = 0,
	\end{align}
	and in particular, $\int_{S_n} \lt(X^n_s - \bE X^n_s\rt) \nu_n(\od s)  \to 0$ in probability as $n \to \infty$.

