[Proposition eq:bounded_advection of arXiv:2604.23981, 'Accelerating sampling via asymptotic relaxation enhancing flows'] Let $v$ be a relaxation enhancing flow, i.e., $\dot{\mathcal{I}}=\emptyset$. Suppose that $\{v_n\}$ is a sequence of flows with finite energies that converges to $v$ weakly in $L^2(\pi)$ and that
\begin{equation}
\|v_n\cdot\nabla\phi\|_{L^2(\pi)}\le C\|\phi\|_{H^1(\pi)}
\end{equation}
Then,
\[
\lim_{n\to\infty}r(v_n)=\infty.
\]

[Thm quantitative_discrete_continuous_convergence of arXiv:2411.13964, 'Long-time analysis of a pair of on-lattice and continuous run-and-tumble particles with ja'] \begin{itemize}
  \item[(i)] There exists a coupling of the continuous process $X$ and
    a sequence of discrete processes $(Y^L)_{L \ge 2}$ with parameters
    scaling as in ($*$) such that for all $T > 0$
    \begin{align*}
      \mathbb{P}\left( \sup_{t \le T} \left| i_L(y^L(t)) - x(t) \right| \ge \epsilon \right) \le \frac{1}{\epsilon} \left( \frac{\ell}{L - 1} + 8 \sqrt{\frac{T \left((\eta T)^2 + 3 \eta T + 1 \right)\ell}{L - 1}} \right)
		\end{align*}
		where $\eta = 2\omega$ (resp. $\eta = 2\max(\alpha,
                \beta)$) for the instantaneous-tumble transition rates of the
                $\sigma^i$ (resp. the finite-tumble transition rates).
              \item[(ii)] One has
		\begin{align*}
                  \Big( (i_L(y^L(t)), (\sigma^1(t), \sigma^2(t))) \Big)_{t\ge 0} \overset{\text{\normalfont Law}}{\longrightarrow} \Big(X(t)\Big)_{t \ge 0}
		\end{align*}
                in the Skorokhod space $\mathcal D[0, +\infty)$.
              \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 (Exact orthogonal replica identities) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] Let $E$ and $H$ be real Hilbert spaces, let
$J_1,\ldots,J_N:E\to H$ be isometries with mutually orthogonal ranges,
and let $q\ge1$.  For $a\in E^{\odot q}$ define
\begin{equation}
 R_N^{(q)}a
 =\frac1{\sqrt N}\sum_{j=1}^NJ_j^{\odot q}a.

\end{equation}
Then, for $a,b\in E^{\odot q}$ and $1\le r<q$,
\begin{align}
 \ip{R_N^{(q)}a}{R_N^{(q)}b}
 &=\ip{a}{b},
 \\
 \norm{R_N^{(q)}a\otimes_rR_N^{(q)}b}
 &=\frac1{\sqrt N}\norm{a\otimes_rb},
 \\
 \norm{L_{R_N^{(q)}a,r}}_{\op}
 &=\frac1{\sqrt N}\norm{L_{a,r}}_{\op}.

\end{align}

[Thm clt:Gini of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] For $m=2$, as $n \to \infty$, we have
\begin{align*}
\frac{L_n-\,{\mathbb{E}}[L_n]}{n} \overset{d}{\longrightarrow} N_1N_2+\frac{1}{4}
\end{align*}
and
\begin{align*}
    n(G_n-\,{\mathbb{E}}[G_n]) \overset{d}{\longrightarrow} N_1N_2+\frac{1}{4}
\end{align*}
with $(N_1,N_2)$ defined in (equation N_i of the paper).\\
For $m \ge 3$, as $n \to \infty$, we have
\begin{align*}
    \frac{L_n-\,{\mathbb{E}}[L_n]}{n^{3/2}} \overset{d}{\longrightarrow} \mathcal{N}\left(0,\frac{(m-1)(m-2)(m+1)(m+2)}{180m^2}\right)
\end{align*}
and
\begin{align*}
    \sqrt{n}\left(G_n-\,{\mathbb{E}}[G_n]\right) \overset{d}{\longrightarrow} \mathcal{N}\left(0,\frac{(m-2)(m-1)(m+2)}{45(m+1)m^2}\right).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

