body:
[Lemma Palm-Lcal-ij of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For $l\neq r, k=1,2$ and for all non-negative measurable functions $f$ on $(\Omega,{\mathcal F })$,
\begin{align}
\lefteqn{ \frac{\Lambda^{(k)}_{l,r}}{4\lambda_1\lambda_2 v_1v_2} \mathbb{E}^0_{{\mathcal V }^{(k)}_{l,r}} [f ({\mathcal H })]}{\nonumber}\\
& = \int_{0}^\infty  \int_{0}^h \int_{t^*}^\infty 
\mathbb{E}_{\mathcal H }\Bigg[ f \left(\theta_{\hat{s}_k(0,h,-t',h')}({\mathcal H }^r+\delta_{(0,h)}+ {\mathcal H }^l+\delta_{(-t',h')})\right) \prod_{i=1,2}{\mathds{1}}_{{\mathcal H }^i\left(E^{\hat{s}_k(0,h,-t',h'),v_i}_{\hat{h}_k(0,h,-t',h')}\right)=0}
	\Bigg] {\rm d}t'  {\rm d}h' {\rm d}h {\nonumber}\\ 

    &\, +  \int_{0}^\infty  \int_h^\infty \int_0^{\infty}
	\mathbb{E}_{\mathcal H }\Bigg[ f \left(\theta_{\hat{s}_k(0,h,-t',h')}({\mathcal H }^r+\delta_{(0,h)}+ {\mathcal H }^l+\delta_{(-t',h')})\right) \prod_{i=1,2}{\mathds{1}}_{{\mathcal H }^i\left(E^{\hat{s}_k(0,h,-t',h'),v_i}_{\hat{h}_k(0,h,-t',h')}\right)=0}
	\Bigg] {\rm d}t'  {\rm d}h' {\rm d}h ,
{\nonumber}
\end{align}

where, $(\hat{s}_k(t,h,t',h'),\hat{h}_k(t,h,t',h'))$
are the coordinates of the $k$-th intersection of the two radial birds with heads $(t,h)$ and $(t',h')$ of type $r$ and $l$, respectively, $t^*=\frac{1}{v_1v_2}(h^2-h'^2)^{\frac{1}{2}} (v_1^2-v_2^2)^{\frac{1}{2}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:one-large-position of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] If $m\ge40$, then
\begin{equation}
  \kappa\le\floor*{\frac{3m}{2}}+1
  +\mu(\kappa)+2\mu(\floor{\kappa/2}).
\end{equation}
In particular,
\begin{equation}
  e=\kappa-1\le3m-6.
\end{equation}

[Corollary corollary_repl_lemma_2 of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] For any function $H \in C^{1,2}( {\Omega_T})$ and for every $\delta >0$, it holds that
\begin{equation} 
\lim_{\epsilon \to 0} \lim_{N\to+\infty}  \mathbb{P}_{\nu_N} \left( \sup_{0 \leq t \leq T}\Big | \int_0^t [\langle h_{-}(\eta_s), H_s\rangle - F_-(\pi^N_s \ast \iota_\epsilon(\epsilon_N)) H_s(0)] ds \Big | > \delta \right) =0,
\end{equation}
and
\begin{equation} 
\lim_{\epsilon \to 0} \lim_{N\to+\infty}  \mathbb{P}_{\nu_N} \left( \sup_{0 \leq t \leq T} \Big | \int_0^t [\langle h_{+}(\eta_s), H_s\rangle - F_+(\pi^N_s \ast \iota_\epsilon(\tau_N)) H_s(1)] ds \Big | > \delta \right) =0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 of arXiv:2512.05340, 'The rate of convergence of the critical mean-field $O(N)$ magnetization via multivariate n'] Let $V$ satisfy Assumption~\ref{assumption: assumptions on V}, let $P_t$ denote the semigroup corresponding to~\eqref{eq: overdamped langevin},
  and let $h \in \smoothlip$. For any $x, u, v, w \in \RR^{d}$ the following hold:
    \begin{align}
        \left|D P_{t}h(x)[u]\right| &\leq C_{1}\, e^{-\theta t}\, |u|,
        \\

         |D^{2} P_{t}h(x)[u, v]| &\leq S(t)\, e^{-\theta t/2}\, |u||v|,\\

        |D^{3} P_{t}h(x)[u, v, w]| &\leq Q(t)\, e^{-\theta t/4}\, |u||v||w|, 
    \end{align}
    where $S:(0,\infty)\to(0,\infty)$ and $Q:(0,\infty)\to(0,\infty)$ are given by
    \begin{equation}
      S(t):= \frac{s_{-1/2}}{\sqrt{t}} + s_0
    \end{equation}
    and
    \begin{equation}
      Q(t):= \frac{q_{-1}}{t} + \frac{q_{-1/2}}{\sqrt{t}} + q_0 + q_1 t + q_2 t^2
    \end{equation}
    where $\theta,C_1,s_{-1/2},s_0,q_{-1},q_{-1/2},q_0,q_1,q_2\in(0,\infty)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

