[Proposition 20 of arXiv:2609.02444, 'The Hasse norm principle for $A_4$-quartic extensions of global function fields'] \begin{enumerate}
  \item There exists $\lambda\in\mathbb{Z}_{>0}$ such that for all \(a,b,n_2,n \in \ZZ_{\geq 0}\) with $a+b+n_2=n$, 
    \[ |V(a,b,n_2)/{\mathbb{B}_n}| \leq \lambda.\]
   \item There exists $M\in\mathbb{Z}_{>0}$ such that for all \(a,b,n_2, n \in \ZZ_{\geq 0}\) with \(a,b,n_2 \geq M\) and $a+b+n_2=n$,
    \[ |V(a,b,n_2)/{\mathbb{B}_n}| = \begin{cases} 1 & \text{ if } a \equiv b \pmod 3 \\
    0 &\text{ otherwise.}
  \end{cases}\]
  \end{enumerate}

[Defn def:stochastic-airy-op of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] We define \textit{Ornstein--Uhlenbeck space-time white noise} as a one parameter family of random continuous functions of time into space distributions $\xi_{a}:[0,\infty)\to \mathcal{D}'((0,\infty))$, such that for any test functions $f_1,\dots,f_k \in C_c^{\infty}((0,\infty))$, $(\langle \xi_{a}(t_1),f_1 \rangle,\dots,\langle \xi_{a}(t_k), f_k \rangle)$ is a centered Gaussian process, and
    \begin{equation}
        \mathbb{E}[\langle \xi_{a}(t), f_i\rangle \langle \xi_{a}(s), f_j\rangle] = \int_{0}^{\infty} e^{-a|t-s|x} f_i(x)f_j(x) dx.
    \end{equation}

[Lemma 29 of arXiv:2606.23099, 'Path-dependent Affine Processes'] Assume that the linear growth condition \eqref{LG-condition-existence} holds and let $X = (X(t))_{t \in [0,T]}$ be a solution to \eqref{path_dependent_sde_existence}
    with $X(0)$ a $\ccF_0$-measurable random variable such that $E[\|X(0)\|^{2m}] < \infty$ for some $m \geq 1$.
    Then, for any $0 \leq s \leq t \leq T$, there exists a constant $C > 0$ depending only on $m, T, C_{LG}$ such that
    \begin{equation}
        E\left[\|X(t)-X(s)\|^{2m}\right] \leq C(1+3E[\|X(0)\|^{2m}])(t-s)^m.
    \end{equation}
    Moreover, $X$ admits a version (which we again denote by $X$) which is Hölder continuous of any order $\alpha \in [0, \frac{1}{2} - \frac{1}{2m})$.
    For each such $\alpha$, there exists a constant $c > 0$ depending only on $m, T, C_{LG}, E[\|X(0)\|^{2m}]$ such that
    \begin{equation}
        E\left[\left(\sup_{0 \leq s < t \leq T} \frac{\|X(t)-X(s)\|}{|t-s|^\alpha}\right)^{2m}\right] \leq c.
    \end{equation}

