[Theorem t:proba of arXiv:2411.12003, 'Central Limit Theorem for non-stationary random products of $\SL(2, \R)$ matrices'] Let the family $\widetilde{\xi}_{a;n}$ satisfy the assumptions~((a:center of the paper))--((a:growth of the paper)). Then there exist constants $C_1,C_{2}$ and a number $n_0$ such that for every $n>n_0$
\begin{equation}
\forall a \quad C_1^2\, n \le \mathop{\rm Var}\nolimits \widetilde{\xi}_{a;n} \le C_{2}^2 \, n,
\end{equation}
and random variables
\begin{equation}
\frac{\widetilde{\xi}_{0;n}}{\sqrt{\mathop{\rm Var}\nolimits \widetilde{\xi}_{0;n}}}
\end{equation}
converge to $\mathcal{N}(0,1)$ in distribution as $n\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 4 (Infinitesimal range evolution) of arXiv:2608.10992, '2608.10992'] At level $t$, conditionally on $X_t=x<\infty$, the update rate is
$x+1$, with update kernel
\begin{equation}

        x\longmapsto\max\{x,U_x+X_t'\},
\end{equation}
where $U_x$ is uniform on $\{0,\ldots,x\}$ and $X_t'$ is independent of $U_x$ with the law of $X_t$. Null changes are allowed. The process is increasing and is sent to $\infty$ when its graphical range becomes infinite.

[Lemma 3 of arXiv:2605.27742, 'Multidimensional Stein's method for asymptotic independence with invariant measures of dif'] Define, for all $x \in (l, u)$,
	\begin{equation}
		S(x) := \frac{8 \left( \int_{l}^x F(w)\,\mathrm{d}w \right)
			\left( \int_{x}^{u} (1 - F(w))\,\mathrm{d}w \right)}{a(x)^2\,p(x)}.
	\end{equation}
	Then $S$ is bounded on $(l, u)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition eq:FO-derivative of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[proposition]{prop:integrand-influence}
Let
\[
 F_O(J)=e^{\Psi_O(J)}.
\]
For each \(1\le r\le m+1\),
\begin{equation}
 \left\lvert\partial_I^rF_O(J)\right\rvert\le C_rq_N^rF_O(J),
\end{equation}
uniformly over \(O\in\mathcal O_{N,L}\), \(I\in[N]^p\), and \(J\in\mathbb R^{N^p}\).  The same estimate holds for
\begin{equation}
 F(J):=\mathcal Z_{N,L}^J(V,\varepsilon,f).
\end{equation}

[Lemma 29 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $J\subseteq [n]$, $f:\cube^n\to \Rbb$, $p\in [1,2]$ and $q\in [1,2)$,
\begin{equation*}
    \left\|f\right\|_{\Leb^\infty}^{2-p} \left\|\Dop_J f\right\|_{\Leb^p}^{p} \geq \Vop_J(f) \left[1+\frac{q}{2|J|(2-q)} \ln^{+}\left(\frac{\Vop_J(f)}{\left\|\Dop_J f\right\|_{\Leb^q}^{2}}\right)\right]^{|J|}.
\end{equation*}

