[Lemma lem:rank-one-trace of arXiv:2608.18293, 'Critical tensor covariance at the Marchenko--Pastur threshold'] For every $\alpha$ and $z=E+i\eta\in\mathbb{C}_+$,
\begin{equation}
  |m_n(z)-m_n^{(\alpha)}(z)|
  \le\frac{\pi}{p\eta}.

\end{equation}

[Lemma uux u M of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $d\ge1$, $s>\frac{d}{2}+1$. Then there exists a constant $\mathscr{c}=\mathscr{c}_{s,d}>0$ such that
		\begin{equation*}
			\left\langle[(v\cdot\nabla)v],v\right\rangle _{H^s}\leq \mathscr{c}\|v\|_{W^{1,\infty}}\|v\|^2_{H^s},\qquad v\in H^{s+1},\ s>\frac{d}{2}+1.
		\end{equation*}

