[Lemma 11 of arXiv:2605.13727, 'Stochastic evolution equations\\ driven by arbitrary cylindrical Lévy processes'] Let $U,H$ and $V$ be separable Hilbert spaces, and $L$ be a cylindrical L\'evy process in $U$. For each $C \in L_2(U,H)$ and $D \in L(H,V)$ with $\norm{D}\leq r$ for some $r>0$, the following assertions hold:
    \begin{enumerate}
        \item [{\rm (1)}] $\zeta_L(DC)\leq \max\{r,1\}\, \zeta_L(C)$;
        \item [{\rm (2)}] $\eta_L(DC)\leq d_r\left(\eta_L(C)+ \zeta_L(C)\right)$ for some constant $d_r>0$ depending only on $r$.
    \end{enumerate}

[Proposition prop:radial-flowline of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] Fix {$\kappa\in(0,4)$,}  $\alpha>\chi,\beta\in\mathbb{R}$, and suppose that $h_{\alpha\beta} = h +\alpha\arg(\cdot)+\beta\log|\cdot|$ has boundary conditions on $\partial\mathbb{D}$ as depicted in Figure~(fig:radial-gff of the paper) where $h$ is a Dirichlet GFF on $\mathbb{D}$. Let 
	\begin{equation}
	   2\pi(1-\frac{\alpha}{\chi})<\theta_2<\theta_1<\frac{2\lambda}{\chi}, \ \ \theta_1-\theta_2<2\pi(\frac{\alpha}{\chi}-1); \ \ \rho = \kappa-6+\frac{2\pi\alpha}{\lambda} . 
	\end{equation}
	Let $(\eta_1,\eta_2)$ be the flow lines of $h_{\alpha\beta}$ with angles $(\theta_1,\theta_2)$ from $-i$ to 0. Then:
	\begin{enumerate}[(i)]
	    \item For $i=1,2$, $\eta_i$ is a radial $\mathrm{SLE}_\kappa^\beta(-\frac{\theta_i\chi}{\lambda};\rho+\frac{\theta_i\chi}{\lambda})$ process;
	    \item $\eta_1$ and $\eta_2$ do not cross each other;
	    \item $\eta_1,\eta_2$ are continuous near 0;
	    \item  
	   {Conditioned on $\eta_1$, the curve $\eta_2$ is the union of independent curves in certain connected components of $\mathbb{D}\backslash\eta_1$, as follows. 
	   \begin{itemize}
	       \item If $\eta_1$ first touches itself at time $\sigma_1<\infty$, let $D_{\eta_1}$ be the component having $\eta_1(\sigma_1)$ on its boundary whose boundary contains a segment of $\partial \mathbb{D}$. Otherwise let $D_{\eta_1}$ be the component having $0$ on its boundary. 
	       Let $a_{\eta_1}$ and $b_{\eta_1}$ be the first and last points on $\partial D_{\eta_1}\cap\partial \mathbb{D}$ when one views $\partial \mathbb{D}$ as a counterclockwise curve from $(-i)^+$ to $(-i)^-$.  Then in $D_{\eta_1}$, $\eta_2$ is a chordal $\mathrm{SLE}_\kappa(\frac{(\theta_1-\theta_2)\chi}{\lambda}-2;\rho+\frac{\theta_2\chi}{\lambda},-\frac{\theta_1\chi}{\lambda})$ process from $a_{\eta_1}$ to $\eta(\sigma_1)$ with force points $a_{\eta_1}^-;a_{\eta_1}^+,b_{\eta_1}$.

	       \item In each remaining component whose boundary contains a segment of the counterclockwise boundary arc of $\partial\mathbb{D}$ from $-i$ to $a_{\eta_1}$, $\eta_2$ is a chordal $\mathrm{SLE}_\kappa(\frac{(\theta_1-\theta_2)\chi}{\lambda}-2;\rho+\frac{\theta_2\chi}{\lambda})$ process from the first to the last boundary point hit by $\eta_1$.

	       \item In each remaining component whose boundary does not contain a segment of $\partial \mathbb{D}$, $\eta_2$ is a chordal $\mathrm{SLE}_\kappa(\frac{(\theta_1-\theta_2)\chi}{\lambda}-2;\rho+\frac{(\theta_2-\theta_1)\chi}{\lambda})$ process from the first to the last boundary point hit by $\eta_1$.
	   \end{itemize}
	   Similarly, given $\eta_2$, defining $D_{\eta_2}, a_{\eta_2}, b_{\eta_2}$ as above with $\eta_1$ replaced by $\eta_2$ and counterclockwise replaced by clockwise, the curve $\eta_1$ is $\mathrm{SLE}_\kappa(-\frac{\theta_1\chi}{\lambda},\rho+\frac{\theta_2\chi}{\lambda};\frac{(\theta_1-\theta_2)\chi}{\lambda}-2)$ in  $D_{\eta_2}$, $\mathrm{SLE}_\kappa(-\frac{\theta_1\chi}{\lambda};\frac{(\theta_1-\theta_2)\chi}{\lambda}-2)$ in each other connected component of $\mathbb{D}\backslash\eta_2$ whose boundary contains a segment of the  clockwise boundary arc of $\partial\mathbb{D}$ from $(-i)^-$ to $a_{\eta_2}$, and $\mathrm{SLE}_\kappa(\rho+\frac{(\theta_2-\theta_1)\chi}{\lambda};\frac{(\theta_1-\theta_2)\chi}{\lambda}-2)$ in each remaining component whose boundary does not contain an interval of $\partial \mathbb{D}$. }
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 3 of arXiv:2606.23099, 'Path-dependent Affine Processes'] Let $X$ be a path-dependent process taking values in $S$.
    We call  $X$ \emph{affine} (up to time $T$), if there exist
    \begin{align*}
        \phi & : \{(t,T,\mu) \in [0,T]^2 \times \cU(T) : t \leq T\} \to \C,                \\
        \Psi & : \{(t,T,\mu) \in [0,T]^2 \times \cU(T) : t \leq T\} \to \ccM([0,T], \C^d),
    \end{align*}
    with $\phi(\cdot,T,0) = 0$ and $\Psi(\cdot,T,0) =0$
    such that
    \begin{enumerate}
        \item[(i)] for each fixed $\mu$, $t \mapsto \phi(t,T,\mu)$ is absolutely continuous on $[0,T]$ and the pair $(\Psi, X)$ satisfies Assumption~\ref{ass:sm-diff-Psi},
        \item[(ii)] for each fixed $(t,T)$, the mappings $\mu \mapsto \phi(t,T,\mu)$ and $\mu \mapsto \Psi(t,T,\mu)$ are continuous in the $weak^\ast$-topology, and
        \item[(iii)] the following affine transform formula holds:
              \begin{equation}
                  E[e^{\, \mu \cdot X_{[0,T]} } \mid \ccF_t] = \exp\bigl( \phi(t,T,\mu) + \Psi(t,T,\mu) \cdot X_{[0,t]} \bigr)
              \end{equation}
              for all $ 0 \leq t \leq T $ and all $\mu \in \cU(T)$.
    \end{enumerate}

[Prop F-Borel of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] The following assertions hold:
\begin{enumerate}	
\item[\rm(1)] The set $F$ is Borel measurable.
\item[\rm(2)] The process $\check{\mathbb{X}}$ with state space $F$ is a Borel right-continuous Markov process.
\end{enumerate}

[Corollary 20 of arXiv:2608.12947, 'Branch-stationary max-stable fields on rooted trees'] Let \(Z\) be an \(\alpha\)-spectral representer satisfying
(equation 2 of the paper) and (equation 17 of the paper), and put
\(\Theta=\Theta^{[\varnothing]}\). Then \(Z\) is branch-BR stationary
if and only if
\begin{equation}
  \E*{
    \mathbf 1_{\{\Theta_a>0\}}
    \Theta_a^\alpha
    H\left(\frac{B^a\Theta}{\Theta_a}\right)
  }
  =
  \E{H(\Theta)},
  \qquad
  a\in\mathcal T,\quad H\in\mathfrak H.

\end{equation}
Under these equivalent conditions
\begin{equation}
  \mathbb P\{\Theta_u=0,\ \Theta_{uv}>0\}
  =
  \mathbb P\{Z_u=0,\ Z_{uv}>0\}
  =
  0,
  \qquad u,v\in\mathcal T.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 227 of arXiv:2601.16377, '2601.16377'] If $\theta_{g,h} = \theta > 0$ for all $g,h \in [H]$, we have
\begin{equation}

\begin{split}
\mathcal{F}(z,w) & = \frac{(\sigma(z) - \sigma(w))^2 - \frac{z - w}{2}(S'(z) - S'(w))}{4\theta(z - w)^2\sigma(z)\sigma(w)} \\
& \quad + \frac{P(z,w) + \sum_{j,i = 0}^{H - 2} c_{j,i}z^{j}w^{i}}{\theta\sigma(z)\sigma(w)}.
\end{split}
\end{equation}
Here, $P(z,w)$ is the unique symmetric polynomial of degree $2H - 2$ in both its variable such that each of its monomial contains at least $z^{H - 1}$ or $w^{H - 1}$, and
\begin{equation}

\frac{(\sigma(z) - \sigma(w))^2 - \frac{z - w}{2}(S'(z) - S'(w))}{4(z - w)^2} + P(z,w) = O(z^{H - 2}w^{H - 2})
\end{equation}
as $z,w \rightarrow \infty$. The constants $c_{j,i}$ are given in terms of the inverse of the restricted period map
\begin{equation}
\forall i \in \llbracket 0,H-2\rrbracket\qquad \sum_{j = 0}^{H - 2} c_{j,i}z^{j} = \hat{\Pi}^{-1}\Bigg[\bigg(\oint_{\gamma_h} \frac{\dd\zeta}{2\ii\pi} \frac{Q_{i}(\zeta)}{\sigma(\zeta)}\bigg)_{h = 1}^{H - 1}\Bigg],
\end{equation}
where $Q_{i}(\zeta)$ are polynomials of degree at most $2H - 2$, defined by the decomposition as $w \rightarrow \infty$
\begin{equation}

\frac{S(z) + S(w) - \frac{z - w}{2}(S'(z) - S'(w))}{4(z - w)^2} = - \sum_{i = 0}^{2H - 2} Q_{i}(z)w^{i} + O\bigg(\frac{1}{w}\bigg).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] There are constants \(c,C>0\), independent of \(\eps\), such that if
\[
  \norm{\phi}_{C^{4,\alpha}_2}\le c,
  \qquad
  \norm{\psi}_{C^{4,\alpha}_2}\le c,
\]
then
\begin{align}
  \norm{Q_\eps(\phi)-Q_\eps(\psi)}_{C^{0,\alpha}_{\delta-4}}
  &\le
  C\left(
    \norm{\phi}_{C^{4,\alpha}_2}
    +\norm{\psi}_{C^{4,\alpha}_2}
  \right)
  \norm{\phi-\psi}_{C^{4,\alpha}_\delta},
  \\
  \norm{Q_\eps(\phi)}_{C^{0,\alpha}_{\delta-4}}
  &\le
  C\norm{\phi}_{C^{4,\alpha}_2}
  \norm{\phi}_{C^{4,\alpha}_\delta}.

\end{align}

[Theorem thm:ito_formulas of arXiv:2606.29622, 'Affine Structure of the Brownian Signature'] Let $(\bm{\ell}_t)_{t\in[0, T]} \in \mathcal{I}^r(X)$. Then, $(\bracket{\bm{\ell}_t}{\sigX})_{t \in [0, T]}$ is an Itô process and, for all $0 \leq s \leq t \leq T$,
    \begin{equation}
        \bracket{\bm{\ell}_t}{\sigX[t]} = \bracket{\bm{\ell}_s}{\sigX[s]}  +
        \int_s^t\bracket{\dot\bm{\ell}_u}{\sigX[u]}du
        +\sum_{{\color{NavyBlue}{\mathbf{i}}}\in \{{\color{NavyBlue}{\mathbf{0}}}, {\color{NavyBlue}{\mathbf{1}}}\}}\int_s^t\bracket{\bm{\ell}_u|_{{\color{NavyBlue}{\mathbf{i}}}}}{\sigX[u]}dX_u^i + \dfrac12\sum_{{\color{NavyBlue}{\mathbf{i}}}, {\color{NavyBlue}{\mathbf{j}}}\in \{{\color{NavyBlue}{\mathbf{0}}}, {\color{NavyBlue}{\mathbf{1}}}\}}\int_s^t\bracket{\bm{\ell}_u|_{{\color{NavyBlue}{\mathbf{ji}}}}}{\sigX[u]}d\bracket{X^i}{X^j}_u.
    \end{equation}    
    Similarly, if $(\bm{\ell}_t)_{t\in[0, T]} \in \mathcal{I}^l(X)$, then $(\bracket{\bm{\ell}_t}{\sigX[t]^{-1}})_{t \in {[0, T]}}$ is an Itô process and, for all $0 \leq s \leq t \leq T$,





\begin{equation}
        \bracket{\bm{\ell}_t}{\sigX[t]^{-1}} = \bracket{\bm{\ell}_s}{\sigX[s]^{-1}}  +
        \int_s^t\bracket{\dot\bm{\ell}_u}{\sigX[u]^{-1}}du
        -\sum_{{\color{NavyBlue}{\mathbf{i}}}\in \{{\color{NavyBlue}{\mathbf{0}}}, {\color{NavyBlue}{\mathbf{1}}}\}}\int_s^t\bracket{~_{{\color{NavyBlue}{\mathbf{i}}}}|\bm{\ell}_u}{\sigX[u]^{-1}}dX_u^i + 
        \dfrac12\sum_{{\color{NavyBlue}{\mathbf{i}}}, {\color{NavyBlue}{\mathbf{j}}}\in \{{\color{NavyBlue}{\mathbf{0}}}, {\color{NavyBlue}{\mathbf{1}}}\}}\int_s^t\bracket{~_{{\color{NavyBlue}{\mathbf{ij}}}}|\bm{\ell}_u}{\sigX[u]^{-1}}d\bracket{X^i}{X^j}_u.
    \end{equation}

[Prop 1-integrated of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] Let $-\check{L}_\mathrm{rel}$ be the generator of $(\check{R}_\alpha)_\alpha$. Then we have the following:
\begin{enumerate}
\item[\rm(1)] The linear relation  $-\check{L}_\mathrm{rel}$ is $m$-dissipative.
\item[\rm(2)] The linear relation  $-\check{L}_\mathrm{rel}$ generates  an integrated semigroup, $\check{\bf S}_t: C_0(X)\to C_0(X)$, $t\geq 0$ via the equation
\begin{equation}
\check{R}_\alpha = \alpha\int_0^\infty e^{-\alpha t} \check{\bf S}_t\,dt.

\end{equation} 
\item[\rm(3)] It holds
\begin{equation}
	\check{\bf S}_t = \int_0^t \check{\bf P}_s\,ds,\quad t\geq 0.

\end{equation}
\end{enumerate}
Here both integrals in the right hand side of 
(equation 1-integrated of the paper) and (equation integrated-smgp of the paper), respectively are
 the strong Riemann integrals.

