[Lemma lem:correlation_inductivestep of arXiv:2608.05089, 'Correlation decay in area-tilted line ensembles'] For all large enough $M$ in the above definitions, there exist constants $\lambda_0 > 1$
and $q > 0$ such that the following holds for all $\lambda \geqslant \lambda_0$.
For any independent $\lambda$-tilted line ensembles $\mathbf{X}$ and $\mathbf{Y}$, we have the following for all
$\tau \in \mathcal{T}_b$ and $\sigma \in [b]$ {almost surely}:
\begin{equation}
    \mathbb{P} \mleft[
        \mathsf{Reverse}_{\tau\sigma}(\mathbf{X},\mathbf{Y})
        \;\middle|\;
        \mathsf{Reverse}_\tau(\mathbf{X},\mathbf{Y}), \;
        \mathcal{E}^{|\tau|+2,\infty}_{I_{\tau\sigma}}(\mathbf{X}), \;
        \mathcal{E}^{|\tau|+2,\infty}_{I_{\tau\sigma}}(\mathbf{Y})
    \mright] \geqslant q.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 2 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma > 0$, $\lambda \in \mathbb{R}$. We say that a $\mathcal{S}'(\mathbb{R})$-valued 
stochastic process $(\mathcal{Z}_t)_{ 0 \leq t \leq T}$ is a stationary solution of the 
fractional Ornstein-Uhlenbeck equation with diffusivity $D>0$ (in short, 
$OU(\gamma,\lambda, D)$), 
\begin{equation} 
\dd \mathcal{Z}_t = ( \mathbb{L}^{ \gamma  } + \widehat{\mathbb{L}}_{\lambda}^{ \gamma}) \; \mathcal{Z}_t \; \dd t + \sqrt{2D \; \mathcal{P}^{\gamma} } \; \dd  \mathcal{W}_t
\end{equation}
if $(\mathcal{Z}_t)_{ 0 \leq t \leq T}$ is such that  
\begin{enumerate}
\item for all $t\in[0,T]$, 
$\mathcal{Z}_t$ is a mean zero Gaussian field whose covariance 
satisfies 
\begin{equation} 
\mathbb{E}_{P} [ \mathcal{Z}_t(H_1) \mathcal{Z}_t(H_2) ] = D \int_{\mathbb{R}}  H_1(u) \; H_2(u) \, \dd u
\end{equation}
for every $H_1, \; H_2 \in \mathcal{S}(\mathbb{R})$; 
\item
 for all $H \in \mathcal{S}(\mathbb{R})$, the processes $\mathcal{M}_t(H)$ and $\mathcal{N}_t(H)$ given by
\begin{equation}  
\mathcal{M}_t(H) := \mathcal{Z}_t(H) - \mathcal{Z}_0(H) - \mathcal{I}_t(H), \quad \mathcal{N}_t(H) := \mathcal{M}_t(H)^2  -2  D t \;    \mathcal{P}^{\gamma} H,
\end{equation}
are martingales with respect to the canonical filtration 
generated by $(\mathcal{Z}_t)_{ 0 \leq t \leq T}$, where, for $H\in\cS(\R)$, $\mathcal{I}_t(H)$ is given by
\begin{equation} 
\forall t \in [0, \; T], \quad \mathcal{I}_t(H):= \int_0^t\mathcal{Z}_s (( \mathbb{L}^{ \gamma  
} + \widehat{\mathbb{L}}_{\lambda}^{ \gamma}) H) \; \dd s.
\end{equation}




\end{enumerate}

[Lemme eq:conditionomega of arXiv:2603.21634, 'Individual-based stochastic model with unbounded growth, birth and death rates: a tightnes'] Assumption~(hyp:poidsomega of the paper) is equivalent to the combination of the following properties. First, $\omega \in \mathcal{C}^{1}(\mathbb{R}^{*}_{+})$, is positive and non-decreasing, and then
\begin{multline}
 \exists \omega_{1}>0, \forall x>0, \\
 \overline{g}(x)(1+\omega'(x)) + b(x)\left(1+\left|\omega(x_{0})+\omega(x-x_{0}) -\omega(x)\right|\right) + d(x)\omega(x) \leq \omega_{1}(1+x+\omega(x)), 
\end{multline}
and
\begin{align}
 \exists \omega_{2}>0, \forall x>0, \quad b(x)(\omega(x_{0})+\omega(x-x_{0}) -\omega(x))^{2}+ d(x)\omega^{2}(x) \leq \omega_{2} (1+x+\omega(x)).

\end{align}

[Lemma repl_lemma_ave of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] For every $H \in C([0,T])$, for any $t \in [0,T]$ and $z=\epsilon_N$, it holds
\begin{equation} 
\lim_{\epsilon\to 0}\lim_{N\to+\infty}\mathbb{E}_{\nu_N} \left[\Big | \int_0^t [\eta_{sN^2}(z) - \overrightarrow{\eta}^{\lfloor \epsilon N\rfloor}_{sN^2}(z)] H(s)ds\Big| \right] =0,
\end{equation}
where, for every $L\in\mathbb N$ and $\eta \in \Omega_N$,
\begin{equation} 
\overrightarrow{\eta}^L(z) :=\frac{1}{L\epsilon_N}\sum_{y= z+\epsilon_N}^{z+L\epsilon_N}\eta(y).
\end{equation}
The same result holds for $z = \tau_N$ by replacing the average to the right, i.e. $\overrightarrow{\eta}^{\lfloor \epsilon N\rfloor}_{sN^2}$, by an average to the left, i.e. $\overleftarrow{\eta}^{\lfloor \epsilon N\rfloor}_{sN^2}$, which is defined, for every $L\in\mathbb N$ and $\eta \in \Omega_N$, as
\begin{equation}
 \overleftarrow{\eta}^L(z) :=\frac{1}{L\epsilon_N}\sum_{y=z-L\epsilon_N}^{z-\epsilon_N}\eta(y).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:reweight_by_two of arXiv:2506.10765, 'A General Coupling for Ising Models and Beyond'] Let $G=(V,E)$ be a finite  graph. Let $A\subset V$ with $|A|$ even (could be $0$). Then, $\forall \omega\in\{0,1\}^E$,
\begin{align}
2^{\abs{\omega}} (\ell^A_x \cup \mathbb{P}_p)[\omega] \propto \left(\ell^A_{\frac{2x}{1+p}} \cup \mathbb{P}_{\frac{2p}{1+ p}}\right)[\omega].
\end{align}
   In particular, with the usual $t=(t_e)_{e\in E}$ and $J=(J_e)_{e\in E}$, it holds that
\begin{align}
       2^{\abs{\omega}} (\ell^A_t \cup \mathbb{P}_{t^2})[\omega] \propto \mathbf{P}^A_{2J}.
   \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 of arXiv:2606.31528, 'Well-posedness and stationary distribution of free stochastic differential equations'] Assume that Assumptions \ref{assumption:ass1} and \ref{assumption:ass2} hold. Then for any given $T>0$ the process $U_t$ given by \eqref{eq:converge} is a unique solution to the free SDE \eqref{eq:fSDE}, i.e., 
\begin{equation}
U_t = U_0 + \int_0^t \alpha(U_s) {\rm d}s + \int_0^t \beta(U_s) {\rm d}W_s \gamma (U_s)
\end{equation}
for $t \in [0, T].$ Moreover,
\begin{equation*}
\sup_{t \in [0, T]} \|U_t\|_2 < \infty. 
\end{equation*}

