[Corollary 4 of arXiv:2607.23401, 'Limit Theorems for the Pitman-Yor Frequency Spectrum'] We have, for   $0<\lambda\le \mu\le 1$ and  $\ell=0,1,\ldots$, the limit
  \bea
 &&
      \lim_{n\to\infty}
    \PP\big(S_n^{\lambda,\mu}(\alpha,\theta) =\ell\big|K_n(\alpha,\theta) = \lf xn^\alpha\rf\big)\cr
    &&=
  \frac{  (xc(\lambda,\mu))^\ell e^{-xc(\lambda,\mu)}}
{ \ell! f_{Y_x^{(0)}}(1)}
 \times \frac{1}{2\pi }
 \int _{-\infty}^\infty e^{-\rmi \tau}
 \EE(e^{\rmi \tau Y_x^{(0)}})
 \EE(e^{\rmi \tau \calI(x,\lambda)})
  \EE(e^{\rmi \tau \calJ(x,\mu)})
\EE(e^{\rmi \tau H_\ell(\lambda,\mu)}) \rmd \tau.
  \eea
  The  righthand side of \eqref{f25} defines a proper probability mass function (adds to 1 over $\ell\ge 0$). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary eq:coexistence-ratio of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[corollary]{cor:coexistence}
Fix \(p\ge3\), \(\sigma>1\), and let \(\mu_{p,\sigma}\) be the law from
(thm:counterexample of the paper).  For every fixed \(L,\varepsilon>0\),
\(V\in\mathcal V_{2p}\), and either \(f\in\mathcal F_{2p}\) or
\(f=\ell_\eta\) for fixed \(\eta>0\),
\begin{equation}
 \frac{\mathbb E_{\mu_{p,\sigma}}\mathcal Z_{N,L}^J(V,\varepsilon,f)}
 {\mathbb E\mathcal Z_{N,L}^G(V,\varepsilon,f)}
 \longrightarrow1.
\end{equation}
The same holds for the point-incoherent functional.  Nevertheless, for
the compact interval \(B\) supplied by (thm:counterexample of the paper),
\begin{equation}
 \liminf_{N\to\infty}\frac1N\log
 \mathbb E_{\mu_{p,\sigma}}\operatorname{Crt}_N^J(B)
 >
 \lim_{N\to\infty}\frac1N\log\mathbb E\operatorname{Crt}_N^G(B).
\end{equation}
Both conclusions, as well as the local-maximum and local-minimum
versions of (equation eq:coexistence-exact of the paper), remain valid for the standard
symmetric-coordinate model (equation eq:symmetric-coordinate-model of the paper).

[Lem 27 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 4$. There exists $C>0$ such that the following holds. For every $n\geq 1$, there exists $S\subset \Lambda_n$ containing $0$ which satisfies the following properties:
\begin{enumerate}
	\item[$(i)$] $\varphi_{\beta_c}(S)\leq C(\log n)^{\mathds{1}_{d=4}}$;
	\item[$(ii)$] one has
	\begin{equation}
		\beta_c \sum_{\substack{x\in S\cap \Lambda_{n/2}\\y\notin S\\x\sim y}}\langle \sigma_0\sigma_x\rangle_{S,\beta_c}\langle\sigma_0\sigma_y\rangle_{\beta_c}\leq C\frac{(\log n)^{\mathds{1}_{d=4}}}{n^{d-2}}.
	\end{equation} 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:RFGbound of arXiv:2604.28068, 'Mean-square Stability and Bifurcations for Dissipative SDEs'] Suppose Assumptions~(assum:FG_bounds of the paper) and (ass:dissipative of the paper) hold and let $Y$ be the solution of (equation eq:main_YSDE of the paper).
Then there exists a positive constant $K_{x^\ast}>0$, which depends on $x^\ast$, such that 
\begin{equation*}
\mathbb{E}\left[\left\|R_F(Y(t),x^\ast)\right\|^2\right]\leq K_{x^\ast} \left(1+R_{q_1+2}+\|X_0\|^{2(q_1+2)}\right),
\end{equation*}
and
\begin{equation*}
\expect{\left\|\mathrm{R_G}(Y(t),x^\ast)\right\|_{\mathbf F}^2} \leq K_{x^\ast} \left(1+R_{q_2+2}+\|X_0\|^{2(q_2+2)}\right), 
\end{equation*}
where $q_1$ and $q_2$ are the exponents in Assumption~(assum:FG_bounds of the paper) and $R_q$ is defined in Lemma (lem:dissipativemomentbound of the paper).

