[Lemma 23 of arXiv:2512.04807, 'Existence and uniqueness of the canonical Brownian motion in non-simple conformal loop ens'] Let $F_1,F_2$ be two sets such that $F_1 \cap F_2$ is a non-empty finite set. For $i=1,2$, let $(\CE_i,\CF_i)$ be a resistance form on $F_i$, and let $(\CE,\CF)$ be the resistance form on $F_1 \cup F_2$ defined by
 \begin{align*}\begin{split}
  \CF &= \{ f : f|_{F_1} \in \CF_1,\, f|_{F_2} \in \CF_2 \} ,\\
  \CE(f,f) &= \CE_1(f|_{F_1},f|_{F_1})+\CE_2(f|_{F_2},f|_{F_2}) .
 \end{split}\end{align*}
 Then the following holds. Let $A \subseteq F_1 \cup F_2$ be a finite set containing $F_1 \cap F_2$, let $A_i = A \cap F_i$ for $i=1,2$, and let $w_A, w_{A,i}$ be the weight functions associated with $\CE|_A, \CE_i|_{A_i}$, respectively.
 Then
 \[
  w_A(x,y) =
  \begin{cases}
   w_{A,1}(x,y)+w_{A,2}(x,y) ,& x,y \in F_1 \cap F_2 ,\\
   w_{A,1}(x,y) ,& x,y \in F_1 ,\, \{x,y\} \nsubseteq F_1 \cap F_2 ,\\
   w_{A,2}(x,y) ,& x,y \in F_2 ,\, \{x,y\} \nsubseteq F_1 \cap F_2 ,\\
   0 ,& \text{otherwise.}
  \end{cases}
 \]

[Lemma prop:iteration of arXiv:2411.06861, 'Quenched invariance principle for random walks in random environments admitting a cycle de'] Let $f:[0, \infty)\times [0, \infty) \to [0, \infty]$ be a non-negative function. Suppose it holds, that for all $l>k \geq 0$ and $ \sigma>\sigma' \geq 0$
         \begin{align*}
             f(l, \sigma')\leq \frac{C_{\mathrm{DG}}}{(\sigma - \sigma')^\alpha(l-k)^\beta} f(k, \sigma)^\gamma, 
         \end{align*}
         for some constants $C_{\mathrm{DG}}, \alpha, \beta >0$ and $\gamma >1$. Then, there exists a constant $K\equiv K(C, f, \sigma', \alpha, \beta, \gamma)$ such that 
         \begin{align*}
             f(l, \sigma')=0, \quad \forall l\geq K. 
         \end{align*}
         In particular, we may choose
         \begin{align}

             K = f(0, \sigma)^{\frac{\gamma-1}{\beta}}C_{\mathrm{DG}}^{\frac{1}{\beta}}2^{\frac{(\alpha+\beta)}{\gamma-1}+1}(\sigma-\sigma')^{-\frac{\alpha}{\beta}}, 
         \end{align}

